--
-- Name: accept_policy_revision(decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, bigint, text, jsonb, decodex.canonical_uuid_v4_text, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.accept_policy_revision(p_policy_id decodex.canonical_uuid_v4_text, p_project_id decodex.canonical_uuid_v4_text, p_revision bigint, p_provenance text, p_snapshot jsonb, p_accepted_by decodex.canonical_uuid_v4_text, p_supersedes_revision bigint) RETURNS TABLE(policy_id uuid, project_id uuid, revision bigint, provenance text, snapshot jsonb, accepted_by uuid, policy_created_at timestamp with time zone, accepted_at timestamp with time zone, supersedes_revision bigint, revision_accepted boolean, actual_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE canonical_policy_id pg_catalog.uuid;
DECLARE canonical_project_id pg_catalog.uuid;
DECLARE canonical_accepting_agent_id pg_catalog.uuid;
DECLARE policy_row decodex.policies%ROWTYPE;
DECLARE existing decodex.policy_revisions%ROWTYPE;
DECLARE acceptance_time pg_catalog.timestamptz;
BEGIN
	IF p_policy_id IS NULL OR p_project_id IS NULL OR p_accepted_by IS NULL THEN
		RAISE EXCEPTION 'identity ingress requires canonical UUID-v4 text'
			USING ERRCODE = '23514', CONSTRAINT = 'canonical_uuid_v4_text_ingress';
	END IF;
	canonical_policy_id := p_policy_id::pg_catalog.text::pg_catalog.uuid;
	canonical_project_id := p_project_id::pg_catalog.text::pg_catalog.uuid;
	canonical_accepting_agent_id := p_accepted_by::pg_catalog.text::pg_catalog.uuid;
	SELECT stored.* INTO policy_row
	FROM decodex.policies AS stored
	WHERE stored.policy_id = canonical_policy_id
	FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'Policy identity does not exist'
			USING ERRCODE = '23503', CONSTRAINT = 'policy_revisions_policy_project_fk';
	END IF;
	IF policy_row.project_id IS DISTINCT FROM canonical_project_id THEN
		RAISE EXCEPTION 'Policy revision cannot attach across Projects'
			USING ERRCODE = '23514', CONSTRAINT = 'policy_revisions_project_scope';
	END IF;
	SELECT stored.* INTO existing
	FROM decodex.policy_revisions AS stored
	WHERE stored.policy_id = canonical_policy_id AND stored.revision = p_revision;
	IF FOUND THEN
		IF existing.project_id = canonical_project_id
			AND existing.provenance = p_provenance
			AND existing.snapshot = p_snapshot
			AND existing.accepted_by = canonical_accepting_agent_id
			AND existing.supersedes_revision IS NOT DISTINCT FROM p_supersedes_revision
		THEN
			RETURN QUERY
			SELECT existing.policy_id, existing.project_id, existing.revision,
				existing.provenance, existing.snapshot, existing.accepted_by,
				policy_row.created_at, existing.accepted_at, existing.supersedes_revision,
				true, NULL::bigint;
			RETURN;
		END IF;
		RAISE EXCEPTION 'Policy revision identity was reused with conflicting immutable bytes'
			USING ERRCODE = '23505', CONSTRAINT = 'policy_revisions_conflicting_replay';
	END IF;
	IF p_revision IS NULL OR p_revision <= 0
		OR p_revision IS DISTINCT FROM coalesce(policy_row.current_revision, 0) + 1
		OR p_supersedes_revision IS DISTINCT FROM policy_row.current_revision
	THEN
		RETURN QUERY
		SELECT canonical_policy_id, canonical_project_id, NULL::bigint, NULL::text,
			NULL::jsonb, NULL::uuid, policy_row.created_at, NULL::timestamptz,
			NULL::bigint, false, policy_row.current_revision;
		RETURN;
	END IF;
	PERFORM 1 FROM decodex.projects AS project
	WHERE project.project_id = canonical_project_id AND project.status = 'active'
	FOR KEY SHARE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'Policy acceptance requires an active Project'
			USING ERRCODE = '23514', CONSTRAINT = 'policy_revisions_active_project';
	END IF;
	PERFORM 1 FROM decodex.agents AS accepting_agent
	WHERE accepting_agent.agent_id = canonical_accepting_agent_id
		AND accepting_agent.project_id = canonical_project_id
		AND accepting_agent.role = 'lead'
		AND accepting_agent.status = 'active'
	FOR KEY SHARE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'Policy acceptance requires the active canonical Project Lead'
			USING ERRCODE = '23514', CONSTRAINT = 'policy_revisions_accepting_authority';
	END IF;
	acceptance_time := pg_catalog.clock_timestamp();
	IF acceptance_time < policy_row.created_at THEN
		RAISE EXCEPTION 'Policy acceptance chronology is invalid'
			USING ERRCODE = '23514', CONSTRAINT = 'policy_revisions_chronology';
	END IF;
	INSERT INTO decodex.policy_revisions (
		policy_id, project_id, revision, provenance, snapshot, accepted_by,
		accepted_at, supersedes_revision
	) VALUES (
		canonical_policy_id, canonical_project_id, p_revision, p_provenance, p_snapshot,
		canonical_accepting_agent_id, acceptance_time, p_supersedes_revision
	);
	UPDATE decodex.policies AS stored
	SET current_revision = p_revision
	WHERE stored.policy_id = canonical_policy_id;
	RETURN QUERY
	SELECT stored.policy_id, stored.project_id, stored.revision, stored.provenance,
		stored.snapshot, stored.accepted_by, policy_row.created_at, stored.accepted_at,
		stored.supersedes_revision, true, NULL::bigint
	FROM decodex.policy_revisions AS stored
	WHERE stored.policy_id = canonical_policy_id AND stored.revision = p_revision;
END
$$;


--
-- Name: accept_work_item_exact(text, text, uuid, uuid, uuid, bigint, uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.accept_work_item_exact(p_protocol text, p_idempotency_key text, p_acceptance_id uuid, p_work_item_id uuid, p_project_id uuid, p_expected_revision bigint, p_actor_id uuid, p_correlation_id uuid, p_provenance text, p_criteria_provenance text, p_evidence_summary text, p_evidence_provenance text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request_value jsonb;
DECLARE replay bytea;
DECLARE item record;
DECLARE accepted_revision bigint;
BEGIN
	request_value := pg_catalog.jsonb_build_object('protocol_version',p_protocol,
		'operation','accept_work_item','acceptance_id',p_acceptance_id,
		'work_item_id',p_work_item_id,'project_id',p_project_id,
		'expected_revision',p_expected_revision,'actor_id',p_actor_id,
		'correlation_id',p_correlation_id,'criteria_provenance',p_criteria_provenance,
		'provenance',p_provenance,'evidence_summary',p_evidence_summary,
		'evidence_provenance',p_evidence_provenance);
	replay := decodex.reserve_exact_work_item_command(p_protocol,p_idempotency_key,request_value);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	IF p_acceptance_id IS NULL OR p_work_item_id IS NULL OR p_project_id IS NULL
		OR p_expected_revision IS NULL OR p_actor_id IS NULL OR p_correlation_id IS NULL
		OR p_provenance IS NULL OR p_criteria_provenance IS NULL OR p_evidence_summary IS NULL
		OR p_evidence_provenance IS NULL OR p_expected_revision <= 0
		OR p_acceptance_id::text COLLATE pg_catalog."C" !~
			'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
		OR p_work_item_id::text COLLATE pg_catalog."C" !~
			'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
		OR p_correlation_id::text COLLATE pg_catalog."C" !~
			'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_input'); END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1345,pg_catalog.hashtext(p_acceptance_id::text));
	SELECT work.*,project.status AS project_state,lead.status AS lead_state,lead.role AS lead_role
	INTO item FROM decodex.work_items work JOIN decodex.projects project USING(project_id)
	JOIN decodex.agents lead ON lead.agent_id=work.lead_agent_id
	WHERE work.work_item_id=p_work_item_id AND work.project_id=p_project_id
	FOR UPDATE OF work FOR SHARE OF project,lead;
	IF NOT FOUND THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'missing_target'); END IF;
	IF item.revision<>p_expected_revision THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'stale_revision'); END IF;
	IF item.state<>'review' THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'illegal_transition'); END IF;
	IF item.project_state<>'active' OR item.lead_state<>'active' OR item.lead_role<>'lead'
		OR p_actor_id<>item.lead_agent_id THEN
		RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_authority'); END IF;
	IF NOT decodex.is_work_item_text(p_provenance,4096)
		OR NOT decodex.is_work_item_text(p_criteria_provenance,4096)
		OR NOT decodex.is_work_item_text(p_evidence_summary,4096)
		OR NOT decodex.is_work_item_text(p_evidence_provenance,4096)
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_input'); END IF;
	IF EXISTS (SELECT 1 FROM decodex.work_item_acceptances
		WHERE acceptance_id=p_acceptance_id OR (work_item_id=p_work_item_id AND work_item_revision=p_expected_revision))
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'duplicate_acceptance'); END IF;
	INSERT INTO decodex.work_item_acceptances(acceptance_id,project_id,work_item_id,
		work_item_revision,work_item_updated_at,accepted_by,acceptance_criteria,
		validation_criteria,criteria_provenance,evidence_summary,evidence_provenance,correlation_id)
	VALUES(p_acceptance_id,p_project_id,p_work_item_id,p_expected_revision,item.updated_at,
		p_actor_id,item.acceptance_criteria,item.validation_criteria,p_criteria_provenance,
		p_evidence_summary,p_evidence_provenance,p_correlation_id)
	RETURNING work_item_revision INTO accepted_revision;
	-- Acceptance intentionally does not update WorkItem state or revision. Completion is unowned.
	RETURN decodex.complete_exact_work_item_success(p_protocol,p_idempotency_key,
		'work_item_accepted',p_work_item_id,pg_catalog.jsonb_build_object(
			'request',request_value,'acceptance_recorded',pg_catalog.jsonb_build_object(
				'acceptance_id',p_acceptance_id,'work_item_revision',accepted_revision)));
END
$_$;


--
-- Name: achieve_objective(decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, bigint, text, decodex.canonical_uuid_v4_text, bigint, text, text, decodex.canonical_uuid_v4_text, bigint, text, decodex.canonical_uuid_v4_text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.achieve_objective(p_evidence_id decodex.canonical_uuid_v4_text, p_objective_id decodex.canonical_uuid_v4_text, p_project_id decodex.canonical_uuid_v4_text, p_objective_revision bigint, p_acceptance_result text, p_accepted_by decodex.canonical_uuid_v4_text, p_accepted_at bigint, p_acceptance_provenance text, p_validation_result text, p_validated_by decodex.canonical_uuid_v4_text, p_validated_at bigint, p_validation_provenance text, p_correlation_id decodex.canonical_uuid_v4_text) RETURNS TABLE(result_code text, actual_revision bigint, changed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE canonical_evidence_id uuid;
DECLARE canonical_objective_id uuid;
DECLARE canonical_project_id uuid;
DECLARE canonical_accepted_by uuid;
DECLARE canonical_validated_by uuid;
DECLARE canonical_correlation_id uuid;
DECLARE stored decodex.objectives%ROWTYPE;
DECLARE existing decodex.objective_completion_evidence%ROWTYPE;
DECLARE record_time timestamptz;
DECLARE inserted boolean;
BEGIN
	IF p_evidence_id IS NULL OR p_objective_id IS NULL OR p_project_id IS NULL
		OR p_accepted_by IS NULL OR p_validated_by IS NULL OR p_correlation_id IS NULL THEN
		RAISE EXCEPTION 'identity ingress requires canonical UUID-v4 text'
			USING ERRCODE = '23514', CONSTRAINT = 'canonical_uuid_v4_text_ingress';
	END IF;
	canonical_evidence_id := p_evidence_id::text::uuid;
	canonical_objective_id := p_objective_id::text::uuid;
	canonical_project_id := p_project_id::text::uuid;
	canonical_accepted_by := p_accepted_by::text::uuid;
	canonical_validated_by := p_validated_by::text::uuid;
	canonical_correlation_id := p_correlation_id::text::uuid;
	SELECT current.* INTO stored FROM decodex.objectives AS current
	WHERE current.objective_id=canonical_objective_id FOR UPDATE;
	IF NOT FOUND THEN RETURN QUERY SELECT 'not_found', NULL::bigint, false; RETURN; END IF;
	SELECT evidence.* INTO existing FROM decodex.objective_completion_evidence AS evidence
	WHERE evidence.evidence_id=canonical_evidence_id;
	IF FOUND THEN
		IF existing.objective_id=canonical_objective_id AND existing.project_id=canonical_project_id
			AND existing.objective_revision=p_objective_revision
			AND existing.acceptance_result=p_acceptance_result
			AND existing.accepted_by=canonical_accepted_by
			AND existing.accepted_at=decodex.program_timestamp(p_accepted_at)
			AND existing.acceptance_provenance=p_acceptance_provenance
			AND existing.validation_result=p_validation_result
			AND existing.validated_by=canonical_validated_by
			AND existing.validated_at=decodex.program_timestamp(p_validated_at)
			AND existing.validation_provenance=p_validation_provenance
			AND existing.correlation_id=canonical_correlation_id
		THEN RETURN QUERY SELECT 'ok', stored.revision, false; RETURN; END IF;
		RETURN QUERY SELECT 'conflicting_identity', stored.revision, false; RETURN;
	END IF;
	IF stored.project_id<>canonical_project_id THEN
		RETURN QUERY SELECT 'invalid_project', stored.revision, false; RETURN;
	END IF;
	IF stored.revision IS DISTINCT FROM p_objective_revision THEN
		RETURN QUERY SELECT 'revision_conflict', stored.revision, false; RETURN;
	END IF;
	IF stored.state NOT IN ('active','blocked') THEN
		RETURN QUERY SELECT 'invalid_transition', stored.revision, false; RETURN;
	END IF;
	PERFORM 1 FROM decodex.projects AS project WHERE project.project_id=canonical_project_id
		AND project.status='active' FOR KEY SHARE;
	IF NOT FOUND THEN RETURN QUERY SELECT 'invalid_authority', stored.revision, false; RETURN; END IF;
	PERFORM 1 FROM decodex.agents AS agent WHERE agent.project_id=canonical_project_id
		AND agent.role='lead' AND agent.status='active'
		AND agent.agent_id IN (canonical_accepted_by,canonical_validated_by)
	GROUP BY agent.project_id HAVING pg_catalog.count(DISTINCT agent.agent_id)
		= CASE WHEN canonical_accepted_by=canonical_validated_by THEN 1 ELSE 2 END;
	IF NOT FOUND THEN RETURN QUERY SELECT 'invalid_authority', stored.revision, false; RETURN; END IF;
	record_time := pg_catalog.clock_timestamp();
	IF decodex.program_timestamp(p_accepted_at) IS NULL
		OR decodex.program_timestamp(p_validated_at) IS NULL
		OR decodex.program_timestamp(p_accepted_at)<stored.updated_at
		OR decodex.program_timestamp(p_accepted_at)>decodex.program_timestamp(p_validated_at)
		OR decodex.program_timestamp(p_validated_at)>record_time
	THEN RETURN QUERY SELECT 'invalid_evidence', stored.revision, false; RETURN; END IF;
	INSERT INTO decodex.objective_completion_evidence (
		evidence_id,objective_id,project_id,objective_revision,objective_updated_at,
		acceptance_result,accepted_by,
		accepted_at,acceptance_provenance,validation_result,validated_by,validated_at,
		validation_provenance,correlation_id,recorded_at
	) VALUES (
		canonical_evidence_id,canonical_objective_id,canonical_project_id,p_objective_revision,
		stored.updated_at,p_acceptance_result,canonical_accepted_by,
		decodex.program_timestamp(p_accepted_at),
		p_acceptance_provenance,p_validation_result,canonical_validated_by,
		decodex.program_timestamp(p_validated_at),p_validation_provenance,
		canonical_correlation_id,record_time
	) ON CONFLICT DO NOTHING
	RETURNING true INTO inserted;
	IF inserted IS DISTINCT FROM true THEN
		SELECT evidence.* INTO existing FROM decodex.objective_completion_evidence AS evidence
		WHERE evidence.evidence_id=canonical_evidence_id;
		IF FOUND AND existing.objective_id=canonical_objective_id
			AND existing.project_id=canonical_project_id
			AND existing.objective_revision=p_objective_revision
			AND existing.acceptance_result=p_acceptance_result
			AND existing.accepted_by=canonical_accepted_by
			AND existing.accepted_at=decodex.program_timestamp(p_accepted_at)
			AND existing.acceptance_provenance=p_acceptance_provenance
			AND existing.validation_result=p_validation_result
			AND existing.validated_by=canonical_validated_by
			AND existing.validated_at=decodex.program_timestamp(p_validated_at)
			AND existing.validation_provenance=p_validation_provenance
			AND existing.correlation_id=canonical_correlation_id
		THEN RETURN QUERY SELECT 'ok', stored.revision, false; RETURN; END IF;
		RETURN QUERY SELECT 'conflicting_identity', stored.revision, false; RETURN;
	END IF;
	UPDATE decodex.objectives SET state='achieved',revision=revision+1,
		completion_evidence_id=canonical_evidence_id,last_changed_by=canonical_validated_by,
		last_correlation_id=canonical_correlation_id,last_provenance=p_validation_provenance,
		updated_at=record_time WHERE objective_id=canonical_objective_id;
	RETURN QUERY SELECT 'ok', stored.revision+1, true;
END
$$;


--
-- Name: acknowledge_runtime_session_turn_exact(text, text, uuid, bigint, uuid, bigint, uuid, bigint, uuid, bigint, uuid, bigint, uuid, decodex.provider_attempt_terminal_outcome, uuid, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.acknowledge_runtime_session_turn_exact(p_protocol text, p_idempotency_key text, p_conversation_id uuid, p_expected_conversation_revision bigint, p_runtime_session_id uuid, p_expected_runtime_session_revision bigint, p_user_turn_id uuid, p_expected_user_turn_revision bigint, p_assistant_turn_id uuid, p_expected_assistant_turn_revision bigint, p_provider_attempt_id uuid, p_expected_provider_attempt_revision bigint, p_provider_evidence_id uuid, p_provider_outcome decodex.provider_attempt_terminal_outcome, p_provider_thread_id uuid, p_provider_turn_id text) RETURNS TABLE(response_bytes bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; claimed record;
DECLARE conversation_row decodex.conversations%ROWTYPE;
DECLARE session_row decodex.runtime_sessions%ROWTYPE;
DECLARE user_turn_row decodex.turns%ROWTYPE;
DECLARE assistant_turn_row decodex.turns%ROWTYPE;
DECLARE attempt_row decodex.provider_attempts%ROWTYPE;
DECLARE evidence_row decodex.provider_attempt_positive_evidence%ROWTYPE;
DECLARE terminal_status decodex.turn_status;
DECLARE new_session_revision bigint;
DECLARE payload jsonb; links jsonb; core jsonb; effect jsonb;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','acknowledge_runtime_session_turn',
		'protocol_version',p_protocol,
		'conversation_id',p_conversation_id,
		'expected_conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'expected_runtime_session_revision',p_expected_runtime_session_revision,
		'user_turn_id',p_user_turn_id,
		'expected_user_turn_revision',p_expected_user_turn_revision,
		'assistant_turn_id',p_assistant_turn_id,
		'expected_assistant_turn_revision',p_expected_assistant_turn_revision,
		'provider_attempt_id',p_provider_attempt_id,
		'expected_provider_attempt_revision',p_expected_provider_attempt_revision,
		'provider_evidence_id',p_provider_evidence_id,
		'provider_outcome',p_provider_outcome,
		'provider_thread_id',p_provider_thread_id,
		'provider_turn_id',p_provider_turn_id
	);
	SELECT * INTO claimed FROM decodex.claim_runtime_session_thread_command(
		p_protocol,p_idempotency_key,request
	);
	IF claimed.replayed THEN
		RETURN QUERY SELECT claimed.response_bytes,true;
		RETURN;
	END IF;
	IF p_conversation_id IS NULL OR p_runtime_session_id IS NULL
		OR p_user_turn_id IS NULL OR p_provider_attempt_id IS NULL
		OR p_provider_evidence_id IS NULL OR p_provider_outcome IS NULL
		OR p_provider_thread_id IS NULL
		OR p_expected_conversation_revision IS NULL
		OR p_expected_conversation_revision<=0
		OR p_expected_runtime_session_revision IS NULL
		OR p_expected_runtime_session_revision<=0
		OR p_expected_user_turn_revision IS NULL
		OR p_expected_user_turn_revision<=0
		OR (p_assistant_turn_id IS NULL)<>
			(p_expected_assistant_turn_revision IS NULL)
		OR p_expected_assistant_turn_revision IS NOT NULL
			AND p_expected_assistant_turn_revision<=0
		OR p_expected_provider_attempt_revision IS NULL
		OR p_expected_provider_attempt_revision<=1
		OR p_provider_turn_id IS NULL
		OR pg_catalog.octet_length(p_provider_turn_id)<1
		OR pg_catalog.octet_length(p_provider_turn_id)>256
		OR p_provider_turn_id COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
		OR decodex.has_credential_material(p_provider_turn_id)
	THEN
		response_bytes:=decodex.complete_runtime_session_thread_rejection(
			p_protocol,p_idempotency_key,
			'acknowledge_runtime_session_turn',request,'invalid_input'
		);
		replayed:=false;
		RETURN NEXT;
		RETURN;
	END IF;

	PERFORM pg_catalog.pg_advisory_xact_lock_shared(1400);
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1276,pg_catalog.hashtext(p_runtime_session_id::text)
	);
	SELECT * INTO conversation_row FROM decodex.conversations
	WHERE conversation_id=p_conversation_id FOR UPDATE;
	SELECT * INTO session_row FROM decodex.runtime_sessions
	WHERE runtime_session_id=p_runtime_session_id FOR UPDATE;
	SELECT * INTO user_turn_row FROM decodex.turns
	WHERE turn_id=p_user_turn_id FOR SHARE;
	IF p_assistant_turn_id IS NOT NULL THEN
		SELECT * INTO assistant_turn_row FROM decodex.turns
		WHERE turn_id=p_assistant_turn_id FOR SHARE;
	END IF;
	SELECT * INTO attempt_row FROM decodex.provider_attempts
	WHERE attempt_id=p_provider_attempt_id FOR SHARE;
	SELECT * INTO evidence_row FROM decodex.provider_attempt_positive_evidence
	WHERE evidence_id=p_provider_evidence_id FOR SHARE;
	terminal_status:=CASE attempt_row.state
		WHEN 'succeeded' THEN 'completed'::decodex.turn_status
		WHEN 'failed_definitive' THEN 'failed'::decodex.turn_status
		ELSE NULL
	END;

	IF conversation_row.conversation_id IS NULL
		OR conversation_row.status<>'open'
		OR conversation_row.revision<>p_expected_conversation_revision
		OR session_row.runtime_session_id IS NULL
		OR session_row.conversation_id<>p_conversation_id
		OR session_row.state<>'active'
		OR session_row.revision<>p_expected_runtime_session_revision
		OR session_row.codex_thread_id IS DISTINCT FROM p_provider_thread_id
		OR session_row.thread_start_request_id IS NULL
		OR session_row.thread_start_request_sha256 IS NULL
		OR session_row.thread_start_response_id IS NULL
		OR session_row.thread_start_response_sha256 IS NULL
		OR session_row.last_known_turn_id IS NOT DISTINCT FROM p_provider_turn_id
		OR user_turn_row.turn_id IS NULL
		OR user_turn_row.conversation_id<>p_conversation_id
		OR user_turn_row.runtime_session_id<>p_runtime_session_id
		OR user_turn_row.role<>'user'
		OR user_turn_row.status IS DISTINCT FROM terminal_status
		OR user_turn_row.revision<>p_expected_user_turn_revision
		OR attempt_row.attempt_id IS NULL
		OR attempt_row.consumer_kind<>'conversation_turn'
		OR attempt_row.conversation_id<>p_conversation_id
		OR attempt_row.turn_id<>p_user_turn_id
		OR attempt_row.accepted_runtime_session_id<>p_runtime_session_id
		OR attempt_row.accepted_runtime_session_revision<>
			p_expected_runtime_session_revision
		OR attempt_row.revision<>p_expected_provider_attempt_revision
		OR attempt_row.state NOT IN ('succeeded','failed_definitive')
		OR attempt_row.state::text<>p_provider_outcome::text
		OR attempt_row.terminal_evidence_id<>p_provider_evidence_id
		OR evidence_row.evidence_id IS NULL
		OR evidence_row.attempt_id<>p_provider_attempt_id
		OR evidence_row.attempt_revision<>p_expected_provider_attempt_revision-1
		OR evidence_row.request_id<>attempt_row.request_id
		OR evidence_row.selected_account_id<>attempt_row.selected_account_id
		OR evidence_row.outcome<>p_provider_outcome
		OR evidence_row.provider_thread_id IS DISTINCT FROM p_provider_thread_id::text
		OR evidence_row.provider_turn_id IS DISTINCT FROM p_provider_turn_id
		OR (
			p_assistant_turn_id IS NULL AND EXISTS (
				SELECT 1 FROM decodex.turns AS assistant
				WHERE assistant.conversation_id=p_conversation_id
					AND assistant.runtime_session_id=p_runtime_session_id
					AND assistant.sequence=user_turn_row.sequence+1
					AND assistant.role='assistant'
			)
		)
		OR (
			p_assistant_turn_id IS NOT NULL AND (
				assistant_turn_row.turn_id IS NULL
				OR assistant_turn_row.conversation_id<>p_conversation_id
				OR assistant_turn_row.runtime_session_id<>p_runtime_session_id
				OR assistant_turn_row.sequence<>user_turn_row.sequence+1
				OR assistant_turn_row.role<>'assistant'
				OR assistant_turn_row.status IS DISTINCT FROM terminal_status
				OR assistant_turn_row.revision<>
					p_expected_assistant_turn_revision
			)
		)
	THEN
		response_bytes:=decodex.complete_runtime_session_thread_rejection(
			p_protocol,p_idempotency_key,
			'acknowledge_runtime_session_turn',request,'authority_unavailable'
		);
		replayed:=false;
		RETURN NEXT;
		RETURN;
	END IF;

	UPDATE decodex.runtime_sessions SET
		last_known_turn_id=p_provider_turn_id,revision=revision+1
	WHERE runtime_session_id=p_runtime_session_id
	RETURNING revision INTO new_session_revision;

	payload:=pg_catalog.jsonb_build_object(
		'kind','runtime_session_turn_acknowledged',
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'prior_revision',p_expected_runtime_session_revision,
		'revision',new_session_revision,
		'codex_thread_id',p_provider_thread_id,
		'last_known_turn_id',p_provider_turn_id,
		'user_turn_id',p_user_turn_id,
		'user_turn_revision',p_expected_user_turn_revision,
		'assistant_turn_id',p_assistant_turn_id,
		'assistant_turn_revision',p_expected_assistant_turn_revision,
		'turn_status',terminal_status,
		'provider_attempt_id',p_provider_attempt_id,
		'provider_attempt_revision',p_expected_provider_attempt_revision,
		'provider_attempt_outcome',p_provider_outcome,
		'provider_evidence_id',p_provider_evidence_id,
		'provider_thread_id',p_provider_thread_id,
		'provider_turn_id',p_provider_turn_id
	);
	links:=decodex.append_runtime_session_thread_effect(
		p_runtime_session_id,new_session_revision,
		'runtime_session_turn_acknowledged',p_idempotency_key,payload
	);
	core:=payload||pg_catalog.jsonb_build_object(
		'operation','acknowledge_runtime_session_turn',
		'activity_sequence',links->'activity_sequence',
		'outbox_id',links->'outbox_id'
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	response_bytes:=decodex.complete_runtime_session_thread_command(
		p_protocol,p_idempotency_key,effect
	);
	replayed:=false;
	RETURN NEXT;
END
$$;


--
-- Name: acquire_hierarchy_coordinator(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.acquire_hierarchy_coordinator() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	RETURN NULL;
END;
$$;


--
-- Name: admit_initial_quick_task_turn_exact(text, text, uuid, bigint, uuid, bigint, uuid, uuid, uuid, text, text, text, jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.admit_initial_quick_task_turn_exact(p_protocol text, p_idempotency_key text, p_conversation_id uuid, p_expected_conversation_revision bigint, p_runtime_session_id uuid, p_expected_runtime_session_revision bigint, p_continuation_plan_id uuid, p_turn_id uuid, p_history_item_id uuid, p_inline_text text, p_blob_hash text, p_media_type text, p_metadata jsonb) RETURNS TABLE(response_bytes bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; claimed record; rejection_code text;
DECLARE conversation_row decodex.conversations%ROWTYPE;
DECLARE session_row decodex.runtime_sessions%ROWTYPE;
DECLARE plan_row decodex.continuation_plans%ROWTYPE;
DECLARE decision_row decodex.routing_decisions%ROWTYPE;
DECLARE turn_value jsonb; message_value jsonb; admission_value jsonb;
DECLARE activity_sequence bigint; outbox_id bigint;
DECLARE core jsonb; effect jsonb; response_value bytea;
BEGIN
	IF p_protocol IS NULL OR p_idempotency_key IS NULL
		OR pg_catalog.octet_length(p_protocol) NOT BETWEEN 1 AND 64
		OR p_protocol COLLATE pg_catalog."C" !~ '^[a-z0-9][a-z0-9._/-]{0,63}$'
		OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 256
		OR decodex.has_credential_material(p_idempotency_key)
	THEN
		RAISE EXCEPTION 'exact initial Quick Task admission identity is invalid'
			USING ERRCODE='22023';
	END IF;

	request:=pg_catalog.jsonb_build_object(
		'operation','admit_initial_quick_task_turn',
		'protocol_version',p_protocol,
		'conversation_id',p_conversation_id,
		'expected_conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'expected_runtime_session_revision',p_expected_runtime_session_revision,
		'continuation_plan_id',p_continuation_plan_id,
		'turn_id',p_turn_id,'sequence',1,'role','user',
		'possible_side_effects','unknown','turn_status','active','turn_revision',1,
		'history_item_id',p_history_item_id,'message_ordinal',0,
		'message_kind','message','message_status','completed','message_revision',1,
		'inline_text',p_inline_text,'blob_hash',p_blob_hash,
		'media_type',p_media_type,'metadata',p_metadata
	);
	INSERT INTO decodex.exact_command_receipts(
		protocol_version,idempotency_key,request_envelope,request_digest,receipt_state
	) VALUES (
		p_protocol,p_idempotency_key,request,
		public.digest(pg_catalog.convert_to(request::text,'UTF8'),'sha256'),'executing'
	) ON CONFLICT DO NOTHING;
	SELECT receipt.request_envelope,receipt.response_bytes,receipt.receipt_state
	INTO STRICT claimed
	FROM decodex.exact_command_receipts AS receipt
	WHERE receipt.protocol_version=p_protocol
		AND receipt.idempotency_key=p_idempotency_key
	FOR UPDATE;
	IF claimed.request_envelope<>request THEN
		RAISE EXCEPTION 'idempotency key reused for another initial Quick Task admission'
			USING ERRCODE='DX001';
	END IF;
	IF claimed.receipt_state<>'executing' THEN
		RETURN QUERY SELECT claimed.response_bytes,true;
		RETURN;
	END IF;

	IF p_conversation_id IS NULL OR p_expected_conversation_revision IS NULL
		OR p_expected_conversation_revision<=0 OR p_runtime_session_id IS NULL
		OR p_expected_runtime_session_revision IS DISTINCT FROM 1
		OR p_continuation_plan_id IS NULL OR p_turn_id IS NULL
		OR p_history_item_id IS NULL OR p_media_type IS NULL OR p_metadata IS NULL
		OR (p_inline_text IS NULL)=(p_blob_hash IS NULL)
		OR (p_inline_text IS NOT NULL AND (
			pg_catalog.octet_length(p_inline_text)>16384
			OR decodex.has_credential_material(p_inline_text)
		))
		OR (p_blob_hash IS NOT NULL AND
			p_blob_hash COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$')
		OR NOT decodex.is_canonical_media_type(p_media_type)
		OR NOT decodex.is_history_metadata_projection(p_metadata)
		OR decodex.has_credential_material(p_media_type)
		OR decodex.has_credential_material(p_metadata)
	THEN
		rejection_code:='invalid_input';
	END IF;

	IF rejection_code IS NULL THEN
		PERFORM pg_catalog.pg_advisory_xact_lock(1271);
		SELECT * INTO conversation_row FROM decodex.conversations
		WHERE conversation_id=p_conversation_id FOR UPDATE;
		IF NOT FOUND THEN
			rejection_code:='authority_unavailable';
		END IF;
	END IF;
	IF rejection_code IS NULL THEN
		SELECT * INTO session_row FROM decodex.runtime_sessions
		WHERE runtime_session_id=p_runtime_session_id FOR UPDATE;
		SELECT * INTO plan_row FROM decodex.continuation_plans
		WHERE plan_id=p_continuation_plan_id FOR SHARE;
		IF plan_row.plan_id IS NOT NULL THEN
			SELECT * INTO decision_row FROM decodex.routing_decisions
			WHERE decision_id=plan_row.routing_decision_id FOR SHARE;
		END IF;
		IF conversation_row.revision<>p_expected_conversation_revision
			OR conversation_row.status<>'open'
			OR session_row.runtime_session_id IS NULL
			OR session_row.conversation_id<>p_conversation_id
			OR session_row.revision<>p_expected_runtime_session_revision
			OR session_row.state<>'starting' OR session_row.codex_thread_id IS NOT NULL
			OR session_row.last_known_turn_id IS NOT NULL
			OR session_row.thread_start_request_id IS NOT NULL
			OR session_row.thread_start_request_sha256 IS NOT NULL
			OR session_row.thread_start_response_id IS NOT NULL
			OR session_row.thread_start_response_sha256 IS NOT NULL
			OR plan_row.plan_id IS NULL OR plan_row.revision<>1
			OR plan_row.kind<>'initial_thread'
			OR plan_row.consumer_kind<>'conversation_turn'
			OR plan_row.consumer_conversation_id<>p_conversation_id
			OR plan_row.conversation_id<>p_conversation_id
			OR plan_row.conversation_revision<>p_expected_conversation_revision
			OR plan_row.source_runtime_session_id<>p_runtime_session_id
			OR plan_row.source_runtime_session_revision<>
				p_expected_runtime_session_revision
			OR plan_row.turn_id<>p_turn_id OR plan_row.replay_permitted
			OR plan_row.dispatch_enabled
			OR decision_row.decision_id IS NULL
			OR decision_row.authority_shape<>'conversation_account_registry'
			OR decision_row.kind<>'selected'
			OR decision_row.consumer_kind<>'conversation_turn'
			OR decision_row.conversation_id<>p_conversation_id
			OR decision_row.conversation_revision<>p_expected_conversation_revision
			OR decision_row.turn_id<>p_turn_id
			OR (SELECT pg_catalog.count(*) FROM decodex.runtime_sessions
				WHERE conversation_id=p_conversation_id)<>1
		THEN
			rejection_code:='authority_unavailable';
		ELSIF EXISTS (
			SELECT 1 FROM decodex.turns
			WHERE conversation_id=p_conversation_id OR turn_id=p_turn_id
		) OR EXISTS (
			SELECT 1 FROM decodex.history_items
			WHERE conversation_id=p_conversation_id
				OR history_item_id=p_history_item_id
		) THEN
			rejection_code:='initial_admission_conflict';
		ELSIF p_blob_hash IS NOT NULL AND NOT EXISTS (
			SELECT 1 FROM decodex.blob_objects WHERE blob_hash=p_blob_hash
			FOR SHARE
		) THEN
			rejection_code:='message_blob_missing';
		END IF;
	END IF;

	IF rejection_code IS NOT NULL THEN
		core:=pg_catalog.jsonb_build_object(
			'operation','admit_initial_quick_task_turn','code',rejection_code
		);
		effect:=core||pg_catalog.jsonb_build_object(
			'effect_digest_source',core::text,
			'effect_digest',pg_catalog.encode(public.digest(
				pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
		);
		response_value:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
			'classification','stable_domain_rejection','effect',effect
		)::text,'UTF8');
		UPDATE decodex.exact_command_receipts SET
			receipt_state='completed_rejected',
			outcome_class='stable_domain_rejection',effect_envelope=effect,
			response_bytes=response_value,completed_at=pg_catalog.clock_timestamp()
		WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
		response_bytes:=response_value;
		replayed:=false;
		RETURN NEXT;
		RETURN;
	END IF;

	INSERT INTO decodex.turns(
		turn_id,conversation_id,runtime_session_id,sequence,role,
		possible_side_effects,status,revision
	) VALUES (
		p_turn_id,p_conversation_id,p_runtime_session_id,1,'user','unknown','active',1
	) RETURNING pg_catalog.jsonb_build_object(
		'turn_id',turn_id,'conversation_id',conversation_id,
		'runtime_session_id',runtime_session_id,'sequence',sequence,'role',role,
		'possible_side_effects',possible_side_effects,'status',status,'revision',revision
	) INTO turn_value;
	INSERT INTO decodex.history_items(
		history_item_id,conversation_id,history_position,turn_id,ordinal,kind,status,
		inline_text,blob_hash,media_type,metadata,revision
	) VALUES (
		p_history_item_id,p_conversation_id,1,p_turn_id,0,'message','completed',
		p_inline_text,p_blob_hash,p_media_type,p_metadata,1
	) RETURNING pg_catalog.jsonb_build_object(
		'history_item_id',history_item_id,'conversation_id',conversation_id,
		'history_position',history_position,'turn_id',turn_id,'ordinal',ordinal,
		'kind',kind,'status',status,'inline_text',inline_text,'blob_hash',blob_hash,
		'media_type',media_type,'metadata',metadata,'revision',revision
	) INTO message_value;

	admission_value:=pg_catalog.jsonb_build_object(
		'kind','initial_quick_task_turn_admission',
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'runtime_session_revision',p_expected_runtime_session_revision,
		'continuation_plan_id',p_continuation_plan_id,
		'routing_decision_id',decision_row.decision_id,
		'turn',turn_value,'message',message_value
	);
	INSERT INTO decodex.activity(
		aggregate_kind,aggregate_id,revision,event_kind,correlation_key,payload
	) VALUES (
		'conversation',p_conversation_id::text,p_expected_conversation_revision,
		'initial_quick_task_turn_admitted',p_idempotency_key,admission_value
	) RETURNING sequence INTO activity_sequence;
	INSERT INTO decodex.outbox(
		effect_key,aggregate_kind,aggregate_id,aggregate_revision,payload
	) VALUES (
		'activity/'||activity_sequence::text,'conversation',p_conversation_id::text,
		p_expected_conversation_revision,pg_catalog.jsonb_build_object(
			'activity_sequence',activity_sequence,
			'event_kind','initial_quick_task_turn_admitted',
			'aggregate_kind','conversation','aggregate_id',p_conversation_id,
			'revision',p_expected_conversation_revision,'payload',admission_value
		)
	) RETURNING id INTO outbox_id;
	core:=admission_value||pg_catalog.jsonb_build_object(
		'operation','admit_initial_quick_task_turn',
		'activity_sequence',activity_sequence,'outbox_id',outbox_id
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	response_value:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect
	)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET
		receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response_value,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	response_bytes:=response_value;
	replayed:=false;
	RETURN NEXT;
END
$_$;


--
-- Name: advance_account_operation_exact(uuid, decodex.account_operation_phase, decodex.account_operation_phase, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.advance_account_operation_exact(p_operation_id uuid, p_expected_phase decodex.account_operation_phase, p_target_phase decodex.account_operation_phase, p_recovery_code text) RETURNS TABLE(result_code text, account_revision bigint, phase decodex.account_operation_phase)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE operation decodex.account_operations%ROWTYPE;
DECLARE next_revision bigint;
BEGIN
	SELECT * INTO operation FROM decodex.account_operations
	WHERE operation_id=p_operation_id FOR UPDATE;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'operation_missing',0::bigint,'prepared'::decodex.account_operation_phase;
		RETURN;
	END IF;
	IF operation.phase=p_target_phase THEN
		SELECT revision INTO next_revision FROM decodex.accounts WHERE account_id=operation.account_id;
		RETURN QUERY SELECT 'replayed',next_revision,operation.phase;
		RETURN;
	END IF;
	IF operation.phase<>p_expected_phase OR NOT (
		(p_expected_phase='prepared' AND p_target_phase IN ('provider_effect_pending','store_applied','cancelled','recovery_required'))
		OR (p_expected_phase='provider_effect_pending' AND p_target_phase IN ('store_applied','cancelled','recovery_required'))
		OR (p_expected_phase='store_applied' AND p_target_phase IN ('committed','recovery_required'))
			OR (p_expected_phase='recovery_required' AND p_target_phase IN ('store_applied','cancelled'))
	) THEN
		SELECT revision INTO next_revision FROM decodex.accounts WHERE account_id=operation.account_id;
		RETURN QUERY SELECT 'stale_operation',next_revision,operation.phase;
		RETURN;
	END IF;
	IF p_target_phase='committed' THEN
		IF operation.kind='logout' THEN
			PERFORM decodex.lock_account_routing_universe_exact();
			UPDATE decodex.accounts SET enabled=false,
				credential_store_schema_version=NULL,credential_version=NULL,
				credential_fingerprint=NULL,credential_writer_operation_id=NULL,
				credential_store_observation='missing',
				credential_store_observed_at=pg_catalog.clock_timestamp(),
				tombstoned_at=pg_catalog.clock_timestamp(),revision=revision+1,
				updated_at=pg_catalog.clock_timestamp()
			WHERE account_id=operation.account_id RETURNING revision INTO next_revision;
			DELETE FROM decodex.account_routing_order WHERE account_id=operation.account_id;
			UPDATE decodex.account_routing_order SET position=position+512,
				updated_at=pg_catalog.clock_timestamp();
			WITH compact AS (
				SELECT ordering.account_id,
					pg_catalog.row_number() OVER (
						ORDER BY ordering.position,ordering.account_id
					)-1 AS position
				FROM decodex.account_routing_order AS ordering
			)
			UPDATE decodex.account_routing_order AS ordering
			SET position=compact.position,updated_at=pg_catalog.clock_timestamp()
			FROM compact WHERE compact.account_id=ordering.account_id;
			UPDATE decodex.account_routing_control SET
				mode=CASE WHEN fixed_account_id=operation.account_id THEN 'balanced' ELSE mode END,
				fixed_account_id=CASE WHEN fixed_account_id=operation.account_id THEN NULL ELSE fixed_account_id END,
				revision=revision+1,updated_at=pg_catalog.clock_timestamp()
			WHERE singleton;
			PERFORM decodex.lock_account_routing_universe_exact();
		ELSE
			UPDATE decodex.accounts SET
				credential_store_schema_version=operation.target_store_schema_version,
				credential_version=operation.target_credential_version,
				credential_fingerprint=operation.target_credential_fingerprint,
				credential_writer_operation_id=operation.target_credential_writer_operation_id,
				provider_kind=operation.provider_kind,
				provider_account_id=operation.provider_account_id,
				credential_store_observation='exact',
				credential_store_observed_at=pg_catalog.clock_timestamp(),
				revision=revision+1,updated_at=pg_catalog.clock_timestamp()
			WHERE account_id=operation.account_id RETURNING revision INTO next_revision;
		END IF;
	ELSE
		SELECT revision INTO next_revision FROM decodex.accounts WHERE account_id=operation.account_id;
	END IF;
	UPDATE decodex.account_operations SET phase=p_target_phase,recovery_code=p_recovery_code,
		updated_at=pg_catalog.clock_timestamp(),completed_at=CASE
			WHEN p_target_phase IN ('committed','cancelled') THEN pg_catalog.clock_timestamp()
			ELSE NULL END
	WHERE operation_id=p_operation_id;
	RETURN QUERY SELECT 'advanced',next_revision,p_target_phase;
END
$$;


--
-- Name: append_runtime_session_thread_effect(uuid, bigint, text, text, jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.append_runtime_session_thread_effect(p_runtime_session_id uuid, p_revision bigint, p_event_kind text, p_correlation_key text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE activity_sequence bigint; outbox_id bigint;
BEGIN
	INSERT INTO decodex.activity(
		aggregate_kind,aggregate_id,revision,event_kind,correlation_key,payload
	) VALUES (
		'runtime_session',p_runtime_session_id::text,p_revision,p_event_kind,
		p_correlation_key,p_payload
	) RETURNING sequence INTO activity_sequence;
	INSERT INTO decodex.outbox(
		effect_key,aggregate_kind,aggregate_id,aggregate_revision,payload
	) VALUES (
		'activity/'||activity_sequence::text,'runtime_session',
		p_runtime_session_id::text,p_revision,
		pg_catalog.jsonb_build_object(
			'activity_sequence',activity_sequence,'event_kind',p_event_kind,
			'aggregate_kind','runtime_session','aggregate_id',p_runtime_session_id,
			'revision',p_revision,'payload',p_payload
		)
	) RETURNING id INTO outbox_id;
	RETURN pg_catalog.jsonb_build_object(
		'activity_sequence',activity_sequence,'outbox_id',outbox_id
	);
END
$$;


--
-- Name: ascii_lower(text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.ascii_lower(value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT translate(value, 'ABCDEFGHIJKLMNOPQRSTUVWXYZ', 'abcdefghijklmnopqrstuvwxyz')
$$;


--
-- Name: assess_work_item_readiness_exact(text, text, uuid, uuid, bigint, uuid, uuid, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.assess_work_item_readiness_exact(p_protocol text, p_idempotency_key text, p_work_item_id uuid, p_project_id uuid, p_expected_revision bigint, p_actor_id uuid, p_correlation_id uuid, p_provenance text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request_value jsonb;
DECLARE replay bytea;
DECLARE item record;
DECLARE blockers jsonb;
DECLARE target_state decodex.work_item_state;
DECLARE event_kind text;
DECLARE project_state text;
DECLARE lead_state text;
DECLARE lead_role text;
BEGIN
	request_value := pg_catalog.jsonb_build_object('protocol_version',p_protocol,
		'operation','assess_work_item_readiness','work_item_id',p_work_item_id,
		'project_id',p_project_id,'expected_revision',p_expected_revision,
		'actor_id',p_actor_id,'correlation_id',p_correlation_id,'provenance',p_provenance);
	replay := decodex.reserve_exact_work_item_command(p_protocol,p_idempotency_key,request_value);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	IF p_work_item_id IS NULL OR p_project_id IS NULL OR p_expected_revision IS NULL
		OR p_actor_id IS NULL OR p_correlation_id IS NULL OR p_provenance IS NULL
		OR p_expected_revision <= 0 OR NOT decodex.is_work_item_text(p_provenance,4096)
		OR p_work_item_id::text COLLATE pg_catalog."C" !~
			'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
		OR p_correlation_id::text COLLATE pg_catalog."C" !~
			'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_input'); END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1343,pg_catalog.hashtext(p_project_id::text));
	SELECT work.* INTO item FROM decodex.work_items work
	WHERE work.work_item_id=p_work_item_id AND work.project_id=p_project_id FOR UPDATE OF work;
	IF NOT FOUND THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'missing_target'); END IF;
	IF item.revision<>p_expected_revision THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'stale_revision'); END IF;
	IF item.state NOT IN ('planned','blocked') THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'illegal_transition'); END IF;
	IF p_actor_id<>item.lead_agent_id THEN
		RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_authority'); END IF;
	-- All authority inputs are selected again inside this transaction after the exact row lock.
	PERFORM 1 FROM decodex.programs WHERE program_id=item.program_id FOR SHARE;
	PERFORM 1 FROM decodex.objectives objective JOIN decodex.work_item_objectives link USING(objective_id)
		WHERE link.work_item_id=p_work_item_id ORDER BY objective.objective_id FOR SHARE OF objective;
	PERFORM 1 FROM decodex.work_items related JOIN decodex.work_item_edges edge
		ON edge.related_work_item_id=related.work_item_id WHERE edge.work_item_id=p_work_item_id
		ORDER BY related.work_item_id FOR SHARE OF related;
	SELECT project.status,lead.status,lead.role INTO project_state,lead_state,lead_role
	FROM decodex.projects project JOIN decodex.agents lead
		ON lead.agent_id=item.lead_agent_id AND lead.project_id=project.project_id
	WHERE project.project_id=p_project_id FOR SHARE OF project,lead;
	blockers := decodex.work_item_readiness(p_work_item_id);
	DELETE FROM decodex.work_item_readiness_blockers WHERE work_item_id=p_work_item_id;
	target_state := CASE WHEN pg_catalog.jsonb_array_length(blockers)=0 THEN 'ready' ELSE 'blocked' END;
	event_kind := CASE WHEN target_state='ready' THEN 'work_item_ready' ELSE 'work_item_readiness_blocked' END;
	UPDATE decodex.work_items SET state=target_state,revision=revision+1,last_changed_by=p_actor_id,
		last_correlation_id=p_correlation_id,last_provenance=p_provenance,
		updated_at=pg_catalog.clock_timestamp() WHERE work_item_id=p_work_item_id;
	IF target_state='blocked' THEN
		INSERT INTO decodex.work_item_readiness_blockers(project_id,work_item_id,work_item_revision,
			ordinal,kind,subject_id,observed_state)
		SELECT p_project_id,p_work_item_id,p_expected_revision+1,entry.ordinality,
			(entry.value->>'kind')::decodex.work_item_blocker_kind,
			(entry.value->>'subject_id')::uuid,entry.value->>'observed_state'
		FROM pg_catalog.jsonb_array_elements(blockers) WITH ORDINALITY AS entry(value,ordinality);
	END IF;
	RETURN decodex.complete_exact_work_item_success(p_protocol,p_idempotency_key,event_kind,
		p_work_item_id,pg_catalog.jsonb_build_object('request',request_value,
			'readiness_blockers',blockers,'ready',target_state='ready'));
END
$_$;


--
-- Name: attest_codex_account_capability_exact(text, text, text, text, boolean, boolean); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.attest_codex_account_capability_exact(p_build_identity text, p_executable_sha256 text, p_schema_sha256 text, p_callback_profile_sha256 text, p_login_chatgpt_auth_tokens boolean, p_refresh_callback boolean) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
BEGIN
	INSERT INTO decodex.codex_account_capability(
		singleton,build_identity,executable_sha256,schema_sha256,callback_profile_sha256,
		login_chatgpt_auth_tokens,refresh_callback
	) VALUES (true,p_build_identity,p_executable_sha256,p_schema_sha256,p_callback_profile_sha256,
		p_login_chatgpt_auth_tokens,p_refresh_callback)
	ON CONFLICT(singleton) DO UPDATE SET build_identity=EXCLUDED.build_identity,
		executable_sha256=EXCLUDED.executable_sha256,schema_sha256=EXCLUDED.schema_sha256,
		callback_profile_sha256=EXCLUDED.callback_profile_sha256,
		login_chatgpt_auth_tokens=EXCLUDED.login_chatgpt_auth_tokens,
		refresh_callback=EXCLUDED.refresh_callback,observed_at=pg_catalog.clock_timestamp();
	RETURN CASE WHEN octet_length(p_build_identity) BETWEEN 1 AND 256
		AND p_executable_sha256 ~ '^[0-9a-f]{64}$'
		AND p_schema_sha256 ~ '^[0-9a-f]{64}$'
		AND p_callback_profile_sha256 ~ '^[0-9a-f]{64}$'
		AND p_login_chatgpt_auth_tokens AND p_refresh_callback
		THEN 'ready' ELSE 'unready' END;
END
$_$;


--
-- Name: attest_codex_experiment_retained_title_exact(text, text, uuid, bigint, uuid, uuid, text, bigint, text, bigint, text, text, text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.attest_codex_experiment_retained_title_exact(p_protocol text, p_idempotency_key text, p_experiment_id uuid, p_expected_revision bigint, p_attestation_id uuid, p_title_attempt_id uuid, p_thread_id text, p_read_request_id bigint, p_read_request_digest text, p_read_response_id bigint, p_read_response_digest text, p_returned_title text, p_returned_cwd text, p_returned_marker text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; replay bytea; attested timestamptz; experiment_row record;
DECLARE core jsonb; effect jsonb; response bytea;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','attest_codex_experiment_retained_title','protocol',p_protocol,
		'experiment_id',p_experiment_id,'expected_revision',p_expected_revision,
		'attestation_id',p_attestation_id,'title_attempt_id',p_title_attempt_id,
		'thread_id',p_thread_id,'read_request_id',p_read_request_id,
		'read_request_digest',p_read_request_digest,'read_response_id',p_read_response_id,
		'read_response_digest',p_read_response_digest,'returned_title',p_returned_title,
		'returned_cwd',p_returned_cwd,'returned_marker',p_returned_marker);
	replay:=decodex.reserve_exact_codex_experiment_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1358);
	PERFORM pg_catalog.pg_advisory_xact_lock(1358,pg_catalog.hashtext(p_experiment_id::text));
	SELECT experiment.*,title_attempt.request_id AS title_request_id
	INTO experiment_row FROM decodex.codex_experiments AS experiment
	JOIN decodex.codex_experiment_start_receipts AS start_receipt USING (experiment_id)
	JOIN decodex.codex_experiment_title_set_attempts AS title_attempt USING (experiment_id,thread_id)
	WHERE experiment.experiment_id=p_experiment_id
		AND title_attempt.title_attempt_id=p_title_attempt_id
		AND start_receipt.thread_id=p_thread_id
	FOR SHARE OF experiment,start_receipt,title_attempt;
	IF NOT FOUND OR experiment_row.revision<>p_expected_revision OR p_expected_revision<>3
		OR experiment_row.state<>'thread_bound' OR p_attestation_id IS NULL
		OR p_read_request_id IS NULL OR p_read_request_id<=0
		OR p_read_request_id<=experiment_row.title_request_id
		OR p_read_response_id IS DISTINCT FROM p_read_request_id
		OR p_read_request_digest IS NULL OR p_read_request_digest!~'^[0-9a-f]{64}$'
		OR p_read_response_digest IS NULL OR p_read_response_digest!~'^[0-9a-f]{64}$'
		OR p_returned_title IS DISTINCT FROM experiment_row.thread_title
		OR p_returned_cwd IS DISTINCT FROM experiment_row.repository_cwd
		OR p_returned_marker IS DISTINCT FROM experiment_row.marker THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'attest_codex_experiment_retained_title',
			'retained_title_mismatch');
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.codex_experiment_retained_title_attestations
		WHERE attestation_id=p_attestation_id OR experiment_id=p_experiment_id
			OR title_attempt_id=p_title_attempt_id) THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'attest_codex_experiment_retained_title',
			'attestation_identity_conflict');
	END IF;
	attested:=pg_catalog.clock_timestamp();
	INSERT INTO decodex.codex_experiment_retained_title_attestations(
		attestation_id,experiment_id,title_attempt_id,thread_id,
		read_request_id,read_request_digest,read_response_id,read_response_digest,
		returned_title,returned_cwd,returned_marker,attested_at
	) VALUES (
		p_attestation_id,p_experiment_id,p_title_attempt_id,p_thread_id,
		p_read_request_id,p_read_request_digest,p_read_response_id,p_read_response_digest,
		p_returned_title,p_returned_cwd,p_returned_marker,attested
	);
	core:=pg_catalog.jsonb_build_object(
		'operation','attest_codex_experiment_retained_title',
		'experiment_id',p_experiment_id,'experiment_revision',3,
		'attestation_id',p_attestation_id,'title_attempt_id',p_title_attempt_id,
		'thread_id',p_thread_id,'read_request_id',p_read_request_id,
		'read_request_digest',p_read_request_digest,'read_response_id',p_read_response_id,
		'read_response_digest',p_read_response_digest,'retained_title',p_returned_title,
		'returned_cwd',p_returned_cwd,'marker',p_returned_marker,
		'attested_at_micros',(extract(epoch FROM attested)*1000000)::bigint);
	effect:=core||pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',
		outcome_class='success',effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$_$;


--
-- Name: authorize_provider_attempt_dispatch_exact(uuid, bigint, uuid, bigint, uuid, bigint, uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.authorize_provider_attempt_dispatch_exact(p_attempt_id uuid, p_expected_revision bigint, p_process_generation_id uuid, p_process_generation_revision bigint, p_conversation_id uuid, p_expected_conversation_revision bigint, p_turn_id uuid, p_expected_turn_revision bigint) RETURNS TABLE(result_code text, revision bigint, state decodex.provider_attempt_state, updated_at_micros bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE attempt decodex.provider_attempts%ROWTYPE;
DECLARE plan decodex.continuation_plans%ROWTYPE;
DECLARE conversation_row decodex.conversations%ROWTYPE;
DECLARE turn_row decodex.turns%ROWTYPE;
DECLARE scope_kind decodex.provider_attempt_consumer_kind;
DECLARE scope_conversation_id uuid; scope_managed_run_id uuid;
DECLARE now_value timestamptz;
BEGIN
	PERFORM pg_catalog.pg_advisory_xact_lock_shared(1400);
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	SELECT consumer_kind,conversation_id,managed_run_id
	INTO scope_kind,scope_conversation_id,scope_managed_run_id
	FROM decodex.provider_attempts WHERE attempt_id=p_attempt_id;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'attempt_missing',0::bigint,
			'prepared'::decodex.provider_attempt_state,0::bigint;
		RETURN;
	END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1401,pg_catalog.hashtext(
			scope_kind::text||':'||COALESCE(
				scope_conversation_id::text,scope_managed_run_id::text
			)
		)
	);
	SELECT * INTO attempt FROM decodex.provider_attempts
	WHERE attempt_id=p_attempt_id FOR UPDATE;
	IF p_expected_revision IS NULL OR p_expected_revision<=0
		OR p_process_generation_id IS NULL
		OR p_process_generation_revision IS NULL OR p_process_generation_revision<=0
		OR NOT (
			attempt.consumer_kind='conversation_turn'
				AND p_conversation_id IS NOT NULL
				AND p_expected_conversation_revision>0
				AND p_turn_id IS NOT NULL AND p_expected_turn_revision=1
			OR attempt.consumer_kind='managed_run_execution'
				AND p_conversation_id IS NULL
				AND p_expected_conversation_revision IS NULL
				AND p_turn_id IS NULL AND p_expected_turn_revision IS NULL
		)
	THEN
		RETURN QUERY SELECT 'invalid_input',attempt.revision,attempt.state,
			(extract(epoch FROM attempt.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF attempt.state='dispatch_authorized' THEN
		RETURN QUERY SELECT CASE
			WHEN p_expected_revision=attempt.revision-1 AND (
				p_process_generation_id,p_process_generation_revision
			)=(attempt.process_generation_id,attempt.process_generation_revision)
			THEN 'replayed' ELSE 'stale_attempt' END,
			attempt.revision,attempt.state,
			(extract(epoch FROM attempt.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF attempt.state<>'prepared' OR attempt.revision<>p_expected_revision
		OR (attempt.process_generation_id,attempt.process_generation_revision)<>
			(p_process_generation_id,p_process_generation_revision)
	THEN
		RETURN QUERY SELECT 'stale_attempt',attempt.revision,attempt.state,
			(extract(epoch FROM attempt.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	SELECT * INTO plan FROM decodex.continuation_plans
	WHERE plan_id=attempt.continuation_plan_id FOR SHARE;
	IF attempt.consumer_kind='conversation_turn' THEN
		SELECT * INTO conversation_row FROM decodex.conversations
		WHERE conversation_id=p_conversation_id FOR UPDATE;
		SELECT * INTO turn_row FROM decodex.turns WHERE turn_id=p_turn_id FOR UPDATE;
		IF attempt.conversation_id<>p_conversation_id OR attempt.turn_id<>p_turn_id
			OR conversation_row.conversation_id IS NULL
			OR conversation_row.status<>'open'
			OR conversation_row.revision<>p_expected_conversation_revision
			OR plan.conversation_revision<>p_expected_conversation_revision
			OR turn_row.turn_id IS NULL OR turn_row.conversation_id<>p_conversation_id
			OR turn_row.runtime_session_id<>plan.source_runtime_session_id
			OR turn_row.role<>'user' OR turn_row.possible_side_effects<>'unknown'
			OR turn_row.status<>'active'
			OR turn_row.revision<>p_expected_turn_revision
		THEN
			RETURN QUERY SELECT 'consumer_unavailable',attempt.revision,attempt.state,
				(extract(epoch FROM attempt.updated_at)*1000000)::bigint;
			RETURN;
		END IF;
	ELSIF NOT EXISTS (
		SELECT 1 FROM decodex.managed_runs AS run
		WHERE (run.managed_run_id,run.revision)=(
			attempt.managed_run_id,attempt.managed_run_revision
		) FOR SHARE
	) THEN
		RETURN QUERY SELECT 'consumer_unavailable',attempt.revision,attempt.state,
			(extract(epoch FROM attempt.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF plan.plan_id IS NULL OR plan.routing_decision_id<>attempt.routing_decision_id
		OR plan.selected_account_id<>attempt.selected_account_id
		OR plan.kind NOT IN ('initial_thread','same_thread','context_pack_fallback')
		OR NOT EXISTS (
			SELECT 1 FROM decodex.runtime_sessions AS session
			JOIN decodex.account_snapshots AS account
				ON account.account_snapshot_id=session.account_snapshot_id
			WHERE (session.runtime_session_id,session.revision)=(
				attempt.accepted_runtime_session_id,
				attempt.accepted_runtime_session_revision
			)
				AND session.state='active'
				AND account.source_account_id=attempt.selected_account_id
			FOR SHARE OF session,account
		)
		OR EXISTS (
			SELECT 1 FROM decodex.provider_attempts AS unresolved
			WHERE unresolved.state='unknown'
				AND unresolved.attempt_id<>attempt.attempt_id
				AND unresolved.attempt_id IS DISTINCT FROM attempt.predecessor_attempt_id
				AND unresolved.consumer_kind=attempt.consumer_kind
				AND (
					attempt.consumer_kind='conversation_turn'
						AND unresolved.conversation_id=attempt.conversation_id
					OR attempt.consumer_kind='managed_run_execution'
						AND unresolved.managed_run_id=attempt.managed_run_id
				)
		)
	THEN
		RETURN QUERY SELECT 'authority_unavailable',attempt.revision,attempt.state,
			(extract(epoch FROM attempt.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF NOT EXISTS (
		SELECT 1 FROM decodex.process_generations AS generation
		JOIN decodex.process_generation_execution_epochs AS epoch
			ON epoch.execution_epoch_id=generation.execution_epoch_id
		WHERE generation.generation_id=attempt.process_generation_id
			AND generation.revision=attempt.process_generation_revision
			AND generation.account_id=attempt.selected_account_id
			AND generation.execution_epoch_id=attempt.process_execution_epoch_id
			AND generation.state='ready' AND generation.process_id IS NOT NULL
			AND epoch.retired_at IS NULL FOR SHARE OF generation,epoch
	) THEN
		RETURN QUERY SELECT 'generation_unavailable',attempt.revision,attempt.state,
			(extract(epoch FROM attempt.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	now_value:=pg_catalog.clock_timestamp();
	UPDATE decodex.provider_attempts AS target SET
		state='dispatch_authorized',revision=target.revision+1,updated_at=now_value
	WHERE target.attempt_id=p_attempt_id;
	RETURN QUERY SELECT 'dispatch_authorized',p_expected_revision+1,
		'dispatch_authorized'::decodex.provider_attempt_state,
		(extract(epoch FROM now_value)*1000000)::bigint;
END
$$;


--
-- Name: bind_codex_experiment_start_exact(text, text, uuid, bigint, uuid, text, bigint, text, text, text, boolean, bigint, text, text, text, boolean, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.bind_codex_experiment_start_exact(p_protocol text, p_idempotency_key text, p_experiment_id uuid, p_expected_revision bigint, p_attempt_id uuid, p_thread_id text, p_start_request_id bigint, p_start_request_digest text, p_request_cwd text, p_request_marker text, p_request_ephemeral boolean, p_start_response_id bigint, p_start_response_digest text, p_response_cwd text, p_response_marker text, p_response_ephemeral boolean, p_returned_name text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; replay bytea; bound timestamptz; experiment_row record;
DECLARE core jsonb; effect jsonb; response bytea;
BEGIN
	request:=pg_catalog.jsonb_build_object('operation','bind_codex_experiment_start',
		'protocol',p_protocol,'experiment_id',p_experiment_id,
		'expected_revision',p_expected_revision,'attempt_id',p_attempt_id,
		'thread_id',p_thread_id,'start_request_id',p_start_request_id,
		'start_request_digest',p_start_request_digest,'request_cwd',p_request_cwd,
		'request_marker',p_request_marker,'request_ephemeral',p_request_ephemeral,
		'start_response_id',p_start_response_id,
		'start_response_digest',p_start_response_digest,'response_cwd',p_response_cwd,
		'response_marker',p_response_marker,'response_ephemeral',p_response_ephemeral,
		'returned_name',p_returned_name);
	replay:=decodex.reserve_exact_codex_experiment_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1358);
	PERFORM pg_catalog.pg_advisory_xact_lock(1358,pg_catalog.hashtext(p_experiment_id::text));
	SELECT * INTO experiment_row FROM decodex.codex_experiments
	WHERE experiment_id=p_experiment_id FOR UPDATE;
	IF NOT FOUND OR experiment_row.revision<>p_expected_revision OR p_expected_revision<>2
		OR experiment_row.state<>'creation_possible'
		OR NOT EXISTS (SELECT 1 FROM decodex.codex_experiment_creation_attempts
			WHERE experiment_id=p_experiment_id AND attempt_id=p_attempt_id)
		OR p_thread_id IS NULL OR p_thread_id='' OR octet_length(p_thread_id)>1024
		OR p_thread_id~'[[:cntrl:]]'
		OR p_start_request_id IS NULL OR p_start_request_id<=0
		OR p_start_response_id IS DISTINCT FROM p_start_request_id
		OR p_start_request_digest IS NULL OR p_start_request_digest!~'^[0-9a-f]{64}$'
		OR p_request_cwd IS DISTINCT FROM experiment_row.repository_cwd
		OR p_request_marker IS DISTINCT FROM experiment_row.marker
		OR p_request_ephemeral IS DISTINCT FROM false
		OR p_start_response_digest IS NULL OR p_start_response_digest!~'^[0-9a-f]{64}$'
		OR p_response_cwd IS DISTINCT FROM experiment_row.repository_cwd
		OR p_response_marker IS DISTINCT FROM experiment_row.marker
		OR p_response_ephemeral IS DISTINCT FROM false
		OR p_returned_name IS NOT NULL THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'bind_codex_experiment_start',
			'start_response_mismatch');
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.codex_experiment_thread_bindings
		WHERE thread_id=p_thread_id
			OR response_id=p_attempt_id::text||':'||p_start_response_id::text
			OR attempt_id=p_attempt_id)
		OR EXISTS (SELECT 1 FROM decodex.codex_experiment_start_receipts
			WHERE experiment_id=p_experiment_id) THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'bind_codex_experiment_start',
			'start_identity_conflict');
	END IF;
	bound:=pg_catalog.clock_timestamp();
	INSERT INTO decodex.codex_experiment_revisions VALUES(p_experiment_id,3,'thread_bound',bound);
	INSERT INTO decodex.codex_experiment_thread_bindings VALUES(
		p_experiment_id,3,p_attempt_id,p_thread_id,
		p_attempt_id::text||':'||p_start_response_id::text,bound);
	INSERT INTO decodex.codex_experiment_start_receipts(
		experiment_id,attempt_id,experiment_revision,thread_id,
		start_request_id,start_request_digest,request_cwd,request_marker,request_ephemeral,
		start_response_id,start_response_digest,
		response_cwd,response_marker,response_ephemeral,returned_name,bound_at
	) VALUES (
		p_experiment_id,p_attempt_id,3,p_thread_id,
		p_start_request_id,p_start_request_digest,p_request_cwd,p_request_marker,p_request_ephemeral,
		p_start_response_id,p_start_response_digest,
		p_response_cwd,p_response_marker,p_response_ephemeral,p_returned_name,bound
	);
	UPDATE decodex.codex_experiments SET revision=3,state='thread_bound',updated_at=bound
	WHERE experiment_id=p_experiment_id;
	core:=pg_catalog.jsonb_build_object('operation','bind_codex_experiment_start',
		'experiment_id',p_experiment_id,'revision',3,'state','thread_bound',
		'attempt_id',p_attempt_id,'thread_id',p_thread_id,
		'start_request_id',p_start_request_id,'start_request_digest',p_start_request_digest,
		'request_cwd',p_request_cwd,'request_marker',p_request_marker,
		'request_ephemeral',p_request_ephemeral,
		'start_response_id',p_start_response_id,'start_response_digest',p_start_response_digest,
		'response_cwd',p_response_cwd,'response_marker',p_response_marker,
		'response_ephemeral',p_response_ephemeral,'returned_name',p_returned_name,
		'bound_at_micros',(extract(epoch FROM bound)*1000000)::bigint);
	effect:=core||pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',
		outcome_class='success',effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$_$;


--
-- Name: bind_codex_experiment_thread_exact(text, text, uuid, bigint, uuid, text, text, text, text, text, boolean); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.bind_codex_experiment_thread_exact(p_protocol text, p_idempotency_key text, p_experiment_id uuid, p_expected_revision bigint, p_attempt_id uuid, p_thread_id text, p_response_id text, p_response_title text, p_response_cwd text, p_response_marker text, p_ephemeral boolean) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; replay bytea; bound timestamptz; experiment_row record;
DECLARE core jsonb; effect jsonb; response bytea;
BEGIN
	request:=pg_catalog.jsonb_build_object('operation','bind_codex_experiment_thread',
		'protocol',p_protocol,'experiment_id',p_experiment_id,
		'expected_revision',p_expected_revision,'attempt_id',p_attempt_id,
		'thread_id',p_thread_id,'response_id',p_response_id,'response_title',p_response_title,
		'response_cwd',p_response_cwd,'response_marker',p_response_marker,'ephemeral',p_ephemeral);
	replay:=decodex.reserve_exact_codex_experiment_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1358);
	PERFORM pg_catalog.pg_advisory_xact_lock(1358,pg_catalog.hashtext(p_experiment_id::text));
	SELECT * INTO experiment_row FROM decodex.codex_experiments
	WHERE experiment_id=p_experiment_id FOR UPDATE;
	IF NOT FOUND OR experiment_row.revision<>p_expected_revision OR p_expected_revision<>2
		OR experiment_row.state<>'creation_possible'
		OR NOT EXISTS (SELECT 1 FROM decodex.codex_experiment_creation_attempts
			WHERE experiment_id=p_experiment_id AND attempt_id=p_attempt_id)
		OR p_thread_id IS NULL OR p_thread_id='' OR p_response_id IS NULL OR p_response_id=''
		OR p_ephemeral IS DISTINCT FROM false
		OR p_response_title IS DISTINCT FROM experiment_row.thread_title
		OR p_response_cwd IS DISTINCT FROM experiment_row.repository_cwd
		OR p_response_marker IS DISTINCT FROM experiment_row.marker THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'bind_codex_experiment_thread','typed_response_mismatch');
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.codex_experiment_thread_bindings
		WHERE thread_id=p_thread_id OR response_id=p_response_id OR attempt_id=p_attempt_id) THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'bind_codex_experiment_thread','thread_identity_conflict');
	END IF;
	bound:=pg_catalog.clock_timestamp();
	INSERT INTO decodex.codex_experiment_revisions VALUES(p_experiment_id,3,'thread_bound',bound);
	INSERT INTO decodex.codex_experiment_thread_bindings VALUES(
		p_experiment_id,3,p_attempt_id,p_thread_id,p_response_id,bound);
	UPDATE decodex.codex_experiments SET revision=3,state='thread_bound',updated_at=bound
	WHERE experiment_id=p_experiment_id;
	core:=pg_catalog.jsonb_build_object('operation','bind_codex_experiment_thread',
		'experiment_id',p_experiment_id,'revision',3,'state','thread_bound',
		'attempt_id',p_attempt_id,'thread_id',p_thread_id,'response_id',p_response_id,
		'marker',experiment_row.marker,
		'bound_at_micros',(extract(epoch FROM bound)*1000000)::bigint);
	effect:=core||pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$$;


--
-- Name: bind_process_generation_identity_exact(uuid, bigint, text, bigint, text, bigint, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.bind_process_generation_identity_exact(p_generation_id uuid, p_expected_revision bigint, p_bound_boot_id text, p_process_id bigint, p_process_start_id text, p_process_group_id bigint, p_session_id bigint) RETURNS TABLE(result_code text, revision bigint, state decodex.process_generation_state, updated_at_micros bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE generation decodex.process_generations%ROWTYPE;
DECLARE now_value timestamptz;
BEGIN
	SELECT * INTO generation FROM decodex.process_generations
	WHERE generation_id = p_generation_id FOR UPDATE;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'generation_missing', 0::bigint,
			'starting'::decodex.process_generation_state, 0::bigint;
		RETURN;
	END IF;
	IF p_expected_revision IS NULL THEN
		RETURN QUERY SELECT 'stale_generation', generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF generation.process_id IS NOT NULL THEN
		IF (generation.bound_boot_id, generation.process_id, generation.process_start_id,
			generation.process_group_id, generation.session_id)
			IS NOT DISTINCT FROM
			(p_bound_boot_id, p_process_id, p_process_start_id,
			p_process_group_id, p_session_id)
			AND generation.state = 'starting'
			AND p_expected_revision = generation.revision - 1
		THEN
			RETURN QUERY SELECT 'replayed', generation.revision, generation.state,
				(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		ELSIF (generation.bound_boot_id, generation.process_id, generation.process_start_id,
			generation.process_group_id, generation.session_id)
			IS NOT DISTINCT FROM
			(p_bound_boot_id, p_process_id, p_process_start_id,
			p_process_group_id, p_session_id)
		THEN
			RETURN QUERY SELECT 'stale_generation', generation.revision, generation.state,
				(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		ELSE
			RETURN QUERY SELECT 'process_identity_conflict', generation.revision, generation.state,
				(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		END IF;
		RETURN;
	END IF;
	IF generation.revision <> p_expected_revision
		OR generation.state <> 'starting'
	THEN
		RETURN QUERY SELECT 'stale_generation', generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF p_bound_boot_id IS DISTINCT FROM generation.intended_boot_id
		OR p_process_id IS NULL OR p_process_id NOT BETWEEN 1 AND 4294967295
		OR p_process_group_id IS DISTINCT FROM p_process_id
		OR p_session_id IS DISTINCT FROM p_process_id
		OR p_process_start_id IS NULL OR p_process_start_id = ''
		OR octet_length(p_process_start_id) > 128
		OR p_process_start_id ~ '[[:cntrl:][:space:]]'
	THEN
		RETURN QUERY SELECT 'invalid_process_identity', generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	now_value := pg_catalog.clock_timestamp();
	UPDATE decodex.process_generations AS target
	SET bound_boot_id = p_bound_boot_id,
		process_id = p_process_id,
		process_start_id = p_process_start_id,
		process_group_id = p_process_group_id,
		session_id = p_session_id,
		revision = target.revision + 1,
		updated_at = now_value
	WHERE target.generation_id = p_generation_id;
	RETURN QUERY SELECT 'bound', p_expected_revision + 1,
		'starting'::decodex.process_generation_state,
		(extract(epoch FROM now_value)*1000000)::bigint;
END;
$$;


--
-- Name: bind_runtime_session_thread_exact(text, text, uuid, bigint, uuid, bigint, uuid, bigint, uuid, text, text, bigint, text, bigint, text, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.bind_runtime_session_thread_exact(p_protocol text, p_idempotency_key text, p_conversation_id uuid, p_expected_conversation_revision bigint, p_runtime_session_id uuid, p_expected_revision bigint, p_turn_id uuid, p_expected_turn_revision bigint, p_continuation_plan_id uuid, p_fence_protocol text, p_fence_idempotency_key text, p_thread_start_request_id bigint, p_thread_start_request_sha256 text, p_thread_start_response_id bigint, p_thread_start_response_sha256 text, p_codex_thread_id uuid) RETURNS TABLE(response_bytes bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; claimed record; fence decodex.exact_command_receipts%ROWTYPE;
DECLARE conversation_row decodex.conversations%ROWTYPE;
DECLARE session_row decodex.runtime_sessions%ROWTYPE;
DECLARE turn_row decodex.turns%ROWTYPE;
DECLARE plan_row decodex.continuation_plans%ROWTYPE;
DECLARE expected_turn_session_id uuid; new_revision bigint;
DECLARE payload jsonb; links jsonb; core jsonb; effect jsonb;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','bind_runtime_session_thread','protocol_version',p_protocol,
		'conversation_id',p_conversation_id,
		'expected_conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,'expected_revision',p_expected_revision,
		'turn_id',p_turn_id,'expected_turn_revision',p_expected_turn_revision,
		'continuation_plan_id',p_continuation_plan_id,
		'fence_protocol',p_fence_protocol,
		'fence_idempotency_key',p_fence_idempotency_key,
		'thread_start_request_id',p_thread_start_request_id,
		'thread_start_request_sha256',p_thread_start_request_sha256,
		'thread_start_response_id',p_thread_start_response_id,
		'thread_start_response_sha256',p_thread_start_response_sha256,
		'codex_thread_id',p_codex_thread_id
	);
	SELECT * INTO claimed FROM decodex.claim_runtime_session_thread_command(
		p_protocol,p_idempotency_key,request
	);
	IF claimed.replayed THEN
		RETURN QUERY SELECT claimed.response_bytes,true;
		RETURN;
	END IF;
	IF p_conversation_id IS NULL OR p_runtime_session_id IS NULL OR p_turn_id IS NULL
		OR p_continuation_plan_id IS NULL OR p_codex_thread_id IS NULL
		OR p_expected_conversation_revision IS NULL
		OR p_expected_conversation_revision<=0
		OR p_expected_revision IS NULL OR p_expected_revision<=1
		OR p_expected_turn_revision IS DISTINCT FROM 1
		OR p_fence_protocol IS DISTINCT FROM 'decodex/exact-command/1'
		OR p_fence_idempotency_key IS NULL
		OR pg_catalog.octet_length(p_fence_idempotency_key) NOT BETWEEN 1 AND 256
		OR p_fence_idempotency_key COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
		OR decodex.has_credential_material(p_fence_idempotency_key)
		OR p_fence_idempotency_key=p_idempotency_key
		OR p_thread_start_request_id IS NULL OR p_thread_start_request_id<=0
		OR p_thread_start_response_id IS DISTINCT FROM p_thread_start_request_id
		OR p_thread_start_request_sha256 IS NULL
		OR p_thread_start_request_sha256 COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$'
		OR decodex.has_credential_material(p_thread_start_request_sha256)
		OR p_thread_start_response_sha256 IS NULL
		OR p_thread_start_response_sha256 COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$'
		OR decodex.has_credential_material(p_thread_start_response_sha256)
	THEN
		response_bytes:=decodex.complete_runtime_session_thread_rejection(
			p_protocol,p_idempotency_key,'bind_runtime_session_thread',request,'invalid_input'
		);
		replayed:=false;
		RETURN NEXT;
		RETURN;
	END IF;

	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1276,pg_catalog.hashtext(p_runtime_session_id::text)
	);
	SELECT * INTO fence FROM decodex.exact_command_receipts
	WHERE protocol_version=p_fence_protocol
		AND idempotency_key=p_fence_idempotency_key FOR SHARE;
	SELECT * INTO conversation_row FROM decodex.conversations
	WHERE conversation_id=p_conversation_id FOR UPDATE;
	SELECT * INTO session_row FROM decodex.runtime_sessions
	WHERE runtime_session_id=p_runtime_session_id FOR UPDATE;
	SELECT * INTO turn_row FROM decodex.turns WHERE turn_id=p_turn_id FOR UPDATE;
	SELECT * INTO plan_row FROM decodex.continuation_plans
	WHERE plan_id=p_continuation_plan_id FOR SHARE;
	expected_turn_session_id:=CASE plan_row.kind
		WHEN 'context_pack_fallback' THEN plan_row.source_runtime_session_id
		ELSE p_runtime_session_id
	END;
	IF fence.receipt_state IS DISTINCT FROM 'completed_success'
		OR fence.request_envelope->>'operation' IS DISTINCT FROM
			'fence_runtime_session_thread_start'
		OR fence.request_envelope->>'protocol_version' IS DISTINCT FROM p_fence_protocol
		OR fence.request_envelope->>'conversation_id' IS DISTINCT FROM p_conversation_id::text
		OR fence.request_envelope->>'expected_conversation_revision' IS DISTINCT FROM
			p_expected_conversation_revision::text
		OR fence.request_envelope->>'runtime_session_id' IS DISTINCT FROM
			p_runtime_session_id::text
		OR fence.request_envelope->>'expected_revision' IS DISTINCT FROM
			(p_expected_revision-1)::text
		OR fence.request_envelope->>'turn_id' IS DISTINCT FROM p_turn_id::text
		OR fence.request_envelope->>'expected_turn_revision' IS DISTINCT FROM '1'
		OR fence.request_envelope->>'continuation_plan_id' IS DISTINCT FROM
			p_continuation_plan_id::text
		OR fence.request_envelope->>'thread_start_request_id' IS DISTINCT FROM
			p_thread_start_request_id::text
		OR fence.request_envelope->>'thread_start_request_sha256' IS DISTINCT FROM
			p_thread_start_request_sha256
		OR fence.effect_envelope->>'operation' IS DISTINCT FROM
			'fence_runtime_session_thread_start'
		OR fence.effect_envelope->>'kind' IS DISTINCT FROM
			'runtime_session_thread_start_fenced'
		OR fence.effect_envelope->>'prior_revision' IS DISTINCT FROM
			(p_expected_revision-1)::text
		OR fence.effect_envelope->>'revision' IS DISTINCT FROM p_expected_revision::text
		OR fence.effect_envelope->>'turn_id' IS DISTINCT FROM p_turn_id::text
		OR fence.effect_envelope->>'turn_revision' IS DISTINCT FROM '1'
		OR fence.effect_envelope->>'turn_state' IS DISTINCT FROM 'active'
		OR conversation_row.conversation_id IS NULL
		OR conversation_row.revision<>p_expected_conversation_revision
		OR conversation_row.status<>'open'
		OR session_row.runtime_session_id IS NULL
		OR session_row.conversation_id<>p_conversation_id
		OR session_row.revision<>p_expected_revision
		OR session_row.state<>'starting' OR session_row.codex_thread_id IS NOT NULL
		OR session_row.thread_start_request_id IS DISTINCT FROM p_thread_start_request_id
		OR session_row.thread_start_request_sha256 IS DISTINCT FROM
			p_thread_start_request_sha256
		OR session_row.thread_start_response_id IS NOT NULL
		OR session_row.thread_start_response_sha256 IS NOT NULL
		OR turn_row.turn_id IS NULL OR turn_row.conversation_id<>p_conversation_id
		OR turn_row.runtime_session_id IS DISTINCT FROM expected_turn_session_id
		OR turn_row.role<>'user' OR turn_row.possible_side_effects<>'unknown'
		OR turn_row.status<>'active' OR turn_row.revision<>1
		OR plan_row.plan_id IS NULL OR plan_row.consumer_kind<>'conversation_turn'
		OR plan_row.consumer_conversation_id<>p_conversation_id
		OR plan_row.conversation_revision<>p_expected_conversation_revision
		OR plan_row.turn_id<>p_turn_id
		OR NOT (
			plan_row.kind='initial_thread'
				AND plan_row.source_runtime_session_id=p_runtime_session_id
				AND plan_row.source_runtime_session_revision=p_expected_revision-1
			OR plan_row.kind='context_pack_fallback'
				AND plan_row.fallback_runtime_session_id=p_runtime_session_id
				AND p_expected_revision=2
		)
		OR EXISTS (
			SELECT 1 FROM decodex.runtime_sessions AS other
			WHERE other.codex_thread_id=p_codex_thread_id
				AND other.runtime_session_id<>p_runtime_session_id
		)
	THEN
		response_bytes:=decodex.complete_runtime_session_thread_rejection(
			p_protocol,p_idempotency_key,'bind_runtime_session_thread',request,
			'authority_unavailable'
		);
		replayed:=false;
		RETURN NEXT;
		RETURN;
	END IF;

	UPDATE decodex.runtime_sessions SET
		codex_thread_id=p_codex_thread_id,
		thread_start_response_id=p_thread_start_response_id,
		thread_start_response_sha256=p_thread_start_response_sha256,
		state='active',revision=revision+1
	WHERE runtime_session_id=p_runtime_session_id
	RETURNING revision INTO new_revision;
	payload:=pg_catalog.jsonb_build_object(
		'kind','runtime_session_thread_bound',
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'prior_state','starting','state','active',
		'prior_revision',p_expected_revision,'revision',new_revision,
		'turn_id',p_turn_id,'turn_revision',p_expected_turn_revision,
		'turn_state','active','continuation_plan_id',p_continuation_plan_id,
		'fence_protocol',p_fence_protocol,
		'fence_idempotency_key',p_fence_idempotency_key,
		'fence_prior_revision',p_expected_revision-1,
		'fence_revision',p_expected_revision,
		'thread_start_request_id',p_thread_start_request_id,
		'thread_start_request_sha256',p_thread_start_request_sha256,
		'thread_start_response_id',p_thread_start_response_id,
		'thread_start_response_sha256',p_thread_start_response_sha256,
		'codex_thread_id',p_codex_thread_id
	);
	links:=decodex.append_runtime_session_thread_effect(
		p_runtime_session_id,new_revision,'runtime_session_thread_bound',
		p_idempotency_key,payload
	);
	core:=payload||pg_catalog.jsonb_build_object(
		'operation','bind_runtime_session_thread',
		'activity_sequence',links->'activity_sequence','outbox_id',links->'outbox_id'
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	response_bytes:=decodex.complete_runtime_session_thread_command(
		p_protocol,p_idempotency_key,effect
	);
	replayed:=false;
	RETURN NEXT;
END
$_$;


--
-- Name: bootstrap_advisor(decodex.canonical_uuid_v4_text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.bootstrap_advisor(p_agent_id decodex.canonical_uuid_v4_text) RETURNS TABLE(agent_id uuid, role decodex.agent_role, project_id uuid, status decodex.agent_status, revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE canonical_agent_id pg_catalog.uuid;
BEGIN
	IF p_agent_id IS NULL THEN
		RAISE EXCEPTION 'identity ingress requires canonical UUID-v4 text'
			USING ERRCODE = '23514', CONSTRAINT = 'canonical_uuid_v4_text_ingress';
	END IF;
	canonical_agent_id := p_agent_id::pg_catalog.text::pg_catalog.uuid;
	PERFORM pg_catalog.pg_advisory_xact_lock(1315, 1);
	INSERT INTO decodex.agents (agent_id, role) VALUES (canonical_agent_id, 'advisor')
	ON CONFLICT DO NOTHING;
	RETURN QUERY
	SELECT stored.agent_id, stored.role, stored.project_id, stored.status, stored.revision
	FROM decodex.agents AS stored WHERE stored.role = 'advisor';
END
$$;


--
-- Name: bootstrap_role_profiles_exact(text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.bootstrap_role_profiles_exact(p_protocol text, p_idempotency_key text, p_advisor_model text, p_advisor_reasoning_effort text, p_advisor_service_tier text, p_advisor_instructions text, p_advisor_provenance text, p_lead_model text, p_lead_reasoning_effort text, p_lead_service_tier text, p_lead_instructions text, p_lead_provenance text, p_task_model text, p_task_reasoning_effort text, p_task_service_tier text, p_task_instructions text, p_task_provenance text, p_reviewer_model text, p_reviewer_reasoning_effort text, p_reviewer_service_tier text, p_reviewer_instructions text, p_reviewer_provenance text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request_value jsonb;
DECLARE existing_request jsonb;
DECLARE existing_response bytea;
DECLARE inserted_count integer;
DECLARE profiles_value jsonb;
DECLARE profile_value jsonb;
DECLARE activity_sequence bigint;
DECLARE activity_payload jsonb;
DECLARE outbox_id bigint;
DECLARE outbox_payload jsonb;
DECLARE effects_value jsonb := '[]'::jsonb;
DECLARE effect_value jsonb;
DECLARE response_value bytea;
BEGIN
	IF p_protocol IS NULL OR p_idempotency_key IS NULL THEN
		RAISE EXCEPTION 'exact RoleProfile command identity is incomplete' USING ERRCODE = '22004';
	END IF;
	IF pg_catalog.octet_length(p_protocol) NOT BETWEEN 1 AND 64
		OR p_protocol COLLATE pg_catalog."C" !~ '^[a-z0-9][a-z0-9._/-]{0,63}$'
		OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 256
		OR decodex.has_credential_material(p_idempotency_key)
	THEN
		RAISE EXCEPTION 'exact RoleProfile command identity is invalid' USING ERRCODE = '22023';
	END IF;

	request_value := decodex.build_role_profile_bootstrap_request(
		p_protocol,
		p_advisor_model, p_advisor_reasoning_effort, p_advisor_service_tier,
		p_advisor_instructions, p_advisor_provenance,
		p_lead_model, p_lead_reasoning_effort, p_lead_service_tier,
		p_lead_instructions, p_lead_provenance,
		p_task_model, p_task_reasoning_effort, p_task_service_tier,
		p_task_instructions, p_task_provenance,
		p_reviewer_model, p_reviewer_reasoning_effort, p_reviewer_service_tier,
		p_reviewer_instructions, p_reviewer_provenance
	);

	INSERT INTO decodex.exact_command_receipts(
		protocol_version, idempotency_key, request_envelope, request_digest, receipt_state
	) VALUES (
		p_protocol, p_idempotency_key, request_value,
		public.digest(pg_catalog.convert_to(request_value::text, 'UTF8'), 'sha256'), 'executing'
	) ON CONFLICT (protocol_version, idempotency_key) DO NOTHING;
	GET DIAGNOSTICS inserted_count = ROW_COUNT;

	IF inserted_count = 0 THEN
		SELECT request_envelope, response_bytes INTO existing_request, existing_response
		FROM decodex.exact_command_receipts
		WHERE protocol_version = p_protocol AND idempotency_key = p_idempotency_key
		FOR UPDATE;
		IF existing_request <> request_value THEN
			RAISE EXCEPTION 'exact idempotency conflict' USING ERRCODE = 'DX001';
		END IF;
		IF existing_response IS NULL THEN
			RAISE EXCEPTION 'incomplete exact receipt is not replayable' USING ERRCODE = 'DX002';
		END IF;
		RETURN existing_response;
	END IF;

	IF NOT decodex.is_role_profile_configuration(p_advisor_model, p_advisor_reasoning_effort,
		p_advisor_service_tier, p_advisor_instructions, p_advisor_provenance)
		OR NOT decodex.is_role_profile_configuration(p_lead_model, p_lead_reasoning_effort,
			p_lead_service_tier, p_lead_instructions, p_lead_provenance)
		OR NOT decodex.is_role_profile_configuration(p_task_model, p_task_reasoning_effort,
			p_task_service_tier, p_task_instructions, p_task_provenance)
		OR NOT decodex.is_role_profile_configuration(p_reviewer_model, p_reviewer_reasoning_effort,
			p_reviewer_service_tier, p_reviewer_instructions, p_reviewer_provenance)
	THEN
		RETURN decodex.complete_exact_role_profile_rejection(
			p_protocol, p_idempotency_key, 'invalid_profile'
		);
	END IF;

	LOCK TABLE decodex.role_profiles IN SHARE ROW EXCLUSIVE MODE;
	IF EXISTS (SELECT 1 FROM decodex.role_profiles) THEN
		RETURN decodex.complete_exact_role_profile_rejection(
			p_protocol, p_idempotency_key, 'already_bootstrapped'
		);
	END IF;

	WITH inputs(role, model, reasoning_effort, service_tier, instructions, provenance) AS (
		VALUES
			('advisor'::decodex.role_profile_role, p_advisor_model,
				p_advisor_reasoning_effort, p_advisor_service_tier,
				p_advisor_instructions, p_advisor_provenance),
			('lead'::decodex.role_profile_role, p_lead_model,
				p_lead_reasoning_effort, p_lead_service_tier,
				p_lead_instructions, p_lead_provenance),
			('task'::decodex.role_profile_role, p_task_model,
				p_task_reasoning_effort, p_task_service_tier,
				p_task_instructions, p_task_provenance),
			('reviewer'::decodex.role_profile_role, p_reviewer_model,
				p_reviewer_reasoning_effort, p_reviewer_service_tier,
				p_reviewer_instructions, p_reviewer_provenance)
	), inserted_profiles AS (
		INSERT INTO decodex.role_profiles(role, current_revision)
		SELECT role, 1 FROM inputs ORDER BY role
		RETURNING role, current_revision, created_at, updated_at
	), inserted_revisions AS (
		INSERT INTO decodex.role_profile_revisions(
			role, revision, model, reasoning_effort, service_tier, instructions, provenance
		)
		SELECT input.role, profile.current_revision, input.model, input.reasoning_effort,
			input.service_tier, input.instructions, input.provenance
		FROM inputs AS input JOIN inserted_profiles AS profile USING (role)
		RETURNING role, revision, model, reasoning_effort, service_tier,
			instructions, provenance, created_at
	)
	SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
		'role', revision.role, 'revision', revision.revision,
		'model', revision.model, 'reasoning_effort', revision.reasoning_effort,
		'service_tier', revision.service_tier, 'instructions', revision.instructions,
		'provenance', revision.provenance, 'created_at', revision.created_at,
		'updated_at', profile.updated_at
	) ORDER BY revision.role)
	INTO profiles_value
	FROM inserted_revisions AS revision JOIN inserted_profiles AS profile USING (role);

	FOR profile_value IN SELECT value FROM pg_catalog.jsonb_array_elements(profiles_value)
	LOOP
		activity_payload := profile_value || pg_catalog.jsonb_build_object('kind', 'role_profile');
		INSERT INTO decodex.activity(
			aggregate_kind, aggregate_id, revision, event_kind, correlation_key, payload
		) VALUES (
			'role_profile', profile_value->>'role', (profile_value->>'revision')::bigint,
			'role_profile_bootstrapped', p_idempotency_key, activity_payload
		) RETURNING sequence, payload INTO activity_sequence, activity_payload;

		outbox_payload := pg_catalog.jsonb_build_object(
			'activity_sequence', activity_sequence,
			'event_kind', 'role_profile_bootstrapped', 'aggregate_kind', 'role_profile',
			'aggregate_id', profile_value->>'role',
			'revision', (profile_value->>'revision')::bigint, 'payload', activity_payload
		);
		INSERT INTO decodex.outbox(
			effect_key, aggregate_kind, aggregate_id, aggregate_revision, payload
		) VALUES (
			'activity/' || activity_sequence::text, 'role_profile', profile_value->>'role',
			(profile_value->>'revision')::bigint, outbox_payload
		) RETURNING id, payload INTO outbox_id, outbox_payload;

		effects_value := effects_value || pg_catalog.jsonb_build_array(
			pg_catalog.jsonb_build_object(
				'profile', profile_value, 'activity_sequence', activity_sequence,
				'activity_payload', activity_payload, 'outbox_id', outbox_id,
				'outbox_payload', outbox_payload
			)
		);
	END LOOP;

	effect_value := pg_catalog.jsonb_build_object('profiles', effects_value);
	response_value := pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification', 'success', 'effect', effect_value
	)::text, 'UTF8');
	UPDATE decodex.exact_command_receipts
	SET receipt_state = 'completed_success', outcome_class = 'success',
		effect_envelope = effect_value, response_bytes = response_value,
		completed_at = pg_catalog.clock_timestamp()
	WHERE protocol_version = p_protocol AND idempotency_key = p_idempotency_key;

	RETURN response_value;
END
$_$;


--
-- Name: build_role_profile_bootstrap_request(text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.build_role_profile_bootstrap_request(p_protocol text, p_advisor_model text, p_advisor_reasoning_effort text, p_advisor_service_tier text, p_advisor_instructions text, p_advisor_provenance text, p_lead_model text, p_lead_reasoning_effort text, p_lead_service_tier text, p_lead_instructions text, p_lead_provenance text, p_task_model text, p_task_reasoning_effort text, p_task_service_tier text, p_task_instructions text, p_task_provenance text, p_reviewer_model text, p_reviewer_reasoning_effort text, p_reviewer_service_tier text, p_reviewer_instructions text, p_reviewer_provenance text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF p_protocol IS NULL OR p_advisor_model IS NULL OR p_advisor_reasoning_effort IS NULL
		OR p_advisor_service_tier IS NULL OR p_advisor_instructions IS NULL
		OR p_lead_model IS NULL OR p_lead_reasoning_effort IS NULL
		OR p_lead_service_tier IS NULL OR p_lead_instructions IS NULL
		OR p_task_model IS NULL OR p_task_reasoning_effort IS NULL
		OR p_task_service_tier IS NULL OR p_task_instructions IS NULL
		OR p_reviewer_model IS NULL OR p_reviewer_reasoning_effort IS NULL
		OR p_reviewer_service_tier IS NULL OR p_reviewer_instructions IS NULL
	THEN
		RAISE EXCEPTION 'RoleProfile bootstrap request is incomplete' USING ERRCODE = '22004';
	END IF;

	RETURN pg_catalog.jsonb_build_object(
		'protocol_version', p_protocol, 'operation', 'bootstrap_role_profiles',
		'profiles', pg_catalog.jsonb_build_array(
			pg_catalog.jsonb_build_object('role', 'advisor', 'model', p_advisor_model,
				'reasoning_effort', p_advisor_reasoning_effort, 'service_tier', p_advisor_service_tier,
				'instructions', p_advisor_instructions, 'provenance', p_advisor_provenance),
			pg_catalog.jsonb_build_object('role', 'lead', 'model', p_lead_model,
				'reasoning_effort', p_lead_reasoning_effort, 'service_tier', p_lead_service_tier,
				'instructions', p_lead_instructions, 'provenance', p_lead_provenance),
			pg_catalog.jsonb_build_object('role', 'task', 'model', p_task_model,
				'reasoning_effort', p_task_reasoning_effort, 'service_tier', p_task_service_tier,
				'instructions', p_task_instructions, 'provenance', p_task_provenance),
			pg_catalog.jsonb_build_object('role', 'reviewer', 'model', p_reviewer_model,
				'reasoning_effort', p_reviewer_reasoning_effort, 'service_tier', p_reviewer_service_tier,
				'instructions', p_reviewer_instructions, 'provenance', p_reviewer_provenance)
		)
	);
END
$$;


