--
-- Name: complete_exact_work_item_success(text, text, text, uuid, jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.complete_exact_work_item_success(p_protocol text, p_idempotency_key text, p_event_kind text, p_work_item_id uuid, p_effect jsonb) RETURNS bytea
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE item_value jsonb;
DECLARE activity_sequence bigint;
DECLARE activity_payload jsonb;
DECLARE outbox_id bigint;
DECLARE outbox_payload jsonb;
DECLARE effect_value jsonb;
DECLARE response_value bytea;
BEGIN
	item_value := decodex.work_item_document(p_work_item_id);
	activity_payload := pg_catalog.jsonb_build_object(
		'kind', 'work_item', 'work_item', item_value
	) || p_effect;
	INSERT INTO decodex.activity(
		aggregate_kind, aggregate_id, revision, event_kind, correlation_key, payload
	) VALUES (
		'work_item', p_work_item_id::text, (item_value->>'revision')::bigint,
		p_event_kind, p_idempotency_key, activity_payload
	) RETURNING sequence, payload INTO activity_sequence, activity_payload;
	outbox_payload := pg_catalog.jsonb_build_object(
		'activity_sequence', activity_sequence, 'event_kind', p_event_kind,
		'aggregate_kind', 'work_item', 'aggregate_id', p_work_item_id,
		'revision', (item_value->>'revision')::bigint, 'payload', activity_payload
	);
	INSERT INTO decodex.outbox(
		effect_key, aggregate_kind, aggregate_id, aggregate_revision, payload
	) VALUES (
		'activity/' || activity_sequence::text, 'work_item', p_work_item_id::text,
		(item_value->>'revision')::bigint, outbox_payload
	) RETURNING id, payload INTO outbox_id, outbox_payload;
	effect_value := pg_catalog.jsonb_build_object(
		'work_item', item_value, 'activity_sequence', activity_sequence,
		'activity_payload', activity_payload, 'outbox_id', outbox_id,
		'outbox_payload', outbox_payload
	) || p_effect;
	response_value := pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification', 'success', 'effect', effect_value
	)::text, 'UTF8');
	UPDATE decodex.exact_command_receipts
	SET receipt_state = 'completed_success', outcome_class = 'success',
		effect_envelope = effect_value, response_bytes = response_value,
		completed_at = pg_catalog.clock_timestamp()
	WHERE protocol_version = p_protocol AND idempotency_key = p_idempotency_key;
	RETURN response_value;
END
$$;


--
-- Name: complete_runtime_session_thread_command(text, text, jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.complete_runtime_session_thread_command(p_protocol text, p_idempotency_key text, p_effect jsonb) RETURNS bytea
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE response bytea;
BEGIN
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',p_effect
	)::text,'UTF8');
	UPDATE decodex.exact_command_receipts
	SET receipt_state='completed_success',outcome_class='success',
		effect_envelope=p_effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key
		AND receipt_state='executing';
	IF NOT FOUND THEN
		RAISE EXCEPTION 'exact RuntimeSession thread command lost its receipt'
			USING ERRCODE='55000';
	END IF;
	RETURN response;
END
$$;


--
-- Name: complete_runtime_session_thread_rejection(text, text, text, jsonb, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.complete_runtime_session_thread_rejection(p_protocol text, p_idempotency_key text, p_operation text, p_request jsonb, p_rejection text) RETURNS bytea
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE core jsonb; effect jsonb; response bytea;
BEGIN
	core:=pg_catalog.jsonb_build_object(
		'operation',p_operation,'request',p_request,
		'changed',false,'rejection',p_rejection
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','stable_domain_rejection','effect',effect
	)::text,'UTF8');
	UPDATE decodex.exact_command_receipts
	SET receipt_state='completed_rejected',
		outcome_class='stable_domain_rejection',
		effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key
		AND receipt_state='executing';
	IF NOT FOUND THEN
		RAISE EXCEPTION 'exact RuntimeSession thread command lost its receipt'
			USING ERRCODE='55000';
	END IF;
	RETURN response;
END
$$;


--
-- Name: create_objective(decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, text, text[], text[], bigint, decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.create_objective(p_objective_id decodex.canonical_uuid_v4_text, p_project_id decodex.canonical_uuid_v4_text, p_program_id decodex.canonical_uuid_v4_text, p_outcome text, p_acceptance_criteria text[], p_validation_criteria text[], p_target_at bigint, p_actor_id decodex.canonical_uuid_v4_text, p_correlation_id decodex.canonical_uuid_v4_text, p_provenance text) RETURNS TABLE(result_code text, actual_revision bigint, changed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE canonical_objective_id uuid;
DECLARE canonical_project_id uuid;
DECLARE canonical_program_id uuid;
DECLARE canonical_actor_id uuid;
DECLARE canonical_correlation_id uuid;
DECLARE existing decodex.objectives%ROWTYPE;
DECLARE write_time timestamptz;
DECLARE inserted boolean := false;
BEGIN
	IF p_objective_id IS NULL OR p_project_id IS NULL OR p_actor_id IS NULL
		OR p_correlation_id IS NULL THEN
		RAISE EXCEPTION 'identity ingress requires canonical UUID-v4 text'
			USING ERRCODE = '23514', CONSTRAINT = 'canonical_uuid_v4_text_ingress';
	END IF;
	canonical_objective_id := p_objective_id::text::uuid;
	canonical_project_id := p_project_id::text::uuid;
	canonical_program_id := CASE WHEN p_program_id IS NULL THEN NULL ELSE p_program_id::text::uuid END;
	canonical_actor_id := p_actor_id::text::uuid;
	canonical_correlation_id := p_correlation_id::text::uuid;
	PERFORM 1 FROM decodex.projects AS project JOIN decodex.agents AS lead
		ON lead.project_id=project.project_id AND lead.role='lead'
	WHERE project.project_id=canonical_project_id AND project.status='active'
		AND lead.agent_id=canonical_actor_id AND lead.status='active' FOR KEY SHARE OF project, lead;
	IF NOT FOUND THEN RETURN QUERY SELECT 'invalid_authority', NULL::bigint, false; RETURN; END IF;
	IF canonical_program_id IS NOT NULL AND NOT EXISTS (
		SELECT 1 FROM decodex.programs AS program
		WHERE program.program_id=canonical_program_id AND program.project_id=canonical_project_id
	) THEN RETURN QUERY SELECT 'invalid_program', NULL::bigint, false; RETURN; END IF;
	IF decodex.program_timestamp(p_target_at) IS NULL
		OR decodex.program_timestamp(p_target_at) <= pg_catalog.clock_timestamp()
	THEN RETURN QUERY SELECT 'invalid_horizon', NULL::bigint, false; RETURN; END IF;
	write_time := pg_catalog.clock_timestamp();
	INSERT INTO decodex.objectives (
		objective_id,project_id,program_id,outcome,acceptance_criteria,validation_criteria,
		target_at,last_changed_by,last_correlation_id,last_provenance,created_at,updated_at
	) VALUES (
		canonical_objective_id,canonical_project_id,canonical_program_id,p_outcome,
		p_acceptance_criteria,p_validation_criteria,decodex.program_timestamp(p_target_at),
		canonical_actor_id,
		canonical_correlation_id,p_provenance,write_time,write_time
	) ON CONFLICT DO NOTHING
	RETURNING true INTO inserted;
	IF inserted IS NULL THEN inserted := false; END IF;
	SELECT stored.* INTO existing FROM decodex.objectives AS stored
	WHERE stored.objective_id=canonical_objective_id FOR UPDATE;
	IF existing.project_id=canonical_project_id
		AND existing.program_id IS NOT DISTINCT FROM canonical_program_id
		AND existing.outcome=p_outcome AND existing.acceptance_criteria=p_acceptance_criteria
		AND existing.validation_criteria=p_validation_criteria
		AND existing.target_at=decodex.program_timestamp(p_target_at)
	THEN RETURN QUERY SELECT 'ok', existing.revision, inserted; RETURN; END IF;
	RETURN QUERY SELECT 'conflicting_identity', existing.revision, false;
END
$$;


--
-- Name: create_policy(decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.create_policy(p_policy_id decodex.canonical_uuid_v4_text, p_project_id decodex.canonical_uuid_v4_text) RETURNS TABLE(policy_id uuid, project_id uuid, created_at timestamp with time zone, current_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE canonical_policy_id pg_catalog.uuid;
DECLARE canonical_project_id pg_catalog.uuid;
DECLARE stored_project_id pg_catalog.uuid;
BEGIN
	IF p_policy_id IS NULL OR p_project_id IS NULL THEN
		RAISE EXCEPTION 'identity ingress requires canonical UUID-v4 text'
			USING ERRCODE = '23514', CONSTRAINT = 'canonical_uuid_v4_text_ingress';
	END IF;
	canonical_policy_id := p_policy_id::pg_catalog.text::pg_catalog.uuid;
	canonical_project_id := p_project_id::pg_catalog.text::pg_catalog.uuid;
	PERFORM 1 FROM decodex.projects AS project
		WHERE project.project_id = canonical_project_id FOR KEY SHARE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'Policy requires an authoritative Project'
			USING ERRCODE = '23503', CONSTRAINT = 'policies_project_id_fkey';
	END IF;
	INSERT INTO decodex.policies (policy_id, project_id)
	VALUES (canonical_policy_id, canonical_project_id)
	ON CONFLICT ON CONSTRAINT policies_pkey DO NOTHING;
	SELECT stored.project_id INTO stored_project_id
	FROM decodex.policies AS stored
	WHERE stored.policy_id = canonical_policy_id
	FOR SHARE;
	IF stored_project_id IS DISTINCT FROM canonical_project_id THEN
		RAISE EXCEPTION 'Policy identity is already bound to another Project'
			USING ERRCODE = '23505', CONSTRAINT = 'policies_identity_project';
	END IF;
	RETURN QUERY
	SELECT stored.policy_id, stored.project_id, stored.created_at, stored.current_revision
	FROM decodex.policies AS stored
	WHERE stored.policy_id = canonical_policy_id;
END
$$;


--
-- Name: create_program(decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, text, text, decodex.canonical_uuid_v4_text, bigint, integer, bigint, jsonb, jsonb, decodex.canonical_uuid_v4_text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.create_program(p_program_id decodex.canonical_uuid_v4_text, p_project_id decodex.canonical_uuid_v4_text, p_owner_agent_id decodex.canonical_uuid_v4_text, p_name text, p_responsibility text, p_policy_id decodex.canonical_uuid_v4_text, p_policy_revision bigint, p_review_interval_days integer, p_next_review_at bigint, p_metrics jsonb, p_signals jsonb, p_correlation_id decodex.canonical_uuid_v4_text, p_provenance text) RETURNS TABLE(result_code text, actual_revision bigint, changed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE canonical_program_id uuid;
DECLARE canonical_project_id uuid;
DECLARE canonical_owner_agent_id uuid;
DECLARE canonical_policy_id uuid;
DECLARE canonical_correlation_id uuid;
DECLARE existing decodex.programs%ROWTYPE;
DECLARE write_time timestamptz;
DECLARE inserted boolean := false;
BEGIN
	IF p_program_id IS NULL OR p_project_id IS NULL OR p_owner_agent_id IS NULL
		OR p_policy_id IS NULL OR p_correlation_id IS NULL THEN
		RAISE EXCEPTION 'identity ingress requires canonical UUID-v4 text'
			USING ERRCODE = '23514', CONSTRAINT = 'canonical_uuid_v4_text_ingress';
	END IF;
	canonical_program_id := p_program_id::text::uuid;
	canonical_project_id := p_project_id::text::uuid;
	canonical_owner_agent_id := p_owner_agent_id::text::uuid;
	canonical_policy_id := p_policy_id::text::uuid;
	canonical_correlation_id := p_correlation_id::text::uuid;
	PERFORM 1 FROM decodex.projects AS project
	JOIN decodex.agents AS lead ON lead.project_id=project.project_id AND lead.role='lead'
	WHERE project.project_id=canonical_project_id AND project.status='active'
		AND lead.agent_id=canonical_owner_agent_id AND lead.status='active' FOR KEY SHARE OF project, lead;
	IF NOT FOUND THEN RETURN QUERY SELECT 'invalid_authority', NULL::bigint, false; RETURN; END IF;
	PERFORM 1 FROM decodex.policy_revisions AS revision
	WHERE revision.policy_id=canonical_policy_id AND revision.project_id=canonical_project_id
		AND revision.revision=p_policy_revision FOR KEY SHARE;
	IF NOT FOUND THEN RETURN QUERY SELECT 'invalid_policy', NULL::bigint, false; RETURN; END IF;
	write_time := pg_catalog.clock_timestamp();
	INSERT INTO decodex.programs (
		program_id,project_id,owner_agent_id,name,responsibility,policy_id,policy_revision,
		review_interval_days,next_review_at,metrics,signals,last_changed_by,last_correlation_id,
		last_provenance,created_at,updated_at
	) VALUES (
		canonical_program_id,canonical_project_id,canonical_owner_agent_id,p_name,p_responsibility,
		canonical_policy_id,p_policy_revision,p_review_interval_days,
		decodex.program_timestamp(p_next_review_at),p_metrics,p_signals,
		canonical_owner_agent_id,canonical_correlation_id,p_provenance,
		write_time,write_time
	) ON CONFLICT DO NOTHING
	RETURNING true INTO inserted;
	IF inserted IS NULL THEN inserted := false; END IF;
	SELECT stored.* INTO existing FROM decodex.programs AS stored
	WHERE stored.program_id=canonical_program_id FOR UPDATE;
	IF existing.project_id=canonical_project_id AND existing.owner_agent_id=canonical_owner_agent_id
		AND existing.name=p_name AND existing.responsibility=p_responsibility
		AND existing.policy_id=canonical_policy_id AND existing.policy_revision=p_policy_revision
		AND existing.review_interval_days=p_review_interval_days
		AND existing.next_review_at=decodex.program_timestamp(p_next_review_at)
		AND existing.metrics=p_metrics AND existing.signals=p_signals
	THEN RETURN QUERY SELECT 'ok', existing.revision, inserted; RETURN; END IF;
	RETURN QUERY SELECT 'conflicting_identity', existing.revision, false;
END
$$;


--
-- Name: create_project(decodex.canonical_uuid_v4_text, text, text, text, jsonb, decodex.canonical_uuid_v4_text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.create_project(p_project_id decodex.canonical_uuid_v4_text, p_repository_identity text, p_repository_root text, p_default_cwd text, p_metadata jsonb, p_lead_id decodex.canonical_uuid_v4_text) RETURNS TABLE(project_id uuid, repository_identity text, repository_root text, default_cwd text, project_status decodex.project_status, metadata jsonb, project_revision bigint, agent_id uuid, agent_role decodex.agent_role, agent_status decodex.agent_status, agent_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE canonical_project_id pg_catalog.uuid;
DECLARE canonical_lead_id pg_catalog.uuid;
DECLARE identity_project_id uuid;
DECLARE repository_project_id uuid;
DECLARE selected_project_id uuid;
DECLARE lead_count bigint;
BEGIN
	IF p_project_id IS NULL OR p_lead_id IS NULL THEN
		RAISE EXCEPTION 'identity ingress requires canonical UUID-v4 text'
			USING ERRCODE = '23514', CONSTRAINT = 'canonical_uuid_v4_text_ingress';
	END IF;
	canonical_project_id := p_project_id::pg_catalog.text::pg_catalog.uuid;
	canonical_lead_id := p_lead_id::pg_catalog.text::pg_catalog.uuid;
	PERFORM pg_catalog.pg_advisory_xact_lock(1315, pg_catalog.hashtext(p_repository_identity));
	INSERT INTO decodex.projects (
		project_id, repository_identity, repository_root, default_cwd, metadata
	) VALUES (
		canonical_project_id, p_repository_identity, p_repository_root, p_default_cwd, p_metadata
	) ON CONFLICT DO NOTHING;

	SELECT stored.project_id INTO identity_project_id
	FROM decodex.projects AS stored
	WHERE stored.project_id = canonical_project_id;
	SELECT stored.project_id INTO repository_project_id
	FROM decodex.projects AS stored
	WHERE stored.repository_identity = p_repository_identity;

	IF identity_project_id IS NOT NULL AND identity_project_id = repository_project_id THEN
		selected_project_id := identity_project_id;
	ELSIF identity_project_id IS NULL AND repository_project_id IS NOT NULL THEN
		selected_project_id := repository_project_id;
	ELSE
		RAISE EXCEPTION 'Project and repository identities are already bound differently'
			USING ERRCODE = '23505', CONSTRAINT = 'projects_identity_pair';
	END IF;

	IF selected_project_id = canonical_project_id THEN
		INSERT INTO decodex.agents (agent_id, role, project_id)
		VALUES (canonical_lead_id, 'lead', selected_project_id)
		ON CONFLICT DO NOTHING;
	END IF;
	SELECT count(*) INTO lead_count
	FROM decodex.agents AS lead
	WHERE lead.project_id = selected_project_id AND lead.role = 'lead';
	IF lead_count <> 1 THEN
		RAISE EXCEPTION 'Project requires exactly one canonical Lead'
			USING ERRCODE = '23514', CONSTRAINT = 'project_canonical_lead';
	END IF;

	RETURN QUERY
	SELECT project.project_id, project.repository_identity, project.repository_root,
		project.default_cwd, project.status, project.metadata, project.revision,
		lead.agent_id, lead.role, lead.status, lead.revision
	FROM decodex.projects AS project
	JOIN decodex.agents AS lead ON lead.project_id = project.project_id AND lead.role = 'lead'
	WHERE project.project_id = selected_project_id;
END
$$;


--
-- Name: create_runtime_session_exact(text, text, uuid, uuid, decodex.role_profile_role, uuid, uuid, text, decodex.account_state, bigint, uuid, decodex.runtime_session_state); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.create_runtime_session_exact(p_protocol text, p_idempotency_key text, p_session_id uuid, p_conversation_id uuid, p_role decodex.role_profile_role, p_account_snapshot_id uuid, p_source_account_id uuid, p_display_label text, p_observed_state decodex.account_state, p_account_source_revision bigint, p_codex_thread_id uuid, p_initial_state decodex.runtime_session_state) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request_value jsonb;
DECLARE existing_request jsonb;
DECLARE existing_response bytea;
DECLARE inserted_count integer;
DECLARE conversation_status decodex.conversation_status;
DECLARE identity_lock bigint;
DECLARE thread_lock bigint;
DECLARE created_profile_snapshot_id uuid;
DECLARE profile_value jsonb;
DECLARE account_value jsonb;
DECLARE session_value jsonb;
DECLARE activity_sequence bigint;
DECLARE activity_aggregate_kind text;
DECLARE activity_aggregate_id text;
DECLARE activity_revision bigint;
DECLARE activity_event_kind text;
DECLARE activity_payload jsonb;
DECLARE outbox_id bigint;
DECLARE outbox_effect_key text;
DECLARE outbox_aggregate_kind text;
DECLARE outbox_aggregate_id text;
DECLARE outbox_aggregate_revision bigint;
DECLARE outbox_payload jsonb;
DECLARE effect_value jsonb;
DECLARE response_value bytea;
BEGIN
	IF p_protocol IS NULL OR p_idempotency_key IS NULL OR p_session_id IS NULL
		OR p_conversation_id IS NULL OR p_role IS NULL OR p_account_snapshot_id IS NULL
		OR p_source_account_id IS NULL OR p_display_label IS NULL
		OR p_observed_state IS NULL OR p_account_source_revision IS NULL
		OR p_initial_state IS NULL
	THEN
		RAISE EXCEPTION 'exact RuntimeSession creation is incomplete' USING ERRCODE = '22004';
	END IF;
	IF pg_catalog.octet_length(p_protocol) NOT BETWEEN 1 AND 64
		OR p_protocol COLLATE pg_catalog."C" !~ '^[a-z0-9][a-z0-9._/-]{0,63}$'
		OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 256
		OR decodex.has_credential_material(p_idempotency_key)
	THEN
		RAISE EXCEPTION 'exact RuntimeSession command identity is invalid' USING ERRCODE = '22023';
	END IF;

	request_value := decodex.build_runtime_session_create_request(
		p_protocol, p_session_id, p_conversation_id, p_role,
		p_account_snapshot_id, p_source_account_id, p_display_label,
		p_observed_state, p_account_source_revision, p_codex_thread_id, p_initial_state
	);
	INSERT INTO decodex.exact_command_receipts(
		protocol_version, idempotency_key, request_envelope, request_digest, receipt_state
	) VALUES (
		p_protocol, p_idempotency_key, request_value,
		public.digest(pg_catalog.convert_to(request_value::text, 'UTF8'), 'sha256'), 'executing'
	) ON CONFLICT (protocol_version, idempotency_key) DO NOTHING;
	GET DIAGNOSTICS inserted_count = ROW_COUNT;

	IF inserted_count = 0 THEN
		SELECT request_envelope, response_bytes INTO existing_request, existing_response
		FROM decodex.exact_command_receipts
		WHERE protocol_version = p_protocol AND idempotency_key = p_idempotency_key
		FOR UPDATE;
		IF existing_request <> request_value THEN
			RAISE EXCEPTION 'exact idempotency conflict' USING ERRCODE = 'DX001';
		END IF;
		IF existing_response IS NULL THEN
			RAISE EXCEPTION 'incomplete exact receipt is not replayable' USING ERRCODE = 'DX002';
		END IF;
		RETURN existing_response;
	END IF;

	IF p_initial_state NOT IN ('starting', 'active') THEN
		RETURN decodex.complete_exact_runtime_session_rejection(
			p_protocol, p_idempotency_key, 'illegal_transition'
		);
	END IF;
	IF p_account_source_revision < 1
		OR pg_catalog.octet_length(p_display_label) NOT BETWEEN 1 AND 128
		OR decodex.has_credential_material(p_display_label)
	THEN
		RETURN decodex.complete_exact_runtime_session_rejection(
			p_protocol, p_idempotency_key, 'invalid_account_snapshot'
		);
	END IF;

	-- Match the statement-level hierarchy trigger order: acquire the outer coordinator
	-- before selecting or locking a Conversation or RuntimeSession tuple.
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);

	-- The row lock is both the Conversation eligibility proof and the canonical create order.
	SELECT status INTO conversation_status FROM decodex.conversations
	WHERE conversation_id = p_conversation_id FOR UPDATE;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_runtime_session_rejection(
			p_protocol, p_idempotency_key, 'missing_target'
		);
	END IF;
	IF conversation_status <> 'open' THEN
		RETURN decodex.complete_exact_runtime_session_rejection(
			p_protocol, p_idempotency_key, 'illegal_transition'
		);
	END IF;

	-- Serialize both unique RuntimeSession identities in canonical order even when
	-- hostile callers name different Conversations. Hash collisions only add safe
	-- serialization; they cannot weaken uniqueness or rejection classification.
	identity_lock := pg_catalog.hashtextextended(
		'runtime_session/id/' || p_session_id::text, 0
	);
	thread_lock := CASE WHEN p_codex_thread_id IS NULL THEN identity_lock ELSE
		pg_catalog.hashtextextended('runtime_session/thread/' || p_codex_thread_id::text, 0)
	END;
	PERFORM pg_catalog.pg_advisory_xact_lock(
		CASE WHEN identity_lock <= thread_lock THEN identity_lock ELSE thread_lock END
	);
	IF thread_lock <> identity_lock THEN
		PERFORM pg_catalog.pg_advisory_xact_lock(
			CASE WHEN identity_lock > thread_lock THEN identity_lock ELSE thread_lock END
		);
	END IF;
	IF EXISTS (
		SELECT 1 FROM decodex.runtime_sessions
		WHERE runtime_session_id = p_session_id
			OR (p_codex_thread_id IS NOT NULL AND codex_thread_id = p_codex_thread_id)
	) THEN
		RETURN decodex.complete_exact_runtime_session_rejection(
			p_protocol, p_idempotency_key, 'duplicate_target'
		);
	END IF;

	-- FOR SHARE prevents a concurrent profile advance until the complete selected
	-- revision has been copied, yielding either the old or new immutable revision.
	SELECT pg_catalog.jsonb_build_object(
		'role', revision.role, 'revision', revision.revision,
		'model', revision.model, 'reasoning_effort', revision.reasoning_effort,
		'service_tier', revision.service_tier, 'instructions', revision.instructions,
		'provenance', revision.provenance, 'created_at', revision.created_at
	) INTO profile_value
	FROM decodex.role_profiles AS profile
	JOIN decodex.role_profile_revisions AS revision
		ON (revision.role, revision.revision) = (profile.role, profile.current_revision)
	WHERE profile.role = p_role
	FOR SHARE OF profile;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_runtime_session_rejection(
			p_protocol, p_idempotency_key, 'missing_target'
		);
	END IF;

	INSERT INTO decodex.account_snapshots(
		account_snapshot_id, source_account_id, display_label, observed_state, source_revision
	) VALUES (
		p_account_snapshot_id, p_source_account_id, p_display_label,
		p_observed_state, p_account_source_revision
	) ON CONFLICT (account_snapshot_id) DO NOTHING;
	SELECT pg_catalog.jsonb_build_object(
		'account_snapshot_id', account_snapshot_id,
		'source_account_id', source_account_id, 'display_label', display_label,
		'observed_state', observed_state, 'source_revision', source_revision,
		'created_at', created_at
	) INTO account_value
	FROM decodex.account_snapshots WHERE account_snapshot_id = p_account_snapshot_id;
	IF account_value->>'source_account_id' <> p_source_account_id::text
		OR account_value->>'display_label' <> p_display_label
		OR account_value->>'observed_state' <> p_observed_state::text
		OR (account_value->>'source_revision')::bigint <> p_account_source_revision
	THEN
		RETURN decodex.complete_exact_runtime_session_rejection(
			p_protocol, p_idempotency_key, 'account_snapshot_conflict'
		);
	END IF;

	created_profile_snapshot_id := pg_catalog.gen_random_uuid();
	INSERT INTO decodex.profile_snapshots(
		profile_snapshot_id, source_profile_id, role, model, reasoning_effort,
		service_tier, instructions_digest, instructions, provenance, source_revision
	) VALUES (
		created_profile_snapshot_id, profile_value->>'role', p_role,
		profile_value->>'model', profile_value->>'reasoning_effort',
		profile_value->>'service_tier',
		pg_catalog.encode(public.digest(
			pg_catalog.convert_to(profile_value->>'instructions', 'UTF8'), 'sha256'
		), 'hex'), profile_value->>'instructions', profile_value->>'provenance',
		(profile_value->>'revision')::bigint
	) RETURNING pg_catalog.jsonb_build_object(
		'profile_snapshot_id', profile_snapshot_id,
		'source_profile_id', source_profile_id, 'role', role,
		'model', model, 'reasoning_effort', reasoning_effort,
		'service_tier', service_tier, 'instructions_digest', instructions_digest,
		'instructions', instructions, 'provenance', provenance,
		'source_revision', source_revision, 'created_at', created_at
	) INTO profile_value;

	INSERT INTO decodex.runtime_sessions(
		runtime_session_id, conversation_id, profile_snapshot_id,
		account_snapshot_id, codex_thread_id, state, last_known_turn_id
	) VALUES (
		p_session_id, p_conversation_id, created_profile_snapshot_id,
		p_account_snapshot_id, p_codex_thread_id, p_initial_state, NULL
	) RETURNING pg_catalog.jsonb_build_object(
		'runtime_session_id', runtime_session_id, 'conversation_id', conversation_id,
		'profile_snapshot_id', profile_snapshot_id,
		'account_snapshot_id', account_snapshot_id,
		'codex_thread_id', codex_thread_id, 'last_known_turn_id', last_known_turn_id,
		'state', state, 'revision', revision, 'created_at', created_at,
		'updated_at', updated_at, 'ended_at', ended_at
	) INTO session_value;

	activity_payload := pg_catalog.jsonb_build_object(
		'kind', 'runtime_session', 'runtime_session_snapshot', session_value,
		'profile_snapshot', profile_value, 'account_snapshot', account_value
	);
	INSERT INTO decodex.activity(
		aggregate_kind, aggregate_id, revision, event_kind, correlation_key, payload
	) VALUES (
		'runtime_session', p_session_id::text, 1, 'runtime_session_created',
		p_idempotency_key, activity_payload
	) RETURNING sequence, aggregate_kind, aggregate_id, revision, event_kind, payload
	INTO activity_sequence, activity_aggregate_kind, activity_aggregate_id,
		activity_revision, activity_event_kind, activity_payload;
	outbox_payload := pg_catalog.jsonb_build_object(
		'activity_sequence', activity_sequence, 'event_kind', 'runtime_session_created',
		'aggregate_kind', 'runtime_session', 'aggregate_id', p_session_id,
		'revision', 1, 'payload', activity_payload
	);
	INSERT INTO decodex.outbox(
		effect_key, aggregate_kind, aggregate_id, aggregate_revision, payload
	) VALUES (
		'activity/' || activity_sequence::text, 'runtime_session', p_session_id::text,
		1, outbox_payload
	) RETURNING id, effect_key, aggregate_kind, aggregate_id, aggregate_revision, payload
	INTO outbox_id, outbox_effect_key, outbox_aggregate_kind,
		outbox_aggregate_id, outbox_aggregate_revision, outbox_payload;

	effect_value := pg_catalog.jsonb_build_object(
		'request', request_value,
		'runtime_session_snapshot', session_value, 'profile_snapshot', profile_value,
		'account_snapshot', account_value, 'prior_state', NULL,
		'new_state', p_initial_state, 'prior_revision', NULL, 'new_revision', 1,
		'activity_sequence', activity_sequence,
		'activity_aggregate_kind', activity_aggregate_kind,
		'activity_aggregate_id', activity_aggregate_id,
		'activity_revision', activity_revision,
		'activity_event_kind', activity_event_kind,
		'activity_payload', activity_payload,
		'outbox_id', outbox_id, 'outbox_effect_key', outbox_effect_key,
		'outbox_aggregate_kind', outbox_aggregate_kind,
		'outbox_aggregate_id', outbox_aggregate_id,
		'outbox_aggregate_revision', outbox_aggregate_revision,
		'outbox_payload', outbox_payload
	);
	response_value := pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification', 'success', 'effect', effect_value
	)::text, 'UTF8');
	UPDATE decodex.exact_command_receipts
	SET receipt_state = 'completed_success', outcome_class = 'success',
		effect_envelope = effect_value, response_bytes = response_value,
		completed_at = pg_catalog.clock_timestamp()
	WHERE protocol_version = p_protocol AND idempotency_key = p_idempotency_key;

	RETURN response_value;
END
$_$;


--
-- Name: create_work_item_exact(text, text, uuid, uuid, uuid, uuid, uuid[], uuid[], uuid[], text, text, decodex.work_item_priority, text[], text[], uuid, uuid, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.create_work_item_exact(p_protocol text, p_idempotency_key text, p_work_item_id uuid, p_project_id uuid, p_lead_agent_id uuid, p_program_id uuid, p_objective_ids uuid[], p_depends_on_ids uuid[], p_blocked_by_ids uuid[], p_title text, p_description text, p_priority decodex.work_item_priority, p_acceptance_criteria text[], p_validation_criteria text[], p_actor_id uuid, p_correlation_id uuid, p_provenance text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request_value jsonb;
DECLARE replay bytea;
DECLARE project_ok boolean;
DECLARE invalid_count bigint;
DECLARE operation_time timestamptz := pg_catalog.clock_timestamp();
BEGIN
	request_value := pg_catalog.jsonb_build_object(
		'protocol_version',p_protocol,'operation','create_work_item','work_item_id',p_work_item_id,
		'project_id',p_project_id,'lead_agent_id',p_lead_agent_id,'program_id',p_program_id,
		'objective_ids',p_objective_ids,'depends_on_ids',p_depends_on_ids,
		'blocked_by_ids',p_blocked_by_ids,'title',p_title,'description',p_description,
		'priority',p_priority,'acceptance_criteria',p_acceptance_criteria,
		'validation_criteria',p_validation_criteria,'actor_id',p_actor_id,
		'correlation_id',p_correlation_id,'provenance',p_provenance
	);
	replay := decodex.reserve_exact_work_item_command(p_protocol,p_idempotency_key,request_value);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	IF p_work_item_id IS NULL OR p_project_id IS NULL OR p_lead_agent_id IS NULL
		OR p_objective_ids IS NULL OR p_depends_on_ids IS NULL OR p_blocked_by_ids IS NULL
		OR p_title IS NULL OR p_description IS NULL OR p_priority IS NULL
		OR p_acceptance_criteria IS NULL OR p_validation_criteria IS NULL
		OR p_actor_id IS NULL OR p_correlation_id IS NULL OR p_provenance IS NULL
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_input'); END IF;
	IF NOT decodex.is_work_item_text(p_title,256)
		OR NOT decodex.is_work_item_text(p_description,4096)
		OR NOT decodex.is_work_item_text(p_provenance,4096)
		OR NOT decodex.is_work_item_criteria(p_acceptance_criteria)
		OR NOT decodex.is_work_item_criteria(p_validation_criteria)
		OR pg_catalog.cardinality(p_objective_ids) > 32
		OR pg_catalog.cardinality(p_depends_on_ids) + pg_catalog.cardinality(p_blocked_by_ids) > 256
		OR COALESCE(pg_catalog.array_ndims(p_objective_ids),1) <> 1
		OR COALESCE(pg_catalog.array_ndims(p_depends_on_ids),1) <> 1
		OR COALESCE(pg_catalog.array_ndims(p_blocked_by_ids),1) <> 1
		OR pg_catalog.array_position(p_objective_ids,NULL) IS NOT NULL
		OR pg_catalog.array_position(p_depends_on_ids,NULL) IS NOT NULL
		OR pg_catalog.array_position(p_blocked_by_ids,NULL) IS NOT NULL
		OR p_work_item_id = ANY(p_depends_on_ids) OR p_work_item_id = ANY(p_blocked_by_ids)
		OR p_work_item_id::text COLLATE pg_catalog."C" !~
			'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
		OR p_correlation_id::text COLLATE pg_catalog."C" !~
			'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_input'); END IF;
	IF (SELECT pg_catalog.count(*) FROM pg_catalog.unnest(p_objective_ids) value)
		<> (SELECT pg_catalog.count(DISTINCT value) FROM pg_catalog.unnest(p_objective_ids) value)
		OR (SELECT pg_catalog.count(*) FROM pg_catalog.unnest(p_depends_on_ids || p_blocked_by_ids) value)
		<> (SELECT pg_catalog.count(DISTINCT value) FROM pg_catalog.unnest(p_depends_on_ids || p_blocked_by_ids) value)
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'duplicate_relation'); END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1343,pg_catalog.hashtext(p_project_id::text));
	PERFORM pg_catalog.pg_advisory_xact_lock(1344,pg_catalog.hashtext(p_work_item_id::text));
	IF EXISTS (SELECT 1 FROM decodex.work_items WHERE work_item_id=p_work_item_id) THEN
		RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'duplicate_target'); END IF;
	IF (SELECT pg_catalog.count(*) FROM decodex.work_items WHERE project_id=p_project_id) >= 4096
		OR (SELECT pg_catalog.count(*) FROM decodex.work_item_edges WHERE project_id=p_project_id)
			+ pg_catalog.cardinality(p_depends_on_ids) + pg_catalog.cardinality(p_blocked_by_ids) > 16384
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_input'); END IF;
	IF EXISTS (SELECT 1 FROM pg_catalog.unnest(p_objective_ids) id LEFT JOIN decodex.objectives objective
		ON objective.objective_id=id AND objective.project_id=p_project_id WHERE objective.objective_id IS NULL)
		OR (p_program_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM decodex.programs
			WHERE program_id=p_program_id AND project_id=p_project_id))
		OR EXISTS (SELECT 1 FROM pg_catalog.unnest(p_depends_on_ids||p_blocked_by_ids) id
			LEFT JOIN decodex.work_items related ON related.work_item_id=id AND related.project_id=p_project_id
			WHERE related.work_item_id IS NULL)
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_relation'); END IF;
	PERFORM 1 FROM decodex.programs WHERE program_id=p_program_id FOR SHARE;
	PERFORM 1 FROM decodex.objectives WHERE objective_id=ANY(p_objective_ids)
		ORDER BY objective_id FOR SHARE;
	PERFORM 1 FROM decodex.work_items WHERE work_item_id=ANY(p_depends_on_ids||p_blocked_by_ids)
		ORDER BY work_item_id FOR SHARE;
	SELECT project.status = 'active' AND lead.role = 'lead' AND lead.status = 'active'
		AND lead.project_id = project.project_id AND lead.agent_id = p_lead_agent_id
		AND p_actor_id = lead.agent_id INTO project_ok
	FROM decodex.projects AS project JOIN decodex.agents AS lead ON lead.project_id=project.project_id
		AND lead.role='lead' WHERE project.project_id=p_project_id FOR SHARE OF project,lead;
	IF project_ok IS DISTINCT FROM true THEN
		RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_authority'); END IF;
	SELECT pg_catalog.count(*) INTO invalid_count FROM pg_catalog.unnest(p_objective_ids) id
	LEFT JOIN decodex.objectives objective ON objective.objective_id=id AND objective.project_id=p_project_id
	WHERE objective.objective_id IS NULL;
	IF invalid_count > 0 OR (p_program_id IS NOT NULL AND NOT EXISTS (
		SELECT 1 FROM decodex.programs WHERE program_id=p_program_id AND project_id=p_project_id
	)) OR EXISTS (
		SELECT 1 FROM pg_catalog.unnest(p_depends_on_ids || p_blocked_by_ids) id
		LEFT JOIN decodex.work_items related ON related.work_item_id=id AND related.project_id=p_project_id
		WHERE related.work_item_id IS NULL
	) THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_relation'); END IF;
	INSERT INTO decodex.work_items(work_item_id,project_id,lead_agent_id,program_id,title,
		description,priority,acceptance_criteria,validation_criteria,last_changed_by,
		last_correlation_id,last_provenance,created_at,updated_at)
	VALUES(p_work_item_id,p_project_id,p_lead_agent_id,p_program_id,p_title,p_description,
		p_priority,p_acceptance_criteria,p_validation_criteria,p_actor_id,p_correlation_id,
		p_provenance,operation_time,operation_time);
	INSERT INTO decodex.work_item_objectives(project_id,work_item_id,objective_id)
	SELECT p_project_id,p_work_item_id,id FROM pg_catalog.unnest(p_objective_ids) id ORDER BY id;
	INSERT INTO decodex.work_item_edges(project_id,work_item_id,related_work_item_id,kind)
	SELECT p_project_id,p_work_item_id,id,'depends_on'::decodex.work_item_edge_kind
	FROM pg_catalog.unnest(p_depends_on_ids) id
	UNION ALL SELECT p_project_id,p_work_item_id,id,'blocked_by'::decodex.work_item_edge_kind
	FROM pg_catalog.unnest(p_blocked_by_ids) id ORDER BY 3;
	RETURN decodex.complete_exact_work_item_success(p_protocol,p_idempotency_key,
		'work_item_created',p_work_item_id,pg_catalog.jsonb_build_object('request',request_value));
END
$_$;


--
-- Name: enforce_artifact_revision_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_artifact_revision_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE parent_status decodex.conversation_status;
DECLARE artifact_state decodex.artifact_status;
DECLARE artifact_revision bigint;
DECLARE predecessor_status decodex.artifact_status;
BEGIN
	SELECT c.status, a.status, a.revision INTO parent_status, artifact_state, artifact_revision
		FROM decodex.conversations c JOIN decodex.artifacts a
		ON a.conversation_id = c.conversation_id
		WHERE (a.artifact_id, a.conversation_id) = (NEW.artifact_id, NEW.conversation_id)
		FOR UPDATE OF c, a;
	IF parent_status <> 'open' OR NEW.status <> artifact_state
		OR NEW.revision <> artifact_revision THEN
		RAISE EXCEPTION 'Artifact revision requires eligible matching parents';
	END IF;
	IF NEW.revision = 1 THEN
		IF NEW.status <> 'active' THEN
			RAISE EXCEPTION 'initial Artifact revision must be active';
		END IF;
	ELSE
		SELECT status INTO predecessor_status FROM decodex.artifact_revisions
			WHERE (artifact_id, conversation_id, revision) =
				(NEW.artifact_id, NEW.conversation_id, NEW.revision - 1);
		IF predecessor_status IS NULL
			OR NOT ((predecessor_status = 'active' AND NEW.status IN ('expired', 'deleted'))
				OR (predecessor_status = 'expired' AND NEW.status = 'deleted')) THEN
			RAISE EXCEPTION 'Artifact revision requires its exact legal immutable predecessor';
		END IF;
	END IF;
	NEW.created_at := pg_catalog.clock_timestamp();
	RETURN NEW;
END;
$$;


--
-- Name: enforce_artifact_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_artifact_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE parent_status decodex.conversation_status;
DECLARE predecessor_status decodex.artifact_status;
BEGIN
	SELECT status INTO parent_status FROM decodex.conversations
		WHERE conversation_id = NEW.conversation_id FOR UPDATE;
	IF parent_status <> 'open' THEN RAISE EXCEPTION 'artifact requires open conversation'; END IF;
	IF TG_OP = 'INSERT' THEN
		IF NEW.status <> 'active' OR NEW.revision <> 1 THEN RAISE EXCEPTION 'illegal initial artifact state'; END IF;
		NEW.created_at := pg_catalog.clock_timestamp();
		NEW.updated_at := NEW.created_at;
		RETURN NEW;
	END IF;
	IF OLD.status = 'deleted' THEN RAISE EXCEPTION 'deleted artifact is immutable'; END IF;
	SELECT status INTO predecessor_status FROM decodex.artifact_revisions
		WHERE (artifact_id, conversation_id, revision) =
			(OLD.artifact_id, OLD.conversation_id, OLD.revision);
	IF predecessor_status IS DISTINCT FROM OLD.status THEN
		RAISE EXCEPTION 'Artifact advance requires its exact immutable current revision';
	END IF;
	IF NEW.artifact_id <> OLD.artifact_id OR NEW.conversation_id <> OLD.conversation_id
		OR NEW.created_at IS DISTINCT FROM OLD.created_at
		OR NEW.revision <> OLD.revision + 1
		OR NOT ((OLD.status = 'active' AND NEW.status IN ('expired', 'deleted'))
			OR (OLD.status = 'expired' AND NEW.status = 'deleted')) THEN
		RAISE EXCEPTION 'illegal artifact transition';
	END IF;
	NEW.updated_at := pg_catalog.clock_timestamp();
	RETURN NEW;
END;
$$;


--
-- Name: enforce_blob_object_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_blob_object_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	NEW.created_at := pg_catalog.clock_timestamp();
	NEW.verified_at := NEW.created_at;
	RETURN NEW;
END;
$$;


--
-- Name: enforce_codex_experiment_command_owner(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_codex_experiment_command_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE owner_name name;
BEGIN
	SELECT role.rolname INTO owner_name
	FROM pg_catalog.pg_class AS class
	JOIN pg_catalog.pg_roles AS role ON role.oid=class.relowner
	WHERE class.oid=TG_RELID;
	IF current_user::name <> owner_name THEN
		RAISE EXCEPTION 'V15 Codex experiment state is writable only by its command owner'
			USING ERRCODE='42501', CONSTRAINT='codex_experiment_command_owner';
	END IF;
	IF TG_OP='DELETE' OR TG_OP='TRUNCATE' THEN
		RAISE EXCEPTION 'V15 Codex experiment state is retained'
			USING ERRCODE='55000', CONSTRAINT='codex_experiment_history_retained';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: enforce_command_receipt_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_command_receipt_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE write_time timestamptz := pg_catalog.clock_timestamp();
BEGIN
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'command receipts are durable and cannot be deleted'
			USING ERRCODE = '55000', CONSTRAINT = 'command_receipts_durable';
	END IF;
	IF TG_OP = 'INSERT' THEN
		IF NEW.created_at > write_time
			OR NEW.created_at < write_time - interval '1 minute'
			OR (NEW.receipt_state = 'pending' AND (
				NEW.claim_expires_at <= write_time
				OR NEW.claim_expires_at > write_time + interval '5 minutes'
			))
			OR NEW.receipt_state = 'completed' THEN
			RAISE EXCEPTION 'new command receipts must be canonical pending reservations'
				USING ERRCODE = '23514', CONSTRAINT = 'command_receipts_canonical_insert';
		END IF;
		RETURN NEW;
	END IF;
	IF NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
		OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
		OR NEW.protocol_version IS DISTINCT FROM OLD.protocol_version
		OR NEW.operation IS DISTINCT FROM OLD.operation
		OR NEW.project_scope IS DISTINCT FROM OLD.project_scope
		OR NEW.scope_id IS DISTINCT FROM OLD.scope_id
		OR NEW.entity_id IS DISTINCT FROM OLD.entity_id
		OR NEW.expected_revision IS DISTINCT FROM OLD.expected_revision
		OR NEW.payload_hash IS DISTINCT FROM OLD.payload_hash
		OR NEW.payload_length IS DISTINCT FROM OLD.payload_length
		OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
		RAISE EXCEPTION 'command receipt request identity is immutable'
			USING ERRCODE = '55000', CONSTRAINT = 'command_receipts_identity_immutable';
	END IF;
	IF OLD.receipt_state = 'completed' THEN
		RAISE EXCEPTION 'completed command receipts are immutable'
			USING ERRCODE = '55000', CONSTRAINT = 'command_receipts_completed_immutable';
	END IF;
	IF NEW.receipt_state = 'pending' THEN
		IF OLD.claim_expires_at > write_time
			OR NEW.claim_token IS NOT DISTINCT FROM OLD.claim_token
			OR NEW.claim_expires_at <= write_time
			OR NEW.claim_expires_at > write_time + interval '5 minutes' THEN
			RAISE EXCEPTION 'pending command claim can rotate only after expiry'
				USING ERRCODE = '55000', CONSTRAINT = 'command_receipts_claim_fence';
		END IF;
	ELSIF NEW.receipt_state = 'completed' THEN
		IF NEW.completion_claim_token IS DISTINCT FROM OLD.claim_token
			OR OLD.claim_expires_at <= write_time
			OR NEW.completed_at > write_time
			OR NEW.completed_at < write_time - interval '1 minute' THEN
			RAISE EXCEPTION 'command completion lost its live claim fence'
				USING ERRCODE = '55000', CONSTRAINT = 'command_receipts_completion_fence';
		END IF;
	END IF;
	RETURN NEW;
END;
$$;


--
-- Name: enforce_complete_role_profile_set(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_complete_role_profile_set() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE profile_count bigint;
BEGIN
	SELECT pg_catalog.count(*) INTO profile_count FROM decodex.role_profiles;

	IF profile_count NOT IN (0, 4)
		OR (profile_count = 4 AND EXISTS (
			SELECT expected.role
			FROM (VALUES
				('advisor'::decodex.role_profile_role), ('lead'::decodex.role_profile_role),
				('task'::decodex.role_profile_role), ('reviewer'::decodex.role_profile_role)
			) AS expected(role)
			EXCEPT SELECT role FROM decodex.role_profiles
		))
	THEN
		RAISE EXCEPTION 'RoleProfiles must contain exactly the four global roles'
			USING ERRCODE = '23514', CONSTRAINT = 'role_profiles_exact_global_set';
	END IF;

	RETURN NULL;
END
$$;


--
-- Name: enforce_context_pack_source_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_context_pack_source_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE artifact_state decodex.artifact_status;
DECLARE conversation_state decodex.conversation_status;
DECLARE pack_exists boolean;
BEGIN
	IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Context Pack source is immutable'; END IF;
	SELECT EXISTS (
		SELECT 1 FROM decodex.context_packs
		WHERE (context_pack_id, conversation_id) = (NEW.context_pack_id, NEW.conversation_id)
	) INTO pack_exists;
	IF pack_exists THEN RAISE EXCEPTION 'Context Pack source manifest is sealed'; END IF;
	SELECT status INTO conversation_state FROM decodex.conversations
		WHERE conversation_id = NEW.conversation_id FOR UPDATE;
	IF conversation_state <> 'open' THEN
		RAISE EXCEPTION 'Context Pack source requires open Conversation';
	END IF;
	IF NEW.kind = 'artifact' THEN
		SELECT status INTO artifact_state FROM decodex.artifacts
			WHERE (artifact_id, conversation_id) = (NEW.artifact_id, NEW.conversation_id)
			FOR UPDATE;
		IF artifact_state <> 'active' THEN
			RAISE EXCEPTION 'Context Pack Artifact source requires active Artifact';
		END IF;
	END IF;
	RETURN NEW;
END;
$$;


--
-- Name: enforce_context_pack_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_context_pack_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE parent_status decodex.conversation_status;
DECLARE actual_source_count bigint;
DECLARE first_position integer;
DECLARE last_position integer;
BEGIN
	IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Context Pack is immutable'; END IF;
	SELECT status INTO parent_status FROM decodex.conversations
		WHERE conversation_id = NEW.conversation_id FOR UPDATE;
	IF parent_status <> 'open' THEN RAISE EXCEPTION 'Context Pack requires open conversation'; END IF;
	SELECT count(*), min(position), max(position)
		INTO actual_source_count, first_position, last_position
		FROM decodex.context_pack_sources
		WHERE (context_pack_id, conversation_id) = (NEW.context_pack_id, NEW.conversation_id);
	IF actual_source_count <> NEW.source_count OR first_position <> 0
		OR last_position <> NEW.source_count - 1 THEN
		RAISE EXCEPTION 'Context Pack requires one exact contiguous source manifest';
	END IF;
	NEW.created_at := pg_catalog.clock_timestamp();
	RETURN NEW;
END;
$$;


--
-- Name: enforce_continuation_event_namespace(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_continuation_event_namespace() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE owner_name name; linked boolean;
BEGIN
	SELECT role.rolname INTO owner_name FROM pg_catalog.pg_class AS class
	JOIN pg_catalog.pg_roles AS role ON role.oid=class.relowner WHERE class.oid=TG_RELID;
	IF TG_TABLE_NAME='activity' THEN
		linked:=NEW.aggregate_kind='continuation_plan'
			OR NEW.event_kind IN (
				'continuation_plan_created','initial_quick_task_turn_admitted'
			)
			OR NEW.payload->>'kind'='initial_quick_task_turn_admission'
			OR pg_catalog.jsonb_path_exists(NEW.payload,'$.** ? (
				exists(@.continuation_plan_id) || exists(@.routing_decision_id) ||
				exists(@.fallback_context_pack_id) || exists(@.fallback_runtime_session_id)
			)');
		IF TG_OP='UPDATE' THEN
			linked:=linked OR OLD.aggregate_kind='continuation_plan'
				OR OLD.event_kind IN (
					'continuation_plan_created','initial_quick_task_turn_admitted'
				)
				OR OLD.payload->>'kind'='initial_quick_task_turn_admission'
				OR pg_catalog.jsonb_path_exists(OLD.payload,'$.** ? (
					exists(@.continuation_plan_id) || exists(@.routing_decision_id) ||
					exists(@.fallback_context_pack_id) || exists(@.fallback_runtime_session_id)
				)');
		END IF;
		IF linked AND current_user::name<>owner_name THEN
			RAISE EXCEPTION 'continuation activity/outbox namespace is command-owned'
				USING ERRCODE='42501', CONSTRAINT='continuation_event_namespace';
		END IF;
	ELSIF TG_TABLE_NAME='outbox' THEN
		linked:=NEW.aggregate_kind='continuation_plan'
			OR NEW.payload->>'event_kind'='initial_quick_task_turn_admitted'
			OR NEW.payload #>> '{payload,kind}'=
				'initial_quick_task_turn_admission'
			OR pg_catalog.jsonb_path_exists(NEW.payload,'$.** ? (
				exists(@.continuation_plan_id) || exists(@.routing_decision_id) ||
				exists(@.fallback_context_pack_id) || exists(@.fallback_runtime_session_id)
			)');
		IF TG_OP='UPDATE' THEN
			linked:=linked OR OLD.aggregate_kind='continuation_plan'
				OR OLD.payload->>'event_kind'=
					'initial_quick_task_turn_admitted'
				OR OLD.payload #>> '{payload,kind}'=
					'initial_quick_task_turn_admission'
				OR pg_catalog.jsonb_path_exists(OLD.payload,'$.** ? (
					exists(@.continuation_plan_id) || exists(@.routing_decision_id) ||
					exists(@.fallback_context_pack_id) || exists(@.fallback_runtime_session_id)
				)');
		END IF;
		IF linked AND current_user::name<>owner_name THEN
			IF TG_OP='INSERT' THEN
				RAISE EXCEPTION 'continuation activity/outbox namespace is command-owned'
					USING ERRCODE='42501', CONSTRAINT='continuation_event_namespace';
			ELSIF NEW.id IS DISTINCT FROM OLD.id OR NEW.effect_key IS DISTINCT FROM OLD.effect_key
			OR NEW.aggregate_kind IS DISTINCT FROM OLD.aggregate_kind
			OR NEW.aggregate_id IS DISTINCT FROM OLD.aggregate_id
			OR NEW.aggregate_revision IS DISTINCT FROM OLD.aggregate_revision
			OR NEW.payload IS DISTINCT FROM OLD.payload OR NEW.created_at IS DISTINCT FROM OLD.created_at
			THEN
				RAISE EXCEPTION 'continuation outbox authority fields are command-owned'
					USING ERRCODE='42501', CONSTRAINT='continuation_event_namespace';
			END IF;
		END IF;
	ELSE
		RAISE EXCEPTION 'continuation event namespace has unexpected trigger relation'
			USING ERRCODE='42501', CONSTRAINT='continuation_event_namespace';
	END IF;
	RETURN NEW;
END
$_$;


--
-- Name: enforce_continuation_plan_completeness(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_continuation_plan_completeness() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF NEW.kind='initial_thread' THEN
		IF NEW.consumer_kind<>'conversation_turn'
			OR NEW.source_runtime_session_revision<>1
			OR NOT EXISTS (
				SELECT 1
				FROM decodex.routing_decisions AS decision
				JOIN decodex.routing_snapshots AS snapshot
					ON snapshot.snapshot_id=decision.snapshot_id
				JOIN decodex.routing_snapshot_members AS member
					ON member.snapshot_id=snapshot.snapshot_id
					AND member.account_id=decision.selected_account_id
				JOIN decodex.runtime_sessions AS session
					ON session.runtime_session_id=NEW.source_runtime_session_id
				JOIN decodex.account_snapshots AS account
					ON account.account_snapshot_id=session.account_snapshot_id
				JOIN decodex.profile_snapshots AS profile
					ON profile.profile_snapshot_id=session.profile_snapshot_id
				WHERE decision.decision_id=NEW.routing_decision_id
					AND decision.authority_shape='conversation_account_registry'
					AND decision.kind='selected'
					AND decision.selected_account_id=NEW.selected_account_id
					AND (
						decision.consumer_kind,decision.conversation_id,
						decision.conversation_revision,decision.turn_id,
						decision.managed_run_id,decision.managed_run_revision,
						decision.managed_execution_id
					) IS NOT DISTINCT FROM (
						NEW.consumer_kind,NEW.consumer_conversation_id,
						NEW.conversation_revision,NEW.turn_id,
						NEW.managed_run_id,NEW.managed_run_revision,
						NEW.managed_execution_id
					)
					AND (
						snapshot.consumer_kind,snapshot.conversation_id,
						snapshot.conversation_revision,snapshot.turn_id,
						snapshot.managed_run_id,snapshot.managed_run_revision,
						snapshot.managed_execution_id
					) IS NOT DISTINCT FROM (
						NEW.consumer_kind,NEW.consumer_conversation_id,
						NEW.conversation_revision,NEW.turn_id,
						NEW.managed_run_id,NEW.managed_run_revision,
						NEW.managed_execution_id
					)
					AND snapshot.runtime_session_id IS NULL
					AND snapshot.authority_shape='conversation_account_registry'
					AND snapshot.account_routing_revision=
						decision.account_routing_revision
					AND snapshot.runtime_session_revision IS NULL
					AND snapshot.account_snapshot_id IS NULL
					AND snapshot.account_snapshot_source_revision IS NULL
					AND snapshot.profile_snapshot_id IS NULL
					AND snapshot.profile_snapshot_source_revision IS NULL
					AND NOT EXISTS (
						SELECT 1
						FROM decodex.routing_decision_blocker_refs AS blocker
						WHERE blocker.decision_id=decision.decision_id
							AND blocker.account_id=decision.selected_account_id
					)
					AND session.conversation_id=NEW.conversation_id
					AND session.revision=NEW.source_runtime_session_revision
					AND session.state='starting'
					AND session.codex_thread_id IS NULL
					AND account.source_account_id=NEW.selected_account_id
					AND account.source_revision=member.account_revision
					AND profile.role='task'
					AND profile.source_revision=snapshot.task_role_profile_revision
					AND EXISTS (
						SELECT 1 FROM decodex.conversations AS conversation
						WHERE conversation.conversation_id=NEW.conversation_id
							AND conversation.revision=NEW.conversation_revision
							AND conversation.status='open'
					)
			)
		THEN
			RAISE EXCEPTION 'initial-thread plan has forged L0 lineage'
				USING ERRCODE='23514',CONSTRAINT='continuation_plan_complete';
		END IF;
		RETURN NULL;
	END IF;

	IF NEW.consumer_kind='conversation_turn' THEN
		IF NEW.consumer_conversation_id<>NEW.conversation_id
			OR NOT EXISTS (
				SELECT 1
				FROM decodex.routing_decisions AS decision
				JOIN decodex.runtime_sessions AS session
					ON session.runtime_session_id=decision.source_runtime_session_id
					AND session.revision=decision.source_runtime_session_revision
				JOIN decodex.routing_decisions AS initial
					ON initial.decision_id=decision.initial_decision_id
				JOIN decodex.routing_snapshots AS snapshot
					ON snapshot.snapshot_id=initial.snapshot_id
				JOIN decodex.routing_snapshot_members AS selected
					ON selected.snapshot_id=snapshot.snapshot_id
					AND selected.account_id=initial.selected_account_id
				JOIN decodex.account_snapshots AS account
					ON account.account_snapshot_id=decision.account_snapshot_id
				JOIN decodex.profile_snapshots AS profile
					ON profile.profile_snapshot_id=decision.profile_snapshot_id
				WHERE decision.decision_id=NEW.routing_decision_id
					AND decision.authority_shape='conversation_continuation'
					AND decision.source_runtime_session_id=NEW.source_runtime_session_id
					AND decision.source_runtime_session_revision=
						NEW.source_runtime_session_revision
					AND decision.conversation_id=NEW.consumer_conversation_id
					AND decision.conversation_revision=NEW.conversation_revision
					AND decision.turn_id=NEW.turn_id
					AND session.conversation_id=NEW.conversation_id
					AND session.account_snapshot_id=decision.account_snapshot_id
					AND session.profile_snapshot_id=decision.profile_snapshot_id
					AND initial.authority_shape='conversation_account_registry'
					AND initial.kind='selected'
					AND initial.selected_account_id=NEW.selected_account_id
					AND initial.conversation_id=NEW.conversation_id
					AND snapshot.authority_shape='conversation_account_registry'
					AND account.source_account_id=NEW.selected_account_id
					AND account.source_revision=selected.account_revision
					AND account.source_revision=
						decision.account_snapshot_source_revision
					AND profile.role='task'
					AND profile.source_revision=snapshot.task_role_profile_revision
					AND profile.source_revision=
						decision.profile_snapshot_source_revision
					AND EXISTS (
						SELECT 1 FROM decodex.conversations AS conversation
						WHERE conversation.conversation_id=NEW.conversation_id
							AND conversation.revision=NEW.conversation_revision
							AND conversation.status='open'
					)
			)
		THEN
			RAISE EXCEPTION 'Conversation continuation plan has forged binding lineage'
				USING ERRCODE='23514',CONSTRAINT='continuation_plan_complete';
		END IF;
	ELSE
		IF NEW.consumer_kind<>'managed_run_execution'
			OR NOT EXISTS (
				SELECT 1
				FROM decodex.routing_decisions AS decision
				JOIN decodex.routing_snapshots AS snapshot
					ON snapshot.snapshot_id=decision.snapshot_id
				JOIN decodex.runtime_sessions AS session
					ON (session.runtime_session_id,session.revision)=
						(snapshot.runtime_session_id,snapshot.runtime_session_revision)
				WHERE decision.decision_id=NEW.routing_decision_id
					AND decision.authority_shape='managed_run_project_policy'
					AND decision.kind='selected'
					AND decision.selected_account_id=NEW.selected_account_id
					AND snapshot.authority_shape='managed_run_project_policy'
					AND NOT EXISTS (
						SELECT 1
						FROM decodex.routing_decision_blocker_refs AS blocker
						WHERE blocker.decision_id=decision.decision_id
							AND blocker.account_id=decision.selected_account_id
					)
					AND (
						decision.consumer_kind,
						decision.managed_run_id,
						decision.managed_run_revision,
						decision.managed_execution_id
					) IS NOT DISTINCT FROM (
						NEW.consumer_kind,
						NEW.managed_run_id,
						NEW.managed_run_revision,
						NEW.managed_execution_id
					)
					AND (
						snapshot.consumer_kind,
						snapshot.managed_run_id,
						snapshot.managed_run_revision,
						snapshot.managed_execution_id
					) IS NOT DISTINCT FROM (
						NEW.consumer_kind,
						NEW.managed_run_id,
						NEW.managed_run_revision,
						NEW.managed_execution_id
					)
					AND (snapshot.runtime_session_id,snapshot.runtime_session_revision)=
						(NEW.source_runtime_session_id,NEW.source_runtime_session_revision)
					AND session.conversation_id=NEW.conversation_id
					AND EXISTS (
						SELECT 1 FROM decodex.managed_runs AS run
						WHERE (run.managed_run_id,run.revision)=
							(NEW.managed_run_id,NEW.managed_run_revision)
					)
			)
		THEN
			RAISE EXCEPTION 'ManagedRun continuation plan has forged routing lineage'
				USING ERRCODE='23514',CONSTRAINT='continuation_plan_complete';
		END IF;
	END IF;

	IF NEW.kind='same_thread'
		AND NEW.consumer_kind::text='managed_run_execution'
		AND NOT EXISTS (
			SELECT 1
			FROM decodex.routing_decisions AS decision
			JOIN decodex.routing_snapshots AS snapshot
				ON snapshot.snapshot_id=decision.snapshot_id
			JOIN decodex.routing_snapshot_members AS member
				ON member.snapshot_id=snapshot.snapshot_id
				AND member.account_id=decision.selected_account_id
			JOIN decodex.managed_runs AS run
				ON run.managed_run_id=NEW.managed_run_id
			JOIN decodex.runtime_sessions AS source_session
				ON source_session.runtime_session_id=
					NEW.source_runtime_session_id
			JOIN decodex.routing_compatibility_evidence AS evidence
				ON evidence.evidence_id=member.evidence_id
			JOIN decodex.codex_experiments AS experiment
				ON experiment.experiment_id=NEW.codex_experiment_id
			JOIN decodex.codex_experiment_thread_bindings AS binding
				ON binding.experiment_id=experiment.experiment_id
			JOIN decodex.codex_experiment_observations AS observation
				ON observation.observation_id=NEW.codex_observation_id
			WHERE decision.decision_id=NEW.routing_decision_id
				AND (
					evidence.evidence_id,
					evidence.evidence_revision,
					evidence.schema_fingerprint
				)=(
					NEW.routing_evidence_id,
					NEW.routing_evidence_revision,
					NEW.schema_fingerprint
				)
				AND (
					experiment.managed_run_id,
					experiment.managed_run_revision,
					experiment.routing_snapshot_id,
					experiment.account_id,
					experiment.account_revision,
					experiment.role_profile_revision,
					experiment.build_id,
					experiment.revision,
					experiment.state
				)=(
					NEW.managed_run_id,
					NEW.managed_run_revision,
					snapshot.snapshot_id,
					decision.selected_account_id,
					member.account_revision,
					snapshot.required_role_profile_revision,
					snapshot.required_build_id,
					3,
					'thread_bound'
				)
				AND binding.thread_id=NEW.codex_thread_id::text
				AND observation.experiment_id=experiment.experiment_id
				AND observation.experiment_revision=3
				AND observation.thread_id=binding.thread_id
				AND observation.kind='thread_read_item'
				AND evidence.account_id=NEW.selected_account_id
				AND evidence.account_revision=member.account_revision
				AND evidence.role=snapshot.required_role
				AND evidence.role_profile_revision=
					snapshot.required_role_profile_revision
				AND evidence.build_id=snapshot.required_build_id
				AND evidence.process_account_id=NEW.selected_account_id
				AND member.disposition='included'
				AND source_session.state='active'
				AND NOT run.diverged
				AND evidence.ingested_at<=NEW.planned_at
				AND NEW.planned_at-evidence.ingested_at<=INTERVAL '300 seconds'
				AND experiment.updated_at<=NEW.planned_at
				AND NEW.planned_at-experiment.updated_at<=INTERVAL '300 seconds'
				AND observation.observed_at<=NEW.planned_at
				AND NEW.planned_at-observation.observed_at<=
					INTERVAL '300 seconds'
				AND 4=(
					SELECT pg_catalog.count(DISTINCT capability.capability)
					FROM decodex.routing_capability_evidence AS capability
					WHERE capability.evidence_id=evidence.evidence_id
						AND capability.capability IN (
							'initialize','account_read',
							'thread_read','paginated_history'
						)
						AND capability.state='supported'
				)
		) THEN
		RAISE EXCEPTION 'same-thread ManagedRun plan has forged positive evidence'
			USING ERRCODE='23514',CONSTRAINT='continuation_plan_complete';
	ELSIF NEW.kind='same_thread'
		AND NEW.consumer_kind::text='conversation_turn'
		AND NOT EXISTS (
			SELECT 1
			FROM decodex.provider_attempts AS attempt
			JOIN decodex.provider_attempt_positive_evidence AS evidence
				ON evidence.evidence_id=attempt.terminal_evidence_id
				AND evidence.attempt_id=attempt.attempt_id
			JOIN decodex.runtime_sessions AS source_session
				ON source_session.runtime_session_id=
					NEW.source_runtime_session_id
			WHERE attempt.attempt_id=NEW.same_thread_provider_attempt_id
				AND attempt.revision=
					NEW.same_thread_provider_attempt_revision
				AND evidence.evidence_id=
					NEW.same_thread_provider_evidence_id
				AND attempt.consumer_kind::text='conversation_turn'
				AND attempt.conversation_id=
					NEW.consumer_conversation_id
				AND attempt.turn_id<>NEW.turn_id
				AND attempt.accepted_runtime_session_id=
					NEW.source_runtime_session_id
				AND attempt.accepted_runtime_session_revision+1=
					NEW.source_runtime_session_revision
				AND attempt.selected_account_id=NEW.selected_account_id
				AND attempt.state IN ('succeeded','failed_definitive')
				AND evidence.outcome::text=attempt.state::text
				AND evidence.source='exact_thread_readback'
				AND evidence.provider_thread_id=NEW.codex_thread_id::text
				AND source_session.codex_thread_id=NEW.codex_thread_id
				AND source_session.state='active'
				AND EXISTS (
					SELECT 1
					FROM decodex.exact_command_receipts AS receipt
					WHERE receipt.receipt_state='completed_success'
						AND receipt.request_envelope->>'operation'=
							'terminalize_quick_task_turn'
						AND receipt.request_envelope->>'conversation_id'=
							attempt.conversation_id::text
						AND receipt.request_envelope->>'runtime_session_id'=
							attempt.accepted_runtime_session_id::text
						AND receipt.request_envelope->>'expected_runtime_session_revision'=
							attempt.accepted_runtime_session_revision::text
						AND receipt.request_envelope->>'user_turn_id'=
							attempt.turn_id::text
						AND receipt.request_envelope->>'provider_attempt_id'=
							attempt.attempt_id::text
						AND receipt.effect_envelope->>'runtime_session_revision'=
							NEW.source_runtime_session_revision::text
						AND receipt.effect_envelope->>'provider_evidence_id'=
							evidence.evidence_id::text
				)
				AND evidence.observed_at<=NEW.planned_at
				AND NEW.planned_at-evidence.observed_at<=
					INTERVAL '300 seconds'
		) THEN
		RAISE EXCEPTION 'same-thread Conversation plan has forged positive evidence'
			USING ERRCODE='23514',CONSTRAINT='continuation_plan_complete';
	ELSIF NEW.kind='context_pack_fallback'
		AND NOT (
			(
				NEW.consumer_kind='conversation_turn'
				AND EXISTS (
					SELECT 1
					FROM decodex.context_packs AS pack
					JOIN decodex.routing_decisions AS decision
						ON decision.decision_id=NEW.routing_decision_id
					JOIN decodex.routing_decisions AS initial
						ON initial.decision_id=decision.initial_decision_id
					JOIN decodex.runtime_sessions AS source_session
						ON source_session.runtime_session_id=
							NEW.source_runtime_session_id
						AND source_session.revision=
							NEW.source_runtime_session_revision
					JOIN decodex.runtime_sessions AS session
						ON session.runtime_session_id=
							NEW.fallback_runtime_session_id
					WHERE pack.context_pack_id=NEW.fallback_context_pack_id
						AND pack.conversation_id=NEW.conversation_id
						AND decision.authority_shape='conversation_continuation'
						AND initial.authority_shape='conversation_account_registry'
						AND initial.kind='selected'
						AND initial.selected_account_id=NEW.selected_account_id
						AND source_session.account_snapshot_id=
							decision.account_snapshot_id
						AND source_session.profile_snapshot_id=
							decision.profile_snapshot_id
						AND session.conversation_id=NEW.conversation_id
						AND session.codex_thread_id IS NULL
						AND session.state='starting'
						AND session.revision=1
						AND session.account_snapshot_id=decision.account_snapshot_id
						AND session.profile_snapshot_id=decision.profile_snapshot_id
				)
			) OR (
				NEW.consumer_kind='managed_run_execution'
				AND EXISTS (
					SELECT 1
					FROM decodex.context_packs AS pack
					JOIN decodex.routing_decisions AS decision
						ON decision.decision_id=NEW.routing_decision_id
					JOIN decodex.routing_snapshot_members AS member
						ON member.snapshot_id=decision.snapshot_id
						AND member.account_id=NEW.selected_account_id
					JOIN decodex.runtime_sessions AS source_session
						ON source_session.runtime_session_id=
							NEW.source_runtime_session_id
					JOIN decodex.runtime_sessions AS session
						ON session.runtime_session_id=
							NEW.fallback_runtime_session_id
					JOIN decodex.account_snapshots AS account
						ON account.account_snapshot_id=session.account_snapshot_id
					WHERE pack.context_pack_id=NEW.fallback_context_pack_id
						AND pack.conversation_id=NEW.conversation_id
						AND decision.authority_shape='managed_run_project_policy'
						AND session.conversation_id=NEW.conversation_id
						AND session.codex_thread_id IS NULL
						AND session.state='starting'
						AND session.revision=1
						AND account.source_account_id=NEW.selected_account_id
						AND (
							account.source_revision,
							account.display_label,
							account.observed_state
						)=(
							member.account_revision,
							member.display_label,
							member.account_state
						)
						AND session.profile_snapshot_id=
							source_session.profile_snapshot_id
				)
			)
		)
	THEN
		RAISE EXCEPTION 'fallback plan has incomplete Context Pack or RuntimeSession linkage'
			USING ERRCODE='23514',CONSTRAINT='continuation_plan_complete';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_conversation_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_conversation_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF TG_OP = 'INSERT' THEN
		IF NEW.status <> 'open' OR NEW.revision <> 1 THEN
			RAISE EXCEPTION 'conversation must be created open at revision 1';
		END IF;
		NEW.created_at := pg_catalog.clock_timestamp();
		NEW.updated_at := NEW.created_at;
		RETURN NEW;
	END IF;
	IF OLD.status = 'archived' THEN
		RAISE EXCEPTION 'archived conversation is immutable';
	END IF;
	IF NEW.conversation_id <> OLD.conversation_id
		OR NEW.title IS DISTINCT FROM OLD.title
		OR NEW.initial_quick_task_message IS DISTINCT FROM
			OLD.initial_quick_task_message
		OR NEW.initial_quick_task_working_directory IS DISTINCT FROM
			OLD.initial_quick_task_working_directory
		OR NEW.created_at IS DISTINCT FROM OLD.created_at
		OR NEW.revision <> OLD.revision + 1
		OR OLD.status <> 'open' OR NEW.status <> 'archived' THEN
		RAISE EXCEPTION 'illegal conversation transition';
	END IF;
	IF NEW.status = 'archived' AND EXISTS (
		SELECT 1 FROM decodex.runtime_sessions WHERE conversation_id = NEW.conversation_id
		AND state IN ('starting', 'active')
	) THEN RAISE EXCEPTION 'conversation has nonterminal runtime sessions'; END IF;
	IF NEW.status = 'archived' AND EXISTS (
		SELECT 1 FROM decodex.artifacts WHERE conversation_id = NEW.conversation_id
		AND status = 'active'
	) THEN RAISE EXCEPTION 'conversation has active Artifacts'; END IF;
	NEW.updated_at := pg_catalog.clock_timestamp();
	RETURN NEW;
END;
$$;


--
-- Name: enforce_conversation_routing_successor(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_conversation_routing_successor() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE source_row decodex.conversations%ROWTYPE;
DECLARE successor_row decodex.conversations%ROWTYPE;
BEGIN
	IF TG_OP<>'INSERT' THEN
		RAISE EXCEPTION 'routing Conversation successor relation is immutable'
			USING ERRCODE='23514',CONSTRAINT='conversation_routing_successor_exact';
	END IF;
	SELECT * INTO source_row FROM decodex.conversations
	WHERE conversation_id=NEW.source_conversation_id;
	SELECT * INTO successor_row FROM decodex.conversations
	WHERE conversation_id=NEW.successor_conversation_id;
	IF source_row.conversation_id IS NULL OR successor_row.conversation_id IS NULL
		OR source_row.status<>'archived' OR source_row.revision<>NEW.source_revision
		OR successor_row.status<>'open'
		OR successor_row.revision<>NEW.successor_revision
		OR source_row.title<>successor_row.title
		OR source_row.initial_quick_task_message IS NULL
		OR source_row.initial_quick_task_message IS DISTINCT FROM
			successor_row.initial_quick_task_message
		OR source_row.initial_quick_task_working_directory IS DISTINCT FROM
			successor_row.initial_quick_task_working_directory
		OR NOT EXISTS (
			SELECT 1 FROM decodex.routing_decisions AS decision
			WHERE decision.decision_id=NEW.source_routing_decision_id
				AND decision.authority_shape='conversation_account_registry'
				AND decision.conversation_id=NEW.source_conversation_id
				AND decision.kind IN ('waiting','no_route')
				AND decision.selected_account_id IS NULL
		)
		OR EXISTS (SELECT 1 FROM decodex.runtime_sessions
			WHERE conversation_id=NEW.source_conversation_id)
		OR EXISTS (SELECT 1 FROM decodex.turns
			WHERE conversation_id=NEW.source_conversation_id)
		OR EXISTS (SELECT 1 FROM decodex.routing_decisions
			WHERE conversation_id=NEW.source_conversation_id
				AND decision_id<>NEW.source_routing_decision_id)
		OR EXISTS (SELECT 1 FROM decodex.continuation_plans
			WHERE consumer_conversation_id=NEW.source_conversation_id
				OR conversation_id=NEW.source_conversation_id)
		OR EXISTS (SELECT 1 FROM decodex.provider_attempts
			WHERE conversation_id=NEW.source_conversation_id)
		OR EXISTS (SELECT 1 FROM decodex.routing_decisions
			WHERE conversation_id=NEW.successor_conversation_id)
		OR EXISTS (SELECT 1 FROM decodex.runtime_sessions
			WHERE conversation_id=NEW.successor_conversation_id)
		OR EXISTS (SELECT 1 FROM decodex.turns
			WHERE conversation_id=NEW.successor_conversation_id)
		OR EXISTS (SELECT 1 FROM decodex.continuation_plans
			WHERE consumer_conversation_id=NEW.successor_conversation_id
				OR conversation_id=NEW.successor_conversation_id)
		OR EXISTS (SELECT 1 FROM decodex.provider_attempts
			WHERE conversation_id=NEW.successor_conversation_id)
	THEN
		RAISE EXCEPTION 'routing Conversation successor relation is incomplete'
			USING ERRCODE='23514',CONSTRAINT='conversation_routing_successor_exact';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_exact_receipt_completion(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_exact_receipt_completion() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE current_state decodex.exact_receipt_state;
BEGIN
	SELECT receipt_state INTO current_state
	FROM decodex.exact_command_receipts
	WHERE protocol_version = NEW.protocol_version
		AND idempotency_key = NEW.idempotency_key;

	IF current_state = 'executing' THEN
		RAISE EXCEPTION 'exact command receipt must be completed before commit'
			USING ERRCODE = '23514', CONSTRAINT = 'exact_receipts_complete_at_commit';
	END IF;

	RETURN NULL;
END
$$;


--
-- Name: enforce_history_cursor_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_history_cursor_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE current_high_water bigint;
DECLARE current_version_sequence bigint;
DECLARE parent_conversation_id uuid;
DECLARE parent_high_water bigint;
DECLARE parent_version_sequence bigint;
DECLARE parent_position bigint;
DECLARE parent_page_size integer;
DECLARE parent_expires_at timestamptz;
DECLARE canonical_position bigint;
DECLARE canonical_item_id uuid;
DECLARE insertion_time timestamptz := pg_catalog.clock_timestamp();
BEGIN
	PERFORM 1 FROM decodex.conversations
		WHERE conversation_id = NEW.conversation_id FOR UPDATE;
	SELECT COALESCE(max(history_position), 0) INTO current_high_water
		FROM decodex.history_items WHERE conversation_id = NEW.conversation_id;
	SELECT COALESCE(max(version_sequence), 0) INTO current_version_sequence
		FROM decodex.history_item_versions WHERE conversation_id = NEW.conversation_id;
	IF NEW.parent_cursor_id IS NULL THEN
		IF NEW.snapshot_high_water <> current_high_water
			OR NEW.snapshot_version_sequence <> current_version_sequence THEN
			RAISE EXCEPTION 'root history cursor requires the current snapshot boundary';
		END IF;
	ELSE
		SELECT conversation_id, snapshot_high_water, snapshot_version_sequence,
				last_position, page_size, expires_at
			INTO parent_conversation_id, parent_high_water, parent_version_sequence, parent_position,
				parent_page_size, parent_expires_at
			FROM decodex.history_cursors WHERE cursor_id = NEW.parent_cursor_id;
		IF parent_conversation_id IS DISTINCT FROM NEW.conversation_id
			OR parent_high_water IS DISTINCT FROM NEW.snapshot_high_water
			OR parent_version_sequence IS DISTINCT FROM NEW.snapshot_version_sequence
			OR parent_position IS NULL OR NEW.last_position <= parent_position
			OR parent_page_size IS DISTINCT FROM NEW.page_size
			OR parent_expires_at <= insertion_time
			OR NEW.expires_at IS DISTINCT FROM parent_expires_at THEN
			RAISE EXCEPTION 'continued history cursor requires one issued earlier boundary';
		END IF;
	END IF;
	IF NEW.created_at > insertion_time
		OR NEW.created_at < insertion_time - interval '1 minute'
		OR (NEW.parent_cursor_id IS NULL
			AND NEW.expires_at IS DISTINCT FROM NEW.created_at + interval '1 hour') THEN
		RAISE EXCEPTION 'history cursor timestamps are not canonical';
	END IF;
	SELECT history_position, history_item_id INTO canonical_position, canonical_item_id FROM (
		SELECT DISTINCT ON (history_position) history_position, history_item_id
		FROM decodex.history_item_versions
		WHERE conversation_id = NEW.conversation_id
			AND version_sequence <= NEW.snapshot_version_sequence
		ORDER BY history_position, version_sequence DESC
	) AS snapshot_items
		WHERE history_position > COALESCE(parent_position, 0)
			AND history_position <= NEW.snapshot_high_water
		ORDER BY history_position
		OFFSET NEW.page_size - 1 LIMIT 1;
	IF canonical_position IS DISTINCT FROM NEW.last_position
		OR canonical_item_id IS DISTINCT FROM NEW.history_item_id THEN
		RAISE EXCEPTION 'history cursor is not one canonical issued page boundary';
	END IF;
	RETURN NEW;
END;
$$;


--
-- Name: enforce_history_item_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_history_item_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE turn_state decodex.turn_status;
DECLARE turn_role decodex.turn_role;
DECLARE turn_sequence bigint;
DECLARE session_state decodex.runtime_session_state;
DECLARE conversation_state decodex.conversation_status;
DECLARE artifact_state decodex.artifact_status;
DECLARE next_position bigint;
BEGIN
	IF pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN
		RAISE EXCEPTION 'history hierarchy writes require READ COMMITTED'
			USING ERRCODE='40001';
	END IF;
	SELECT turn.status,turn.role,turn.sequence,session.state,conversation.status
	INTO turn_state,turn_role,turn_sequence,session_state,conversation_state
	FROM decodex.turns AS turn
	JOIN decodex.runtime_sessions AS session
		ON (session.runtime_session_id,session.conversation_id)=
			(turn.runtime_session_id,turn.conversation_id)
	JOIN decodex.conversations AS conversation
		ON conversation.conversation_id=turn.conversation_id
	WHERE (turn.turn_id,turn.conversation_id)=(NEW.turn_id,NEW.conversation_id)
	FOR UPDATE OF conversation,turn;
	IF turn_state<>'active' OR conversation_state<>'open'
		OR NOT (
			session_state='active'
			OR (
				TG_OP='INSERT' AND session_state='starting'
				AND turn_role='user' AND turn_sequence=1
				AND NEW.kind='message' AND NEW.status='completed'
			)
		)
	THEN
		RAISE EXCEPTION 'history write requires active parents or initial reservation';
	END IF;
	IF NEW.kind='artifact' THEN
		SELECT status INTO artifact_state FROM decodex.artifacts
		WHERE (artifact_id,conversation_id)=(NEW.artifact_id,NEW.conversation_id)
		FOR UPDATE;
		IF artifact_state<>'active' THEN
			RAISE EXCEPTION 'history Artifact reference requires active Artifact';
		END IF;
	END IF;
	IF TG_OP='INSERT' THEN
		IF NEW.revision<>1 THEN
			RAISE EXCEPTION 'history item must start at revision 1';
		END IF;
		SELECT COALESCE(pg_catalog.max(history_position),0)+1
		INTO next_position FROM decodex.history_items
		WHERE conversation_id=NEW.conversation_id;
		NEW.history_position:=next_position;
		NEW.created_at:=pg_catalog.clock_timestamp();
		NEW.updated_at:=NEW.created_at;
		RETURN NEW;
	END IF;
	IF OLD.status IN ('completed','failed') THEN
		RAISE EXCEPTION 'terminal history item is immutable';
	END IF;
	IF NEW.history_item_id<>OLD.history_item_id
		OR NEW.conversation_id<>OLD.conversation_id
		OR NEW.history_position<>OLD.history_position
		OR NEW.turn_id<>OLD.turn_id OR NEW.ordinal<>OLD.ordinal
		OR NEW.kind<>OLD.kind
		OR NEW.artifact_id IS DISTINCT FROM OLD.artifact_id
		OR NEW.artifact_revision IS DISTINCT FROM OLD.artifact_revision
		OR NEW.created_at IS DISTINCT FROM OLD.created_at
		OR NEW.revision<>OLD.revision+1
	THEN
		RAISE EXCEPTION 'illegal history item transition';
	END IF;
	NEW.updated_at:=pg_catalog.clock_timestamp();
	RETURN NEW;
END
$$;


--
-- Name: enforce_initial_quick_task_admission_complete(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_initial_quick_task_admission_complete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE conversation_row decodex.conversations%ROWTYPE;
DECLARE session_row decodex.runtime_sessions%ROWTYPE;
DECLARE turn_row decodex.turns%ROWTYPE;
DECLARE message_row decodex.history_items%ROWTYPE;
DECLARE plan_row decodex.continuation_plans%ROWTYPE;
DECLARE decision_row decodex.routing_decisions%ROWTYPE;
DECLARE receipt_row decodex.exact_command_receipts%ROWTYPE;
DECLARE activity_row decodex.activity%ROWTYPE;
DECLARE outbox_row decodex.outbox%ROWTYPE;
DECLARE receipt_count bigint; turn_count bigint; message_count bigint;
DECLARE expected_request jsonb; turn_value jsonb; message_value jsonb;
DECLARE admission_value jsonb; core jsonb; expected_effect jsonb;
DECLARE expected_response bytea; expected_outbox_payload jsonb;
BEGIN
	SELECT * INTO plan_row FROM decodex.continuation_plans AS plan
	WHERE plan.kind='initial_thread' AND plan.turn_id=NEW.turn_id
		AND plan.consumer_conversation_id=NEW.conversation_id
		AND plan.source_runtime_session_id=NEW.runtime_session_id;
	IF NOT FOUND THEN
		RETURN NULL;
	END IF;

	SELECT * INTO conversation_row FROM decodex.conversations
	WHERE conversation_id=NEW.conversation_id;
	SELECT * INTO session_row FROM decodex.runtime_sessions
	WHERE runtime_session_id=NEW.runtime_session_id;
	SELECT * INTO turn_row FROM decodex.turns WHERE turn_id=NEW.turn_id;
	SELECT * INTO decision_row FROM decodex.routing_decisions
	WHERE decision_id=plan_row.routing_decision_id;
	SELECT pg_catalog.count(*) INTO turn_count FROM decodex.turns
	WHERE conversation_id=NEW.conversation_id;
	SELECT pg_catalog.count(*) INTO message_count FROM decodex.history_items
	WHERE conversation_id=NEW.conversation_id;
	SELECT * INTO message_row FROM decodex.history_items
	WHERE conversation_id=NEW.conversation_id AND turn_id=NEW.turn_id;

	SELECT pg_catalog.count(*) INTO receipt_count
	FROM decodex.exact_command_receipts AS receipt
	WHERE receipt.receipt_state='completed_success'
		AND receipt.request_envelope->>'operation'=
			'admit_initial_quick_task_turn'
		AND receipt.request_envelope->>'conversation_id'=NEW.conversation_id::text
		AND receipt.request_envelope->>'runtime_session_id'=
			NEW.runtime_session_id::text
		AND receipt.request_envelope->>'turn_id'=NEW.turn_id::text;
	IF receipt_count=1 THEN
		SELECT * INTO receipt_row FROM decodex.exact_command_receipts AS receipt
		WHERE receipt.receipt_state='completed_success'
			AND receipt.request_envelope->>'operation'=
				'admit_initial_quick_task_turn'
			AND receipt.request_envelope->>'conversation_id'=
				NEW.conversation_id::text
			AND receipt.request_envelope->>'runtime_session_id'=
				NEW.runtime_session_id::text
			AND receipt.request_envelope->>'turn_id'=NEW.turn_id::text;
	END IF;

	IF receipt_count<>1 OR turn_count<>1 OR message_count<>1
		OR conversation_row.conversation_id IS NULL
		OR conversation_row.status<>'open'
		OR conversation_row.revision<>plan_row.conversation_revision
		OR session_row.runtime_session_id IS NULL
		OR session_row.conversation_id<>conversation_row.conversation_id
		OR session_row.state<>'starting' OR session_row.revision<>1
		OR session_row.codex_thread_id IS NOT NULL
		OR session_row.last_known_turn_id IS NOT NULL
		OR session_row.thread_start_request_id IS NOT NULL
		OR session_row.thread_start_request_sha256 IS NOT NULL
		OR session_row.thread_start_response_id IS NOT NULL
		OR session_row.thread_start_response_sha256 IS NOT NULL
		OR turn_row.turn_id IS NULL OR turn_row.sequence<>1
		OR turn_row.role<>'user' OR turn_row.possible_side_effects<>'unknown'
		OR turn_row.status<>'active' OR turn_row.revision<>1
		OR turn_row.conversation_id<>conversation_row.conversation_id
		OR turn_row.runtime_session_id<>session_row.runtime_session_id
		OR message_row.history_item_id IS NULL OR message_row.history_position<>1
		OR message_row.conversation_id<>conversation_row.conversation_id
		OR message_row.turn_id<>turn_row.turn_id OR message_row.ordinal<>0
		OR message_row.kind<>'message' OR message_row.status<>'completed'
		OR message_row.revision<>1 OR plan_row.revision<>1
		OR plan_row.consumer_kind<>'conversation_turn'
		OR plan_row.conversation_id<>conversation_row.conversation_id
		OR plan_row.source_runtime_session_revision<>1
		OR plan_row.replay_permitted OR plan_row.dispatch_enabled
		OR decision_row.decision_id IS NULL
		OR decision_row.authority_shape<>'conversation_account_registry'
		OR decision_row.kind<>'selected'
		OR decision_row.consumer_kind<>'conversation_turn'
		OR decision_row.conversation_id<>conversation_row.conversation_id
		OR decision_row.conversation_revision<>conversation_row.revision
		OR decision_row.turn_id<>turn_row.turn_id
	THEN
		RAISE EXCEPTION 'initial Quick Task admission is incomplete'
			USING ERRCODE='23514',
				CONSTRAINT='initial_quick_task_admission_complete';
	END IF;

	expected_request:=pg_catalog.jsonb_build_object(
		'operation','admit_initial_quick_task_turn',
		'protocol_version',receipt_row.protocol_version,
		'conversation_id',conversation_row.conversation_id,
		'expected_conversation_revision',conversation_row.revision,
		'runtime_session_id',session_row.runtime_session_id,
		'expected_runtime_session_revision',session_row.revision,
		'continuation_plan_id',plan_row.plan_id,
		'turn_id',turn_row.turn_id,'sequence',1,'role','user',
		'possible_side_effects','unknown','turn_status','active','turn_revision',1,
		'history_item_id',message_row.history_item_id,'message_ordinal',0,
		'message_kind','message','message_status','completed','message_revision',1,
		'inline_text',message_row.inline_text,'blob_hash',message_row.blob_hash,
		'media_type',message_row.media_type,'metadata',message_row.metadata
	);
	turn_value:=pg_catalog.jsonb_build_object(
		'turn_id',turn_row.turn_id,'conversation_id',turn_row.conversation_id,
		'runtime_session_id',turn_row.runtime_session_id,
		'sequence',turn_row.sequence,'role',turn_row.role,
		'possible_side_effects',turn_row.possible_side_effects,
		'status',turn_row.status,'revision',turn_row.revision
	);
	message_value:=pg_catalog.jsonb_build_object(
		'history_item_id',message_row.history_item_id,
		'conversation_id',message_row.conversation_id,
		'history_position',message_row.history_position,'turn_id',message_row.turn_id,
		'ordinal',message_row.ordinal,'kind',message_row.kind,
		'status',message_row.status,'inline_text',message_row.inline_text,
		'blob_hash',message_row.blob_hash,'media_type',message_row.media_type,
		'metadata',message_row.metadata,'revision',message_row.revision
	);
	admission_value:=pg_catalog.jsonb_build_object(
		'kind','initial_quick_task_turn_admission',
		'conversation_id',conversation_row.conversation_id,
		'conversation_revision',conversation_row.revision,
		'runtime_session_id',session_row.runtime_session_id,
		'runtime_session_revision',session_row.revision,
		'continuation_plan_id',plan_row.plan_id,
		'routing_decision_id',decision_row.decision_id,
		'turn',turn_value,'message',message_value
	);
	SELECT * INTO activity_row FROM decodex.activity
	WHERE sequence=(receipt_row.effect_envelope->>'activity_sequence')::bigint;
	SELECT * INTO outbox_row FROM decodex.outbox
	WHERE id=(receipt_row.effect_envelope->>'outbox_id')::bigint;
	core:=admission_value||pg_catalog.jsonb_build_object(
		'operation','admit_initial_quick_task_turn',
		'activity_sequence',activity_row.sequence,'outbox_id',outbox_row.id
	);
	expected_effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	expected_response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',expected_effect
	)::text,'UTF8');
	expected_outbox_payload:=pg_catalog.jsonb_build_object(
		'activity_sequence',activity_row.sequence,
		'event_kind','initial_quick_task_turn_admitted',
		'aggregate_kind','conversation','aggregate_id',conversation_row.conversation_id,
		'revision',conversation_row.revision,'payload',admission_value
	);
	IF receipt_row.request_envelope<>expected_request
		OR receipt_row.effect_envelope<>expected_effect
		OR receipt_row.response_bytes<>expected_response
		OR activity_row.sequence IS NULL
		OR activity_row.aggregate_kind<>'conversation'
		OR activity_row.aggregate_id<>conversation_row.conversation_id::text
		OR activity_row.revision<>conversation_row.revision
		OR activity_row.event_kind<>'initial_quick_task_turn_admitted'
		OR activity_row.correlation_key<>receipt_row.idempotency_key
		OR activity_row.payload<>admission_value
		OR outbox_row.id IS NULL
		OR outbox_row.effect_key<>'activity/'||activity_row.sequence::text
		OR outbox_row.aggregate_kind<>'conversation'
		OR outbox_row.aggregate_id<>conversation_row.conversation_id::text
		OR outbox_row.aggregate_revision<>conversation_row.revision
		OR outbox_row.payload<>expected_outbox_payload
	THEN
		RAISE EXCEPTION 'initial Quick Task admission evidence is not exact'
			USING ERRCODE='23514',
				CONSTRAINT='initial_quick_task_admission_complete';
	END IF;
	RETURN NULL;
END
$_$;


--
-- Name: enforce_initial_quick_task_admission_owner(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_initial_quick_task_admission_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE owner_name name; session_state decodex.runtime_session_state;
BEGIN
	SELECT role.rolname INTO owner_name FROM pg_catalog.pg_class AS class
	JOIN pg_catalog.pg_roles AS role ON role.oid=class.relowner
	WHERE class.oid=TG_RELID;
	IF TG_TABLE_NAME='turns' THEN
		SELECT session.state INTO session_state FROM decodex.runtime_sessions AS session
		WHERE session.runtime_session_id=NEW.runtime_session_id;
	ELSIF TG_TABLE_NAME='history_items' THEN
		SELECT session.state INTO session_state FROM decodex.turns AS turn
		JOIN decodex.runtime_sessions AS session
			ON session.runtime_session_id=turn.runtime_session_id
		WHERE turn.turn_id=NEW.turn_id;
	ELSE
		RAISE EXCEPTION 'initial Quick Task admission owner has unexpected relation'
			USING ERRCODE='42501',
				CONSTRAINT='initial_quick_task_admission_command_owner';
	END IF;
	IF session_state='starting' AND current_user::name<>owner_name THEN
		RAISE EXCEPTION 'initial Quick Task admission is writable only by its command owner'
			USING ERRCODE='42501',
				CONSTRAINT='initial_quick_task_admission_command_owner';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: enforce_lease_operation_time(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_lease_operation_time() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE
	write_at timestamptz := clock_timestamp();
BEGIN
	IF NEW.updated_at > write_at
		OR NEW.expires_at > write_at + 31536000000 * interval '1 millisecond'
	THEN
		RAISE EXCEPTION 'lease timestamps must be anchored to the database write time'
			USING ERRCODE = '23514', CONSTRAINT = 'leases_operation_time';
	END IF;

	RETURN NEW;
END
$$;


--
-- Name: enforce_managed_repository_projection(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_managed_repository_projection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE transition_row decodex.repository_authority_transitions%ROWTYPE;
DECLARE terminal_state decodex.repository_operation_state;
DECLARE operation_row decodex.repository_operations%ROWTYPE;
DECLARE result_row decodex.repository_operation_results%ROWTYPE;
BEGIN
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'managed-repository current authority cannot be deleted'
			USING ERRCODE = '23514', CONSTRAINT = 'managed_repository_projection';
	END IF;
	SELECT * INTO transition_row FROM decodex.repository_authority_transitions
	WHERE repository_id = NEW.repository_id AND generation = NEW.generation
		AND authority_tip = NEW.authority_tip;
	IF NOT FOUND OR transition_row.phase <> NEW.phase
		OR transition_row.ambiguity IS DISTINCT FROM NEW.ambiguity
		OR transition_row.head <> NEW.head
		OR transition_row.active_operation_id IS DISTINCT FROM NEW.active_operation_id
	THEN
		RAISE EXCEPTION 'managed-repository projection must equal its authority transition'
			USING ERRCODE = '23514', CONSTRAINT = 'managed_repository_projection';
	END IF;
	IF TG_OP = 'INSERT' THEN
		IF NEW.generation <> 1 OR NEW.active_operation_id IS NOT NULL
			OR transition_row.transition_kind <> 'allocated'
		THEN
			RAISE EXCEPTION 'managed-repository projection must begin at allocation generation one'
				USING ERRCODE = '23514', CONSTRAINT = 'managed_repository_projection';
		END IF;
		RETURN NEW;
	END IF;
	IF NEW.repository_id <> OLD.repository_id OR NEW.project_id <> OLD.project_id
		OR NEW.allocation_id <> OLD.allocation_id OR NEW.worktree_id <> OLD.worktree_id
		OR NEW.worktree_absolute_path <> OLD.worktree_absolute_path
		OR NEW.generation <> OLD.generation + 1
		OR transition_row.prior_generation <> OLD.generation
		OR transition_row.prior_authority_tip <> OLD.authority_tip
		OR NEW.updated_at < OLD.updated_at
	THEN
		RAISE EXCEPTION 'managed-repository projection update is not one monotonic transition'
			USING ERRCODE = '23514', CONSTRAINT = 'managed_repository_projection';
	END IF;
	IF OLD.active_operation_id IS NULL AND NEW.active_operation_id IS NOT NULL THEN
		SELECT * INTO operation_row FROM decodex.repository_operations
		WHERE operation_id = NEW.active_operation_id;
		IF NOT FOUND OR operation_row.repository_id <> NEW.repository_id
			OR operation_row.expected_generation <> OLD.generation
			OR operation_row.expected_authority_tip <> OLD.authority_tip
			OR operation_row.payload->>'expected_head' <> OLD.head
			OR NOT (CASE operation_row.kind
				WHEN 'register' THEN OLD.phase = 'allocated'
				WHEN 'worktree_ready' THEN OLD.phase = 'registered'
				WHEN 'commit' THEN OLD.phase = 'ready'
			END)
			OR NEW.phase <> OLD.phase OR NEW.head <> OLD.head
			OR transition_row.operation_id <> NEW.active_operation_id
			OR transition_row.transition_kind <> (CASE operation_row.kind
				WHEN 'register' THEN 'register_prepared'::decodex.repository_authority_transition_kind
				WHEN 'worktree_ready' THEN 'worktree_ready_prepared'::decodex.repository_authority_transition_kind
				WHEN 'commit' THEN 'commit_prepared'::decodex.repository_authority_transition_kind
			END) OR EXISTS (
			SELECT 1 FROM decodex.repository_operation_results
			WHERE operation_id = NEW.active_operation_id
		) OR NOT EXISTS (
			SELECT 1 FROM decodex.repository_operation_events
			WHERE operation_id = NEW.active_operation_id AND ordinal = 1
				AND state = 'possibly_effected'
		) THEN
			RAISE EXCEPTION 'managed-repository preparation is incomplete'
				USING ERRCODE = '23514', CONSTRAINT = 'managed_repository_projection';
		END IF;
	ELSIF OLD.active_operation_id IS NOT NULL AND NEW.active_operation_id IS NULL THEN
		SELECT * INTO result_row FROM decodex.repository_operation_results
		WHERE operation_id = OLD.active_operation_id;
		terminal_state := result_row.state;
		SELECT * INTO operation_row FROM decodex.repository_operations
		WHERE operation_id = OLD.active_operation_id;
		IF terminal_state IS NULL OR operation_row.operation_id IS NULL
			OR result_row.repository_id <> NEW.repository_id
			OR result_row.evidence_id <> transition_row.evidence_id
			OR NOT EXISTS (
				SELECT 1 FROM decodex.repository_operation_evidence evidence
				WHERE evidence.evidence_id = result_row.evidence_id
					AND evidence.repository_id = NEW.repository_id
					AND evidence.operation_id = OLD.active_operation_id
					AND evidence.kind = (CASE operation_row.kind
						WHEN 'register' THEN 'registration'::decodex.repository_evidence_kind
						WHEN 'worktree_ready' THEN 'worktree_ready'::decodex.repository_evidence_kind
						WHEN 'commit' THEN 'commit'::decodex.repository_evidence_kind
					END)
			)
			OR transition_row.operation_id <> OLD.active_operation_id
			OR NOT EXISTS (SELECT 1 FROM decodex.repository_operation_events
				WHERE operation_id = OLD.active_operation_id AND ordinal = 2
					AND state = terminal_state AND evidence_id = result_row.evidence_id)
			OR (terminal_state = 'ambiguous' AND (
				NEW.phase <> 'ambiguous' OR NEW.ambiguity <> result_row.ambiguity
				OR NEW.head <> OLD.head OR transition_row.transition_kind <> 'operation_ambiguous'
			))
			OR (terminal_state = 'completed' AND (
				NEW.ambiguity IS NOT NULL
				OR transition_row.transition_kind <> (CASE operation_row.kind
					WHEN 'register' THEN 'register_completed'::decodex.repository_authority_transition_kind
					WHEN 'worktree_ready' THEN 'worktree_ready_completed'::decodex.repository_authority_transition_kind
					WHEN 'commit' THEN 'commit_completed'::decodex.repository_authority_transition_kind
				END)
				OR (CASE operation_row.kind
					WHEN 'register' THEN result_row.result <> pg_catalog.jsonb_build_object(
						'kind','registered','head',operation_row.payload->>'expected_head'
					) OR NEW.phase <> 'registered' OR NEW.head <> OLD.head
					WHEN 'worktree_ready' THEN result_row.result <> pg_catalog.jsonb_build_object(
						'kind','worktree_ready','head',operation_row.payload->>'expected_head'
					) OR NEW.phase <> 'ready' OR NEW.head <> OLD.head
					WHEN 'commit' THEN result_row.result <> pg_catalog.jsonb_build_object(
						'kind','committed','from',operation_row.payload->>'expected_head',
						'to',operation_row.payload->>'next_head'
					) OR NEW.phase <> 'ready'
						OR NEW.head <> operation_row.payload->>'next_head'
				END)
			))
		THEN
			RAISE EXCEPTION 'managed-repository reconciliation is incomplete'
				USING ERRCODE = '23514', CONSTRAINT = 'managed_repository_projection';
		END IF;
	ELSE
		RAISE EXCEPTION 'managed-repository transition must set or clear one active fence'
			USING ERRCODE = '23514', CONSTRAINT = 'managed_repository_projection';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: enforce_managed_run_assignment_scope(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_managed_run_assignment_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE run_session uuid;
DECLARE snapshot_role decodex.role_profile_role;
BEGIN
	SELECT run.runtime_session_id INTO run_session FROM decodex.managed_runs AS run
	WHERE run.managed_run_id = NEW.managed_run_id AND run.project_id = NEW.project_id;
	SELECT profile.role INTO snapshot_role
	FROM decodex.runtime_sessions AS session
	JOIN decodex.profile_snapshots AS profile USING (profile_snapshot_id)
	WHERE session.runtime_session_id = NEW.runtime_session_id;
	IF snapshot_role::text <> NEW.role::text
		OR (NEW.role = 'task' AND NEW.runtime_session_id <> run_session)
	THEN
		RAISE EXCEPTION 'execution assignment is not exact-run Task/Reviewer identity'
			USING ERRCODE = '23514', CONSTRAINT = 'managed_run_assignment_scope';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_managed_run_command_owner(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_managed_run_command_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE owner_name name;
BEGIN
	SELECT pg_catalog.pg_get_userbyid(class.relowner) INTO owner_name
	FROM pg_catalog.pg_class AS class WHERE class.oid = TG_RELID;
	IF current_user::name <> owner_name THEN
		RAISE EXCEPTION 'ManagedRun state is command-owned'
			USING ERRCODE = '42501', CONSTRAINT = 'managed_run_command_owner';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_managed_run_event_namespace(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_managed_run_event_namespace() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE owner_name name;
DECLARE linked boolean := false;
BEGIN
	SELECT pg_catalog.pg_get_userbyid(class.relowner) INTO owner_name
	FROM pg_catalog.pg_class AS class WHERE class.oid = TG_RELID;
	IF TG_TABLE_NAME = 'activity' THEN
		linked := NEW.aggregate_kind = 'managed_run'
			OR NEW.event_kind LIKE 'managed_run_%'
			OR pg_catalog.jsonb_path_exists(NEW.payload, '$.** ? (
				@.aggregate_kind == "managed_run" || @.kind == "managed_run" ||
				@.event_kind like_regex "^managed_run_" ||
				exists(@.managed_run) || exists(@.managed_run_id) ||
				exists(@.effect_barrier) || exists(@.effect_barrier_id)
			)');
		IF TG_OP = 'UPDATE' THEN
			linked := linked OR OLD.aggregate_kind = 'managed_run'
				OR OLD.event_kind LIKE 'managed_run_%'
				OR pg_catalog.jsonb_path_exists(OLD.payload, '$.** ? (
					@.aggregate_kind == "managed_run" || @.kind == "managed_run" ||
					@.event_kind like_regex "^managed_run_" ||
					exists(@.managed_run) || exists(@.managed_run_id) ||
					exists(@.effect_barrier) || exists(@.effect_barrier_id)
				)');
		END IF;
	ELSE
		IF EXISTS (
			SELECT 1 FROM pg_catalog.jsonb_path_query(
				NEW.payload, '$.**.activity_sequence'
			) AS link(value)
			WHERE pg_catalog.jsonb_typeof(link.value) NOT IN ('number', 'string')
				OR link.value #>> '{}' !~ '^[0-9]+$'
		) THEN
			RAISE EXCEPTION 'ManagedRun activity/outbox link is malformed'
				USING ERRCODE = '42501', CONSTRAINT = 'managed_run_event_namespace';
		END IF;
		linked := NEW.aggregate_kind = 'managed_run'
			OR pg_catalog.jsonb_path_exists(NEW.payload, '$.** ? (
				@.aggregate_kind == "managed_run" || @.kind == "managed_run" ||
				@.event_kind like_regex "^managed_run_" ||
				exists(@.managed_run) || exists(@.managed_run_id) ||
				exists(@.effect_barrier) || exists(@.effect_barrier_id)
			)') OR EXISTS (
				SELECT 1 FROM pg_catalog.jsonb_path_query(
					NEW.payload, '$.**.activity_sequence'
				) AS link(value)
				JOIN decodex.activity AS activity ON activity.sequence = CASE
					WHEN pg_catalog.jsonb_typeof(link.value) IN ('number', 'string')
						AND link.value #>> '{}' ~ '^[0-9]+$'
					THEN (link.value #>> '{}')::bigint
				END WHERE activity.aggregate_kind = 'managed_run'
					OR activity.event_kind LIKE 'managed_run_%'
					OR pg_catalog.jsonb_path_exists(activity.payload, '$.** ? (
						@.aggregate_kind == "managed_run" || @.kind == "managed_run" ||
						@.event_kind like_regex "^managed_run_" ||
						exists(@.managed_run) || exists(@.managed_run_id) ||
						exists(@.effect_barrier) || exists(@.effect_barrier_id)
					)')
			);
		IF TG_OP = 'UPDATE' THEN
			IF EXISTS (
				SELECT 1 FROM pg_catalog.jsonb_path_query(
					OLD.payload, '$.**.activity_sequence'
				) AS link(value)
				WHERE pg_catalog.jsonb_typeof(link.value) NOT IN ('number', 'string')
					OR link.value #>> '{}' !~ '^[0-9]+$'
			) THEN
				RAISE EXCEPTION 'ManagedRun activity/outbox link is malformed'
					USING ERRCODE = '42501', CONSTRAINT = 'managed_run_event_namespace';
			END IF;
			linked := linked OR OLD.aggregate_kind = 'managed_run'
				OR pg_catalog.jsonb_path_exists(OLD.payload, '$.** ? (
					@.aggregate_kind == "managed_run" || @.kind == "managed_run" ||
					@.event_kind like_regex "^managed_run_" ||
					exists(@.managed_run) || exists(@.managed_run_id) ||
					exists(@.effect_barrier) || exists(@.effect_barrier_id)
				)') OR EXISTS (
					SELECT 1 FROM pg_catalog.jsonb_path_query(
						OLD.payload, '$.**.activity_sequence'
					) AS link(value)
					JOIN decodex.activity AS activity ON activity.sequence = CASE
						WHEN pg_catalog.jsonb_typeof(link.value) IN ('number', 'string')
							AND link.value #>> '{}' ~ '^[0-9]+$'
						THEN (link.value #>> '{}')::bigint
					END WHERE activity.aggregate_kind = 'managed_run'
						OR activity.event_kind LIKE 'managed_run_%'
						OR pg_catalog.jsonb_path_exists(activity.payload, '$.** ? (
							@.aggregate_kind == "managed_run" || @.kind == "managed_run" ||
							@.event_kind like_regex "^managed_run_" ||
							exists(@.managed_run) || exists(@.managed_run_id) ||
							exists(@.effect_barrier) || exists(@.effect_barrier_id)
						)')
				);
		END IF;
	END IF;
	IF linked AND current_user::name <> owner_name THEN
		IF TG_TABLE_NAME = 'activity' OR TG_OP = 'INSERT' THEN
			RAISE EXCEPTION 'ManagedRun activity/outbox namespace is command-owned'
				USING ERRCODE = '42501', CONSTRAINT = 'managed_run_event_namespace';
		ELSIF NEW.id IS DISTINCT FROM OLD.id
			OR NEW.effect_key IS DISTINCT FROM OLD.effect_key
			OR NEW.aggregate_kind IS DISTINCT FROM OLD.aggregate_kind
			OR NEW.aggregate_id IS DISTINCT FROM OLD.aggregate_id
			OR NEW.aggregate_revision IS DISTINCT FROM OLD.aggregate_revision
			OR NEW.payload IS DISTINCT FROM OLD.payload
			OR NEW.created_at IS DISTINCT FROM OLD.created_at
		THEN
			RAISE EXCEPTION 'ManagedRun outbox authority fields are command-owned'
				USING ERRCODE = '42501', CONSTRAINT = 'managed_run_event_namespace';
		END IF;
	END IF;
	RETURN NEW;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
	RAISE EXCEPTION 'ManagedRun activity/outbox link is malformed'
		USING ERRCODE = '42501', CONSTRAINT = 'managed_run_event_namespace';
END
$_$;


--
-- Name: enforce_managed_run_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_managed_run_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF TG_OP = 'INSERT' THEN
		IF NEW.lifecycle <> 'waiting' OR NOT NEW.blocked OR NEW.revision <> 1
			OR NEW.updated_at <> NEW.created_at
		THEN
			RAISE EXCEPTION 'new ManagedRun must be inert waiting revision one'
				USING ERRCODE = '23514', CONSTRAINT = 'managed_runs_inert_state';
		END IF;
		RETURN NEW;
	END IF;
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'ManagedRuns cannot be deleted'
			USING ERRCODE = '23514', CONSTRAINT = 'managed_runs_inert_state';
	END IF;
	IF NEW.managed_run_id <> OLD.managed_run_id OR NEW.project_id <> OLD.project_id
		OR NEW.work_item_id <> OLD.work_item_id
		OR NEW.runtime_session_id <> OLD.runtime_session_id
		OR NEW.lifecycle <> 'waiting' OR NOT NEW.blocked
		OR NEW.phase <> OLD.phase OR NEW.created_at <> OLD.created_at
		OR NEW.revision <> OLD.revision + 1 OR NEW.updated_at < OLD.updated_at
		OR (OLD.diverged AND NOT NEW.diverged)
	THEN
		RAISE EXCEPTION 'ManagedRun update must remain monotonic and inert'
			USING ERRCODE = '23514', CONSTRAINT = 'managed_runs_inert_state';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: enforce_objective_completion_coherence(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_objective_completion_coherence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE objective_row decodex.objectives%ROWTYPE;
DECLARE evidence_row decodex.objective_completion_evidence%ROWTYPE;
BEGIN
	IF TG_TABLE_NAME = 'objectives' THEN
		IF NEW.state <> 'achieved' THEN RETURN NEW; END IF;
		SELECT stored.* INTO evidence_row FROM decodex.objective_completion_evidence AS stored
		WHERE stored.evidence_id = NEW.completion_evidence_id;
		IF NOT FOUND OR evidence_row.objective_id <> NEW.objective_id
			OR evidence_row.project_id <> NEW.project_id
			OR evidence_row.objective_revision + 1 <> NEW.revision
		THEN
			RAISE EXCEPTION 'achieved Objective requires exact prior-revision evidence'
				USING ERRCODE = '23514', CONSTRAINT = 'objective_completion_coherence';
		END IF;
		RETURN NEW;
	END IF;
	SELECT stored.* INTO objective_row FROM decodex.objectives AS stored
	WHERE stored.objective_id = NEW.objective_id;
	IF NOT FOUND OR objective_row.project_id <> NEW.project_id
		OR objective_row.state <> 'achieved'
		OR objective_row.completion_evidence_id <> NEW.evidence_id
		OR objective_row.revision <> NEW.objective_revision + 1
	THEN
		RAISE EXCEPTION 'Objective evidence must establish one exact achieved revision'
			USING ERRCODE = '23514', CONSTRAINT = 'objective_completion_coherence';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: enforce_objective_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_objective_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE evidence_row decodex.objective_completion_evidence%ROWTYPE;
BEGIN
	IF TG_OP = 'TRUNCATE' OR TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'Objectives are retained'
			USING ERRCODE = '55000', CONSTRAINT = 'objectives_retained';
	END IF;
	IF TG_OP = 'INSERT' THEN
		IF NEW.state <> 'proposed' OR NEW.revision <> 1
			OR NEW.completion_evidence_id IS NOT NULL OR NEW.updated_at <> NEW.created_at
		THEN
			RAISE EXCEPTION 'Objective insertion must be canonical proposed revision one'
				USING ERRCODE = '23514', CONSTRAINT = 'objectives_canonical_insert';
		END IF;
		RETURN NEW;
	END IF;
	IF OLD.state IN ('achieved','abandoned') THEN
		RAISE EXCEPTION 'terminal Objective is immutable'
			USING ERRCODE = '55000', CONSTRAINT = 'objectives_terminal';
	END IF;
	IF NEW.objective_id IS DISTINCT FROM OLD.objective_id
		OR NEW.project_id IS DISTINCT FROM OLD.project_id
		OR NEW.program_id IS DISTINCT FROM OLD.program_id
		OR NEW.outcome IS DISTINCT FROM OLD.outcome
		OR NEW.acceptance_criteria IS DISTINCT FROM OLD.acceptance_criteria
		OR NEW.validation_criteria IS DISTINCT FROM OLD.validation_criteria
		OR NEW.target_at IS DISTINCT FROM OLD.target_at
		OR NEW.created_at IS DISTINCT FROM OLD.created_at
		OR NEW.revision IS DISTINCT FROM OLD.revision + 1
		OR NEW.updated_at < OLD.updated_at
	THEN
		RAISE EXCEPTION 'Objective identity or revision mutation is invalid'
			USING ERRCODE = '23514', CONSTRAINT = 'objectives_identity_revision';
	END IF;
	IF NEW.state = 'achieved' THEN
		SELECT stored.* INTO evidence_row
		FROM decodex.objective_completion_evidence AS stored
		WHERE stored.evidence_id = NEW.completion_evidence_id;
		IF NOT FOUND OR evidence_row.objective_id <> OLD.objective_id
			OR evidence_row.project_id <> OLD.project_id
			OR evidence_row.objective_revision <> OLD.revision
			OR evidence_row.objective_updated_at <> OLD.updated_at
			OR evidence_row.accepted_at < OLD.updated_at
		THEN
			RAISE EXCEPTION 'Objective achievement evidence must follow its exact prior revision'
				USING ERRCODE = '23514', CONSTRAINT = 'objective_evidence_prior_revision_time';
		END IF;
	END IF;
	IF NOT (
		(OLD.state = 'proposed' AND NEW.state IN ('active','abandoned'))
		OR (OLD.state = 'active' AND NEW.state IN ('blocked','achieved','abandoned'))
		OR (OLD.state = 'blocked' AND NEW.state IN ('active','achieved','abandoned'))
	) THEN
		RAISE EXCEPTION 'Objective lifecycle transition is invalid'
			USING ERRCODE = '23514', CONSTRAINT = 'objectives_invalid_transition';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: enforce_outbox_operation_time(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_outbox_operation_time() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE
	write_at timestamptz := clock_timestamp();
	latest_deadline timestamptz := write_at + 31536000000 * interval '1 millisecond';
BEGIN
	IF NEW.created_at > write_at
		OR NEW.available_at > latest_deadline
		OR (NEW.lease_acquired_at IS NOT NULL AND NEW.lease_acquired_at > write_at)
		OR (NEW.lease_expires_at IS NOT NULL AND NEW.lease_expires_at > latest_deadline)
		OR (NEW.delivered_at IS NOT NULL AND NEW.delivered_at > write_at)
		OR (NEW.dead_lettered_at IS NOT NULL AND NEW.dead_lettered_at > write_at)
		OR (NEW.retain_until IS NOT NULL AND NEW.retain_until > latest_deadline)
	THEN
		RAISE EXCEPTION 'outbox timestamps must be anchored to the database write time'
			USING ERRCODE = '23514', CONSTRAINT = 'outbox_operation_time';
	END IF;

	RETURN NEW;
END
$$;


--
-- Name: enforce_outbox_terminal_retention(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_outbox_terminal_retention() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF TG_OP = 'DELETE' THEN
		IF OLD.state <> 'delivered' OR OLD.retain_until > clock_timestamp() THEN
			RAISE EXCEPTION 'outbox rows may be deleted only after delivered retention is due'
				USING ERRCODE = '55000', CONSTRAINT = 'outbox_retention_pruning_only';
		END IF;

		RETURN OLD;
	END IF;

	IF OLD.state = 'delivered' AND NEW IS DISTINCT FROM OLD THEN
		RAISE EXCEPTION 'delivered outbox rows are immutable until retention pruning'
			USING ERRCODE = '55000', CONSTRAINT = 'outbox_delivered_is_terminal';
	END IF;

	RETURN NEW;
END
$$;


--
-- Name: enforce_policy_identity_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_policy_identity_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF TG_OP = 'TRUNCATE' OR TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'Policy identities are retained'
			USING ERRCODE = '55000', CONSTRAINT = 'policies_retained';
	END IF;
	IF NEW.policy_id IS DISTINCT FROM OLD.policy_id
		OR NEW.project_id IS DISTINCT FROM OLD.project_id
		OR NEW.created_at IS DISTINCT FROM OLD.created_at
		OR NEW.current_revision IS NULL
		OR NEW.current_revision IS DISTINCT FROM coalesce(OLD.current_revision, 0) + 1
	THEN
		RAISE EXCEPTION 'Policy identity mutation is not a legal revision advance'
			USING ERRCODE = '23514', CONSTRAINT = 'policies_revision_advance';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: enforce_process_generation_transition(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_process_generation_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF TG_OP = 'INSERT' THEN
		IF NEW.revision <> 1 OR NEW.state <> 'starting'
			OR NEW.process_id IS NOT NULL
			OR NEW.authority_loss_reason IS NOT NULL
			OR NEW.death_evidence_id IS NOT NULL
		THEN
			RAISE EXCEPTION 'process generation must begin as unbound revision-one starting'
				USING ERRCODE='23514',
					CONSTRAINT='process_generation_initial_state';
		END IF;
		RETURN NEW;
	END IF;

	IF (NEW.generation_id, NEW.account_id, NEW.execution_epoch_id, NEW.runner_identity,
		NEW.intended_boot_id, NEW.control_kind, NEW.isolation_kind,
		NEW.quick_task_prepare_protocol,
		NEW.quick_task_prepare_idempotency_key, NEW.created_at)
		IS DISTINCT FROM
		(OLD.generation_id, OLD.account_id, OLD.execution_epoch_id, OLD.runner_identity,
		OLD.intended_boot_id, OLD.control_kind, OLD.isolation_kind,
		OLD.quick_task_prepare_protocol,
		OLD.quick_task_prepare_idempotency_key, OLD.created_at)
		OR NEW.revision <> OLD.revision + 1
		OR NEW.updated_at < OLD.updated_at
	THEN
		RAISE EXCEPTION 'process generation immutable identity or revision changed'
			USING ERRCODE='23514',
				CONSTRAINT='process_generation_immutable_identity';
	END IF;

	IF (NEW.bound_boot_id, NEW.process_id, NEW.process_start_id,
		NEW.process_group_id, NEW.session_id)
		IS DISTINCT FROM
		(OLD.bound_boot_id, OLD.process_id, OLD.process_start_id,
		OLD.process_group_id, OLD.session_id)
		AND NOT (
			OLD.state = 'starting'
			AND NEW.state = 'starting'
			AND OLD.process_id IS NULL
			AND NEW.process_id IS NOT NULL
		)
	THEN
		RAISE EXCEPTION 'process generation exact process identity changed'
			USING ERRCODE='23514',
				CONSTRAINT='process_generation_immutable_process_identity';
	END IF;

	IF NOT (
		(OLD.state = 'starting' AND NEW.state = 'starting'
			AND OLD.process_id IS NULL AND NEW.process_id IS NOT NULL)
		OR (OLD.state = 'starting' AND NEW.state IN ('ready', 'death_unknown'))
		OR (OLD.state = 'starting' AND NEW.state = 'stopping'
			AND NEW.process_id IS NOT NULL)
		OR (OLD.state = 'ready' AND NEW.state IN ('stopping', 'death_unknown'))
		OR (OLD.state = 'stopping' AND NEW.state IN ('dead', 'death_unknown'))
		OR (OLD.state = 'death_unknown' AND NEW.state IN ('stopping', 'dead'))
	) THEN
		RAISE EXCEPTION 'illegal process generation transition'
			USING ERRCODE='23514',
				CONSTRAINT='process_generation_legal_transition';
	END IF;

	IF NEW.state = 'dead' AND NOT EXISTS (
		SELECT 1
		FROM decodex.process_generation_death_evidence AS evidence
		WHERE (evidence.evidence_id, evidence.generation_id) =
			(NEW.death_evidence_id, NEW.generation_id)
	) THEN
		RAISE EXCEPTION 'dead process generation lacks positive evidence'
			USING ERRCODE='23514',
				CONSTRAINT='process_generation_positive_death';
	END IF;

	RETURN NEW;
END;
$$;


--
-- Name: enforce_program_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_program_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF TG_OP = 'TRUNCATE' OR TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'Programs are retained'
			USING ERRCODE = '55000', CONSTRAINT = 'programs_retained';
	END IF;
	IF TG_OP = 'INSERT' THEN
		IF NEW.state <> 'active' OR NEW.revision <> 1 OR NEW.updated_at <> NEW.created_at THEN
			RAISE EXCEPTION 'Program insertion must be canonical active revision one'
				USING ERRCODE = '23514', CONSTRAINT = 'programs_canonical_insert';
		END IF;
		RETURN NEW;
	END IF;
	IF OLD.state = 'retired' THEN
		RAISE EXCEPTION 'retired Program is immutable'
			USING ERRCODE = '55000', CONSTRAINT = 'programs_retired_terminal';
	END IF;
	IF NEW.program_id IS DISTINCT FROM OLD.program_id
		OR NEW.project_id IS DISTINCT FROM OLD.project_id
		OR NEW.owner_agent_id IS DISTINCT FROM OLD.owner_agent_id
		OR NEW.name IS DISTINCT FROM OLD.name
		OR NEW.responsibility IS DISTINCT FROM OLD.responsibility
		OR NEW.policy_id IS DISTINCT FROM OLD.policy_id
		OR NEW.policy_revision IS DISTINCT FROM OLD.policy_revision
		OR NEW.created_at IS DISTINCT FROM OLD.created_at
		OR NEW.revision IS DISTINCT FROM OLD.revision + 1
		OR NEW.updated_at < OLD.updated_at
	THEN
		RAISE EXCEPTION 'Program identity or revision mutation is invalid'
			USING ERRCODE = '23514', CONSTRAINT = 'programs_identity_revision';
	END IF;
	IF NEW.state IS DISTINCT FROM OLD.state THEN
		IF NOT (
			(OLD.state = 'active' AND NEW.state IN ('needs_attention','blocked','paused','retired'))
			OR (OLD.state = 'needs_attention' AND NEW.state IN ('active','blocked','paused','retired'))
			OR (OLD.state = 'blocked' AND NEW.state IN ('active','needs_attention','paused','retired'))
			OR (OLD.state = 'paused' AND NEW.state IN ('active','retired'))
		) OR NEW.review_interval_days IS DISTINCT FROM OLD.review_interval_days
			OR NEW.next_review_at IS DISTINCT FROM OLD.next_review_at
			OR NEW.metrics IS DISTINCT FROM OLD.metrics OR NEW.signals IS DISTINCT FROM OLD.signals
		THEN
			RAISE EXCEPTION 'Program lifecycle transition is invalid'
				USING ERRCODE = '23514', CONSTRAINT = 'programs_invalid_transition';
		END IF;
	ELSIF NEW.review_interval_days IS NOT DISTINCT FROM OLD.review_interval_days
		AND NEW.next_review_at IS NOT DISTINCT FROM OLD.next_review_at
		AND NEW.metrics IS NOT DISTINCT FROM OLD.metrics
		AND NEW.signals IS NOT DISTINCT FROM OLD.signals
	THEN
		RAISE EXCEPTION 'Program context update is empty'
			USING ERRCODE = '23514', CONSTRAINT = 'programs_noop_update';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: enforce_provider_attempt_binding(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_provider_attempt_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE plan decodex.continuation_plans%ROWTYPE;
DECLARE expected_session_id uuid; expected_session_revision bigint;
DECLARE expected_turn_session_id uuid;
BEGIN
	SELECT * INTO plan FROM decodex.continuation_plans
	WHERE plan_id=NEW.continuation_plan_id;
	expected_session_id:=CASE plan.kind
		WHEN 'context_pack_fallback' THEN plan.fallback_runtime_session_id
		ELSE plan.source_runtime_session_id
	END;
	expected_session_revision:=CASE plan.kind
		WHEN 'initial_thread' THEN plan.source_runtime_session_revision+2
		WHEN 'context_pack_fallback' THEN 3
		ELSE plan.source_runtime_session_revision
	END;
	expected_turn_session_id:=plan.source_runtime_session_id;
	IF plan.plan_id IS NULL
		OR plan.routing_decision_id<>NEW.routing_decision_id
		OR plan.selected_account_id<>NEW.selected_account_id
		OR (
			plan.consumer_kind,plan.consumer_conversation_id,plan.turn_id,
			plan.managed_run_id,plan.managed_run_revision,plan.managed_execution_id
		) IS DISTINCT FROM (
			NEW.consumer_kind,NEW.conversation_id,NEW.turn_id,
			NEW.managed_run_id,NEW.managed_run_revision,NEW.managed_execution_id
		)
		OR (NEW.accepted_runtime_session_id,NEW.accepted_runtime_session_revision)<>
			(expected_session_id,expected_session_revision)
		OR NOT EXISTS (
			SELECT 1 FROM decodex.routing_decisions AS decision
			LEFT JOIN decodex.routing_decisions AS initial_decision
				ON initial_decision.decision_id=decision.initial_decision_id
			JOIN decodex.runtime_sessions AS session
				ON (session.runtime_session_id,session.revision)=(
					NEW.accepted_runtime_session_id,
					NEW.accepted_runtime_session_revision
				)
			JOIN decodex.account_snapshots AS account
				ON account.account_snapshot_id=session.account_snapshot_id
			JOIN decodex.process_generations AS generation
				ON generation.generation_id=NEW.process_generation_id
			JOIN decodex.process_generation_transitions AS transition
				ON (transition.generation_id,transition.revision)=(
					NEW.process_generation_id,NEW.process_generation_revision
				)
			JOIN decodex.process_generation_execution_epochs AS epoch
				ON epoch.execution_epoch_id=generation.execution_epoch_id
			WHERE decision.decision_id=NEW.routing_decision_id
				AND (
					NEW.consumer_kind='managed_run_execution'
						AND decision.authority_shape='managed_run_project_policy'
						AND decision.kind='selected'
						AND decision.selected_account_id=NEW.selected_account_id
					OR NEW.consumer_kind='conversation_turn'
						AND (
							decision.authority_shape=
								'conversation_account_registry'
								AND plan.kind='initial_thread'
								AND decision.kind='selected'
								AND decision.selected_account_id=
									NEW.selected_account_id
							OR decision.authority_shape=
								'conversation_continuation'
								AND decision.kind IS NULL
								AND initial_decision.authority_shape=
									'conversation_account_registry'
								AND initial_decision.kind='selected'
								AND initial_decision.selected_account_id=
									NEW.selected_account_id
								AND decision.account_snapshot_id=
									session.account_snapshot_id
								AND decision.profile_snapshot_id=
									session.profile_snapshot_id
						)
				)
				AND account.source_account_id=NEW.selected_account_id
				AND session.state='active'
				AND generation.account_id=NEW.selected_account_id
				AND generation.execution_epoch_id=NEW.process_execution_epoch_id
				AND generation.revision=NEW.process_generation_revision
				AND generation.state='ready' AND generation.process_id IS NOT NULL
				AND transition.state='ready' AND epoch.retired_at IS NULL
		)
	THEN
		RAISE EXCEPTION 'provider attempt has forged execution authority'
			USING ERRCODE='23514',CONSTRAINT='provider_attempt_authority_complete';
	END IF;

	IF NEW.consumer_kind='conversation_turn' THEN
		IF plan.conversation_revision<=0 OR NOT EXISTS (
			SELECT 1 FROM decodex.conversations AS conversation
			JOIN decodex.turns AS turn ON turn.turn_id=NEW.turn_id
			WHERE conversation.conversation_id=NEW.conversation_id
				AND conversation.revision=plan.conversation_revision
				AND conversation.status='open'
				AND turn.conversation_id=NEW.conversation_id
				AND turn.runtime_session_id=expected_turn_session_id
				AND turn.role='user' AND turn.possible_side_effects='unknown'
				AND turn.status='active' AND turn.revision=1
		) THEN
			RAISE EXCEPTION 'provider attempt Turn authority is incomplete'
				USING ERRCODE='23514',CONSTRAINT='provider_attempt_consumer_complete';
		END IF;
	ELSE
		IF NOT EXISTS (
			SELECT 1 FROM decodex.managed_runs AS run
			WHERE (run.managed_run_id,run.revision)=(
				NEW.managed_run_id,NEW.managed_run_revision
			)
		) THEN
			RAISE EXCEPTION 'provider attempt ManagedRun authority is incomplete'
				USING ERRCODE='23514',CONSTRAINT='provider_attempt_consumer_complete';
		END IF;
	END IF;

	IF plan.kind='same_thread' THEN
		IF NEW.runtime_session_binding_protocol IS NOT NULL
			OR NEW.runtime_session_binding_idempotency_key IS NOT NULL
		THEN
			RAISE EXCEPTION 'same-thread attempt cannot carry a bind receipt'
				USING ERRCODE='23514',CONSTRAINT='provider_attempt_authority_complete';
		END IF;
	ELSIF plan.kind IN ('initial_thread','context_pack_fallback') THEN
		IF NOT EXISTS (
			SELECT 1 FROM decodex.exact_command_receipts AS binding
			JOIN decodex.exact_command_receipts AS fence
				ON fence.protocol_version=binding.request_envelope->>'fence_protocol'
				AND fence.idempotency_key=
					binding.request_envelope->>'fence_idempotency_key'
			WHERE binding.protocol_version=NEW.runtime_session_binding_protocol
				AND binding.idempotency_key=
					NEW.runtime_session_binding_idempotency_key
				AND binding.receipt_state='completed_success'
				AND binding.request_envelope->>'operation'=
					'bind_runtime_session_thread'
				AND binding.request_envelope->>'conversation_id'=plan.conversation_id::text
				AND binding.request_envelope->>'runtime_session_id'=
					NEW.accepted_runtime_session_id::text
				AND binding.request_envelope->>'turn_id'=plan.turn_id::text
				AND binding.request_envelope->>'expected_turn_revision'='1'
				AND binding.request_envelope->>'continuation_plan_id'=plan.plan_id::text
				AND binding.effect_envelope->>'revision'=
					NEW.accepted_runtime_session_revision::text
				AND fence.receipt_state='completed_success'
				AND fence.request_envelope->>'operation'=
					'fence_runtime_session_thread_start'
				AND fence.request_envelope->>'process_generation_id'=
					NEW.process_generation_id::text
				AND fence.request_envelope->>'process_generation_revision'=
					NEW.process_generation_revision::text
				AND fence.request_envelope->>'process_execution_epoch_id'=
					NEW.process_execution_epoch_id::text
		) THEN
			RAISE EXCEPTION 'new-thread attempt lacks its exact bind receipt'
				USING ERRCODE='23514',CONSTRAINT='provider_attempt_authority_complete';
		END IF;
	ELSE
		RAISE EXCEPTION 'provider attempt Continuation Plan kind is unsupported'
			USING ERRCODE='23514',CONSTRAINT='provider_attempt_authority_complete';
	END IF;

	IF NEW.predecessor_attempt_id IS NOT NULL AND NOT EXISTS (
		SELECT 1 FROM decodex.provider_attempts AS predecessor
		WHERE predecessor.attempt_id=NEW.predecessor_attempt_id
			AND predecessor.state='unknown'
			AND predecessor.consumer_kind=NEW.consumer_kind
			AND predecessor.request_id<>NEW.request_id
			AND (
				NEW.consumer_kind='conversation_turn'
					AND predecessor.conversation_id=NEW.conversation_id
					AND predecessor.turn_id<>NEW.turn_id
				OR NEW.consumer_kind='managed_run_execution'
					AND predecessor.managed_run_id=NEW.managed_run_id
					AND predecessor.managed_execution_id<>NEW.managed_execution_id
			)
	) THEN
		RAISE EXCEPTION 'duplicate-risk acknowledgement is not exact'
			USING ERRCODE='23514',
				CONSTRAINT='provider_attempt_duplicate_risk_ack_invalid';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_provider_attempt_transition(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_provider_attempt_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF TG_OP='INSERT' THEN
		IF NEW.revision<>1 OR NEW.state<>'prepared'
			OR NEW.unknown_reason IS NOT NULL
			OR NEW.terminal_evidence_id IS NOT NULL
		THEN
			RAISE EXCEPTION 'provider attempt must begin as revision-one prepared'
				USING ERRCODE='23514',
					CONSTRAINT='provider_attempt_initial_state';
		END IF;
		RETURN NEW;
	END IF;
	IF (
		NEW.attempt_id,NEW.consumer_kind,NEW.conversation_id,NEW.turn_id,
		NEW.managed_run_id,NEW.managed_run_revision,NEW.managed_execution_id,
		NEW.continuation_plan_id,NEW.routing_decision_id,
		NEW.accepted_runtime_session_id,NEW.accepted_runtime_session_revision,
		NEW.selected_account_id,NEW.process_generation_id,
		NEW.process_generation_revision,NEW.process_execution_epoch_id,
		NEW.request_id,NEW.request_digest,NEW.provider_idempotency_key,
		NEW.provider_correlation_key,NEW.predecessor_attempt_id,
		NEW.duplicate_risk_ack_digest,NEW.runtime_session_binding_protocol,
		NEW.runtime_session_binding_idempotency_key,NEW.created_at
	) IS DISTINCT FROM (
		OLD.attempt_id,OLD.consumer_kind,OLD.conversation_id,OLD.turn_id,
		OLD.managed_run_id,OLD.managed_run_revision,OLD.managed_execution_id,
		OLD.continuation_plan_id,OLD.routing_decision_id,
		OLD.accepted_runtime_session_id,OLD.accepted_runtime_session_revision,
		OLD.selected_account_id,OLD.process_generation_id,
		OLD.process_generation_revision,OLD.process_execution_epoch_id,
		OLD.request_id,OLD.request_digest,OLD.provider_idempotency_key,
		OLD.provider_correlation_key,OLD.predecessor_attempt_id,
		OLD.duplicate_risk_ack_digest,OLD.runtime_session_binding_protocol,
		OLD.runtime_session_binding_idempotency_key,OLD.created_at
	) OR NEW.revision<>OLD.revision+1 OR NEW.updated_at<OLD.updated_at
	THEN
		RAISE EXCEPTION 'provider attempt immutable authority or revision changed'
			USING ERRCODE='23514',
				CONSTRAINT='provider_attempt_immutable_authority';
	END IF;
	IF NOT (
		(OLD.state='prepared' AND NEW.state IN ('canceled','dispatch_authorized'))
		OR (
			OLD.state='prepared' AND NEW.state='unknown'
			AND NEW.unknown_reason='restore_projection'
		) OR (
			OLD.state='dispatch_authorized'
			AND NEW.state IN (
				'succeeded','failed_definitive','not_submitted','unknown'
			)
		) OR (
			OLD.state='unknown'
			AND NEW.state IN ('succeeded','failed_definitive','not_submitted')
		)
	) THEN
		RAISE EXCEPTION 'illegal provider attempt transition'
			USING ERRCODE='23514',
				CONSTRAINT='provider_attempt_legal_transition';
	END IF;
	IF NEW.state IN ('succeeded','failed_definitive','not_submitted')
		AND NOT EXISTS (
			SELECT 1 FROM decodex.provider_attempt_positive_evidence AS evidence
			WHERE (
				evidence.evidence_id,evidence.attempt_id,evidence.outcome::text
			)=(NEW.terminal_evidence_id,NEW.attempt_id,NEW.state::text)
		)
	THEN
		RAISE EXCEPTION 'terminal provider attempt lacks exact positive evidence'
			USING ERRCODE='23514',
				CONSTRAINT='provider_attempt_positive_terminal_evidence';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: enforce_provider_attempt_turn_materialization(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_provider_attempt_turn_materialization() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF EXISTS (
		SELECT 1
		FROM decodex.provider_attempts AS attempt
		WHERE attempt.consumer_kind = 'conversation_turn'
			AND attempt.turn_id = NEW.turn_id
			AND (
				attempt.conversation_id <> NEW.conversation_id
				OR attempt.accepted_runtime_session_id <> NEW.runtime_session_id
			)
	) THEN
		RAISE EXCEPTION 'Turn conflicts with one reserved ProviderAttempt identity'
			USING ERRCODE='23514',
				CONSTRAINT='provider_attempt_turn_materialization';
	END IF;
	RETURN NEW;
END;
$$;


--
-- Name: enforce_quota_observation_monotonicity(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_quota_observation_monotonicity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF NEW.observed_at < OLD.observed_at THEN
		RAISE EXCEPTION 'quota observations cannot move backward in time'
			USING ERRCODE = '23514', CONSTRAINT = 'quota_windows_observed_at_monotonic';
	END IF;
	RETURN NEW;
END;
$$;


--
-- Name: enforce_repository_history_completeness(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_repository_history_completeness() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE target_operation_id uuid;
DECLARE target_repository_id uuid;
DECLARE target_evidence_id uuid;
DECLARE allocation_entry boolean := false;
DECLARE terminal_entry boolean := false;
BEGIN
	IF TG_TABLE_NAME = 'repository_authority_transitions' THEN
		IF NOT EXISTS (SELECT 1 FROM decodex.managed_repositories repository
			WHERE repository.repository_id = NEW.repository_id
				AND repository.generation = NEW.generation
				AND repository.authority_tip = NEW.authority_tip
				AND repository.phase = NEW.phase
				AND repository.ambiguity IS NOT DISTINCT FROM NEW.ambiguity
				AND repository.head = NEW.head
				AND repository.active_operation_id IS NOT DISTINCT FROM NEW.active_operation_id)
		THEN
			RAISE EXCEPTION 'repository authority transition has no exact current projection'
				USING ERRCODE = '23514', CONSTRAINT = 'repository_history_completeness';
		END IF;
		IF NEW.transition_kind = 'allocated' THEN
			allocation_entry := true;
			target_repository_id := NEW.repository_id;
			target_evidence_id := NEW.evidence_id;
		ELSIF NEW.transition_kind IN ('register_completed','worktree_ready_completed',
			'commit_completed','operation_ambiguous')
		THEN
			terminal_entry := true;
			target_operation_id := NEW.operation_id;
			target_repository_id := NEW.repository_id;
			target_evidence_id := NEW.evidence_id;
		ELSE
			RETURN NULL;
		END IF;
	ELSIF TG_TABLE_NAME = 'repository_operation_evidence' THEN
		IF NEW.operation_id IS NULL THEN
			allocation_entry := true;
		ELSE
			terminal_entry := true;
			target_operation_id := NEW.operation_id;
		END IF;
		target_repository_id := NEW.repository_id;
		target_evidence_id := NEW.evidence_id;
	ELSIF TG_TABLE_NAME = 'repository_operation_results' THEN
		terminal_entry := true;
		target_operation_id := NEW.operation_id;
		target_repository_id := NEW.repository_id;
		target_evidence_id := NEW.evidence_id;
	ELSIF TG_TABLE_NAME = 'repository_operation_events' THEN
		IF NEW.ordinal <> 2 THEN
			RETURN NULL;
		END IF;
		terminal_entry := true;
		target_operation_id := NEW.operation_id;
		target_repository_id := NEW.repository_id;
		target_evidence_id := NEW.evidence_id;
	ELSE
		RAISE EXCEPTION 'unexpected repository history completeness trigger source'
			USING ERRCODE = '23514', CONSTRAINT = 'repository_history_completeness';
	END IF;

	IF allocation_entry THEN
		IF NOT EXISTS (
			SELECT 1
			FROM decodex.repository_operation_evidence evidence
			JOIN decodex.repository_admissions admission
				ON admission.repository_id = evidence.repository_id
			JOIN decodex.repository_authority_transitions transition
				ON transition.repository_id = evidence.repository_id
				AND transition.generation = 1
				AND transition.evidence_id = evidence.evidence_id
			JOIN decodex.managed_repositories repository
				ON repository.repository_id = transition.repository_id
				AND repository.generation = transition.generation
				AND repository.authority_tip = transition.authority_tip
			WHERE evidence.evidence_id = target_evidence_id
				AND evidence.repository_id = target_repository_id
				AND evidence.operation_id IS NULL AND evidence.kind = 'allocation'
				AND evidence.evidence = pg_catalog.jsonb_build_object(
					'classification','positive',
					'evidence_id',evidence.evidence_id,
					'admission_descriptor',admission.admission_descriptor,
					'vacant_worktree_absolute_path',repository.worktree_absolute_path
				)
				AND transition.transition_kind = 'allocated'
				AND transition.prior_generation IS NULL
				AND transition.prior_authority_tip IS NULL
				AND transition.operation_id IS NULL
				AND transition.phase = 'allocated' AND transition.ambiguity IS NULL
				AND transition.head = admission.admitted_base
				AND transition.active_operation_id IS NULL
				AND repository.project_id = admission.project_id
				AND repository.phase = 'allocated' AND repository.ambiguity IS NULL
				AND repository.head = admission.admitted_base
				AND repository.active_operation_id IS NULL
				AND pg_catalog.rtrim(repository.worktree_absolute_path, '/')
					<> pg_catalog.rtrim(admission.repository_absolute_path, '/')
		) THEN
			RAISE EXCEPTION 'allocation history has no exact admitted generation-one cluster'
				USING ERRCODE = '23514', CONSTRAINT = 'repository_history_completeness';
		END IF;
		RETURN NULL;
	END IF;

	IF terminal_entry THEN
		IF NOT EXISTS (
			SELECT 1
			FROM decodex.repository_operations operation
			JOIN decodex.repository_operation_evidence evidence
				ON evidence.operation_id = operation.operation_id
				AND evidence.repository_id = operation.repository_id
			JOIN decodex.repository_operation_results result
				ON result.operation_id = operation.operation_id
				AND result.repository_id = operation.repository_id
				AND result.evidence_id = evidence.evidence_id
			JOIN decodex.repository_operation_events initial_event
				ON initial_event.operation_id = operation.operation_id
				AND initial_event.ordinal = 1
				AND initial_event.repository_id = operation.repository_id
			JOIN decodex.repository_operation_events terminal_event
				ON terminal_event.operation_id = operation.operation_id
				AND terminal_event.ordinal = 2
				AND terminal_event.repository_id = operation.repository_id
				AND terminal_event.evidence_id = evidence.evidence_id
				AND terminal_event.state = result.state
			JOIN decodex.repository_authority_transitions preparation
				ON preparation.repository_id = operation.repository_id
				AND preparation.generation = operation.expected_generation + 1
				AND preparation.operation_id = operation.operation_id
			JOIN decodex.repository_authority_transitions terminal_transition
				ON terminal_transition.repository_id = operation.repository_id
				AND terminal_transition.generation = operation.expected_generation + 2
				AND terminal_transition.operation_id = operation.operation_id
				AND terminal_transition.evidence_id = evidence.evidence_id
				AND terminal_transition.prior_generation = preparation.generation
				AND terminal_transition.prior_authority_tip = preparation.authority_tip
			JOIN decodex.managed_repositories repository
				ON repository.repository_id = terminal_transition.repository_id
				AND repository.generation = terminal_transition.generation
				AND repository.authority_tip = terminal_transition.authority_tip
			WHERE operation.operation_id = target_operation_id
				AND operation.repository_id = target_repository_id
				AND evidence.evidence_id = target_evidence_id
				AND evidence.kind = (CASE operation.kind
					WHEN 'register' THEN 'registration'::decodex.repository_evidence_kind
					WHEN 'worktree_ready' THEN 'worktree_ready'::decodex.repository_evidence_kind
					WHEN 'commit' THEN 'commit'::decodex.repository_evidence_kind
				END)
				AND initial_event.state = 'possibly_effected'
				AND initial_event.evidence_id IS NULL
				AND preparation.transition_kind = (CASE operation.kind
					WHEN 'register' THEN 'register_prepared'::decodex.repository_authority_transition_kind
					WHEN 'worktree_ready' THEN 'worktree_ready_prepared'::decodex.repository_authority_transition_kind
					WHEN 'commit' THEN 'commit_prepared'::decodex.repository_authority_transition_kind
				END)
				AND preparation.evidence_id IS NULL
				AND preparation.active_operation_id = operation.operation_id
				AND preparation.head = operation.payload->>'expected_head'
				AND terminal_transition.active_operation_id IS NULL
				AND repository.active_operation_id IS NULL
				AND repository.project_id = operation.project_id
				AND repository.allocation_id = operation.allocation_id
				AND repository.worktree_id = operation.worktree_id
				AND repository.worktree_absolute_path = operation.worktree_absolute_path
				AND repository.phase = terminal_transition.phase
				AND repository.ambiguity IS NOT DISTINCT FROM terminal_transition.ambiguity
				AND repository.head = terminal_transition.head
				AND (CASE result.state
					WHEN 'ambiguous' THEN
						terminal_transition.transition_kind = 'operation_ambiguous'
						AND terminal_transition.phase = 'ambiguous'
						AND terminal_transition.ambiguity = result.ambiguity
						AND terminal_transition.head = operation.payload->>'expected_head'
					WHEN 'completed' THEN
						terminal_transition.transition_kind = (CASE operation.kind
							WHEN 'register' THEN 'register_completed'::decodex.repository_authority_transition_kind
							WHEN 'worktree_ready' THEN 'worktree_ready_completed'::decodex.repository_authority_transition_kind
							WHEN 'commit' THEN 'commit_completed'::decodex.repository_authority_transition_kind
						END)
						AND terminal_transition.ambiguity IS NULL
						AND (CASE operation.kind
							WHEN 'register' THEN result.result = pg_catalog.jsonb_build_object(
								'kind','registered','head',operation.payload->>'expected_head'
							) AND terminal_transition.phase = 'registered'
								AND terminal_transition.head = operation.payload->>'expected_head'
							WHEN 'worktree_ready' THEN result.result = pg_catalog.jsonb_build_object(
								'kind','worktree_ready','head',operation.payload->>'expected_head'
							) AND terminal_transition.phase = 'ready'
								AND terminal_transition.head = operation.payload->>'expected_head'
							WHEN 'commit' THEN result.result = pg_catalog.jsonb_build_object(
								'kind','committed','from',operation.payload->>'expected_head',
								'to',operation.payload->>'next_head'
							) AND terminal_transition.phase = 'ready'
								AND terminal_transition.head = operation.payload->>'next_head'
						END)
				END)
		)
		THEN
			RAISE EXCEPTION 'terminal repository history has no exact reconciliation cluster'
				USING ERRCODE = '23514', CONSTRAINT = 'repository_history_completeness';
		END IF;
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_repository_operation_scope(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_repository_operation_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF NOT EXISTS (
		SELECT 1 FROM decodex.repository_admissions admission
		JOIN decodex.managed_repositories repository USING (repository_id)
		WHERE admission.repository_id = NEW.repository_id
			AND admission.project_id = NEW.project_id
			AND admission.admitted_identity = NEW.admitted_identity
			AND admission.admitted_base = NEW.admitted_base
			AND admission.admission_descriptor_digest = NEW.admission_descriptor_digest
			AND admission.repository_absolute_path = NEW.repository_absolute_path
			AND repository.allocation_id = NEW.allocation_id
			AND repository.worktree_id = NEW.worktree_id
			AND repository.worktree_absolute_path = NEW.worktree_absolute_path
			AND repository.generation = NEW.expected_generation + 1
			AND repository.active_operation_id = NEW.operation_id
			AND EXISTS (SELECT 1 FROM decodex.repository_operation_events event
				WHERE event.operation_id = NEW.operation_id AND event.ordinal = 1
					AND event.repository_id = NEW.repository_id
					AND event.state = 'possibly_effected' AND event.evidence_id IS NULL)
			AND EXISTS (SELECT 1 FROM decodex.repository_authority_transitions transition
				WHERE transition.repository_id = NEW.repository_id
					AND transition.generation = repository.generation
					AND transition.authority_tip = repository.authority_tip
					AND transition.operation_id = NEW.operation_id
					AND transition.active_operation_id = NEW.operation_id)
	) THEN
		RAISE EXCEPTION 'repository operation descriptor is outside admitted allocation scope'
			USING ERRCODE = '23514', CONSTRAINT = 'repository_operation_scope';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_role_profile_event_namespace(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_role_profile_event_namespace() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE owner_name name;
DECLARE linked_role_profile boolean := false;
BEGIN
	SELECT pg_catalog.pg_get_userbyid(class.relowner) INTO owner_name
	FROM pg_catalog.pg_class AS class
	WHERE class.oid = TG_RELID;

	IF TG_TABLE_NAME = 'activity' THEN
		linked_role_profile := NEW.aggregate_kind = 'role_profile'
			OR NEW.event_kind IN ('role_profile_bootstrapped', 'role_profile_updated')
			OR NEW.payload->>'aggregate_kind' = 'role_profile'
			OR NEW.payload->>'event_kind' IN ('role_profile_bootstrapped', 'role_profile_updated')
			OR NEW.payload->>'kind' = 'role_profile'
			OR NEW.payload OPERATOR(pg_catalog.?&) ARRAY[
				'role', 'model', 'reasoning_effort', 'service_tier', 'instructions', 'revision'
			];
		IF TG_OP = 'UPDATE' THEN
			linked_role_profile := linked_role_profile
				OR OLD.aggregate_kind = 'role_profile'
				OR OLD.event_kind IN ('role_profile_bootstrapped', 'role_profile_updated')
				OR OLD.payload->>'aggregate_kind' = 'role_profile'
				OR OLD.payload->>'event_kind' IN ('role_profile_bootstrapped', 'role_profile_updated')
				OR OLD.payload->>'kind' = 'role_profile'
				OR OLD.payload OPERATOR(pg_catalog.?&) ARRAY[
					'role', 'model', 'reasoning_effort', 'service_tier', 'instructions', 'revision'
				];
		END IF;
	ELSE
		linked_role_profile := NEW.aggregate_kind = 'role_profile'
			OR NEW.payload->>'aggregate_kind' = 'role_profile'
			OR NEW.payload->>'event_kind' IN ('role_profile_bootstrapped', 'role_profile_updated')
			OR NEW.payload->'payload'->>'kind' = 'role_profile'
			OR EXISTS (
				SELECT 1 FROM decodex.activity AS activity
				WHERE activity.sequence = (NEW.payload->>'activity_sequence')::bigint
					AND activity.aggregate_kind = 'role_profile'
			);
		IF TG_OP = 'UPDATE' THEN
			linked_role_profile := linked_role_profile
				OR OLD.aggregate_kind = 'role_profile'
				OR OLD.payload->>'aggregate_kind' = 'role_profile'
				OR OLD.payload->>'event_kind' IN ('role_profile_bootstrapped', 'role_profile_updated')
				OR OLD.payload->'payload'->>'kind' = 'role_profile';
		END IF;
	END IF;

	IF linked_role_profile AND current_user::name <> owner_name THEN
		IF TG_TABLE_NAME = 'activity' OR TG_OP = 'INSERT' THEN
			RAISE EXCEPTION 'RoleProfile activity/outbox namespace is command-owned'
				USING ERRCODE = '42501', CONSTRAINT = 'role_profile_event_namespace';
		ELSIF NEW.id IS DISTINCT FROM OLD.id
			OR NEW.effect_key IS DISTINCT FROM OLD.effect_key
			OR NEW.aggregate_kind IS DISTINCT FROM OLD.aggregate_kind
			OR NEW.aggregate_id IS DISTINCT FROM OLD.aggregate_id
			OR NEW.aggregate_revision IS DISTINCT FROM OLD.aggregate_revision
			OR NEW.payload IS DISTINCT FROM OLD.payload
			OR NEW.created_at IS DISTINCT FROM OLD.created_at
		THEN
			RAISE EXCEPTION 'RoleProfile outbox authority fields are command-owned'
				USING ERRCODE = '42501', CONSTRAINT = 'role_profile_event_namespace';
		END IF;
	END IF;

	RETURN NEW;
EXCEPTION
	WHEN invalid_text_representation THEN
		RAISE EXCEPTION 'RoleProfile activity/outbox link is malformed'
			USING ERRCODE = '42501', CONSTRAINT = 'role_profile_event_namespace';
END
$$;


--
-- Name: enforce_routing_command_owner(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_routing_command_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE owner_name name;
BEGIN
	SELECT role.rolname INTO owner_name
	FROM pg_catalog.pg_class AS class
	JOIN pg_catalog.pg_roles AS role ON role.oid=class.relowner
	WHERE class.oid=TG_RELID;
	IF current_user::name <> owner_name THEN
		RAISE EXCEPTION 'V14 routing state is writable only by its command owner'
			USING ERRCODE='42501', CONSTRAINT='routing_command_owner';
	END IF;
	IF TG_OP='DELETE' OR TG_OP='TRUNCATE' THEN
		RAISE EXCEPTION 'V14 routing history is retained'
			USING ERRCODE='55000', CONSTRAINT='routing_history_retained';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: enforce_routing_completeness(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_routing_completeness() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE member_count bigint; capability_count bigint; account_count bigint;
DECLARE quota_count bigint; matrix_count bigint; blocker_count bigint;
DECLARE blocker_array_count bigint; lineage_complete boolean;
BEGIN
	IF TG_TABLE_NAME='routing_policy_revisions' THEN
		SELECT pg_catalog.count(*) INTO member_count
		FROM decodex.routing_policy_members
		WHERE routing_policy_id=NEW.routing_policy_id
			AND routing_policy_revision=NEW.revision;
		SELECT pg_catalog.count(*) INTO account_count FROM decodex.accounts;
		IF member_count<>account_count OR EXISTS (
			SELECT 1 FROM decodex.routing_policy_members
			WHERE routing_policy_id=NEW.routing_policy_id
				AND routing_policy_revision=NEW.revision
			GROUP BY routing_policy_id,routing_policy_revision
			HAVING pg_catalog.min(position)<>1
				OR pg_catalog.max(position)<>pg_catalog.count(*)
		) OR EXISTS (
			SELECT account_id FROM decodex.accounts
			EXCEPT
			SELECT account_id FROM decodex.routing_policy_members
			WHERE routing_policy_id=NEW.routing_policy_id
				AND routing_policy_revision=NEW.revision
		) THEN
			RAISE EXCEPTION 'routing policy revision is not a complete account inventory'
				USING ERRCODE='23514',
					CONSTRAINT='routing_policy_complete_inventory';
		END IF;
		IF EXISTS (
			SELECT 1 FROM decodex.routing_policy_required_capabilities
			WHERE routing_policy_id=NEW.routing_policy_id
				AND routing_policy_revision=NEW.revision
			GROUP BY routing_policy_id,routing_policy_revision
			HAVING pg_catalog.min(position)<>1
				OR pg_catalog.max(position)<>pg_catalog.count(*)
				OR pg_catalog.array_agg(capability ORDER BY position)
					<>pg_catalog.array_agg(capability ORDER BY capability)
		) THEN
			RAISE EXCEPTION 'required capability positions are not contiguous'
				USING ERRCODE='23514',
					CONSTRAINT='routing_policy_capabilities_contiguous';
		END IF;
		RETURN NULL;
	END IF;

	IF TG_TABLE_NAME='routing_compatibility_evidence' THEN
		SELECT pg_catalog.count(*) INTO capability_count
		FROM decodex.routing_capability_evidence
		WHERE evidence_id=NEW.evidence_id;
		IF capability_count<>8 OR EXISTS (
			SELECT 1 FROM decodex.routing_capability_evidence
			WHERE evidence_id=NEW.evidence_id
			GROUP BY evidence_id
			HAVING pg_catalog.min(position)<>1
				OR pg_catalog.max(position)<>8
				OR pg_catalog.count(*)<>8
		) THEN
			RAISE EXCEPTION 'compatibility evidence lacks the closed capability projection'
				USING ERRCODE='23514',
					CONSTRAINT='routing_evidence_complete_capabilities';
		END IF;
		RETURN NULL;
	END IF;

	SELECT pg_catalog.count(*) INTO member_count
	FROM decodex.routing_snapshot_members WHERE snapshot_id=NEW.snapshot_id;
	IF NEW.authority_shape='conversation_account_registry' THEN
		SELECT pg_catalog.count(*) INTO account_count
		FROM decodex.accounts WHERE tombstoned_at IS NULL;
	ELSE
		SELECT pg_catalog.count(*) INTO account_count
		FROM decodex.routing_policy_members
		WHERE routing_policy_id=NEW.routing_policy_id
			AND routing_policy_revision=NEW.routing_policy_revision;
	END IF;
	SELECT pg_catalog.count(*) INTO quota_count
	FROM decodex.routing_snapshot_quota_facts WHERE snapshot_id=NEW.snapshot_id;
	SELECT pg_catalog.count(*) INTO matrix_count
	FROM decodex.routing_snapshot_capability_facts WHERE snapshot_id=NEW.snapshot_id;
	SELECT pg_catalog.count(*) INTO blocker_count
	FROM decodex.routing_snapshot_blockers WHERE snapshot_id=NEW.snapshot_id;
	SELECT COALESCE(pg_catalog.sum(pg_catalog.cardinality(blockers)),0)
	INTO blocker_array_count
	FROM decodex.routing_snapshot_members WHERE snapshot_id=NEW.snapshot_id;

	IF NEW.authority_shape='conversation_account_registry' THEN
		PERFORM 1
		FROM decodex.conversations
		WHERE conversation_id=NEW.conversation_id
			AND revision=NEW.conversation_revision
			AND status='open'
		FOR UPDATE;
		IF NOT FOUND
			OR account_count<1
			OR account_count>512
			OR member_count<>account_count
			OR quota_count<>member_count*2
			OR matrix_count<>0
			OR blocker_count<>blocker_array_count
			OR NOT EXISTS (
				SELECT 1
				FROM decodex.account_routing_control AS control
				WHERE control.singleton
					AND control.revision=NEW.account_routing_revision
					AND control.mode=NEW.account_selection_mode
					AND control.fixed_account_id IS NOT DISTINCT FROM NEW.fixed_account_id
			)
			OR NOT EXISTS (
				SELECT 1
				FROM decodex.role_profiles AS head
				JOIN decodex.role_profile_revisions AS revision
					ON revision.role=head.role
					AND revision.revision=head.current_revision
				WHERE head.role='task'
					AND head.current_revision=NEW.task_role_profile_revision
			)
			OR EXISTS (
				SELECT 1 FROM decodex.runtime_sessions
				WHERE conversation_id=NEW.conversation_id
			)
			OR EXISTS (
				SELECT 1 FROM decodex.turns
				WHERE conversation_id=NEW.conversation_id OR turn_id=NEW.turn_id
			)
			OR (
				SELECT pg_catalog.count(*)
				FROM decodex.routing_snapshots AS existing
				WHERE existing.authority_shape='conversation_account_registry'
					AND existing.conversation_id=NEW.conversation_id
			)<>1
			OR EXISTS (
				SELECT 1
				FROM decodex.routing_snapshot_members AS member
				WHERE member.snapshot_id=NEW.snapshot_id
					AND member.authority_shape<>NEW.authority_shape
			)
			OR EXISTS (
				SELECT 1
				FROM decodex.routing_snapshot_quota_facts AS quota
				WHERE quota.snapshot_id=NEW.snapshot_id
					AND quota.authority_shape<>NEW.authority_shape
			)
			OR EXISTS (
				SELECT 1
				FROM decodex.routing_snapshot_members
				WHERE snapshot_id=NEW.snapshot_id
				GROUP BY snapshot_id
				HAVING pg_catalog.min(position)<>1
					OR pg_catalog.max(position)<>pg_catalog.count(*)
			)
			OR EXISTS (
				SELECT member.position,member.account_id,member.account_revision
				FROM decodex.routing_snapshot_members AS member
				WHERE member.snapshot_id=NEW.snapshot_id
				EXCEPT
				SELECT ordering.position+1,account.account_id,account.revision
				FROM decodex.accounts AS account
				JOIN decodex.account_routing_order AS ordering
					ON ordering.account_id=account.account_id
				WHERE account.tombstoned_at IS NULL
			)
			OR EXISTS (
				SELECT ordering.position+1,account.account_id,account.revision
				FROM decodex.accounts AS account
				JOIN decodex.account_routing_order AS ordering
					ON ordering.account_id=account.account_id
				WHERE account.tombstoned_at IS NULL
				EXCEPT
				SELECT member.position,member.account_id,member.account_revision
				FROM decodex.routing_snapshot_members AS member
				WHERE member.snapshot_id=NEW.snapshot_id
			)
			OR (
				NEW.fixed_account_id IS NOT NULL
				AND NOT EXISTS (
					SELECT 1
					FROM decodex.routing_snapshot_members AS member
					WHERE member.snapshot_id=NEW.snapshot_id
						AND member.account_id=NEW.fixed_account_id
				)
			)
			OR EXISTS (
				SELECT 1
				FROM decodex.routing_snapshot_members AS member
				JOIN decodex.accounts AS account
					ON account.account_id=member.account_id
				CROSS JOIN LATERAL (
					SELECT COALESCE(
						pg_catalog.array_agg(fact.blocker ORDER BY fact.blocker),
						ARRAY[]::decodex.routing_blocker[]
					) AS blockers
					FROM (
						SELECT source.blocker
						FROM (VALUES
							('account_from_future'::decodex.routing_blocker,
								account.observed_at>NEW.resolved_at
								OR account.credential_store_observed_at>NEW.resolved_at),
							('account_stale'::decodex.routing_blocker,
								account.observed_at<=NEW.resolved_at
									AND NEW.resolved_at-account.observed_at>
										INTERVAL '300 seconds'
								OR account.credential_store_observed_at<=NEW.resolved_at
									AND NEW.resolved_at-
										account.credential_store_observed_at>
										INTERVAL '300 seconds'),
							('account_unavailable'::decodex.routing_blocker,
								account.state='unavailable'
								OR account.credential_store_observation='unavailable'
								OR EXISTS (
									SELECT 1
									FROM decodex.account_operations AS operation
									WHERE operation.account_id=account.account_id
										AND operation.phase NOT IN ('committed','cancelled')
								)),
							('account_unknown'::decodex.routing_blocker,
								account.state='unknown'
								OR account.credential_store_observation='unknown'),
							('account_depleted'::decodex.routing_blocker,
								account.state='depleted'),
							('account_auth_failed'::decodex.routing_blocker,
								account.state='auth_failed'
								OR account.provider_kind IS NULL
								OR account.provider_account_id IS NULL
								OR account.credential_store_schema_version IS DISTINCT FROM 1
								OR account.credential_version IS NULL
								OR account.credential_fingerprint IS NULL
								OR account.credential_writer_operation_id IS NULL
								OR account.credential_store_observation IN (
									'missing','mismatch','provider_mismatch'
								)),
							('account_plugin_unready'::decodex.routing_blocker,
								account.state='plugin_unready'),
							('account_disabled'::decodex.routing_blocker,
								NOT account.enabled OR account.state='disabled')
						) AS source(blocker,applies)
						WHERE source.applies
					) AS fact
				) AS expected
				WHERE member.snapshot_id=NEW.snapshot_id
					AND member.blockers IS DISTINCT FROM expected.blockers
			)
			OR EXISTS (
				SELECT blocker.account_id,blocker.position,blocker.blocker
				FROM decodex.routing_snapshot_blockers AS blocker
				WHERE blocker.snapshot_id=NEW.snapshot_id
				EXCEPT
				SELECT member.account_id,item.ordinality::integer,item.blocker
				FROM decodex.routing_snapshot_members AS member
				CROSS JOIN LATERAL pg_catalog.unnest(member.blockers)
					WITH ORDINALITY AS item(blocker,ordinality)
				WHERE member.snapshot_id=NEW.snapshot_id
			)
			OR EXISTS (
				SELECT member.account_id,item.ordinality::integer,item.blocker
				FROM decodex.routing_snapshot_members AS member
				CROSS JOIN LATERAL pg_catalog.unnest(member.blockers)
					WITH ORDINALITY AS item(blocker,ordinality)
				WHERE member.snapshot_id=NEW.snapshot_id
				EXCEPT
				SELECT blocker.account_id,blocker.position,blocker.blocker
				FROM decodex.routing_snapshot_blockers AS blocker
				WHERE blocker.snapshot_id=NEW.snapshot_id
			)
			OR EXISTS (
				WITH expected AS (
					SELECT member.account_id,definition.position,
						definition.window_class,definition.duration_minutes,
						CASE
							WHEN quota.account_id IS NULL THEN
								'missing'::decodex.account_registry_quota_state
							WHEN quota.error_code IS NULL THEN
								'current'::decodex.account_registry_quota_state
							ELSE 'observation_error'::decodex.account_registry_quota_state
						END AS observation_state,
						quota.used_percent,quota.observed_at_micros,
						quota.resets_at_micros,quota.error_code
					FROM decodex.routing_snapshot_members AS member
					CROSS JOIN (VALUES
						(1::smallint,'five_hour'::decodex.quota_window_class,300::smallint),
						(2::smallint,'seven_day'::decodex.quota_window_class,10080::smallint)
					) AS definition(position,window_class,duration_minutes)
					LEFT JOIN decodex.account_quota_facts AS quota
						ON quota.account_id=member.account_id
						AND quota.duration_minutes=definition.duration_minutes
					WHERE member.snapshot_id=NEW.snapshot_id
				), difference AS (
					(
						SELECT account_id,position,window_class,duration_minutes,
							observation_state,used_percent,observed_at_micros,
							resets_at_micros,error_code
						FROM expected
						EXCEPT
						SELECT account_id,position,window_class,duration_minutes,
							observation_state,used_percent,observed_at_micros,
							resets_at_micros,error_code
						FROM decodex.routing_snapshot_quota_facts
						WHERE snapshot_id=NEW.snapshot_id
					)
					UNION ALL
					(
						SELECT account_id,position,window_class,duration_minutes,
							observation_state,used_percent,observed_at_micros,
							resets_at_micros,error_code
						FROM decodex.routing_snapshot_quota_facts
						WHERE snapshot_id=NEW.snapshot_id
						EXCEPT
						SELECT account_id,position,window_class,duration_minutes,
							observation_state,used_percent,observed_at_micros,
							resets_at_micros,error_code
						FROM expected
					)
				)
				SELECT 1 FROM difference
			)
		THEN
			RAISE EXCEPTION 'Account Registry routing snapshot is incomplete or cross-linked'
				USING ERRCODE='23514',CONSTRAINT='routing_snapshot_complete';
		END IF;
		RETURN NULL;
	END IF;

	IF NEW.authority_shape<>'managed_run_project_policy' THEN
		RAISE EXCEPTION 'routing snapshot authority shape is not selectable'
			USING ERRCODE='23514',CONSTRAINT='routing_snapshot_complete';
	END IF;

	SELECT EXISTS (
		SELECT 1
		FROM decodex.managed_runs AS run
		JOIN decodex.runtime_sessions AS session
			ON (session.runtime_session_id,session.revision)=
				(NEW.runtime_session_id,NEW.runtime_session_revision)
		JOIN decodex.account_snapshots AS account
			ON account.account_snapshot_id=NEW.account_snapshot_id
		JOIN decodex.profile_snapshots AS profile
			ON profile.profile_snapshot_id=NEW.profile_snapshot_id
		JOIN decodex.routing_policy_revisions AS policy
			ON policy.routing_policy_id=NEW.routing_policy_id
			AND policy.revision=NEW.routing_policy_revision
		JOIN decodex.routing_snapshot_members AS sticky
			ON sticky.snapshot_id=NEW.snapshot_id AND sticky.sticky
		WHERE run.managed_run_id=NEW.managed_run_id
			AND run.revision=NEW.managed_run_revision
			AND run.project_id=policy.project_id
			AND (run.runtime_session_id,run.runtime_session_revision)=
				(session.runtime_session_id,session.revision)
			AND (session.account_snapshot_id,session.profile_snapshot_id)=
				(account.account_snapshot_id,profile.profile_snapshot_id)
			AND (account.source_account_id,account.source_revision)=
				(sticky.account_id,NEW.account_snapshot_source_revision)
			AND (profile.role,profile.source_revision)=
				(NEW.required_role,NEW.profile_snapshot_source_revision)
			AND NEW.required_role_profile_revision=profile.source_revision
	) INTO lineage_complete;

	IF member_count<>account_count
		OR quota_count<>member_count*2
		OR matrix_count<>member_count*8
		OR blocker_count<>blocker_array_count
		OR NOT lineage_complete
		OR EXISTS (
			SELECT 1 FROM decodex.routing_snapshot_members
			WHERE snapshot_id=NEW.snapshot_id
				AND authority_shape<>NEW.authority_shape
		)
		OR EXISTS (
			SELECT 1 FROM decodex.routing_snapshot_quota_facts
			WHERE snapshot_id=NEW.snapshot_id
				AND authority_shape<>NEW.authority_shape
		)
		OR (
			SELECT pg_catalog.count(*) FROM decodex.routing_snapshot_members
			WHERE snapshot_id=NEW.snapshot_id AND sticky
		)<>1
		OR EXISTS (
			SELECT 1 FROM decodex.routing_snapshot_members
			WHERE snapshot_id=NEW.snapshot_id
			GROUP BY snapshot_id
			HAVING pg_catalog.min(position)<>1
				OR pg_catalog.max(position)<>pg_catalog.count(*)
		)
		OR EXISTS (
			SELECT member.position,member.account_id,member.disposition
			FROM decodex.routing_snapshot_members AS member
			WHERE member.snapshot_id=NEW.snapshot_id
			EXCEPT
			SELECT policy.position,policy.account_id,policy.disposition
			FROM decodex.routing_policy_members AS policy
			WHERE policy.routing_policy_id=NEW.routing_policy_id
				AND policy.routing_policy_revision=NEW.routing_policy_revision
		)
		OR EXISTS (
			SELECT policy.position,policy.account_id,policy.disposition
			FROM decodex.routing_policy_members AS policy
			WHERE policy.routing_policy_id=NEW.routing_policy_id
				AND policy.routing_policy_revision=NEW.routing_policy_revision
			EXCEPT
			SELECT member.position,member.account_id,member.disposition
			FROM decodex.routing_snapshot_members AS member
			WHERE member.snapshot_id=NEW.snapshot_id
		)
		OR EXISTS (
			SELECT 1 FROM decodex.routing_snapshot_members AS member
			WHERE member.snapshot_id=NEW.snapshot_id
				AND pg_catalog.cardinality(member.blockers)
					<>(
						SELECT pg_catalog.count(*)
						FROM decodex.routing_snapshot_blockers AS blocker
						WHERE blocker.snapshot_id=member.snapshot_id
							AND blocker.account_id=member.account_id
					)
		)
	THEN
		RAISE EXCEPTION 'routing snapshot is incomplete or cross-linked'
			USING ERRCODE='23514',CONSTRAINT='routing_snapshot_complete';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_routing_decision_completeness(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_routing_decision_completeness() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE member_count bigint; quota_count bigint; capability_count bigint;
DECLARE blocker_count bigint; included_count bigint; exclusion_count bigint;
DECLARE lineage_complete boolean;
BEGIN
	SELECT pg_catalog.count(*) INTO member_count
	FROM decodex.routing_decision_member_refs WHERE decision_id=NEW.decision_id;
	SELECT pg_catalog.count(*) INTO quota_count
	FROM decodex.routing_decision_quota_refs WHERE decision_id=NEW.decision_id;
	SELECT pg_catalog.count(*) INTO capability_count
	FROM decodex.routing_decision_capability_refs WHERE decision_id=NEW.decision_id;
	SELECT pg_catalog.count(*) INTO blocker_count
	FROM decodex.routing_decision_blocker_refs WHERE decision_id=NEW.decision_id;
	SELECT pg_catalog.count(*) INTO exclusion_count
	FROM decodex.routing_decision_exclusions WHERE decision_id=NEW.decision_id;

	IF NEW.authority_shape='conversation_continuation' THEN
		SELECT EXISTS (
			SELECT 1
			FROM decodex.conversations AS conversation
			JOIN decodex.runtime_sessions AS session
				ON session.runtime_session_id=NEW.source_runtime_session_id
				AND session.revision=NEW.source_runtime_session_revision
			JOIN decodex.routing_decisions AS initial
				ON initial.decision_id=NEW.initial_decision_id
			JOIN decodex.routing_snapshots AS snapshot
				ON snapshot.snapshot_id=initial.snapshot_id
			JOIN decodex.routing_snapshot_members AS selected
				ON selected.snapshot_id=snapshot.snapshot_id
				AND selected.account_id=initial.selected_account_id
			JOIN decodex.account_snapshots AS account
				ON account.account_snapshot_id=NEW.account_snapshot_id
			JOIN decodex.profile_snapshots AS profile
				ON profile.profile_snapshot_id=NEW.profile_snapshot_id
			WHERE conversation.conversation_id=NEW.conversation_id
				AND conversation.revision=NEW.conversation_revision
				AND conversation.status='open'
				AND session.conversation_id=conversation.conversation_id
				AND session.state='active'
				AND session.account_snapshot_id=account.account_snapshot_id
				AND session.profile_snapshot_id=profile.profile_snapshot_id
				AND initial.authority_shape='conversation_account_registry'
				AND initial.kind='selected'
				AND initial.conversation_id=conversation.conversation_id
				AND snapshot.authority_shape='conversation_account_registry'
				AND account.source_account_id=initial.selected_account_id
				AND account.source_revision=selected.account_revision
				AND account.source_revision=NEW.account_snapshot_source_revision
				AND profile.role='task'
				AND profile.source_revision=snapshot.task_role_profile_revision
				AND profile.source_revision=NEW.profile_snapshot_source_revision
				AND NOT EXISTS (
					SELECT 1
					FROM decodex.runtime_sessions AS other
					WHERE other.conversation_id=conversation.conversation_id
						AND other.runtime_session_id<>session.runtime_session_id
						AND other.state IN ('starting','active')
				)
				AND NOT EXISTS (
					SELECT 1 FROM decodex.turns AS turn_row
					WHERE turn_row.turn_id=NEW.turn_id
						AND NOT (
							turn_row.conversation_id=NEW.conversation_id
							AND turn_row.runtime_session_id=
								NEW.source_runtime_session_id
							AND turn_row.sequence>1
							AND turn_row.role='user'
							AND turn_row.possible_side_effects='unknown'
							AND turn_row.status='active'
							AND turn_row.revision=1
							AND turn_row.completed_at IS NULL
						)
				)
		) INTO lineage_complete;

		IF member_count<>0 OR quota_count<>0 OR capability_count<>0
			OR blocker_count<>0 OR exclusion_count<>0 OR NOT lineage_complete
		THEN
			RAISE EXCEPTION 'Quick Task continuation routing lineage is incomplete or cross-linked'
				USING ERRCODE='23514',CONSTRAINT='routing_decision_complete';
		END IF;
		RETURN NULL;
	END IF;

	IF NEW.authority_shape='conversation_account_registry' THEN
		IF member_count=0
			OR quota_count<>member_count*2
			OR capability_count<>0
			OR NOT EXISTS (
				SELECT 1
				FROM decodex.routing_snapshots AS snapshot
				WHERE snapshot.snapshot_id=NEW.snapshot_id
					AND snapshot.authority_shape=NEW.authority_shape
					AND snapshot.account_routing_revision=NEW.account_routing_revision
					AND snapshot.resolved_at<=NEW.decided_at
					AND (
						snapshot.consumer_kind,
						snapshot.conversation_id,
						snapshot.conversation_revision,
						snapshot.turn_id,
						snapshot.managed_run_id,
						snapshot.managed_run_revision,
						snapshot.managed_execution_id
					) IS NOT DISTINCT FROM (
						NEW.consumer_kind,
						NEW.conversation_id,
						NEW.conversation_revision,
						NEW.turn_id,
						NEW.managed_run_id,
						NEW.managed_run_revision,
						NEW.managed_execution_id
					)
			)
			OR (
				SELECT pg_catalog.count(*)
				FROM decodex.routing_decisions AS existing
				WHERE existing.authority_shape='conversation_account_registry'
					AND existing.conversation_id=NEW.conversation_id
			)<>1
			OR EXISTS (
				SELECT position,account_id
				FROM decodex.routing_snapshot_members
				WHERE snapshot_id=NEW.snapshot_id
				EXCEPT
				SELECT position,account_id
				FROM decodex.routing_decision_member_refs
				WHERE decision_id=NEW.decision_id
			)
			OR EXISTS (
				SELECT position,account_id
				FROM decodex.routing_decision_member_refs
				WHERE decision_id=NEW.decision_id
				EXCEPT
				SELECT position,account_id
				FROM decodex.routing_snapshot_members
				WHERE snapshot_id=NEW.snapshot_id
			)
			OR EXISTS (
				WITH difference AS (
					(
						SELECT account_id,position,window_class,duration_minutes,
							observation_revision,remaining_percent,observed_at_micros,
							resets_at_micros,confidence,observation_state,
							used_percent,error_code
						FROM decodex.routing_snapshot_quota_facts
						WHERE snapshot_id=NEW.snapshot_id
						EXCEPT
						SELECT account_id,position,window_class,duration_minutes,
							observation_revision,remaining_percent,observed_at_micros,
							resets_at_micros,confidence,observation_state,
							used_percent,error_code
						FROM decodex.routing_decision_quota_refs
						WHERE decision_id=NEW.decision_id
					)
					UNION ALL
					(
						SELECT account_id,position,window_class,duration_minutes,
							observation_revision,remaining_percent,observed_at_micros,
							resets_at_micros,confidence,observation_state,
							used_percent,error_code
						FROM decodex.routing_decision_quota_refs
						WHERE decision_id=NEW.decision_id
						EXCEPT
						SELECT account_id,position,window_class,duration_minutes,
							observation_revision,remaining_percent,observed_at_micros,
							resets_at_micros,confidence,observation_state,
							used_percent,error_code
						FROM decodex.routing_snapshot_quota_facts
						WHERE snapshot_id=NEW.snapshot_id
					)
				)
				SELECT 1 FROM difference
			)
			OR EXISTS (
				SELECT blocker.account_id
				FROM decodex.routing_decision_blocker_refs AS blocker
				WHERE blocker.decision_id=NEW.decision_id
				GROUP BY blocker.account_id
				HAVING pg_catalog.min(blocker.position)<>1
					OR pg_catalog.max(blocker.position)<>pg_catalog.count(*)
			)
			OR NEW.kind='selected' AND NOT EXISTS (
				SELECT 1
				FROM decodex.routing_decision_member_refs AS member
				WHERE member.decision_id=NEW.decision_id
					AND member.account_id=NEW.selected_account_id
			)
			OR EXISTS (
				SELECT 1
				FROM decodex.routing_decision_blocker_refs AS blocker
				WHERE blocker.decision_id=NEW.decision_id
					AND blocker.snapshot_id<>NEW.snapshot_id
			)
			OR EXISTS (
				SELECT 1
				FROM decodex.routing_decision_exclusions AS exclusion
				WHERE exclusion.decision_id=NEW.decision_id
					AND exclusion.authority_shape<>NEW.authority_shape
			)
		THEN
			RAISE EXCEPTION 'Account Registry routing decision is incomplete or cross-linked'
				USING ERRCODE='23514',CONSTRAINT='routing_decision_complete';
		END IF;
		RETURN NULL;
	END IF;

	IF NEW.authority_shape<>'managed_run_project_policy' THEN
		RAISE EXCEPTION 'routing decision authority shape is not closed'
			USING ERRCODE='23514',CONSTRAINT='routing_decision_complete';
	END IF;

	SELECT pg_catalog.count(*) INTO included_count
	FROM decodex.routing_decision_member_refs AS reference
	JOIN decodex.routing_snapshot_members AS member
		ON member.snapshot_id=reference.snapshot_id
		AND member.account_id=reference.account_id
	WHERE reference.decision_id=NEW.decision_id
		AND member.disposition='included';

	IF NOT EXISTS (
		SELECT 1 FROM decodex.routing_snapshots AS snapshot
		WHERE snapshot.snapshot_id=NEW.snapshot_id
			AND snapshot.authority_shape=NEW.authority_shape
			AND snapshot.routing_policy_id=NEW.routing_policy_id
			AND snapshot.routing_policy_revision=NEW.routing_policy_revision
			AND (
				snapshot.consumer_kind,
				snapshot.conversation_id,
				snapshot.conversation_revision,
				snapshot.turn_id,
				snapshot.managed_run_id,
				snapshot.managed_run_revision,
				snapshot.managed_execution_id
			) IS NOT DISTINCT FROM (
				NEW.consumer_kind,
				NEW.conversation_id,
				NEW.conversation_revision,
				NEW.turn_id,
				NEW.managed_run_id,
				NEW.managed_run_revision,
				NEW.managed_execution_id
			)
	) OR member_count=0
		OR quota_count<>member_count*2
		OR capability_count<>member_count*8
		OR EXISTS (
			SELECT 1 FROM decodex.routing_decision_quota_refs
			WHERE decision_id=NEW.decision_id
				AND authority_shape<>NEW.authority_shape
		)
		OR EXISTS (
			SELECT 1 FROM decodex.routing_decision_exclusions
			WHERE decision_id=NEW.decision_id
				AND authority_shape<>NEW.authority_shape
		)
		OR EXISTS (
			SELECT position,account_id
			FROM decodex.routing_snapshot_members
			WHERE snapshot_id=NEW.snapshot_id
			EXCEPT
			SELECT position,account_id
			FROM decodex.routing_decision_member_refs
			WHERE decision_id=NEW.decision_id
		)
		OR EXISTS (
			SELECT position,account_id
			FROM decodex.routing_decision_member_refs
			WHERE decision_id=NEW.decision_id
			EXCEPT
			SELECT position,account_id
			FROM decodex.routing_snapshot_members
			WHERE snapshot_id=NEW.snapshot_id
		)
		OR EXISTS (
			SELECT 1
			FROM decodex.routing_decision_member_refs AS reference
			JOIN decodex.routing_snapshot_members AS member
				ON member.snapshot_id=reference.snapshot_id
				AND member.account_id=reference.account_id
			WHERE reference.decision_id=NEW.decision_id
				AND (
					(
						member.disposition='excluded'
						AND NOT EXISTS (
							SELECT 1
							FROM decodex.routing_decision_blocker_refs AS blocker
							WHERE blocker.decision_id=reference.decision_id
								AND blocker.account_id=reference.account_id
								AND blocker.blocker='excluded_by_policy'
						)
					) OR (
						member.disposition='included'
						AND EXISTS (
							SELECT 1
							FROM decodex.routing_decision_blocker_refs AS blocker
							WHERE blocker.decision_id=reference.decision_id
								AND blocker.account_id=reference.account_id
								AND blocker.blocker='excluded_by_policy'
						)
					)
				)
		)
		OR EXISTS (
			SELECT blocker.account_id,blocker.position,blocker.blocker
			FROM decodex.routing_snapshot_blockers AS blocker
			JOIN decodex.routing_snapshot_members AS member
				ON member.snapshot_id=blocker.snapshot_id
				AND member.account_id=blocker.account_id
			WHERE blocker.snapshot_id=NEW.snapshot_id
				AND member.disposition='excluded'
			EXCEPT
			SELECT blocker.account_id,blocker.position,blocker.blocker
			FROM decodex.routing_decision_blocker_refs AS blocker
			JOIN decodex.routing_snapshot_members AS member
				ON member.snapshot_id=blocker.snapshot_id
				AND member.account_id=blocker.account_id
			WHERE blocker.decision_id=NEW.decision_id
				AND member.disposition='excluded'
		)
		OR EXISTS (
			SELECT blocker.account_id,blocker.position,blocker.blocker
			FROM decodex.routing_decision_blocker_refs AS blocker
			JOIN decodex.routing_snapshot_members AS member
				ON member.snapshot_id=blocker.snapshot_id
				AND member.account_id=blocker.account_id
			WHERE blocker.decision_id=NEW.decision_id
				AND member.disposition='excluded'
			EXCEPT
			SELECT blocker.account_id,blocker.position,blocker.blocker
			FROM decodex.routing_snapshot_blockers AS blocker
			JOIN decodex.routing_snapshot_members AS member
				ON member.snapshot_id=blocker.snapshot_id
				AND member.account_id=blocker.account_id
			WHERE blocker.snapshot_id=NEW.snapshot_id
				AND member.disposition='excluded'
		)
	THEN
		RAISE EXCEPTION 'routing decision evidence is incomplete or cross-linked'
			USING ERRCODE='23514',CONSTRAINT='routing_decision_complete';
	END IF;

	IF NEW.kind='selected' THEN
		IF NOT EXISTS (
			SELECT 1
			FROM decodex.routing_decision_member_refs AS reference
			JOIN decodex.routing_snapshot_members AS member
				ON member.snapshot_id=reference.snapshot_id
				AND member.account_id=reference.account_id
			WHERE reference.decision_id=NEW.decision_id
				AND reference.account_id=NEW.selected_account_id
				AND member.disposition='included'
				AND NOT EXISTS (
					SELECT 1 FROM decodex.routing_decision_blocker_refs AS blocker
					WHERE blocker.decision_id=NEW.decision_id
						AND blocker.account_id=reference.account_id
				)
		) THEN
			RAISE EXCEPTION 'selected route is not independently eligible'
				USING ERRCODE='23514',CONSTRAINT='routing_decision_complete';
		END IF;
	ELSIF NEW.kind='waiting_usage' THEN
		IF included_count=0 OR EXISTS (
			SELECT 1
			FROM decodex.routing_decision_member_refs AS reference
			JOIN decodex.routing_snapshot_members AS member
				ON member.snapshot_id=reference.snapshot_id
				AND member.account_id=reference.account_id
			LEFT JOIN decodex.routing_decision_blocker_refs AS blocker
				ON blocker.decision_id=reference.decision_id
				AND blocker.account_id=reference.account_id
			WHERE reference.decision_id=NEW.decision_id
				AND member.disposition='included'
			GROUP BY reference.account_id
			HAVING pg_catalog.count(blocker.blocker)=0
				OR pg_catalog.bool_or(
					blocker.blocker::text NOT IN (
						'quota_five_hour_depleted','quota_seven_day_depleted'
					)
				)
		) OR exclusion_count=0 THEN
			RAISE EXCEPTION 'waiting_usage is not pure positive quota depletion'
				USING ERRCODE='23514',CONSTRAINT='routing_decision_complete';
		END IF;
	ELSIF NEW.kind='waiting_reconciliation' THEN
		IF included_count=0 OR exclusion_count<>0 OR EXISTS (
			SELECT 1
			FROM decodex.routing_decision_member_refs AS reference
			JOIN decodex.routing_snapshot_members AS member
				ON member.snapshot_id=reference.snapshot_id
				AND member.account_id=reference.account_id
			LEFT JOIN decodex.routing_decision_blocker_refs AS blocker
				ON blocker.decision_id=reference.decision_id
				AND blocker.account_id=reference.account_id
			WHERE reference.decision_id=NEW.decision_id
				AND member.disposition='included'
			GROUP BY reference.account_id
			HAVING pg_catalog.count(blocker.blocker)=0
				OR pg_catalog.bool_or(
					blocker.blocker::text NOT IN (
						'process_generation_unresolved',
						'provider_attempt_unresolved'
					)
				)
		) THEN
			RAISE EXCEPTION 'waiting_reconciliation is not a pure unresolved authority'
				USING ERRCODE='23514',CONSTRAINT='routing_decision_complete';
		END IF;
	ELSIF NEW.kind='no_route' AND blocker_count=0 THEN
		RAISE EXCEPTION 'NoRoute has no exact blocker cause'
			USING ERRCODE='23514',CONSTRAINT='routing_decision_complete';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_runtime_session_command_owner(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_runtime_session_command_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE owner_name name;
BEGIN
	SELECT pg_catalog.pg_get_userbyid(class.relowner) INTO owner_name
	FROM pg_catalog.pg_class AS class WHERE class.oid = TG_RELID;

	IF current_user::name <> owner_name THEN
		RAISE EXCEPTION 'RuntimeSession state is command-owned'
			USING ERRCODE = '42501', CONSTRAINT = 'runtime_session_command_owner';
	END IF;

	RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END
$$;


--
-- Name: enforce_runtime_session_event_namespace(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_runtime_session_event_namespace() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE owner_name name;
DECLARE linked_runtime_session boolean := false;
-- Complete shapes are object-local: lax array access must not combine fields from siblings.
DECLARE ownership_path CONSTANT pg_catalog.jsonpath := '$.** ? (
	@.aggregate_kind == "runtime_session" ||
	@.kind == "runtime_session" ||
	@.event_kind == "runtime_session_recorded" ||
	@.event_kind == "runtime_session_created" ||
	@.event_kind == "runtime_session_transitioned" ||
	(
		@.type() == "object" &&
		exists(@.runtime_session_id) && exists(@.conversation_id) &&
		exists(@.profile_snapshot_id) && exists(@.account_snapshot_id) &&
		exists(@.codex_thread_id) && exists(@.last_known_turn_id) &&
		exists(@.state) && exists(@.revision) && exists(@.created_at) &&
		exists(@.updated_at) && exists(@.ended_at)
	) ||
	(
		@.type() == "object" &&
		exists(@.profile_snapshot_id) && exists(@.source_profile_id) &&
		exists(@.role) && exists(@.model) && exists(@.reasoning_effort) &&
		exists(@.service_tier) && exists(@.instructions_digest) &&
		exists(@.instructions) && exists(@.provenance) &&
		exists(@.source_revision) && exists(@.created_at)
	) ||
	(
		@.type() == "object" &&
		exists(@.account_snapshot_id) && exists(@.source_account_id) &&
		exists(@.display_label) && exists(@.observed_state) &&
		exists(@.source_revision) && exists(@.created_at)
	)
)';
BEGIN
	SELECT pg_catalog.pg_get_userbyid(class.relowner) INTO owner_name
	FROM pg_catalog.pg_class AS class WHERE class.oid = TG_RELID;

	IF TG_TABLE_NAME = 'activity' THEN
		linked_runtime_session := NEW.aggregate_kind = 'runtime_session'
			OR NEW.event_kind IN ('runtime_session_recorded', 'runtime_session_created',
				'runtime_session_transitioned')
			OR pg_catalog.jsonb_path_exists(NEW.payload, ownership_path);
		IF TG_OP = 'UPDATE' THEN
			linked_runtime_session := linked_runtime_session
				OR OLD.aggregate_kind = 'runtime_session'
				OR OLD.event_kind IN ('runtime_session_recorded', 'runtime_session_created',
					'runtime_session_transitioned')
				OR pg_catalog.jsonb_path_exists(OLD.payload, ownership_path);
		END IF;
	ELSIF TG_TABLE_NAME = 'outbox' THEN
		linked_runtime_session := NEW.aggregate_kind = 'runtime_session'
			OR pg_catalog.jsonb_path_exists(NEW.payload, ownership_path)
			OR EXISTS (
				SELECT 1
				FROM pg_catalog.jsonb_path_query(
					NEW.payload, '$.**.activity_sequence'
				) AS link(value)
				JOIN decodex.activity AS activity ON activity.sequence = CASE
					WHEN pg_catalog.jsonb_typeof(link.value) IN ('number', 'string')
						AND link.value #>> '{}' ~ '^[0-9]+$'
					THEN (link.value #>> '{}')::bigint
				END
				WHERE (activity.aggregate_kind = 'runtime_session'
						OR activity.event_kind IN ('runtime_session_recorded',
							'runtime_session_created', 'runtime_session_transitioned')
						OR pg_catalog.jsonb_path_exists(activity.payload, ownership_path))
			);
		IF TG_OP = 'UPDATE' THEN
			linked_runtime_session := linked_runtime_session
				OR OLD.aggregate_kind = 'runtime_session'
				OR pg_catalog.jsonb_path_exists(OLD.payload, ownership_path)
				OR EXISTS (
					SELECT 1
					FROM pg_catalog.jsonb_path_query(
						OLD.payload, '$.**.activity_sequence'
					) AS link(value)
					JOIN decodex.activity AS activity ON activity.sequence = CASE
						WHEN pg_catalog.jsonb_typeof(link.value) IN ('number', 'string')
							AND link.value #>> '{}' ~ '^[0-9]+$'
						THEN (link.value #>> '{}')::bigint
					END
					WHERE (activity.aggregate_kind = 'runtime_session'
						OR activity.event_kind IN ('runtime_session_recorded',
							'runtime_session_created', 'runtime_session_transitioned')
						OR pg_catalog.jsonb_path_exists(activity.payload, ownership_path))
				);
		END IF;
	ELSE
		RAISE EXCEPTION 'RuntimeSession event namespace has unexpected trigger relation'
			USING ERRCODE = '42501', CONSTRAINT = 'runtime_session_event_namespace';
	END IF;

	IF linked_runtime_session AND current_user::name <> owner_name THEN
		IF TG_TABLE_NAME = 'activity' OR TG_OP = 'INSERT' THEN
			RAISE EXCEPTION 'RuntimeSession activity/outbox namespace is command-owned'
				USING ERRCODE = '42501', CONSTRAINT = 'runtime_session_event_namespace';
		ELSIF NEW.id IS DISTINCT FROM OLD.id
			OR NEW.effect_key IS DISTINCT FROM OLD.effect_key
			OR NEW.aggregate_kind IS DISTINCT FROM OLD.aggregate_kind
			OR NEW.aggregate_id IS DISTINCT FROM OLD.aggregate_id
			OR NEW.aggregate_revision IS DISTINCT FROM OLD.aggregate_revision
			OR NEW.payload IS DISTINCT FROM OLD.payload
			OR NEW.created_at IS DISTINCT FROM OLD.created_at
		THEN
			RAISE EXCEPTION 'RuntimeSession outbox authority fields are command-owned'
				USING ERRCODE = '42501', CONSTRAINT = 'runtime_session_event_namespace';
		END IF;
	END IF;

	RETURN NEW;
EXCEPTION
	WHEN invalid_text_representation OR numeric_value_out_of_range THEN
		RAISE EXCEPTION 'RuntimeSession activity/outbox link is malformed'
			USING ERRCODE = '42501', CONSTRAINT = 'runtime_session_event_namespace';
END
$_$;


--
-- Name: enforce_runtime_session_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_runtime_session_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE parent_status decodex.conversation_status;
DECLARE transition_time timestamptz;
BEGIN
	SELECT status INTO parent_status FROM decodex.conversations
	WHERE conversation_id=NEW.conversation_id FOR UPDATE;
	IF parent_status<>'open' THEN
		RAISE EXCEPTION 'runtime session requires an open conversation';
	END IF;
	IF TG_OP='INSERT' THEN
		IF NEW.state NOT IN ('starting','active') OR NEW.revision<>1 THEN
			RAISE EXCEPTION 'illegal initial runtime session state';
		END IF;
		NEW.created_at:=pg_catalog.clock_timestamp();
		NEW.updated_at:=NEW.created_at;
		NEW.ended_at:=NULL;
		RETURN NEW;
	END IF;
	IF OLD.state IN ('ended','diverged') THEN
		RAISE EXCEPTION 'terminal runtime session is immutable';
	END IF;
	IF NEW.runtime_session_id<>OLD.runtime_session_id
		OR NEW.conversation_id<>OLD.conversation_id
		OR NEW.profile_snapshot_id<>OLD.profile_snapshot_id
		OR NEW.account_snapshot_id<>OLD.account_snapshot_id
		OR NEW.created_at IS DISTINCT FROM OLD.created_at
		OR NEW.revision<>OLD.revision+1
		OR NOT (
			(
				OLD.state='starting' AND NEW.state='starting'
				AND OLD.codex_thread_id IS NULL AND NEW.codex_thread_id IS NULL
				AND OLD.last_known_turn_id IS NULL AND NEW.last_known_turn_id IS NULL
				AND OLD.thread_start_request_id IS NULL
				AND OLD.thread_start_request_sha256 IS NULL
				AND OLD.thread_start_response_id IS NULL
				AND OLD.thread_start_response_sha256 IS NULL
				AND NEW.thread_start_request_id IS NOT NULL
				AND NEW.thread_start_request_sha256 IS NOT NULL
				AND NEW.thread_start_response_id IS NULL
				AND NEW.thread_start_response_sha256 IS NULL
			) OR (
				OLD.state='starting' AND NEW.state='active'
				AND OLD.codex_thread_id IS NULL AND NEW.codex_thread_id IS NOT NULL
				AND NEW.last_known_turn_id IS NULL
				AND NEW.thread_start_request_id IS NOT DISTINCT FROM
					OLD.thread_start_request_id
				AND NEW.thread_start_request_sha256 IS NOT DISTINCT FROM
					OLD.thread_start_request_sha256
				AND OLD.thread_start_response_id IS NULL
				AND OLD.thread_start_response_sha256 IS NULL
				AND NEW.thread_start_response_id IS NOT NULL
				AND NEW.thread_start_response_sha256 IS NOT NULL
			) OR (
				OLD.state='active' AND NEW.state='active'
				AND NEW.codex_thread_id IS NOT DISTINCT FROM OLD.codex_thread_id
				AND NEW.thread_start_request_id IS NOT DISTINCT FROM
					OLD.thread_start_request_id
				AND NEW.thread_start_request_sha256 IS NOT DISTINCT FROM
					OLD.thread_start_request_sha256
				AND NEW.thread_start_response_id IS NOT DISTINCT FROM
					OLD.thread_start_response_id
				AND NEW.thread_start_response_sha256 IS NOT DISTINCT FROM
					OLD.thread_start_response_sha256
				AND NEW.last_known_turn_id IS NOT NULL
				AND NEW.last_known_turn_id IS DISTINCT FROM OLD.last_known_turn_id
			) OR (
				OLD.state IN ('starting','active')
				AND NEW.state IN ('ended','diverged')
				AND NEW.codex_thread_id IS NOT DISTINCT FROM OLD.codex_thread_id
				AND NEW.last_known_turn_id IS NOT DISTINCT FROM OLD.last_known_turn_id
				AND NEW.thread_start_request_id IS NOT DISTINCT FROM
					OLD.thread_start_request_id
				AND NEW.thread_start_request_sha256 IS NOT DISTINCT FROM
					OLD.thread_start_request_sha256
				AND NEW.thread_start_response_id IS NOT DISTINCT FROM
					OLD.thread_start_response_id
				AND NEW.thread_start_response_sha256 IS NOT DISTINCT FROM
					OLD.thread_start_response_sha256
			)
		)
	THEN
		RAISE EXCEPTION 'illegal runtime session transition';
	END IF;
	IF NEW.state='ended' AND EXISTS (
		SELECT 1 FROM decodex.turns
		WHERE runtime_session_id=NEW.runtime_session_id AND status='active'
	) THEN
		RAISE EXCEPTION 'runtime session has active turns';
	END IF;
	transition_time:=pg_catalog.clock_timestamp();
	NEW.updated_at:=transition_time;
	NEW.ended_at:=CASE
		WHEN NEW.state IN ('ended','diverged') THEN transition_time ELSE NULL
	END;
	RETURN NEW;
END
$$;


--
-- Name: enforce_turn_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_turn_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE parent_state decodex.runtime_session_state;
DECLARE parent_status decodex.conversation_status;
DECLARE transition_time timestamptz;
DECLARE initial_refusal_proven boolean:=false;
DECLARE proof_conversation_revision bigint;
DECLARE proof_plan_id uuid;
DECLARE proof_routing_decision_id uuid;
DECLARE proof_selected_account_id uuid;
DECLARE proof_process_generation_id uuid;
BEGIN
	IF pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN
		RAISE EXCEPTION 'turn hierarchy writes require READ COMMITTED'
			USING ERRCODE='40001';
	END IF;
	SELECT conversation.status,session.state
	INTO parent_status,parent_state
	FROM decodex.conversations AS conversation
	JOIN decodex.runtime_sessions AS session
		ON session.conversation_id=conversation.conversation_id
	WHERE conversation.conversation_id=NEW.conversation_id
		AND session.runtime_session_id=NEW.runtime_session_id
	FOR UPDATE OF conversation;
	IF TG_OP='INSERT' THEN
		IF parent_status<>'open' OR NEW.status<>'active' OR NEW.revision<>1
			OR (
				parent_state='starting'
				AND (
					NEW.role<>'user' OR NEW.sequence<>1
					OR NEW.possible_side_effects<>'unknown'
					OR EXISTS (
						SELECT 1 FROM decodex.turns AS existing
						WHERE existing.conversation_id=NEW.conversation_id
					)
					OR NOT EXISTS (
						SELECT 1
						FROM decodex.routing_decisions AS decision
						JOIN decodex.routing_snapshots AS snapshot
							ON snapshot.snapshot_id=decision.snapshot_id
						JOIN decodex.continuation_plans AS plan
							ON plan.routing_decision_id=decision.decision_id
						WHERE decision.authority_shape=
								'conversation_account_registry'
							AND snapshot.authority_shape=
								'conversation_account_registry'
							AND decision.kind='selected'
							AND decision.consumer_kind='conversation_turn'
							AND (decision.conversation_id,decision.turn_id)=(
								NEW.conversation_id,NEW.turn_id
							)
							AND snapshot.runtime_session_id IS NULL
							AND snapshot.runtime_session_revision IS NULL
							AND snapshot.account_snapshot_id IS NULL
							AND snapshot.account_snapshot_source_revision IS NULL
							AND snapshot.profile_snapshot_id IS NULL
							AND snapshot.profile_snapshot_source_revision IS NULL
							AND plan.kind='initial_thread'
							AND plan.consumer_conversation_id=NEW.conversation_id
							AND plan.turn_id=NEW.turn_id
							AND plan.source_runtime_session_id=NEW.runtime_session_id
							AND plan.source_runtime_session_revision=1
					)
				)
			)
			OR parent_state NOT IN ('starting','active')
		THEN
			RAISE EXCEPTION 'turn requires an active parent or exact initial admission';
		END IF;
		NEW.created_at:=pg_catalog.clock_timestamp();
		NEW.updated_at:=NEW.created_at;
		NEW.completed_at:=NULL;
		RETURN NEW;
	END IF;
	IF OLD.status IN ('completed','failed') THEN
		RAISE EXCEPTION 'terminal turn is immutable';
	END IF;
	IF parent_state='starting'
		AND OLD.status='active' AND OLD.revision=1
		AND NEW.status='failed' AND NEW.revision=2
		AND OLD.role='user' AND OLD.sequence=1
	THEN
		SELECT conversation.revision,plan.plan_id,plan.routing_decision_id,
			plan.selected_account_id,generation.generation_id
		INTO proof_conversation_revision,proof_plan_id,
			proof_routing_decision_id,proof_selected_account_id,
			proof_process_generation_id
		FROM decodex.conversations AS conversation
		JOIN decodex.runtime_sessions AS session
			ON (session.runtime_session_id,session.conversation_id)=(
				OLD.runtime_session_id,OLD.conversation_id
			)
		JOIN decodex.continuation_plans AS plan
			ON plan.source_runtime_session_id=session.runtime_session_id
			AND plan.turn_id=OLD.turn_id
		JOIN decodex.exact_command_receipts AS receipt
			ON receipt.request_envelope->>'operation'=
				'prepare_quick_task_process_generation'
			AND receipt.request_envelope->>'turn_id'=OLD.turn_id::text
		JOIN decodex.process_generations AS generation
			ON (generation.quick_task_prepare_protocol,
				generation.quick_task_prepare_idempotency_key)=(
				receipt.protocol_version,receipt.idempotency_key
			)
		WHERE conversation.conversation_id=OLD.conversation_id
		ORDER BY receipt.protocol_version,receipt.idempotency_key
		LIMIT 1;
		initial_refusal_proven:=COALESCE(
			decodex.prove_initial_quick_task_spawn_not_created_exact(
				OLD.conversation_id,proof_conversation_revision,
				OLD.runtime_session_id,1,OLD.turn_id,1,proof_plan_id,
				proof_routing_decision_id,proof_selected_account_id,
				proof_process_generation_id
			),false
		);
	END IF;
	IF parent_status<>'open'
		OR parent_state NOT IN ('starting','active')
		OR NEW.turn_id<>OLD.turn_id
		OR NEW.conversation_id<>OLD.conversation_id
		OR NEW.runtime_session_id<>OLD.runtime_session_id
		OR NEW.sequence<>OLD.sequence OR NEW.role<>OLD.role
		OR NEW.possible_side_effects<>OLD.possible_side_effects
		OR NEW.created_at IS DISTINCT FROM OLD.created_at
		OR NEW.revision<>OLD.revision+1
		OR NEW.status NOT IN ('completed','failed')
		OR (
			parent_state='starting'
			AND (
				OLD.status<>'active' OR OLD.revision<>1 OR NEW.status<>'failed'
				OR NEW.revision<>2 OR OLD.role<>'user' OR OLD.sequence<>1
				OR NOT initial_refusal_proven
				OR NOT EXISTS (
					SELECT 1 FROM decodex.continuation_plans AS plan
					JOIN decodex.routing_decisions AS decision
						ON decision.decision_id=plan.routing_decision_id
					WHERE plan.kind='initial_thread'
						AND plan.source_runtime_session_id=OLD.runtime_session_id
						AND plan.consumer_conversation_id=OLD.conversation_id
						AND plan.turn_id=OLD.turn_id
						AND decision.authority_shape=
							'conversation_account_registry'
						AND decision.kind='selected'
				)
				OR EXISTS (
					SELECT 1 FROM decodex.provider_attempts AS attempt
					WHERE attempt.consumer_kind='conversation_turn'
						AND attempt.conversation_id=OLD.conversation_id
						AND attempt.turn_id=OLD.turn_id
				)
				OR EXISTS (
					SELECT 1 FROM decodex.exact_command_receipts AS receipt
					WHERE receipt.request_envelope->>'operation' IN (
						'fence_runtime_session_thread_start',
						'bind_runtime_session_thread'
					)
						AND receipt.request_envelope->>'runtime_session_id'=
							OLD.runtime_session_id::text
				)
			)
		)
	THEN
		RAISE EXCEPTION 'illegal turn transition';
	END IF;
	IF EXISTS (
		SELECT 1 FROM decodex.history_items
		WHERE turn_id=NEW.turn_id AND status='streaming'
	) THEN
		RAISE EXCEPTION 'turn has streaming items';
	END IF;
	transition_time:=pg_catalog.clock_timestamp();
	NEW.updated_at:=transition_time;
	NEW.completed_at:=transition_time;
	RETURN NEW;
END
$$;


--
-- Name: enforce_waiting_usage_wake_command_owner(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_waiting_usage_wake_command_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE owner_name name;
BEGIN
	SELECT role.rolname INTO owner_name FROM pg_catalog.pg_class AS class
	JOIN pg_catalog.pg_roles AS role ON role.oid=class.relowner WHERE class.oid=TG_RELID;
	IF current_user::name<>owner_name THEN
		RAISE EXCEPTION 'waiting-usage wake state is writable only by its command owner'
			USING ERRCODE='42501', CONSTRAINT='waiting_usage_wake_command_owner';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_waiting_usage_wake_event_namespace(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_waiting_usage_wake_event_namespace() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE owner_name name; linked boolean;
BEGIN
	SELECT role.rolname INTO owner_name FROM pg_catalog.pg_class AS class
	JOIN pg_catalog.pg_roles AS role ON role.oid=class.relowner WHERE class.oid=TG_RELID;
	IF TG_TABLE_NAME='activity' THEN
		linked:=NEW.aggregate_kind IN ('waiting_usage_wake','routing_resolution_request')
			OR NEW.event_kind LIKE 'waiting_usage_wake_%'
			OR pg_catalog.jsonb_path_exists(NEW.payload,'$.** ? (
				exists(@.waiting_usage_wake_id) || exists(@.waiting_usage_wake_transition_id)
				|| exists(@.routing_resolution_request_id))');
		IF TG_OP='UPDATE' THEN
			linked:=linked OR OLD.aggregate_kind IN ('waiting_usage_wake','routing_resolution_request')
				OR OLD.event_kind LIKE 'waiting_usage_wake_%'
				OR pg_catalog.jsonb_path_exists(OLD.payload,'$.** ? (
					exists(@.waiting_usage_wake_id) || exists(@.waiting_usage_wake_transition_id)
					|| exists(@.routing_resolution_request_id))');
		END IF;
		IF linked AND current_user::name<>owner_name THEN
			RAISE EXCEPTION 'waiting-usage wake activity/outbox namespace is command-owned'
				USING ERRCODE='42501', CONSTRAINT='waiting_usage_wake_event_namespace';
		END IF;
	ELSIF TG_TABLE_NAME='outbox' THEN
		linked:=NEW.aggregate_kind IN ('waiting_usage_wake','routing_resolution_request')
			OR pg_catalog.jsonb_path_exists(NEW.payload,'$.** ? (
				exists(@.waiting_usage_wake_id) || exists(@.waiting_usage_wake_transition_id)
				|| exists(@.routing_resolution_request_id))');
		IF TG_OP='UPDATE' THEN
			linked:=linked OR OLD.aggregate_kind IN ('waiting_usage_wake','routing_resolution_request')
				OR pg_catalog.jsonb_path_exists(OLD.payload,'$.** ? (
					exists(@.waiting_usage_wake_id) || exists(@.waiting_usage_wake_transition_id)
					|| exists(@.routing_resolution_request_id))');
		END IF;
		IF linked AND current_user::name<>owner_name THEN
			IF TG_OP='INSERT' THEN
				RAISE EXCEPTION 'waiting-usage wake activity/outbox namespace is command-owned'
					USING ERRCODE='42501', CONSTRAINT='waiting_usage_wake_event_namespace';
			ELSIF NEW.id IS DISTINCT FROM OLD.id OR NEW.effect_key IS DISTINCT FROM OLD.effect_key
			OR NEW.aggregate_kind IS DISTINCT FROM OLD.aggregate_kind
			OR NEW.aggregate_id IS DISTINCT FROM OLD.aggregate_id
			OR NEW.aggregate_revision IS DISTINCT FROM OLD.aggregate_revision
			OR NEW.payload IS DISTINCT FROM OLD.payload OR NEW.created_at IS DISTINCT FROM OLD.created_at
			THEN
				RAISE EXCEPTION 'waiting-usage wake outbox authority fields are command-owned'
					USING ERRCODE='42501', CONSTRAINT='waiting_usage_wake_event_namespace';
			END IF;
		END IF;
	ELSE
		RAISE EXCEPTION 'waiting-usage wake event namespace has unexpected trigger relation'
			USING ERRCODE='42501', CONSTRAINT='waiting_usage_wake_event_namespace';
	END IF;
	RETURN NEW;
END
$_$;


--
-- Name: enforce_waiting_usage_wake_head_projection(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_waiting_usage_wake_head_projection() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE tip decodex.waiting_usage_wake_transitions%ROWTYPE;
BEGIN
	IF TG_OP='DELETE' THEN
		RAISE EXCEPTION 'waiting-usage wake head cannot be deleted'
			USING ERRCODE='23514', CONSTRAINT='waiting_usage_wake_head_projection';
	END IF;
	SELECT * INTO STRICT tip FROM decodex.waiting_usage_wake_transitions
	WHERE (wake_id,revision,transition_id)=(NEW.wake_id,NEW.revision,NEW.transition_id);
	IF tip.registration_operation_id<>NEW.registration_operation_id
		OR tip.routing_decision_id<>NEW.routing_decision_id
		OR tip.routing_decision_revision<>NEW.routing_decision_revision
		OR tip.routing_policy_id<>NEW.routing_policy_id
		OR tip.routing_policy_revision<>NEW.routing_policy_revision
		OR tip.managed_run_id<>NEW.managed_run_id
		OR tip.managed_run_revision<>NEW.managed_run_revision
		OR tip.earliest_ready_at_micros<>NEW.earliest_ready_at_micros
		OR tip.state<>NEW.state OR tip.claim_id IS DISTINCT FROM NEW.claim_id
		OR tip.lease_holder IS DISTINCT FROM NEW.lease_holder
		OR tip.lease_fence_id IS DISTINCT FROM NEW.lease_fence_id
		OR tip.lease_acquired_at IS DISTINCT FROM NEW.lease_acquired_at
		OR tip.lease_expires_at IS DISTINCT FROM NEW.lease_expires_at
		OR tip.terminal_reason IS DISTINCT FROM NEW.terminal_reason
		OR tip.routing_resolution_request_id IS DISTINCT FROM NEW.routing_resolution_request_id
		OR tip.registered_at<>NEW.registered_at OR tip.transitioned_at<>NEW.updated_at
		OR (TG_OP='INSERT' AND NEW.revision<>1)
		OR (TG_OP='UPDATE' AND (
			NEW.wake_id<>OLD.wake_id OR NEW.registration_operation_id<>OLD.registration_operation_id
			OR NEW.routing_decision_id<>OLD.routing_decision_id
			OR NEW.routing_decision_revision<>OLD.routing_decision_revision
			OR NEW.routing_policy_id<>OLD.routing_policy_id
			OR NEW.routing_policy_revision<>OLD.routing_policy_revision
			OR NEW.managed_run_id<>OLD.managed_run_id
			OR NEW.managed_run_revision<>OLD.managed_run_revision
			OR NEW.earliest_ready_at_micros<>OLD.earliest_ready_at_micros
			OR NEW.registered_at<>OLD.registered_at OR NEW.revision<>OLD.revision+1
			OR tip.predecessor_revision<>OLD.revision
			OR tip.predecessor_transition_id<>OLD.transition_id
		))
	THEN
		RAISE EXCEPTION 'waiting-usage wake head is not the exact monotonic ledger tip'
			USING ERRCODE='23514', CONSTRAINT='waiting_usage_wake_head_projection';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_waiting_usage_wake_transition_complete(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_waiting_usage_wake_transition_complete() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE predecessor decodex.waiting_usage_wake_transitions%ROWTYPE;
BEGIN
	IF NEW.revision>1 THEN
		SELECT * INTO STRICT predecessor FROM decodex.waiting_usage_wake_transitions
		WHERE wake_id=NEW.wake_id AND revision=NEW.predecessor_revision
			AND transition_id=NEW.predecessor_transition_id;
		IF predecessor.registration_operation_id<>NEW.registration_operation_id
			OR predecessor.routing_decision_id<>NEW.routing_decision_id
			OR predecessor.routing_decision_revision<>NEW.routing_decision_revision
			OR predecessor.routing_policy_id<>NEW.routing_policy_id
			OR predecessor.routing_policy_revision<>NEW.routing_policy_revision
			OR predecessor.managed_run_id<>NEW.managed_run_id
			OR predecessor.managed_run_revision<>NEW.managed_run_revision
			OR predecessor.earliest_ready_at_micros<>NEW.earliest_ready_at_micros
			OR predecessor.registered_at<>NEW.registered_at
			OR predecessor.state IN ('fired','cancelled','superseded')
			OR (NEW.transition_kind='claimed' AND predecessor.state<>'pending')
			OR (NEW.transition_kind='reclaimed' AND (
				predecessor.state<>'leased'
				OR predecessor.lease_expires_at>NEW.transitioned_at))
			OR (NEW.transition_kind='fired' AND predecessor.state<>'leased')
			OR (NEW.transition_kind='cancelled' AND predecessor.state NOT IN ('pending','leased'))
			OR (NEW.transition_kind='superseded' AND predecessor.state NOT IN ('pending','leased'))
		THEN
			RAISE EXCEPTION 'waiting-usage wake transition has a forged predecessor'
				USING ERRCODE='23514', CONSTRAINT='waiting_usage_wake_transition_chain';
		END IF;
	END IF;
	IF (NEW.transition_kind='registered' AND (
			NEW.request_envelope->>'operation' IS DISTINCT FROM 'register_waiting_usage_wake'
			OR NEW.request_envelope->>'decision_id' IS DISTINCT FROM NEW.routing_decision_id::text
			OR (NEW.request_envelope->>'expected_managed_run_revision')::bigint
				IS DISTINCT FROM NEW.managed_run_revision))
		OR (NEW.transition_kind IN ('claimed','reclaimed') AND (
			NEW.request_envelope->>'operation' IS DISTINCT FROM 'claim_due_waiting_usage_wake'
			OR NEW.request_envelope->>'claim_id' IS DISTINCT FROM NEW.claim_id::text
			OR NEW.request_envelope->>'holder_id' IS DISTINCT FROM NEW.lease_holder::text))
		OR (NEW.transition_kind='fired' AND (
			NEW.request_envelope->>'operation' IS DISTINCT FROM 'fire_waiting_usage_wake'
			OR NEW.request_envelope->>'wake_id' IS DISTINCT FROM NEW.wake_id::text
			OR (NEW.request_envelope->>'expected_revision')::bigint IS DISTINCT FROM predecessor.revision
			OR NEW.request_envelope->>'expected_transition_id' IS DISTINCT FROM predecessor.transition_id::text
			OR NEW.request_envelope->>'holder_id' IS DISTINCT FROM predecessor.lease_holder::text
			OR NEW.request_envelope->>'lease_fence_id' IS DISTINCT FROM predecessor.lease_fence_id::text))
		OR (NEW.transition_kind='cancelled' AND (
			NEW.request_envelope->>'operation' IS DISTINCT FROM 'cancel_waiting_usage_wake'
			OR NEW.request_envelope->>'wake_id' IS DISTINCT FROM NEW.wake_id::text
			OR (NEW.request_envelope->>'expected_revision')::bigint IS DISTINCT FROM predecessor.revision
			OR NEW.request_envelope->>'expected_transition_id' IS DISTINCT FROM predecessor.transition_id::text))
		OR (NEW.transition_kind='superseded' AND NOT (
			(NEW.request_envelope->>'operation' IS NOT DISTINCT FROM 'claim_due_waiting_usage_wake')
			OR (NEW.request_envelope->>'operation' IS NOT DISTINCT FROM 'fire_waiting_usage_wake'
				AND NEW.request_envelope->>'wake_id' IS NOT DISTINCT FROM NEW.wake_id::text
				AND (NEW.request_envelope->>'expected_revision')::bigint IS NOT DISTINCT FROM predecessor.revision
				AND NEW.request_envelope->>'expected_transition_id' IS NOT DISTINCT FROM predecessor.transition_id::text
				AND NEW.request_envelope->>'holder_id' IS NOT DISTINCT FROM predecessor.lease_holder::text
				AND NEW.request_envelope->>'lease_fence_id' IS NOT DISTINCT FROM predecessor.lease_fence_id::text)))
	THEN
		RAISE EXCEPTION 'waiting-usage wake operation request is not bound to its transition'
			USING ERRCODE='23514', CONSTRAINT='waiting_usage_wake_transition_request';
	END IF;
	IF NOT EXISTS (
		SELECT 1 FROM decodex.routing_decisions AS decision
		JOIN decodex.routing_snapshots AS snapshot ON snapshot.snapshot_id=decision.snapshot_id
		WHERE decision.decision_id=NEW.routing_decision_id
			AND decision.authority_shape='managed_run_project_policy'
			AND snapshot.authority_shape='managed_run_project_policy'
			AND decision.kind='waiting_usage'
			AND decision.waiting_ready_at_micros=NEW.earliest_ready_at_micros
			AND decision.routing_policy_id=NEW.routing_policy_id
			AND decision.routing_policy_revision=NEW.routing_policy_revision
			AND decision.managed_run_id=NEW.managed_run_id
			AND decision.managed_run_revision=NEW.managed_run_revision
			AND snapshot.routing_policy_id=decision.routing_policy_id
			AND snapshot.routing_policy_revision=decision.routing_policy_revision
			AND snapshot.managed_run_id=decision.managed_run_id
			AND snapshot.managed_run_revision=decision.managed_run_revision
	) OR NOT EXISTS (
		SELECT 1 FROM decodex.waiting_usage_wake_heads AS head
		WHERE (head.wake_id,head.revision,head.transition_id)=
			(NEW.wake_id,NEW.revision,NEW.transition_id)
			AND head.registration_operation_id=NEW.registration_operation_id
			AND head.routing_decision_id=NEW.routing_decision_id
			AND head.routing_decision_revision=NEW.routing_decision_revision
			AND head.routing_policy_id=NEW.routing_policy_id
			AND head.routing_policy_revision=NEW.routing_policy_revision
			AND head.managed_run_id=NEW.managed_run_id
			AND head.managed_run_revision=NEW.managed_run_revision
			AND head.earliest_ready_at_micros=NEW.earliest_ready_at_micros
			AND head.state=NEW.state AND head.claim_id IS NOT DISTINCT FROM NEW.claim_id
			AND head.lease_holder IS NOT DISTINCT FROM NEW.lease_holder
			AND head.lease_fence_id IS NOT DISTINCT FROM NEW.lease_fence_id
			AND head.lease_acquired_at IS NOT DISTINCT FROM NEW.lease_acquired_at
			AND head.lease_expires_at IS NOT DISTINCT FROM NEW.lease_expires_at
			AND head.terminal_reason IS NOT DISTINCT FROM NEW.terminal_reason
			AND head.routing_resolution_request_id IS NOT DISTINCT FROM
				NEW.routing_resolution_request_id
			AND head.registered_at=NEW.registered_at AND head.updated_at=NEW.transitioned_at
	) OR NOT EXISTS (
		SELECT 1 FROM decodex.activity AS activity
		WHERE activity.sequence=NEW.activity_sequence
			AND activity.aggregate_kind='waiting_usage_wake'
			AND activity.aggregate_id=NEW.wake_id::text AND activity.revision=NEW.revision
			AND activity.correlation_key=NEW.operation_id::text
			AND activity.event_kind=CASE NEW.transition_kind
				WHEN 'registered' THEN 'waiting_usage_wake_registered'
				WHEN 'claimed' THEN 'waiting_usage_wake_claimed'
				WHEN 'reclaimed' THEN 'waiting_usage_wake_reclaimed'
				WHEN 'fired' THEN 'waiting_usage_wake_fired'
				WHEN 'cancelled' THEN 'waiting_usage_wake_cancelled'
				WHEN 'superseded' THEN 'waiting_usage_wake_superseded' END
			AND activity.payload->>'waiting_usage_wake_transition_id'=NEW.transition_id::text
	) OR NOT EXISTS (
		SELECT 1 FROM decodex.outbox AS outbox
		WHERE outbox.id=NEW.outbox_id
			AND outbox.effect_key='activity/'||NEW.activity_sequence::text
			AND outbox.aggregate_kind='waiting_usage_wake'
			AND outbox.aggregate_id=NEW.wake_id::text
			AND outbox.aggregate_revision=NEW.revision
			AND outbox.payload->>'waiting_usage_wake_transition_id'=NEW.transition_id::text
	) THEN
		RAISE EXCEPTION 'waiting-usage wake transition cluster is incomplete'
			USING ERRCODE='23514', CONSTRAINT='waiting_usage_wake_transition_complete';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_work_item_acceptance_coherence(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_work_item_acceptance_coherence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE item record;
BEGIN
	SELECT revision, updated_at, state, lead_agent_id, acceptance_criteria, validation_criteria
	INTO item FROM decodex.work_items
	WHERE work_item_id = NEW.work_item_id AND project_id = NEW.project_id;
	IF NOT FOUND OR item.revision <> NEW.work_item_revision OR item.updated_at <> NEW.work_item_updated_at
		OR item.state <> 'review' OR item.lead_agent_id <> NEW.accepted_by
		OR item.acceptance_criteria <> NEW.acceptance_criteria
		OR item.validation_criteria <> NEW.validation_criteria
	THEN
		RAISE EXCEPTION 'WorkItem acceptance does not bind the exact review revision'
			USING ERRCODE = '23514', CONSTRAINT = 'work_item_acceptance_coherence';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_work_item_command_owner(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_work_item_command_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE owner_name name;
BEGIN
	SELECT pg_catalog.pg_get_userbyid(class.relowner) INTO owner_name
	FROM pg_catalog.pg_class AS class WHERE class.oid = TG_RELID;
	IF current_user::name <> owner_name THEN
		RAISE EXCEPTION 'WorkItem state is command-owned'
			USING ERRCODE = '42501', CONSTRAINT = 'work_item_command_owner';
	END IF;
	RETURN NULL;
END
$$;


--
-- Name: enforce_work_item_event_namespace(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_work_item_event_namespace() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE owner_name name;
DECLARE linked boolean := false;
BEGIN
	SELECT pg_catalog.pg_get_userbyid(class.relowner) INTO owner_name
	FROM pg_catalog.pg_class AS class WHERE class.oid = TG_RELID;
	IF TG_TABLE_NAME = 'activity' THEN
		linked := NEW.aggregate_kind = 'work_item'
			OR NEW.event_kind IN ('work_item_created', 'work_item_updated',
				'work_item_readiness_blocked', 'work_item_ready', 'work_item_accepted')
			OR pg_catalog.jsonb_path_exists(NEW.payload, '$.** ? (
				@.aggregate_kind == "work_item" || @.kind == "work_item" ||
				exists(@.work_item) || exists(@.work_item_id) ||
				exists(@.readiness_blockers) || exists(@.acceptance)
			)');
		IF TG_OP = 'UPDATE' THEN
			linked := linked OR OLD.aggregate_kind = 'work_item'
				OR OLD.event_kind IN ('work_item_created', 'work_item_updated',
					'work_item_readiness_blocked', 'work_item_ready', 'work_item_accepted')
				OR pg_catalog.jsonb_path_exists(OLD.payload, '$.** ? (
					@.aggregate_kind == "work_item" || @.kind == "work_item" ||
					exists(@.work_item) || exists(@.work_item_id) ||
					exists(@.readiness_blockers) || exists(@.acceptance)
				)');
		END IF;
	ELSE
		linked := NEW.aggregate_kind = 'work_item'
			OR pg_catalog.jsonb_path_exists(NEW.payload, '$.** ? (
				@.aggregate_kind == "work_item" || @.kind == "work_item" ||
				exists(@.work_item) || exists(@.work_item_id) ||
				exists(@.readiness_blockers) || exists(@.acceptance)
			)') OR EXISTS (
				SELECT 1 FROM pg_catalog.jsonb_path_query(
					NEW.payload, '$.**.activity_sequence'
				) AS link(value)
				JOIN decodex.activity AS activity ON activity.sequence = CASE
					WHEN link.value #>> '{}' ~ '^[0-9]+$' THEN (link.value #>> '{}')::bigint
				END WHERE activity.aggregate_kind = 'work_item'
			);
		IF TG_OP = 'UPDATE' THEN
			linked := linked OR OLD.aggregate_kind = 'work_item'
				OR pg_catalog.jsonb_path_exists(OLD.payload, '$.** ? (
					@.aggregate_kind == "work_item" || @.kind == "work_item" ||
					exists(@.work_item) || exists(@.work_item_id) ||
					exists(@.readiness_blockers) || exists(@.acceptance)
				)') OR EXISTS (
					SELECT 1 FROM pg_catalog.jsonb_path_query(
						OLD.payload, '$.**.activity_sequence'
					) AS link(value)
					JOIN decodex.activity AS activity ON activity.sequence = CASE
						WHEN link.value #>> '{}' ~ '^[0-9]+$' THEN (link.value #>> '{}')::bigint
					END WHERE activity.aggregate_kind = 'work_item'
				);
		END IF;
	END IF;
	IF linked AND current_user::name <> owner_name THEN
		IF TG_TABLE_NAME = 'activity' OR TG_OP = 'INSERT' THEN
			RAISE EXCEPTION 'WorkItem activity/outbox namespace is command-owned'
				USING ERRCODE = '42501', CONSTRAINT = 'work_item_event_namespace';
		ELSIF NEW.id IS DISTINCT FROM OLD.id
			OR NEW.effect_key IS DISTINCT FROM OLD.effect_key
			OR NEW.aggregate_kind IS DISTINCT FROM OLD.aggregate_kind
			OR NEW.aggregate_id IS DISTINCT FROM OLD.aggregate_id
			OR NEW.aggregate_revision IS DISTINCT FROM OLD.aggregate_revision
			OR NEW.payload IS DISTINCT FROM OLD.payload
			OR NEW.created_at IS DISTINCT FROM OLD.created_at
		THEN
			RAISE EXCEPTION 'WorkItem outbox authority fields are command-owned'
				USING ERRCODE = '42501', CONSTRAINT = 'work_item_event_namespace';
		END IF;
	END IF;
	RETURN NEW;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
	RAISE EXCEPTION 'WorkItem activity/outbox link is malformed'
		USING ERRCODE = '42501', CONSTRAINT = 'work_item_event_namespace';
END
$_$;


--
-- Name: enforce_work_item_state(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.enforce_work_item_state() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF TG_OP = 'INSERT' THEN
		IF NEW.state <> 'inbox' OR NEW.revision <> 1 OR NEW.updated_at <> NEW.created_at THEN
			RAISE EXCEPTION 'new WorkItem must be inbox revision one'
				USING ERRCODE = '23514', CONSTRAINT = 'work_items_state_guard';
		END IF;
		RETURN NEW;
	END IF;
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'WorkItems cannot be deleted'
			USING ERRCODE = '23514', CONSTRAINT = 'work_items_state_guard';
	END IF;
	IF NEW.work_item_id <> OLD.work_item_id OR NEW.project_id <> OLD.project_id
		OR NEW.lead_agent_id <> OLD.lead_agent_id OR NEW.created_at <> OLD.created_at
		OR NEW.revision <> OLD.revision + 1 OR NEW.updated_at < OLD.updated_at
		OR NOT (
			(OLD.state = 'inbox' AND NEW.state IN ('inbox', 'planned', 'canceled'))
			OR (OLD.state = 'planned' AND NEW.state IN ('inbox', 'planned', 'ready', 'blocked', 'canceled'))
			OR (OLD.state = 'ready' AND NEW.state IN ('planned', 'blocked', 'canceled'))
			OR (OLD.state = 'running' AND NEW.state IN ('review', 'blocked', 'canceled'))
			OR (OLD.state = 'review' AND NEW.state IN ('blocked', 'canceled'))
			OR (OLD.state = 'blocked' AND NEW.state IN ('planned', 'ready', 'blocked', 'canceled'))
		)
	THEN
		RAISE EXCEPTION 'invalid WorkItem revision or lifecycle mutation'
			USING ERRCODE = '23514', CONSTRAINT = 'work_items_state_guard';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: fence_runtime_session_thread_start_exact(text, text, uuid, bigint, uuid, bigint, uuid, bigint, uuid, uuid, bigint, uuid, bigint, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.fence_runtime_session_thread_start_exact(p_protocol text, p_idempotency_key text, p_conversation_id uuid, p_expected_conversation_revision bigint, p_runtime_session_id uuid, p_expected_revision bigint, p_turn_id uuid, p_expected_turn_revision bigint, p_continuation_plan_id uuid, p_process_generation_id uuid, p_process_generation_revision bigint, p_process_execution_epoch_id uuid, p_thread_start_request_id bigint, p_thread_start_request_sha256 text) RETURNS TABLE(response_bytes bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; claimed record;
DECLARE conversation_row decodex.conversations%ROWTYPE;
DECLARE session_row decodex.runtime_sessions%ROWTYPE;
DECLARE turn_row decodex.turns%ROWTYPE;
DECLARE plan_row decodex.continuation_plans%ROWTYPE;
DECLARE decision_row decodex.routing_decisions%ROWTYPE;
DECLARE account_row decodex.account_snapshots%ROWTYPE;
DECLARE generation_row decodex.process_generations%ROWTYPE;
DECLARE transition_row decodex.process_generation_transitions%ROWTYPE;
DECLARE epoch_row decodex.process_generation_execution_epochs%ROWTYPE;
DECLARE expected_turn_session_id uuid; new_revision bigint;
DECLARE payload jsonb; links jsonb; core jsonb; effect jsonb;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','fence_runtime_session_thread_start','protocol_version',p_protocol,
		'conversation_id',p_conversation_id,
		'expected_conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,'expected_revision',p_expected_revision,
		'turn_id',p_turn_id,'expected_turn_revision',p_expected_turn_revision,
		'continuation_plan_id',p_continuation_plan_id,
		'process_generation_id',p_process_generation_id,
		'process_generation_revision',p_process_generation_revision,
		'process_execution_epoch_id',p_process_execution_epoch_id,
		'thread_start_request_id',p_thread_start_request_id,
		'thread_start_request_sha256',p_thread_start_request_sha256
	);
	SELECT * INTO claimed FROM decodex.claim_runtime_session_thread_command(
		p_protocol,p_idempotency_key,request
	);
	IF claimed.replayed THEN
		RETURN QUERY SELECT claimed.response_bytes,true;
		RETURN;
	END IF;
	IF p_conversation_id IS NULL OR p_runtime_session_id IS NULL OR p_turn_id IS NULL
		OR p_continuation_plan_id IS NULL OR p_process_generation_id IS NULL
		OR p_process_execution_epoch_id IS NULL
		OR p_expected_conversation_revision IS NULL
		OR p_expected_conversation_revision<=0
		OR p_expected_revision IS NULL OR p_expected_revision<=0
		OR p_expected_turn_revision IS DISTINCT FROM 1
		OR p_process_generation_revision IS NULL OR p_process_generation_revision<=0
		OR p_thread_start_request_id IS NULL OR p_thread_start_request_id<=0
		OR p_thread_start_request_sha256 IS NULL
		OR p_thread_start_request_sha256 COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$'
		OR decodex.has_credential_material(p_thread_start_request_sha256)
	THEN
		response_bytes:=decodex.complete_runtime_session_thread_rejection(
			p_protocol,p_idempotency_key,
			'fence_runtime_session_thread_start',request,'invalid_input'
		);
		replayed:=false;
		RETURN NEXT;
		RETURN;
	END IF;

	PERFORM pg_catalog.pg_advisory_xact_lock_shared(1400);
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1276,pg_catalog.hashtext(p_runtime_session_id::text)
	);
	SELECT * INTO conversation_row FROM decodex.conversations
	WHERE conversation_id=p_conversation_id FOR UPDATE;
	SELECT * INTO session_row FROM decodex.runtime_sessions
	WHERE runtime_session_id=p_runtime_session_id FOR UPDATE;
	SELECT * INTO turn_row FROM decodex.turns WHERE turn_id=p_turn_id FOR UPDATE;
	SELECT * INTO plan_row FROM decodex.continuation_plans
	WHERE plan_id=p_continuation_plan_id FOR SHARE;
	SELECT * INTO decision_row FROM decodex.routing_decisions
	WHERE decision_id=plan_row.routing_decision_id FOR SHARE;
	SELECT * INTO account_row FROM decodex.account_snapshots
	WHERE account_snapshot_id=session_row.account_snapshot_id FOR SHARE;
	SELECT * INTO generation_row FROM decodex.process_generations
	WHERE generation_id=p_process_generation_id FOR SHARE;
	SELECT * INTO transition_row FROM decodex.process_generation_transitions
	WHERE generation_id=p_process_generation_id
		AND revision=p_process_generation_revision FOR SHARE;
	SELECT * INTO epoch_row FROM decodex.process_generation_execution_epochs
	WHERE execution_epoch_id=p_process_execution_epoch_id FOR SHARE;
	expected_turn_session_id:=CASE plan_row.kind
		WHEN 'context_pack_fallback' THEN plan_row.source_runtime_session_id
		ELSE p_runtime_session_id
	END;
	IF conversation_row.conversation_id IS NULL
		OR conversation_row.revision<>p_expected_conversation_revision
		OR conversation_row.status<>'open'
		OR session_row.runtime_session_id IS NULL
		OR session_row.conversation_id<>p_conversation_id
		OR session_row.revision<>p_expected_revision
		OR session_row.state<>'starting'
		OR session_row.codex_thread_id IS NOT NULL
		OR session_row.thread_start_request_id IS NOT NULL
		OR session_row.thread_start_request_sha256 IS NOT NULL
		OR session_row.thread_start_response_id IS NOT NULL
		OR session_row.thread_start_response_sha256 IS NOT NULL
		OR turn_row.turn_id IS NULL OR turn_row.conversation_id<>p_conversation_id
		OR turn_row.runtime_session_id IS DISTINCT FROM expected_turn_session_id
		OR turn_row.role<>'user' OR turn_row.possible_side_effects<>'unknown'
		OR turn_row.status<>'active' OR turn_row.revision<>1
		OR plan_row.plan_id IS NULL OR plan_row.consumer_kind<>'conversation_turn'
		OR plan_row.consumer_conversation_id<>p_conversation_id
		OR plan_row.conversation_revision<>p_expected_conversation_revision
		OR plan_row.turn_id<>p_turn_id
		OR NOT (
			plan_row.kind='initial_thread'
				AND plan_row.source_runtime_session_id=p_runtime_session_id
				AND plan_row.source_runtime_session_revision=p_expected_revision
			OR plan_row.kind='context_pack_fallback'
				AND plan_row.fallback_runtime_session_id=p_runtime_session_id
				AND p_expected_revision=1
		)
		OR decision_row.decision_id IS NULL
		OR decision_row.consumer_kind<>'conversation_turn'
		OR decision_row.conversation_id<>p_conversation_id
		OR decision_row.conversation_revision<>p_expected_conversation_revision
		OR decision_row.turn_id<>p_turn_id
		OR NOT (
			plan_row.kind='initial_thread'
				AND decision_row.authority_shape=
					'conversation_account_registry'
				AND decision_row.kind='selected'
				AND decision_row.selected_account_id=plan_row.selected_account_id
			OR plan_row.kind='context_pack_fallback'
				AND decision_row.authority_shape='conversation_continuation'
				AND decision_row.kind IS NULL
				AND decision_row.account_snapshot_id=
					session_row.account_snapshot_id
				AND decision_row.profile_snapshot_id=
					session_row.profile_snapshot_id
				AND EXISTS (
					SELECT 1
					FROM decodex.routing_decisions AS initial
					WHERE initial.decision_id=decision_row.initial_decision_id
						AND initial.authority_shape=
							'conversation_account_registry'
						AND initial.kind='selected'
						AND initial.selected_account_id=
							plan_row.selected_account_id
				)
		)
		OR account_row.account_snapshot_id IS NULL
		OR account_row.source_account_id<>plan_row.selected_account_id
		OR generation_row.generation_id IS NULL
		OR generation_row.account_id<>plan_row.selected_account_id
		OR generation_row.revision<>p_process_generation_revision
		OR generation_row.state<>'ready' OR generation_row.process_id IS NULL
		OR generation_row.execution_epoch_id<>p_process_execution_epoch_id
		OR transition_row.generation_id IS NULL OR transition_row.state<>'ready'
		OR epoch_row.execution_epoch_id IS NULL OR epoch_row.retired_at IS NOT NULL
		OR NOT EXISTS (
			SELECT 1 FROM decodex.exact_command_receipts AS admission
			WHERE (admission.protocol_version,admission.idempotency_key)=(
					generation_row.quick_task_prepare_protocol,
					generation_row.quick_task_prepare_idempotency_key
				)
				AND admission.receipt_state='completed_success'
				AND admission.request_envelope->>'operation'=
					'prepare_quick_task_process_generation'
				AND admission.request_envelope->>'conversation_id'=p_conversation_id::text
				AND admission.request_envelope->>'expected_conversation_revision'=
					p_expected_conversation_revision::text
				AND admission.request_envelope->>'runtime_session_id'=
					p_runtime_session_id::text
				AND admission.request_envelope->>'expected_runtime_session_revision'=
					p_expected_revision::text
				AND admission.request_envelope->>'turn_id'=p_turn_id::text
				AND admission.request_envelope->>'expected_turn_revision'='1'
				AND admission.request_envelope->>'continuation_plan_id'=
					p_continuation_plan_id::text
				AND admission.request_envelope->>'routing_decision_id'=
					plan_row.routing_decision_id::text
				AND admission.request_envelope->>'selected_account_id'=
					plan_row.selected_account_id::text
				AND admission.request_envelope->>'process_generation_id'=
					p_process_generation_id::text
		)
	THEN
		response_bytes:=decodex.complete_runtime_session_thread_rejection(
			p_protocol,p_idempotency_key,
			'fence_runtime_session_thread_start',request,'authority_unavailable'
		);
		replayed:=false;
		RETURN NEXT;
		RETURN;
	END IF;

	UPDATE decodex.runtime_sessions SET
		thread_start_request_id=p_thread_start_request_id,
		thread_start_request_sha256=p_thread_start_request_sha256,
		revision=revision+1
	WHERE runtime_session_id=p_runtime_session_id
	RETURNING revision INTO new_revision;
	payload:=pg_catalog.jsonb_build_object(
		'kind','runtime_session_thread_start_fenced',
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'prior_state','starting','state','starting',
		'prior_revision',p_expected_revision,'revision',new_revision,
		'turn_id',p_turn_id,'turn_revision',p_expected_turn_revision,
		'turn_state','active','continuation_plan_id',p_continuation_plan_id,
		'routing_decision_id',plan_row.routing_decision_id,
		'selected_account_id',plan_row.selected_account_id,
		'process_generation_id',p_process_generation_id,
		'process_generation_revision',p_process_generation_revision,
		'process_execution_epoch_id',p_process_execution_epoch_id,
		'thread_start_request_id',p_thread_start_request_id,
		'thread_start_request_sha256',p_thread_start_request_sha256
	);
	links:=decodex.append_runtime_session_thread_effect(
		p_runtime_session_id,new_revision,'runtime_session_thread_start_fenced',
		p_idempotency_key,payload
	);
	core:=payload||pg_catalog.jsonb_build_object(
		'operation','fence_runtime_session_thread_start',
		'activity_sequence',links->'activity_sequence','outbox_id',links->'outbox_id'
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	response_bytes:=decodex.complete_runtime_session_thread_command(
		p_protocol,p_idempotency_key,effect
	);
	replayed:=false;
	RETURN NEXT;
END
$_$;


--
-- Name: fire_waiting_usage_wake_exact(text, text, uuid, uuid, bigint, uuid, uuid, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.fire_waiting_usage_wake_exact(p_protocol text, p_idempotency_key text, p_operation_id uuid, p_wake_id uuid, p_expected_revision bigint, p_expected_transition_id uuid, p_holder_id uuid, p_lease_fence_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	RETURN decodex.fire_waiting_usage_wake_exact_internal(
		p_protocol,p_idempotency_key,p_operation_id,p_wake_id,p_expected_revision,
		p_expected_transition_id,p_holder_id,p_lease_fence_id,
		NULL::pg_catalog.timestamptz);
END
$$;


--
-- Name: fire_waiting_usage_wake_exact_internal(text, text, uuid, uuid, bigint, uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.fire_waiting_usage_wake_exact_internal(p_protocol text, p_idempotency_key text, p_operation_id uuid, p_wake_id uuid, p_expected_revision bigint, p_expected_transition_id uuid, p_holder_id uuid, p_lease_fence_id uuid, p_authority_now timestamp with time zone) RETURNS bytea
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; replay bytea; head record; run_row record; now_value timestamptz;
DECLARE transition_uuid uuid; request_uuid uuid; revision_value bigint; reason text;
DECLARE activity_sequence bigint; outbox_id bigint; core jsonb; effect jsonb; response bytea;
DECLARE payload jsonb; state_value text; event_kind text; run_uuid uuid;
BEGIN
	IF p_authority_now IS NOT NULL THEN
		IF NOT pg_catalog.isfinite(p_authority_now)
			OR extract(epoch FROM p_authority_now)*1000000 < 0
			OR extract(epoch FROM p_authority_now)*1000000
				> 253402300739999999
			OR extract(epoch FROM p_authority_now)*1000000
				<> pg_catalog.trunc(extract(epoch FROM p_authority_now)*1000000)
		THEN
			RAISE EXCEPTION 'explicit waiting-usage wake authority time is outside the canonical range'
				USING ERRCODE='22023', CONSTRAINT='waiting_usage_wake_authority_time';
		END IF;
	END IF;
	request:=pg_catalog.jsonb_build_object('operation','fire_waiting_usage_wake',
		'protocol',p_protocol,'operation_id',p_operation_id,'wake_id',p_wake_id,
		'expected_revision',p_expected_revision,'expected_transition_id',p_expected_transition_id,
		'holder_id',p_holder_id,'lease_fence_id',p_lease_fence_id);
	replay:=decodex.reserve_exact_waiting_usage_wake_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	IF p_operation_id IS NULL OR p_wake_id IS NULL OR p_expected_revision IS NULL
		OR p_expected_revision<=0 OR p_expected_transition_id IS NULL
		OR p_holder_id IS NULL OR p_lease_fence_id IS NULL THEN
		RETURN decodex.complete_exact_waiting_usage_wake_rejection(
			p_protocol,p_idempotency_key,'fire_waiting_usage_wake','invalid_input');
	END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	replay:=decodex.replay_waiting_usage_wake_operation_exact(
		p_protocol,p_idempotency_key,'fire_waiting_usage_wake',p_operation_id,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	SELECT managed_run_id INTO run_uuid FROM decodex.waiting_usage_wake_heads
	WHERE wake_id=p_wake_id;
	IF NOT FOUND THEN RETURN decodex.complete_exact_waiting_usage_wake_rejection(
		p_protocol,p_idempotency_key,'fire_waiting_usage_wake','wake_not_found'); END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1338,pg_catalog.hashtext(run_uuid::text));
	SELECT * INTO head FROM decodex.waiting_usage_wake_heads WHERE wake_id=p_wake_id FOR UPDATE;
	IF head.state IN ('fired','cancelled','superseded') THEN
		RETURN decodex.complete_exact_waiting_usage_wake_rejection(
			p_protocol,p_idempotency_key,'fire_waiting_usage_wake','wake_terminal');
	END IF;
	IF head.revision<>p_expected_revision OR head.transition_id<>p_expected_transition_id THEN
		RETURN decodex.complete_exact_waiting_usage_wake_rejection(
			p_protocol,p_idempotency_key,'fire_waiting_usage_wake','stale_wake_tip');
	END IF;
	now_value:=CASE WHEN p_authority_now IS NULL THEN pg_catalog.clock_timestamp()
		ELSE p_authority_now END;
	IF p_authority_now IS NOT NULL AND now_value<head.updated_at THEN
		RAISE EXCEPTION 'explicit wake fire time precedes the locked wake tip'
			USING ERRCODE='22023', CONSTRAINT='waiting_usage_wake_authority_time_monotonic';
	END IF;
	IF head.state<>'leased' OR head.lease_holder<>p_holder_id
		OR head.lease_fence_id<>p_lease_fence_id OR head.lease_expires_at<=now_value THEN
		RETURN decodex.complete_exact_waiting_usage_wake_rejection(
			p_protocol,p_idempotency_key,'fire_waiting_usage_wake','lease_lost');
	END IF;
	SELECT * INTO run_row FROM decodex.managed_runs
	WHERE managed_run_id=head.managed_run_id FOR SHARE;
	IF run_row.managed_run_id IS NULL OR run_row.revision<>head.managed_run_revision
		OR run_row.lifecycle<>'waiting' OR run_row.wait_reason<>'usage'
		OR NOT run_row.blocked OR run_row.diverged THEN reason:='managed_run_stale';
	ELSIF NOT EXISTS (SELECT 1 FROM decodex.routing_policy_heads
		WHERE routing_policy_id=head.routing_policy_id
			AND current_revision=head.routing_policy_revision FOR SHARE) THEN
		reason:='policy_revision_stale';
	ELSIF NOT EXISTS (SELECT 1 FROM decodex.routing_decisions
		WHERE decision_id=head.routing_decision_id
			AND authority_shape='managed_run_project_policy'
			AND kind='waiting_usage'
			AND managed_run_id=head.managed_run_id
			AND managed_run_revision=head.managed_run_revision)
		OR EXISTS (SELECT 1 FROM decodex.routing_decisions AS other
			WHERE other.managed_run_id=head.managed_run_id
				AND other.managed_run_revision>=head.managed_run_revision
				AND other.decision_id<>head.routing_decision_id) THEN
		reason:='ambiguous_decision_lineage';
	END IF;
	transition_uuid:=pg_catalog.gen_random_uuid(); revision_value:=head.revision+1;
	IF reason IS NULL THEN
		request_uuid:=pg_catalog.gen_random_uuid(); state_value:='fired';
		event_kind:='waiting_usage_wake_fired';
	ELSE state_value:='superseded'; event_kind:='waiting_usage_wake_superseded'; END IF;
	activity_sequence:=pg_catalog.nextval(
		pg_catalog.pg_get_serial_sequence('decodex.activity','sequence')::pg_catalog.regclass);
	outbox_id:=pg_catalog.nextval(
		pg_catalog.pg_get_serial_sequence('decodex.outbox','id')::pg_catalog.regclass);
	payload:=pg_catalog.jsonb_build_object('waiting_usage_wake_id',head.wake_id,
		'waiting_usage_wake_transition_id',transition_uuid,'state',state_value,
		'terminal_reason',reason,'routing_resolution_request_id',request_uuid,
		'fresh_routing_resolution_only',true,'prior_decision_reusable',false,
		'production_enabled',false);
	core:=pg_catalog.jsonb_build_object('operation','fire_waiting_usage_wake',
		'operation_id',p_operation_id,'transition_id',transition_uuid,
		'transition_kind',CASE WHEN reason IS NULL THEN 'fired' ELSE 'superseded' END,
		'wake_id',head.wake_id,'revision',revision_value,
		'predecessor_revision',head.revision,'predecessor_transition_id',head.transition_id,
		'registration_operation_id',head.registration_operation_id,
		'routing_decision_id',head.routing_decision_id,'routing_decision_revision',1,
		'routing_policy_id',head.routing_policy_id,'routing_policy_revision',head.routing_policy_revision,
		'managed_run_id',head.managed_run_id,'managed_run_revision',head.managed_run_revision,
		'earliest_ready_at_micros',head.earliest_ready_at_micros,'state',state_value,
		'claim_id',NULL,'lease_holder',NULL,'lease_fence_id',NULL,
		'lease_acquired_at_micros',NULL,'lease_expires_at_micros',NULL,
		'registered_at_micros',(extract(epoch FROM head.registered_at)*1000000)::bigint,
		'transitioned_at_micros',(extract(epoch FROM now_value)*1000000)::bigint,
		'terminal_reason',reason,'routing_resolution_request_id',request_uuid,
		'fresh_routing_resolution_only',true,'prior_decision_reusable',false,
		'production_enabled',false,
		'activity_effects',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
			'sequence',activity_sequence,'event_kind',event_kind)),
		'outbox_effects',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
			'id',outbox_id,'effect_key','activity/'||activity_sequence::text)));
	effect:=core||pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	INSERT INTO decodex.waiting_usage_wake_transitions(
		transition_id,wake_id,revision,predecessor_revision,predecessor_transition_id,
		operation_id,transition_kind,request_envelope,request_digest,registration_operation_id,
		routing_decision_id,routing_policy_id,routing_policy_revision,managed_run_id,
		managed_run_revision,earliest_ready_at_micros,state,terminal_reason,
		routing_resolution_request_id,registered_at,transitioned_at,activity_sequence,outbox_id,
		effect_envelope,effect_digest,response_bytes
	) VALUES(transition_uuid,head.wake_id,revision_value,head.revision,head.transition_id,
		p_operation_id,CASE WHEN reason IS NULL THEN 'fired' ELSE 'superseded' END::
			decodex.waiting_usage_wake_transition_kind,request,
		public.digest(pg_catalog.convert_to(request::text,'UTF8'),'sha256'),
		head.registration_operation_id,head.routing_decision_id,head.routing_policy_id,
		head.routing_policy_revision,head.managed_run_id,head.managed_run_revision,
		head.earliest_ready_at_micros,state_value::decodex.waiting_usage_wake_state,
		reason::decodex.waiting_usage_wake_terminal_reason,request_uuid,head.registered_at,now_value,
		activity_sequence,outbox_id,effect,
		public.digest(pg_catalog.convert_to(core::text,'UTF8'),'sha256'),response);
	UPDATE decodex.waiting_usage_wake_heads SET revision=revision_value,
		transition_id=transition_uuid,state=state_value::decodex.waiting_usage_wake_state,
		claim_id=NULL,lease_holder=NULL,lease_fence_id=NULL,lease_acquired_at=NULL,
		lease_expires_at=NULL,terminal_reason=reason::decodex.waiting_usage_wake_terminal_reason,
		routing_resolution_request_id=request_uuid,updated_at=now_value
	WHERE wake_id=head.wake_id AND revision=head.revision AND transition_id=head.transition_id;
	IF NOT FOUND THEN RAISE EXCEPTION 'waiting-usage wake head changed during fire'
		USING ERRCODE='40001'; END IF;
	INSERT INTO decodex.activity(sequence,aggregate_kind,aggregate_id,revision,event_kind,
		correlation_key,payload) OVERRIDING SYSTEM VALUE
	VALUES(activity_sequence,'waiting_usage_wake',head.wake_id::text,revision_value,
		event_kind,p_operation_id::text,payload);
	INSERT INTO decodex.outbox(id,effect_key,aggregate_kind,aggregate_id,aggregate_revision,payload)
	OVERRIDING SYSTEM VALUE VALUES(outbox_id,'activity/'||activity_sequence::text,
		'waiting_usage_wake',head.wake_id::text,revision_value,payload);
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',
		outcome_class='success',effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$$;


