CREATE FUNCTION decodex.forbid_codex_experiment_history_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	RAISE EXCEPTION 'V15 Codex experiment history is immutable'
		USING ERRCODE='55000', CONSTRAINT='codex_experiment_history_immutable';
END
$$;


--
-- Name: forbid_continuation_plan_mutation(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.forbid_continuation_plan_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE owner_name name;
BEGIN
	SELECT role.rolname INTO owner_name
	FROM pg_catalog.pg_class AS class
	JOIN pg_catalog.pg_roles AS role ON role.oid=class.relowner
	WHERE class.oid=TG_RELID;
	IF current_user::name<>owner_name THEN
		RAISE EXCEPTION 'continuation plans are writable only by their command owner'
			USING ERRCODE='42501', CONSTRAINT='continuation_plan_command_owner';
	END IF;
	IF TG_OP<>'INSERT' THEN
		RAISE EXCEPTION 'continuation plans are immutable'
			USING ERRCODE='55000', CONSTRAINT='continuation_plan_immutable';
	END IF;
	RETURN NEW;
END
$$;


--
-- Name: forbid_exact_receipt_rewrite(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.forbid_exact_receipt_rewrite() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'exact command receipts cannot be deleted'
			USING ERRCODE = '23514', CONSTRAINT = 'exact_receipts_immutable';
	END IF;

	IF OLD.receipt_state <> 'executing'
		OR NEW.receipt_state = 'executing'
		OR OLD.protocol_version <> NEW.protocol_version
		OR OLD.idempotency_key <> NEW.idempotency_key
		OR OLD.request_envelope <> NEW.request_envelope
		OR OLD.request_digest <> NEW.request_digest
		OR OLD.created_at <> NEW.created_at
	THEN
		RAISE EXCEPTION 'exact command receipt rewrite is forbidden'
			USING ERRCODE = '23514', CONSTRAINT = 'exact_receipts_immutable';
	END IF;

	RETURN NEW;
END
$$;


