--
-- Name: guard_work_item_running_resume(uuid, uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.guard_work_item_running_resume(p_work_item_id uuid, p_project_id uuid, p_expected_revision bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE item record;
DECLARE blockers jsonb;
BEGIN
	PERFORM pg_catalog.pg_advisory_xact_lock(1343,pg_catalog.hashtext(p_project_id::text));
	SELECT work.revision,work.state,work.program_id,work.lead_agent_id INTO item
	FROM decodex.work_items work
	WHERE work.work_item_id=p_work_item_id AND work.project_id=p_project_id FOR UPDATE OF work;
	IF NOT FOUND OR item.revision<>p_expected_revision OR item.state NOT IN ('ready','running') THEN
		RAISE EXCEPTION 'future WorkItem running/resume guard rejected current state'
			USING ERRCODE='55000',CONSTRAINT='work_item_running_resume_guard';
	END IF;
	PERFORM 1 FROM decodex.programs WHERE program_id=item.program_id FOR SHARE;
	PERFORM 1 FROM decodex.objectives objective JOIN decodex.work_item_objectives link USING(objective_id)
		WHERE link.work_item_id=p_work_item_id ORDER BY objective.objective_id FOR SHARE OF objective;
	PERFORM 1 FROM decodex.work_items related JOIN decodex.work_item_edges edge
		ON edge.related_work_item_id=related.work_item_id WHERE edge.work_item_id=p_work_item_id
		ORDER BY related.work_item_id FOR SHARE OF related;
	PERFORM 1 FROM decodex.projects project JOIN decodex.agents lead
		ON lead.agent_id=item.lead_agent_id AND lead.project_id=project.project_id
		WHERE project.project_id=p_project_id FOR SHARE OF project,lead;
	blockers := decodex.work_item_readiness(p_work_item_id);
	IF pg_catalog.jsonb_array_length(blockers)<>0 THEN
		RAISE EXCEPTION 'future WorkItem running/resume guard found current blockers'
			USING ERRCODE='55000',CONSTRAINT='work_item_running_resume_guard';
	END IF;
	-- Intentionally no transition, receipt, lease, assignment, dispatch, or side effect.
END
$$;


--
-- Name: has_credential_material(jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.has_credential_material(document jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE
	entry record;
	normalized_key text;
BEGIN
	CASE jsonb_typeof(document)
		WHEN 'object' THEN
			FOR entry IN SELECT key, value FROM jsonb_each(document)
			LOOP
				normalized_key := regexp_replace(
					decodex.ascii_lower(entry.key) COLLATE "C",
					'[^a-z0-9]',
					'',
					'g'
				);
				IF (normalized_key COLLATE "C") ~ '(credentials?|password|passphrase|privatekey|secret|authorization|bearer|apikey|cookie|token|session)$'
					OR decodex.has_credential_material(entry.value) THEN
					RETURN true;
				END IF;
			END LOOP;
		WHEN 'array' THEN
			FOR entry IN SELECT value FROM jsonb_array_elements(document)
			LOOP
				IF decodex.has_credential_material(entry.value) THEN
					RETURN true;
				END IF;
			END LOOP;
		WHEN 'string' THEN
			IF decodex.has_credential_material(document #>> '{}') THEN
				RETURN true;
			END IF;
		ELSE
			NULL;
	END CASE;
	RETURN false;
END
$_$;


--
-- Name: has_credential_material(text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.has_credential_material(value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT (
		decodex.ascii_lower(decodex.normalize_unicode_whitespace(value)) COLLATE "C"
	) ~ '(^|[[:space:][:punct:]])(bearer[[:space:]]+[[:alnum:]_.~+/-]{8,}|basic[[:space:]]+[[:alnum:]+/]{8,}={0,2})|(^|[^[:alnum:]])(sk-[[:alnum:]_-]{8,}|(sk|pk|rk)_(live|test|proj)?[[:alnum:]_-]{8,}|xox[baprs]-[[:alnum:]-]{8,}|glpat-[[:alnum:]_-]{8,}|npm_[[:alnum:]]{8,})|gh[pousr]_[[:alnum:]]{20,}|eyj[[:alnum:]_-]{8,}\.[[:alnum:]_-]{8,}\.[[:alnum:]_-]{8,}|-----begin[^-]*private[[:space:]]+key-----|(password|passphrase|secret|token|authorization)[[:space:]]*[:=][[:space:]]*[^[:space:]]{4,}|[a-z][a-z0-9+.-]*://[^/:[:space:]]+:[^@[:space:]]+@|akia[0-9a-z]{16}'
$$;


--
-- Name: is_canonical_continuation_pack(uuid, bytea, text, text, integer, integer, text, boolean, integer, text[], text[], bigint[], text[], bigint[], bigint[], text[], text[], text[], bigint[]); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_canonical_continuation_pack(p_conversation_id uuid, p_compiled_bytes bytea, p_compiled_digest text, p_manifest_digest text, p_max_bytes integer, p_recent_item_limit integer, p_possible_side_effects text, p_truncated boolean, p_omitted_source_count integer, p_source_kinds text[], p_source_ids text[], p_source_revisions bigint[], p_content_digests text[], p_original_lengths bigint[], p_included_lengths bigint[], p_included_digests text[], p_dispositions text[], p_artifact_ids text[], p_artifact_revisions bigint[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE source_count integer; position integer; kind_tag integer; prior_kind integer:=-1;
DECLARE disposition_tag integer; manifest_bytes bytea; computed_manifest text;
DECLARE header bytea; cursor integer; encoded_position integer; encoded_length bigint;
DECLARE represented bytea; computed_truncated boolean:=false; computed_omitted integer:=0;
BEGIN
	source_count:=pg_catalog.cardinality(p_source_kinds);
	IF p_conversation_id IS NULL OR p_compiled_bytes IS NULL
		OR p_compiled_digest COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$'
		OR p_manifest_digest COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$'
		OR pg_catalog.encode(public.digest(p_compiled_bytes,'sha256'),'hex')<>p_compiled_digest
		OR pg_catalog.octet_length(p_compiled_bytes) NOT BETWEEN 1 AND 262144
		OR p_max_bytes NOT BETWEEN 1024 AND 262144
		OR pg_catalog.octet_length(p_compiled_bytes)>p_max_bytes
		OR p_recent_item_limit NOT BETWEEN 1 AND 256
		OR p_possible_side_effects NOT IN ('none','possible','unknown')
		OR source_count NOT BETWEEN 1 AND 512
		OR source_count IS DISTINCT FROM pg_catalog.cardinality(p_source_ids)
		OR source_count IS DISTINCT FROM pg_catalog.cardinality(p_source_revisions)
		OR source_count IS DISTINCT FROM pg_catalog.cardinality(p_content_digests)
		OR source_count IS DISTINCT FROM pg_catalog.cardinality(p_original_lengths)
		OR source_count IS DISTINCT FROM pg_catalog.cardinality(p_included_lengths)
		OR source_count IS DISTINCT FROM pg_catalog.cardinality(p_included_digests)
		OR source_count IS DISTINCT FROM pg_catalog.cardinality(p_dispositions)
		OR source_count IS DISTINCT FROM pg_catalog.cardinality(p_artifact_ids)
		OR source_count IS DISTINCT FROM pg_catalog.cardinality(p_artifact_revisions)
	THEN RETURN false; END IF;
	manifest_bytes:=pg_catalog.int2send(source_count::smallint);
	FOR position IN 1..source_count LOOP
		kind_tag:=CASE p_source_kinds[position]
			WHEN 'pinned_revision' THEN 0 WHEN 'repository_instructions' THEN 1
			WHEN 'openwiki' THEN 2 WHEN 'decision' THEN 3 WHEN 'fact' THEN 4
			WHEN 'artifact' THEN 5 WHEN 'recent_raw' THEN 6 ELSE -1 END;
		disposition_tag:=CASE p_dispositions[position]
			WHEN 'complete' THEN 0 WHEN 'truncated' THEN 1 WHEN 'omitted' THEN 2 ELSE -1 END;
		IF kind_tag<0 OR disposition_tag<0 OR kind_tag<prior_kind
			OR (position=1) IS DISTINCT FROM (kind_tag=0) OR (position>1 AND kind_tag=0)
			OR p_source_ids[position] IS NULL
			OR pg_catalog.octet_length(p_source_ids[position]) NOT BETWEEN 1 AND 256
			OR decodex.has_credential_material(p_source_ids[position])
			OR p_source_revisions[position] IS NULL OR p_source_revisions[position]<=0
			OR p_content_digests[position] COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$'
			OR p_included_digests[position] COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$'
			OR p_original_lengths[position] NOT BETWEEN 0 AND 2097152
			OR p_included_lengths[position] NOT BETWEEN 0 AND p_original_lengths[position]
			OR (disposition_tag=0 AND (p_original_lengths[position]<=0
				OR p_included_lengths[position]<>p_original_lengths[position]
				OR p_included_digests[position]<>p_content_digests[position]))
			OR (disposition_tag=1 AND (p_included_lengths[position]<=0
				OR p_included_lengths[position]>=p_original_lengths[position]))
			OR (disposition_tag=2 AND (p_included_lengths[position]<>0
				OR p_included_digests[position]<>'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'))
			OR (position=1 AND (disposition_tag<>0 OR p_included_lengths[position]<=0))
			OR (kind_tag=5) IS DISTINCT FROM (p_artifact_ids[position]<>'')
			OR (kind_tag=5 AND (p_artifact_ids[position] COLLATE pg_catalog."C" !~
				'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
				OR p_artifact_ids[position]<>p_source_ids[position]
				OR p_artifact_revisions[position]<>p_source_revisions[position]))
			OR (kind_tag<>5 AND (p_artifact_ids[position]<>'' OR p_artifact_revisions[position]<>0))
		THEN RETURN false; END IF;
		manifest_bytes:=manifest_bytes
			||pg_catalog.decode(pg_catalog.lpad(pg_catalog.to_hex(kind_tag),2,'0'),'hex')
			||pg_catalog.int2send(pg_catalog.octet_length(p_source_ids[position])::smallint)
			||pg_catalog.convert_to(p_source_ids[position],'UTF8')
			||pg_catalog.int8send(p_source_revisions[position])
			||pg_catalog.convert_to(p_content_digests[position],'UTF8')
			||pg_catalog.int8send(p_original_lengths[position])
			||pg_catalog.int8send(p_included_lengths[position])
			||pg_catalog.convert_to(p_included_digests[position],'UTF8')
			||pg_catalog.decode(pg_catalog.lpad(pg_catalog.to_hex(disposition_tag),2,'0'),'hex')
			||CASE WHEN kind_tag=5 THEN pg_catalog.decode('01','hex')
				||pg_catalog.convert_to(p_artifact_ids[position],'UTF8')
				||pg_catalog.int8send(p_artifact_revisions[position])
				ELSE pg_catalog.decode('00','hex') END;
		prior_kind:=kind_tag;
		computed_truncated:=computed_truncated OR disposition_tag<>0;
		computed_omitted:=computed_omitted+CASE WHEN disposition_tag=2 THEN 1 ELSE 0 END;
	END LOOP;
	computed_manifest:=pg_catalog.encode(public.digest(manifest_bytes,'sha256'),'hex');
	IF computed_manifest<>p_manifest_digest OR computed_truncated IS DISTINCT FROM p_truncated
		OR computed_omitted<>p_omitted_source_count THEN RETURN false; END IF;
	header:=pg_catalog.convert_to('decodex/context-pack/2','UTF8')||pg_catalog.decode('00','hex')
		||pg_catalog.convert_to(p_conversation_id::text,'UTF8')
		||pg_catalog.decode(CASE p_possible_side_effects WHEN 'none' THEN '00'
			WHEN 'possible' THEN '01' ELSE '02' END,'hex')
		||pg_catalog.int4send(p_max_bytes)||pg_catalog.int2send(p_recent_item_limit::smallint)
		||pg_catalog.int2send(source_count::smallint)||pg_catalog.convert_to(p_manifest_digest,'UTF8')
		||pg_catalog.decode(CASE WHEN p_truncated THEN '01' ELSE '00' END,'hex');
	IF pg_catalog.substr(p_compiled_bytes, 1, pg_catalog.octet_length(header))<>header
	THEN RETURN false; END IF;
	cursor:=pg_catalog.octet_length(header)+1;
	FOR position IN 1..source_count LOOP
		IF p_included_lengths[position]=0 THEN CONTINUE; END IF;
		IF cursor+5>pg_catalog.octet_length(p_compiled_bytes) THEN RETURN false; END IF;
		encoded_position:=pg_catalog.get_byte(p_compiled_bytes,cursor-1)*256
			+pg_catalog.get_byte(p_compiled_bytes,cursor);
		encoded_length:=pg_catalog.get_byte(p_compiled_bytes,cursor+1)::bigint*16777216
			+pg_catalog.get_byte(p_compiled_bytes,cursor+2)::bigint*65536
			+pg_catalog.get_byte(p_compiled_bytes,cursor+3)::bigint*256
			+pg_catalog.get_byte(p_compiled_bytes,cursor+4)::bigint;
		cursor:=cursor+6;
		IF encoded_position<>position-1 OR encoded_length<>p_included_lengths[position]
			OR cursor+encoded_length-1>pg_catalog.octet_length(p_compiled_bytes)
		THEN RETURN false; END IF;
		represented:=pg_catalog.substr(p_compiled_bytes, cursor, encoded_length::integer);
		IF pg_catalog.encode(public.digest(represented,'sha256'),'hex')<>p_included_digests[position]
		THEN RETURN false; END IF;
		cursor:=cursor+encoded_length::integer;
	END LOOP;
	RETURN cursor=pg_catalog.octet_length(p_compiled_bytes)+1;
EXCEPTION WHEN OTHERS THEN RETURN false;
END
$_$;


--
-- Name: is_canonical_media_type(text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_canonical_media_type(value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
	SELECT octet_length(value) BETWEEN 1 AND 128
		AND translate(
			value,
			'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$&^_.+-/',
			''
		) = ''
		AND length(value) - length(replace(value, '/', '')) = 1
		AND split_part(value, '/', 1) <> ''
		AND split_part(value, '/', 2) <> ''
$_$;


--
-- Name: is_history_metadata_projection(jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_history_metadata_projection(document jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE
	entry record;
	field_count integer := 0;
BEGIN
	IF pg_catalog.jsonb_typeof(document) <> 'object'
		OR decodex.has_credential_material(document)
	THEN
		RETURN false;
	END IF;
	FOR entry IN SELECT key, value FROM pg_catalog.jsonb_each(document) LOOP
		field_count := field_count + 1;
		IF field_count > 32 OR pg_catalog.octet_length(entry.key) NOT BETWEEN 1 AND 64 THEN
			RETURN false;
		END IF;
		IF pg_catalog.jsonb_typeof(entry.value) = 'string' THEN
			IF pg_catalog.octet_length(entry.value OPERATOR(pg_catalog.#>>) '{}') > 256 THEN
				RETURN false;
			END IF;
		ELSIF pg_catalog.jsonb_typeof(entry.value) <> 'boolean' THEN
			RETURN false;
		END IF;
	END LOOP;
	RETURN true;
END
$$;


--
-- Name: is_meaningful_evidence(jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_meaningful_evidence(document jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE
	entry jsonb;
BEGIN
	CASE jsonb_typeof(document)
		WHEN 'object' THEN
			FOR entry IN SELECT value FROM jsonb_each(document)
			LOOP
				IF decodex.is_meaningful_evidence(entry) THEN
					RETURN true;
				END IF;
			END LOOP;
		WHEN 'array' THEN
			FOR entry IN SELECT value FROM jsonb_array_elements(document)
			LOOP
				IF decodex.is_meaningful_evidence(entry) THEN
					RETURN true;
				END IF;
			END LOOP;
		WHEN 'string' THEN
			RETURN length(btrim(decodex.normalize_unicode_whitespace(document #>> '{}'))) > 0;
		WHEN 'number', 'boolean' THEN
			RETURN true;
		ELSE
			NULL;
	END CASE;

	RETURN false;
END
$$;


--
-- Name: is_objective_criteria(text[]); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_objective_criteria(document text[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE item text;
BEGIN
	IF pg_catalog.array_ndims(document) <> 1
		OR pg_catalog.cardinality(document) NOT BETWEEN 1 AND 32
	THEN RETURN false; END IF;
	FOREACH item IN ARRAY document
	LOOP
		IF item IS NULL
			OR pg_catalog.octet_length(item) NOT BETWEEN 1 AND 4096
			OR item COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
			OR item COLLATE pg_catalog."C" ~ U&'[\0080-\009F]'
			OR decodex.has_credential_material(item)
		THEN RETURN false; END IF;
	END LOOP;
	RETURN pg_catalog.cardinality(document) = (
		SELECT pg_catalog.count(DISTINCT criterion)
		FROM pg_catalog.unnest(document) AS criterion
	);
END
$$;


--
-- Name: is_policy_snapshot(jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_policy_snapshot(document jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE entry record;
DECLARE field_count bigint;
BEGIN
	IF pg_catalog.jsonb_typeof(document) <> 'object' THEN
		RETURN false;
	END IF;
	SELECT count(*) INTO field_count FROM pg_catalog.jsonb_object_keys(document);
	IF field_count > 32 THEN RETURN false; END IF;
	FOR entry IN SELECT key, value FROM pg_catalog.jsonb_each(document)
	LOOP
		IF pg_catalog.octet_length(entry.key) NOT BETWEEN 1 AND 64
			OR entry.key COLLATE pg_catalog."C" !~ '^[a-z][a-z0-9_]*$'
			OR pg_catalog.jsonb_typeof(entry.value) NOT IN ('string', 'boolean')
			OR (
				pg_catalog.jsonb_typeof(entry.value) = 'string'
				AND (
					pg_catalog.octet_length(entry.value OPERATOR(pg_catalog.#>>) '{}') > 256
					OR (entry.value OPERATOR(pg_catalog.#>>) '{}') COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
					OR (entry.value OPERATOR(pg_catalog.#>>) '{}') COLLATE pg_catalog."C" ~ U&'[\0080-\009F]'
				)
			)
		THEN
			RETURN false;
		END IF;
	END LOOP;
	RETURN true;
END
$_$;


--
-- Name: is_program_metrics(jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_program_metrics(document jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE item jsonb;
DECLARE item_count bigint;
DECLARE metric_keys text[] := ARRAY[]::text[];
BEGIN
	IF pg_catalog.jsonb_typeof(document) <> 'array' THEN RETURN false; END IF;
	SELECT pg_catalog.count(*) INTO item_count FROM pg_catalog.jsonb_array_elements(document);
	IF item_count > 64 THEN RETURN false; END IF;
	FOR item IN SELECT value FROM pg_catalog.jsonb_array_elements(document)
	LOOP
		IF pg_catalog.jsonb_typeof(item) <> 'object'
			OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(item)) <> 4
			OR NOT item OPERATOR(pg_catalog.?&) ARRAY['key','value','unit','provenance']
			OR pg_catalog.jsonb_typeof(item->'key') <> 'string'
			OR pg_catalog.jsonb_typeof(item->'value') <> 'string'
			OR pg_catalog.jsonb_typeof(item->'unit') <> 'string'
			OR pg_catalog.jsonb_typeof(item->'provenance') <> 'object'
			OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(item->'provenance')) <> 2
			OR NOT (item->'provenance') OPERATOR(pg_catalog.?&) ARRAY['source','observed_at_microseconds']
			OR pg_catalog.jsonb_typeof(item->'provenance'->'source') <> 'string'
			OR pg_catalog.jsonb_typeof(item->'provenance'->'observed_at_microseconds') <> 'number'
			OR (item->>'key') COLLATE pg_catalog."C" !~ '^[a-z][a-z0-9_]{0,63}$'
			OR pg_catalog.octet_length(item->>'value') NOT BETWEEN 1 AND 256
			OR pg_catalog.octet_length(item->>'unit') NOT BETWEEN 1 AND 64
			OR pg_catalog.octet_length(item->'provenance'->>'source') NOT BETWEEN 1 AND 256
			OR (item->>'value') COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
			OR (item->>'unit') COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
			OR (item->'provenance'->>'source') COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
			OR (item->>'value') COLLATE pg_catalog."C" ~ U&'[\0080-\009F]'
			OR (item->>'unit') COLLATE pg_catalog."C" ~ U&'[\0080-\009F]'
			OR (item->'provenance'->>'source') COLLATE pg_catalog."C" ~ U&'[\0080-\009F]'
			OR (item->'provenance'->>'observed_at_microseconds') COLLATE pg_catalog."C" !~ '^(0|[1-9][0-9]{0,17})$'
			OR (item->'provenance'->>'observed_at_microseconds')::numeric > 253402300799999999
			OR (item->>'key') = ANY(metric_keys)
			OR decodex.has_credential_material(item)
		THEN RETURN false; END IF;
		metric_keys := pg_catalog.array_append(metric_keys, item->>'key');
	END LOOP;
	RETURN true;
END
$_$;


--
-- Name: is_program_signals(jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_program_signals(document jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE item jsonb;
DECLARE item_count bigint;
DECLARE signal_ids text[] := ARRAY[]::text[];
BEGIN
	IF pg_catalog.jsonb_typeof(document) <> 'array' THEN RETURN false; END IF;
	SELECT pg_catalog.count(*) INTO item_count FROM pg_catalog.jsonb_array_elements(document);
	IF item_count > 64 THEN RETURN false; END IF;
	FOR item IN SELECT value FROM pg_catalog.jsonb_array_elements(document)
	LOOP
		IF pg_catalog.jsonb_typeof(item) <> 'object'
			OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(item)) <> 4
			OR NOT item OPERATOR(pg_catalog.?&) ARRAY['id','kind','summary','provenance']
			OR pg_catalog.jsonb_typeof(item->'id') <> 'string'
			OR pg_catalog.jsonb_typeof(item->'kind') <> 'string'
			OR pg_catalog.jsonb_typeof(item->'summary') <> 'string'
			OR pg_catalog.jsonb_typeof(item->'provenance') <> 'object'
			OR (SELECT pg_catalog.count(*) FROM pg_catalog.jsonb_object_keys(item->'provenance')) <> 2
			OR NOT (item->'provenance') OPERATOR(pg_catalog.?&) ARRAY['source','observed_at_microseconds']
			OR pg_catalog.jsonb_typeof(item->'provenance'->'source') <> 'string'
			OR pg_catalog.jsonb_typeof(item->'provenance'->'observed_at_microseconds') <> 'number'
			OR (item->>'id') COLLATE pg_catalog."C" !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
			OR (item->>'kind') COLLATE pg_catalog."C" !~ '^[a-z][a-z0-9_]{0,63}$'
			OR pg_catalog.octet_length(item->>'summary') NOT BETWEEN 1 AND 4096
			OR pg_catalog.octet_length(item->'provenance'->>'source') NOT BETWEEN 1 AND 256
			OR (item->>'summary') COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
			OR (item->'provenance'->>'source') COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
			OR (item->>'summary') COLLATE pg_catalog."C" ~ U&'[\0080-\009F]'
			OR (item->'provenance'->>'source') COLLATE pg_catalog."C" ~ U&'[\0080-\009F]'
			OR (item->'provenance'->>'observed_at_microseconds') COLLATE pg_catalog."C" !~ '^(0|[1-9][0-9]{0,17})$'
			OR (item->'provenance'->>'observed_at_microseconds')::numeric > 253402300799999999
			OR (item->>'id') = ANY(signal_ids)
			OR decodex.has_credential_material(item)
		THEN RETURN false; END IF;
		signal_ids := pg_catalog.array_append(signal_ids, item->>'id');
	END LOOP;
	RETURN true;
END
$_$;


--
-- Name: is_project_metadata(jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_project_metadata(document jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE entry record;
DECLARE field_count bigint;
BEGIN
	IF jsonb_typeof(document) <> 'object' THEN
		RETURN false;
	END IF;
	SELECT count(*) INTO field_count FROM jsonb_object_keys(document);
	IF field_count > 32 THEN RETURN false; END IF;
	FOR entry IN SELECT key, value FROM jsonb_each(document)
	LOOP
		IF pg_catalog.octet_length(entry.key) NOT BETWEEN 1 AND 64
			OR entry.key COLLATE "C" !~ '^[a-z][a-z0-9_]*$'
			OR pg_catalog.jsonb_typeof(entry.value) NOT IN ('string', 'boolean')
			OR (
				pg_catalog.jsonb_typeof(entry.value) = 'string'
				AND (
					pg_catalog.octet_length(entry.value OPERATOR(pg_catalog.#>>) '{}') > 256
					OR (entry.value OPERATOR(pg_catalog.#>>) '{}') COLLATE "C" ~ '[[:cntrl:]]'
					OR (entry.value OPERATOR(pg_catalog.#>>) '{}') COLLATE "C" ~ U&'[\0080-\009F]'
				)
			)
		THEN
			RETURN false;
		END IF;
	END LOOP;
	RETURN true;
END
$_$;


--
-- Name: is_role_profile_configuration(text, text, text, text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_role_profile_configuration(p_model text, p_reasoning_effort text, p_service_tier text, p_instructions text, p_provenance text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
SELECT p_model IS NOT NULL AND pg_catalog.octet_length(p_model) BETWEEN 1 AND 128
	AND p_reasoning_effort IS NOT NULL
	AND pg_catalog.octet_length(p_reasoning_effort) BETWEEN 1 AND 32
	AND p_reasoning_effort COLLATE pg_catalog."C" ~ '^[a-z][a-z0-9_-]{0,31}$'
	AND p_service_tier IS NOT NULL
	AND pg_catalog.octet_length(p_service_tier) BETWEEN 1 AND 32
	AND p_service_tier COLLATE pg_catalog."C" ~ '^[a-z][a-z0-9_-]{0,31}$'
	AND p_instructions IS NOT NULL
	AND pg_catalog.octet_length(p_instructions) BETWEEN 1 AND 65536
	AND (p_provenance IS NULL OR pg_catalog.octet_length(p_provenance) BETWEEN 1 AND 4096)
	AND p_model COLLATE pg_catalog."C" !~ '[[:cntrl:]]'
	AND p_instructions COLLATE pg_catalog."C" !~ U&'[\0080-\009F]'
	AND (p_provenance IS NULL OR p_provenance COLLATE pg_catalog."C" !~ U&'[\0080-\009F]')
	AND NOT decodex.has_credential_material(p_model)
	AND NOT decodex.has_credential_material(p_reasoning_effort)
	AND NOT decodex.has_credential_material(p_service_tier)
	AND NOT decodex.has_credential_material(p_instructions)
	AND (p_provenance IS NULL OR NOT decodex.has_credential_material(p_provenance))
$_$;


--
-- Name: is_valid_operation_duration(interval); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_valid_operation_duration(value interval) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT extract(year FROM value) = 0
		AND extract(month FROM value) = 0
		AND extract(epoch FROM value) * 1000 BETWEEN 1 AND 31536000000
		AND extract(epoch FROM value) * 1000 = trunc(extract(epoch FROM value) * 1000)
$$;


--
-- Name: is_work_item_criteria(text[]); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_work_item_criteria(document text[]) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE item text;
BEGIN
	IF pg_catalog.array_ndims(document) <> 1
		OR pg_catalog.cardinality(document) NOT BETWEEN 1 AND 32
	THEN RETURN false; END IF;
	FOREACH item IN ARRAY document LOOP
		IF item IS NULL OR NOT decodex.is_work_item_text(item, 4096) THEN RETURN false; END IF;
	END LOOP;
	RETURN pg_catalog.cardinality(document) = (
		SELECT pg_catalog.count(DISTINCT criterion)
		FROM pg_catalog.unnest(document) AS criterion
	);
END
$$;


--
-- Name: is_work_item_text(text, integer); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.is_work_item_text(value text, maximum_bytes integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
SELECT maximum_bytes > 0
	AND pg_catalog.octet_length(value) BETWEEN 1 AND maximum_bytes
	AND value COLLATE pg_catalog."C" !~ '[[:cntrl:]]'
	AND value COLLATE pg_catalog."C" !~ U&'[\0080-\009F]'
	AND NOT decodex.has_credential_material(value)
$$;


--
-- Name: issue_history_cursor(uuid, uuid, integer); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.issue_history_cursor(p_conversation_id uuid, p_parent_cursor_id uuid, p_page_size integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE current_high_water bigint;
DECLARE v_snapshot_high_water bigint;
DECLARE v_snapshot_version_sequence bigint;
DECLARE start_position bigint := 0;
DECLARE boundary_position bigint;
DECLARE boundary_item_id uuid;
DECLARE issued_cursor_id uuid;
DECLARE parent_page_size integer;
DECLARE cursor_expiry timestamptz;
DECLARE issuance_time timestamptz := pg_catalog.clock_timestamp();
DECLARE cursor_created_at timestamptz;
DECLARE global_cursor_count bigint;
DECLARE conversation_cursor_count bigint;
BEGIN
	IF p_conversation_id IS NULL OR p_page_size NOT BETWEEN 1 AND 100 THEN
		RAISE EXCEPTION 'history cursor page size is invalid' USING ERRCODE = '22023';
	END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(1272);
	PERFORM 1 FROM decodex.conversations
		WHERE conversation_id = p_conversation_id FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'history cursor Conversation does not exist' USING ERRCODE = '22023';
	END IF;
	PERFORM decodex.prune_history_snapshots();
	SELECT COALESCE(max(history_position), 0) INTO current_high_water
		FROM decodex.history_items WHERE conversation_id = p_conversation_id;
	IF p_parent_cursor_id IS NULL THEN
		v_snapshot_high_water := current_high_water;
		SELECT COALESCE(max(version_sequence), 0) INTO v_snapshot_version_sequence
			FROM decodex.history_item_versions WHERE conversation_id = p_conversation_id;
		cursor_expiry := issuance_time + interval '1 hour';
	ELSE
		SELECT snapshot_high_water, snapshot_version_sequence, last_position, page_size, expires_at
			INTO v_snapshot_high_water, v_snapshot_version_sequence, start_position,
				parent_page_size, cursor_expiry
			FROM decodex.history_cursors
			WHERE cursor_id = p_parent_cursor_id
				AND conversation_id = p_conversation_id
				AND expires_at > issuance_time;
		IF v_snapshot_high_water IS NULL THEN
			RAISE EXCEPTION 'history cursor parent was not issued for this Conversation'
				USING ERRCODE = '22023';
		END IF;
		IF p_page_size <> parent_page_size THEN
			RAISE EXCEPTION 'history cursor page size must match its issued parent'
				USING ERRCODE = '22023';
		END IF;
	END IF;
	cursor_created_at := CASE
		WHEN issuance_time > cursor_expiry - interval '1 hour' THEN issuance_time
		ELSE cursor_expiry - interval '1 hour'
	END;
	SELECT history_position, history_item_id INTO boundary_position, boundary_item_id FROM (
		SELECT DISTINCT ON (history_position) history_position, history_item_id
		FROM decodex.history_item_versions
		WHERE conversation_id = p_conversation_id
			AND version_sequence <= v_snapshot_version_sequence
		ORDER BY history_position, version_sequence DESC
	) AS snapshot_items
		WHERE history_position > start_position
			AND history_position <= v_snapshot_high_water
		ORDER BY history_position
		OFFSET p_page_size - 1 LIMIT 1;
	IF boundary_position IS NULL THEN
		RAISE EXCEPTION 'history cursor requires a canonical page boundary'
			USING ERRCODE = '22023';
	END IF;
	IF boundary_position >= v_snapshot_high_water THEN
		RAISE EXCEPTION 'history cursor requires another page in its snapshot'
			USING ERRCODE = '22023';
	END IF;
	SELECT cursor_id INTO issued_cursor_id FROM decodex.history_cursors AS cursor
	WHERE cursor.conversation_id = p_conversation_id
		AND cursor.snapshot_high_water = v_snapshot_high_water
		AND cursor.snapshot_version_sequence = v_snapshot_version_sequence
		AND cursor.page_size = p_page_size
		AND cursor.last_position = boundary_position
		AND cursor.history_item_id = boundary_item_id
		AND cursor.parent_cursor_id IS NOT DISTINCT FROM p_parent_cursor_id;
	IF issued_cursor_id IS NOT NULL THEN
		RETURN issued_cursor_id;
	END IF;
	SELECT count(*), count(*) FILTER (WHERE conversation_id = p_conversation_id)
		INTO global_cursor_count, conversation_cursor_count
		FROM decodex.history_cursors;
	IF global_cursor_count >= 4096 OR conversation_cursor_count >= 512 THEN
		RAISE EXCEPTION 'history cursor capacity is exhausted' USING ERRCODE = '54000';
	END IF;
	INSERT INTO decodex.history_cursors (
		conversation_id, snapshot_high_water, snapshot_version_sequence, page_size, last_position,
		history_item_id, parent_cursor_id, created_at, expires_at
	) VALUES (
		p_conversation_id, v_snapshot_high_water, v_snapshot_version_sequence,
		p_page_size, boundary_position,
		boundary_item_id, p_parent_cursor_id, cursor_created_at, cursor_expiry
	)
	RETURNING cursor_id INTO issued_cursor_id;
	RETURN issued_cursor_id;
END;
$$;


--
-- Name: lease_ttl_milliseconds(interval); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.lease_ttl_milliseconds(value interval) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE
	milliseconds numeric;
BEGIN
	IF extract(year FROM value) <> 0 OR extract(month FROM value) <> 0 THEN
		RAISE EXCEPTION 'lease TTL must be a fixed duration' USING ERRCODE = '22023';
	END IF;

	milliseconds := extract(epoch FROM value) * 1000;

	IF milliseconds < 1
		OR milliseconds > 31536000000
		OR milliseconds <> trunc(milliseconds)
	THEN
		RAISE EXCEPTION 'lease TTL must be a positive whole number of milliseconds no greater than 365 days'
			USING ERRCODE = '22023';
	END IF;

	RETURN milliseconds::bigint;
END
$$;


--
-- Name: lock_account_routing_universe_exact(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.lock_account_routing_universe_exact() RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE visible_count bigint;
DECLARE routing_count bigint;
DECLARE current_mode decodex.account_selection_mode;
DECLARE current_fixed_account_id uuid;
BEGIN
	SELECT control.mode,control.fixed_account_id
	INTO current_mode,current_fixed_account_id
	FROM decodex.account_routing_control AS control
	WHERE control.singleton FOR UPDATE;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'account routing universe is incompatible'
			USING ERRCODE='55000',CONSTRAINT='account_routing_universe_complete';
	END IF;
	PERFORM account.account_id FROM decodex.accounts AS account
	WHERE account.tombstoned_at IS NULL
	ORDER BY account.account_id FOR UPDATE OF account;
	PERFORM ordering.account_id FROM decodex.account_routing_order AS ordering
	ORDER BY ordering.account_id,ordering.position FOR UPDATE OF ordering;
	SELECT pg_catalog.count(*) INTO visible_count
	FROM decodex.accounts AS account WHERE account.tombstoned_at IS NULL;
	SELECT pg_catalog.count(*) INTO routing_count FROM decodex.account_routing_order;
	IF visible_count>512 OR routing_count>512
		OR routing_count<>(SELECT pg_catalog.count(DISTINCT ordering.position)
			FROM decodex.account_routing_order AS ordering)
		OR EXISTS (
			SELECT 1 FROM decodex.account_routing_order AS ordering
			LEFT JOIN decodex.accounts AS account ON account.account_id=ordering.account_id
			WHERE account.account_id IS NULL OR account.tombstoned_at IS NOT NULL
				OR ordering.position<0 OR ordering.position>=routing_count
		)
		OR (current_mode='fixed') IS DISTINCT FROM
			(current_fixed_account_id IS NOT NULL)
		OR (current_fixed_account_id IS NOT NULL AND NOT EXISTS (
			SELECT 1 FROM decodex.account_routing_order AS ordering
			WHERE ordering.account_id=current_fixed_account_id
		))
		OR visible_count<>routing_count
		OR EXISTS (
			SELECT 1 FROM decodex.accounts AS account
			LEFT JOIN decodex.account_routing_order AS ordering
				ON ordering.account_id=account.account_id
			WHERE account.tombstoned_at IS NULL AND ordering.account_id IS NULL
		)
	THEN
		RAISE EXCEPTION 'account routing universe is incompatible'
			USING ERRCODE='55000',CONSTRAINT='account_routing_universe_complete';
	END IF;
	RETURN true;
END
$$;


--
-- Name: mark_codex_experiment_creation_possible_exact(text, text, uuid, bigint, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.mark_codex_experiment_creation_possible_exact(p_protocol text, p_idempotency_key text, p_experiment_id uuid, p_expected_revision bigint, p_attempt_id uuid) RETURNS TABLE(response_bytes bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; replay bytea; fenced timestamptz; experiment_row record;
DECLARE authority_run_id uuid;
DECLARE core jsonb; effect jsonb; response bytea;
BEGIN
	request:=pg_catalog.jsonb_build_object('operation','mark_codex_experiment_creation_possible',
		'protocol',p_protocol,'experiment_id',p_experiment_id,
		'expected_revision',p_expected_revision,'attempt_id',p_attempt_id);
	replay:=decodex.reserve_exact_codex_experiment_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN QUERY SELECT replay,true; RETURN; END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	SELECT managed_run_id INTO authority_run_id FROM decodex.codex_experiments
	WHERE experiment_id=p_experiment_id;
	IF NOT FOUND THEN
		response:=decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'mark_codex_experiment_creation_possible',
			'creation_not_authorized');
		RETURN QUERY SELECT response,false; RETURN;
	END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1338,pg_catalog.hashtext(authority_run_id::text));
	PERFORM pg_catalog.pg_advisory_xact_lock(1358);
	PERFORM pg_catalog.pg_advisory_xact_lock(1358,pg_catalog.hashtext(p_experiment_id::text));
	SELECT * INTO experiment_row FROM decodex.codex_experiments
	WHERE experiment_id=p_experiment_id FOR UPDATE;
	IF NOT FOUND OR experiment_row.revision<>p_expected_revision OR p_expected_revision<>1
		OR experiment_row.state<>'prepared'
		OR experiment_row.managed_run_id<>authority_run_id OR p_attempt_id IS NULL THEN
		response:=decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'mark_codex_experiment_creation_possible',
			'creation_not_authorized');
		RETURN QUERY SELECT response,false; RETURN;
	END IF;
	PERFORM 1 FROM decodex.routing_snapshots AS snapshot
	JOIN decodex.managed_runs AS run
		ON run.managed_run_id=snapshot.managed_run_id
		AND run.revision=snapshot.managed_run_revision
	JOIN decodex.runtime_sessions AS session
		ON session.runtime_session_id=snapshot.runtime_session_id
		AND session.revision=snapshot.runtime_session_revision
	WHERE (snapshot.snapshot_id,snapshot.managed_run_id,snapshot.managed_run_revision)=
		(experiment_row.routing_snapshot_id,experiment_row.managed_run_id,
			experiment_row.managed_run_revision)
		AND (run.runtime_session_id,run.runtime_session_revision)=
			(snapshot.runtime_session_id,snapshot.runtime_session_revision)
	FOR SHARE OF snapshot,run,session;
	IF NOT FOUND THEN
		response:=decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'mark_codex_experiment_creation_possible',
			'creation_not_authorized');
		RETURN QUERY SELECT response,false; RETURN;
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.codex_experiment_creation_attempts
		WHERE attempt_id=p_attempt_id) THEN
		response:=decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'mark_codex_experiment_creation_possible',
			'attempt_identity_conflict');
		RETURN QUERY SELECT response,false; RETURN;
	END IF;
	fenced:=pg_catalog.clock_timestamp();
	INSERT INTO decodex.codex_experiment_revisions VALUES(
		p_experiment_id,2,'creation_possible',fenced);
	INSERT INTO decodex.codex_experiment_creation_attempts VALUES(
		p_experiment_id,p_attempt_id,2,fenced);
	UPDATE decodex.codex_experiments SET revision=2,state='creation_possible',updated_at=fenced
	WHERE experiment_id=p_experiment_id;
	core:=pg_catalog.jsonb_build_object('operation','mark_codex_experiment_creation_possible',
		'experiment_id',p_experiment_id,'revision',2,'state','creation_possible',
		'attempt_id',p_attempt_id,
		'fenced_at_micros',(extract(epoch FROM fenced)*1000000)::bigint);
	effect:=core||pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN QUERY SELECT response,false;
END
$$;


--
-- Name: mark_codex_experiment_title_set_possible_exact(text, text, uuid, bigint, uuid, text, bigint, text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.mark_codex_experiment_title_set_possible_exact(p_protocol text, p_idempotency_key text, p_experiment_id uuid, p_expected_revision bigint, p_title_attempt_id uuid, p_thread_id text, p_request_id bigint, p_request_digest text, p_requested_title text) RETURNS TABLE(response_bytes bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; replay bytea; fenced timestamptz; experiment_row record;
DECLARE core jsonb; effect jsonb; response bytea;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','mark_codex_experiment_title_set_possible','protocol',p_protocol,
		'experiment_id',p_experiment_id,'expected_revision',p_expected_revision,
		'title_attempt_id',p_title_attempt_id,'thread_id',p_thread_id,
		'request_id',p_request_id,'request_digest',p_request_digest,
		'requested_title',p_requested_title);
	replay:=decodex.reserve_exact_codex_experiment_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN QUERY SELECT replay,true; RETURN; END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1358);
	PERFORM pg_catalog.pg_advisory_xact_lock(1358,pg_catalog.hashtext(p_experiment_id::text));
	SELECT experiment.*,receipt.start_request_id AS bound_start_request_id
	INTO experiment_row FROM decodex.codex_experiments AS experiment
	JOIN decodex.codex_experiment_start_receipts AS receipt USING (experiment_id)
	WHERE experiment.experiment_id=p_experiment_id AND receipt.thread_id=p_thread_id
	FOR SHARE OF experiment,receipt;
	IF NOT FOUND OR experiment_row.revision<>p_expected_revision OR p_expected_revision<>3
		OR experiment_row.state<>'thread_bound' OR p_title_attempt_id IS NULL
		OR p_request_id IS NULL OR p_request_id<=0
		OR p_request_id<=experiment_row.bound_start_request_id
		OR p_request_digest IS NULL OR p_request_digest!~'^[0-9a-f]{64}$'
		OR p_requested_title IS DISTINCT FROM experiment_row.thread_title THEN
		response:=decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'mark_codex_experiment_title_set_possible',
			'title_set_not_authorized');
		RETURN QUERY SELECT response,false; RETURN;
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.codex_experiment_title_set_attempts
		WHERE experiment_id=p_experiment_id OR title_attempt_id=p_title_attempt_id) THEN
		response:=decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'mark_codex_experiment_title_set_possible',
			'title_attempt_identity_conflict');
		RETURN QUERY SELECT response,false; RETURN;
	END IF;
	fenced:=pg_catalog.clock_timestamp();
	INSERT INTO decodex.codex_experiment_title_set_attempts(
		experiment_id,title_attempt_id,thread_id,request_id,request_digest,requested_title,fenced_at
	) VALUES (
		p_experiment_id,p_title_attempt_id,p_thread_id,p_request_id,p_request_digest,
		p_requested_title,fenced
	);
	core:=pg_catalog.jsonb_build_object(
		'operation','mark_codex_experiment_title_set_possible',
		'experiment_id',p_experiment_id,'experiment_revision',3,
		'title_attempt_id',p_title_attempt_id,'thread_id',p_thread_id,
		'request_id',p_request_id,'request_digest',p_request_digest,
		'requested_title',p_requested_title,
		'fenced_at_micros',(extract(epoch FROM fenced)*1000000)::bigint);
	effect:=core||pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',
		outcome_class='success',effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN QUERY SELECT response,false;
END
$_$;


--
-- Name: mark_process_generation_death_unknown_exact(uuid, bigint, decodex.process_generation_loss_reason); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.mark_process_generation_death_unknown_exact(p_generation_id uuid, p_expected_revision bigint, p_reason decodex.process_generation_loss_reason) RETURNS TABLE(result_code text, revision bigint, state decodex.process_generation_state, updated_at_micros bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE generation decodex.process_generations%ROWTYPE;
DECLARE now_value timestamptz;
BEGIN
	SELECT * INTO generation FROM decodex.process_generations
	WHERE generation_id = p_generation_id FOR UPDATE;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'generation_missing', 0::bigint,
			'starting'::decodex.process_generation_state, 0::bigint;
		RETURN;
	END IF;
	IF p_expected_revision IS NULL OR p_reason IS NULL THEN
		RETURN QUERY SELECT 'stale_generation', generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF generation.state = 'death_unknown' THEN
		RETURN QUERY SELECT
			CASE WHEN p_expected_revision = generation.revision - 1
					AND p_reason = generation.authority_loss_reason
				THEN 'replayed' ELSE 'stale_generation' END,
			generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF generation.state = 'dead'
		OR generation.revision <> p_expected_revision
	THEN
		RETURN QUERY SELECT 'stale_generation', generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	now_value := pg_catalog.clock_timestamp();
	UPDATE decodex.process_generations AS target
	SET state = 'death_unknown',
		authority_loss_reason = p_reason,
		revision = target.revision + 1,
		updated_at = now_value
	WHERE target.generation_id = p_generation_id;
	RETURN QUERY SELECT 'death_unknown', p_expected_revision + 1,
		'death_unknown'::decodex.process_generation_state,
		(extract(epoch FROM now_value)*1000000)::bigint;
END;
$$;


--
-- Name: mark_process_generation_ready_exact(uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.mark_process_generation_ready_exact(p_generation_id uuid, p_expected_revision bigint) RETURNS TABLE(result_code text, revision bigint, state decodex.process_generation_state, updated_at_micros bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE generation decodex.process_generations%ROWTYPE;
DECLARE now_value timestamptz;
BEGIN
	SELECT * INTO generation FROM decodex.process_generations
	WHERE generation_id = p_generation_id FOR UPDATE;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'generation_missing', 0::bigint,
			'starting'::decodex.process_generation_state, 0::bigint;
		RETURN;
	END IF;
	IF p_expected_revision IS NULL THEN
		RETURN QUERY SELECT 'stale_generation', generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF generation.state = 'ready' THEN
		RETURN QUERY SELECT
			CASE WHEN p_expected_revision = generation.revision - 1
				THEN 'replayed' ELSE 'stale_generation' END,
			generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF generation.revision <> p_expected_revision
		OR generation.state <> 'starting'
		OR generation.process_id IS NULL
	THEN
		RETURN QUERY SELECT 'stale_generation', generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	now_value := pg_catalog.clock_timestamp();
	UPDATE decodex.process_generations AS target
	SET state = 'ready', revision = target.revision + 1, updated_at = now_value
	WHERE target.generation_id = p_generation_id;
	RETURN QUERY SELECT 'ready', p_expected_revision + 1,
		'ready'::decodex.process_generation_state,
		(extract(epoch FROM now_value)*1000000)::bigint;
END;
$$;


--
-- Name: mark_process_generation_stopping_exact(uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.mark_process_generation_stopping_exact(p_generation_id uuid, p_expected_revision bigint) RETURNS TABLE(result_code text, revision bigint, state decodex.process_generation_state, updated_at_micros bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE generation decodex.process_generations%ROWTYPE;
DECLARE now_value timestamptz;
BEGIN
	SELECT * INTO generation FROM decodex.process_generations
	WHERE generation_id = p_generation_id FOR UPDATE;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'generation_missing', 0::bigint,
			'starting'::decodex.process_generation_state, 0::bigint;
		RETURN;
	END IF;
	IF p_expected_revision IS NULL THEN
		RETURN QUERY SELECT 'stale_generation', generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF generation.state = 'stopping' THEN
		RETURN QUERY SELECT
			CASE WHEN p_expected_revision IN (generation.revision - 1, generation.revision)
				THEN 'replayed' ELSE 'stale_generation' END,
			generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF generation.revision <> p_expected_revision
		OR generation.state NOT IN ('starting', 'ready', 'death_unknown')
		OR generation.process_id IS NULL
	THEN
		RETURN QUERY SELECT 'stale_generation', generation.revision, generation.state,
			(extract(epoch FROM generation.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	now_value := pg_catalog.clock_timestamp();
	UPDATE decodex.process_generations AS target
	SET state = 'stopping',
		authority_loss_reason = NULL,
		revision = target.revision + 1,
		updated_at = now_value
	WHERE target.generation_id = p_generation_id;
	RETURN QUERY SELECT 'stopping', p_expected_revision + 1,
		'stopping'::decodex.process_generation_state,
		(extract(epoch FROM now_value)*1000000)::bigint;
END;
$$;


--
-- Name: mark_provider_attempt_unknown_exact(uuid, bigint, decodex.provider_attempt_unknown_reason); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.mark_provider_attempt_unknown_exact(p_attempt_id uuid, p_expected_revision bigint, p_reason decodex.provider_attempt_unknown_reason) RETURNS TABLE(result_code text, revision bigint, state decodex.provider_attempt_state, updated_at_micros bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE attempt decodex.provider_attempts%ROWTYPE;
DECLARE scope_kind decodex.provider_attempt_consumer_kind;
DECLARE scope_conversation_id uuid;
DECLARE scope_managed_run_id uuid;
DECLARE now_value timestamptz;
BEGIN
	SELECT consumer_kind, conversation_id, managed_run_id
	INTO scope_kind, scope_conversation_id, scope_managed_run_id
	FROM decodex.provider_attempts
	WHERE attempt_id = p_attempt_id;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'attempt_missing', 0::bigint,
			'prepared'::decodex.provider_attempt_state, 0::bigint;
		RETURN;
	END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1401,
		pg_catalog.hashtext(
			scope_kind::text || ':' ||
			COALESCE(scope_conversation_id::text, scope_managed_run_id::text)
		)
	);
	SELECT * INTO attempt
	FROM decodex.provider_attempts
	WHERE attempt_id = p_attempt_id
	FOR UPDATE;
	IF p_expected_revision IS NULL
		OR p_expected_revision <= 0
		OR p_reason IS NULL
		OR p_reason = 'restore_projection'
	THEN
		RETURN QUERY SELECT 'invalid_input', attempt.revision, attempt.state,
			(extract(epoch FROM attempt.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF attempt.state = 'unknown' THEN
		RETURN QUERY SELECT
			CASE
				WHEN p_expected_revision = attempt.revision - 1
					AND p_reason = attempt.unknown_reason
				THEN 'replayed'
				ELSE 'stale_attempt'
			END,
			attempt.revision,
			attempt.state,
			(extract(epoch FROM attempt.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	IF attempt.state <> 'dispatch_authorized'
		OR attempt.revision <> p_expected_revision
	THEN
		RETURN QUERY SELECT 'stale_attempt', attempt.revision, attempt.state,
			(extract(epoch FROM attempt.updated_at)*1000000)::bigint;
		RETURN;
	END IF;
	now_value := pg_catalog.clock_timestamp();
	UPDATE decodex.provider_attempts AS target
	SET state = 'unknown',
		unknown_reason = p_reason,
		revision = target.revision + 1,
		updated_at = now_value
	WHERE target.attempt_id = p_attempt_id;
	RETURN QUERY SELECT 'unknown', p_expected_revision + 1,
		'unknown'::decodex.provider_attempt_state,
		(extract(epoch FROM now_value)*1000000)::bigint;
END;
$$;


--
-- Name: normalize_unicode_whitespace(text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.normalize_unicode_whitespace(value text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT translate(
		value,
		U&'\0009\000A\000B\000C\000D\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000',
		repeat(' ', 25)
	)
$$;


--
-- Name: observe_account_profile_exact(uuid, bigint, decodex.account_provider_kind, text, bigint, text, text, bigint, bigint, bigint, integer, integer, text[], bigint[]); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.observe_account_profile_exact(p_account_id uuid, p_expected_revision bigint, p_expected_provider decodex.account_provider_kind, p_expected_provider_account_id text, p_observed_at_micros bigint, p_display_name text, p_username text, p_lifetime_tokens bigint, p_peak_daily_tokens bigint, p_longest_task_seconds bigint, p_current_streak_days integer, p_longest_streak_days integer, p_daily_start_dates text[], p_daily_tokens bigint[]) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE account decodex.accounts%ROWTYPE;
DECLARE existing_observed_at bigint;
DECLARE daily_count integer;
DECLARE date_value text;
DECLARE date_year integer;
DECLARE date_month integer;
DECLARE date_day integer;
DECLARE maximum_day integer;
DECLARE effective_peak_daily_tokens bigint;
BEGIN
	daily_count:=COALESCE(pg_catalog.cardinality(p_daily_start_dates),0);
	IF p_expected_revision IS NULL OR p_expected_revision<1
		OR p_expected_provider IS NULL OR p_expected_provider_account_id IS NULL
		OR pg_catalog.octet_length(p_expected_provider_account_id)<1
		OR pg_catalog.octet_length(p_expected_provider_account_id)>512
		OR p_observed_at_micros IS NULL OR p_observed_at_micros<1
		OR p_observed_at_micros>253402300799999999
		OR (p_display_name IS NOT NULL AND (
			pg_catalog.octet_length(p_display_name)<1
			OR pg_catalog.octet_length(p_display_name)>256
			OR p_display_name~'[[:cntrl:]]'))
		OR (p_username IS NOT NULL AND (
			pg_catalog.octet_length(p_username)<1 OR pg_catalog.octet_length(p_username)>256
			OR p_username~'[[:cntrl:]]'))
		OR p_lifetime_tokens<0 OR p_peak_daily_tokens<0 OR p_longest_task_seconds<0
		OR p_current_streak_days<0 OR p_longest_streak_days<0
		OR daily_count<>COALESCE(pg_catalog.cardinality(p_daily_tokens),0)
		OR daily_count>36
		OR EXISTS (
			SELECT 1
			FROM ROWS FROM (
				pg_catalog.unnest(p_daily_start_dates),
				pg_catalog.unnest(p_daily_tokens)
			) AS daily(start_date,tokens)
			WHERE daily.start_date IS NULL
				OR daily.tokens IS NULL OR daily.tokens<0
		)
		OR EXISTS (
			SELECT 1
			FROM pg_catalog.unnest(p_daily_start_dates) AS duplicate_date(value)
			GROUP BY duplicate_date.value HAVING pg_catalog.count(*)>1
		)
		OR (p_display_name IS NULL AND p_username IS NULL AND p_lifetime_tokens IS NULL
			AND p_peak_daily_tokens IS NULL AND p_longest_task_seconds IS NULL
			AND p_current_streak_days IS NULL AND p_longest_streak_days IS NULL
			AND daily_count=0)
	THEN RETURN 'invalid_fact'; END IF;

	FOREACH date_value IN ARRAY COALESCE(p_daily_start_dates,ARRAY[]::text[]) LOOP
		IF date_value!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN
			RETURN 'invalid_fact';
		END IF;
		date_year:=substring(date_value FROM 1 FOR 4)::integer;
		date_month:=substring(date_value FROM 6 FOR 2)::integer;
		date_day:=substring(date_value FROM 9 FOR 2)::integer;
		maximum_day:=CASE date_month
			WHEN 1 THEN 31 WHEN 3 THEN 31 WHEN 5 THEN 31 WHEN 7 THEN 31
			WHEN 8 THEN 31 WHEN 10 THEN 31 WHEN 12 THEN 31
			WHEN 4 THEN 30 WHEN 6 THEN 30 WHEN 9 THEN 30 WHEN 11 THEN 30
			WHEN 2 THEN CASE
				WHEN date_year%4=0 AND (date_year%100<>0 OR date_year%400=0) THEN 29
				ELSE 28
			END
			ELSE 0
		END;
		IF date_year<1 OR date_day<1 OR date_day>maximum_day THEN
			RETURN 'invalid_fact';
		END IF;
	END LOOP;
	effective_peak_daily_tokens:=COALESCE(
		p_peak_daily_tokens,
		(SELECT pg_catalog.max(daily.tokens)
			FROM pg_catalog.unnest(p_daily_tokens) AS daily(tokens))
	);

	SELECT * INTO account FROM decodex.accounts
	WHERE account_id=p_account_id FOR UPDATE;
	IF NOT FOUND OR account.tombstoned_at IS NOT NULL THEN
		RETURN 'account_unavailable';
	END IF;
	IF account.revision<>p_expected_revision
		OR account.provider_kind IS DISTINCT FROM p_expected_provider
		OR account.provider_account_id IS DISTINCT FROM p_expected_provider_account_id
	THEN RETURN 'stale_account'; END IF;

	SELECT snapshot.observed_at_micros INTO existing_observed_at
	FROM decodex.account_profile_snapshots AS snapshot
	WHERE snapshot.account_id=p_account_id FOR UPDATE;
	IF FOUND AND existing_observed_at>=p_observed_at_micros THEN
		RETURN 'stale_observation';
	END IF;

	INSERT INTO decodex.account_profile_snapshots(
		account_id,account_revision,provider_kind,provider_account_id,observed_at_micros,
		display_name,username,lifetime_tokens,peak_daily_tokens,longest_task_seconds,
		current_streak_days,longest_streak_days
	) VALUES (
		p_account_id,p_expected_revision,p_expected_provider,p_expected_provider_account_id,
		p_observed_at_micros,p_display_name,p_username,p_lifetime_tokens,effective_peak_daily_tokens,
		p_longest_task_seconds,p_current_streak_days,p_longest_streak_days
	) ON CONFLICT(account_id) DO UPDATE SET
		account_revision=EXCLUDED.account_revision,provider_kind=EXCLUDED.provider_kind,
		provider_account_id=EXCLUDED.provider_account_id,
		observed_at_micros=EXCLUDED.observed_at_micros,
		display_name=EXCLUDED.display_name,username=EXCLUDED.username,
		lifetime_tokens=EXCLUDED.lifetime_tokens,peak_daily_tokens=EXCLUDED.peak_daily_tokens,
		longest_task_seconds=EXCLUDED.longest_task_seconds,
		current_streak_days=EXCLUDED.current_streak_days,
		longest_streak_days=EXCLUDED.longest_streak_days;
	DELETE FROM decodex.account_profile_daily_usage WHERE account_id=p_account_id;
	INSERT INTO decodex.account_profile_daily_usage(
		account_id,start_date,tokens,observed_at_micros
	) SELECT p_account_id,daily.start_date::date,daily.tokens,p_observed_at_micros
	FROM ROWS FROM (
		pg_catalog.unnest(p_daily_start_dates),
		pg_catalog.unnest(p_daily_tokens)
	) AS daily(start_date,tokens);
	RETURN 'observed';
END
$_$;


--
-- Name: observe_account_quota_error_exact(uuid, integer, decodex.account_quota_observation_error, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.observe_account_quota_error_exact(p_account_id uuid, p_duration_minutes integer, p_error_code decodex.account_quota_observation_error, p_observed_at_micros bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF p_account_id IS NULL OR p_duration_minutes IS NULL
		OR p_duration_minutes NOT IN (300,10080) OR p_error_code IS NULL
		OR p_observed_at_micros IS NULL OR p_observed_at_micros<0
		OR p_observed_at_micros>253402300799999999 THEN
		RETURN 'invalid_fact';
	END IF;
	PERFORM account.account_id
	FROM decodex.accounts AS account
	WHERE account.account_id=p_account_id AND account.tombstoned_at IS NULL
	FOR UPDATE OF account;
	IF NOT FOUND THEN RETURN 'stale_account'; END IF;
	INSERT INTO decodex.account_quota_facts(
		account_id,duration_minutes,used_percent,resets_at_micros,error_code,observed_at_micros
	) VALUES (
		p_account_id,p_duration_minutes,NULL,NULL,p_error_code,p_observed_at_micros
	) ON CONFLICT(account_id,duration_minutes) DO UPDATE SET
		used_percent=NULL,resets_at_micros=NULL,error_code=EXCLUDED.error_code,
		observed_at_micros=EXCLUDED.observed_at_micros
	WHERE account_quota_facts.observed_at_micros<=EXCLUDED.observed_at_micros;
	RETURN 'observed';
END
$$;


--
-- Name: observe_account_quota_exact(uuid, integer, integer, bigint, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.observe_account_quota_exact(p_account_id uuid, p_duration_minutes integer, p_used_percent integer, p_resets_at_micros bigint, p_observed_at_micros bigint) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF p_account_id IS NULL OR p_duration_minutes IS NULL
		OR p_duration_minutes NOT IN (300,10080) OR p_used_percent IS NULL
		OR p_used_percent<0 OR p_used_percent>100
		OR p_observed_at_micros IS NULL OR p_observed_at_micros<0
		OR p_observed_at_micros>253402300799999999
		OR p_resets_at_micros IS NULL
		OR p_resets_at_micros<=p_observed_at_micros
		OR p_resets_at_micros>253402300799999999 THEN RETURN 'invalid_fact'; END IF;
	PERFORM account.account_id
	FROM decodex.accounts AS account
	WHERE account.account_id=p_account_id AND account.tombstoned_at IS NULL
	FOR UPDATE OF account;
	IF NOT FOUND THEN RETURN 'stale_account'; END IF;
	INSERT INTO decodex.account_quota_facts(
		account_id,duration_minutes,used_percent,resets_at_micros,observed_at_micros
	) VALUES (
		p_account_id,p_duration_minutes,p_used_percent,p_resets_at_micros,p_observed_at_micros
		) ON CONFLICT(account_id,duration_minutes) DO UPDATE SET
			used_percent=EXCLUDED.used_percent,resets_at_micros=EXCLUDED.resets_at_micros,
			error_code=NULL,observed_at_micros=EXCLUDED.observed_at_micros
	WHERE account_quota_facts.observed_at_micros<=EXCLUDED.observed_at_micros;
	UPDATE decodex.accounts AS account SET
		state=CASE WHEN EXISTS (
			SELECT 1 FROM decodex.account_quota_facts AS quota
			WHERE quota.account_id=p_account_id AND quota.error_code IS NULL
				AND quota.used_percent>=100
		) THEN 'depleted'::decodex.account_state ELSE 'available'::decodex.account_state END,
		updated_at=pg_catalog.clock_timestamp()
	WHERE account.account_id=p_account_id AND account.tombstoned_at IS NULL;
	RETURN 'observed';
END
$$;


--
-- Name: observe_account_store_exact(uuid, bigint, integer, bigint, text, uuid, decodex.account_provider_kind, text, decodex.account_store_observation); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.observe_account_store_exact(p_account_id uuid, p_expected_revision bigint, p_expected_schema integer, p_expected_version bigint, p_expected_fingerprint text, p_expected_writer_operation_id uuid, p_expected_provider decodex.account_provider_kind, p_expected_provider_account_id text, p_observation decodex.account_store_observation) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	UPDATE decodex.accounts SET credential_store_observation=p_observation,
		credential_store_observed_at=pg_catalog.clock_timestamp()
	WHERE account_id=p_account_id AND tombstoned_at IS NULL
		AND revision=p_expected_revision
		AND credential_store_schema_version=p_expected_schema
		AND credential_version=p_expected_version
		AND credential_fingerprint=p_expected_fingerprint
		AND credential_writer_operation_id=p_expected_writer_operation_id
		AND provider_kind=p_expected_provider
		AND provider_account_id=p_expected_provider_account_id;
	RETURN CASE WHEN FOUND THEN 'observed' ELSE 'stale_account' END;
END
$$;


--
-- Name: plan_continuation_exact(text, text, uuid, uuid, bigint, uuid, uuid, uuid, uuid, bytea, text, text, integer, integer, text, boolean, integer, text[], text[], bigint[], text[], bigint[], bigint[], text[], text[], text[], bigint[]); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.plan_continuation_exact(p_protocol text, p_idempotency_key text, p_operation_id uuid, p_decision_id uuid, p_expected_consumer_revision bigint, p_plan_id uuid, p_fallback_session_id uuid, p_account_snapshot_id uuid, p_context_pack_id uuid, p_compiled_bytes bytea, p_compiled_digest text, p_manifest_digest text, p_max_bytes integer, p_recent_item_limit integer, p_possible_side_effects text, p_truncated boolean, p_omitted_source_count integer, p_source_kinds text[], p_source_ids text[], p_source_revisions bigint[], p_content_digests text[], p_original_lengths bigint[], p_included_lengths bigint[], p_included_digests text[], p_dispositions text[], p_artifact_ids text[], p_artifact_revisions bigint[]) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; replay bytea; existing_plan record; decision_row record;
DECLARE snapshot_row record; run_row record; session_row record; profile_row record;
	DECLARE conversation_row record; member_row record; initial_row record;
	DECLARE account_snapshot_row record;
DECLARE evidence_count bigint; selected_evidence_id uuid:=NULL;
DECLARE selected_evidence_revision bigint:=NULL;
DECLARE selected_schema_fingerprint text:=NULL;
DECLARE selected_experiment_id uuid:=NULL;
DECLARE selected_experiment_revision bigint:=NULL;
DECLARE selected_observation_id uuid:=NULL;
DECLARE selected_provider_attempt_id uuid:=NULL;
DECLARE selected_provider_attempt_revision bigint:=NULL;
DECLARE selected_provider_evidence_id uuid:=NULL;
DECLARE planned timestamptz; pack_revision bigint; source_count integer;
DECLARE position integer; inline_value bytea; blob_value text;
DECLARE plan_kind decodex.continuation_plan_kind; thread_value uuid;
DECLARE same_thread_available boolean:=false;
DECLARE core jsonb; effect jsonb; response bytea;
DECLARE activity_sequence bigint; outbox_id bigint;
DECLARE activity_rows jsonb:='[]'::jsonb;
DECLARE outbox_rows jsonb:='[]'::jsonb; payload jsonb;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','plan_continuation',
		'protocol',p_protocol,
		'operation_id',p_operation_id,
		'decision_id',p_decision_id,
		'expected_consumer_revision',p_expected_consumer_revision,
		'plan_id',p_plan_id,
		'fallback_session_id',p_fallback_session_id,
		'account_snapshot_id',p_account_snapshot_id,
		'context_pack_id',p_context_pack_id,
		'compiled_digest',p_compiled_digest,
		'manifest_digest',p_manifest_digest,
		'byte_length',pg_catalog.octet_length(p_compiled_bytes),
		'max_bytes',p_max_bytes,
		'recent_item_limit',p_recent_item_limit,
		'possible_side_effects',p_possible_side_effects,
		'truncated',p_truncated,
		'omitted_source_count',p_omitted_source_count,
		'source_kinds',p_source_kinds,
		'source_ids',p_source_ids,
		'source_revisions',p_source_revisions,
		'content_digests',p_content_digests,
		'original_lengths',p_original_lengths,
		'included_lengths',p_included_lengths,
		'included_digests',p_included_digests,
		'dispositions',p_dispositions,
		'artifact_ids',p_artifact_ids,
		'artifact_revisions',p_artifact_revisions
	);
	replay:=decodex.reserve_exact_continuation_command(
		p_protocol,p_idempotency_key,request
	);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	IF p_operation_id IS NULL
		OR p_decision_id IS NULL
		OR p_plan_id IS NULL
		OR p_fallback_session_id IS NULL
		OR p_account_snapshot_id IS NULL
		OR p_context_pack_id IS NULL
		OR p_expected_consumer_revision IS NULL
		OR p_expected_consumer_revision<=0
	THEN
		RETURN decodex.complete_exact_continuation_rejection(
			p_protocol,p_idempotency_key,'invalid_input'
		);
	END IF;

	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1360,pg_catalog.hashtext(p_decision_id::text)
	);
	SELECT * INTO decision_row
	FROM decodex.routing_decisions
	WHERE decision_id=p_decision_id
	FOR UPDATE;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_continuation_rejection(
			p_protocol,p_idempotency_key,'missing_decision'
		);
	END IF;
	IF NOT (
		(
			decision_row.authority_shape='conversation_continuation'
			AND decision_row.consumer_kind='conversation_turn'
			AND decision_row.kind IS NULL
		) OR (
			decision_row.authority_shape='managed_run_project_policy'
			AND decision_row.consumer_kind='managed_run_execution'
			AND decision_row.kind='selected'
		)
	)
	THEN
		RETURN decodex.complete_exact_continuation_rejection(
			p_protocol,p_idempotency_key,'decision_not_selected'
		);
	END IF;
	SELECT * INTO existing_plan
	FROM decodex.continuation_plans
	WHERE routing_decision_id=p_decision_id
		OR operation_id=p_operation_id
		OR plan_id=p_plan_id
	FOR SHARE;
	IF FOUND THEN
		IF existing_plan.routing_decision_id<>p_decision_id
			OR existing_plan.operation_id<>p_operation_id
			OR existing_plan.plan_id<>p_plan_id
			OR existing_plan.request_envelope<>request
		THEN
			RETURN decodex.complete_exact_continuation_rejection(
				p_protocol,p_idempotency_key,'decision_already_consumed'
			);
		END IF;
		UPDATE decodex.exact_command_receipts
		SET receipt_state='completed_success',outcome_class='success',
			effect_envelope=existing_plan.effect_envelope,
			response_bytes=existing_plan.response_bytes,
			completed_at=pg_catalog.clock_timestamp()
		WHERE protocol_version=p_protocol
			AND idempotency_key=p_idempotency_key;
		RETURN existing_plan.response_bytes;
	END IF;

	planned:=pg_catalog.clock_timestamp();
	IF decision_row.authority_shape='conversation_continuation' THEN
		SELECT * INTO conversation_row
		FROM decodex.conversations
		WHERE conversation_id=decision_row.conversation_id
		FOR UPDATE;
		SELECT * INTO initial_row
		FROM decodex.routing_decisions
		WHERE decision_id=decision_row.initial_decision_id
		FOR SHARE;
		SELECT * INTO snapshot_row
		FROM decodex.routing_snapshots
		WHERE snapshot_id=initial_row.snapshot_id
		FOR SHARE;
		SELECT * INTO member_row
		FROM decodex.routing_snapshot_members
		WHERE snapshot_id=snapshot_row.snapshot_id
			AND account_id=initial_row.selected_account_id
		FOR SHARE;
		SELECT * INTO session_row
		FROM decodex.runtime_sessions
		WHERE runtime_session_id=decision_row.source_runtime_session_id
			AND revision=decision_row.source_runtime_session_revision
		FOR UPDATE;
		SELECT * INTO account_snapshot_row
		FROM decodex.account_snapshots
		WHERE account_snapshot_id=decision_row.account_snapshot_id
		FOR SHARE;
		SELECT * INTO profile_row
		FROM decodex.profile_snapshots
		WHERE profile_snapshot_id=decision_row.profile_snapshot_id
		FOR SHARE;

		IF conversation_row.conversation_id IS NULL
			OR conversation_row.revision<>p_expected_consumer_revision
			OR decision_row.conversation_revision<>p_expected_consumer_revision
			OR conversation_row.status<>'open'
			OR initial_row.decision_id IS NULL
			OR initial_row.authority_shape<>'conversation_account_registry'
			OR initial_row.kind<>'selected'
			OR initial_row.conversation_id<>decision_row.conversation_id
			OR snapshot_row.snapshot_id IS NULL
			OR snapshot_row.authority_shape<>'conversation_account_registry'
			OR member_row.account_id IS NULL
			OR member_row.authority_shape<>'conversation_account_registry'
			OR session_row.runtime_session_id IS NULL
			OR session_row.conversation_id<>decision_row.conversation_id
			OR session_row.account_snapshot_id<>decision_row.account_snapshot_id
			OR session_row.profile_snapshot_id<>decision_row.profile_snapshot_id
			OR p_account_snapshot_id<>decision_row.account_snapshot_id
			OR session_row.state<>'active'
			OR account_snapshot_row.account_snapshot_id IS NULL
			OR account_snapshot_row.source_account_id<>initial_row.selected_account_id
			OR account_snapshot_row.source_revision<>member_row.account_revision
			OR account_snapshot_row.source_revision<>
				decision_row.account_snapshot_source_revision
			OR profile_row.profile_snapshot_id IS NULL
			OR profile_row.role<>'task'
			OR profile_row.source_revision<>snapshot_row.task_role_profile_revision
			OR profile_row.source_revision<>
				decision_row.profile_snapshot_source_revision
			OR EXISTS (
				SELECT 1 FROM decodex.turns AS turn_row
				WHERE turn_row.turn_id=decision_row.turn_id
					AND NOT (
						turn_row.conversation_id=decision_row.conversation_id
						AND turn_row.runtime_session_id=
							decision_row.source_runtime_session_id
						AND turn_row.sequence>1
						AND turn_row.role='user'
						AND turn_row.possible_side_effects='unknown'
						AND turn_row.status='active'
						AND turn_row.revision=1
						AND turn_row.completed_at IS NULL
					)
			)
		THEN
			RETURN decodex.complete_exact_continuation_rejection(
				p_protocol,p_idempotency_key,'stale_consumer_revision'
			);
		END IF;

		decision_row.selected_account_id:=initial_row.selected_account_id;
		decision_row.snapshot_id:=initial_row.snapshot_id;
	ELSE
		SELECT * INTO snapshot_row
		FROM decodex.routing_snapshots
		WHERE snapshot_id=decision_row.snapshot_id
		FOR SHARE;
		IF snapshot_row.snapshot_id IS NULL
			OR snapshot_row.authority_shape<>'managed_run_project_policy'
			OR (
				decision_row.consumer_kind,
				decision_row.managed_run_id,
				decision_row.managed_run_revision,
				decision_row.managed_execution_id
			) IS DISTINCT FROM (
				snapshot_row.consumer_kind,
				snapshot_row.managed_run_id,
				snapshot_row.managed_run_revision,
				snapshot_row.managed_execution_id
			)
		THEN
			RETURN decodex.complete_exact_continuation_rejection(
				p_protocol,p_idempotency_key,'stale_consumer_revision'
			);
		END IF;
		SELECT * INTO run_row
		FROM decodex.managed_runs
		WHERE managed_run_id=decision_row.managed_run_id
		FOR UPDATE;
		IF run_row.managed_run_id IS NULL
			OR run_row.revision<>p_expected_consumer_revision
			OR decision_row.managed_run_revision<>p_expected_consumer_revision
		THEN
			RETURN decodex.complete_exact_continuation_rejection(
				p_protocol,p_idempotency_key,'stale_consumer_revision'
			);
		END IF;
		SELECT * INTO session_row
		FROM decodex.runtime_sessions
		WHERE (runtime_session_id,revision)=(
			snapshot_row.runtime_session_id,
			snapshot_row.runtime_session_revision
		)
		FOR SHARE;
		SELECT * INTO profile_row
		FROM decodex.profile_snapshots
		WHERE profile_snapshot_id=snapshot_row.profile_snapshot_id
		FOR SHARE;
		SELECT * INTO conversation_row
		FROM decodex.conversations
		WHERE conversation_id=session_row.conversation_id
		FOR SHARE;
		SELECT * INTO member_row
		FROM decodex.routing_snapshot_members
		WHERE snapshot_id=snapshot_row.snapshot_id
			AND account_id=decision_row.selected_account_id
		FOR SHARE;
		IF session_row.runtime_session_id IS NULL
			OR profile_row.profile_snapshot_id IS NULL
			OR conversation_row.conversation_id IS NULL
			OR conversation_row.status<>'open'
			OR member_row.account_id IS NULL
			OR member_row.disposition<>'included'
			OR EXISTS (
				SELECT 1
				FROM decodex.routing_decision_blocker_refs AS blocker
				WHERE blocker.decision_id=decision_row.decision_id
					AND blocker.account_id=decision_row.selected_account_id
			)
			OR (
				session_row.profile_snapshot_id,
				profile_row.role,
				profile_row.source_revision
			) IS DISTINCT FROM (
				snapshot_row.profile_snapshot_id,
				snapshot_row.required_role,
				snapshot_row.required_role_profile_revision
			)
		THEN
			RETURN decodex.complete_exact_continuation_rejection(
				p_protocol,p_idempotency_key,'stale_consumer_revision'
			);
		END IF;
	END IF;
	IF decision_row.consumer_kind::text='managed_run_execution' THEN
		SELECT pg_catalog.count(*) INTO evidence_count
		FROM (
			SELECT experiment.experiment_id
			FROM decodex.routing_compatibility_evidence AS evidence
			JOIN decodex.routing_capability_evidence AS capability
				ON capability.evidence_id=evidence.evidence_id
			JOIN decodex.codex_experiments AS experiment
				ON (
					experiment.managed_run_id,
					experiment.managed_run_revision,
					experiment.routing_snapshot_id,
					experiment.account_id,
					experiment.account_revision,
					experiment.role_profile_revision,
					experiment.build_id,
					experiment.revision,
					experiment.state
				)=(
					decision_row.managed_run_id,
					decision_row.managed_run_revision,
					snapshot_row.snapshot_id,
					decision_row.selected_account_id,
					member_row.account_revision,
					snapshot_row.required_role_profile_revision,
					snapshot_row.required_build_id,
					3,
					'thread_bound'
				)
			JOIN decodex.codex_experiment_thread_bindings AS binding
				ON binding.experiment_id=experiment.experiment_id
			JOIN decodex.codex_experiment_observations AS observation
				ON observation.experiment_id=experiment.experiment_id
				AND observation.experiment_revision=3
				AND observation.thread_id=binding.thread_id
				AND observation.kind='thread_read_item'
			WHERE evidence.evidence_id=member_row.evidence_id
				AND evidence.evidence_revision=member_row.evidence_revision
				AND evidence.account_id=decision_row.selected_account_id
				AND evidence.account_revision=member_row.account_revision
				AND evidence.role=snapshot_row.required_role
				AND evidence.role_profile_revision=
					snapshot_row.required_role_profile_revision
				AND evidence.build_id=snapshot_row.required_build_id
				AND evidence.process_account_id=
					decision_row.selected_account_id
				AND session_row.codex_thread_id IS NOT NULL
				AND binding.thread_id=session_row.codex_thread_id::text
				AND session_row.state='active'
				AND NOT run_row.diverged
				AND evidence.ingested_at<=planned
				AND planned-evidence.ingested_at<=INTERVAL '300 seconds'
				AND experiment.updated_at<=planned
				AND planned-experiment.updated_at<=INTERVAL '300 seconds'
				AND observation.observed_at<=planned
				AND planned-observation.observed_at<=INTERVAL '300 seconds'
				AND capability.capability IN (
					'initialize','account_read','thread_read','paginated_history'
				)
				AND capability.state='supported'
			GROUP BY experiment.experiment_id
			HAVING pg_catalog.count(DISTINCT capability.capability)=4
		) AS canonical_experiment;
		IF evidence_count=1 THEN
			SELECT evidence.evidence_id,evidence.evidence_revision,
				evidence.schema_fingerprint,experiment.experiment_id,
				experiment.revision,observation.observation_id
			INTO selected_evidence_id,selected_evidence_revision,
				selected_schema_fingerprint,selected_experiment_id,
				selected_experiment_revision,selected_observation_id
			FROM decodex.routing_compatibility_evidence AS evidence
			JOIN decodex.codex_experiments AS experiment
				ON experiment.managed_run_id=decision_row.managed_run_id
				AND experiment.managed_run_revision=
					decision_row.managed_run_revision
				AND experiment.routing_snapshot_id=snapshot_row.snapshot_id
				AND experiment.account_id=decision_row.selected_account_id
				AND experiment.account_revision=member_row.account_revision
				AND experiment.role_profile_revision=
					snapshot_row.required_role_profile_revision
				AND experiment.build_id=snapshot_row.required_build_id
				AND experiment.revision=3
				AND experiment.state='thread_bound'
			JOIN decodex.codex_experiment_thread_bindings AS binding
				ON binding.experiment_id=experiment.experiment_id
			JOIN decodex.codex_experiment_observations AS observation
				ON observation.experiment_id=experiment.experiment_id
				AND observation.experiment_revision=3
				AND observation.thread_id=binding.thread_id
				AND observation.kind='thread_read_item'
			WHERE evidence.evidence_id=member_row.evidence_id
				AND evidence.evidence_revision=member_row.evidence_revision
				AND binding.thread_id=session_row.codex_thread_id::text
				AND evidence.ingested_at<=planned
				AND planned-evidence.ingested_at<=INTERVAL '300 seconds'
				AND experiment.updated_at<=planned
				AND planned-experiment.updated_at<=INTERVAL '300 seconds'
				AND observation.observed_at<=planned
				AND planned-observation.observed_at<=INTERVAL '300 seconds'
			ORDER BY observation.observed_at DESC,observation.observation_id
			LIMIT 1;
			same_thread_available:=true;
		END IF;
	ELSE
		SELECT attempt.attempt_id,attempt.revision,evidence.evidence_id
		INTO selected_provider_attempt_id,
			selected_provider_attempt_revision,
			selected_provider_evidence_id
		FROM decodex.provider_attempts AS attempt
		JOIN decodex.provider_attempt_positive_evidence AS evidence
			ON evidence.evidence_id=attempt.terminal_evidence_id
			AND evidence.attempt_id=attempt.attempt_id
		WHERE attempt.consumer_kind::text='conversation_turn'
			AND attempt.conversation_id=decision_row.conversation_id
			AND attempt.turn_id<>decision_row.turn_id
			AND attempt.accepted_runtime_session_id=
				session_row.runtime_session_id
			AND attempt.accepted_runtime_session_revision+1=session_row.revision
			AND attempt.selected_account_id=decision_row.selected_account_id
			AND attempt.state IN ('succeeded','failed_definitive')
			AND evidence.outcome::text=attempt.state::text
			AND evidence.source='exact_thread_readback'
			AND evidence.provider_thread_id=session_row.codex_thread_id::text
			AND session_row.codex_thread_id IS NOT NULL
			AND session_row.state='active'
			AND EXISTS (
				SELECT 1
				FROM decodex.exact_command_receipts AS receipt
				WHERE receipt.receipt_state='completed_success'
					AND receipt.request_envelope->>'operation'=
						'terminalize_quick_task_turn'
					AND receipt.request_envelope->>'conversation_id'=
						attempt.conversation_id::text
					AND receipt.request_envelope->>'runtime_session_id'=
						attempt.accepted_runtime_session_id::text
					AND receipt.request_envelope->>'expected_runtime_session_revision'=
						attempt.accepted_runtime_session_revision::text
					AND receipt.request_envelope->>'user_turn_id'=
						attempt.turn_id::text
					AND receipt.request_envelope->>'provider_attempt_id'=
						attempt.attempt_id::text
					AND receipt.effect_envelope->>'runtime_session_revision'=
						session_row.revision::text
					AND receipt.effect_envelope->>'provider_evidence_id'=
						evidence.evidence_id::text
			)
			AND evidence.observed_at<=planned
			AND planned-evidence.observed_at<=INTERVAL '300 seconds'
		ORDER BY evidence.observed_at DESC,evidence.evidence_id
		LIMIT 1;
		same_thread_available:=FOUND;
	END IF;

	IF same_thread_available THEN
		plan_kind:='same_thread';
		thread_value:=session_row.codex_thread_id;
	ELSE
		plan_kind:='context_pack_fallback';
		thread_value:=NULL;
		IF NOT decodex.is_canonical_continuation_pack(
			session_row.conversation_id,p_compiled_bytes,p_compiled_digest,
			p_manifest_digest,p_max_bytes,p_recent_item_limit,
			p_possible_side_effects,p_truncated,p_omitted_source_count,
			p_source_kinds,p_source_ids,p_source_revisions,p_content_digests,
			p_original_lengths,p_included_lengths,p_included_digests,
			p_dispositions,p_artifact_ids,p_artifact_revisions
		) THEN
			RETURN decodex.complete_exact_continuation_rejection(
				p_protocol,p_idempotency_key,'invalid_context_pack'
			);
		END IF;
		IF EXISTS (
			SELECT 1 FROM decodex.runtime_sessions
			WHERE runtime_session_id=p_fallback_session_id
		) OR (
			decision_row.authority_shape='managed_run_project_policy'
			AND EXISTS (
			SELECT 1 FROM decodex.account_snapshots
			WHERE account_snapshot_id=p_account_snapshot_id
			)
		) OR (
			decision_row.authority_shape='conversation_continuation'
			AND p_account_snapshot_id<>decision_row.account_snapshot_id
		) OR EXISTS (
			SELECT 1 FROM decodex.context_packs
			WHERE context_pack_id=p_context_pack_id
		) THEN
			RETURN decodex.complete_exact_continuation_rejection(
				p_protocol,p_idempotency_key,'fallback_identity_conflict'
			);
		END IF;
		SELECT COALESCE(pg_catalog.max(stored.pack_revision),0)+1
		INTO pack_revision
		FROM decodex.context_packs AS stored
		WHERE stored.conversation_id=session_row.conversation_id;
		source_count:=pg_catalog.cardinality(p_source_kinds);
		FOR position IN 1..source_count LOOP
			IF p_artifact_ids[position]<>''
				AND NOT EXISTS (
					SELECT 1
					FROM decodex.artifact_revisions AS artifact
					JOIN decodex.blob_objects AS blob
						ON blob.blob_hash=artifact.blob_hash
					WHERE artifact.artifact_id=
							p_artifact_ids[position]::uuid
						AND artifact.conversation_id=
							session_row.conversation_id
						AND artifact.revision=
							p_artifact_revisions[position]
						AND artifact.blob_hash=
							p_content_digests[position]
						AND blob.byte_length=
							p_original_lengths[position]
				)
			THEN
				RETURN decodex.complete_exact_continuation_rejection(
					p_protocol,p_idempotency_key,'invalid_context_pack'
				);
			END IF;
		END LOOP;
		IF pg_catalog.octet_length(p_compiled_bytes)>16384 THEN
			inline_value:=NULL;
			blob_value:=p_compiled_digest;
			INSERT INTO decodex.blob_objects(
				blob_hash,byte_length,verified_at,created_at
			) VALUES (
				blob_value,pg_catalog.octet_length(p_compiled_bytes),
				planned,planned
			) ON CONFLICT (blob_hash) DO NOTHING;
			IF NOT EXISTS (
				SELECT 1
				FROM decodex.blob_objects
				WHERE blob_hash=blob_value
					AND byte_length=
						pg_catalog.octet_length(p_compiled_bytes)
			) THEN
				RETURN decodex.complete_exact_continuation_rejection(
					p_protocol,p_idempotency_key,'invalid_context_pack'
				);
			END IF;
		ELSE
			inline_value:=p_compiled_bytes;
			blob_value:=NULL;
		END IF;
		FOR position IN 1..source_count LOOP
			INSERT INTO decodex.context_pack_sources(
				context_pack_id,conversation_id,position,kind,
				source_id,source_revision,content_digest,
				original_byte_length,included_byte_length,included_digest,
				disposition,artifact_id,artifact_revision
			) VALUES (
				p_context_pack_id,session_row.conversation_id,position-1,
				p_source_kinds[position]::decodex.context_source_kind,
				p_source_ids[position],p_source_revisions[position],
				p_content_digests[position],p_original_lengths[position],
				p_included_lengths[position],p_included_digests[position],
				p_dispositions[position]::decodex.context_source_disposition,
				NULLIF(p_artifact_ids[position],'')::uuid,
				NULLIF(p_artifact_revisions[position],0)
			);
		END LOOP;
		INSERT INTO decodex.context_packs(
			context_pack_id,conversation_id,pack_revision,compiled_digest,
			manifest_digest,inline_bytes,blob_hash,byte_length,max_bytes,
			recent_item_limit,possible_side_effects,truncated,
			omitted_source_count,source_count
		) VALUES (
			p_context_pack_id,session_row.conversation_id,pack_revision,
			p_compiled_digest,p_manifest_digest,inline_value,blob_value,
			pg_catalog.octet_length(p_compiled_bytes),p_max_bytes,
			p_recent_item_limit,
			p_possible_side_effects::decodex.side_effect_state,
			p_truncated,p_omitted_source_count,source_count
		);
		IF decision_row.authority_shape='managed_run_project_policy' THEN
			INSERT INTO decodex.account_snapshots(
				account_snapshot_id,source_account_id,display_label,
				observed_state,source_revision
			) VALUES (
				p_account_snapshot_id,member_row.account_id,
				member_row.display_label,member_row.account_state,
				member_row.account_revision
			);
		END IF;
		INSERT INTO decodex.runtime_sessions(
			runtime_session_id,conversation_id,profile_snapshot_id,
			account_snapshot_id,codex_thread_id,state,last_known_turn_id
		) VALUES (
			p_fallback_session_id,session_row.conversation_id,
			profile_row.profile_snapshot_id,p_account_snapshot_id,
			NULL,'starting',NULL
		);
	END IF;

	core:=pg_catalog.jsonb_build_object(
		'operation','plan_continuation',
		'plan_id',p_plan_id,
		'operation_id',p_operation_id,
		'routing_decision_id',p_decision_id,
		'consumer_kind',decision_row.consumer_kind,
		'consumer_conversation_id',decision_row.conversation_id,
		'conversation_revision',decision_row.conversation_revision,
		'turn_id',decision_row.turn_id,
		'managed_run_id',decision_row.managed_run_id,
		'managed_run_revision',decision_row.managed_run_revision,
		'managed_execution_id',decision_row.managed_execution_id,
		'conversation_id',session_row.conversation_id,
		'source_runtime_session_id',session_row.runtime_session_id,
		'source_runtime_session_revision',session_row.revision,
		'selected_account_id',decision_row.selected_account_id,
		'kind',plan_kind,
		'codex_thread_id',thread_value,
		'fallback_context_pack_id',CASE
			WHEN plan_kind='context_pack_fallback' THEN p_context_pack_id
		END,
		'fallback_context_pack_revision',CASE
			WHEN plan_kind='context_pack_fallback' THEN pack_revision
		END,
		'fallback_runtime_session_id',CASE
			WHEN plan_kind='context_pack_fallback' THEN p_fallback_session_id
		END,
		'routing_evidence_id',selected_evidence_id,
		'routing_evidence_revision',selected_evidence_revision,
		'schema_fingerprint',selected_schema_fingerprint,
		'codex_experiment_id',selected_experiment_id,
		'codex_experiment_revision',selected_experiment_revision,
		'codex_observation_id',selected_observation_id,
		'same_thread_provider_attempt_id',selected_provider_attempt_id,
		'same_thread_provider_attempt_revision',
			selected_provider_attempt_revision,
		'same_thread_provider_evidence_id',selected_provider_evidence_id,
		'replay_permitted',false,
		'dispatch_enabled',false,
		'planned_at_micros',
			(extract(epoch FROM planned)*1000000)::bigint
	);
	payload:=core||pg_catalog.jsonb_build_object(
		'continuation_plan_id',p_plan_id
	);
	INSERT INTO decodex.activity(
		aggregate_kind,aggregate_id,revision,event_kind,
		correlation_key,payload
	) VALUES (
		'continuation_plan',p_plan_id::text,1,
		'continuation_plan_created',p_idempotency_key,payload
	) RETURNING sequence INTO activity_sequence;
	activity_rows:=activity_rows||pg_catalog.jsonb_build_array(
		pg_catalog.jsonb_build_object(
			'sequence',activity_sequence,
			'aggregate_kind','continuation_plan',
			'aggregate_id',p_plan_id,
			'revision',1,
			'event_kind','continuation_plan_created',
			'payload',payload
		)
	);
	INSERT INTO decodex.outbox(
		effect_key,aggregate_kind,aggregate_id,aggregate_revision,payload
	) VALUES (
		'activity/'||activity_sequence::text,
		'continuation_plan',p_plan_id::text,1,
		pg_catalog.jsonb_build_object(
			'activity_sequence',activity_sequence,
			'event_kind','continuation_plan_created',
			'aggregate_kind','continuation_plan',
			'aggregate_id',p_plan_id,
			'revision',1,
			'payload',payload
		)
	) RETURNING id INTO outbox_id;
	outbox_rows:=outbox_rows||pg_catalog.jsonb_build_array(
		pg_catalog.jsonb_build_object(
			'id',outbox_id,
			'effect_key','activity/'||activity_sequence::text,
			'aggregate_kind','continuation_plan',
			'aggregate_id',p_plan_id,
			'aggregate_revision',1
		)
	);
	IF plan_kind='context_pack_fallback' THEN
		payload:=pg_catalog.jsonb_build_object(
			'kind','context_pack',
			'continuation_plan_id',p_plan_id,
			'routing_decision_id',p_decision_id,
			'fallback_context_pack_id',p_context_pack_id,
			'conversation_id',session_row.conversation_id,
			'pack_revision',pack_revision,
			'compiled_digest',p_compiled_digest,
			'dispatch_enabled',false
		);
		INSERT INTO decodex.activity(
			aggregate_kind,aggregate_id,revision,event_kind,
			correlation_key,payload
		) VALUES (
			'context_pack',p_context_pack_id::text,pack_revision,
			'context_pack_persisted',p_idempotency_key,payload
		) RETURNING sequence INTO activity_sequence;
		activity_rows:=activity_rows||pg_catalog.jsonb_build_array(
			pg_catalog.jsonb_build_object(
				'sequence',activity_sequence,
				'aggregate_kind','context_pack',
				'aggregate_id',p_context_pack_id,
				'revision',pack_revision,
				'event_kind','context_pack_persisted',
				'payload',payload
			)
		);
		INSERT INTO decodex.outbox(
			effect_key,aggregate_kind,aggregate_id,
			aggregate_revision,payload
		) VALUES (
			'activity/'||activity_sequence::text,
			'context_pack',p_context_pack_id::text,pack_revision,
			pg_catalog.jsonb_build_object(
				'activity_sequence',activity_sequence,
				'event_kind','context_pack_persisted',
				'aggregate_kind','context_pack',
				'aggregate_id',p_context_pack_id,
				'revision',pack_revision,
				'payload',payload
			)
		) RETURNING id INTO outbox_id;
		outbox_rows:=outbox_rows||pg_catalog.jsonb_build_array(
			pg_catalog.jsonb_build_object(
				'id',outbox_id,
				'effect_key','activity/'||activity_sequence::text,
				'aggregate_kind','context_pack',
				'aggregate_id',p_context_pack_id,
				'aggregate_revision',pack_revision
			)
		);
		payload:=pg_catalog.jsonb_build_object(
			'kind','runtime_session',
			'continuation_plan_id',p_plan_id,
			'routing_decision_id',p_decision_id,
			'fallback_runtime_session_id',p_fallback_session_id,
			'conversation_id',session_row.conversation_id,
			'selected_account_id',decision_row.selected_account_id,
			'state','starting',
			'revision',1,
			'dispatch_enabled',false
		);
		INSERT INTO decodex.activity(
			aggregate_kind,aggregate_id,revision,event_kind,
			correlation_key,payload
		) VALUES (
			'runtime_session',p_fallback_session_id::text,1,
			'runtime_session_created',p_idempotency_key,payload
		) RETURNING sequence INTO activity_sequence;
		activity_rows:=activity_rows||pg_catalog.jsonb_build_array(
			pg_catalog.jsonb_build_object(
				'sequence',activity_sequence,
				'aggregate_kind','runtime_session',
				'aggregate_id',p_fallback_session_id,
				'revision',1,
				'event_kind','runtime_session_created',
				'payload',payload
			)
		);
		INSERT INTO decodex.outbox(
			effect_key,aggregate_kind,aggregate_id,
			aggregate_revision,payload
		) VALUES (
			'activity/'||activity_sequence::text,
			'runtime_session',p_fallback_session_id::text,1,
			pg_catalog.jsonb_build_object(
				'activity_sequence',activity_sequence,
				'event_kind','runtime_session_created',
				'aggregate_kind','runtime_session',
				'aggregate_id',p_fallback_session_id,
				'revision',1,
				'payload',payload
			)
		) RETURNING id INTO outbox_id;
		outbox_rows:=outbox_rows||pg_catalog.jsonb_build_array(
			pg_catalog.jsonb_build_object(
				'id',outbox_id,
				'effect_key','activity/'||activity_sequence::text,
				'aggregate_kind','runtime_session',
				'aggregate_id',p_fallback_session_id,
				'aggregate_revision',1
			)
		);
	END IF;

	effect:=core||pg_catalog.jsonb_build_object(
		'activity_effects',activity_rows,
		'outbox_effects',outbox_rows,
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(
			public.digest(pg_catalog.convert_to(core::text,'UTF8'),'sha256'),
			'hex'
		)
	);
	response:=pg_catalog.convert_to(
		pg_catalog.jsonb_build_object(
			'classification','success',
			'effect',effect
		)::text,
		'UTF8'
	);
	INSERT INTO decodex.continuation_plans(
		plan_id,operation_id,routing_decision_id,consumer_kind,
		consumer_conversation_id,conversation_revision,turn_id,
		managed_run_id,managed_run_revision,managed_execution_id,
		conversation_id,source_runtime_session_id,
		source_runtime_session_revision,selected_account_id,kind,
		codex_thread_id,fallback_context_pack_id,
		fallback_runtime_session_id,routing_evidence_id,
		routing_evidence_revision,schema_fingerprint,codex_experiment_id,
		codex_experiment_revision,codex_observation_id,
		same_thread_provider_attempt_id,
		same_thread_provider_attempt_revision,
		same_thread_provider_evidence_id,replay_permitted,
		dispatch_enabled,revision,request_envelope,effect_envelope,
		response_bytes,planned_at
	) VALUES (
		p_plan_id,p_operation_id,p_decision_id,
		decision_row.consumer_kind,decision_row.conversation_id,
		decision_row.conversation_revision,decision_row.turn_id,
		decision_row.managed_run_id,decision_row.managed_run_revision,
		decision_row.managed_execution_id,session_row.conversation_id,
		session_row.runtime_session_id,session_row.revision,
		decision_row.selected_account_id,plan_kind,thread_value,
		CASE WHEN plan_kind='context_pack_fallback'
			THEN p_context_pack_id END,
		CASE WHEN plan_kind='context_pack_fallback'
			THEN p_fallback_session_id END,
		selected_evidence_id,selected_evidence_revision,
		selected_schema_fingerprint,selected_experiment_id,
		selected_experiment_revision,selected_observation_id,
		selected_provider_attempt_id,selected_provider_attempt_revision,
		selected_provider_evidence_id,false,false,1,request,effect,response,planned
	);
	UPDATE decodex.exact_command_receipts
	SET receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol
		AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$$;


--
-- Name: plan_initial_thread_continuation_exact(text, text, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.plan_initial_thread_continuation_exact(p_protocol text, p_idempotency_key text, p_operation_id uuid, p_decision_id uuid, p_expected_conversation_revision bigint, p_plan_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; replay bytea; existing_plan decodex.continuation_plans%ROWTYPE;
DECLARE decision_row decodex.routing_decisions%ROWTYPE;
DECLARE snapshot_row decodex.routing_snapshots%ROWTYPE;
DECLARE member_row decodex.routing_snapshot_members%ROWTYPE;
DECLARE profile_source decodex.role_profile_revisions%ROWTYPE;
DECLARE new_account_snapshot_id uuid; new_profile_snapshot_id uuid;
DECLARE new_runtime_session_id uuid;
DECLARE account_value jsonb; profile_value jsonb; session_value jsonb;
DECLARE planned timestamptz; core jsonb; effect jsonb; response bytea;
DECLARE payload jsonb; activity_sequence bigint; outbox_id bigint;
DECLARE activity_rows jsonb:='[]'::jsonb; outbox_rows jsonb:='[]'::jsonb;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','plan_initial_thread_continuation',
		'protocol',p_protocol,'operation_id',p_operation_id,
		'decision_id',p_decision_id,
		'expected_consumer_revision',p_expected_conversation_revision,
		'plan_id',p_plan_id
	);
	replay:=decodex.reserve_exact_continuation_command(
		p_protocol,p_idempotency_key,request
	);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	IF p_operation_id IS NULL OR p_decision_id IS NULL OR p_plan_id IS NULL
		OR p_expected_conversation_revision IS NULL
		OR p_expected_conversation_revision<=0
	THEN
		RETURN decodex.complete_exact_continuation_rejection(
			p_protocol,p_idempotency_key,'invalid_input'
		);
	END IF;

	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1360,pg_catalog.hashtext(p_decision_id::text)
	);
	SELECT * INTO decision_row FROM decodex.routing_decisions
	WHERE decision_id=p_decision_id FOR UPDATE;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_continuation_rejection(
			p_protocol,p_idempotency_key,'missing_decision'
		);
	END IF;
	IF decision_row.authority_shape<>'conversation_account_registry'
		OR decision_row.kind<>'selected'
	THEN
		RETURN decodex.complete_exact_continuation_rejection(
			p_protocol,p_idempotency_key,'decision_not_selected'
		);
	END IF;
	SELECT * INTO existing_plan FROM decodex.continuation_plans
	WHERE routing_decision_id=p_decision_id
		OR operation_id=p_operation_id OR plan_id=p_plan_id
	FOR SHARE;
	IF FOUND THEN
		RETURN decodex.complete_exact_continuation_rejection(
			p_protocol,p_idempotency_key,'decision_already_consumed'
		);
	END IF;

	SELECT * INTO snapshot_row FROM decodex.routing_snapshots
	WHERE snapshot_id=decision_row.snapshot_id FOR SHARE;
	SELECT * INTO member_row FROM decodex.routing_snapshot_members
	WHERE snapshot_id=decision_row.snapshot_id
		AND account_id=decision_row.selected_account_id
	FOR SHARE;
	PERFORM 1 FROM decodex.conversations
	WHERE conversation_id=decision_row.conversation_id
		AND revision=p_expected_conversation_revision
		AND status='open'
	FOR UPDATE;
	IF snapshot_row.snapshot_id IS NULL
		OR member_row.account_id IS NULL
		OR NOT FOUND
		OR snapshot_row.authority_shape<>'conversation_account_registry'
		OR member_row.authority_shape<>'conversation_account_registry'
		OR decision_row.consumer_kind<>'conversation_turn'
		OR snapshot_row.consumer_kind<>'conversation_turn'
		OR (
			decision_row.conversation_id,decision_row.conversation_revision,
			decision_row.turn_id
		) IS DISTINCT FROM (
			snapshot_row.conversation_id,snapshot_row.conversation_revision,
			snapshot_row.turn_id
		)
		OR decision_row.conversation_revision<>p_expected_conversation_revision
		OR snapshot_row.runtime_session_id IS NOT NULL
		OR snapshot_row.runtime_session_revision IS NOT NULL
		OR snapshot_row.account_snapshot_id IS NOT NULL
		OR snapshot_row.account_snapshot_source_revision IS NOT NULL
		OR snapshot_row.profile_snapshot_id IS NOT NULL
		OR snapshot_row.profile_snapshot_source_revision IS NOT NULL
		OR EXISTS (
			SELECT 1 FROM decodex.routing_decision_blocker_refs AS blocker
			WHERE blocker.decision_id=decision_row.decision_id
				AND blocker.account_id=decision_row.selected_account_id
		)
		OR EXISTS (
			SELECT 1 FROM decodex.runtime_sessions
			WHERE conversation_id=decision_row.conversation_id
		)
		OR EXISTS (
			SELECT 1 FROM decodex.turns
			WHERE conversation_id=decision_row.conversation_id
				OR turn_id=decision_row.turn_id
		)
	THEN
		RETURN decodex.complete_exact_continuation_rejection(
			p_protocol,p_idempotency_key,'stale_consumer_revision'
		);
	END IF;

	SELECT * INTO profile_source
	FROM decodex.role_profile_revisions AS revision
	WHERE revision.role='task'
		AND revision.revision=snapshot_row.task_role_profile_revision
	FOR SHARE;
	IF member_row.display_label IS NULL OR member_row.account_state IS NULL
		OR profile_source.role IS NULL
	THEN
		RETURN decodex.complete_exact_continuation_rejection(
			p_protocol,p_idempotency_key,'stale_consumer_revision'
		);
	END IF;

	planned:=pg_catalog.clock_timestamp();
	new_account_snapshot_id:=pg_catalog.gen_random_uuid();
	new_profile_snapshot_id:=pg_catalog.gen_random_uuid();
	new_runtime_session_id:=pg_catalog.gen_random_uuid();

	INSERT INTO decodex.account_snapshots(
		account_snapshot_id,source_account_id,display_label,observed_state,
		source_revision
	) VALUES (
		new_account_snapshot_id,member_row.account_id,member_row.display_label,
		member_row.account_state,member_row.account_revision
	) RETURNING pg_catalog.jsonb_build_object(
		'account_snapshot_id',account_snapshot_id,
		'source_account_id',source_account_id,'display_label',display_label,
		'observed_state',observed_state,'source_revision',source_revision,
		'created_at',created_at
	) INTO account_value;

	INSERT INTO decodex.profile_snapshots(
		profile_snapshot_id,source_profile_id,role,model,reasoning_effort,
		service_tier,instructions_digest,instructions,provenance,source_revision
	) VALUES (
		new_profile_snapshot_id,profile_source.role::text,profile_source.role,
		profile_source.model,profile_source.reasoning_effort,
		profile_source.service_tier,
		pg_catalog.encode(public.digest(
			pg_catalog.convert_to(profile_source.instructions,'UTF8'),'sha256'
		),'hex'),profile_source.instructions,profile_source.provenance,
		profile_source.revision
	) RETURNING pg_catalog.jsonb_build_object(
		'profile_snapshot_id',profile_snapshot_id,
		'source_profile_id',source_profile_id,'role',role,'model',model,
		'reasoning_effort',reasoning_effort,'service_tier',service_tier,
		'instructions_digest',instructions_digest,'instructions',instructions,
		'provenance',provenance,'source_revision',source_revision,
		'created_at',created_at
	) INTO profile_value;

	INSERT INTO decodex.runtime_sessions(
		runtime_session_id,conversation_id,profile_snapshot_id,
		account_snapshot_id,codex_thread_id,state,last_known_turn_id,
		thread_start_request_id,thread_start_request_sha256,
		thread_start_response_id,thread_start_response_sha256
	) VALUES (
		new_runtime_session_id,decision_row.conversation_id,new_profile_snapshot_id,
		new_account_snapshot_id,NULL,'starting',NULL,NULL,NULL,NULL,NULL
	) RETURNING pg_catalog.jsonb_build_object(
		'runtime_session_id',runtime_session_id,'conversation_id',conversation_id,
		'profile_snapshot_id',profile_snapshot_id,
		'account_snapshot_id',account_snapshot_id,
		'codex_thread_id',codex_thread_id,'last_known_turn_id',last_known_turn_id,
		'state',state,'revision',revision,'created_at',created_at,
		'updated_at',updated_at,'ended_at',ended_at
	) INTO session_value;

	core:=pg_catalog.jsonb_build_object(
		'operation','plan_initial_thread_continuation','plan_id',p_plan_id,
		'operation_id',p_operation_id,'routing_decision_id',p_decision_id,
		'consumer_kind','conversation_turn',
		'consumer_conversation_id',decision_row.conversation_id,
		'conversation_revision',decision_row.conversation_revision,
		'turn_id',decision_row.turn_id,'managed_run_id',NULL,
		'managed_run_revision',NULL,'managed_execution_id',NULL,
		'conversation_id',decision_row.conversation_id,
		'source_runtime_session_id',new_runtime_session_id,
		'source_runtime_session_revision',1,
		'selected_account_id',decision_row.selected_account_id,
		'kind','initial_thread','codex_thread_id',NULL,
		'fallback_context_pack_id',NULL,
		'fallback_context_pack_revision',NULL,
		'fallback_runtime_session_id',NULL,
		'routing_evidence_id',NULL,'routing_evidence_revision',NULL,
		'schema_fingerprint',NULL,'codex_experiment_id',NULL,
		'codex_experiment_revision',NULL,'codex_observation_id',NULL,
		'same_thread_provider_attempt_id',NULL,
		'same_thread_provider_attempt_revision',NULL,
		'same_thread_provider_evidence_id',NULL,
		'runtime_session_snapshot',session_value,
		'profile_snapshot',profile_value,'account_snapshot',account_value,
		'replay_permitted',false,'dispatch_enabled',false,
		'planned_at_micros',(extract(epoch FROM planned)*1000000)::bigint
	);
	payload:=core||pg_catalog.jsonb_build_object(
		'continuation_plan_id',p_plan_id
	);
	INSERT INTO decodex.activity(
		aggregate_kind,aggregate_id,revision,event_kind,correlation_key,payload
	) VALUES (
		'continuation_plan',p_plan_id::text,1,
		'continuation_plan_created',p_idempotency_key,payload
	) RETURNING sequence INTO activity_sequence;
	activity_rows:=pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
		'sequence',activity_sequence,'aggregate_kind','continuation_plan',
		'aggregate_id',p_plan_id,'revision',1,
		'event_kind','continuation_plan_created','payload',payload
	));
	INSERT INTO decodex.outbox(
		effect_key,aggregate_kind,aggregate_id,aggregate_revision,payload
	) VALUES (
		'activity/'||activity_sequence::text,'continuation_plan',
		p_plan_id::text,1,pg_catalog.jsonb_build_object(
			'activity_sequence',activity_sequence,
			'event_kind','continuation_plan_created',
			'aggregate_kind','continuation_plan','aggregate_id',p_plan_id,
			'revision',1,'payload',payload
		)
	) RETURNING id INTO outbox_id;
	outbox_rows:=pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
		'id',outbox_id,'effect_key','activity/'||activity_sequence::text,
		'aggregate_kind','continuation_plan','aggregate_id',p_plan_id,
		'aggregate_revision',1
	));
	effect:=core||pg_catalog.jsonb_build_object(
		'activity_effects',activity_rows,'outbox_effects',outbox_rows,
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect
	)::text,'UTF8');
	INSERT INTO decodex.continuation_plans(
		plan_id,operation_id,routing_decision_id,consumer_kind,
		consumer_conversation_id,conversation_revision,turn_id,
		managed_run_id,managed_run_revision,managed_execution_id,
		conversation_id,source_runtime_session_id,
		source_runtime_session_revision,selected_account_id,kind,
		codex_thread_id,fallback_context_pack_id,
		fallback_runtime_session_id,routing_evidence_id,
		routing_evidence_revision,schema_fingerprint,codex_experiment_id,
		codex_experiment_revision,codex_observation_id,
		same_thread_provider_attempt_id,
		same_thread_provider_attempt_revision,
		same_thread_provider_evidence_id,replay_permitted,dispatch_enabled,
		revision,request_envelope,effect_envelope,response_bytes,planned_at
	) VALUES (
		p_plan_id,p_operation_id,p_decision_id,'conversation_turn',
		decision_row.conversation_id,decision_row.conversation_revision,
		decision_row.turn_id,NULL,NULL,NULL,decision_row.conversation_id,
		new_runtime_session_id,1,decision_row.selected_account_id,
		'initial_thread',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,
		NULL,NULL,NULL,false,false,1,request,effect,response,planned
	);
	UPDATE decodex.exact_command_receipts SET
		receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$$;


--
-- Name: prepare_account_operation_exact(uuid, uuid, decodex.account_operation_kind, text, boolean, bigint, integer, bigint, text, uuid, integer, bigint, text, uuid, decodex.account_provider_kind, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.prepare_account_operation_exact(p_operation_id uuid, p_account_id uuid, p_kind decodex.account_operation_kind, p_display_label text, p_enabled boolean, p_expected_account_revision bigint, p_expected_store_schema_version integer, p_expected_credential_version bigint, p_expected_credential_fingerprint text, p_expected_credential_writer_operation_id uuid, p_target_store_schema_version integer, p_target_credential_version bigint, p_target_credential_fingerprint text, p_target_credential_writer_operation_id uuid, p_provider_kind decodex.account_provider_kind, p_provider_account_id text) RETURNS TABLE(result_code text, account_revision bigint, phase decodex.account_operation_phase)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE existing decodex.account_operations%ROWTYPE;
DECLARE account decodex.accounts%ROWTYPE;
DECLARE conflicting_constraint text;
BEGIN
	IF p_kind='logout' THEN
		PERFORM pg_catalog.pg_advisory_xact_lock_shared(1400);
		PERFORM pg_catalog.pg_advisory_xact_lock(1271);
		PERFORM pg_catalog.pg_advisory_xact_lock(
			1401,pg_catalog.hashtext(p_account_id::text)
		);
	END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1422,pg_catalog.hashtext(p_account_id::text));
	SELECT * INTO existing FROM decodex.account_operations
	WHERE operation_id=p_operation_id FOR UPDATE;
	IF FOUND THEN
		IF (existing.account_id,existing.kind,existing.expected_account_revision,
			existing.expected_store_schema_version,existing.expected_credential_version,
			existing.expected_credential_fingerprint,
			existing.expected_credential_writer_operation_id,
			existing.target_store_schema_version,existing.target_credential_version,
			existing.target_credential_fingerprint,
			existing.target_credential_writer_operation_id,
			existing.provider_kind,existing.provider_account_id,
			existing.requested_display_label,existing.requested_enabled) IS DISTINCT FROM
			(p_account_id,p_kind,p_expected_account_revision,p_expected_store_schema_version,
			p_expected_credential_version,p_expected_credential_fingerprint,
			p_expected_credential_writer_operation_id,
			p_target_store_schema_version,p_target_credential_version,
			p_target_credential_fingerprint,p_target_credential_writer_operation_id,
			p_provider_kind,p_provider_account_id,p_display_label,p_enabled)
		THEN
			RETURN QUERY SELECT 'identity_conflict',0::bigint,existing.phase;
		ELSE
			SELECT * INTO account FROM decodex.accounts WHERE account_id=p_account_id;
			RETURN QUERY SELECT 'replayed',account.revision,existing.phase;
		END IF;
		RETURN;
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.account_operations AS operation
		WHERE operation.account_id=p_account_id
		AND operation.phase NOT IN ('committed','cancelled')) THEN
		RETURN QUERY SELECT 'operation_unsettled',0::bigint,'prepared'::decodex.account_operation_phase;
		RETURN;
	END IF;
	IF p_kind IN ('enroll','import') AND (
		p_target_store_schema_version<>1 OR p_target_credential_version<>1
		OR p_target_credential_fingerprint !~ '^[0-9a-f]{64}$'
		OR p_target_credential_writer_operation_id IS DISTINCT FROM p_operation_id
	) THEN
		RETURN QUERY SELECT 'invalid_request',0::bigint,'prepared'::decodex.account_operation_phase;
		RETURN;
	END IF;
	SELECT * INTO account FROM decodex.accounts WHERE account_id=p_account_id FOR UPDATE;
	IF p_kind IN ('enroll','import') AND NOT FOUND THEN
		PERFORM 1 FROM decodex.account_routing_control WHERE singleton FOR UPDATE;
		IF p_expected_account_revision IS NOT NULL
			OR p_enabled IS NULL
			OR p_display_label IS NULL OR pg_catalog.octet_length(p_display_label) < 1
			OR pg_catalog.octet_length(p_display_label) > 128
			OR p_display_label ~ '[[:cntrl:]]'
			OR decodex.has_credential_material(p_display_label)
			OR (SELECT pg_catalog.count(*) FROM decodex.accounts
				WHERE tombstoned_at IS NULL)>=512
		THEN
			RETURN QUERY SELECT 'invalid_request',0::bigint,'prepared'::decodex.account_operation_phase;
			RETURN;
		END IF;
		BEGIN
			INSERT INTO decodex.accounts(
				account_id,display_label,state,enabled,provider_kind,provider_account_id
			) VALUES (
				p_account_id,p_display_label,'unknown',p_enabled,
				p_provider_kind,p_provider_account_id
			) RETURNING * INTO account;
		EXCEPTION
			WHEN unique_violation THEN
				GET STACKED DIAGNOSTICS conflicting_constraint = CONSTRAINT_NAME;
				IF conflicting_constraint='accounts_provider_identity_unique' THEN
					RETURN QUERY SELECT 'identity_conflict',0::bigint,
						'prepared'::decodex.account_operation_phase;
					RETURN;
				END IF;
				RAISE;
		END;
		INSERT INTO decodex.account_routing_order(account_id,position)
		SELECT p_account_id,COALESCE(pg_catalog.max(position)+1,0)
		FROM decodex.account_routing_order;
		UPDATE decodex.account_routing_control SET revision=revision+1,
			updated_at=pg_catalog.clock_timestamp() WHERE singleton;
	ELSIF NOT FOUND THEN
		RETURN QUERY SELECT 'account_missing',0::bigint,'prepared'::decodex.account_operation_phase;
		RETURN;
	ELSIF account.revision IS DISTINCT FROM p_expected_account_revision
		OR account.tombstoned_at IS NOT NULL
		OR account.provider_kind IS DISTINCT FROM p_provider_kind
		OR account.provider_account_id IS DISTINCT FROM p_provider_account_id
		OR account.credential_store_schema_version IS DISTINCT FROM p_expected_store_schema_version
		OR account.credential_version IS DISTINCT FROM p_expected_credential_version
		OR account.credential_fingerprint IS DISTINCT FROM p_expected_credential_fingerprint
		OR account.credential_writer_operation_id IS DISTINCT FROM
			p_expected_credential_writer_operation_id
	THEN
		RETURN QUERY SELECT 'stale_account',account.revision,'prepared'::decodex.account_operation_phase;
		RETURN;
	END IF;
	IF p_kind='logout' AND (
		EXISTS (SELECT 1 FROM decodex.process_generations AS generation
			WHERE generation.account_id=p_account_id AND generation.state<>'dead')
		OR EXISTS (SELECT 1 FROM decodex.provider_attempts AS attempt
			WHERE attempt.selected_account_id=p_account_id
				AND attempt.state IN ('prepared','dispatch_authorized','unknown'))
		OR EXISTS (SELECT 1 FROM decodex.outbox AS work
			WHERE work.aggregate_kind='reset_card_operation'
				AND work.payload #>> '{payload,account_id}'=p_account_id::text
				AND work.state IN ('pending','in_flight'))
	) THEN
		RETURN QUERY SELECT 'account_in_use',account.revision,
			'prepared'::decodex.account_operation_phase;
		RETURN;
	END IF;
	IF p_kind='refresh' AND p_target_credential_version IS NOT NULL
		AND (p_target_credential_version<>p_expected_credential_version+1
			OR p_target_credential_writer_operation_id IS DISTINCT FROM p_operation_id) THEN
		RETURN QUERY SELECT 'stale_account',account.revision,'prepared'::decodex.account_operation_phase;
		RETURN;
	END IF;
	INSERT INTO decodex.account_operations(
		operation_id,account_id,kind,expected_account_revision,
		expected_store_schema_version,expected_credential_version,
		expected_credential_fingerprint,expected_credential_writer_operation_id,
		target_store_schema_version,target_credential_version,
		target_credential_fingerprint,target_credential_writer_operation_id,
		provider_kind,provider_account_id,requested_display_label,requested_enabled
	) VALUES (
		p_operation_id,p_account_id,p_kind,p_expected_account_revision,
		p_expected_store_schema_version,p_expected_credential_version,
		p_expected_credential_fingerprint,p_expected_credential_writer_operation_id,
		p_target_store_schema_version,p_target_credential_version,
		p_target_credential_fingerprint,p_target_credential_writer_operation_id,
		p_provider_kind,p_provider_account_id,p_display_label,p_enabled
	);
	RETURN QUERY SELECT 'prepared',account.revision,'prepared'::decodex.account_operation_phase;
END
$_$;


--
-- Name: prepare_codex_experiment_exact(text, text, uuid, uuid, bigint, uuid, uuid, bigint, bigint, text, text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.prepare_codex_experiment_exact(p_protocol text, p_idempotency_key text, p_experiment_id uuid, p_managed_run_id uuid, p_managed_run_revision bigint, p_routing_snapshot_id uuid, p_account_id uuid, p_account_revision bigint, p_role_profile_revision bigint, p_build_id text, p_repository_cwd text, p_thread_title text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; replay bytea; prepared timestamptz; marker_value text;
DECLARE core jsonb; effect jsonb; response bytea;
BEGIN
	request:=pg_catalog.jsonb_build_object('operation','prepare_codex_experiment',
		'protocol',p_protocol,'experiment_id',p_experiment_id,
		'managed_run_id',p_managed_run_id,'managed_run_revision',p_managed_run_revision,
		'routing_snapshot_id',p_routing_snapshot_id,'account_id',p_account_id,
		'account_revision',p_account_revision,'role_profile_revision',p_role_profile_revision,
		'build_id',p_build_id,'repository_cwd',p_repository_cwd,'thread_title',p_thread_title);
	replay:=decodex.reserve_exact_codex_experiment_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(1358,pg_catalog.hashtext(p_experiment_id::text));
	marker_value:=decodex.codex_experiment_marker(p_experiment_id);
	IF p_experiment_id IS NULL OR p_managed_run_id IS NULL OR p_routing_snapshot_id IS NULL
		OR p_account_id IS NULL OR p_managed_run_revision<=0 OR p_account_revision<=0
		OR p_role_profile_revision<=0 OR p_build_id IS NULL OR p_build_id=''
		OR p_repository_cwd IS NULL OR p_repository_cwd=''
		OR p_thread_title IS NULL OR position(marker_value IN p_thread_title)=0 THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'prepare_codex_experiment','invalid_identity');
	END IF;
	PERFORM 1 FROM decodex.routing_snapshots AS snapshot
	JOIN decodex.routing_snapshot_members AS member USING (snapshot_id)
	JOIN decodex.managed_runs AS run ON run.managed_run_id=snapshot.managed_run_id
	WHERE snapshot.snapshot_id=p_routing_snapshot_id
		AND snapshot.managed_run_id=p_managed_run_id
		AND snapshot.managed_run_revision=p_managed_run_revision
		AND run.revision=p_managed_run_revision
		AND member.account_id=p_account_id
		AND member.account_revision=p_account_revision
		AND snapshot.required_role_profile_revision=p_role_profile_revision
		AND snapshot.required_build_id=p_build_id FOR SHARE OF snapshot,member,run;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'prepare_codex_experiment','lineage_mismatch');
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.codex_experiments WHERE experiment_id=p_experiment_id) THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'prepare_codex_experiment','experiment_exists');
	END IF;
	prepared:=pg_catalog.clock_timestamp();
	INSERT INTO decodex.codex_experiments(experiment_id,managed_run_id,managed_run_revision,
		routing_snapshot_id,account_id,account_revision,role_profile_revision,build_id,
		repository_cwd,thread_title,revision,state,prepared_at,updated_at)
	VALUES(p_experiment_id,p_managed_run_id,p_managed_run_revision,p_routing_snapshot_id,
		p_account_id,p_account_revision,p_role_profile_revision,p_build_id,p_repository_cwd,
		p_thread_title,1,'prepared',prepared,prepared);
	INSERT INTO decodex.codex_experiment_revisions VALUES(p_experiment_id,1,'prepared',prepared);
	core:=pg_catalog.jsonb_build_object('operation','prepare_codex_experiment',
		'experiment_id',p_experiment_id,'revision',1,'state','prepared','marker',marker_value,
		'managed_run_id',p_managed_run_id,'managed_run_revision',p_managed_run_revision,
		'routing_snapshot_id',p_routing_snapshot_id,'account_id',p_account_id,
		'account_revision',p_account_revision,'role_profile_revision',p_role_profile_revision,
		'build_id',p_build_id,'repository_cwd',p_repository_cwd,'thread_title',p_thread_title,
		'prepared_at_micros',(extract(epoch FROM prepared)*1000000)::bigint);
	effect:=core||pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$$;


--
-- Name: prepare_process_generation_exact(uuid, uuid, uuid, text, text, text, decodex.process_generation_control_kind, decodex.process_generation_isolation_kind, bigint, integer, bigint, text, uuid, decodex.account_provider_kind, text, text, bigint, uuid, uuid, text, text, uuid, bigint, uuid, bigint, uuid, bigint, uuid, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.prepare_process_generation_exact(p_generation_id uuid, p_account_id uuid, p_execution_epoch_id uuid, p_authorization_digest text, p_runner_identity text, p_intended_boot_id text, p_control_kind decodex.process_generation_control_kind, p_isolation_kind decodex.process_generation_isolation_kind, p_initial_account_revision bigint, p_credential_store_schema_version integer, p_credential_version bigint, p_credential_fingerprint text, p_credential_writer_operation_id uuid, p_provider_kind decodex.account_provider_kind, p_provider_account_id text, p_refresh_callback_profile_sha256 text, p_reset_card_outbox_id bigint, p_reset_card_worker_id uuid, p_reset_card_claim_token uuid, p_quick_task_protocol text, p_quick_task_idempotency_key text, p_quick_task_conversation_id uuid, p_quick_task_conversation_revision bigint, p_quick_task_runtime_session_id uuid, p_quick_task_runtime_session_revision bigint, p_quick_task_turn_id uuid, p_quick_task_turn_revision bigint, p_quick_task_continuation_plan_id uuid, p_quick_task_routing_decision_id uuid) RETURNS TABLE(result_code text, revision bigint, state decodex.process_generation_state, created_at_micros bigint, updated_at_micros bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE existing decodex.process_generations%ROWTYPE;
DECLARE account decodex.accounts%ROWTYPE;
DECLARE receipt decodex.exact_command_receipts%ROWTYPE;
DECLARE conversation_row decodex.conversations%ROWTYPE;
DECLARE session_row decodex.runtime_sessions%ROWTYPE;
DECLARE turn_row decodex.turns%ROWTYPE;
DECLARE plan_row decodex.continuation_plans%ROWTYPE;
DECLARE decision_row decodex.routing_decisions%ROWTYPE;
DECLARE account_snapshot_row decodex.account_snapshots%ROWTYPE;
DECLARE expected_turn_session_id uuid;
DECLARE quick_task_count integer;
DECLARE now_value timestamptz;
DECLARE reconciliation_authorized boolean:=false;
BEGIN
	quick_task_count:=pg_catalog.num_nonnulls(
		p_quick_task_protocol,p_quick_task_idempotency_key,
		p_quick_task_conversation_id,p_quick_task_conversation_revision,
		p_quick_task_runtime_session_id,p_quick_task_runtime_session_revision,
		p_quick_task_turn_id,p_quick_task_turn_revision,
		p_quick_task_continuation_plan_id,p_quick_task_routing_decision_id
	);
	IF quick_task_count NOT IN (0,10)
		OR quick_task_count=10 AND p_reset_card_outbox_id IS NOT NULL
	THEN
		RETURN QUERY SELECT 'quick_task_authority_unavailable',0::bigint,
			'starting'::decodex.process_generation_state,0::bigint,0::bigint;
		RETURN;
	END IF;

	PERFORM pg_catalog.pg_advisory_xact_lock_shared(1400);
	IF quick_task_count=10 THEN
		PERFORM pg_catalog.pg_advisory_xact_lock(1271);
		PERFORM pg_catalog.pg_advisory_xact_lock(
			1276,pg_catalog.hashtext(p_quick_task_runtime_session_id::text)
		);
	END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1400,pg_catalog.hashtext(p_generation_id::text));
	PERFORM pg_catalog.pg_advisory_xact_lock(1401,pg_catalog.hashtext(p_account_id::text));

	IF quick_task_count=10 THEN
		SELECT * INTO receipt FROM decodex.exact_command_receipts
		WHERE protocol_version=p_quick_task_protocol
			AND idempotency_key=p_quick_task_idempotency_key FOR SHARE;
		SELECT * INTO conversation_row FROM decodex.conversations
		WHERE conversation_id=p_quick_task_conversation_id FOR UPDATE;
		SELECT * INTO session_row FROM decodex.runtime_sessions
		WHERE runtime_session_id=p_quick_task_runtime_session_id FOR UPDATE;
		SELECT * INTO turn_row FROM decodex.turns
		WHERE turn_id=p_quick_task_turn_id FOR UPDATE;
		SELECT * INTO plan_row FROM decodex.continuation_plans
		WHERE plan_id=p_quick_task_continuation_plan_id FOR SHARE;
		SELECT * INTO decision_row FROM decodex.routing_decisions
		WHERE decision_id=p_quick_task_routing_decision_id FOR SHARE;
		SELECT * INTO account_snapshot_row FROM decodex.account_snapshots
		WHERE account_snapshot_id=session_row.account_snapshot_id FOR SHARE;
		expected_turn_session_id:=CASE plan_row.kind
			WHEN 'context_pack_fallback' THEN plan_row.source_runtime_session_id
			ELSE p_quick_task_runtime_session_id
		END;
		IF p_quick_task_protocol<>'decodex/exact-command/1'
			OR p_quick_task_conversation_revision<=0
			OR p_quick_task_runtime_session_revision<=0
			OR p_quick_task_turn_revision<>1
			OR receipt.receipt_state IS DISTINCT FROM 'completed_success'
			OR receipt.request_envelope->>'operation' IS DISTINCT FROM
				'prepare_quick_task_process_generation'
			OR receipt.request_envelope->>'protocol_version' IS DISTINCT FROM
				p_quick_task_protocol
			OR receipt.request_envelope->>'conversation_id' IS DISTINCT FROM
				p_quick_task_conversation_id::text
			OR receipt.request_envelope->>'expected_conversation_revision' IS DISTINCT FROM
				p_quick_task_conversation_revision::text
			OR receipt.request_envelope->>'runtime_session_id' IS DISTINCT FROM
				p_quick_task_runtime_session_id::text
			OR receipt.request_envelope->>'expected_runtime_session_revision' IS DISTINCT FROM
				p_quick_task_runtime_session_revision::text
			OR receipt.request_envelope->>'turn_id' IS DISTINCT FROM
				p_quick_task_turn_id::text
			OR receipt.request_envelope->>'expected_turn_revision' IS DISTINCT FROM
				p_quick_task_turn_revision::text
			OR receipt.request_envelope->>'continuation_plan_id' IS DISTINCT FROM
				p_quick_task_continuation_plan_id::text
			OR receipt.request_envelope->>'routing_decision_id' IS DISTINCT FROM
				p_quick_task_routing_decision_id::text
			OR receipt.request_envelope->>'selected_account_id' IS DISTINCT FROM
				p_account_id::text
			OR receipt.request_envelope->>'process_generation_id' IS DISTINCT FROM
				p_generation_id::text
			OR receipt.effect_envelope->>'operation' IS DISTINCT FROM
				'prepare_quick_task_process_generation'
			OR receipt.effect_envelope->>'admission_revision' IS DISTINCT FROM '1'
			OR receipt.effect_envelope->>'turn_state' IS DISTINCT FROM 'active'
			OR conversation_row.conversation_id IS NULL
			OR conversation_row.revision<>p_quick_task_conversation_revision
			OR conversation_row.status<>'open'
			OR session_row.runtime_session_id IS NULL
			OR session_row.conversation_id<>p_quick_task_conversation_id
			OR session_row.revision<>p_quick_task_runtime_session_revision
			OR session_row.state<>'starting'
			OR session_row.codex_thread_id IS NOT NULL
			OR turn_row.turn_id IS NULL
			OR turn_row.conversation_id<>p_quick_task_conversation_id
			OR turn_row.runtime_session_id IS DISTINCT FROM expected_turn_session_id
			OR turn_row.role<>'user'
			OR turn_row.possible_side_effects<>'unknown'
			OR turn_row.status<>'active'
			OR turn_row.revision<>p_quick_task_turn_revision
			OR plan_row.plan_id IS NULL
			OR plan_row.consumer_kind<>'conversation_turn'
			OR plan_row.consumer_conversation_id<>p_quick_task_conversation_id
			OR plan_row.conversation_revision<>p_quick_task_conversation_revision
			OR plan_row.turn_id<>p_quick_task_turn_id
			OR plan_row.routing_decision_id<>p_quick_task_routing_decision_id
			OR plan_row.selected_account_id<>p_account_id
			OR NOT (
				plan_row.kind='initial_thread'
					AND plan_row.source_runtime_session_id=p_quick_task_runtime_session_id
					AND plan_row.source_runtime_session_revision=
						p_quick_task_runtime_session_revision
				OR plan_row.kind='context_pack_fallback'
					AND plan_row.fallback_runtime_session_id=p_quick_task_runtime_session_id
					AND p_quick_task_runtime_session_revision=1
			)
			OR decision_row.decision_id IS NULL
			OR decision_row.consumer_kind<>'conversation_turn'
			OR decision_row.conversation_id<>p_quick_task_conversation_id
			OR decision_row.conversation_revision<>p_quick_task_conversation_revision
			OR decision_row.turn_id<>p_quick_task_turn_id
			OR NOT (
				plan_row.kind='initial_thread'
					AND decision_row.authority_shape=
						'conversation_account_registry'
					AND decision_row.kind='selected'
					AND decision_row.selected_account_id=p_account_id
				OR plan_row.kind='context_pack_fallback'
					AND decision_row.authority_shape=
						'conversation_continuation'
					AND decision_row.kind IS NULL
					AND decision_row.account_snapshot_id=
						session_row.account_snapshot_id
					AND decision_row.profile_snapshot_id=
						session_row.profile_snapshot_id
					AND EXISTS (
						SELECT 1
						FROM decodex.routing_decisions AS initial
						WHERE initial.decision_id=
							decision_row.initial_decision_id
							AND initial.authority_shape=
								'conversation_account_registry'
							AND initial.kind='selected'
							AND initial.selected_account_id=p_account_id
					)
			)
		OR account_snapshot_row.account_snapshot_id IS NULL
		OR account_snapshot_row.source_account_id<>p_account_id
		OR account_snapshot_row.source_revision IS DISTINCT FROM
			p_initial_account_revision
	THEN
			RETURN QUERY SELECT 'quick_task_authority_unavailable',0::bigint,
				'starting'::decodex.process_generation_state,0::bigint,0::bigint;
			RETURN;
		END IF;
	END IF;

	SELECT * INTO existing FROM decodex.process_generations
	WHERE generation_id=p_generation_id FOR UPDATE;
	IF FOUND THEN
		IF (existing.account_id,existing.execution_epoch_id,existing.runner_identity,
			existing.intended_boot_id,existing.control_kind,existing.isolation_kind,
			existing.initial_account_revision,existing.credential_store_schema_version,
			existing.credential_version,existing.credential_fingerprint,
			existing.credential_writer_operation_id,
			existing.provider_kind,existing.provider_account_id,
			existing.refresh_callback_profile_sha256,
			existing.quick_task_prepare_protocol,
			existing.quick_task_prepare_idempotency_key) IS DISTINCT FROM
			(p_account_id,p_execution_epoch_id,p_runner_identity,p_intended_boot_id,
			p_control_kind,p_isolation_kind,p_initial_account_revision,
			p_credential_store_schema_version,p_credential_version,p_credential_fingerprint,
			p_credential_writer_operation_id,
			p_provider_kind,p_provider_account_id,p_refresh_callback_profile_sha256,
			p_quick_task_protocol,p_quick_task_idempotency_key)
		THEN
			RETURN QUERY SELECT 'identity_conflict',existing.revision,existing.state,
				(extract(epoch FROM existing.created_at)*1000000)::bigint,
				(extract(epoch FROM existing.updated_at)*1000000)::bigint;
		ELSE
			RETURN QUERY SELECT 'replayed',existing.revision,existing.state,
				(extract(epoch FROM existing.created_at)*1000000)::bigint,
				(extract(epoch FROM existing.updated_at)*1000000)::bigint;
		END IF;
		RETURN;
	END IF;

	IF p_authorization_digest IS NULL OR p_authorization_digest !~ '^[0-9a-f]{64}$' THEN
		RETURN QUERY SELECT 'restore_authority_unavailable',0::bigint,
			'starting'::decodex.process_generation_state,0::bigint,0::bigint;
		RETURN;
	END IF;
	PERFORM 1 FROM decodex.process_generation_execution_epochs AS epoch
	WHERE epoch.execution_epoch_id=p_execution_epoch_id
		AND epoch.authorization_digest=p_authorization_digest AND epoch.retired_at IS NULL FOR SHARE;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'restore_authority_unavailable',0::bigint,
			'starting'::decodex.process_generation_state,0::bigint,0::bigint;
		RETURN;
	END IF;
	SELECT * INTO account FROM decodex.accounts WHERE account_id=p_account_id FOR KEY SHARE;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'account_missing',0::bigint,
			'starting'::decodex.process_generation_state,0::bigint,0::bigint;
		RETURN;
	END IF;
	IF (p_reset_card_outbox_id IS NULL,p_reset_card_worker_id IS NULL,
		p_reset_card_claim_token IS NULL) NOT IN ((true,true,true),(false,false,false))
	THEN
		RETURN QUERY SELECT 'account_lifecycle_unready',0::bigint,
			'starting'::decodex.process_generation_state,0::bigint,0::bigint;
		RETURN;
	END IF;
	IF p_reset_card_outbox_id IS NOT NULL THEN
		SELECT EXISTS (
			SELECT 1 FROM decodex.outbox AS work
			WHERE work.id=p_reset_card_outbox_id
				AND work.aggregate_kind='reset_card_operation'
				AND work.state='in_flight'
				AND work.lease_holder=p_reset_card_worker_id
				AND work.claim_token=p_reset_card_claim_token
				AND work.lease_expires_at>pg_catalog.clock_timestamp()
				AND work.effect_state IN ('ambiguous','receipt_recorded')
				AND work.payload #>> '{payload,account_id}'=p_account_id::text
				AND work.payload #>> '{payload,provider_kind}'=p_provider_kind::text
				AND work.payload #>> '{payload,provider_account_id}'=p_provider_account_id
				AND work.payload #>> '{payload,refresh_callback_profile_sha256}'=
					p_refresh_callback_profile_sha256
		) INTO reconciliation_authorized;
		IF NOT reconciliation_authorized THEN
			RETURN QUERY SELECT 'account_lifecycle_unready',0::bigint,
				'starting'::decodex.process_generation_state,0::bigint,0::bigint;
			RETURN;
		END IF;
	END IF;
	IF account.tombstoned_at IS NOT NULL OR account.revision<>p_initial_account_revision
		OR account.credential_store_observation<>'exact'
		OR account.credential_store_schema_version<>p_credential_store_schema_version
		OR account.credential_version<>p_credential_version
		OR account.credential_fingerprint<>p_credential_fingerprint
		OR account.credential_writer_operation_id<>p_credential_writer_operation_id
		OR account.provider_kind<>p_provider_kind
		OR account.provider_account_id<>p_provider_account_id
		OR p_refresh_callback_profile_sha256 !~ '^[0-9a-f]{64}$'
		OR (NOT reconciliation_authorized AND (NOT account.enabled OR EXISTS (
			SELECT 1 FROM decodex.account_operations AS operation
			WHERE operation.account_id=p_account_id
				AND operation.phase NOT IN ('committed','cancelled'))))
	THEN
		RETURN QUERY SELECT 'account_lifecycle_unready',0::bigint,
			'starting'::decodex.process_generation_state,0::bigint,0::bigint;
		RETURN;
	END IF;
	IF NOT reconciliation_authorized AND NOT EXISTS (
		SELECT 1 FROM decodex.codex_account_capability AS capability
		WHERE capability.singleton AND capability.login_chatgpt_auth_tokens
			AND capability.refresh_callback
			AND capability.executable_sha256 ~ '^[0-9a-f]{64}$'
			AND capability.schema_sha256 ~ '^[0-9a-f]{64}$'
			AND capability.callback_profile_sha256 ~ '^[0-9a-f]{64}$'
			AND capability.callback_profile_sha256=p_refresh_callback_profile_sha256)
	THEN
		RETURN QUERY SELECT 'callback_capability_unready',0::bigint,
			'starting'::decodex.process_generation_state,0::bigint,0::bigint;
		RETURN;
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.process_generations AS generation
		WHERE generation.account_id=p_account_id AND generation.state<>'dead')
	THEN
		RETURN QUERY SELECT 'account_quarantined',0::bigint,
			'starting'::decodex.process_generation_state,0::bigint,0::bigint;
		RETURN;
	END IF;
	now_value:=pg_catalog.clock_timestamp();
	INSERT INTO decodex.process_generations(
		generation_id,account_id,execution_epoch_id,runner_identity,intended_boot_id,
		control_kind,isolation_kind,state,revision,created_at,updated_at,
		initial_account_revision,credential_store_schema_version,credential_version,
		credential_fingerprint,credential_writer_operation_id,provider_kind,
		provider_account_id,refresh_callback_profile_sha256,
		quick_task_prepare_protocol,quick_task_prepare_idempotency_key
	) VALUES (
		p_generation_id,p_account_id,p_execution_epoch_id,p_runner_identity,p_intended_boot_id,
		p_control_kind,p_isolation_kind,'starting',1,now_value,now_value,
		p_initial_account_revision,p_credential_store_schema_version,p_credential_version,
		p_credential_fingerprint,p_credential_writer_operation_id,
		p_provider_kind,p_provider_account_id,p_refresh_callback_profile_sha256,
		p_quick_task_protocol,p_quick_task_idempotency_key
	);
	RETURN QUERY SELECT 'prepared',1::bigint,'starting'::decodex.process_generation_state,
		(extract(epoch FROM now_value)*1000000)::bigint,
		(extract(epoch FROM now_value)*1000000)::bigint;
END
$_$;


--
-- Name: prepare_provider_attempt_exact(uuid, decodex.provider_attempt_consumer_kind, uuid, uuid, uuid, bigint, uuid, uuid, uuid, bigint, uuid, uuid, text, text, text, uuid, text, text, text, bigint, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.prepare_provider_attempt_exact(p_attempt_id uuid, p_consumer_kind decodex.provider_attempt_consumer_kind, p_conversation_id uuid, p_turn_id uuid, p_managed_run_id uuid, p_managed_run_revision bigint, p_managed_execution_id uuid, p_continuation_plan_id uuid, p_process_generation_id uuid, p_process_generation_revision bigint, p_process_execution_epoch_id uuid, p_request_id uuid, p_request_digest text, p_provider_idempotency_key text, p_provider_correlation_key text, p_predecessor_attempt_id uuid, p_duplicate_risk_ack_digest text, p_runtime_session_binding_protocol text, p_runtime_session_binding_idempotency_key text, p_expected_conversation_revision bigint, p_expected_turn_revision bigint) RETURNS TABLE(result_code text, revision bigint, state decodex.provider_attempt_state, created_at_micros bigint, updated_at_micros bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE existing decodex.provider_attempts%ROWTYPE;
DECLARE plan decodex.continuation_plans%ROWTYPE;
DECLARE generation decodex.process_generations%ROWTYPE;
DECLARE session_row decodex.runtime_sessions%ROWTYPE;
DECLARE conversation_row decodex.conversations%ROWTYPE;
DECLARE turn_row decodex.turns%ROWTYPE;
DECLARE binding decodex.exact_command_receipts%ROWTYPE;
DECLARE fence decodex.exact_command_receipts%ROWTYPE;
DECLARE accepted_session_id uuid; accepted_session_revision bigint;
DECLARE expected_turn_session_id uuid; now_value timestamptz;
BEGIN
	PERFORM pg_catalog.pg_advisory_xact_lock_shared(1400);
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1401,pg_catalog.hashtext(
			COALESCE(p_consumer_kind::text,'invalid')||':'||
			COALESCE(p_turn_id::text,p_managed_execution_id::text,'invalid')
		)
	);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1402,pg_catalog.hashtext(p_attempt_id::text)
	);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1403,pg_catalog.hashtext(p_request_id::text)
	);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1404,pg_catalog.hashtext(p_continuation_plan_id::text)
	);
	SELECT * INTO existing FROM decodex.provider_attempts
	WHERE attempt_id=p_attempt_id FOR UPDATE;
	IF FOUND THEN
		IF (
			existing.consumer_kind,existing.conversation_id,existing.turn_id,
			existing.managed_run_id,existing.managed_run_revision,
			existing.managed_execution_id,existing.continuation_plan_id,
			existing.process_generation_id,existing.process_generation_revision,
			existing.process_execution_epoch_id,existing.request_id,existing.request_digest,
			existing.provider_idempotency_key,existing.provider_correlation_key,
			existing.predecessor_attempt_id,existing.duplicate_risk_ack_digest,
			existing.runtime_session_binding_protocol,
			existing.runtime_session_binding_idempotency_key
		) IS DISTINCT FROM (
			p_consumer_kind,p_conversation_id,p_turn_id,p_managed_run_id,
			p_managed_run_revision,p_managed_execution_id,p_continuation_plan_id,
			p_process_generation_id,p_process_generation_revision,
			p_process_execution_epoch_id,p_request_id,p_request_digest,
			p_provider_idempotency_key,p_provider_correlation_key,
			p_predecessor_attempt_id,p_duplicate_risk_ack_digest,
			p_runtime_session_binding_protocol,p_runtime_session_binding_idempotency_key
		) THEN
			RETURN QUERY SELECT 'identity_conflict',existing.revision,existing.state,
				(extract(epoch FROM existing.created_at)*1000000)::bigint,
				(extract(epoch FROM existing.updated_at)*1000000)::bigint;
		ELSE
			RETURN QUERY SELECT 'replayed',existing.revision,existing.state,
				(extract(epoch FROM existing.created_at)*1000000)::bigint,
				(extract(epoch FROM existing.updated_at)*1000000)::bigint;
		END IF;
		RETURN;
	END IF;

	IF p_attempt_id IS NULL OR p_continuation_plan_id IS NULL
		OR p_process_generation_id IS NULL
		OR p_process_generation_revision IS NULL OR p_process_generation_revision<=0
		OR p_process_execution_epoch_id IS NULL OR p_request_id IS NULL
		OR p_request_digest IS NULL
		OR p_request_digest COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$'
		OR p_provider_idempotency_key IS NULL AND p_provider_correlation_key IS NULL
		OR p_provider_idempotency_key IS NOT NULL AND (
			pg_catalog.octet_length(p_provider_idempotency_key) NOT BETWEEN 1 AND 512
			OR p_provider_idempotency_key COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
		)
		OR p_provider_correlation_key IS NOT NULL AND (
			pg_catalog.octet_length(p_provider_correlation_key) NOT BETWEEN 1 AND 512
			OR p_provider_correlation_key COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
		)
		OR (p_predecessor_attempt_id IS NULL)<>(p_duplicate_risk_ack_digest IS NULL)
		OR p_duplicate_risk_ack_digest IS NOT NULL
			AND p_duplicate_risk_ack_digest COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$'
		OR NOT (
			p_consumer_kind='conversation_turn'
				AND p_conversation_id IS NOT NULL AND p_turn_id IS NOT NULL
				AND p_managed_run_id IS NULL AND p_managed_run_revision IS NULL
				AND p_managed_execution_id IS NULL
				AND p_expected_conversation_revision>0 AND p_expected_turn_revision=1
			OR p_consumer_kind='managed_run_execution'
				AND p_conversation_id IS NULL AND p_turn_id IS NULL
				AND p_managed_run_id IS NOT NULL AND p_managed_run_revision>0
				AND p_managed_execution_id IS NOT NULL
				AND p_expected_conversation_revision IS NULL
				AND p_expected_turn_revision IS NULL
		)
		OR NOT (
			p_runtime_session_binding_protocol IS NULL
				AND p_runtime_session_binding_idempotency_key IS NULL
			OR p_runtime_session_binding_protocol='decodex/exact-command/1'
				AND p_runtime_session_binding_idempotency_key IS NOT NULL
				AND pg_catalog.octet_length(
					p_runtime_session_binding_idempotency_key
				) BETWEEN 1 AND 256
				AND p_runtime_session_binding_idempotency_key
					COLLATE pg_catalog."C" !~ '[[:cntrl:]]'
				AND NOT decodex.has_credential_material(
					p_runtime_session_binding_idempotency_key
				)
		)
	THEN
		RETURN QUERY SELECT 'invalid_input',0::bigint,
			'prepared'::decodex.provider_attempt_state,0::bigint,0::bigint;
		RETURN;
	END IF;

	SELECT * INTO plan FROM decodex.continuation_plans
	WHERE plan_id=p_continuation_plan_id FOR SHARE;
	IF plan.plan_id IS NULL OR (
		plan.consumer_kind,plan.consumer_conversation_id,plan.turn_id,
		plan.managed_run_id,plan.managed_run_revision,plan.managed_execution_id
	) IS DISTINCT FROM (
		p_consumer_kind,p_conversation_id,p_turn_id,p_managed_run_id,
		p_managed_run_revision,p_managed_execution_id
	) THEN
		RETURN QUERY SELECT 'authority_unavailable',0::bigint,
			'prepared'::decodex.provider_attempt_state,0::bigint,0::bigint;
		RETURN;
	END IF;
	CASE plan.kind
		WHEN 'initial_thread' THEN
			accepted_session_id:=plan.source_runtime_session_id;
			accepted_session_revision:=plan.source_runtime_session_revision+2;
		WHEN 'context_pack_fallback' THEN
			accepted_session_id:=plan.fallback_runtime_session_id;
			accepted_session_revision:=3;
		WHEN 'same_thread' THEN
			accepted_session_id:=plan.source_runtime_session_id;
			accepted_session_revision:=plan.source_runtime_session_revision;
		ELSE
			RETURN QUERY SELECT 'authority_unavailable',0::bigint,
				'prepared'::decodex.provider_attempt_state,0::bigint,0::bigint;
			RETURN;
	END CASE;
	IF (plan.kind='same_thread')<>
		(p_runtime_session_binding_protocol IS NULL)
	THEN
		RETURN QUERY SELECT 'authority_unavailable',0::bigint,
			'prepared'::decodex.provider_attempt_state,0::bigint,0::bigint;
		RETURN;
	END IF;

	SELECT * INTO generation FROM decodex.process_generations
	WHERE generation_id=p_process_generation_id FOR SHARE;
	IF generation.generation_id IS NULL
		OR generation.revision<>p_process_generation_revision
		OR generation.state<>'ready' OR generation.account_id<>plan.selected_account_id
		OR generation.execution_epoch_id<>p_process_execution_epoch_id
		OR generation.process_id IS NULL
		OR NOT EXISTS (
			SELECT 1 FROM decodex.process_generation_transitions AS transition
			JOIN decodex.process_generation_execution_epochs AS epoch
				ON epoch.execution_epoch_id=generation.execution_epoch_id
			WHERE (transition.generation_id,transition.revision)=(
				generation.generation_id,generation.revision
			)
				AND transition.state='ready' AND epoch.retired_at IS NULL
			FOR SHARE OF transition,epoch
		)
	THEN
		RETURN QUERY SELECT 'generation_unavailable',0::bigint,
			'prepared'::decodex.provider_attempt_state,0::bigint,0::bigint;
		RETURN;
	END IF;

	SELECT * INTO session_row FROM decodex.runtime_sessions
	WHERE runtime_session_id=accepted_session_id FOR SHARE;
	IF session_row.runtime_session_id IS NULL
		OR session_row.revision<>accepted_session_revision
		OR session_row.state<>'active' OR session_row.codex_thread_id IS NULL
		OR NOT EXISTS (
			SELECT 1 FROM decodex.routing_decisions AS decision
			LEFT JOIN decodex.routing_decisions AS initial
				ON initial.decision_id=decision.initial_decision_id
			JOIN decodex.account_snapshots AS account
				ON account.account_snapshot_id=session_row.account_snapshot_id
			WHERE decision.decision_id=plan.routing_decision_id
				AND (
					plan.consumer_kind='managed_run_execution'
						AND decision.authority_shape=
							'managed_run_project_policy'
						AND decision.kind='selected'
						AND decision.selected_account_id=
							plan.selected_account_id
					OR plan.consumer_kind='conversation_turn'
						AND (
							plan.kind='initial_thread'
								AND decision.authority_shape=
									'conversation_account_registry'
								AND decision.kind='selected'
								AND decision.selected_account_id=
									plan.selected_account_id
							OR decision.authority_shape=
								'conversation_continuation'
								AND decision.kind IS NULL
								AND initial.authority_shape=
									'conversation_account_registry'
								AND initial.kind='selected'
								AND initial.selected_account_id=
									plan.selected_account_id
								AND decision.account_snapshot_id=
									session_row.account_snapshot_id
								AND decision.profile_snapshot_id=
									session_row.profile_snapshot_id
						)
				)
				AND account.source_account_id=plan.selected_account_id
			FOR SHARE OF decision,account
		)
	THEN
		RETURN QUERY SELECT 'authority_unavailable',0::bigint,
			'prepared'::decodex.provider_attempt_state,0::bigint,0::bigint;
		RETURN;
	END IF;

	IF plan.kind<>'same_thread' THEN
		SELECT * INTO binding FROM decodex.exact_command_receipts
		WHERE protocol_version=p_runtime_session_binding_protocol
			AND idempotency_key=p_runtime_session_binding_idempotency_key FOR SHARE;
		SELECT * INTO fence FROM decodex.exact_command_receipts
		WHERE protocol_version=binding.request_envelope->>'fence_protocol'
			AND idempotency_key=binding.request_envelope->>'fence_idempotency_key' FOR SHARE;
		IF binding.receipt_state IS DISTINCT FROM 'completed_success'
			OR binding.request_envelope->>'operation' IS DISTINCT FROM
				'bind_runtime_session_thread'
			OR binding.request_envelope->>'conversation_id' IS DISTINCT FROM
				plan.conversation_id::text
			OR binding.request_envelope->>'runtime_session_id' IS DISTINCT FROM
				accepted_session_id::text
			OR binding.request_envelope->>'expected_revision' IS DISTINCT FROM
				(accepted_session_revision-1)::text
			OR binding.request_envelope->>'turn_id' IS DISTINCT FROM plan.turn_id::text
			OR binding.request_envelope->>'expected_turn_revision' IS DISTINCT FROM '1'
			OR binding.request_envelope->>'continuation_plan_id' IS DISTINCT FROM
				plan.plan_id::text
			OR binding.effect_envelope->>'revision' IS DISTINCT FROM
				accepted_session_revision::text
			OR fence.receipt_state IS DISTINCT FROM 'completed_success'
			OR fence.request_envelope->>'operation' IS DISTINCT FROM
				'fence_runtime_session_thread_start'
			OR fence.request_envelope->>'conversation_id' IS DISTINCT FROM
				plan.conversation_id::text
			OR fence.request_envelope->>'runtime_session_id' IS DISTINCT FROM
				accepted_session_id::text
			OR fence.request_envelope->>'turn_id' IS DISTINCT FROM plan.turn_id::text
			OR fence.request_envelope->>'continuation_plan_id' IS DISTINCT FROM
				plan.plan_id::text
			OR fence.request_envelope->>'process_generation_id' IS DISTINCT FROM
				p_process_generation_id::text
			OR fence.request_envelope->>'process_generation_revision' IS DISTINCT FROM
				p_process_generation_revision::text
			OR fence.request_envelope->>'process_execution_epoch_id' IS DISTINCT FROM
				p_process_execution_epoch_id::text
		THEN
			RETURN QUERY SELECT 'authority_unavailable',0::bigint,
				'prepared'::decodex.provider_attempt_state,0::bigint,0::bigint;
			RETURN;
		END IF;
	END IF;

	IF p_consumer_kind='conversation_turn' THEN
		SELECT * INTO conversation_row FROM decodex.conversations
		WHERE conversation_id=p_conversation_id FOR UPDATE;
		SELECT * INTO turn_row FROM decodex.turns WHERE turn_id=p_turn_id FOR UPDATE;
		expected_turn_session_id:=plan.source_runtime_session_id;
		IF conversation_row.conversation_id IS NULL OR conversation_row.status<>'open'
			OR conversation_row.revision<>p_expected_conversation_revision
			OR plan.conversation_revision<>p_expected_conversation_revision
			OR turn_row.turn_id IS NULL OR turn_row.conversation_id<>p_conversation_id
			OR turn_row.runtime_session_id<>expected_turn_session_id
			OR turn_row.role<>'user' OR turn_row.possible_side_effects<>'unknown'
			OR turn_row.status<>'active'
			OR turn_row.revision<>p_expected_turn_revision
		THEN
			RETURN QUERY SELECT 'consumer_unavailable',0::bigint,
				'prepared'::decodex.provider_attempt_state,0::bigint,0::bigint;
			RETURN;
		END IF;
	ELSIF NOT EXISTS (
		SELECT 1 FROM decodex.managed_runs AS run
		WHERE (run.managed_run_id,run.revision)=(p_managed_run_id,p_managed_run_revision)
		FOR SHARE
	) THEN
		RETURN QUERY SELECT 'consumer_unavailable',0::bigint,
			'prepared'::decodex.provider_attempt_state,0::bigint,0::bigint;
		RETURN;
	END IF;

	PERFORM pg_catalog.pg_advisory_xact_lock(
		1405,pg_catalog.hashtext(
			plan.selected_account_id::text||':'||COALESCE(p_provider_idempotency_key,'')
		)
	);
	IF EXISTS (
		SELECT 1 FROM decodex.provider_attempts AS assigned
		WHERE assigned.request_id=p_request_id
			OR assigned.continuation_plan_id=p_continuation_plan_id
			OR p_provider_idempotency_key IS NOT NULL
				AND assigned.selected_account_id=plan.selected_account_id
				AND assigned.provider_idempotency_key=p_provider_idempotency_key
	) THEN
		RETURN QUERY SELECT 'identity_conflict',0::bigint,
			'prepared'::decodex.provider_attempt_state,0::bigint,0::bigint;
		RETURN;
	END IF;
	now_value:=pg_catalog.clock_timestamp();
	INSERT INTO decodex.provider_attempts(
		attempt_id,consumer_kind,conversation_id,turn_id,managed_run_id,
		managed_run_revision,managed_execution_id,continuation_plan_id,
		routing_decision_id,accepted_runtime_session_id,
		accepted_runtime_session_revision,selected_account_id,
		process_generation_id,process_generation_revision,
		process_execution_epoch_id,request_id,request_digest,
		provider_idempotency_key,provider_correlation_key,
		predecessor_attempt_id,duplicate_risk_ack_digest,
		runtime_session_binding_protocol,runtime_session_binding_idempotency_key,
		state,revision,created_at,updated_at
	) VALUES (
		p_attempt_id,p_consumer_kind,p_conversation_id,p_turn_id,p_managed_run_id,
		p_managed_run_revision,p_managed_execution_id,p_continuation_plan_id,
		plan.routing_decision_id,accepted_session_id,accepted_session_revision,
		plan.selected_account_id,p_process_generation_id,p_process_generation_revision,
		p_process_execution_epoch_id,p_request_id,p_request_digest,
		p_provider_idempotency_key,p_provider_correlation_key,
		p_predecessor_attempt_id,p_duplicate_risk_ack_digest,
		p_runtime_session_binding_protocol,p_runtime_session_binding_idempotency_key,
		'prepared',1,now_value,now_value
	);
	RETURN QUERY SELECT 'prepared',1::bigint,
		'prepared'::decodex.provider_attempt_state,
		(extract(epoch FROM now_value)*1000000)::bigint,
		(extract(epoch FROM now_value)*1000000)::bigint;
END
$_$;


--
-- Name: prepare_quick_task_process_generation_exact(text, text, uuid, bigint, uuid, bigint, uuid, bigint, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.prepare_quick_task_process_generation_exact(p_protocol text, p_idempotency_key text, p_conversation_id uuid, p_expected_conversation_revision bigint, p_runtime_session_id uuid, p_expected_runtime_session_revision bigint, p_turn_id uuid, p_expected_turn_revision bigint, p_continuation_plan_id uuid, p_routing_decision_id uuid, p_selected_account_id uuid, p_process_generation_id uuid) RETURNS TABLE(response_bytes bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; claimed record;
DECLARE conversation_row decodex.conversations%ROWTYPE;
DECLARE session_row decodex.runtime_sessions%ROWTYPE;
DECLARE turn_row decodex.turns%ROWTYPE;
DECLARE plan_row decodex.continuation_plans%ROWTYPE;
DECLARE decision_row decodex.routing_decisions%ROWTYPE;
DECLARE account_row decodex.account_snapshots%ROWTYPE;
DECLARE existing_prepare decodex.exact_command_receipts%ROWTYPE;
DECLARE expected_turn_session_id uuid;
DECLARE rejection text; core jsonb; effect jsonb;
DECLARE conflicting_prepare boolean:=false;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','prepare_quick_task_process_generation',
		'protocol_version',p_protocol,
		'conversation_id',p_conversation_id,
		'expected_conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'expected_runtime_session_revision',p_expected_runtime_session_revision,
		'turn_id',p_turn_id,'expected_turn_revision',p_expected_turn_revision,
		'continuation_plan_id',p_continuation_plan_id,
		'routing_decision_id',p_routing_decision_id,
		'selected_account_id',p_selected_account_id,
		'process_generation_id',p_process_generation_id
	);
	IF p_protocol IS NULL OR p_protocol<>'decodex/exact-command/1'
		OR p_idempotency_key IS NULL
		OR pg_catalog.octet_length(p_idempotency_key)<1
		OR pg_catalog.octet_length(p_idempotency_key)>256
		OR p_idempotency_key COLLATE pg_catalog."C" ~ '[[:cntrl:]]'
		OR decodex.has_credential_material(p_idempotency_key)
	THEN
		RAISE EXCEPTION 'invalid exact RuntimeSession thread command identity'
			USING ERRCODE='22023';
	END IF;

	PERFORM pg_catalog.pg_advisory_xact_lock_shared(1400);
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1276,pg_catalog.hashtext(COALESCE(p_runtime_session_id::text,'invalid'))
	);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1400,pg_catalog.hashtext(COALESCE(p_process_generation_id::text,'invalid'))
	);
	SELECT * INTO existing_prepare
	FROM decodex.exact_command_receipts AS receipt
	WHERE receipt.request_envelope->>'operation'=
			'prepare_quick_task_process_generation'
		AND receipt.request_envelope->>'turn_id'=p_turn_id::text
	ORDER BY receipt.protocol_version,receipt.idempotency_key
	LIMIT 1
	FOR SHARE;
	IF existing_prepare.protocol_version IS NOT NULL
		AND (existing_prepare.protocol_version,existing_prepare.idempotency_key)
			IS DISTINCT FROM (p_protocol,p_idempotency_key)
	THEN
		conflicting_prepare:=true;
		rejection:='authority_unavailable';
		SELECT * INTO turn_row FROM decodex.turns WHERE turn_id=p_turn_id;
	ELSE
		SELECT * INTO claimed FROM decodex.claim_runtime_session_thread_command(
			p_protocol,p_idempotency_key,request
		);
		IF claimed.replayed THEN
			RETURN QUERY SELECT claimed.response_bytes,true;
			RETURN;
		END IF;
	END IF;

	IF rejection IS NULL THEN
	IF p_conversation_id IS NULL OR p_runtime_session_id IS NULL OR p_turn_id IS NULL
		OR p_continuation_plan_id IS NULL OR p_routing_decision_id IS NULL
		OR p_selected_account_id IS NULL OR p_process_generation_id IS NULL
		OR p_expected_conversation_revision IS NULL OR p_expected_conversation_revision<=0
		OR p_expected_runtime_session_revision IS NULL
		OR p_expected_runtime_session_revision<=0
		OR p_expected_turn_revision IS DISTINCT FROM 1
	THEN
		rejection:='invalid_input';
	ELSE
		SELECT * INTO conversation_row FROM decodex.conversations
		WHERE conversation_id=p_conversation_id FOR UPDATE;
		SELECT * INTO session_row FROM decodex.runtime_sessions
		WHERE runtime_session_id=p_runtime_session_id FOR UPDATE;
		SELECT * INTO turn_row FROM decodex.turns WHERE turn_id=p_turn_id FOR UPDATE;
		SELECT * INTO plan_row FROM decodex.continuation_plans
		WHERE plan_id=p_continuation_plan_id FOR SHARE;
		SELECT * INTO decision_row FROM decodex.routing_decisions
		WHERE decision_id=p_routing_decision_id FOR SHARE;
		SELECT * INTO account_row FROM decodex.account_snapshots
		WHERE account_snapshot_id=session_row.account_snapshot_id FOR SHARE;
		expected_turn_session_id:=CASE plan_row.kind
			WHEN 'context_pack_fallback' THEN plan_row.source_runtime_session_id
			ELSE p_runtime_session_id
		END;
		IF turn_row.turn_id IS NULL THEN
			rejection:='missing_turn';
		ELSIF turn_row.status<>'active' THEN
			rejection:='inactive_turn';
		ELSIF turn_row.revision<>1 THEN
			rejection:='stale_turn';
		ELSIF conversation_row.conversation_id IS NULL
			OR conversation_row.revision<>p_expected_conversation_revision
			OR conversation_row.status<>'open'
			OR session_row.runtime_session_id IS NULL
			OR session_row.conversation_id<>p_conversation_id
			OR session_row.revision<>p_expected_runtime_session_revision
			OR session_row.state<>'starting'
			OR session_row.codex_thread_id IS NOT NULL
			OR turn_row.conversation_id<>p_conversation_id
			OR turn_row.runtime_session_id IS DISTINCT FROM expected_turn_session_id
			OR turn_row.role<>'user'
			OR turn_row.possible_side_effects<>'unknown'
			OR plan_row.plan_id IS NULL
			OR plan_row.consumer_kind<>'conversation_turn'
			OR plan_row.consumer_conversation_id<>p_conversation_id
			OR plan_row.conversation_revision<>p_expected_conversation_revision
			OR plan_row.turn_id<>p_turn_id
			OR plan_row.routing_decision_id<>p_routing_decision_id
			OR plan_row.selected_account_id<>p_selected_account_id
			OR NOT (
				plan_row.kind='initial_thread'
					AND plan_row.source_runtime_session_id=p_runtime_session_id
					AND plan_row.source_runtime_session_revision=
						p_expected_runtime_session_revision
				OR plan_row.kind='context_pack_fallback'
					AND plan_row.fallback_runtime_session_id=p_runtime_session_id
					AND p_expected_runtime_session_revision=1
			)
			OR decision_row.decision_id IS NULL
			OR decision_row.consumer_kind<>'conversation_turn'
			OR decision_row.conversation_id<>p_conversation_id
			OR decision_row.conversation_revision<>p_expected_conversation_revision
			OR decision_row.turn_id<>p_turn_id
			OR NOT (
				plan_row.kind='initial_thread'
					AND decision_row.authority_shape=
						'conversation_account_registry'
					AND decision_row.kind='selected'
					AND decision_row.selected_account_id=
						p_selected_account_id
				OR plan_row.kind='context_pack_fallback'
					AND decision_row.authority_shape=
						'conversation_continuation'
					AND decision_row.kind IS NULL
					AND decision_row.account_snapshot_id=
						session_row.account_snapshot_id
					AND decision_row.profile_snapshot_id=
						session_row.profile_snapshot_id
					AND EXISTS (
						SELECT 1
						FROM decodex.routing_decisions AS initial
						WHERE initial.decision_id=
							decision_row.initial_decision_id
							AND initial.authority_shape=
								'conversation_account_registry'
							AND initial.kind='selected'
							AND initial.selected_account_id=
								p_selected_account_id
					)
			)
			OR account_row.account_snapshot_id IS NULL
			OR account_row.source_account_id<>p_selected_account_id
			OR EXISTS (
				SELECT 1 FROM decodex.process_generations
				WHERE generation_id=p_process_generation_id
			)
		THEN
			rejection:='authority_unavailable';
		END IF;
	END IF;
	END IF;

	IF rejection IS NOT NULL THEN
		core:=pg_catalog.jsonb_build_object(
			'operation','prepare_quick_task_process_generation',
			'conversation_id',p_conversation_id,
			'conversation_revision',p_expected_conversation_revision,
			'runtime_session_id',p_runtime_session_id,
			'runtime_session_revision',p_expected_runtime_session_revision,
			'turn_id',p_turn_id,'turn_revision',p_expected_turn_revision,
			'turn_state',CASE
				WHEN turn_row.turn_id IS NULL THEN 'missing'
				ELSE turn_row.status::text
			END,
			'continuation_plan_id',p_continuation_plan_id,
			'routing_decision_id',p_routing_decision_id,
			'selected_account_id',p_selected_account_id,
			'process_generation_id',p_process_generation_id,
			'admission_revision',NULL,
			'changed',false,'rejection',rejection
		);
		effect:=core||pg_catalog.jsonb_build_object(
			'effect_digest_source',core::text,
			'effect_digest',pg_catalog.encode(public.digest(
				pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
		);
		response_bytes:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
			'classification','stable_domain_rejection','effect',effect
		)::text,'UTF8');
		UPDATE decodex.exact_command_receipts SET
			receipt_state='completed_rejected',outcome_class='stable_domain_rejection',
			effect_envelope=effect,response_bytes=response_bytes,
			completed_at=pg_catalog.clock_timestamp()
		WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key
			AND receipt_state='executing';
		replayed:=conflicting_prepare;
		RETURN NEXT;
		RETURN;
	END IF;

	core:=pg_catalog.jsonb_build_object(
		'operation','prepare_quick_task_process_generation',
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'runtime_session_revision',p_expected_runtime_session_revision,
		'turn_id',p_turn_id,'turn_revision',p_expected_turn_revision,
		'turn_state','active','continuation_plan_id',p_continuation_plan_id,
		'routing_decision_id',p_routing_decision_id,
		'selected_account_id',p_selected_account_id,
		'process_generation_id',p_process_generation_id,
		'admission_revision',1,'changed',true
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	response_bytes:=decodex.complete_runtime_session_thread_command(
		p_protocol,p_idempotency_key,effect
	);
	replayed:=false;
	RETURN NEXT;
END
$$;


--
-- Name: prove_initial_quick_task_spawn_not_created_exact(uuid, bigint, uuid, bigint, uuid, bigint, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.prove_initial_quick_task_spawn_not_created_exact(p_conversation_id uuid, p_expected_conversation_revision bigint, p_runtime_session_id uuid, p_expected_runtime_session_revision bigint, p_turn_id uuid, p_expected_turn_revision bigint, p_continuation_plan_id uuid, p_routing_decision_id uuid, p_selected_account_id uuid, p_process_generation_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE prepare_count bigint;
DECLARE linked_generation_count bigint;
DECLARE receipt decodex.exact_command_receipts%ROWTYPE;
DECLARE expected_request jsonb;
DECLARE core jsonb;
DECLARE expected_effect jsonb;
DECLARE expected_response bytea;
BEGIN
	IF p_conversation_id IS NULL OR p_expected_conversation_revision IS NULL
		OR p_expected_conversation_revision<=0 OR p_runtime_session_id IS NULL
		OR p_expected_runtime_session_revision IS DISTINCT FROM 1
		OR p_turn_id IS NULL OR p_expected_turn_revision IS DISTINCT FROM 1
		OR p_continuation_plan_id IS NULL OR p_routing_decision_id IS NULL
		OR p_selected_account_id IS NULL OR p_process_generation_id IS NULL
	THEN
		RETURN false;
	END IF;

	expected_request:=pg_catalog.jsonb_build_object(
		'operation','prepare_quick_task_process_generation',
		'protocol_version','decodex/exact-command/1',
		'conversation_id',p_conversation_id,
		'expected_conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'expected_runtime_session_revision',p_expected_runtime_session_revision,
		'turn_id',p_turn_id,'expected_turn_revision',p_expected_turn_revision,
		'continuation_plan_id',p_continuation_plan_id,
		'routing_decision_id',p_routing_decision_id,
		'selected_account_id',p_selected_account_id,
		'process_generation_id',p_process_generation_id
	);
	core:=pg_catalog.jsonb_build_object(
		'operation','prepare_quick_task_process_generation',
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'runtime_session_revision',p_expected_runtime_session_revision,
		'turn_id',p_turn_id,'turn_revision',p_expected_turn_revision,
		'turn_state','active','continuation_plan_id',p_continuation_plan_id,
		'routing_decision_id',p_routing_decision_id,
		'selected_account_id',p_selected_account_id,
		'process_generation_id',p_process_generation_id,
		'admission_revision',1,'changed',true
	);
	expected_effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	expected_response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',expected_effect
	)::text,'UTF8');

	SELECT pg_catalog.count(*) INTO prepare_count
	FROM decodex.exact_command_receipts AS candidate
	WHERE (
		candidate.request_envelope->>'operation'=
			'prepare_quick_task_process_generation'
		AND candidate.request_envelope->>'turn_id'=p_turn_id::text
	) OR (
		candidate.effect_envelope->>'operation'=
			'prepare_quick_task_process_generation'
		AND candidate.effect_envelope->>'turn_id'=p_turn_id::text
	);
	IF prepare_count<>1 THEN
		RETURN false;
	END IF;
	SELECT * INTO receipt
	FROM decodex.exact_command_receipts AS candidate
	WHERE (
		candidate.request_envelope->>'operation'=
			'prepare_quick_task_process_generation'
		AND candidate.request_envelope->>'turn_id'=p_turn_id::text
	) OR (
		candidate.effect_envelope->>'operation'=
			'prepare_quick_task_process_generation'
		AND candidate.effect_envelope->>'turn_id'=p_turn_id::text
	);
	IF receipt.protocol_version IS DISTINCT FROM 'decodex/exact-command/1'
		OR receipt.receipt_state IS DISTINCT FROM 'completed_success'
		OR receipt.outcome_class IS DISTINCT FROM 'success'
		OR receipt.request_envelope IS DISTINCT FROM expected_request
		OR receipt.request_digest IS DISTINCT FROM public.digest(
			pg_catalog.convert_to(expected_request::text,'UTF8'),'sha256'
		)
		OR receipt.effect_envelope IS DISTINCT FROM expected_effect
		OR receipt.response_bytes IS DISTINCT FROM expected_response
		OR receipt.completed_at IS NULL
	THEN
		RETURN false;
	END IF;

	SELECT pg_catalog.count(*) INTO linked_generation_count
	FROM decodex.process_generations AS linked
	WHERE (linked.quick_task_prepare_protocol,
		linked.quick_task_prepare_idempotency_key)=(
		receipt.protocol_version,receipt.idempotency_key
	);
	IF linked_generation_count<>1 THEN
		RETURN false;
	END IF;

	RETURN EXISTS (
		SELECT 1
		FROM decodex.process_generations AS generation
		JOIN decodex.process_generation_death_evidence AS death
			ON (death.evidence_id,death.generation_id)=(
				generation.death_evidence_id,generation.generation_id
			)
		JOIN decodex.process_generation_transitions AS starting_transition
			ON (starting_transition.generation_id,starting_transition.revision)=(
				generation.generation_id,1
			)
		JOIN decodex.process_generation_transitions AS unknown_transition
			ON (unknown_transition.generation_id,unknown_transition.revision)=(
				generation.generation_id,2
			)
		JOIN decodex.process_generation_transitions AS dead_transition
			ON (dead_transition.generation_id,dead_transition.revision)=(
				generation.generation_id,3
			)
		JOIN decodex.conversations AS conversation
			ON conversation.conversation_id=p_conversation_id
		JOIN decodex.runtime_sessions AS session
			ON (session.runtime_session_id,session.conversation_id)=(
				p_runtime_session_id,p_conversation_id
			)
		JOIN decodex.turns AS turn
			ON (turn.turn_id,turn.conversation_id,turn.runtime_session_id)=(
				p_turn_id,p_conversation_id,p_runtime_session_id
			)
		JOIN decodex.continuation_plans AS plan
			ON plan.plan_id=p_continuation_plan_id
		JOIN decodex.routing_decisions AS decision
			ON decision.decision_id=p_routing_decision_id
		JOIN decodex.account_snapshots AS account_snapshot
			ON account_snapshot.account_snapshot_id=session.account_snapshot_id
		WHERE generation.generation_id=p_process_generation_id
			AND (generation.quick_task_prepare_protocol,
				generation.quick_task_prepare_idempotency_key)=(
				receipt.protocol_version,receipt.idempotency_key
			)
			AND generation.account_id=p_selected_account_id
			AND generation.initial_account_revision=account_snapshot.source_revision
			AND generation.state='dead' AND generation.revision=3
			AND generation.authority_loss_reason IS NULL
			AND generation.bound_boot_id IS NULL
			AND generation.process_id IS NULL
			AND generation.process_start_id IS NULL
			AND generation.process_group_id IS NULL
			AND generation.session_id IS NULL
			AND generation.updated_at=death.observed_at
			AND death.generation_revision=1
			AND death.kind='spawn_not_created'
			AND death.observed_boot_id=generation.intended_boot_id
			AND death.process_id IS NULL AND death.process_start_id IS NULL
			AND death.process_group_id IS NULL AND death.session_id IS NULL
			AND death.witness_digest~'^[0-9a-f]{64}$'
			AND starting_transition.previous_state IS NULL
			AND starting_transition.state='starting'
			AND starting_transition.authority_loss_reason IS NULL
			AND starting_transition.death_evidence_id IS NULL
			AND starting_transition.transitioned_at=generation.created_at
			AND unknown_transition.previous_state='starting'
			AND unknown_transition.state='death_unknown'
			AND unknown_transition.authority_loss_reason='control_authority_lost'
			AND unknown_transition.death_evidence_id IS NULL
			AND unknown_transition.transitioned_at=death.observed_at
			AND dead_transition.previous_state='death_unknown'
			AND dead_transition.state='dead'
			AND dead_transition.authority_loss_reason IS NULL
			AND dead_transition.death_evidence_id=death.evidence_id
			AND dead_transition.transitioned_at=death.observed_at
			AND (
				SELECT pg_catalog.count(*)
				FROM decodex.process_generation_transitions AS transition
				WHERE transition.generation_id=generation.generation_id
			)=3
			AND (
				SELECT pg_catalog.count(*)
				FROM decodex.process_generation_death_evidence AS evidence
				WHERE evidence.generation_id=generation.generation_id
			)=1
			AND conversation.status='open'
			AND conversation.revision=p_expected_conversation_revision
			AND session.state='starting' AND session.revision=1
			AND session.codex_thread_id IS NULL
			AND session.last_known_turn_id IS NULL
			AND session.thread_start_request_id IS NULL
			AND session.thread_start_request_sha256 IS NULL
			AND session.thread_start_response_id IS NULL
			AND session.thread_start_response_sha256 IS NULL
			AND session.ended_at IS NULL AND session.updated_at=session.created_at
			AND turn.sequence=1 AND turn.role='user'
			AND turn.possible_side_effects='unknown'
			AND (
				turn.status='active' AND turn.revision=1
					AND turn.completed_at IS NULL
					AND turn.updated_at=turn.created_at
				OR turn.status='failed' AND turn.revision=2
					AND turn.completed_at IS NOT NULL
					AND turn.updated_at=turn.completed_at
			)
			AND plan.revision=1 AND plan.kind='initial_thread'
			AND plan.consumer_kind='conversation_turn'
			AND plan.consumer_conversation_id=p_conversation_id
			AND plan.conversation_id=p_conversation_id
			AND plan.conversation_revision=p_expected_conversation_revision
			AND plan.source_runtime_session_id=p_runtime_session_id
			AND plan.source_runtime_session_revision=1
			AND plan.turn_id=p_turn_id
			AND plan.routing_decision_id=p_routing_decision_id
			AND plan.selected_account_id=p_selected_account_id
			AND NOT plan.replay_permitted AND NOT plan.dispatch_enabled
			AND decision.authority_shape='conversation_account_registry'
			AND decision.kind='selected'
			AND decision.consumer_kind='conversation_turn'
			AND decision.conversation_id=p_conversation_id
			AND decision.conversation_revision=p_expected_conversation_revision
			AND decision.turn_id=p_turn_id
			AND decision.selected_account_id=p_selected_account_id
			AND account_snapshot.source_account_id=p_selected_account_id
			AND NOT EXISTS (
				SELECT 1 FROM decodex.provider_attempts AS attempt
				WHERE attempt.conversation_id=p_conversation_id
					OR attempt.turn_id=p_turn_id
					OR attempt.continuation_plan_id=p_continuation_plan_id
					OR attempt.routing_decision_id=p_routing_decision_id
					OR attempt.accepted_runtime_session_id=p_runtime_session_id
					OR attempt.process_generation_id=p_process_generation_id
			)
			AND NOT EXISTS (
				SELECT 1 FROM decodex.exact_command_receipts AS effect_receipt
				WHERE effect_receipt.receipt_state='completed_success'
					AND effect_receipt.request_envelope->>'operation' IN (
						'fence_runtime_session_thread_start',
						'bind_runtime_session_thread',
						'acknowledge_runtime_session_turn'
					)
					AND (
						effect_receipt.request_envelope->>'runtime_session_id'=
							p_runtime_session_id::text
						OR effect_receipt.request_envelope->>'turn_id'=p_turn_id::text
						OR effect_receipt.request_envelope->>'user_turn_id'=p_turn_id::text
						OR effect_receipt.request_envelope->>'process_generation_id'=
							p_process_generation_id::text
					)
			)
			AND NOT EXISTS (
				SELECT 1 FROM decodex.activity AS event
				WHERE event.aggregate_kind='runtime_session'
					AND event.aggregate_id=p_runtime_session_id::text
					AND event.event_kind IN (
						'runtime_session_thread_start_fenced',
						'runtime_session_thread_bound',
						'runtime_session_turn_acknowledged'
					)
			)
			AND NOT EXISTS (
				SELECT 1 FROM decodex.outbox AS effect
				WHERE effect.aggregate_kind='runtime_session'
					AND effect.aggregate_id=p_runtime_session_id::text
					AND effect.payload->>'event_kind' IN (
						'runtime_session_thread_start_fenced',
						'runtime_session_thread_bound',
						'runtime_session_turn_acknowledged'
					)
			)
			AND NOT EXISTS (
				SELECT 1 FROM decodex.history_items AS item
				WHERE item.conversation_id=p_conversation_id
					AND item.status='streaming'
			)
	);
END
$$;


--
-- Name: program_timestamp(bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.program_timestamp(value bigint) RETURNS timestamp with time zone
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT CASE WHEN value BETWEEN 0 AND 253402300799999999 THEN
		TIMESTAMPTZ 'epoch'
			+ (value / 1000000) * INTERVAL '1 second'
			+ (value % 1000000) * INTERVAL '1 microsecond'
	END
$$;


--
-- Name: project_process_generations_after_supervisor_loss_exact(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.project_process_generations_after_supervisor_loss_exact() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE changed bigint;
DECLARE now_value timestamptz;
BEGIN
	PERFORM pg_catalog.pg_advisory_xact_lock(1400);
	now_value := pg_catalog.clock_timestamp();
	UPDATE decodex.process_generations
	SET state = 'death_unknown',
		authority_loss_reason = 'supervisor_restarted',
		revision = revision + 1,
		updated_at = now_value
	WHERE state IN ('starting', 'ready', 'stopping');
	GET DIAGNOSTICS changed = ROW_COUNT;
	RETURN changed;
END;
$$;


--
-- Name: project_provider_attempts_after_supervisor_loss_exact(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.project_provider_attempts_after_supervisor_loss_exact() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE changed bigint;
DECLARE now_value timestamptz;
BEGIN
	-- The exclusive restore gate excludes both generation launch fencing and attempt
	-- preparation/dispatch authorization. A restored prepared row can be older than a later
	-- authorization, so restore projects it to unknown as an exceptional fail-closed view.
	PERFORM pg_catalog.pg_advisory_xact_lock(1400);
	now_value := pg_catalog.clock_timestamp();
	UPDATE decodex.provider_attempts
	SET state = 'unknown',
		unknown_reason = 'restore_projection',
		revision = revision + 1,
		updated_at = now_value
	WHERE state IN ('prepared', 'dispatch_authorized');
	GET DIAGNOSTICS changed = ROW_COUNT;
	RETURN changed;
END;
$$;


--
-- Name: prune_history_snapshots(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.prune_history_snapshots() RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE maintenance_time timestamptz := pg_catalog.clock_timestamp();
DECLARE removed_count bigint;
BEGIN
	PERFORM pg_catalog.pg_advisory_xact_lock(1272);
	DELETE FROM decodex.history_cursors WHERE expires_at <= maintenance_time;
	WITH obsolete AS (
		SELECT candidate.version_sequence
		FROM decodex.history_item_versions AS candidate
		WHERE NOT EXISTS (
			SELECT 1 FROM decodex.history_items AS current
			WHERE current.history_item_id = candidate.history_item_id
				AND current.revision = candidate.revision
		) AND NOT EXISTS (
			SELECT 1 FROM decodex.command_receipts AS receipt
			WHERE receipt.receipt_state = 'completed'
				AND receipt.response->>'kind' = 'history_item'
				AND receipt.response->>'history_item_id' = candidate.history_item_id::text
				AND (receipt.response->>'revision')::bigint = candidate.revision
		) AND NOT EXISTS (
			SELECT 1 FROM decodex.history_cursors AS cursor
			WHERE cursor.conversation_id = candidate.conversation_id
				AND cursor.expires_at > maintenance_time
				AND candidate.version_sequence = (
					SELECT max(snapshot.version_sequence)
					FROM decodex.history_item_versions AS snapshot
					WHERE snapshot.history_item_id = candidate.history_item_id
						AND snapshot.version_sequence <= cursor.snapshot_version_sequence
				)
		)
		ORDER BY candidate.version_sequence
		LIMIT 4096
	)
	DELETE FROM decodex.history_item_versions AS candidate
	USING obsolete
	WHERE candidate.version_sequence = obsolete.version_sequence;
	GET DIAGNOSTICS removed_count = ROW_COUNT;
	RETURN removed_count;
END;
$$;


--
-- Name: publish_routing_evidence_exact(text, text, uuid, uuid, bigint, bigint, decodex.role_profile_role, bigint, text, uuid, uuid, text, decodex.codex_capability[], decodex.capability_evidence_state[]); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.publish_routing_evidence_exact(p_protocol text, p_idempotency_key text, p_evidence_id uuid, p_account_id uuid, p_expected_account_revision bigint, p_expected_evidence_revision bigint, p_role decodex.role_profile_role, p_role_profile_revision bigint, p_build_id text, p_process_id uuid, p_process_account_id uuid, p_schema_fingerprint text, p_capabilities decodex.codex_capability[], p_states decodex.capability_evidence_state[]) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; replay bytea; next_revision bigint; core jsonb; effect jsonb; response bytea;
BEGIN
	request := pg_catalog.jsonb_build_object('operation','publish_routing_evidence',
		'protocol',p_protocol,'evidence_id',p_evidence_id,'account_id',p_account_id,
		'expected_account_revision',p_expected_account_revision,
		'expected_evidence_revision',p_expected_evidence_revision,'role',p_role,
		'role_profile_revision',p_role_profile_revision,'build_id',p_build_id,
		'process_id',p_process_id,'process_account_id',p_process_account_id,
		'schema_fingerprint',p_schema_fingerprint,'capabilities',p_capabilities,'states',p_states);
	replay := decodex.reserve_exact_routing_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(1356);
	LOCK TABLE decodex.accounts, decodex.role_profiles, decodex.role_profile_revisions,
		decodex.routing_compatibility_evidence, decodex.routing_capability_evidence IN SHARE MODE;
	IF p_evidence_id IS NULL OR p_account_id IS NULL OR p_role IS NULL
		OR p_build_id IS NULL OR p_process_id IS NULL OR p_process_account_id IS NULL
		OR p_schema_fingerprint IS NULL OR p_expected_account_revision<=0 OR p_role_profile_revision<=0
		OR p_expected_evidence_revision IS NOT NULL AND p_expected_evidence_revision<=0
		OR p_build_id COLLATE pg_catalog."C" !~ '^sha256:[0-9a-f]{64}$'
		OR p_schema_fingerprint COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$' THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'publish_routing_evidence','invalid_evidence');
	END IF;
	PERFORM 1 FROM decodex.accounts WHERE account_id=p_account_id
		AND revision=p_expected_account_revision FOR SHARE;
	IF NOT FOUND OR p_process_account_id <> p_account_id THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'publish_routing_evidence','account_provenance_mismatch');
	END IF;
	PERFORM 1 FROM decodex.role_profiles
		WHERE role=p_role AND current_revision=p_role_profile_revision FOR SHARE;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'publish_routing_evidence','role_profile_mismatch');
	END IF;
	PERFORM 1 FROM decodex.role_profile_revisions WHERE role=p_role
		AND revision=p_role_profile_revision FOR SHARE;
	IF NOT FOUND THEN RETURN decodex.complete_exact_routing_rejection(
		p_protocol,p_idempotency_key,'publish_routing_evidence','role_profile_mismatch'); END IF;
	IF p_capabilities IS NULL OR p_states IS NULL
		OR pg_catalog.array_position(p_capabilities,NULL) IS NOT NULL
		OR pg_catalog.array_position(p_states,NULL) IS NOT NULL
		OR pg_catalog.cardinality(p_capabilities) <> 8 OR pg_catalog.cardinality(p_states) <> 8
		OR p_capabilities <> ARRAY['initialize','account_read','thread_list','thread_read',
			'thread_archive','paginated_history','native_collaboration','thread_search']::decodex.codex_capability[]
	THEN RETURN decodex.complete_exact_routing_rejection(
		p_protocol,p_idempotency_key,'publish_routing_evidence','invalid_capability_projection'); END IF;
	IF EXISTS (SELECT 1 FROM decodex.routing_compatibility_evidence WHERE evidence_id=p_evidence_id) THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'publish_routing_evidence','duplicate_evidence_id');
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.routing_compatibility_evidence
		WHERE process_id=p_process_id) THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'publish_routing_evidence','duplicate_process_id');
	END IF;
	PERFORM 1 FROM decodex.routing_compatibility_evidence WHERE account_id=p_account_id
	ORDER BY evidence_revision FOR UPDATE;
	SELECT COALESCE(pg_catalog.max(evidence_revision),0)+1 INTO next_revision
	FROM decodex.routing_compatibility_evidence WHERE account_id=p_account_id;
	IF (next_revision=1 AND p_expected_evidence_revision IS NOT NULL)
		OR (next_revision>1 AND p_expected_evidence_revision IS DISTINCT FROM next_revision-1) THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'publish_routing_evidence','stale_evidence_revision');
	END IF;
	INSERT INTO decodex.routing_compatibility_evidence(
		evidence_id,account_id,account_revision,role,role_profile_revision,build_id,
		process_id,process_account_id,schema_fingerprint,evidence_revision
	) VALUES (p_evidence_id,p_account_id,p_expected_account_revision,p_role,p_role_profile_revision,
		p_build_id,p_process_id,p_process_account_id,p_schema_fingerprint,next_revision);
	INSERT INTO decodex.routing_capability_evidence
	SELECT p_evidence_id,ordinality::integer,capability,state
	FROM ROWS FROM (
		pg_catalog.unnest(p_capabilities), pg_catalog.unnest(p_states)
	) WITH ORDINALITY
		AS item(capability,state,ordinality);
	core := pg_catalog.jsonb_build_object('operation','publish_routing_evidence',
		'evidence_id',p_evidence_id,'account_id',p_account_id,'account_revision',p_expected_account_revision,
		'evidence_revision',next_revision,'role',p_role,'role_profile_revision',p_role_profile_revision,
		'build_id',p_build_id,'process_id',p_process_id,'schema_fingerprint',p_schema_fingerprint,
		'process_account_id',p_process_account_id,
		'capabilities',p_capabilities,'states',p_states,
		'ingested_at_micros',(SELECT
			(extract(epoch FROM ingested_at)*1000000)::bigint
			FROM decodex.routing_compatibility_evidence WHERE evidence_id=p_evidence_id));
	effect := core || pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(
		public.digest(pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response := pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$_$;


SET default_table_access_method = heap;

--
-- Name: account_operations; Type: TABLE; Schema: decodex; Owner: -
--

CREATE TABLE decodex.account_operations (
    operation_id uuid NOT NULL,
    account_id uuid NOT NULL,
    kind decodex.account_operation_kind NOT NULL,
    phase decodex.account_operation_phase DEFAULT 'prepared'::decodex.account_operation_phase NOT NULL,
    expected_account_revision bigint,
    expected_store_schema_version integer,
    expected_credential_version bigint,
    expected_credential_fingerprint text,
    expected_credential_writer_operation_id uuid,
    target_store_schema_version integer,
    target_credential_version bigint,
    target_credential_fingerprint text,
    target_credential_writer_operation_id uuid,
    provider_kind decodex.account_provider_kind NOT NULL,
    provider_account_id text NOT NULL,
    recovery_code text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    requested_display_label text,
    requested_enabled boolean,
    CONSTRAINT account_operations_expected_binding_shape CHECK ((((expected_store_schema_version IS NULL) AND (expected_credential_version IS NULL) AND (expected_credential_fingerprint IS NULL) AND (expected_credential_writer_operation_id IS NULL)) OR ((expected_store_schema_version = 1) AND (expected_credential_version > 0) AND (expected_credential_fingerprint ~ '^[0-9a-f]{64}$'::text) AND (expected_credential_writer_operation_id IS NOT NULL)))),
    CONSTRAINT account_operations_finite_times CHECK ((isfinite(created_at) AND isfinite(updated_at) AND ((completed_at IS NULL) OR isfinite(completed_at)))),
    CONSTRAINT account_operations_install_request_shape CHECK (((((kind = ANY (ARRAY['enroll'::decodex.account_operation_kind, 'import'::decodex.account_operation_kind])) AND (requested_display_label IS NOT NULL) AND (requested_enabled IS NOT NULL)) OR ((kind <> ALL (ARRAY['enroll'::decodex.account_operation_kind, 'import'::decodex.account_operation_kind])) AND (requested_display_label IS NULL) AND (requested_enabled IS NULL))) AND ((requested_display_label IS NULL) OR ((octet_length(requested_display_label) >= 1) AND (octet_length(requested_display_label) <= 128) AND (requested_display_label !~ '[[:cntrl:]]'::text) AND (NOT decodex.has_credential_material(requested_display_label)))))),
    CONSTRAINT account_operations_provider_shape CHECK (((octet_length(provider_account_id) >= 1) AND (octet_length(provider_account_id) <= 512) AND (provider_account_id !~ '[[:cntrl:]]'::text) AND (NOT decodex.has_credential_material(provider_account_id)))),
    CONSTRAINT account_operations_recovery_shape CHECK ((((phase = 'recovery_required'::decodex.account_operation_phase) = (recovery_code IS NOT NULL)) AND ((recovery_code IS NULL) OR (recovery_code ~ '^[a-z][a-z0-9_]{0,127}$'::text)))),
    CONSTRAINT account_operations_target_binding_shape CHECK ((((target_store_schema_version IS NULL) AND (target_credential_version IS NULL) AND (target_credential_fingerprint IS NULL) AND (target_credential_writer_operation_id IS NULL)) OR ((target_store_schema_version = 1) AND (target_credential_version > 0) AND (target_credential_fingerprint ~ '^[0-9a-f]{64}$'::text) AND (target_credential_writer_operation_id IS NOT NULL)))),
    CONSTRAINT account_operations_terminal_time CHECK (((completed_at IS NOT NULL) = (phase = ANY (ARRAY['committed'::decodex.account_operation_phase, 'cancelled'::decodex.account_operation_phase]))))
);


--
-- Name: read_account_operation_exact(uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_account_operation_exact(p_operation_id uuid) RETURNS SETOF decodex.account_operations
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT * FROM decodex.account_operations WHERE operation_id=p_operation_id
$$;


--
-- Name: read_account_profile_exact(uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_account_profile_exact(p_account_id uuid) RETURNS TABLE(account_id uuid, account_revision bigint, provider_kind decodex.account_provider_kind, provider_account_id text, observed_at_micros bigint, display_name text, username text, lifetime_tokens bigint, peak_daily_tokens bigint, longest_task_seconds bigint, current_streak_days integer, longest_streak_days integer, daily_start_dates text[], daily_tokens bigint[])
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT snapshot.account_id,snapshot.account_revision,snapshot.provider_kind,
		snapshot.provider_account_id,snapshot.observed_at_micros,snapshot.display_name,
		snapshot.username,snapshot.lifetime_tokens,snapshot.peak_daily_tokens,
		snapshot.longest_task_seconds,snapshot.current_streak_days,snapshot.longest_streak_days,
		COALESCE(
			pg_catalog.array_agg(
				pg_catalog.to_char(daily.start_date,'YYYY-MM-DD') ORDER BY daily.start_date
			)
				FILTER (WHERE daily.start_date IS NOT NULL),
			ARRAY[]::text[]
		),
		COALESCE(
			pg_catalog.array_agg(daily.tokens ORDER BY daily.start_date)
				FILTER (WHERE daily.start_date IS NOT NULL),
			ARRAY[]::bigint[]
		)
	FROM decodex.account_profile_snapshots AS snapshot
	JOIN decodex.accounts AS account ON account.account_id=snapshot.account_id
		AND account.tombstoned_at IS NULL
		AND account.revision=snapshot.account_revision
		AND account.provider_kind=snapshot.provider_kind
		AND account.provider_account_id=snapshot.provider_account_id
	LEFT JOIN decodex.account_profile_daily_usage AS daily
		ON daily.account_id=snapshot.account_id
	WHERE snapshot.account_id=p_account_id
	GROUP BY snapshot.account_id;
$$;


--
-- Name: read_account_registry_exact(uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_account_registry_exact(p_account_id uuid, p_limit bigint) RETURNS TABLE(account_id uuid, display_label text, enabled boolean, state decodex.account_state, revision bigint, provider_kind decodex.account_provider_kind, provider_account_id text, credential_store_schema_version integer, credential_version bigint, credential_fingerprint text, credential_writer_operation_id uuid, tombstoned boolean, lifecycle_readiness text, unsettled_operation_id uuid, unsettled_kind decodex.account_operation_kind, unsettled_phase decodex.account_operation_phase, unsettled_recovery_code text, five_hour_disposition text, five_hour_used_percent integer, five_hour_resets_at_micros bigint, five_hour_observed_at_micros bigint, five_hour_error_code decodex.account_quota_observation_error, seven_day_disposition text, seven_day_used_percent integer, seven_day_resets_at_micros bigint, seven_day_observed_at_micros bigint, seven_day_error_code decodex.account_quota_observation_error)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	BEGIN
	IF p_limit IS NULL OR p_limit < 1 OR p_limit > 512 THEN
		RAISE EXCEPTION 'account registry read limit is invalid' USING ERRCODE='22023';
	END IF;
	IF p_account_id IS NULL AND
		(SELECT pg_catalog.count(*) FROM decodex.accounts WHERE tombstoned_at IS NULL) > 512
	THEN
		RAISE EXCEPTION 'account registry cardinality exceeds the supported bound'
			USING ERRCODE='54000';
	END IF;
	RETURN QUERY
	SELECT account.account_id,account.display_label,account.enabled,account.state,account.revision,
		account.provider_kind,account.provider_account_id,
		account.credential_store_schema_version,account.credential_version,
		account.credential_fingerprint,account.credential_writer_operation_id,
		account.tombstoned_at IS NOT NULL,
		CASE
			WHEN account.tombstoned_at IS NOT NULL THEN 'tombstoned'
			WHEN operation.operation_id IS NOT NULL THEN 'operation_unsettled'
			WHEN account.credential_version IS NULL THEN 'credential_absent'
			WHEN NOT EXISTS (
				SELECT 1 FROM decodex.codex_account_capability AS capability
				WHERE capability.singleton
					AND capability.executable_sha256 ~ '^[0-9a-f]{64}$'
					AND capability.schema_sha256 ~ '^[0-9a-f]{64}$'
					AND capability.callback_profile_sha256 ~ '^[0-9a-f]{64}$'
					AND capability.login_chatgpt_auth_tokens AND capability.refresh_callback
			) THEN 'callback_capability_unready'
			WHEN account.credential_store_observation='exact' THEN 'ready'
			WHEN account.credential_store_observation='unavailable' THEN 'store_unavailable'
			WHEN account.credential_store_observation='provider_mismatch' THEN 'provider_mismatch'
			ELSE 'store_mismatch'
		END,
		operation.operation_id,operation.kind,operation.phase,operation.recovery_code,
		CASE WHEN five_hour.account_id IS NULL THEN 'unknown'
			WHEN five_hour.error_code IS NOT NULL THEN 'error'
			WHEN five_hour.resets_at_micros<=
				(extract(epoch FROM pg_catalog.clock_timestamp())*1000000)::bigint
				OR five_hour.observed_at_micros+300000000<
				(extract(epoch FROM pg_catalog.clock_timestamp())*1000000)::bigint
			THEN 'stale' ELSE 'current' END,
		five_hour.used_percent,
		five_hour.resets_at_micros,
		five_hour.observed_at_micros,
		five_hour.error_code,
		CASE WHEN seven_day.account_id IS NULL THEN 'unknown'
			WHEN seven_day.error_code IS NOT NULL THEN 'error'
			WHEN seven_day.resets_at_micros<=
				(extract(epoch FROM pg_catalog.clock_timestamp())*1000000)::bigint
				OR seven_day.observed_at_micros+300000000<
				(extract(epoch FROM pg_catalog.clock_timestamp())*1000000)::bigint
			THEN 'stale' ELSE 'current' END,
		seven_day.used_percent,
		seven_day.resets_at_micros,
		seven_day.observed_at_micros,
		seven_day.error_code
	FROM decodex.accounts AS account
	LEFT JOIN decodex.account_operations AS operation
		ON operation.account_id=account.account_id
		AND operation.phase NOT IN ('committed','cancelled')
	LEFT JOIN decodex.account_quota_facts AS five_hour
		ON five_hour.account_id=account.account_id AND five_hour.duration_minutes=300
	LEFT JOIN decodex.account_quota_facts AS seven_day
		ON seven_day.account_id=account.account_id AND seven_day.duration_minutes=10080
	LEFT JOIN decodex.account_routing_order AS ordering ON ordering.account_id=account.account_id
	WHERE (p_account_id IS NULL AND account.tombstoned_at IS NULL)
		OR account.account_id=p_account_id
	ORDER BY ordering.position NULLS LAST,account.account_id
	LIMIT p_limit;
END
$$;


--
-- Name: read_account_routing_control_exact(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_account_routing_control_exact() RETURNS TABLE(mode decodex.account_selection_mode, fixed_account_id uuid, revision bigint, account_order uuid[])
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	PERFORM decodex.lock_account_routing_universe_exact();
	RETURN QUERY SELECT control.mode,control.fixed_account_id,control.revision,
		COALESCE(pg_catalog.array_agg(ordering.account_id ORDER BY ordering.position)
			FILTER (WHERE ordering.account_id IS NOT NULL),'{}'::uuid[])
	FROM decodex.account_routing_control AS control
	LEFT JOIN decodex.account_routing_order AS ordering ON true
	WHERE control.singleton GROUP BY control.mode,control.fixed_account_id,control.revision;
END
$$;


--
-- Name: read_codex_experiment_start_exact(uuid, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_codex_experiment_start_exact(p_experiment_id uuid, p_attempt_id uuid) RETURNS TABLE(experiment_id uuid, attempt_id uuid, experiment_revision bigint, thread_id text, start_request_id bigint, start_request_digest text, request_cwd text, request_marker text, request_ephemeral boolean, start_response_id bigint, start_response_digest text, response_cwd text, response_marker text, response_ephemeral boolean, returned_name text, bound_at_micros bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT receipt.experiment_id,receipt.attempt_id,receipt.experiment_revision,
		receipt.thread_id,receipt.start_request_id,receipt.start_request_digest,
		receipt.request_cwd,receipt.request_marker,receipt.request_ephemeral,
		receipt.start_response_id,receipt.start_response_digest,
		receipt.response_cwd,receipt.response_marker,receipt.response_ephemeral,
		receipt.returned_name,
		(extract(epoch FROM receipt.bound_at)*1000000)::bigint
	FROM decodex.codex_experiment_start_receipts AS receipt
	WHERE receipt.experiment_id=p_experiment_id AND receipt.attempt_id=p_attempt_id
$$;


--
-- Name: read_continuation_plan_exact(uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_continuation_plan_exact(p_plan_id uuid, p_expected_revision bigint) RETURNS TABLE(response_bytes bytea, effect_envelope jsonb, kind text, codex_thread_id text, fallback_context_pack_id text, fallback_runtime_session_id text, replay_permitted boolean, dispatch_enabled boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT plan.response_bytes,plan.effect_envelope,plan.kind::text,plan.codex_thread_id::text,
		plan.fallback_context_pack_id::text,plan.fallback_runtime_session_id::text,
		plan.replay_permitted,plan.dispatch_enabled
	FROM decodex.continuation_plans AS plan
	WHERE plan.plan_id=p_plan_id AND plan.revision=p_expected_revision
$$;


-- Name: read_execution_decision_exact(uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_execution_decision_exact(p_decision_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	RETURN (
	SELECT CASE decision.authority_shape
	WHEN 'conversation_continuation' THEN
		pg_catalog.jsonb_build_object(
			'decision_id',decision.decision_id,
			'authority_shape',decision.authority_shape,
			'consumer_kind',decision.consumer_kind,
			'conversation_id',decision.conversation_id,
			'conversation_revision',decision.conversation_revision,
			'source_runtime_session_id',decision.source_runtime_session_id,
			'source_runtime_session_revision',
				decision.source_runtime_session_revision,
			'turn_id',decision.turn_id,
			'initial_decision_id',decision.initial_decision_id,
			'account_snapshot_id',decision.account_snapshot_id,
			'account_snapshot_source_revision',
				decision.account_snapshot_source_revision,
			'profile_snapshot_id',decision.profile_snapshot_id,
			'profile_snapshot_source_revision',
				decision.profile_snapshot_source_revision,
			'decided_at_micros',
				(extract(epoch FROM decision.decided_at)*1000000)::bigint
		)
	WHEN 'conversation_account_registry' THEN
		pg_catalog.jsonb_build_object(
			'decision_id',decision.decision_id,
			'authority_shape',decision.authority_shape,
			'snapshot_id',decision.snapshot_id,
			'account_routing_revision',decision.account_routing_revision,
			'consumer_kind',decision.consumer_kind,
			'conversation_id',decision.conversation_id,
			'conversation_revision',decision.conversation_revision,
			'source_runtime_session_id',NULL,
			'source_runtime_session_revision',NULL,
			'turn_id',decision.turn_id,
			'kind',decision.kind,
			'selected_account_id',decision.selected_account_id,
			'causes',(
				SELECT COALESCE(
					pg_catalog.jsonb_agg(
						pg_catalog.jsonb_build_object(
							'account_id',blocker.account_id,
							'blocker',blocker.blocker
						)
						ORDER BY member.position,blocker.position
					),
					'[]'::jsonb
				)
				FROM decodex.routing_decision_blocker_refs AS blocker
				JOIN decodex.routing_snapshot_members AS member
					ON member.snapshot_id=blocker.snapshot_id
					AND member.account_id=blocker.account_id
				WHERE blocker.decision_id=decision.decision_id
			),
			'quota_exclusions',(
				SELECT COALESCE(
					pg_catalog.jsonb_agg(
						pg_catalog.jsonb_build_object(
							'account_id',exclusion.account_id,
							'member_position',exclusion.member_position,
							'window_class',exclusion.window_class,
							'duration_minutes',exclusion.duration_minutes,
							'used_percent',exclusion.used_percent,
							'observed_at_micros',
								exclusion.observed_at_micros,
							'resets_at_micros',exclusion.resets_at_micros
						)
						ORDER BY exclusion.member_position,
							exclusion.window_class
					),
					'[]'::jsonb
				)
				FROM decodex.routing_decision_exclusions AS exclusion
				WHERE exclusion.decision_id=decision.decision_id
			),
			'decided_at_micros',
				(extract(epoch FROM decision.decided_at)*1000000)::bigint
		)
	ELSE
		pg_catalog.jsonb_build_object(
			'decision_id',decision.decision_id,
			'consumer_kind',decision.consumer_kind,
			'conversation_id',decision.conversation_id,
			'conversation_revision',decision.conversation_revision,
			'source_runtime_session_id',CASE
				WHEN decision.consumer_kind::text='conversation_turn'
					THEN snapshot.runtime_session_id
			END,
			'source_runtime_session_revision',CASE
				WHEN decision.consumer_kind::text='conversation_turn'
					THEN snapshot.runtime_session_revision
			END,
			'turn_id',decision.turn_id,
			'managed_run_id',decision.managed_run_id,
			'managed_run_revision',decision.managed_run_revision,
			'managed_execution_id',decision.managed_execution_id,
			'kind',decision.kind,
			'selected_account_id',decision.selected_account_id,
			'waiting_ready_at_micros',decision.waiting_ready_at_micros,
			'no_route_reason',decision.no_route_reason,
			'causes',CASE WHEN decision.kind::text='selected' THEN '[]'::jsonb
				ELSE (
					SELECT COALESCE(
						pg_catalog.jsonb_agg(
							pg_catalog.jsonb_build_object(
								'account_id',blocker.account_id,
								'blocker',blocker.blocker
							)
							ORDER BY member.position,blocker.position
						),
						'[]'::jsonb
					)
					FROM decodex.routing_decision_blocker_refs AS blocker
					JOIN decodex.routing_snapshot_members AS member
						ON member.snapshot_id=blocker.snapshot_id
						AND member.account_id=blocker.account_id
					WHERE blocker.decision_id=decision.decision_id
						AND (
							decision.kind::text='no_route'
							OR member.disposition='included'
						)
				) END,
			'quota_exclusions',(
				SELECT COALESCE(
					pg_catalog.jsonb_agg(
						pg_catalog.jsonb_build_object(
							'account_id',exclusion.account_id,
							'window_class',exclusion.window_class,
							'duration_minutes',exclusion.duration_minutes,
							'observation_revision',
								exclusion.observation_revision,
							'resets_at_micros',exclusion.resets_at_micros
						)
						ORDER BY exclusion.member_position,
							exclusion.window_class
					),
					'[]'::jsonb
				)
				FROM decodex.routing_decision_exclusions AS exclusion
				WHERE exclusion.decision_id=decision.decision_id
			)
		)
	END
	FROM decodex.routing_decisions AS decision
	LEFT JOIN decodex.routing_snapshots AS snapshot
		ON snapshot.snapshot_id=decision.snapshot_id
	WHERE decision.decision_id=p_decision_id
	);
END
$$;


--
-- Name: read_managed_run_execution_exact(uuid, uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_managed_run_execution_exact(p_managed_run_id uuid, p_project_id uuid, p_expected_revision bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT pg_catalog.jsonb_build_object(
		'managed_run_id',run.managed_run_id,'project_id',run.project_id,
		'work_item_id',run.work_item_id,'runtime_session_id',run.runtime_session_id,
		'runtime_session_revision',run.runtime_session_revision,
		'runtime_session_state',session.state,'lifecycle',run.lifecycle,'phase',run.phase,
		'wait_reason',run.wait_reason,'revision',run.revision,'diverged',run.diverged,
		'blocked',run.blocked,'created_at',run.created_at,'updated_at',run.updated_at,
		'assignments',COALESCE((
			SELECT pg_catalog.jsonb_agg(
				pg_catalog.jsonb_build_object(
					'runtime_session_id',assignment.runtime_session_id,
					'role',assignment.role
				)
				ORDER BY assignment.role
			)
			FROM decodex.managed_run_assignments AS assignment
			WHERE assignment.managed_run_id=run.managed_run_id
		),'[]'::jsonb),
		'provider_attempts',COALESCE((
			SELECT pg_catalog.jsonb_agg(
				pg_catalog.jsonb_build_object(
					'execution_id',attempt.managed_execution_id,
					'attempt_id',attempt.attempt_id,
					'process_generation_id',attempt.process_generation_id,
					'state',attempt.state,
					'revision',attempt.revision,
					'terminal_evidence_id',attempt.terminal_evidence_id,
					'unknown_reason',attempt.unknown_reason
				)
				ORDER BY attempt.managed_execution_id,attempt.attempt_id
			)
			FROM decodex.provider_attempts AS attempt
			WHERE attempt.consumer_kind='managed_run_execution'
				AND attempt.managed_run_id=run.managed_run_id
		),'[]'::jsonb)
	)
	FROM decodex.managed_runs AS run
	JOIN decodex.runtime_sessions AS session
		ON session.runtime_session_id=run.runtime_session_id
		AND session.revision=run.runtime_session_revision
	WHERE run.managed_run_id=p_managed_run_id
		AND run.project_id=p_project_id
		AND run.revision=p_expected_revision
$$;


--
-- Name: read_ordinary_runtime_session_for_resume_exact(uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_ordinary_runtime_session_for_resume_exact(p_conversation_id uuid) RETURNS TABLE(conversation_revision bigint, runtime_session_id uuid, runtime_session_revision bigint, codex_thread_id uuid, model text, reasoning_effort text, instructions text, source_account_id uuid, source_account_revision bigint, next_turn_sequence bigint, thread_start_request_id bigint, thread_start_request_sha256 text, thread_start_response_id bigint, thread_start_response_sha256 text, has_acknowledged_turn boolean, has_active_turn boolean, has_unresolved_provider_attempt boolean, conversation_status text, profile_role text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	WITH current_plan AS (
		SELECT plan.*,
			CASE plan.kind
				WHEN 'context_pack_fallback' THEN plan.fallback_runtime_session_id
				ELSE plan.source_runtime_session_id
			END AS current_runtime_session_id
		FROM decodex.continuation_plans AS plan
		WHERE plan.consumer_kind='conversation_turn'
			AND plan.conversation_id=p_conversation_id
		ORDER BY plan.planned_at DESC,plan.plan_id DESC
		LIMIT 1
	)
	SELECT conversation.revision,session.runtime_session_id,session.revision,
		session.codex_thread_id::uuid,profile.model,profile.reasoning_effort,
		profile.instructions,account.source_account_id,account.source_revision,
		COALESCE((
			SELECT pg_catalog.max(turn_row.sequence)
			FROM decodex.turns AS turn_row
			WHERE turn_row.conversation_id=conversation.conversation_id
		),0)+1,
		session.thread_start_request_id,session.thread_start_request_sha256,
		session.thread_start_response_id,session.thread_start_response_sha256,
		session.last_known_turn_id IS NOT NULL,
		EXISTS (
			SELECT 1 FROM decodex.turns AS active_turn
			WHERE active_turn.conversation_id=conversation.conversation_id
				AND active_turn.status='active'
		),
		EXISTS (
			SELECT 1 FROM decodex.provider_attempts AS attempt
			WHERE attempt.conversation_id=conversation.conversation_id
				AND attempt.accepted_runtime_session_id=session.runtime_session_id
				AND attempt.state IN ('prepared','dispatch_authorized','unknown')
		),
		conversation.status::text,profile.role::text
	FROM current_plan AS plan
	JOIN decodex.runtime_sessions AS session
		ON session.runtime_session_id=plan.current_runtime_session_id
	JOIN decodex.conversations AS conversation
		ON conversation.conversation_id=session.conversation_id
	JOIN decodex.profile_snapshots AS profile
		ON profile.profile_snapshot_id=session.profile_snapshot_id
	JOIN decodex.account_snapshots AS account
		ON account.account_snapshot_id=session.account_snapshot_id
	WHERE session.state='active' AND conversation.status='open'
		AND profile.role='task'
		AND NOT EXISTS (
			SELECT 1 FROM decodex.managed_runs AS managed
			WHERE managed.runtime_session_id=session.runtime_session_id
		)
$$;


--
-- Name: read_quick_task_request_exact(uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_quick_task_request_exact(p_conversation_id uuid) RETURNS TABLE(message text, working_directory text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT conversation.initial_quick_task_message,
		conversation.initial_quick_task_working_directory
	FROM decodex.conversations AS conversation
	WHERE conversation.conversation_id=p_conversation_id
		AND conversation.status='open'
		AND conversation.initial_quick_task_message IS NOT NULL
		AND conversation.initial_quick_task_working_directory IS NOT NULL
$$;


--
-- Name: read_ordinary_task_conversations_exact(uuid, bigint, uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_ordinary_task_conversations_exact(p_conversation_id uuid, p_after_updated_at_micros bigint, p_after_conversation_id uuid, p_limit bigint) RETURNS TABLE(conversation_id uuid, conversation_revision bigint, runtime_session_id uuid, runtime_session_revision bigint, runtime_session_state decodex.runtime_session_state, codex_thread_id uuid, thread_start_request_id bigint, thread_start_request_sha256 text, thread_start_response_id bigint, thread_start_response_sha256 text, has_acknowledged_turn boolean, active_user_turn_id uuid, active_user_turn_count bigint, has_active_provider_attempt boolean, has_unknown_provider_attempt boolean, pre_session_state text, routing_decision_id uuid, updated_at_micros bigint, routing_successor_conversation_id uuid, routing_successor_conversation_revision bigint, has_admitted_user_turn boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF p_limit IS NULL OR p_limit<1 OR p_limit>65
		OR (p_after_updated_at_micros IS NULL)<>(p_after_conversation_id IS NULL)
		OR p_after_updated_at_micros IS NOT NULL AND p_after_updated_at_micros<=0
		OR p_conversation_id IS NOT NULL AND p_after_updated_at_micros IS NOT NULL
	THEN
		RAISE EXCEPTION 'ordinary Task Conversation read bound is invalid'
			USING ERRCODE='22023';
	END IF;
	RETURN QUERY
	WITH projected AS (
		SELECT conversation.conversation_id,conversation.revision AS conversation_revision,
			session.runtime_session_id,session.revision AS runtime_session_revision,
			session.state AS runtime_session_state,session.codex_thread_id::uuid,
			session.thread_start_request_id,session.thread_start_request_sha256,
			session.thread_start_response_id,session.thread_start_response_sha256,
			COALESCE(session.last_known_turn_id IS NOT NULL,false) AS has_acknowledged_turn,
			CASE WHEN session.runtime_session_id IS NOT NULL THEN active_turn.turn_id END
				AS active_user_turn_id,
			CASE WHEN session.runtime_session_id IS NULL THEN 0
				ELSE COALESCE(active_turn.active_count,0) END AS active_user_turn_count,
			CASE WHEN session.runtime_session_id IS NULL THEN false
				ELSE COALESCE(active_turn.total_count,0)>0 END AS has_admitted_user_turn,
			COALESCE(attempt.has_active,false) AS has_active_provider_attempt,
			COALESCE(attempt.has_unknown,false) AS has_unknown_provider_attempt,
			CASE
				WHEN session.runtime_session_id IS NOT NULL THEN NULL
				WHEN decision.authority_shape='conversation_account_registry'
					AND decision.kind='selected' THEN 'establishment_pending'
				WHEN decision.authority_shape='conversation_account_registry'
					AND decision.kind='waiting' THEN 'quota_exhausted'
				WHEN decision.kind='no_route' THEN 'no_route'
				ELSE 'routing_pending'
			END AS pre_session_state,
			decision.decision_id AS routing_decision_id,
			(extract(epoch FROM greatest(
				conversation.updated_at,
				COALESCE(session.updated_at,conversation.updated_at),
				COALESCE(decision.decided_at,conversation.updated_at),
				COALESCE(plan.planned_at,conversation.updated_at),
				COALESCE(active_turn.updated_at,conversation.updated_at),
				COALESCE(attempt.updated_at,conversation.updated_at)
			))*1000000)::bigint AS updated_at_micros
		FROM decodex.conversations AS conversation
		LEFT JOIN LATERAL (
			SELECT stored.* FROM decodex.routing_decisions AS stored
			WHERE stored.consumer_kind='conversation_turn'
				AND stored.conversation_id=conversation.conversation_id
			ORDER BY stored.decided_at DESC,stored.decision_id DESC LIMIT 1
		) AS decision ON true
		LEFT JOIN LATERAL (
			SELECT stored.*,
				CASE stored.kind
					WHEN 'context_pack_fallback' THEN stored.fallback_runtime_session_id
					ELSE stored.source_runtime_session_id
				END AS current_runtime_session_id
			FROM decodex.continuation_plans AS stored
			WHERE stored.consumer_kind='conversation_turn'
				AND stored.conversation_id=conversation.conversation_id
			ORDER BY stored.planned_at DESC,stored.plan_id DESC LIMIT 1
		) AS plan ON true
		LEFT JOIN decodex.runtime_sessions AS session
			ON session.runtime_session_id=plan.current_runtime_session_id
		LEFT JOIN decodex.profile_snapshots AS profile
			ON profile.profile_snapshot_id=session.profile_snapshot_id
			LEFT JOIN LATERAL (
				SELECT latest.turn_id,aggregate.active_count,aggregate.total_count,
					aggregate.updated_at
				FROM (
					SELECT pg_catalog.count(*) FILTER (WHERE turn_row.status='active')
						AS active_count,
						pg_catalog.count(*) AS total_count,
						pg_catalog.max(turn_row.updated_at) AS updated_at
					FROM decodex.turns AS turn_row
					WHERE turn_row.conversation_id=conversation.conversation_id
						AND turn_row.runtime_session_id=session.runtime_session_id
						AND turn_row.role='user'
				) AS aggregate
			LEFT JOIN LATERAL (
				SELECT candidate.turn_id
				FROM decodex.turns AS candidate
				WHERE candidate.conversation_id=conversation.conversation_id
					AND candidate.runtime_session_id=session.runtime_session_id
					AND candidate.role='user' AND candidate.status='active'
				ORDER BY candidate.sequence DESC LIMIT 1
				) AS latest ON true
			) AS active_turn ON true
			LEFT JOIN LATERAL (
				SELECT pg_catalog.bool_or(stored.state IN ('prepared','dispatch_authorized'))
						AS has_active,
					pg_catalog.bool_or(stored.state='unknown') AS has_unknown,
					pg_catalog.max(stored.updated_at) AS updated_at
				FROM decodex.provider_attempts AS stored
				WHERE session.runtime_session_id IS NOT NULL
					AND stored.conversation_id=conversation.conversation_id
					AND stored.accepted_runtime_session_id=session.runtime_session_id
			) AS attempt ON true
		WHERE conversation.status='open'
			AND conversation.initial_quick_task_message IS NOT NULL
			AND conversation.initial_quick_task_working_directory IS NOT NULL
			AND (p_conversation_id IS NULL
				OR conversation.conversation_id=p_conversation_id)
			AND (
				session.runtime_session_id IS NULL
					OR profile.role='task'
			)
			AND (
				session.runtime_session_id IS NULL
				OR NOT EXISTS (
					SELECT 1 FROM decodex.managed_runs AS managed
					WHERE managed.runtime_session_id=session.runtime_session_id
				)
			)
			AND (
				decision.decision_id IS NULL
				OR decision.authority_shape='conversation_account_registry'
					AND EXISTS (
						SELECT 1 FROM decodex.routing_snapshots AS snapshot
						WHERE snapshot.snapshot_id=decision.snapshot_id
							AND snapshot.authority_shape=
								'conversation_account_registry'
							AND snapshot.task_role='task'
					)
				OR decision.authority_shape='conversation_continuation'
					AND EXISTS (
						SELECT 1
						FROM decodex.routing_decisions AS initial
						JOIN decodex.routing_snapshots AS snapshot
							ON snapshot.snapshot_id=initial.snapshot_id
						WHERE initial.decision_id=decision.initial_decision_id
							AND initial.authority_shape=
								'conversation_account_registry'
							AND snapshot.authority_shape=
								'conversation_account_registry'
							AND snapshot.task_role='task'
					)
			)
	), current_page AS (
	SELECT projected.*
	FROM projected
	WHERE p_after_updated_at_micros IS NULL
		OR (projected.updated_at_micros,projected.conversation_id)<
			(p_after_updated_at_micros,p_after_conversation_id)
	ORDER BY projected.updated_at_micros DESC,projected.conversation_id DESC
	LIMIT p_limit
	), combined AS (
		SELECT current_page.conversation_id,current_page.conversation_revision,
		current_page.runtime_session_id,current_page.runtime_session_revision,
		current_page.runtime_session_state,current_page.codex_thread_id,
		current_page.thread_start_request_id,current_page.thread_start_request_sha256,
		current_page.thread_start_response_id,current_page.thread_start_response_sha256,
		current_page.has_acknowledged_turn,current_page.active_user_turn_id,
		current_page.active_user_turn_count,current_page.has_active_provider_attempt,
		current_page.has_unknown_provider_attempt,current_page.pre_session_state,
			current_page.routing_decision_id,current_page.updated_at_micros,
			NULL::uuid AS routing_successor_conversation_id,
			NULL::bigint AS routing_successor_conversation_revision,
			current_page.has_admitted_user_turn
	FROM current_page
	UNION ALL
	SELECT source.conversation_id,source.revision,
		NULL::uuid,NULL::bigint,NULL::decodex.runtime_session_state,NULL::uuid,
		NULL::bigint,NULL::text,NULL::bigint,NULL::text,
			false,NULL::uuid,0::bigint,false,false,NULL::text,NULL::uuid,
			(extract(epoch FROM source.updated_at)*1000000)::bigint,
			relation.successor_conversation_id,relation.successor_revision,false
	FROM decodex.conversation_routing_successors AS relation
	JOIN decodex.conversations AS source
		ON source.conversation_id=relation.source_conversation_id
	JOIN decodex.conversations AS successor
		ON successor.conversation_id=relation.successor_conversation_id
	WHERE p_conversation_id IS NOT NULL
		AND relation.source_conversation_id=p_conversation_id
		AND source.status='archived' AND source.revision=relation.source_revision
		AND successor.status='open' AND successor.revision=relation.successor_revision
	)
	SELECT combined.conversation_id,combined.conversation_revision,
		combined.runtime_session_id,combined.runtime_session_revision,
		combined.runtime_session_state,combined.codex_thread_id,
		combined.thread_start_request_id,combined.thread_start_request_sha256,
		combined.thread_start_response_id,combined.thread_start_response_sha256,
		combined.has_acknowledged_turn,combined.active_user_turn_id,
		combined.active_user_turn_count,combined.has_active_provider_attempt,
		combined.has_unknown_provider_attempt,combined.pre_session_state,
		combined.routing_decision_id,combined.updated_at_micros,
			combined.routing_successor_conversation_id,
			combined.routing_successor_conversation_revision,
			combined.has_admitted_user_turn
	FROM combined
	ORDER BY combined.updated_at_micros DESC,combined.conversation_id DESC
	LIMIT p_limit;
END
$$;


--
-- Name: read_process_generations_exact(uuid, boolean, uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_process_generations_exact(p_account_id uuid, p_include_dead boolean, p_after_generation_id uuid, p_limit bigint) RETURNS TABLE(generation_id uuid, account_id uuid, execution_epoch_id uuid, runner_identity text, intended_boot_id text, control_kind decodex.process_generation_control_kind, isolation_kind decodex.process_generation_isolation_kind, bound_boot_id text, process_id bigint, process_start_id text, process_group_id bigint, session_id bigint, state decodex.process_generation_state, revision bigint, authority_loss_reason decodex.process_generation_loss_reason, death_evidence_id uuid, created_at_micros bigint, updated_at_micros bigint, initial_account_revision bigint, credential_store_schema_version integer, credential_version bigint, credential_fingerprint text, credential_writer_operation_id uuid, provider_kind decodex.account_provider_kind, provider_account_id text, refresh_callback_profile_sha256 text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF p_limit IS NULL OR p_limit<1 OR p_limit>256 THEN
		RAISE EXCEPTION 'process generation read limit is invalid' USING ERRCODE='22023';
	END IF;
	RETURN QUERY SELECT generation.generation_id,generation.account_id,
		generation.execution_epoch_id,generation.runner_identity,generation.intended_boot_id,
		generation.control_kind,generation.isolation_kind,generation.bound_boot_id,
		generation.process_id,generation.process_start_id,generation.process_group_id,
		generation.session_id,generation.state,generation.revision,
		generation.authority_loss_reason,generation.death_evidence_id,
		(extract(epoch FROM generation.created_at)*1000000)::bigint,
		(extract(epoch FROM generation.updated_at)*1000000)::bigint,
		generation.initial_account_revision,generation.credential_store_schema_version,
		generation.credential_version,generation.credential_fingerprint,
		generation.credential_writer_operation_id,
		generation.provider_kind,generation.provider_account_id,
		generation.refresh_callback_profile_sha256
	FROM decodex.process_generations AS generation
	WHERE (p_account_id IS NULL OR generation.account_id=p_account_id)
		AND (p_include_dead OR generation.state<>'dead')
		AND (p_after_generation_id IS NULL OR generation.generation_id>p_after_generation_id)
	ORDER BY generation.generation_id LIMIT p_limit;
END
$$;


--
-- Name: read_provider_attempts_exact(uuid, uuid, decodex.provider_attempt_state, uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_provider_attempts_exact(p_attempt_id uuid, p_account_id uuid, p_state decodex.provider_attempt_state, p_after_attempt_id uuid, p_limit bigint) RETURNS TABLE(attempt_id uuid, consumer_kind decodex.provider_attempt_consumer_kind, conversation_id uuid, turn_id uuid, managed_run_id uuid, managed_run_revision bigint, managed_execution_id uuid, continuation_plan_id uuid, routing_decision_id uuid, accepted_runtime_session_id uuid, accepted_runtime_session_revision bigint, selected_account_id uuid, process_generation_id uuid, process_generation_revision bigint, process_execution_epoch_id uuid, request_id uuid, request_digest text, provider_idempotency_key text, provider_correlation_key text, predecessor_attempt_id uuid, duplicate_risk_ack_digest text, state decodex.provider_attempt_state, unknown_reason decodex.provider_attempt_unknown_reason, terminal_evidence_id uuid, revision bigint, created_at_micros bigint, updated_at_micros bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF p_limit IS NULL OR p_limit < 1 OR p_limit > 256 THEN
		RAISE EXCEPTION 'provider attempt read limit is invalid'
			USING ERRCODE='22023';
	END IF;
	RETURN QUERY
	SELECT
		attempt.attempt_id,
		attempt.consumer_kind,
		attempt.conversation_id,
		attempt.turn_id,
		attempt.managed_run_id,
		attempt.managed_run_revision,
		attempt.managed_execution_id,
		attempt.continuation_plan_id,
		attempt.routing_decision_id,
		attempt.accepted_runtime_session_id,
		attempt.accepted_runtime_session_revision,
		attempt.selected_account_id,
		attempt.process_generation_id,
		attempt.process_generation_revision,
		attempt.process_execution_epoch_id,
		attempt.request_id,
		attempt.request_digest,
		attempt.provider_idempotency_key,
		attempt.provider_correlation_key,
		attempt.predecessor_attempt_id,
		attempt.duplicate_risk_ack_digest,
		attempt.state,
		attempt.unknown_reason,
		attempt.terminal_evidence_id,
		attempt.revision,
		(extract(epoch FROM attempt.created_at)*1000000)::bigint,
		(extract(epoch FROM attempt.updated_at)*1000000)::bigint
	FROM decodex.provider_attempts AS attempt
	WHERE (p_attempt_id IS NULL OR attempt.attempt_id = p_attempt_id)
		AND (p_account_id IS NULL OR attempt.selected_account_id = p_account_id)
		AND (p_state IS NULL OR attempt.state = p_state)
		AND (p_after_attempt_id IS NULL OR attempt.attempt_id > p_after_attempt_id)
	ORDER BY attempt.attempt_id
	LIMIT p_limit;
END;
$$;


--
-- Name: read_quick_task_thread_establishment_exact(uuid, bigint, uuid, bigint, uuid, bigint, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_quick_task_thread_establishment_exact(p_conversation_id uuid, p_expected_conversation_revision bigint, p_runtime_session_id uuid, p_expected_runtime_session_revision bigint, p_turn_id uuid, p_expected_turn_revision bigint, p_continuation_plan_id uuid, p_routing_decision_id uuid, p_selected_account_id uuid, p_process_generation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE base jsonb; result jsonb;
DECLARE turn_state text:='missing';
DECLARE fence decodex.exact_command_receipts%ROWTYPE;
DECLARE binding decodex.exact_command_receipts%ROWTYPE;
DECLARE generation decodex.process_generations%ROWTYPE;
DECLARE death decodex.process_generation_death_evidence%ROWTYPE;
DECLARE session_row decodex.runtime_sessions%ROWTYPE;
BEGIN
	SELECT status::text INTO turn_state FROM decodex.turns WHERE turn_id=p_turn_id;
	turn_state:=COALESCE(turn_state,'missing');
	base:=pg_catalog.jsonb_build_object(
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'baseline_runtime_session_revision',p_expected_runtime_session_revision,
		'turn_id',p_turn_id,'turn_revision',p_expected_turn_revision,
		'turn_state',turn_state,'continuation_plan_id',p_continuation_plan_id,
		'routing_decision_id',p_routing_decision_id,
		'selected_account_id',p_selected_account_id,
		'process_generation_id',p_process_generation_id
	);
	IF p_conversation_id IS NULL OR p_runtime_session_id IS NULL OR p_turn_id IS NULL
		OR p_continuation_plan_id IS NULL OR p_routing_decision_id IS NULL
		OR p_selected_account_id IS NULL OR p_process_generation_id IS NULL
		OR p_expected_conversation_revision<=0
		OR p_expected_runtime_session_revision<=0 OR p_expected_turn_revision<>1
	THEN
		RETURN base||pg_catalog.jsonb_build_object('disposition','unknown');
	END IF;

	SELECT * INTO binding FROM decodex.exact_command_receipts AS receipt
	WHERE receipt.receipt_state='completed_success'
		AND receipt.request_envelope->>'operation'='bind_runtime_session_thread'
		AND receipt.request_envelope->>'conversation_id'=p_conversation_id::text
		AND receipt.request_envelope->>'expected_conversation_revision'=
			p_expected_conversation_revision::text
		AND receipt.request_envelope->>'runtime_session_id'=p_runtime_session_id::text
		AND receipt.request_envelope->>'expected_revision'=
			(p_expected_runtime_session_revision+1)::text
		AND receipt.request_envelope->>'turn_id'=p_turn_id::text
		AND receipt.request_envelope->>'expected_turn_revision'=p_expected_turn_revision::text
		AND receipt.request_envelope->>'continuation_plan_id'=p_continuation_plan_id::text
	ORDER BY receipt.completed_at DESC,receipt.idempotency_key LIMIT 1;
	IF binding.protocol_version IS NOT NULL THEN
		SELECT * INTO fence FROM decodex.exact_command_receipts
		WHERE protocol_version=binding.request_envelope->>'fence_protocol'
			AND idempotency_key=binding.request_envelope->>'fence_idempotency_key';
		SELECT * INTO session_row FROM decodex.runtime_sessions
		WHERE runtime_session_id=p_runtime_session_id;
		IF fence.receipt_state='completed_success'
			AND fence.request_envelope->>'operation'='fence_runtime_session_thread_start'
			AND fence.request_envelope->>'conversation_id'=p_conversation_id::text
			AND fence.request_envelope->>'expected_conversation_revision'=
				p_expected_conversation_revision::text
			AND fence.request_envelope->>'runtime_session_id'=p_runtime_session_id::text
			AND fence.request_envelope->>'expected_revision'=
				p_expected_runtime_session_revision::text
			AND fence.request_envelope->>'turn_id'=p_turn_id::text
			AND fence.request_envelope->>'expected_turn_revision'=
				p_expected_turn_revision::text
			AND fence.request_envelope->>'continuation_plan_id'=
				p_continuation_plan_id::text
			AND fence.request_envelope->>'process_generation_id'=
				p_process_generation_id::text
			AND session_row.state='active'
			AND session_row.revision=p_expected_runtime_session_revision+2
			AND session_row.codex_thread_id::text=
				binding.request_envelope->>'codex_thread_id'
			AND session_row.thread_start_request_id::text=
				fence.request_envelope->>'thread_start_request_id'
			AND session_row.thread_start_request_sha256=
				fence.request_envelope->>'thread_start_request_sha256'
			AND session_row.thread_start_response_id::text=
				binding.request_envelope->>'thread_start_response_id'
			AND session_row.thread_start_response_sha256=
				binding.request_envelope->>'thread_start_response_sha256'
		THEN
			RETURN base||pg_catalog.jsonb_build_object(
				'disposition','bound',
				'runtime_session_revision',session_row.revision,
				'fence_revision',p_expected_runtime_session_revision+1,
				'fence_idempotency_key',fence.idempotency_key,
				'binding_idempotency_key',binding.idempotency_key,
				'process_generation_revision',
					(fence.effect_envelope->>'process_generation_revision')::bigint,
				'process_execution_epoch_id',
					fence.effect_envelope->>'process_execution_epoch_id',
				'thread_start_request_id',session_row.thread_start_request_id,
				'thread_start_request_sha256',session_row.thread_start_request_sha256,
				'thread_start_response_id',session_row.thread_start_response_id,
				'thread_start_response_sha256',session_row.thread_start_response_sha256,
				'codex_thread_id',session_row.codex_thread_id,
				'fence_activity_sequence',
					(fence.effect_envelope->>'activity_sequence')::bigint,
				'fence_outbox_id',(fence.effect_envelope->>'outbox_id')::bigint,
				'binding_activity_sequence',
					(binding.effect_envelope->>'activity_sequence')::bigint,
				'binding_outbox_id',(binding.effect_envelope->>'outbox_id')::bigint
			);
		END IF;
	END IF;

	SELECT * INTO fence FROM decodex.exact_command_receipts AS receipt
	WHERE receipt.receipt_state='completed_success'
		AND receipt.request_envelope->>'operation'='fence_runtime_session_thread_start'
		AND receipt.request_envelope->>'conversation_id'=p_conversation_id::text
		AND receipt.request_envelope->>'expected_conversation_revision'=
			p_expected_conversation_revision::text
		AND receipt.request_envelope->>'runtime_session_id'=p_runtime_session_id::text
		AND receipt.request_envelope->>'expected_revision'=
			p_expected_runtime_session_revision::text
		AND receipt.request_envelope->>'turn_id'=p_turn_id::text
		AND receipt.request_envelope->>'expected_turn_revision'=p_expected_turn_revision::text
		AND receipt.request_envelope->>'continuation_plan_id'=p_continuation_plan_id::text
		AND receipt.request_envelope->>'process_generation_id'=p_process_generation_id::text
	ORDER BY receipt.completed_at DESC,receipt.idempotency_key LIMIT 1;
	IF fence.protocol_version IS NOT NULL THEN
		SELECT * INTO session_row FROM decodex.runtime_sessions
		WHERE runtime_session_id=p_runtime_session_id;
		IF session_row.state='starting'
			AND session_row.revision=p_expected_runtime_session_revision+1
			AND session_row.thread_start_request_id::text=
				fence.request_envelope->>'thread_start_request_id'
			AND session_row.thread_start_request_sha256=
				fence.request_envelope->>'thread_start_request_sha256'
		THEN
			RETURN base||pg_catalog.jsonb_build_object(
				'disposition','fenced',
				'fence_revision',session_row.revision,
				'fence_idempotency_key',fence.idempotency_key,
				'process_generation_revision',
					(fence.effect_envelope->>'process_generation_revision')::bigint,
				'process_execution_epoch_id',
					fence.effect_envelope->>'process_execution_epoch_id',
				'thread_start_request_id',session_row.thread_start_request_id,
				'thread_start_request_sha256',session_row.thread_start_request_sha256,
				'fence_activity_sequence',
					(fence.effect_envelope->>'activity_sequence')::bigint,
				'fence_outbox_id',(fence.effect_envelope->>'outbox_id')::bigint
			);
		END IF;
	END IF;

	IF decodex.prove_initial_quick_task_spawn_not_created_exact(
		p_conversation_id,p_expected_conversation_revision,
		p_runtime_session_id,p_expected_runtime_session_revision,
		p_turn_id,p_expected_turn_revision,p_continuation_plan_id,
		p_routing_decision_id,p_selected_account_id,p_process_generation_id
	) THEN
		SELECT * INTO generation FROM decodex.process_generations
		WHERE generation_id=p_process_generation_id;
		SELECT * INTO death FROM decodex.process_generation_death_evidence
		WHERE evidence_id=generation.death_evidence_id;
		RETURN base||pg_catalog.jsonb_build_object(
			'disposition','definitely_not_started',
			'non_effect_kind','spawn_not_created',
			'non_effect_evidence_id',death.evidence_id,
			'process_generation_revision',generation.revision
		);
	END IF;
	RETURN base||pg_catalog.jsonb_build_object('disposition','unknown');
END
$$;


--
-- Name: read_reset_card_account_admission_exact(uuid, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_reset_card_account_admission_exact(p_account_id uuid, p_callback_profile_sha256 text) RETURNS TABLE(state decodex.account_state, revision bigint, enabled boolean, tombstoned boolean, credential_store_schema_version integer, credential_version bigint, credential_fingerprint text, credential_writer_operation_id uuid, provider_kind decodex.account_provider_kind, provider_account_id text, credential_store_observation decodex.account_store_observation, operation_unsettled boolean, callback_profile_ready boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
BEGIN
	RETURN QUERY SELECT account.state,account.revision,account.enabled,
		account.tombstoned_at IS NOT NULL,account.credential_store_schema_version,
		account.credential_version,account.credential_fingerprint,
		account.credential_writer_operation_id,account.provider_kind,
		account.provider_account_id,account.credential_store_observation,
		EXISTS (
			SELECT 1 FROM decodex.account_operations AS operation
			WHERE operation.account_id=account.account_id
				AND operation.phase NOT IN ('committed','cancelled')
		),
		EXISTS (
			SELECT 1 FROM decodex.codex_account_capability AS capability
			WHERE capability.singleton
				AND capability.executable_sha256 ~ '^[0-9a-f]{64}$'
				AND capability.schema_sha256 ~ '^[0-9a-f]{64}$'
				AND capability.callback_profile_sha256 ~ '^[0-9a-f]{64}$'
				AND capability.login_chatgpt_auth_tokens
				AND capability.refresh_callback
				AND capability.callback_profile_sha256=p_callback_profile_sha256
		)
	FROM decodex.accounts AS account
	WHERE account.account_id=p_account_id
	FOR SHARE OF account;
END
$_$;


--
-- Name: read_turn_admission_exact(uuid, uuid, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_turn_admission_exact(p_conversation_id uuid, p_runtime_session_id uuid, p_turn_id uuid) RETURNS TABLE(conversation_id uuid, runtime_session_id uuid, turn_id uuid, sequence bigint, role decodex.turn_role, possible_side_effects decodex.side_effect_state, status decodex.turn_status, revision bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE turn_row decodex.turns%ROWTYPE;
BEGIN
	IF p_conversation_id IS NULL OR p_runtime_session_id IS NULL OR p_turn_id IS NULL THEN
		RAISE EXCEPTION 'Turn admission identity is invalid' USING ERRCODE='22023';
	END IF;
	SELECT * INTO turn_row
	FROM decodex.turns AS candidate
	WHERE candidate.turn_id=p_turn_id;
	IF NOT FOUND THEN
		RETURN;
	END IF;
	IF turn_row.conversation_id<>p_conversation_id
		OR turn_row.runtime_session_id<>p_runtime_session_id
		OR turn_row.role<>'user'::decodex.turn_role
		OR turn_row.possible_side_effects<>'unknown'::decodex.side_effect_state
	THEN
		RAISE EXCEPTION 'Turn admission is cross-linked' USING ERRCODE='55000';
	END IF;
	RETURN QUERY SELECT
		turn_row.conversation_id,turn_row.runtime_session_id,turn_row.turn_id,
		turn_row.sequence,turn_row.role,turn_row.possible_side_effects,
		turn_row.status,turn_row.revision;
END
$$;


--
-- Name: read_unsettled_account_operations_exact(bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_unsettled_account_operations_exact(p_limit bigint) RETURNS SETOF decodex.account_operations
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	IF p_limit IS NULL OR p_limit < 1 OR p_limit > 512 THEN
		RAISE EXCEPTION 'account operation read limit is invalid' USING ERRCODE='22023';
	END IF;
	RETURN QUERY SELECT * FROM decodex.account_operations
	WHERE phase NOT IN ('committed','cancelled')
	ORDER BY operation_id LIMIT p_limit;
END
$$;


--
-- Name: read_waiting_usage_wake_transition_exact(uuid, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_waiting_usage_wake_transition_exact(p_transition_id uuid, p_operation_id uuid) RETURNS TABLE(transition_id text, wake_id text, revision bigint, predecessor_revision bigint, predecessor_transition_id text, operation_id text, transition_kind text, registration_operation_id text, routing_decision_id text, routing_decision_revision bigint, routing_policy_id text, routing_policy_revision bigint, managed_run_id text, managed_run_revision bigint, earliest_ready_at_micros bigint, state text, claim_id text, lease_holder text, lease_fence_id text, lease_acquired_at_micros bigint, lease_expires_at_micros bigint, registered_at_micros bigint, transitioned_at_micros bigint, terminal_reason text, routing_resolution_request_id text, fresh_routing_resolution_only boolean, prior_decision_reusable boolean, production_enabled boolean, effect_envelope jsonb, response_bytes bytea)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT transition.transition_id::text,transition.wake_id::text,transition.revision,
		transition.predecessor_revision,transition.predecessor_transition_id::text,
		transition.operation_id::text,transition.transition_kind::text,
		transition.registration_operation_id::text,transition.routing_decision_id::text,
		transition.routing_decision_revision,transition.routing_policy_id::text,
		transition.routing_policy_revision,transition.managed_run_id::text,
		transition.managed_run_revision,transition.earliest_ready_at_micros,
		transition.state::text,transition.claim_id::text,transition.lease_holder::text,
		transition.lease_fence_id::text,
		CASE WHEN transition.lease_acquired_at IS NULL THEN NULL ELSE
			(extract(epoch FROM transition.lease_acquired_at)*1000000)::bigint END,
		CASE WHEN transition.lease_expires_at IS NULL THEN NULL ELSE
			(extract(epoch FROM transition.lease_expires_at)*1000000)::bigint END,
		(extract(epoch FROM transition.registered_at)*1000000)::bigint,
		(extract(epoch FROM transition.transitioned_at)*1000000)::bigint,
		transition.terminal_reason::text,transition.routing_resolution_request_id::text,
		transition.fresh_routing_resolution_only,transition.prior_decision_reusable,
		transition.production_enabled,transition.effect_envelope,transition.response_bytes
	FROM decodex.waiting_usage_wake_transitions AS transition
	WHERE transition.transition_id=p_transition_id AND transition.operation_id=p_operation_id
$$;


--
-- Name: reconcile_quick_task_terminalizations_exact(integer); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.reconcile_quick_task_terminalizations_exact(p_limit integer) RETURNS TABLE(terminalized_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE candidate record; outcome record; changed bigint:=0;
BEGIN
	IF p_limit IS NULL OR p_limit<1 OR p_limit>256 THEN
		RAISE EXCEPTION 'Quick Task terminalization bound is invalid' USING ERRCODE='22023';
	END IF;
	FOR candidate IN
		SELECT attempt.*,conversation.revision AS conversation_revision,
			session.revision AS session_revision,evidence.evidence_id,
			evidence.outcome,evidence.provider_thread_id,evidence.provider_turn_id,
			user_turn.revision AS user_turn_revision,
			assistant.turn_id AS assistant_turn_id,
			assistant.revision AS assistant_turn_revision
		FROM decodex.provider_attempts AS attempt
		JOIN decodex.provider_attempt_positive_evidence AS evidence
			ON evidence.evidence_id=attempt.terminal_evidence_id
		JOIN decodex.conversations AS conversation
			ON conversation.conversation_id=attempt.conversation_id
		JOIN decodex.runtime_sessions AS session
			ON session.runtime_session_id=attempt.accepted_runtime_session_id
		JOIN decodex.turns AS user_turn ON user_turn.turn_id=attempt.turn_id
		LEFT JOIN decodex.turns AS assistant
			ON assistant.conversation_id=attempt.conversation_id
			AND assistant.sequence=user_turn.sequence+1 AND assistant.role='assistant'
		WHERE attempt.consumer_kind='conversation_turn'
			AND attempt.state IN ('succeeded','failed_definitive')
			AND conversation.status='open' AND session.state='active'
			AND session.revision=attempt.accepted_runtime_session_revision
			AND user_turn.status='active' AND user_turn.revision=1
			AND user_turn.possible_side_effects='unknown'
			AND (
				assistant.turn_id IS NULL
				OR assistant.status='active' AND assistant.revision=1
					AND assistant.possible_side_effects='unknown'
			)
			AND evidence.outcome::text=attempt.state::text
			AND evidence.provider_thread_id COLLATE pg_catalog."C" ~
				'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
			AND evidence.provider_turn_id COLLATE pg_catalog."C" ~
				'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
		ORDER BY evidence.observed_at,attempt.attempt_id
		LIMIT p_limit
		FOR UPDATE OF attempt SKIP LOCKED
	LOOP
		SELECT * INTO outcome FROM decodex.terminalize_quick_task_turn_exact(
			'decodex/exact-command/1',
			'quick-task-terminalization-reconcile/'||candidate.attempt_id::text,
			candidate.conversation_id,candidate.conversation_revision,
			candidate.accepted_runtime_session_id,candidate.session_revision,
			candidate.turn_id,candidate.user_turn_revision,
			candidate.assistant_turn_id,candidate.assistant_turn_revision,
			candidate.attempt_id,candidate.revision,candidate.evidence_id,
			candidate.outcome,candidate.provider_thread_id::uuid,
			candidate.provider_turn_id
		);
		IF outcome.result_code IN ('applied','replayed') THEN
			changed:=changed+1;
		END IF;
	END LOOP;
	RETURN QUERY SELECT changed;
END
$_$;


--
-- Name: record_attested_codex_experiment_observation_exact(text, text, uuid, bigint, uuid, uuid, decodex.codex_experiment_observation_kind, text, text, text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.record_attested_codex_experiment_observation_exact(p_protocol text, p_idempotency_key text, p_experiment_id uuid, p_expected_revision bigint, p_attestation_id uuid, p_observation_id uuid, p_kind decodex.codex_experiment_observation_kind, p_thread_id text, p_marker text, p_source_id text, p_fact_digest text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; replay bytea; observed timestamptz; experiment_row record;
DECLARE core jsonb; effect jsonb; response bytea;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','record_attested_codex_experiment_observation','protocol',p_protocol,
		'experiment_id',p_experiment_id,'expected_revision',p_expected_revision,
		'attestation_id',p_attestation_id,'observation_id',p_observation_id,
		'kind',p_kind,'thread_id',p_thread_id,'marker',p_marker,
		'source_id',p_source_id,'fact_digest',p_fact_digest);
	replay:=decodex.reserve_exact_codex_experiment_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1358);
	PERFORM pg_catalog.pg_advisory_xact_lock(1358,pg_catalog.hashtext(p_experiment_id::text));
	SELECT experiment.* INTO experiment_row FROM decodex.codex_experiments AS experiment
	JOIN decodex.codex_experiment_retained_title_attestations AS attestation
		USING (experiment_id)
	WHERE experiment.experiment_id=p_experiment_id
		AND attestation.attestation_id=p_attestation_id
		AND attestation.thread_id=p_thread_id
	FOR SHARE OF experiment,attestation;
	IF NOT FOUND OR experiment_row.revision<>p_expected_revision OR p_expected_revision<>3
		OR experiment_row.state<>'thread_bound' OR p_observation_id IS NULL
		OR p_kind IS NULL OR p_marker IS DISTINCT FROM experiment_row.marker
		OR p_source_id IS NULL OR p_source_id='' OR octet_length(p_source_id)>1024
		OR p_source_id~'[[:cntrl:]]' OR p_fact_digest IS NULL
		OR p_fact_digest!~'^[0-9a-f]{64}$' THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'record_attested_codex_experiment_observation',
			'attested_observation_lineage_mismatch');
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.codex_experiment_observations
		WHERE observation_id=p_observation_id) THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'record_attested_codex_experiment_observation',
			'observation_identity_conflict');
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.codex_experiment_observations
		WHERE experiment_id=p_experiment_id AND kind=p_kind
			AND source_id=p_source_id AND fact_digest=p_fact_digest) THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'record_attested_codex_experiment_observation',
			'observation_fact_conflict');
	END IF;
	observed:=pg_catalog.clock_timestamp();
	INSERT INTO decodex.codex_experiment_observations(
		observation_id,experiment_id,experiment_revision,thread_id,marker,
		kind,source_id,fact_digest,observed_at
	) VALUES (
		p_observation_id,p_experiment_id,3,p_thread_id,p_marker,
		p_kind,p_source_id,p_fact_digest,observed
	);
	INSERT INTO decodex.codex_experiment_attested_observations(
		observation_id,attestation_id,experiment_id,thread_id
	) VALUES (p_observation_id,p_attestation_id,p_experiment_id,p_thread_id);
	core:=pg_catalog.jsonb_build_object(
		'operation','record_attested_codex_experiment_observation',
		'experiment_id',p_experiment_id,'experiment_revision',3,
		'attestation_id',p_attestation_id,'observation_id',p_observation_id,
		'kind',p_kind,'thread_id',p_thread_id,'marker',p_marker,
		'source_id',p_source_id,'fact_digest',p_fact_digest,
		'observed_at_micros',(extract(epoch FROM observed)*1000000)::bigint);
	effect:=core||pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',
		outcome_class='success',effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$_$;


--
-- Name: record_codex_experiment_observation_exact(text, text, uuid, bigint, uuid, decodex.codex_experiment_observation_kind, text, text, text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.record_codex_experiment_observation_exact(p_protocol text, p_idempotency_key text, p_experiment_id uuid, p_expected_revision bigint, p_observation_id uuid, p_kind decodex.codex_experiment_observation_kind, p_thread_id text, p_marker text, p_source_id text, p_fact_digest text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; replay bytea; observed timestamptz; experiment_row record;
DECLARE core jsonb; effect jsonb; response bytea;
BEGIN
	request:=pg_catalog.jsonb_build_object('operation','record_codex_experiment_observation',
		'protocol',p_protocol,'experiment_id',p_experiment_id,
		'expected_revision',p_expected_revision,'observation_id',p_observation_id,
		'kind',p_kind,'thread_id',p_thread_id,'marker',p_marker,
		'source_id',p_source_id,'fact_digest',p_fact_digest);
	replay:=decodex.reserve_exact_codex_experiment_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1358);
	PERFORM pg_catalog.pg_advisory_xact_lock(1358,pg_catalog.hashtext(p_experiment_id::text));
	SELECT experiment.* INTO experiment_row FROM decodex.codex_experiments AS experiment
	JOIN decodex.codex_experiment_thread_bindings AS binding USING (experiment_id)
	WHERE experiment.experiment_id=p_experiment_id
		AND binding.thread_id=p_thread_id FOR SHARE OF experiment,binding;
	IF NOT FOUND OR experiment_row.revision<>p_expected_revision OR p_expected_revision<>3
		OR experiment_row.state<>'thread_bound' OR p_observation_id IS NULL
		OR p_kind IS NULL OR p_marker IS DISTINCT FROM experiment_row.marker
		OR p_source_id IS NULL OR p_source_id='' OR p_fact_digest !~ '^[0-9a-f]{64}$' THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'record_codex_experiment_observation',
			'observation_lineage_mismatch');
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.codex_experiment_observations
		WHERE observation_id=p_observation_id) THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'record_codex_experiment_observation',
			'observation_identity_conflict');
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.codex_experiment_observations
		WHERE experiment_id=p_experiment_id AND kind=p_kind
			AND source_id=p_source_id AND fact_digest=p_fact_digest) THEN
		RETURN decodex.complete_exact_codex_experiment_rejection(
			p_protocol,p_idempotency_key,'record_codex_experiment_observation',
			'observation_fact_conflict');
	END IF;
	observed:=pg_catalog.clock_timestamp();
	INSERT INTO decodex.codex_experiment_observations(observation_id,experiment_id,
		experiment_revision,thread_id,marker,kind,source_id,fact_digest,observed_at)
	VALUES(p_observation_id,p_experiment_id,3,p_thread_id,p_marker,p_kind,
		p_source_id,p_fact_digest,observed);
	core:=pg_catalog.jsonb_build_object('operation','record_codex_experiment_observation',
		'experiment_id',p_experiment_id,'experiment_revision',3,
		'observation_id',p_observation_id,'kind',p_kind,'thread_id',p_thread_id,
		'marker',p_marker,'source_id',p_source_id,'fact_digest',p_fact_digest,
		'observed_at_micros',(extract(epoch FROM observed)*1000000)::bigint);
	effect:=core||pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$_$;


--
-- Name: record_process_generation_death_exact(uuid, bigint, uuid, decodex.process_generation_death_evidence_kind, text, bigint, text, bigint, bigint, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.record_process_generation_death_exact(p_generation_id uuid, p_expected_revision bigint, p_evidence_id uuid, p_kind decodex.process_generation_death_evidence_kind, p_observed_boot_id text, p_process_id bigint, p_process_start_id text, p_process_group_id bigint, p_session_id bigint, p_witness_digest text) RETURNS TABLE(result_code text, revision bigint, state decodex.process_generation_state, observed_at_micros bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE generation decodex.process_generations%ROWTYPE;
DECLARE evidence decodex.process_generation_death_evidence%ROWTYPE;
DECLARE observed timestamptz;
BEGIN
	SELECT * INTO generation FROM decodex.process_generations
	WHERE generation_id = p_generation_id FOR UPDATE;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'generation_missing', 0::bigint,
			'starting'::decodex.process_generation_state, 0::bigint;
		RETURN;
	END IF;
	IF p_expected_revision IS NULL THEN
		RETURN QUERY SELECT 'stale_generation', generation.revision, generation.state, 0::bigint;
		RETURN;
	END IF;
	SELECT * INTO evidence
	FROM decodex.process_generation_death_evidence
	WHERE evidence_id = p_evidence_id;
	IF FOUND THEN
		IF (evidence.generation_id, evidence.generation_revision,
			evidence.kind, evidence.observed_boot_id,
			evidence.process_id, evidence.process_start_id, evidence.process_group_id,
			evidence.session_id, evidence.witness_digest)
			IS NOT DISTINCT FROM
			(p_generation_id, p_expected_revision, p_kind, p_observed_boot_id,
			p_process_id, p_process_start_id, p_process_group_id,
			p_session_id, p_witness_digest)
			AND generation.state = 'dead'
			AND generation.death_evidence_id = p_evidence_id
		THEN
			RETURN QUERY SELECT 'replayed', generation.revision, generation.state,
				(extract(epoch FROM evidence.observed_at)*1000000)::bigint;
		ELSE
			RETURN QUERY SELECT 'evidence_conflict', generation.revision, generation.state,
				(extract(epoch FROM evidence.observed_at)*1000000)::bigint;
		END IF;
		RETURN;
	END IF;
	IF generation.state = 'dead'
		OR generation.revision <> p_expected_revision
	THEN
		RETURN QUERY SELECT 'stale_generation', generation.revision, generation.state, 0::bigint;
		RETURN;
	END IF;
	IF p_witness_digest IS NULL OR p_witness_digest !~ '^[0-9a-f]{64}$'
		OR p_observed_boot_id IS NULL OR p_observed_boot_id = ''
		OR octet_length(p_observed_boot_id) > 128
		OR p_observed_boot_id ~ '[[:cntrl:][:space:]]'
	THEN
		RETURN QUERY SELECT 'invalid_evidence', generation.revision, generation.state, 0::bigint;
		RETURN;
	END IF;
	IF p_kind = 'spawn_not_created' THEN
		IF generation.state <> 'starting'
			OR generation.process_id IS NOT NULL
			OR p_observed_boot_id IS DISTINCT FROM generation.intended_boot_id
			OR p_process_id IS NOT NULL OR p_process_start_id IS NOT NULL
			OR p_process_group_id IS NOT NULL OR p_session_id IS NOT NULL
		THEN
			RETURN QUERY SELECT 'evidence_mismatch', generation.revision, generation.state,
				0::bigint;
			RETURN;
		END IF;
	ELSIF p_kind = 'prior_boot_ended' THEN
		IF generation.state <> 'death_unknown'
			OR p_observed_boot_id = generation.intended_boot_id
			OR p_process_id IS NOT NULL OR p_process_start_id IS NOT NULL
			OR p_process_group_id IS NOT NULL OR p_session_id IS NOT NULL
		THEN
			RETURN QUERY SELECT 'evidence_mismatch', generation.revision, generation.state,
				0::bigint;
			RETURN;
		END IF;
	ELSIF p_kind = 'owned_child_exit' AND generation.process_id IS NULL THEN
		IF generation.state NOT IN ('starting', 'death_unknown')
			OR p_observed_boot_id IS DISTINCT FROM generation.intended_boot_id
			OR p_process_id IS NOT NULL OR p_process_start_id IS NOT NULL
			OR p_process_group_id IS NOT NULL OR p_session_id IS NOT NULL
		THEN
			RETURN QUERY SELECT 'evidence_mismatch', generation.revision, generation.state,
				0::bigint;
			RETURN;
		END IF;
	ELSIF generation.process_id IS NULL
		OR p_observed_boot_id IS DISTINCT FROM generation.bound_boot_id
		OR (p_process_id, p_process_start_id, p_process_group_id, p_session_id)
			IS DISTINCT FROM
			(generation.process_id, generation.process_start_id,
			generation.process_group_id, generation.session_id)
	THEN
		RETURN QUERY SELECT 'evidence_mismatch', generation.revision, generation.state,
			0::bigint;
		RETURN;
	END IF;

	observed := pg_catalog.clock_timestamp();
	INSERT INTO decodex.process_generation_death_evidence(
		evidence_id, generation_id, generation_revision, kind, observed_boot_id,
		process_id, process_start_id, process_group_id, session_id,
		witness_digest, observed_at
	) VALUES (
		p_evidence_id, p_generation_id, p_expected_revision, p_kind, p_observed_boot_id,
		p_process_id, p_process_start_id, p_process_group_id, p_session_id,
		p_witness_digest, observed
	);

	IF generation.state = 'ready' THEN
		UPDATE decodex.process_generations AS target
		SET state = 'stopping', revision = target.revision + 1, updated_at = observed
		WHERE target.generation_id = p_generation_id;
	ELSIF generation.state = 'starting' THEN
		UPDATE decodex.process_generations AS target
		SET state = 'death_unknown',
			authority_loss_reason = 'control_authority_lost',
			revision = target.revision + 1,
			updated_at = observed
		WHERE target.generation_id = p_generation_id;
	END IF;

	UPDATE decodex.process_generations AS target
	SET state = 'dead',
		authority_loss_reason = NULL,
		death_evidence_id = p_evidence_id,
		revision = target.revision + 1,
		updated_at = observed
	WHERE target.generation_id = p_generation_id;

	SELECT * INTO generation FROM decodex.process_generations
	WHERE generation_id = p_generation_id;
	RETURN QUERY SELECT 'dead', generation.revision, generation.state,
		(extract(epoch FROM observed)*1000000)::bigint;
END;
$_$;


--
-- Name: record_process_generation_transition(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.record_process_generation_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	INSERT INTO decodex.process_generation_transitions(
		generation_id, revision, previous_state, state,
		authority_loss_reason, death_evidence_id, transitioned_at
	) VALUES (
		NEW.generation_id, NEW.revision,
		CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.state END,
		NEW.state, NEW.authority_loss_reason, NEW.death_evidence_id, NEW.updated_at
	);
	RETURN NULL;
END;
$$;


--
-- Name: record_provider_attempt_positive_evidence_exact(uuid, bigint, uuid, uuid, decodex.provider_attempt_evidence_source, decodex.provider_attempt_terminal_outcome, text, text, text, text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.record_provider_attempt_positive_evidence_exact(p_attempt_id uuid, p_expected_revision bigint, p_evidence_id uuid, p_request_id uuid, p_source decodex.provider_attempt_evidence_source, p_outcome decodex.provider_attempt_terminal_outcome, p_provider_key text, p_provider_receipt_id text, p_provider_thread_id text, p_provider_turn_id text, p_witness_digest text) RETURNS TABLE(result_code text, revision bigint, state decodex.provider_attempt_state, observed_at_micros bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE attempt decodex.provider_attempts%ROWTYPE;
DECLARE evidence decodex.provider_attempt_positive_evidence%ROWTYPE;
DECLARE session_thread_id text;
DECLARE observed timestamptz;
BEGIN
	SELECT * INTO attempt
	FROM decodex.provider_attempts
	WHERE attempt_id = p_attempt_id
	FOR UPDATE;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'attempt_missing', 0::bigint,
			'prepared'::decodex.provider_attempt_state, 0::bigint;
		RETURN;
	END IF;
	IF p_expected_revision IS NULL OR p_expected_revision <= 0 THEN
		RETURN QUERY SELECT 'invalid_input', attempt.revision, attempt.state, 0::bigint;
		RETURN;
	END IF;

	SELECT * INTO evidence
	FROM decodex.provider_attempt_positive_evidence
	WHERE evidence_id = p_evidence_id;
	IF FOUND THEN
		IF (
			evidence.attempt_id,
			evidence.request_id,
			evidence.selected_account_id,
			evidence.source,
			evidence.outcome,
			evidence.provider_key,
			evidence.provider_receipt_id,
			evidence.provider_thread_id,
			evidence.provider_turn_id,
			evidence.witness_digest
		) IS NOT DISTINCT FROM (
			p_attempt_id,
			p_request_id,
			attempt.selected_account_id,
			p_source,
			p_outcome,
			p_provider_key,
			p_provider_receipt_id,
			p_provider_thread_id,
			p_provider_turn_id,
			p_witness_digest
		)
			AND p_expected_revision IN (
				evidence.attempt_revision, attempt.revision
			)
			AND attempt.terminal_evidence_id = p_evidence_id
			AND attempt.state::text = p_outcome::text
		THEN
			RETURN QUERY SELECT
				'replayed',
				attempt.revision,
				attempt.state,
				(extract(epoch FROM evidence.observed_at)*1000000)::bigint;
		ELSE
			RETURN QUERY SELECT
				'evidence_conflict',
				attempt.revision,
				attempt.state,
				(extract(epoch FROM evidence.observed_at)*1000000)::bigint;
		END IF;
		RETURN;
	END IF;

	IF attempt.state NOT IN ('dispatch_authorized', 'unknown')
		OR attempt.revision <> p_expected_revision
	THEN
		RETURN QUERY SELECT 'stale_attempt', attempt.revision, attempt.state, 0::bigint;
		RETURN;
	END IF;
	IF p_request_id <> attempt.request_id
		OR (
			p_provider_key IS DISTINCT FROM attempt.provider_idempotency_key
			AND p_provider_key IS DISTINCT FROM attempt.provider_correlation_key
		)
		OR (
			p_source = 'positive_idempotency_lookup'
			AND p_provider_key IS DISTINCT FROM attempt.provider_idempotency_key
		)
		OR p_witness_digest IS NULL
		OR p_witness_digest COLLATE pg_catalog."C" !~ '^[0-9a-f]{64}$'
	THEN
		RETURN QUERY SELECT 'evidence_mismatch', attempt.revision, attempt.state, 0::bigint;
		RETURN;
	END IF;

	IF (
		p_source = 'provider_receipt'
		AND (
			p_outcome = 'not_submitted'
			OR p_provider_receipt_id IS NULL
		)
	) OR (
		p_source = 'exact_turn_readback'
		AND (
			p_outcome = 'not_submitted'
			OR p_provider_receipt_id IS NOT NULL
			OR p_provider_thread_id IS NOT NULL
			OR p_provider_turn_id IS NULL
		)
	) OR (
		p_source = 'exact_thread_readback'
		AND (
			p_outcome = 'not_submitted'
			OR p_provider_receipt_id IS NOT NULL
			OR p_provider_thread_id IS NULL
			OR p_provider_turn_id IS NULL
		)
	) OR (
		p_source = 'positive_non_submission_receipt'
		AND (
			p_outcome <> 'not_submitted'
			OR p_provider_receipt_id IS NULL
			OR p_provider_turn_id IS NOT NULL
		)
	) THEN
		RETURN QUERY SELECT 'invalid_evidence', attempt.revision, attempt.state, 0::bigint;
		RETURN;
	END IF;

	SELECT session.codex_thread_id INTO session_thread_id
	FROM decodex.runtime_sessions AS session
	WHERE session.runtime_session_id = attempt.accepted_runtime_session_id;
	IF p_source = 'exact_thread_readback'
		AND p_provider_thread_id IS DISTINCT FROM session_thread_id
	THEN
		RETURN QUERY SELECT 'evidence_mismatch', attempt.revision, attempt.state, 0::bigint;
		RETURN;
	END IF;

	observed := pg_catalog.clock_timestamp();
	INSERT INTO decodex.provider_attempt_positive_evidence(
		evidence_id,
		attempt_id,
		attempt_revision,
		request_id,
		selected_account_id,
		source,
		outcome,
		provider_key,
		provider_receipt_id,
		provider_thread_id,
		provider_turn_id,
		witness_digest,
		observed_at
	) VALUES (
		p_evidence_id,
		p_attempt_id,
		p_expected_revision,
		p_request_id,
		attempt.selected_account_id,
		p_source,
		p_outcome,
		p_provider_key,
		p_provider_receipt_id,
		p_provider_thread_id,
		p_provider_turn_id,
		p_witness_digest,
		observed
	);
	UPDATE decodex.provider_attempts AS target
	SET state = p_outcome::text::decodex.provider_attempt_state,
		unknown_reason = NULL,
		terminal_evidence_id = p_evidence_id,
		revision = target.revision + 1,
		updated_at = observed
	WHERE target.attempt_id = p_attempt_id;
	RETURN QUERY SELECT
		p_outcome::text,
		p_expected_revision + 1,
		p_outcome::text::decodex.provider_attempt_state,
		(extract(epoch FROM observed)*1000000)::bigint;
END;
$_$;


--
-- Name: record_provider_attempt_transition(); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.record_provider_attempt_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	INSERT INTO decodex.provider_attempt_transitions(
		attempt_id,
		revision,
		previous_state,
		state,
		unknown_reason,
		terminal_evidence_id,
		transitioned_at
	) VALUES (
		NEW.attempt_id,
		NEW.revision,
		CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE OLD.state END,
		NEW.state,
		NEW.unknown_reason,
		NEW.terminal_evidence_id,
		NEW.updated_at
	);
	RETURN NULL;
END;
$$;


--
-- Name: register_waiting_usage_wake_exact(text, text, uuid, uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.register_waiting_usage_wake_exact(p_protocol text, p_idempotency_key text, p_operation_id uuid, p_decision_id uuid, p_expected_managed_run_revision bigint) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
BEGIN
	RETURN decodex.register_waiting_usage_wake_exact_internal(
		p_protocol,p_idempotency_key,p_operation_id,p_decision_id,
		p_expected_managed_run_revision,NULL::pg_catalog.timestamptz);
END
$$;


--
-- Name: register_waiting_usage_wake_exact_internal(text, text, uuid, uuid, bigint, timestamp with time zone); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.register_waiting_usage_wake_exact_internal(p_protocol text, p_idempotency_key text, p_operation_id uuid, p_decision_id uuid, p_expected_managed_run_revision bigint, p_authority_now timestamp with time zone) RETURNS bytea
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; replay bytea; decision_row record; run_row record; existing_head record;
DECLARE run_uuid uuid; wake_uuid uuid; transition_uuid uuid; now_value timestamptz;
DECLARE activity_sequence bigint; outbox_id bigint; core jsonb; effect jsonb; response bytea;
DECLARE payload jsonb;
BEGIN
	IF p_authority_now IS NOT NULL THEN
		IF NOT pg_catalog.isfinite(p_authority_now)
			OR extract(epoch FROM p_authority_now)*1000000 < 0
			OR extract(epoch FROM p_authority_now)*1000000
				> 253402300739999999
			OR extract(epoch FROM p_authority_now)*1000000
				<> pg_catalog.trunc(extract(epoch FROM p_authority_now)*1000000)
		THEN
			RAISE EXCEPTION 'explicit waiting-usage wake authority time is outside the canonical range'
				USING ERRCODE='22023', CONSTRAINT='waiting_usage_wake_authority_time';
		END IF;
	END IF;
	request:=pg_catalog.jsonb_build_object('operation','register_waiting_usage_wake',
		'protocol',p_protocol,'operation_id',p_operation_id,'decision_id',p_decision_id,
		'expected_managed_run_revision',p_expected_managed_run_revision);
	replay:=decodex.reserve_exact_waiting_usage_wake_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	IF p_operation_id IS NULL OR p_decision_id IS NULL
		OR p_expected_managed_run_revision IS NULL OR p_expected_managed_run_revision<=0 THEN
		RETURN decodex.complete_exact_waiting_usage_wake_rejection(
			p_protocol,p_idempotency_key,'register_waiting_usage_wake','invalid_input');
	END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	replay:=decodex.replay_waiting_usage_wake_operation_exact(
		p_protocol,p_idempotency_key,'register_waiting_usage_wake',p_operation_id,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	SELECT managed_run_id INTO run_uuid FROM decodex.routing_decisions
	WHERE decision_id=p_decision_id
		AND authority_shape='managed_run_project_policy';
	IF NOT FOUND THEN RETURN decodex.complete_exact_waiting_usage_wake_rejection(
		p_protocol,p_idempotency_key,'register_waiting_usage_wake','missing_decision'); END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1338,pg_catalog.hashtext(run_uuid::text));
	PERFORM pg_catalog.pg_advisory_xact_lock(1362,pg_catalog.hashtext(p_decision_id::text));
	SELECT * INTO decision_row FROM decodex.routing_decisions
	WHERE decision_id=p_decision_id FOR UPDATE;
	IF decision_row.authority_shape<>'managed_run_project_policy'
		OR decision_row.kind<>'waiting_usage'
	THEN
		RETURN decodex.complete_exact_waiting_usage_wake_rejection(
			p_protocol,p_idempotency_key,'register_waiting_usage_wake','decision_not_waiting_usage');
	END IF;
	SELECT * INTO existing_head FROM decodex.waiting_usage_wake_heads
	WHERE routing_decision_id=p_decision_id FOR UPDATE;
	IF FOUND THEN
		RETURN decodex.complete_exact_waiting_usage_wake_rejection(
			p_protocol,p_idempotency_key,'register_waiting_usage_wake','decision_already_registered');
	END IF;
	SELECT * INTO run_row FROM decodex.managed_runs
	WHERE managed_run_id=decision_row.managed_run_id FOR UPDATE;
	IF run_row.managed_run_id IS NULL OR run_row.revision<>p_expected_managed_run_revision
		OR decision_row.managed_run_revision<>p_expected_managed_run_revision
		OR run_row.lifecycle<>'waiting' OR run_row.wait_reason<>'usage'
		OR NOT run_row.blocked OR run_row.diverged THEN
		RETURN decodex.complete_exact_waiting_usage_wake_rejection(
			p_protocol,p_idempotency_key,'register_waiting_usage_wake','stale_managed_run');
	END IF;
	IF NOT EXISTS (SELECT 1 FROM decodex.routing_policy_heads
		WHERE routing_policy_id=decision_row.routing_policy_id
			AND current_revision=decision_row.routing_policy_revision FOR SHARE) THEN
		RETURN decodex.complete_exact_waiting_usage_wake_rejection(
			p_protocol,p_idempotency_key,'register_waiting_usage_wake','stale_policy');
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.routing_decisions AS other
		WHERE other.managed_run_id=decision_row.managed_run_id
			AND other.managed_run_revision>=decision_row.managed_run_revision
			AND other.decision_id<>decision_row.decision_id) THEN
		RETURN decodex.complete_exact_waiting_usage_wake_rejection(
			p_protocol,p_idempotency_key,'register_waiting_usage_wake',
			'ambiguous_decision_lineage');
	END IF;
	now_value:=CASE WHEN p_authority_now IS NULL THEN pg_catalog.clock_timestamp()
		ELSE p_authority_now END;
	IF p_authority_now IS NOT NULL AND (
		now_value < decision_row.decided_at OR now_value < run_row.updated_at) THEN
		RAISE EXCEPTION 'explicit wake registration time precedes locked decision or run authority'
			USING ERRCODE='22023', CONSTRAINT='waiting_usage_wake_authority_time_monotonic';
	END IF;
	wake_uuid:=pg_catalog.gen_random_uuid();
	transition_uuid:=pg_catalog.gen_random_uuid();
	activity_sequence:=pg_catalog.nextval(
		pg_catalog.pg_get_serial_sequence('decodex.activity','sequence')::pg_catalog.regclass);
	outbox_id:=pg_catalog.nextval(
		pg_catalog.pg_get_serial_sequence('decodex.outbox','id')::pg_catalog.regclass);
	payload:=pg_catalog.jsonb_build_object('waiting_usage_wake_id',wake_uuid,
		'waiting_usage_wake_transition_id',transition_uuid,'state','pending',
		'routing_decision_id',p_decision_id,'managed_run_id',decision_row.managed_run_id,
		'managed_run_revision',decision_row.managed_run_revision,'production_enabled',false);
	core:=pg_catalog.jsonb_build_object('operation','register_waiting_usage_wake',
		'operation_id',p_operation_id,'transition_id',transition_uuid,
		'transition_kind','registered','wake_id',wake_uuid,'revision',1,
		'predecessor_revision',NULL,'predecessor_transition_id',NULL,
		'registration_operation_id',p_operation_id,'routing_decision_id',p_decision_id,
		'routing_decision_revision',1,'routing_policy_id',decision_row.routing_policy_id,
		'routing_policy_revision',decision_row.routing_policy_revision,
		'managed_run_id',decision_row.managed_run_id,
		'managed_run_revision',decision_row.managed_run_revision,
		'earliest_ready_at_micros',decision_row.waiting_ready_at_micros,'state','pending',
		'claim_id',NULL,'lease_holder',NULL,'lease_fence_id',NULL,
		'lease_acquired_at_micros',NULL,'lease_expires_at_micros',NULL,
		'registered_at_micros',(extract(epoch FROM now_value)*1000000)::bigint,
		'transitioned_at_micros',(extract(epoch FROM now_value)*1000000)::bigint,
		'terminal_reason',NULL,'routing_resolution_request_id',NULL,
		'fresh_routing_resolution_only',true,'prior_decision_reusable',false,
		'production_enabled',false,
		'activity_effects',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
			'sequence',activity_sequence,'event_kind','waiting_usage_wake_registered')),
		'outbox_effects',pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
			'id',outbox_id,'effect_key','activity/'||activity_sequence::text)));
	effect:=core||pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	INSERT INTO decodex.waiting_usage_wake_transitions(
		transition_id,wake_id,revision,operation_id,transition_kind,request_envelope,
		request_digest,registration_operation_id,routing_decision_id,routing_policy_id,
		routing_policy_revision,managed_run_id,managed_run_revision,earliest_ready_at_micros,
		state,registered_at,transitioned_at,activity_sequence,outbox_id,effect_envelope,
		effect_digest,response_bytes
	) VALUES(transition_uuid,wake_uuid,1,p_operation_id,'registered',request,
		public.digest(pg_catalog.convert_to(request::text,'UTF8'),'sha256'),p_operation_id,
		p_decision_id,decision_row.routing_policy_id,decision_row.routing_policy_revision,
		decision_row.managed_run_id,decision_row.managed_run_revision,
		decision_row.waiting_ready_at_micros,'pending',now_value,now_value,
		activity_sequence,outbox_id,effect,
		public.digest(pg_catalog.convert_to(core::text,'UTF8'),'sha256'),response);
	INSERT INTO decodex.waiting_usage_wake_heads(
		wake_id,revision,transition_id,registration_operation_id,routing_decision_id,
		routing_decision_revision,routing_policy_id,routing_policy_revision,managed_run_id,
		managed_run_revision,earliest_ready_at_micros,state,registered_at,updated_at
	) VALUES(wake_uuid,1,transition_uuid,p_operation_id,p_decision_id,1,
		decision_row.routing_policy_id,decision_row.routing_policy_revision,
		decision_row.managed_run_id,decision_row.managed_run_revision,
		decision_row.waiting_ready_at_micros,'pending',now_value,now_value);
	INSERT INTO decodex.activity(sequence,aggregate_kind,aggregate_id,revision,event_kind,
		correlation_key,payload) OVERRIDING SYSTEM VALUE
	VALUES(activity_sequence,'waiting_usage_wake',wake_uuid::text,1,
		'waiting_usage_wake_registered',p_operation_id::text,payload);
	INSERT INTO decodex.outbox(id,effect_key,aggregate_kind,aggregate_id,aggregate_revision,payload)
	OVERRIDING SYSTEM VALUE VALUES(outbox_id,'activity/'||activity_sequence::text,
		'waiting_usage_wake',wake_uuid::text,1,payload);
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',
		outcome_class='success',effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$$;


--
-- Name: release_lease(text, uuid, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.release_lease(p_resource_key text, p_holder_id uuid, p_lease_token uuid) RETURNS boolean
    LANGUAGE sql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	WITH write_time AS (SELECT clock_timestamp() AS value)
	UPDATE decodex.leases
	SET expires_at = write_time.value,
		revision = revision + 1,
		updated_at = write_time.value
	FROM write_time
	WHERE resource_key = p_resource_key
		AND holder_id = p_holder_id
		AND lease_token = p_lease_token
		AND expires_at > write_time.value
	RETURNING true
$$;


--
-- Name: renew_lease(text, uuid, uuid, interval); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.renew_lease(p_resource_key text, p_holder_id uuid, p_lease_token uuid, p_ttl interval) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE
	ttl_milliseconds bigint := decodex.lease_ttl_milliseconds(p_ttl);
	write_at timestamptz := clock_timestamp();
	updated_count bigint;
BEGIN
	UPDATE decodex.leases
	SET expires_at = write_at + ttl_milliseconds * interval '1 millisecond',
		revision = revision + 1,
		updated_at = write_at
	WHERE resource_key = p_resource_key
		AND holder_id = p_holder_id
		AND lease_token = p_lease_token
		AND expires_at > write_at;

	GET DIAGNOSTICS updated_count = ROW_COUNT;

	RETURN updated_count = 1;
END
$$;


--
-- Name: replace_routing_policy_exact(text, text, uuid, uuid, bigint, uuid, bigint, decodex.role_profile_role, bigint, text, uuid[], bigint[], decodex.routing_member_disposition[], decodex.codex_capability[]); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.replace_routing_policy_exact(p_protocol text, p_idempotency_key text, p_routing_policy_id uuid, p_project_id uuid, p_expected_revision bigint, p_accepted_policy_id uuid, p_accepted_policy_revision bigint, p_required_role decodex.role_profile_role, p_required_role_profile_revision bigint, p_required_build_id text, p_account_ids uuid[], p_account_revisions bigint[], p_dispositions decodex.routing_member_disposition[], p_required_capabilities decodex.codex_capability[]) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; replay bytea; actual_revision bigint; actual_project_id uuid;
DECLARE new_revision bigint;
DECLARE inventory_count bigint; core jsonb; effect jsonb; response bytea;
BEGIN
	request := pg_catalog.jsonb_build_object(
		'operation','replace_routing_policy','protocol',p_protocol,
		'routing_policy_id',p_routing_policy_id,'project_id',p_project_id,
		'expected_revision',p_expected_revision,'accepted_policy_id',p_accepted_policy_id,
		'accepted_policy_revision',p_accepted_policy_revision,'required_role',p_required_role,
		'required_role_profile_revision',p_required_role_profile_revision,
		'required_build_id',p_required_build_id,'account_ids',p_account_ids,
		'account_revisions',p_account_revisions,'dispositions',p_dispositions,
		'required_capabilities',p_required_capabilities);
	replay := decodex.reserve_exact_routing_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(1356);
	LOCK TABLE decodex.accounts, decodex.policies, decodex.policy_revisions,
		decodex.role_profiles, decodex.role_profile_revisions,
		decodex.routing_policy_heads, decodex.routing_policy_revisions,
		decodex.routing_policy_members, decodex.routing_policy_required_capabilities
		IN SHARE MODE;
	IF p_routing_policy_id IS NULL OR p_project_id IS NULL OR p_accepted_policy_id IS NULL
		OR p_required_role IS NULL OR p_required_build_id IS NULL
		OR p_accepted_policy_revision<=0 OR p_required_role_profile_revision<=0
		OR p_expected_revision IS NOT NULL AND p_expected_revision<=0
		OR p_required_build_id COLLATE pg_catalog."C" !~ '^sha256:[0-9a-f]{64}$'
		OR p_account_ids IS NULL OR p_account_revisions IS NULL OR p_dispositions IS NULL
		OR pg_catalog.cardinality(p_account_ids) <> pg_catalog.cardinality(p_account_revisions)
		OR pg_catalog.cardinality(p_account_ids) <> pg_catalog.cardinality(p_dispositions)
		OR pg_catalog.array_position(p_account_ids,NULL) IS NOT NULL
		OR pg_catalog.array_position(p_account_revisions,NULL) IS NOT NULL
		OR pg_catalog.array_position(p_dispositions,NULL) IS NOT NULL
		OR EXISTS (SELECT 1 FROM pg_catalog.unnest(p_account_revisions) AS revision
			WHERE revision <= 0)
		OR pg_catalog.cardinality(p_account_ids) <> (
			SELECT pg_catalog.count(DISTINCT value) FROM pg_catalog.unnest(p_account_ids) AS item(value)
		) OR p_required_capabilities IS NULL
		OR pg_catalog.array_position(p_required_capabilities,NULL) IS NOT NULL
		OR pg_catalog.cardinality(p_required_capabilities) <> (
			SELECT pg_catalog.count(DISTINCT value)
			FROM pg_catalog.unnest(p_required_capabilities) AS item(value)
		) OR p_required_capabilities <> ARRAY(
			SELECT capability FROM pg_catalog.unnest(p_required_capabilities) AS item(capability)
			ORDER BY capability
		) THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'replace_routing_policy','invalid_inventory');
	END IF;
	PERFORM 1 FROM decodex.accounts ORDER BY account_id FOR SHARE;
	SELECT pg_catalog.count(*) INTO inventory_count FROM decodex.accounts;
	IF inventory_count <> pg_catalog.cardinality(p_account_ids) OR EXISTS (
		SELECT account_id,revision FROM decodex.accounts
		EXCEPT SELECT account_id,revision FROM ROWS FROM (
			pg_catalog.unnest(p_account_ids), pg_catalog.unnest(p_account_revisions)
		)
			AS requested(account_id,revision)
	) THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'replace_routing_policy','inventory_revision_mismatch');
	END IF;
	PERFORM 1 FROM decodex.policies WHERE policy_id=p_accepted_policy_id
		AND project_id=p_project_id AND current_revision=p_accepted_policy_revision FOR SHARE;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'replace_routing_policy','accepted_policy_mismatch');
	END IF;
	PERFORM 1 FROM decodex.policy_revisions WHERE policy_id=p_accepted_policy_id
		AND project_id=p_project_id AND revision=p_accepted_policy_revision FOR SHARE;
	IF NOT FOUND THEN RETURN decodex.complete_exact_routing_rejection(
		p_protocol,p_idempotency_key,'replace_routing_policy','accepted_policy_mismatch'); END IF;
	PERFORM 1 FROM decodex.role_profiles WHERE role=p_required_role
		AND current_revision=p_required_role_profile_revision FOR SHARE;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_routing_rejection(
		p_protocol,p_idempotency_key,'replace_routing_policy','role_profile_mismatch'); END IF;
	PERFORM 1 FROM decodex.role_profile_revisions WHERE role=p_required_role
		AND revision=p_required_role_profile_revision FOR SHARE;
	IF NOT FOUND THEN RETURN decodex.complete_exact_routing_rejection(
		p_protocol,p_idempotency_key,'replace_routing_policy','role_profile_mismatch'); END IF;
	SELECT current_revision,project_id INTO actual_revision,actual_project_id
	FROM decodex.routing_policy_heads
	WHERE routing_policy_id=p_routing_policy_id FOR UPDATE;
	IF actual_revision IS NULL THEN
		IF p_expected_revision IS NOT NULL THEN RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'replace_routing_policy','stale_revision'); END IF;
		new_revision := 1;
		INSERT INTO decodex.routing_policy_heads(routing_policy_id,project_id,current_revision)
		VALUES (p_routing_policy_id,p_project_id,new_revision);
	ELSE
		IF actual_revision <> p_expected_revision OR actual_project_id<>p_project_id THEN
			RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'replace_routing_policy','stale_revision'); END IF;
		new_revision := actual_revision + 1;
		UPDATE decodex.routing_policy_heads SET current_revision=new_revision,
			updated_at=pg_catalog.clock_timestamp()
		WHERE routing_policy_id=p_routing_policy_id AND current_revision=actual_revision;
	END IF;
	INSERT INTO decodex.routing_policy_revisions VALUES (
		p_routing_policy_id,new_revision,p_project_id,p_accepted_policy_id,
		p_accepted_policy_revision,p_required_role,p_required_role_profile_revision,
		p_required_build_id,pg_catalog.clock_timestamp());
	INSERT INTO decodex.routing_policy_members
	SELECT p_routing_policy_id,new_revision,ordinality::integer,account_id,account_revision,disposition
	FROM ROWS FROM (
		pg_catalog.unnest(p_account_ids), pg_catalog.unnest(p_account_revisions),
		pg_catalog.unnest(p_dispositions)
	) WITH ORDINALITY
		AS item(account_id,account_revision,disposition,ordinality);
	INSERT INTO decodex.routing_policy_required_capabilities
	SELECT p_routing_policy_id,new_revision,ordinality::integer,capability
	FROM pg_catalog.unnest(p_required_capabilities) WITH ORDINALITY AS item(capability,ordinality);
	core := pg_catalog.jsonb_build_object('operation','replace_routing_policy',
		'routing_policy_id',p_routing_policy_id,'routing_policy_revision',new_revision,
		'project_id',p_project_id,'accepted_policy_id',p_accepted_policy_id,
		'accepted_policy_revision',p_accepted_policy_revision,'required_role',p_required_role,
		'required_role_profile_revision',p_required_role_profile_revision,
		'required_build_id',p_required_build_id,
		'members',(SELECT COALESCE(
			pg_catalog.jsonb_agg(pg_catalog.to_jsonb(policy_member) ORDER BY position), '[]'::jsonb)
			FROM decodex.routing_policy_members AS policy_member
			WHERE routing_policy_id=p_routing_policy_id AND routing_policy_revision=new_revision),
		'required_capabilities',p_required_capabilities);
	effect := core || pg_catalog.jsonb_build_object('effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(
		public.digest(pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'));
	response := pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$_$;


--
-- Name: replay_waiting_usage_wake_operation_exact(text, text, text, uuid, jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.replay_waiting_usage_wake_operation_exact(p_protocol text, p_idempotency_key text, p_operation text, p_operation_id uuid, p_request jsonb) RETURNS bytea
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE stored decodex.waiting_usage_wake_transitions%ROWTYPE;
BEGIN
	SELECT * INTO stored FROM decodex.waiting_usage_wake_transitions
	WHERE operation_id=p_operation_id;
	IF NOT FOUND THEN RETURN NULL; END IF;
	IF stored.request_envelope<>p_request THEN
		RETURN decodex.complete_exact_waiting_usage_wake_rejection(
			p_protocol,p_idempotency_key,p_operation,'operation_identity_conflict');
	END IF;
	UPDATE decodex.exact_command_receipts SET receipt_state='completed_success',
		outcome_class='success',effect_envelope=stored.effect_envelope,
		response_bytes=stored.response_bytes,completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN stored.response_bytes;
END
$$;


--
-- Name: reserve_exact_codex_experiment_command(text, text, jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.reserve_exact_codex_experiment_command(p_protocol text, p_idempotency_key text, p_request jsonb) RETURNS bytea
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE stored record;
BEGIN
	IF pg_catalog.current_setting('transaction_isolation') <> 'read committed' THEN
		RAISE EXCEPTION 'exact commands require READ COMMITTED' USING ERRCODE='40001';
	END IF;
	INSERT INTO decodex.exact_command_receipts(
		protocol_version,idempotency_key,request_envelope,request_digest,receipt_state
	) VALUES (p_protocol,p_idempotency_key,p_request,
		public.digest(pg_catalog.convert_to(p_request::text,'UTF8'),'sha256'),'executing')
	ON CONFLICT DO NOTHING;
	SELECT request_envelope,response_bytes,receipt_state INTO stored
	FROM decodex.exact_command_receipts
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key FOR UPDATE;
	IF stored.request_envelope <> p_request THEN
		RAISE EXCEPTION 'idempotency key reused for another Codex experiment command'
			USING ERRCODE='DX001';
	END IF;
	IF stored.receipt_state <> 'executing' THEN RETURN stored.response_bytes; END IF;
	RETURN NULL;
END
$$;


--
-- Name: reserve_exact_continuation_command(text, text, jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.reserve_exact_continuation_command(p_protocol text, p_idempotency_key text, p_request jsonb) RETURNS bytea
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE stored record;
BEGIN
	IF pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN
		RAISE EXCEPTION 'exact commands require READ COMMITTED' USING ERRCODE='40001';
	END IF;
	IF p_protocol IS NULL OR p_idempotency_key IS NULL OR p_request IS NULL
		OR pg_catalog.octet_length(p_protocol) NOT BETWEEN 1 AND 64
		OR p_protocol COLLATE pg_catalog."C" !~ '^[a-z0-9][a-z0-9._/-]{0,63}$'
		OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 256
		OR decodex.has_credential_material(p_idempotency_key) THEN
		RAISE EXCEPTION 'exact continuation command identity is invalid' USING ERRCODE='22023';
	END IF;
	INSERT INTO decodex.exact_command_receipts(
		protocol_version,idempotency_key,request_envelope,request_digest,receipt_state
	) VALUES(p_protocol,p_idempotency_key,p_request,
		public.digest(pg_catalog.convert_to(p_request::text,'UTF8'),'sha256'),'executing')
	ON CONFLICT DO NOTHING;
	SELECT request_envelope,response_bytes,receipt_state INTO STRICT stored
	FROM decodex.exact_command_receipts
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key FOR UPDATE;
	IF stored.request_envelope<>p_request THEN
		RAISE EXCEPTION 'idempotency key reused for another continuation command' USING ERRCODE='DX001';
	END IF;
	IF stored.receipt_state<>'executing' THEN RETURN stored.response_bytes; END IF;
	RETURN NULL;
END
$_$;


