--
-- Name: reserve_exact_work_item_command(text, text, jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.reserve_exact_work_item_command(p_protocol text, p_idempotency_key text, p_request jsonb) RETURNS bytea
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE existing_request jsonb;
DECLARE existing_response bytea;
DECLARE inserted_count integer;
BEGIN
	IF p_protocol IS NULL OR p_idempotency_key IS NULL OR p_request IS NULL THEN
		RAISE EXCEPTION 'exact WorkItem command identity is incomplete' USING ERRCODE = '22004';
	END IF;
	IF pg_catalog.octet_length(p_protocol) NOT BETWEEN 1 AND 64
		OR p_protocol COLLATE pg_catalog."C" !~ '^[a-z0-9][a-z0-9._/-]{0,63}$'
		OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 256
		OR decodex.has_credential_material(p_idempotency_key)
	THEN RAISE EXCEPTION 'exact WorkItem command identity is invalid' USING ERRCODE = '22023';
	END IF;
	INSERT INTO decodex.exact_command_receipts(
		protocol_version, idempotency_key, request_envelope, request_digest, receipt_state
	) VALUES (
		p_protocol, p_idempotency_key, p_request,
		public.digest(pg_catalog.convert_to(p_request::text, 'UTF8'), 'sha256'), 'executing'
	) ON CONFLICT (protocol_version, idempotency_key) DO NOTHING;
	GET DIAGNOSTICS inserted_count = ROW_COUNT;
	IF inserted_count = 0 THEN
		SELECT request_envelope, response_bytes INTO existing_request, existing_response
		FROM decodex.exact_command_receipts
		WHERE protocol_version = p_protocol AND idempotency_key = p_idempotency_key FOR UPDATE;
		IF existing_request <> p_request THEN
			RAISE EXCEPTION 'exact idempotency conflict' USING ERRCODE = 'DX001';
		END IF;
		IF existing_response IS NULL THEN
			RAISE EXCEPTION 'incomplete exact receipt is not replayable' USING ERRCODE = 'DX002';
		END IF;
		RETURN existing_response;
	END IF;
	RETURN NULL;
END
$_$;


--
-- Name: create_quick_task_routing_successor_exact(text, text, uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.create_quick_task_routing_successor_exact(p_protocol text, p_idempotency_key text, p_source_conversation_id uuid, p_expected_source_revision bigint) RETURNS TABLE(response_bytes bytea, replayed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; claimed record; source_row decodex.conversations%ROWTYPE;
DECLARE decision_row decodex.routing_decisions%ROWTYPE;
DECLARE successor_uuid uuid; activity_sequence bigint; outbox_id bigint;
DECLARE payload jsonb; core jsonb; effect jsonb; response_value bytea;
DECLARE rejection_code text;
BEGIN
	IF pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN
		RAISE EXCEPTION 'exact commands require READ COMMITTED' USING ERRCODE='40001';
	END IF;
	IF p_protocol IS NULL OR p_idempotency_key IS NULL
		OR pg_catalog.octet_length(p_protocol) NOT BETWEEN 1 AND 64
		OR p_protocol COLLATE pg_catalog."C" !~ '^[a-z0-9][a-z0-9._/-]{0,63}$'
		OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 256
		OR decodex.has_credential_material(p_idempotency_key)
	THEN
		RAISE EXCEPTION 'exact routing successor identity is invalid' USING ERRCODE='22023';
	END IF;
	request:=pg_catalog.jsonb_build_object(
		'operation','create_quick_task_routing_successor','protocol',p_protocol,
		'source_conversation_id',p_source_conversation_id,
		'expected_source_revision',p_expected_source_revision
	);
	SELECT receipt.request_envelope,receipt.response_bytes,receipt.receipt_state
	INTO claimed
	FROM decodex.exact_command_receipts AS receipt
	WHERE receipt.protocol_version=p_protocol
		AND receipt.idempotency_key=p_idempotency_key;
	IF FOUND THEN
		IF claimed.request_envelope<>request THEN
			RAISE EXCEPTION 'idempotency key reused for another routing successor'
				USING ERRCODE='DX001';
		END IF;
		IF claimed.receipt_state<>'executing' THEN
			RETURN QUERY SELECT claimed.response_bytes,true;
			RETURN;
		END IF;
	END IF;

	IF p_source_conversation_id IS NULL OR p_expected_source_revision IS NULL
		OR p_expected_source_revision<=0
	THEN
		rejection_code:='malformed_input';
	ELSE
		SELECT * INTO source_row FROM decodex.conversations
		WHERE conversation_id=p_source_conversation_id FOR UPDATE;
		IF NOT FOUND THEN rejection_code:='source_conversation_mismatch'; END IF;
	END IF;
	INSERT INTO decodex.exact_command_receipts(
		protocol_version,idempotency_key,request_envelope,request_digest,receipt_state
	) VALUES (
		p_protocol,p_idempotency_key,request,
		public.digest(pg_catalog.convert_to(request::text,'UTF8'),'sha256'),'executing'
	) ON CONFLICT DO NOTHING;
	SELECT receipt.request_envelope,receipt.response_bytes,receipt.receipt_state
	INTO STRICT claimed
	FROM decodex.exact_command_receipts AS receipt
	WHERE receipt.protocol_version=p_protocol
		AND receipt.idempotency_key=p_idempotency_key
	FOR UPDATE;
	IF claimed.request_envelope<>request THEN
		RAISE EXCEPTION 'idempotency key reused for another routing successor'
			USING ERRCODE='DX001';
	END IF;
	IF claimed.receipt_state<>'executing' THEN
		RETURN QUERY SELECT claimed.response_bytes,true;
		RETURN;
	END IF;

	IF rejection_code IS NULL AND (
		source_row.revision<>p_expected_source_revision
		OR source_row.status<>'open'
		OR source_row.initial_quick_task_message IS NULL
		OR source_row.initial_quick_task_working_directory IS NULL
	) THEN rejection_code:='source_conversation_mismatch'; END IF;
	IF rejection_code IS NULL AND EXISTS (
		SELECT 1 FROM decodex.conversation_routing_successors
		WHERE source_conversation_id=p_source_conversation_id
			OR successor_conversation_id=p_source_conversation_id
	) THEN rejection_code:='routing_successor_already_exists'; END IF;
	IF rejection_code IS NULL THEN
		SELECT * INTO decision_row
		FROM decodex.routing_decisions
		WHERE authority_shape='conversation_account_registry'
			AND conversation_id=p_source_conversation_id
		FOR SHARE;
		IF NOT FOUND OR decision_row.kind NOT IN ('waiting','no_route')
			OR decision_row.selected_account_id IS NOT NULL
			OR EXISTS (
				SELECT 1 FROM decodex.routing_decisions
				WHERE conversation_id=p_source_conversation_id
					AND decision_id<>decision_row.decision_id
			)
			OR EXISTS (SELECT 1 FROM decodex.runtime_sessions
				WHERE conversation_id=p_source_conversation_id)
			OR EXISTS (SELECT 1 FROM decodex.turns
				WHERE conversation_id=p_source_conversation_id)
			OR EXISTS (SELECT 1 FROM decodex.continuation_plans
				WHERE consumer_conversation_id=p_source_conversation_id
					OR conversation_id=p_source_conversation_id)
			OR EXISTS (SELECT 1 FROM decodex.provider_attempts
				WHERE conversation_id=p_source_conversation_id)
		THEN rejection_code:='routing_successor_forbidden'; END IF;
	END IF;
	IF rejection_code IS NOT NULL THEN
		response_value:=decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'create_quick_task_routing_successor',
			rejection_code
		);
		RETURN QUERY SELECT response_value,false;
		RETURN;
	END IF;

	successor_uuid:=pg_catalog.gen_random_uuid();
	INSERT INTO decodex.conversations(
		conversation_id,title,initial_quick_task_message,
		initial_quick_task_working_directory
	) VALUES (
		successor_uuid,source_row.title,source_row.initial_quick_task_message,
		source_row.initial_quick_task_working_directory
	);
	UPDATE decodex.conversations SET status='archived',revision=revision+1
	WHERE conversation_id=p_source_conversation_id;
	INSERT INTO decodex.conversation_routing_successors(
		source_conversation_id,successor_conversation_id,source_routing_decision_id,
		source_revision,successor_revision
	) VALUES (
		p_source_conversation_id,successor_uuid,decision_row.decision_id,
		p_expected_source_revision+1,1
	);
	payload:=pg_catalog.jsonb_build_object(
		'kind','quick_task_routing_successor_created',
		'source_conversation_id',p_source_conversation_id,
		'source_conversation_revision',p_expected_source_revision+1,
		'successor_conversation_id',successor_uuid,
		'successor_conversation_revision',1,
		'source_routing_decision_id',decision_row.decision_id
	);
	INSERT INTO decodex.activity(
		aggregate_kind,aggregate_id,revision,event_kind,correlation_key,payload
	) VALUES (
		'conversation',p_source_conversation_id::text,p_expected_source_revision+1,
		'quick_task_routing_successor_created',p_idempotency_key,payload
	) RETURNING sequence INTO activity_sequence;
	INSERT INTO decodex.outbox(
		effect_key,aggregate_kind,aggregate_id,aggregate_revision,payload
	) VALUES (
		'activity/'||activity_sequence::text,'conversation',
		p_source_conversation_id::text,p_expected_source_revision+1,
		pg_catalog.jsonb_build_object(
			'activity_sequence',activity_sequence,
			'event_kind','quick_task_routing_successor_created',
			'aggregate_kind','conversation',
			'aggregate_id',p_source_conversation_id,
			'revision',p_expected_source_revision+1,'payload',payload
		)
	) RETURNING id INTO outbox_id;
	core:=payload||pg_catalog.jsonb_build_object(
		'operation','create_quick_task_routing_successor',
		'activity_sequence',activity_sequence,'outbox_id',outbox_id
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	response_value:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect
	)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET
		receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response_value,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN QUERY SELECT response_value,false;
END
$_$;


--
-- Name: begin_quick_task_initial_route_exact(text, text, uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.begin_quick_task_initial_route_exact(p_protocol text, p_idempotency_key text, p_conversation_id uuid, p_expected_conversation_revision bigint) RETURNS TABLE(disposition text, response_bytes bytea, snapshot_envelope jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; stored record; replay bytea; response bytea;
DECLARE conversation_row decodex.conversations%ROWTYPE;
DECLARE control_row decodex.account_routing_control%ROWTYPE;
DECLARE task_profile_revision bigint; account_count bigint;
DECLARE resolved timestamptz; snapshot_uuid uuid; turn_uuid uuid; core jsonb;
DECLARE conversation_found boolean;
BEGIN
	IF pg_catalog.current_setting('transaction_isolation')<>'read committed' THEN
		RAISE EXCEPTION 'exact commands require READ COMMITTED' USING ERRCODE='40001';
	END IF;
	IF p_protocol IS NULL OR p_idempotency_key IS NULL
		OR pg_catalog.octet_length(p_protocol) NOT BETWEEN 1 AND 64
		OR p_protocol COLLATE pg_catalog."C" !~ '^[a-z0-9][a-z0-9._/-]{0,63}$'
		OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 256
		OR decodex.has_credential_material(p_idempotency_key)
	THEN
		RAISE EXCEPTION 'exact initial route identity is invalid' USING ERRCODE='22023';
	END IF;
	request:=pg_catalog.jsonb_build_object(
		'operation','route_quick_task_initial','protocol',p_protocol,
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision
	);

	-- Completed same-key replay is immutable and does not consume a new lock universe.
	SELECT receipt.request_envelope,receipt.response_bytes,receipt.receipt_state
	INTO stored
	FROM decodex.exact_command_receipts AS receipt
	WHERE receipt.protocol_version=p_protocol
		AND receipt.idempotency_key=p_idempotency_key;
	IF FOUND THEN
		IF stored.request_envelope<>request THEN
			RAISE EXCEPTION 'idempotency key reused for another initial route'
				USING ERRCODE='DX001';
		END IF;
		IF stored.receipt_state<>'executing' THEN
			disposition:='replayed'; response_bytes:=stored.response_bytes;
			snapshot_envelope:=NULL; RETURN NEXT; RETURN;
		END IF;
	END IF;

	IF p_conversation_id IS NULL OR p_expected_conversation_revision IS NULL
		OR p_expected_conversation_revision<=0
	THEN
		replay:=decodex.reserve_exact_routing_command(p_protocol,p_idempotency_key,request);
		IF replay IS NOT NULL THEN
			disposition:='replayed'; response_bytes:=replay;
			snapshot_envelope:=NULL; RETURN NEXT; RETURN;
		END IF;
		response:=decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_quick_task_initial','malformed_input'
		);
		disposition:='rejected'; response_bytes:=response;
		snapshot_envelope:=NULL; RETURN NEXT; RETURN;
	END IF;

	-- The Conversation is always the first mutable domain lock for a fresh route.
	SELECT * INTO conversation_row
	FROM decodex.conversations
	WHERE conversation_id=p_conversation_id
	FOR UPDATE;
	conversation_found:=FOUND;
	replay:=decodex.reserve_exact_routing_command(p_protocol,p_idempotency_key,request);
	IF replay IS NOT NULL THEN
		disposition:='replayed'; response_bytes:=replay;
		snapshot_envelope:=NULL; RETURN NEXT; RETURN;
	END IF;
	IF NOT conversation_found OR conversation_row.revision<>p_expected_conversation_revision
		OR conversation_row.status<>'open'
		OR conversation_row.initial_quick_task_message IS NULL
		OR conversation_row.initial_quick_task_working_directory IS NULL
	THEN
		response:=decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_quick_task_initial','conversation_mismatch'
		);
		disposition:='rejected'; response_bytes:=response;
		snapshot_envelope:=NULL; RETURN NEXT; RETURN;
	END IF;
	IF EXISTS (
		SELECT 1 FROM decodex.routing_snapshots
		WHERE authority_shape='conversation_account_registry'
			AND conversation_id=p_conversation_id
	) OR EXISTS (
		SELECT 1 FROM decodex.routing_decisions
		WHERE authority_shape='conversation_account_registry'
			AND conversation_id=p_conversation_id
	) OR EXISTS (
		SELECT 1 FROM decodex.runtime_sessions
		WHERE conversation_id=p_conversation_id
	) OR EXISTS (
		SELECT 1 FROM decodex.turns
		WHERE conversation_id=p_conversation_id
	) OR EXISTS (
		SELECT 1 FROM decodex.continuation_plans
		WHERE consumer_conversation_id=p_conversation_id
			OR conversation_id=p_conversation_id
	) OR EXISTS (
		SELECT 1 FROM decodex.provider_attempts
		WHERE conversation_id=p_conversation_id
	) THEN
		response:=decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_quick_task_initial',
			'initial_routing_already_bound'
		);
		disposition:='rejected'; response_bytes:=response;
		snapshot_envelope:=NULL; RETURN NEXT; RETURN;
	END IF;

	-- One repeatable Account Registry universe, in the authority-defined lock order.
	SELECT * INTO control_row
	FROM decodex.account_routing_control AS control
	WHERE control.singleton
	FOR UPDATE;
	IF NOT FOUND THEN
		response:=decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_quick_task_initial',
			'routing_authority_unavailable'
		);
		disposition:='rejected'; response_bytes:=response;
		snapshot_envelope:=NULL; RETURN NEXT; RETURN;
	END IF;
	PERFORM account.account_id
	FROM decodex.accounts AS account
	WHERE account.tombstoned_at IS NULL
	ORDER BY account.account_id
	FOR UPDATE OF account;
	SELECT head.current_revision INTO task_profile_revision
	FROM decodex.role_profiles AS head
	JOIN decodex.role_profile_revisions AS revision
		ON revision.role=head.role AND revision.revision=head.current_revision
	WHERE head.role='task'
	FOR UPDATE OF head,revision;
	IF NOT FOUND THEN
		response:=decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_quick_task_initial',
			'routing_authority_unavailable'
		);
		disposition:='rejected'; response_bytes:=response;
		snapshot_envelope:=NULL; RETURN NEXT; RETURN;
	END IF;
	PERFORM ordering.account_id
	FROM decodex.account_routing_order AS ordering
	ORDER BY ordering.account_id
	FOR UPDATE OF ordering;
	PERFORM operation.operation_id
	FROM decodex.account_operations AS operation
	JOIN decodex.accounts AS account USING(account_id)
	WHERE account.tombstoned_at IS NULL
		AND operation.phase NOT IN ('committed','cancelled')
	ORDER BY operation.account_id,operation.operation_id
	FOR SHARE OF operation;
	PERFORM quota.account_id
	FROM decodex.account_quota_facts AS quota
	JOIN decodex.accounts AS account USING(account_id)
	WHERE account.tombstoned_at IS NULL
	ORDER BY quota.account_id,quota.duration_minutes
	FOR SHARE OF quota;

	SELECT pg_catalog.count(*) INTO account_count
	FROM decodex.accounts WHERE tombstoned_at IS NULL;
	IF account_count<1 OR account_count>512
		OR NOT EXISTS (SELECT 1 FROM decodex.account_routing_order)
		OR EXISTS (
			SELECT 1 FROM decodex.account_routing_order
			GROUP BY true
			HAVING pg_catalog.count(*)<>account_count
				OR pg_catalog.min(position)<>0
				OR pg_catalog.max(position)<>account_count-1
				OR pg_catalog.count(DISTINCT position)<>account_count
		)
		OR EXISTS (
			SELECT account_id FROM decodex.accounts WHERE tombstoned_at IS NULL
			EXCEPT SELECT account_id FROM decodex.account_routing_order
		)
		OR EXISTS (
			SELECT account_id FROM decodex.account_routing_order
			EXCEPT SELECT account_id FROM decodex.accounts WHERE tombstoned_at IS NULL
		)
		OR (control_row.mode='fixed') IS DISTINCT FROM
			(control_row.fixed_account_id IS NOT NULL)
		OR (control_row.fixed_account_id IS NOT NULL AND NOT EXISTS (
			SELECT 1 FROM decodex.account_routing_order
			WHERE account_id=control_row.fixed_account_id
		))
	THEN
		response:=decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_quick_task_initial',
			'routing_authority_unavailable'
		);
		disposition:='rejected'; response_bytes:=response;
		snapshot_envelope:=NULL; RETURN NEXT; RETURN;
	END IF;

	resolved:=pg_catalog.clock_timestamp();
	snapshot_uuid:=pg_catalog.gen_random_uuid();
	turn_uuid:=pg_catalog.gen_random_uuid();
	INSERT INTO decodex.routing_snapshots(
		snapshot_id,authority_shape,account_routing_revision,account_selection_mode,
		fixed_account_id,task_role,task_role_profile_revision,resolved_at,
		consumer_kind,conversation_id,conversation_revision,turn_id
	) VALUES (
		snapshot_uuid,'conversation_account_registry',control_row.revision,control_row.mode,
		control_row.fixed_account_id,'task',task_profile_revision,resolved,
		'conversation_turn',p_conversation_id,p_expected_conversation_revision,turn_uuid
	);
	INSERT INTO decodex.routing_snapshot_members(
		snapshot_id,authority_shape,position,account_id,account_revision,
		display_label,account_state,blockers
	)
	SELECT snapshot_uuid,'conversation_account_registry',ordering.position+1,
		account.account_id,account.revision,account.display_label,account.state,
		expected.blockers
	FROM decodex.accounts AS account
	JOIN decodex.account_routing_order AS ordering USING(account_id)
	CROSS JOIN LATERAL (
		SELECT COALESCE(
			pg_catalog.array_agg(fact.blocker ORDER BY fact.blocker),
			ARRAY[]::decodex.routing_blocker[]
		) AS blockers
		FROM (
			SELECT source.blocker
			FROM (VALUES
				('account_from_future'::decodex.routing_blocker,
					account.observed_at>resolved
					OR account.credential_store_observed_at>resolved),
				('account_stale'::decodex.routing_blocker,
					account.observed_at<=resolved
						AND resolved-account.observed_at>INTERVAL '300 seconds'
					OR account.credential_store_observed_at<=resolved
						AND resolved-account.credential_store_observed_at>
							INTERVAL '300 seconds'),
				('account_unavailable'::decodex.routing_blocker,
					account.state='unavailable'
					OR account.credential_store_observation='unavailable'
					OR EXISTS (
						SELECT 1 FROM decodex.account_operations AS operation
						WHERE operation.account_id=account.account_id
							AND operation.phase NOT IN ('committed','cancelled')
					)),
				('account_unknown'::decodex.routing_blocker,
					account.state='unknown'
					OR account.credential_store_observation='unknown'),
				('account_depleted'::decodex.routing_blocker,
					account.state='depleted'),
				('account_auth_failed'::decodex.routing_blocker,
					account.state='auth_failed'
					OR account.provider_kind IS NULL
					OR account.provider_account_id IS NULL
					OR account.credential_store_schema_version IS DISTINCT FROM 1
					OR account.credential_version IS NULL
					OR account.credential_fingerprint IS NULL
					OR account.credential_writer_operation_id IS NULL
					OR account.credential_store_observation IN (
						'missing','mismatch','provider_mismatch'
					)),
				('account_plugin_unready'::decodex.routing_blocker,
					account.state='plugin_unready'),
				('account_disabled'::decodex.routing_blocker,
					NOT account.enabled OR account.state='disabled')
			) AS source(blocker,applies)
			WHERE source.applies
		) AS fact
	) AS expected
	WHERE account.tombstoned_at IS NULL
	ORDER BY ordering.position;
	INSERT INTO decodex.routing_snapshot_blockers(
		snapshot_id,account_id,position,blocker
	)
	SELECT member.snapshot_id,member.account_id,item.ordinality::integer,item.blocker
	FROM decodex.routing_snapshot_members AS member
	CROSS JOIN LATERAL pg_catalog.unnest(member.blockers)
		WITH ORDINALITY AS item(blocker,ordinality)
	WHERE member.snapshot_id=snapshot_uuid;
	INSERT INTO decodex.routing_snapshot_quota_facts(
		snapshot_id,authority_shape,account_id,position,window_class,
		duration_minutes,observed_at_micros,resets_at_micros,
		observation_state,used_percent,error_code
	)
	SELECT snapshot_uuid,'conversation_account_registry',member.account_id,
		definition.position,definition.window_class,definition.duration_minutes,
		quota.observed_at_micros,quota.resets_at_micros,
		CASE WHEN quota.account_id IS NULL THEN 'missing'::decodex.account_registry_quota_state
			WHEN quota.error_code IS NULL THEN 'current'::decodex.account_registry_quota_state
			ELSE 'observation_error'::decodex.account_registry_quota_state END,
		quota.used_percent,quota.error_code
	FROM decodex.routing_snapshot_members AS member
	CROSS JOIN (VALUES
		(1::smallint,'five_hour'::decodex.quota_window_class,300::smallint),
		(2::smallint,'seven_day'::decodex.quota_window_class,10080::smallint)
	) AS definition(position,window_class,duration_minutes)
	LEFT JOIN decodex.account_quota_facts AS quota
		ON quota.account_id=member.account_id
		AND quota.duration_minutes=definition.duration_minutes
	WHERE member.snapshot_id=snapshot_uuid
	ORDER BY member.position,definition.position;

	core:=pg_catalog.jsonb_build_object(
		'operation','route_quick_task_initial',
		'authority_shape','conversation_account_registry',
		'snapshot_id',snapshot_uuid,
		'account_routing_revision',control_row.revision,
		'account_selection_mode',control_row.mode,
		'fixed_account_id',control_row.fixed_account_id,
		'task_role_profile_revision',task_profile_revision,
		'consumer_kind','conversation_turn',
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'turn_id',turn_uuid,
		'resolved_at_micros',(extract(epoch FROM resolved)*1000000)::bigint,
		'members',(
			SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
				'position',member.position,'account_id',member.account_id,
				'account_revision',member.account_revision,
				'display_label',member.display_label,
				'account_state',member.account_state,'blockers',member.blockers
			) ORDER BY member.position)
			FROM decodex.routing_snapshot_members AS member
			WHERE member.snapshot_id=snapshot_uuid
		),
		'quota_facts',(
			SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
				'account_id',quota.account_id,'position',quota.position,
				'window_class',quota.window_class,
				'duration_minutes',quota.duration_minutes,
				'observation_state',quota.observation_state,
				'used_percent',quota.used_percent,
				'observed_at_micros',quota.observed_at_micros,
				'resets_at_micros',quota.resets_at_micros,
				'error_code',quota.error_code
			) ORDER BY member.position,quota.position)
			FROM decodex.routing_snapshot_quota_facts AS quota
			JOIN decodex.routing_snapshot_members AS member USING(snapshot_id,account_id)
			WHERE quota.snapshot_id=snapshot_uuid
		)
	);
	disposition:='fresh'; response_bytes:=NULL; snapshot_envelope:=core;
	RETURN NEXT;
END
$_$;


--
-- Name: complete_quick_task_initial_route_exact(text, text, uuid, bigint, uuid, decodex.routing_decision_kind, uuid, jsonb, jsonb); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.complete_quick_task_initial_route_exact(p_protocol text, p_idempotency_key text, p_conversation_id uuid, p_expected_conversation_revision bigint, p_snapshot_id uuid, p_kind decodex.routing_decision_kind, p_selected_account_id uuid, p_causes jsonb, p_exclusions jsonb) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE receipt_row decodex.exact_command_receipts%ROWTYPE;
DECLARE snapshot_row decodex.routing_snapshots%ROWTYPE;
DECLARE decision_uuid uuid; operation_uuid uuid; decided timestamptz;
DECLARE activity_sequence bigint; outbox_id bigint;
DECLARE snapshot_value jsonb; payload jsonb; core jsonb; effect jsonb; response bytea;
BEGIN
	SELECT * INTO receipt_row
	FROM decodex.exact_command_receipts
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key
	FOR UPDATE;
	IF NOT FOUND OR receipt_row.receipt_state<>'executing'
		OR receipt_row.request_envelope<>pg_catalog.jsonb_build_object(
			'operation','route_quick_task_initial','protocol',p_protocol,
			'conversation_id',p_conversation_id,
			'conversation_revision',p_expected_conversation_revision
		)
	THEN
		RAISE EXCEPTION 'initial route completion has no matching executing receipt'
			USING ERRCODE='23514',CONSTRAINT='quick_task_initial_route_atomic';
	END IF;
	SELECT * INTO snapshot_row
	FROM decodex.routing_snapshots
	WHERE snapshot_id=p_snapshot_id
		AND authority_shape='conversation_account_registry'
		AND consumer_kind='conversation_turn'
		AND conversation_id=p_conversation_id
		AND conversation_revision=p_expected_conversation_revision
	FOR SHARE;
	IF NOT FOUND OR EXISTS (
		SELECT 1 FROM decodex.routing_decisions
		WHERE authority_shape='conversation_account_registry'
			AND conversation_id=p_conversation_id
	) OR p_kind NOT IN ('selected','waiting','no_route')
		OR (p_kind='selected') IS DISTINCT FROM (p_selected_account_id IS NOT NULL)
		OR p_causes IS NULL OR pg_catalog.jsonb_typeof(p_causes)<>'array'
		OR p_exclusions IS NULL OR pg_catalog.jsonb_typeof(p_exclusions)<>'array'
		OR decodex.has_credential_material(p_causes)
		OR decodex.has_credential_material(p_exclusions)
		OR (p_kind='selected' AND NOT EXISTS (
			SELECT 1 FROM decodex.routing_snapshot_members
			WHERE snapshot_id=p_snapshot_id AND account_id=p_selected_account_id
		))
	THEN
		RAISE EXCEPTION 'initial route completion is malformed or cross-linked'
			USING ERRCODE='23514',CONSTRAINT='quick_task_initial_route_atomic';
	END IF;

	decision_uuid:=pg_catalog.gen_random_uuid();
	operation_uuid:=pg_catalog.gen_random_uuid();
	decided:=snapshot_row.resolved_at;
	INSERT INTO decodex.routing_decision_member_refs(
		decision_id,snapshot_id,position,account_id
	)
	SELECT decision_uuid,snapshot_id,position,account_id
	FROM decodex.routing_snapshot_members
	WHERE snapshot_id=p_snapshot_id ORDER BY position;
	INSERT INTO decodex.routing_decision_quota_refs(
		decision_id,snapshot_id,authority_shape,account_id,position,
		window_class,duration_minutes,observed_at_micros,resets_at_micros,
		observation_state,used_percent,error_code
	)
	SELECT decision_uuid,snapshot_id,'conversation_account_registry',account_id,
		position,window_class,duration_minutes,observed_at_micros,resets_at_micros,
		observation_state,used_percent,error_code
	FROM decodex.routing_snapshot_quota_facts
	WHERE snapshot_id=p_snapshot_id ORDER BY account_id,position;
	INSERT INTO decodex.routing_decision_blocker_refs(
		decision_id,snapshot_id,account_id,position,blocker
	)
	SELECT decision_uuid,p_snapshot_id,(item.value->>'account_id')::uuid,
		pg_catalog.row_number() OVER (
			PARTITION BY item.value->>'account_id' ORDER BY item.ordinality
		)::integer,(item.value->>'blocker')::decodex.routing_blocker
	FROM pg_catalog.jsonb_array_elements(p_causes)
		WITH ORDINALITY AS item(value,ordinality)
	ORDER BY item.ordinality;
	INSERT INTO decodex.routing_decision_exclusions(
		decision_id,authority_shape,account_id,member_position,window_class,
		duration_minutes,used_percent,observed_at_micros,resets_at_micros,reason
	)
	SELECT decision_uuid,'conversation_account_registry',
		(item.value->>'account_id')::uuid,
		(item.value->>'member_position')::integer,
		(item.value->>'window_class')::decodex.quota_window_class,
		(item.value->>'duration_minutes')::smallint,
		(item.value->>'used_percent')::smallint,
		(item.value->>'observed_at_micros')::bigint,
		(item.value->>'resets_at_micros')::bigint,'usage_depleted'
	FROM pg_catalog.jsonb_array_elements(p_exclusions)
		WITH ORDINALITY AS item(value,ordinality)
	ORDER BY item.ordinality;
	INSERT INTO decodex.routing_decisions(
		decision_id,operation_id,authority_shape,snapshot_id,
		account_routing_revision,consumer_kind,conversation_id,
		conversation_revision,turn_id,kind,selected_account_id,decided_at
	) VALUES (
		decision_uuid,operation_uuid,'conversation_account_registry',p_snapshot_id,
		snapshot_row.account_routing_revision,'conversation_turn',p_conversation_id,
		p_expected_conversation_revision,snapshot_row.turn_id,p_kind,
		p_selected_account_id,decided
	);

	snapshot_value:=pg_catalog.jsonb_build_object(
		'snapshot_id',p_snapshot_id,
		'account_routing_revision',snapshot_row.account_routing_revision,
		'account_selection_mode',snapshot_row.account_selection_mode,
		'fixed_account_id',snapshot_row.fixed_account_id,
		'task_role_profile_revision',snapshot_row.task_role_profile_revision,
		'resolved_at_micros',(extract(epoch FROM snapshot_row.resolved_at)*1000000)::bigint,
		'members',(
			SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
				'position',member.position,'account_id',member.account_id,
				'account_revision',member.account_revision,
				'display_label',member.display_label,
				'account_state',member.account_state,'blockers',member.blockers
			) ORDER BY member.position)
			FROM decodex.routing_snapshot_members AS member
			WHERE member.snapshot_id=p_snapshot_id
		),
		'quota_facts',(
			SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
				'account_id',quota.account_id,'position',quota.position,
				'window_class',quota.window_class,
				'duration_minutes',quota.duration_minutes,
				'observation_state',quota.observation_state,
				'used_percent',quota.used_percent,
				'observed_at_micros',quota.observed_at_micros,
				'resets_at_micros',quota.resets_at_micros,
				'error_code',quota.error_code
			) ORDER BY member.position,quota.position)
			FROM decodex.routing_snapshot_quota_facts AS quota
			JOIN decodex.routing_snapshot_members AS member USING(snapshot_id,account_id)
			WHERE quota.snapshot_id=p_snapshot_id
		)
	);
	payload:=pg_catalog.jsonb_build_object(
		'kind','quick_task_initial_route_committed',
		'decision_id',decision_uuid,'operation_id',operation_uuid,
		'snapshot_id',p_snapshot_id,'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'turn_id',snapshot_row.turn_id,'decision_kind',p_kind,
		'selected_account_id',p_selected_account_id
	);
	INSERT INTO decodex.activity(
		aggregate_kind,aggregate_id,revision,event_kind,correlation_key,payload
	) VALUES (
		'routing_decision',decision_uuid::text,1,
		'quick_task_initial_route_committed',p_idempotency_key,payload
	) RETURNING sequence INTO activity_sequence;
	INSERT INTO decodex.outbox(
		effect_key,aggregate_kind,aggregate_id,aggregate_revision,payload
	) VALUES (
		'activity/'||activity_sequence::text,'routing_decision',decision_uuid::text,1,
		pg_catalog.jsonb_build_object(
			'activity_sequence',activity_sequence,
			'event_kind','quick_task_initial_route_committed',
			'aggregate_kind','routing_decision','aggregate_id',decision_uuid,
			'revision',1,'payload',payload
		)
	) RETURNING id INTO outbox_id;
	core:=pg_catalog.jsonb_build_object(
		'operation','route_quick_task_initial',
		'authority_shape','conversation_account_registry',
		'decision_id',decision_uuid,'operation_id',operation_uuid,
		'snapshot_id',p_snapshot_id,
		'account_routing_revision',snapshot_row.account_routing_revision,
		'consumer_kind','conversation_turn','conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'turn_id',snapshot_row.turn_id,'kind',p_kind,
		'selected_account_id',p_selected_account_id,
		'decided_at_micros',(extract(epoch FROM decided)*1000000)::bigint,
		'causes',p_causes,'exclusions',p_exclusions,
		'routing_snapshot',snapshot_value,
		'activity_sequence',activity_sequence,'outbox_id',outbox_id
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	response:=pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification','success','effect',effect
	)::text,'UTF8');
	UPDATE decodex.exact_command_receipts SET
		receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$_$;


--
-- Name: read_quick_task_initial_route_exact(uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.read_quick_task_initial_route_exact(p_conversation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE route_count bigint; route_effect jsonb;
BEGIN
	SELECT pg_catalog.count(*),(pg_catalog.array_agg(receipt.effect_envelope))[1]
	INTO route_count,route_effect
	FROM decodex.exact_command_receipts AS receipt
	WHERE receipt.receipt_state='completed_success'
		AND receipt.request_envelope->>'operation'='route_quick_task_initial'
		AND receipt.request_envelope->>'conversation_id'=p_conversation_id::text;
	IF route_count>1 THEN
		RAISE EXCEPTION 'initial Quick Task route receipt is not unique'
			USING ERRCODE='23514',CONSTRAINT='quick_task_initial_route_atomic';
	END IF;
	RETURN route_effect;
END
$$;


--
-- Name: bind_quick_task_continuation_exact(text, text, uuid, uuid, bigint, uuid, bigint, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.bind_quick_task_continuation_exact(p_protocol text, p_idempotency_key text, p_operation_id uuid, p_conversation_id uuid, p_expected_conversation_revision bigint, p_source_runtime_session_id uuid, p_expected_source_runtime_session_revision bigint, p_turn_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; replay bytea; binding record; decision_uuid uuid;
DECLARE decided timestamptz; decided_micros bigint;
DECLARE core jsonb; effect jsonb; response bytea;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','bind_quick_task_continuation',
		'protocol',p_protocol,
		'operation_id',p_operation_id,
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'source_runtime_session_id',p_source_runtime_session_id,
		'source_runtime_session_revision',p_expected_source_runtime_session_revision,
		'turn_id',p_turn_id
	);
	replay:=decodex.reserve_exact_routing_command(
		p_protocol,p_idempotency_key,request
	);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	IF p_operation_id IS NULL
		OR p_conversation_id IS NULL
		OR p_expected_conversation_revision IS NULL
		OR p_expected_conversation_revision<=0
		OR p_source_runtime_session_id IS NULL
		OR p_expected_source_runtime_session_revision IS NULL
		OR p_expected_source_runtime_session_revision<=0
		OR p_turn_id IS NULL
	THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'bind_quick_task_continuation',
			'malformed_input'
		);
	END IF;

	PERFORM 1
	FROM decodex.conversations
	WHERE conversation_id=p_conversation_id
		AND revision=p_expected_conversation_revision
		AND status='open'
	FOR UPDATE;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'bind_quick_task_continuation',
			'conversation_mismatch'
		);
	END IF;
	IF EXISTS (
		SELECT 1
		FROM decodex.routing_decisions
		WHERE authority_shape='conversation_continuation'
			AND conversation_id=p_conversation_id
			AND turn_id=p_turn_id
	) THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'bind_quick_task_continuation',
			'continuation_already_bound'
		);
	END IF;

	SELECT session.runtime_session_id,session.revision AS runtime_session_revision,
		session.account_snapshot_id,account.source_revision AS account_source_revision,
		session.profile_snapshot_id,profile.source_revision AS profile_source_revision,
		initial.decision_id AS initial_decision_id
	INTO binding
	FROM decodex.runtime_sessions AS session
	JOIN decodex.account_snapshots AS account
		ON account.account_snapshot_id=session.account_snapshot_id
	JOIN decodex.profile_snapshots AS profile
		ON profile.profile_snapshot_id=session.profile_snapshot_id
	JOIN decodex.routing_decisions AS initial
		ON initial.authority_shape='conversation_account_registry'
		AND initial.kind='selected'
		AND initial.conversation_id=session.conversation_id
	JOIN decodex.routing_snapshots AS snapshot
		ON snapshot.snapshot_id=initial.snapshot_id
		AND snapshot.authority_shape='conversation_account_registry'
	JOIN decodex.routing_snapshot_members AS selected
		ON selected.snapshot_id=snapshot.snapshot_id
		AND selected.account_id=initial.selected_account_id
	WHERE session.runtime_session_id=p_source_runtime_session_id
		AND session.revision=p_expected_source_runtime_session_revision
		AND session.conversation_id=p_conversation_id
		AND session.state='active'
		AND account.source_account_id=initial.selected_account_id
		AND account.source_revision=selected.account_revision
		AND profile.role='task'
		AND profile.source_revision=snapshot.task_role_profile_revision
		AND NOT EXISTS (
			SELECT 1
			FROM decodex.runtime_sessions AS other
			WHERE other.conversation_id=session.conversation_id
				AND other.runtime_session_id<>session.runtime_session_id
				AND other.state IN ('starting','active')
		)
		AND NOT EXISTS (
			SELECT 1 FROM decodex.turns AS turn_row
			WHERE turn_row.turn_id=p_turn_id
				AND NOT (
					turn_row.conversation_id=p_conversation_id
					AND turn_row.runtime_session_id=session.runtime_session_id
					AND turn_row.sequence>1
					AND turn_row.role='user'
					AND turn_row.possible_side_effects='unknown'
					AND turn_row.status='active'
					AND turn_row.revision=1
					AND turn_row.completed_at IS NULL
				)
		)
	FOR UPDATE OF session;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'bind_quick_task_continuation',
			'continuation_lineage_mismatch'
		);
	END IF;

	decided:=pg_catalog.clock_timestamp();
	decided_micros:=(extract(epoch FROM decided)*1000000)::bigint;
	decision_uuid:=pg_catalog.gen_random_uuid();
	INSERT INTO decodex.routing_decisions(
		decision_id,operation_id,authority_shape,source_runtime_session_id,
		source_runtime_session_revision,initial_decision_id,account_snapshot_id,
		account_snapshot_source_revision,profile_snapshot_id,
		profile_snapshot_source_revision,decided_at,consumer_kind,
		conversation_id,conversation_revision,turn_id
	) VALUES (
		decision_uuid,p_operation_id,'conversation_continuation',
		binding.runtime_session_id,binding.runtime_session_revision,
		binding.initial_decision_id,binding.account_snapshot_id,
		binding.account_source_revision,binding.profile_snapshot_id,
		binding.profile_source_revision,decided,'conversation_turn',
		p_conversation_id,p_expected_conversation_revision,p_turn_id
	);

	core:=pg_catalog.jsonb_build_object(
		'operation','bind_quick_task_continuation',
		'authority_shape','conversation_continuation',
		'decision_id',decision_uuid,
		'operation_id',p_operation_id,
		'consumer_kind','conversation_turn',
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'turn_id',p_turn_id,
		'source_runtime_session_id',binding.runtime_session_id,
		'source_runtime_session_revision',binding.runtime_session_revision,
		'initial_decision_id',binding.initial_decision_id,
		'account_snapshot_id',binding.account_snapshot_id,
		'account_snapshot_source_revision',binding.account_source_revision,
		'profile_snapshot_id',binding.profile_snapshot_id,
		'profile_snapshot_source_revision',binding.profile_source_revision,
		'decided_at_micros',decided_micros
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(
			public.digest(pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'
		)
	);
	response:=pg_catalog.convert_to(
		pg_catalog.jsonb_build_object('classification','success','effect',effect)::text,
		'UTF8'
	);
	UPDATE decodex.exact_command_receipts
	SET receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$$;


--
-- Name: resolve_routing_snapshot_exact(text, text, decodex.routing_authority_shape, uuid, bigint, bigint, decodex.provider_attempt_consumer_kind, uuid, bigint, uuid, bigint, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.resolve_routing_snapshot_exact(p_protocol text, p_idempotency_key text, p_authority_shape decodex.routing_authority_shape, p_routing_policy_id uuid, p_expected_routing_policy_revision bigint, p_expected_account_routing_revision bigint, p_consumer_kind decodex.provider_attempt_consumer_kind, p_conversation_id uuid, p_expected_conversation_revision bigint, p_source_runtime_session_id uuid, p_expected_source_runtime_session_revision bigint, p_turn_id uuid, p_managed_run_id uuid, p_expected_managed_run_revision bigint, p_managed_execution_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; replay bytea; policy_row record; run_row record;
DECLARE session_row record; resolved timestamptz;
DECLARE new_snapshot_id uuid; member record; evidence record; quota record;
DECLARE blockers decodex.routing_blocker[]; sticky_account uuid;
DECLARE core jsonb; effect jsonb; response bytea;
DECLARE source_session_id uuid; source_session_revision bigint;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','resolve_routing_snapshot',
		'protocol',p_protocol,
		'authority_shape',p_authority_shape,
		'routing_policy_id',p_routing_policy_id,
		'expected_routing_policy_revision',p_expected_routing_policy_revision,
		'expected_account_routing_revision',p_expected_account_routing_revision,
		'consumer_kind',p_consumer_kind,
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'source_runtime_session_id',p_source_runtime_session_id,
		'source_runtime_session_revision',p_expected_source_runtime_session_revision,
		'turn_id',p_turn_id,
		'managed_run_id',p_managed_run_id,
		'managed_run_revision',p_expected_managed_run_revision,
		'managed_execution_id',p_managed_execution_id
	);
	replay:=decodex.reserve_exact_routing_command(
		p_protocol,p_idempotency_key,request
	);
	IF replay IS NOT NULL THEN RETURN replay; END IF;

	IF p_authority_shape<>'managed_run_project_policy'
		OR p_routing_policy_id IS NULL
		OR p_expected_routing_policy_revision IS NULL
		OR p_expected_routing_policy_revision<=0
		OR p_expected_account_routing_revision IS NOT NULL
		OR p_consumer_kind<>'managed_run_execution'
		OR p_conversation_id IS NOT NULL
		OR p_expected_conversation_revision IS NOT NULL
		OR p_source_runtime_session_id IS NOT NULL
		OR p_expected_source_runtime_session_revision IS NOT NULL
		OR p_turn_id IS NOT NULL
		OR p_managed_run_id IS NULL
		OR p_expected_managed_run_revision IS NULL
		OR p_expected_managed_run_revision<=0
		OR p_managed_execution_id IS NULL
	THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'resolve_routing_snapshot','malformed_input'
		);
	END IF;

	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1338,
		pg_catalog.hashtext(COALESCE(p_conversation_id::text,p_managed_run_id::text))
	);
	PERFORM pg_catalog.pg_advisory_xact_lock(1356);
	LOCK TABLE decodex.accounts,decodex.quota_windows,decodex.policies,
		decodex.policy_revisions,decodex.role_profiles,decodex.role_profile_revisions,
		decodex.profile_snapshots,decodex.account_snapshots,decodex.runtime_sessions,
		decodex.conversations,decodex.routing_policy_heads,
		decodex.routing_policy_revisions,decodex.routing_policy_members,
		decodex.routing_policy_required_capabilities,
		decodex.routing_compatibility_evidence,
		decodex.routing_capability_evidence IN SHARE MODE;

	SELECT revision.project_id,revision.accepted_policy_id,
		revision.accepted_policy_revision,revision.required_role,
		revision.required_role_profile_revision,revision.required_build_id
	INTO policy_row
	FROM decodex.routing_policy_heads AS head
	JOIN decodex.routing_policy_revisions AS revision
		ON revision.routing_policy_id=head.routing_policy_id
		AND revision.revision=head.current_revision
	WHERE head.routing_policy_id=p_routing_policy_id
		AND head.current_revision=p_expected_routing_policy_revision
	FOR SHARE OF head,revision;
	IF NOT FOUND OR NOT EXISTS (
		SELECT 1 FROM decodex.policies
		WHERE policy_id=policy_row.accepted_policy_id
			AND project_id=policy_row.project_id
			AND current_revision=policy_row.accepted_policy_revision
	) OR NOT EXISTS (
		SELECT 1 FROM decodex.role_profiles
		WHERE role=policy_row.required_role
			AND current_revision=policy_row.required_role_profile_revision
	) THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'resolve_routing_snapshot',
			'routing_authority_mismatch'
		);
	END IF;

	SELECT * INTO run_row
	FROM decodex.managed_runs
	WHERE managed_run_id=p_managed_run_id
		AND revision=p_expected_managed_run_revision
	FOR SHARE;
	IF NOT FOUND OR run_row.project_id<>policy_row.project_id
		OR run_row.runtime_session_id IS NULL
		OR run_row.runtime_session_revision IS NULL
	THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'resolve_routing_snapshot',
			'managed_run_mismatch'
		);
	END IF;
	source_session_id:=run_row.runtime_session_id;
	source_session_revision:=run_row.runtime_session_revision;

	SELECT session.runtime_session_id,session.revision,session.conversation_id,
			session.account_snapshot_id,session.profile_snapshot_id,
			account.source_account_id,
			account.source_revision AS account_source_revision,
			account.display_label AS account_snapshot_display_label,
			account.observed_state AS account_snapshot_state,
			profile.role,profile.source_revision AS profile_source_revision
		INTO session_row
		FROM decodex.runtime_sessions AS session
		JOIN decodex.account_snapshots AS account USING(account_snapshot_id)
		JOIN decodex.profile_snapshots AS profile USING(profile_snapshot_id)
		WHERE session.runtime_session_id=source_session_id
			AND session.revision=source_session_revision
		FOR SHARE OF session,account,profile;
		IF NOT FOUND
			OR session_row.role<>policy_row.required_role
			OR session_row.profile_source_revision<>policy_row.required_role_profile_revision
			OR NOT EXISTS (
				SELECT 1 FROM decodex.accounts AS account
				WHERE account.account_id=session_row.source_account_id
					AND account.revision=session_row.account_source_revision
					AND account.display_label=session_row.account_snapshot_display_label
					AND account.state=session_row.account_snapshot_state
			)
			OR NOT EXISTS (
				SELECT 1 FROM decodex.routing_policy_members AS policy_member
				WHERE policy_member.routing_policy_id=p_routing_policy_id
					AND policy_member.routing_policy_revision=
						p_expected_routing_policy_revision
					AND policy_member.account_id=session_row.source_account_id
					AND policy_member.account_revision=session_row.account_source_revision
			)
		THEN
			RETURN decodex.complete_exact_routing_rejection(
				p_protocol,p_idempotency_key,'resolve_routing_snapshot',
				'sticky_provenance_mismatch'
			);
		END IF;

	sticky_account:=session_row.source_account_id;
	IF EXISTS (
		SELECT account_id,revision FROM decodex.accounts
		EXCEPT
		SELECT policy_member.account_id,policy_member.account_revision
		FROM decodex.routing_policy_members AS policy_member
		WHERE policy_member.routing_policy_id=p_routing_policy_id
			AND policy_member.routing_policy_revision=p_expected_routing_policy_revision
	) OR EXISTS (
		SELECT policy_member.account_id,policy_member.account_revision
		FROM decodex.routing_policy_members AS policy_member
		WHERE policy_member.routing_policy_id=p_routing_policy_id
			AND policy_member.routing_policy_revision=p_expected_routing_policy_revision
		EXCEPT
		SELECT account_id,revision FROM decodex.accounts
	) THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'resolve_routing_snapshot',
			'routing_authority_mismatch'
		);
	END IF;

	PERFORM 1
	FROM decodex.routing_policy_members AS policy_member
	JOIN decodex.accounts AS account USING(account_id)
	WHERE policy_member.routing_policy_id=p_routing_policy_id
		AND policy_member.routing_policy_revision=p_expected_routing_policy_revision
	ORDER BY policy_member.position
	FOR SHARE OF policy_member,account;
	PERFORM 1 FROM decodex.routing_compatibility_evidence
	WHERE account_id IN (
		SELECT account_id FROM decodex.routing_policy_members
		WHERE routing_policy_id=p_routing_policy_id
			AND routing_policy_revision=p_expected_routing_policy_revision
	) ORDER BY evidence_id FOR SHARE;
	PERFORM 1 FROM decodex.routing_capability_evidence
	WHERE evidence_id IN (
		SELECT evidence_id FROM decodex.routing_compatibility_evidence
		WHERE account_id IN (
			SELECT account_id FROM decodex.routing_policy_members
			WHERE routing_policy_id=p_routing_policy_id
				AND routing_policy_revision=p_expected_routing_policy_revision
		)
	) ORDER BY evidence_id,position FOR SHARE;
	PERFORM 1 FROM decodex.routing_policy_required_capabilities
	WHERE routing_policy_id=p_routing_policy_id
		AND routing_policy_revision=p_expected_routing_policy_revision
	ORDER BY position FOR SHARE;
	PERFORM 1 FROM decodex.quota_windows
	WHERE account_id IN (
		SELECT account_id FROM decodex.routing_policy_members
		WHERE routing_policy_id=p_routing_policy_id
			AND routing_policy_revision=p_expected_routing_policy_revision
	) ORDER BY account_id,window_class,duration_minutes FOR SHARE;

	resolved:=pg_catalog.clock_timestamp();
	INSERT INTO decodex.routing_snapshots(
		authority_shape,routing_policy_id,routing_policy_revision,accepted_policy_id,
		accepted_policy_revision,required_role,required_role_profile_revision,
		required_build_id,managed_run_id,managed_run_revision,
		runtime_session_id,runtime_session_revision,account_snapshot_id,
		account_snapshot_source_revision,profile_snapshot_id,
		profile_snapshot_source_revision,resolved_at,consumer_kind,
		conversation_id,conversation_revision,turn_id,managed_execution_id
	) VALUES (
		'managed_run_project_policy',p_routing_policy_id,p_expected_routing_policy_revision,
		policy_row.accepted_policy_id,policy_row.accepted_policy_revision,
		policy_row.required_role,policy_row.required_role_profile_revision,
		policy_row.required_build_id,p_managed_run_id,p_expected_managed_run_revision,
		session_row.runtime_session_id,session_row.revision,
		session_row.account_snapshot_id,session_row.account_source_revision,
		session_row.profile_snapshot_id,session_row.profile_source_revision,resolved,
		p_consumer_kind,p_conversation_id,p_expected_conversation_revision,
		p_turn_id,p_managed_execution_id
	) RETURNING snapshot_id INTO new_snapshot_id;

	FOR member IN
		SELECT policy_member.position,policy_member.account_id,
			policy_member.account_revision,policy_member.disposition,
			account.display_label,account.state,account.observed_at,
			account.revision AS current_account_revision
		FROM decodex.routing_policy_members AS policy_member
		JOIN decodex.accounts AS account USING(account_id)
		WHERE policy_member.routing_policy_id=p_routing_policy_id
			AND policy_member.routing_policy_revision=p_expected_routing_policy_revision
		ORDER BY policy_member.position
	LOOP
		blockers:=ARRAY[]::decodex.routing_blocker[];
		IF member.disposition='excluded' THEN
			blockers:=pg_catalog.array_append(
				blockers,'excluded_by_policy'::decodex.routing_blocker
			);
		END IF;
		IF member.account_revision<>member.current_account_revision THEN
			blockers:=pg_catalog.array_append(
				blockers,'account_stale'::decodex.routing_blocker
			);
		END IF;
		IF member.observed_at>resolved THEN
			blockers:=pg_catalog.array_append(
				blockers,'account_from_future'::decodex.routing_blocker
			);
		ELSIF resolved-member.observed_at>INTERVAL '300 seconds' THEN
			blockers:=pg_catalog.array_append(
				blockers,'account_stale'::decodex.routing_blocker
			);
		END IF;
		blockers:=pg_catalog.array_append(blockers,CASE member.state
			WHEN 'unavailable' THEN 'account_unavailable'::decodex.routing_blocker
			WHEN 'unknown' THEN 'account_unknown'::decodex.routing_blocker
			WHEN 'depleted' THEN 'account_depleted'::decodex.routing_blocker
			WHEN 'auth_failed' THEN 'account_auth_failed'::decodex.routing_blocker
			WHEN 'plugin_unready' THEN 'account_plugin_unready'::decodex.routing_blocker
			WHEN 'disabled' THEN 'account_disabled'::decodex.routing_blocker
			ELSE NULL
		END);
		blockers:=pg_catalog.array_remove(blockers,NULL);

		SELECT candidate.* INTO evidence
		FROM decodex.routing_compatibility_evidence AS candidate
		WHERE candidate.account_id=member.account_id
		ORDER BY candidate.evidence_revision DESC LIMIT 1;
		IF NOT FOUND THEN
			blockers:=pg_catalog.array_append(
				blockers,'evidence_missing'::decodex.routing_blocker
			);
		ELSE
			IF evidence.ingested_at>resolved THEN
				blockers:=pg_catalog.array_append(
					blockers,'evidence_from_future'::decodex.routing_blocker
				);
			ELSIF resolved-evidence.ingested_at>INTERVAL '300 seconds' THEN
				blockers:=pg_catalog.array_append(
					blockers,'evidence_stale'::decodex.routing_blocker
				);
			END IF;
			IF evidence.account_revision<>member.current_account_revision THEN
				blockers:=pg_catalog.array_append(
					blockers,'evidence_account_mismatch'::decodex.routing_blocker
				);
			END IF;
			IF evidence.role<>policy_row.required_role
				OR evidence.role_profile_revision<>
					policy_row.required_role_profile_revision
			THEN
				blockers:=pg_catalog.array_append(
					blockers,'evidence_profile_mismatch'::decodex.routing_blocker
				);
			END IF;
			IF evidence.build_id<>policy_row.required_build_id THEN
				blockers:=pg_catalog.array_append(
					blockers,'evidence_build_mismatch'::decodex.routing_blocker
				);
			END IF;
		END IF;
		IF EXISTS (
			SELECT 1
			FROM decodex.routing_policy_required_capabilities AS required
			LEFT JOIN decodex.routing_capability_evidence AS actual
				ON actual.evidence_id=evidence.evidence_id
				AND actual.capability=required.capability
			WHERE required.routing_policy_id=p_routing_policy_id
				AND required.routing_policy_revision=p_expected_routing_policy_revision
				AND actual.state IS DISTINCT FROM 'supported'
		) THEN
			blockers:=pg_catalog.array_append(
				blockers,'required_capability_unsatisfied'::decodex.routing_blocker
			);
		END IF;

		FOR quota IN
			SELECT definition.window_class,definition.duration_minutes,
				quota_window.revision,quota_window.remaining_percent,
				quota_window.resets_at,quota_window.observed_at,
				quota_window.confidence
			FROM (
				VALUES
					('five_hour'::decodex.quota_window_class,300::smallint),
					('seven_day'::decodex.quota_window_class,10080::smallint)
			) AS definition(window_class,duration_minutes)
			LEFT JOIN decodex.quota_windows AS quota_window
				ON quota_window.account_id=member.account_id
				AND quota_window.window_class=definition.window_class
				AND quota_window.duration_minutes=definition.duration_minutes
		LOOP
			IF quota.revision IS NULL THEN
				blockers:=pg_catalog.array_append(blockers,CASE quota.window_class
					WHEN 'five_hour' THEN
						'quota_five_hour_missing'::decodex.routing_blocker
					ELSE 'quota_seven_day_missing'::decodex.routing_blocker
				END);
			ELSIF quota.observed_at>resolved THEN
				blockers:=pg_catalog.array_append(blockers,CASE quota.window_class
					WHEN 'five_hour' THEN
						'quota_five_hour_from_future'::decodex.routing_blocker
					ELSE 'quota_seven_day_from_future'::decodex.routing_blocker
				END);
			ELSIF resolved-quota.observed_at>INTERVAL '300 seconds' THEN
				blockers:=pg_catalog.array_append(blockers,CASE quota.window_class
					WHEN 'five_hour' THEN
						'quota_five_hour_stale'::decodex.routing_blocker
					ELSE 'quota_seven_day_stale'::decodex.routing_blocker
				END);
			ELSIF quota.remaining_percent IS NULL OR quota.confidence<>'high' THEN
				blockers:=pg_catalog.array_append(blockers,CASE quota.window_class
					WHEN 'five_hour' THEN
						'quota_five_hour_unknown'::decodex.routing_blocker
					ELSE 'quota_seven_day_unknown'::decodex.routing_blocker
				END);
			ELSIF quota.resets_at IS NULL OR quota.resets_at<=resolved THEN
				blockers:=pg_catalog.array_append(blockers,CASE quota.window_class
					WHEN 'five_hour' THEN
						'quota_five_hour_reset_elapsed'::decodex.routing_blocker
					ELSE 'quota_seven_day_reset_elapsed'::decodex.routing_blocker
				END);
			ELSIF quota.remaining_percent=0 THEN
				blockers:=pg_catalog.array_append(blockers,CASE quota.window_class
					WHEN 'five_hour' THEN
						'quota_five_hour_depleted'::decodex.routing_blocker
					ELSE 'quota_seven_day_depleted'::decodex.routing_blocker
				END);
			END IF;
		END LOOP;

		SELECT pg_catalog.array_agg(DISTINCT blocker ORDER BY blocker)
		INTO blockers
		FROM pg_catalog.unnest(blockers) AS item(blocker);
		blockers:=COALESCE(blockers,ARRAY[]::decodex.routing_blocker[]);
		INSERT INTO decodex.routing_snapshot_members(
			snapshot_id,authority_shape,position,account_id,disposition,account_revision,
			display_label,account_state,account_observed_at_utc,evidence_id,
			evidence_revision,evidence_account_revision,evidence_role,
			evidence_role_profile_revision,evidence_build_id,process_id,
			schema_fingerprint,sticky,blockers
		) VALUES (
			new_snapshot_id,'managed_run_project_policy',member.position,
			member.account_id,member.disposition,
			member.current_account_revision,member.display_label,member.state,
			decodex.rfc3339_utc(member.observed_at),evidence.evidence_id,
			evidence.evidence_revision,evidence.account_revision,evidence.role,
			evidence.role_profile_revision,evidence.build_id,evidence.process_id,
			evidence.schema_fingerprint,COALESCE(member.account_id=sticky_account,false),blockers
		);
		INSERT INTO decodex.routing_snapshot_quota_facts(
			snapshot_id,authority_shape,account_id,position,window_class,
			duration_minutes,observation_revision,remaining_percent,
			resets_at_micros,observed_at_micros,confidence
		)
		SELECT new_snapshot_id,'managed_run_project_policy',member.account_id,
			definition.position,
			definition.window_class,definition.duration_minutes,quota_window.revision,
			quota_window.remaining_percent,
			CASE WHEN quota_window.resets_at IS NULL THEN NULL
				ELSE (extract(epoch FROM quota_window.resets_at)*1000000)::bigint END,
			CASE WHEN quota_window.observed_at IS NULL THEN NULL
				ELSE (extract(epoch FROM quota_window.observed_at)*1000000)::bigint END,
			quota_window.confidence
		FROM (
			VALUES
				(1::smallint,'five_hour'::decodex.quota_window_class,300::smallint),
				(2::smallint,'seven_day'::decodex.quota_window_class,10080::smallint)
		) AS definition(position,window_class,duration_minutes)
		LEFT JOIN decodex.quota_windows AS quota_window
			ON quota_window.account_id=member.account_id
			AND quota_window.window_class=definition.window_class
			AND quota_window.duration_minutes=definition.duration_minutes;
		INSERT INTO decodex.routing_snapshot_capability_facts
		SELECT new_snapshot_id,member.account_id,definition.position,
			definition.capability,required.capability IS NOT NULL,actual.state
		FROM (
			VALUES
				(1::smallint,'initialize'::decodex.codex_capability),
				(2::smallint,'account_read'),(3::smallint,'thread_list'),
				(4::smallint,'thread_read'),(5::smallint,'thread_archive'),
				(6::smallint,'paginated_history'),
				(7::smallint,'native_collaboration'),(8::smallint,'thread_search')
		) AS definition(position,capability)
		LEFT JOIN decodex.routing_policy_required_capabilities AS required
			ON required.routing_policy_id=p_routing_policy_id
			AND required.routing_policy_revision=p_expected_routing_policy_revision
			AND required.capability=definition.capability
		LEFT JOIN decodex.routing_capability_evidence AS actual
			ON actual.evidence_id=evidence.evidence_id
			AND actual.capability=definition.capability;
		INSERT INTO decodex.routing_snapshot_blockers
		SELECT new_snapshot_id,member.account_id,ordinality::integer,blocker
		FROM pg_catalog.unnest(blockers) WITH ORDINALITY
			AS item(blocker,ordinality);
	END LOOP;

	core:=pg_catalog.jsonb_build_object(
		'operation','resolve_routing_snapshot',
		'authority_shape','managed_run_project_policy',
		'snapshot_id',new_snapshot_id,
		'routing_policy_id',p_routing_policy_id,
		'routing_policy_revision',p_expected_routing_policy_revision,
		'accepted_policy_id',policy_row.accepted_policy_id,
		'accepted_policy_revision',policy_row.accepted_policy_revision,
		'required_role',policy_row.required_role,
		'required_role_profile_revision',policy_row.required_role_profile_revision,
		'required_build_id',policy_row.required_build_id,
		'consumer_kind',p_consumer_kind,
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'turn_id',p_turn_id,
		'managed_run_id',p_managed_run_id,
		'managed_run_revision',p_expected_managed_run_revision,
		'managed_execution_id',p_managed_execution_id,
		'runtime_session_id',session_row.runtime_session_id,
		'runtime_session_revision',session_row.revision,
		'account_snapshot_id',session_row.account_snapshot_id,
		'account_snapshot_source_revision',session_row.account_source_revision,
		'profile_snapshot_id',session_row.profile_snapshot_id,
		'profile_snapshot_source_revision',session_row.profile_source_revision,
		'resolved_at_micros',(extract(epoch FROM resolved)*1000000)::bigint,
		'members',(
			SELECT pg_catalog.jsonb_agg(
				pg_catalog.to_jsonb(member_row)-'authority_shape' ORDER BY position
			)
			FROM decodex.routing_snapshot_members AS member_row
			WHERE snapshot_id=new_snapshot_id
		),
		'quota_facts',(
			SELECT pg_catalog.jsonb_agg(
				pg_catalog.to_jsonb(quota_row)-'authority_shape'-'observation_state'-
					'used_percent'-'error_code'
				ORDER BY snapshot_member.position,quota_row.position
			)
			FROM decodex.routing_snapshot_quota_facts AS quota_row
			JOIN decodex.routing_snapshot_members AS snapshot_member
				USING(snapshot_id,account_id)
			WHERE quota_row.snapshot_id=new_snapshot_id
		),
		'capability_facts',(
			SELECT pg_catalog.jsonb_agg(
				pg_catalog.to_jsonb(capability_row)
				ORDER BY snapshot_member.position,capability_row.position
			)
			FROM decodex.routing_snapshot_capability_facts AS capability_row
			JOIN decodex.routing_snapshot_members AS snapshot_member
				USING(snapshot_id,account_id)
			WHERE capability_row.snapshot_id=new_snapshot_id
		),
		'blockers',(
			SELECT COALESCE(
				pg_catalog.jsonb_agg(
					pg_catalog.to_jsonb(blocker_row)
					ORDER BY snapshot_member.position,blocker_row.position
				),
				'[]'::jsonb
			)
			FROM decodex.routing_snapshot_blockers AS blocker_row
			JOIN decodex.routing_snapshot_members AS snapshot_member
				USING(snapshot_id,account_id)
			WHERE blocker_row.snapshot_id=new_snapshot_id
		)
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(
			public.digest(pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex'
		)
	);
	response:=pg_catalog.convert_to(
		pg_catalog.jsonb_build_object(
			'classification','success','effect',effect
		)::text,
		'UTF8'
	);
	UPDATE decodex.exact_command_receipts
	SET receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol
		AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$$;


--
-- Name: rfc3339_utc(timestamp with time zone); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.rfc3339_utc(value timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
	SELECT to_char(value AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
$$;


--
-- Name: route_account_exact(text, text, uuid, decodex.routing_authority_shape, uuid, bigint, bigint, decodex.provider_attempt_consumer_kind, uuid, bigint, uuid, bigint, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.route_account_exact(p_protocol text, p_idempotency_key text, p_operation_id uuid, p_authority_shape decodex.routing_authority_shape, p_routing_policy_id uuid, p_expected_routing_policy_revision bigint, p_expected_account_routing_revision bigint, p_consumer_kind decodex.provider_attempt_consumer_kind, p_conversation_id uuid, p_expected_conversation_revision bigint, p_source_runtime_session_id uuid, p_expected_source_runtime_session_revision bigint, p_turn_id uuid, p_managed_run_id uuid, p_expected_managed_run_revision bigint, p_managed_execution_id uuid) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE request jsonb; replay bytea; snapshot_row decodex.routing_snapshots%ROWTYPE;
DECLARE run_row decodex.managed_runs%ROWTYPE; selected_account uuid;
DECLARE selected_position integer; decided timestamptz; decided_micros bigint;
DECLARE decision_kind text; no_route_value text; ready_micros bigint;
DECLARE decision_uuid uuid; core jsonb; effect jsonb; response bytea;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','route_account',
		'protocol',p_protocol,
		'operation_id',p_operation_id,
		'authority_shape',p_authority_shape,
		'routing_policy_id',p_routing_policy_id,
		'expected_routing_policy_revision',p_expected_routing_policy_revision,
		'expected_account_routing_revision',p_expected_account_routing_revision,
		'consumer_kind',p_consumer_kind,
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'source_runtime_session_id',p_source_runtime_session_id,
		'source_runtime_session_revision',p_expected_source_runtime_session_revision,
		'turn_id',p_turn_id,
		'managed_run_id',p_managed_run_id,
		'managed_run_revision',p_expected_managed_run_revision,
		'managed_execution_id',p_managed_execution_id
	);
	replay:=decodex.reserve_exact_routing_command(
		p_protocol,p_idempotency_key,request
	);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	IF p_operation_id IS NULL
		OR p_authority_shape<>'managed_run_project_policy'
		OR p_routing_policy_id IS NULL
		OR p_expected_routing_policy_revision IS NULL
		OR p_expected_routing_policy_revision<=0
		OR p_expected_account_routing_revision IS NOT NULL
		OR p_consumer_kind<>'managed_run_execution'
		OR p_conversation_id IS NOT NULL
		OR p_expected_conversation_revision IS NOT NULL
		OR p_source_runtime_session_id IS NOT NULL
		OR p_expected_source_runtime_session_revision IS NOT NULL
		OR p_turn_id IS NOT NULL
		OR p_managed_run_id IS NULL
		OR p_expected_managed_run_revision IS NULL
		OR p_expected_managed_run_revision<=0
		OR p_managed_execution_id IS NULL
	THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_account','malformed_input'
		);
	END IF;

	PERFORM pg_catalog.pg_advisory_xact_lock_shared(1400);
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1338,
		pg_catalog.hashtext(COALESCE(p_conversation_id::text,p_managed_run_id::text))
	);
	PERFORM pg_catalog.pg_advisory_xact_lock(1356);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1359,pg_catalog.hashtext(p_operation_id::text)
	);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1401,
		pg_catalog.hashtext(
			p_consumer_kind::text||':'||
			COALESCE(p_conversation_id::text,p_managed_run_id::text)
		)
	);
	LOCK TABLE decodex.accounts,decodex.quota_windows,
		decodex.routing_policy_heads,decodex.policies,decodex.policy_revisions,
		decodex.role_profiles,decodex.role_profile_revisions,
		decodex.profile_snapshots,decodex.account_snapshots,
		decodex.runtime_sessions,decodex.conversations,
		decodex.routing_policy_revisions,decodex.routing_policy_members,
		decodex.routing_policy_required_capabilities,
		decodex.routing_compatibility_evidence,
		decodex.routing_capability_evidence,decodex.routing_snapshots,
		decodex.routing_snapshot_members,decodex.routing_snapshot_quota_facts,
		decodex.routing_snapshot_capability_facts,
		decodex.routing_snapshot_blockers,decodex.process_generations,
		decodex.process_generation_execution_epochs,decodex.provider_attempts
		IN SHARE MODE;

	PERFORM 1 FROM decodex.routing_policy_heads
	WHERE routing_policy_id=p_routing_policy_id
		AND current_revision=p_expected_routing_policy_revision
	FOR SHARE;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_account','stale_routing_policy'
		);
	END IF;
	SELECT * INTO run_row FROM decodex.managed_runs
	WHERE managed_run_id=p_managed_run_id
		AND revision=p_expected_managed_run_revision
	FOR SHARE;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_account','stale_consumer'
		);
	END IF;

	SELECT snapshot.* INTO snapshot_row
	FROM decodex.routing_snapshots AS snapshot
	WHERE snapshot.authority_shape='managed_run_project_policy'
		AND snapshot.routing_policy_id=p_routing_policy_id
		AND snapshot.routing_policy_revision=p_expected_routing_policy_revision
		AND (
			snapshot.consumer_kind,
			snapshot.conversation_id,
			snapshot.conversation_revision,
			snapshot.turn_id,
			snapshot.managed_run_id,
			snapshot.managed_run_revision,
			snapshot.managed_execution_id
		) IS NOT DISTINCT FROM (
			p_consumer_kind,
			p_conversation_id,
			p_expected_conversation_revision,
			p_turn_id,
			p_managed_run_id,
			p_expected_managed_run_revision,
			p_managed_execution_id
		)
	ORDER BY snapshot.resolved_at DESC,snapshot.snapshot_id
	LIMIT 1 FOR SHARE;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_account','snapshot_missing'
		);
	END IF;
	IF NOT EXISTS (
		SELECT 1 FROM decodex.policies
		WHERE policy_id=snapshot_row.accepted_policy_id
			AND current_revision=snapshot_row.accepted_policy_revision
		FOR SHARE
	) OR NOT EXISTS (
		SELECT 1 FROM decodex.role_profiles
		WHERE role=snapshot_row.required_role
			AND current_revision=snapshot_row.required_role_profile_revision
		FOR SHARE
	) OR (
		snapshot_row.runtime_session_id IS NOT NULL
		AND NOT EXISTS (
			SELECT 1 FROM decodex.runtime_sessions
			WHERE runtime_session_id=snapshot_row.runtime_session_id
				AND revision=snapshot_row.runtime_session_revision
			FOR SHARE
		)
	) THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_account',
			'concurrent_authority_change'
		);
	END IF;

	decided:=pg_catalog.clock_timestamp();
	decided_micros:=(extract(epoch FROM decided)*1000000)::bigint;
	IF EXISTS (
		SELECT account_id,revision FROM decodex.accounts
		EXCEPT
		SELECT account_id,account_revision
		FROM decodex.routing_policy_members
		WHERE routing_policy_id=p_routing_policy_id
			AND routing_policy_revision=p_expected_routing_policy_revision
	) OR EXISTS (
		SELECT account_id,account_revision
		FROM decodex.routing_policy_members
		WHERE routing_policy_id=p_routing_policy_id
			AND routing_policy_revision=p_expected_routing_policy_revision
		EXCEPT
		SELECT account_id,revision FROM decodex.accounts
	) OR EXISTS (
		SELECT position,account_id,account_revision,disposition
		FROM decodex.routing_policy_members
		WHERE routing_policy_id=p_routing_policy_id
			AND routing_policy_revision=p_expected_routing_policy_revision
		EXCEPT
		SELECT position,account_id,account_revision,disposition
		FROM decodex.routing_snapshot_members
		WHERE snapshot_id=snapshot_row.snapshot_id
	) OR EXISTS (
		SELECT 1
		FROM decodex.routing_snapshot_members AS member
		LEFT JOIN decodex.accounts AS account
			ON account.account_id=member.account_id
		WHERE member.snapshot_id=snapshot_row.snapshot_id
			AND (
				account.account_id IS NULL
				OR account.revision<>member.account_revision
				OR account.state<>member.account_state
				OR decodex.rfc3339_utc(account.observed_at)<>
					member.account_observed_at_utc
				OR account.observed_at>decided
				OR decided-account.observed_at>INTERVAL '300 seconds'
			)
	) OR EXISTS (
		SELECT 1
		FROM decodex.routing_snapshot_members AS member
		LEFT JOIN LATERAL (
			SELECT evidence_id,evidence_revision,ingested_at
			FROM decodex.routing_compatibility_evidence
			WHERE account_id=member.account_id
			ORDER BY evidence_revision DESC LIMIT 1
		) AS current_evidence ON true
		WHERE member.snapshot_id=snapshot_row.snapshot_id
			AND (
				member.evidence_id IS DISTINCT FROM current_evidence.evidence_id
				OR member.evidence_revision IS DISTINCT FROM
					current_evidence.evidence_revision
				OR (
					member.evidence_id IS NOT NULL
					AND (
						current_evidence.ingested_at>decided
						OR decided-current_evidence.ingested_at>
							INTERVAL '300 seconds'
					)
				)
			)
	) OR EXISTS (
		SELECT 1
		FROM decodex.routing_snapshot_quota_facts AS fact
		LEFT JOIN decodex.quota_windows AS quota
			ON quota.account_id=fact.account_id
			AND quota.window_class=fact.window_class
			AND quota.duration_minutes=fact.duration_minutes
		WHERE fact.snapshot_id=snapshot_row.snapshot_id
			AND (
				(fact.observation_revision IS NULL)<>(quota.account_id IS NULL)
				OR fact.observation_revision IS DISTINCT FROM quota.revision
				OR fact.remaining_percent IS DISTINCT FROM quota.remaining_percent
				OR fact.observed_at_micros IS DISTINCT FROM
					(extract(epoch FROM quota.observed_at)*1000000)::bigint
				OR fact.resets_at_micros IS DISTINCT FROM
					(extract(epoch FROM quota.resets_at)*1000000)::bigint
				OR fact.confidence IS DISTINCT FROM quota.confidence
			)
	) THEN
		RETURN decodex.complete_exact_routing_rejection(
			p_protocol,p_idempotency_key,'route_account',
			'concurrent_authority_change'
		);
	END IF;

	decision_uuid:=pg_catalog.gen_random_uuid();
	INSERT INTO decodex.routing_decision_member_refs(
		decision_id,snapshot_id,position,account_id
	)
	SELECT decision_uuid,snapshot_id,position,account_id
	FROM decodex.routing_snapshot_members
	WHERE snapshot_id=snapshot_row.snapshot_id
	ORDER BY position;
	INSERT INTO decodex.routing_decision_quota_refs(
		decision_id,snapshot_id,authority_shape,account_id,position,window_class,
		duration_minutes,observation_revision,remaining_percent,
		observed_at_micros,resets_at_micros,confidence,source_id,
		timestamp_precision,raw_observed_at,raw_resets_at
	)
	SELECT decision_uuid,fact.snapshot_id,'managed_run_project_policy',
		fact.account_id,fact.position,
		fact.window_class,fact.duration_minutes,fact.observation_revision,
		fact.remaining_percent,fact.observed_at_micros,fact.resets_at_micros,
		fact.confidence,
		CASE WHEN quota.metadata->>'timestamp_precision'='unix_microsecond'
			AND quota.metadata->>'evidence_revision'=
				fact.observation_revision::text
			AND quota.metadata->>'source_id'<>''
			AND pg_catalog.octet_length(quota.metadata->>'source_id')<=256
			AND NOT decodex.has_credential_material(quota.metadata->>'source_id')
			AND quota.metadata->>'raw_observed_at'=fact.observed_at_micros::text
			AND quota.metadata->>'raw_resets_at'=fact.resets_at_micros::text
			THEN quota.metadata->>'source_id' END,
		CASE WHEN quota.metadata->>'timestamp_precision'='unix_microsecond'
			AND quota.metadata->>'evidence_revision'=
				fact.observation_revision::text
			AND quota.metadata->>'source_id'<>''
			AND pg_catalog.octet_length(quota.metadata->>'source_id')<=256
			AND NOT decodex.has_credential_material(quota.metadata->>'source_id')
			AND quota.metadata->>'raw_observed_at'=fact.observed_at_micros::text
			AND quota.metadata->>'raw_resets_at'=fact.resets_at_micros::text
			THEN 'unix_microsecond' END,
		CASE WHEN quota.metadata->>'timestamp_precision'='unix_microsecond'
			AND quota.metadata->>'evidence_revision'=
				fact.observation_revision::text
			AND quota.metadata->>'source_id'<>''
			AND pg_catalog.octet_length(quota.metadata->>'source_id')<=256
			AND NOT decodex.has_credential_material(quota.metadata->>'source_id')
			AND quota.metadata->>'raw_observed_at'=fact.observed_at_micros::text
			AND quota.metadata->>'raw_resets_at'=fact.resets_at_micros::text
			THEN quota.metadata->>'raw_observed_at' END,
		CASE WHEN quota.metadata->>'timestamp_precision'='unix_microsecond'
			AND quota.metadata->>'evidence_revision'=
				fact.observation_revision::text
			AND quota.metadata->>'source_id'<>''
			AND pg_catalog.octet_length(quota.metadata->>'source_id')<=256
			AND NOT decodex.has_credential_material(quota.metadata->>'source_id')
			AND quota.metadata->>'raw_observed_at'=fact.observed_at_micros::text
			AND quota.metadata->>'raw_resets_at'=fact.resets_at_micros::text
			THEN quota.metadata->>'raw_resets_at' END
	FROM decodex.routing_snapshot_quota_facts AS fact
	LEFT JOIN decodex.quota_windows AS quota
		ON quota.account_id=fact.account_id
		AND quota.window_class=fact.window_class
		AND quota.duration_minutes=fact.duration_minutes
	WHERE fact.snapshot_id=snapshot_row.snapshot_id
	ORDER BY fact.account_id,fact.position;
	INSERT INTO decodex.routing_decision_capability_refs
	SELECT decision_uuid,snapshot_id,account_id,position,capability,
		applicable,evidence_state
	FROM decodex.routing_snapshot_capability_facts
	WHERE snapshot_id=snapshot_row.snapshot_id
	ORDER BY account_id,position;
	INSERT INTO decodex.routing_decision_blocker_refs
	SELECT decision_uuid,blocker.snapshot_id,blocker.account_id,
		blocker.position,blocker.blocker
	FROM decodex.routing_snapshot_blockers AS blocker
	JOIN decodex.routing_snapshot_members AS member
		ON member.snapshot_id=blocker.snapshot_id
		AND member.account_id=blocker.account_id
	WHERE blocker.snapshot_id=snapshot_row.snapshot_id
		AND (
			member.disposition='excluded'
			OR blocker.blocker::text NOT IN (
				'quota_five_hour_missing','quota_five_hour_from_future',
				'quota_five_hour_stale','quota_five_hour_unknown',
				'quota_five_hour_reset_elapsed','quota_five_hour_depleted',
				'quota_seven_day_missing','quota_seven_day_from_future',
				'quota_seven_day_stale','quota_seven_day_unknown',
				'quota_seven_day_reset_elapsed','quota_seven_day_depleted'
			)
		)
	ORDER BY blocker.account_id,blocker.position;

	-- V16 classifies both quota windows again at its own database-authored instant. A fact that
	-- was current at V14 can become stale or reset-expired before V16 commits. Retain that exact
	-- duration-typed cause instead of producing an empty or falsely pure projection.
	WITH classified AS (
		SELECT fact.account_id,fact.position AS quota_position,
			CASE
				WHEN fact.observation_revision IS NULL THEN CASE fact.window_class
					WHEN 'five_hour' THEN
						'quota_five_hour_missing'::decodex.routing_blocker
					ELSE 'quota_seven_day_missing'::decodex.routing_blocker
				END
				WHEN fact.observed_at_micros IS NULL
					OR fact.remaining_percent IS NULL
					OR fact.confidence IS DISTINCT FROM 'high'
				THEN CASE fact.window_class
					WHEN 'five_hour' THEN
						'quota_five_hour_unknown'::decodex.routing_blocker
					ELSE 'quota_seven_day_unknown'::decodex.routing_blocker
				END
				WHEN fact.observed_at_micros>decided_micros THEN CASE fact.window_class
					WHEN 'five_hour' THEN
						'quota_five_hour_from_future'::decodex.routing_blocker
					ELSE 'quota_seven_day_from_future'::decodex.routing_blocker
				END
				WHEN decided_micros-fact.observed_at_micros>300000000 THEN
					CASE fact.window_class
						WHEN 'five_hour' THEN
							'quota_five_hour_stale'::decodex.routing_blocker
						ELSE 'quota_seven_day_stale'::decodex.routing_blocker
					END
				WHEN fact.resets_at_micros IS NULL
					OR fact.resets_at_micros<=decided_micros
				THEN CASE fact.window_class
					WHEN 'five_hour' THEN
						'quota_five_hour_reset_elapsed'::decodex.routing_blocker
					ELSE 'quota_seven_day_reset_elapsed'::decodex.routing_blocker
				END
				WHEN fact.remaining_percent=0 THEN CASE fact.window_class
					WHEN 'five_hour' THEN
						'quota_five_hour_depleted'::decodex.routing_blocker
					ELSE 'quota_seven_day_depleted'::decodex.routing_blocker
				END
			END AS blocker
		FROM decodex.routing_decision_quota_refs AS fact
		JOIN decodex.routing_snapshot_members AS member
			ON member.snapshot_id=fact.snapshot_id
			AND member.account_id=fact.account_id
		WHERE fact.decision_id=decision_uuid
			AND member.disposition='included'
	),
	novel AS (
		SELECT classified.account_id,classified.quota_position,classified.blocker
		FROM classified
		WHERE classified.blocker IS NOT NULL
			AND NOT EXISTS (
				SELECT 1
				FROM decodex.routing_decision_blocker_refs AS existing
				WHERE existing.decision_id=decision_uuid
					AND existing.account_id=classified.account_id
					AND existing.blocker=classified.blocker
			)
	),
	positioned AS (
		SELECT novel.*,
			(COALESCE((
				SELECT pg_catalog.max(existing.position)
				FROM decodex.routing_decision_blocker_refs AS existing
				WHERE existing.decision_id=decision_uuid
					AND existing.account_id=novel.account_id
			),0)+pg_catalog.row_number() OVER (
				PARTITION BY novel.account_id ORDER BY novel.quota_position
			))::integer AS blocker_position
		FROM novel
	)
	INSERT INTO decodex.routing_decision_blocker_refs(
		decision_id,snapshot_id,account_id,position,blocker
	)
	SELECT decision_uuid,snapshot_row.snapshot_id,account_id,
		blocker_position,blocker
	FROM positioned
	ORDER BY account_id,blocker_position;

	-- Preserve ManagedRun domain blockers without allowing them to impersonate positive quota.
	IF p_consumer_kind::text='managed_run_execution'
		AND run_row.lifecycle='waiting'
	THEN
		INSERT INTO decodex.routing_decision_blocker_refs(
			decision_id,snapshot_id,account_id,position,blocker
		)
		SELECT decision_uuid,snapshot_row.snapshot_id,member.account_id,
			COALESCE((
				SELECT pg_catalog.max(existing.position)
				FROM decodex.routing_decision_blocker_refs AS existing
				WHERE existing.decision_id=decision_uuid
					AND existing.account_id=member.account_id
			),0)+1,
			cause.blocker
		FROM decodex.routing_snapshot_members AS member
		CROSS JOIN LATERAL (
			SELECT CASE run_row.wait_reason::text
				WHEN 'usage' THEN CASE WHEN EXISTS (
					SELECT 1
					FROM decodex.routing_snapshot_blockers AS quota_blocker
					WHERE quota_blocker.snapshot_id=member.snapshot_id
						AND quota_blocker.account_id=member.account_id
						AND quota_blocker.blocker::text IN (
							'quota_five_hour_depleted',
							'quota_seven_day_depleted'
						)
				) THEN NULL
				ELSE 'usage_unproven'::decodex.routing_blocker END
				WHEN 'auth' THEN
					'authentication_required'::decodex.routing_blocker
				WHEN 'plugin' THEN 'plugin_unready'::decodex.routing_blocker
				WHEN 'dependency' THEN
					'dependency_blocked'::decodex.routing_blocker
				WHEN 'approval' THEN
					'approval_required'::decodex.routing_blocker
				WHEN 'user' THEN 'user_required'::decodex.routing_blocker
				WHEN 'external' THEN 'external_blocked'::decodex.routing_blocker
				WHEN 'reconciliation' THEN CASE
					WHEN EXISTS (
						SELECT 1
						FROM decodex.provider_attempts AS attempt
						WHERE attempt.consumer_kind='managed_run_execution'
							AND attempt.managed_run_id=p_managed_run_id
							AND attempt.managed_execution_id=p_managed_execution_id
					) OR EXISTS (
						SELECT 1
						FROM decodex.process_generations AS generation
						WHERE generation.account_id=member.account_id
							AND generation.state<>'dead'
							AND NOT (
								generation.state='ready'
								AND generation.process_id IS NOT NULL
								AND EXISTS (
									SELECT 1
									FROM decodex.process_generation_execution_epochs
										AS epoch
									WHERE epoch.execution_epoch_id=
										generation.execution_epoch_id
										AND epoch.retired_at IS NULL
								)
							)
					) THEN NULL
					ELSE 'reconciliation_unproven'::decodex.routing_blocker
				END
				WHEN 'reviewer_unavailable' THEN
					'reviewer_unavailable'::decodex.routing_blocker
				WHEN 'reviewer_failed' THEN
					'reviewer_failed'::decodex.routing_blocker
				WHEN 'reviewer_ambiguous' THEN
					'reviewer_ambiguous'::decodex.routing_blocker
				ELSE NULL
			END AS blocker
		) AS cause
		WHERE member.snapshot_id=snapshot_row.snapshot_id
			AND member.disposition='included'
			AND cause.blocker IS NOT NULL;
		END IF;

	-- V14 owns the quota values. V16 also requires the exact timestamp provenance that turns a
	-- current positive value into selectable evidence. Preserve missing provenance as a cause.
	INSERT INTO decodex.routing_decision_blocker_refs(
		decision_id,snapshot_id,account_id,position,blocker
	)
	SELECT decision_uuid,snapshot_row.snapshot_id,member.account_id,
		COALESCE((
			SELECT pg_catalog.max(existing.position)
			FROM decodex.routing_decision_blocker_refs AS existing
			WHERE existing.decision_id=decision_uuid
				AND existing.account_id=member.account_id
		),0)+1,
		'usage_unproven'::decodex.routing_blocker
	FROM decodex.routing_snapshot_members AS member
	WHERE member.snapshot_id=snapshot_row.snapshot_id
		AND member.disposition='included'
		AND EXISTS (
			SELECT 1
			FROM decodex.routing_decision_quota_refs AS fact
			WHERE fact.decision_id=decision_uuid
				AND fact.account_id=member.account_id
				AND fact.observation_revision IS NOT NULL
				AND fact.remaining_percent IS NOT NULL
				AND fact.confidence='high'
				AND fact.observed_at_micros<=decided_micros
				AND decided_micros-fact.observed_at_micros<=300000000
				AND fact.resets_at_micros>decided_micros
				AND fact.source_id IS NULL
		)
		AND NOT EXISTS (
			SELECT 1
			FROM decodex.routing_decision_blocker_refs AS existing
			WHERE existing.decision_id=decision_uuid
				AND existing.account_id=member.account_id
				AND existing.blocker='usage_unproven'
		);

	-- An existing exact ManagedRun intent is blocked at that intent only. Unrelated executions do
	-- not inherit its ambiguity. Every route for the same exact intent remains blocked.
	INSERT INTO decodex.routing_decision_blocker_refs(
		decision_id,snapshot_id,account_id,position,blocker
	)
	SELECT decision_uuid,snapshot_row.snapshot_id,member.account_id,
		COALESCE((
			SELECT pg_catalog.max(existing.position)
			FROM decodex.routing_decision_blocker_refs AS existing
			WHERE existing.decision_id=decision_uuid
				AND existing.account_id=member.account_id
		),0)+1,
		CASE WHEN EXISTS (
			SELECT 1 FROM decodex.provider_attempts AS unresolved
			WHERE unresolved.state IN (
					'prepared','dispatch_authorized','unknown'
				)
				AND unresolved.consumer_kind='managed_run_execution'
				AND unresolved.managed_run_id=p_managed_run_id
				AND unresolved.managed_execution_id=p_managed_execution_id
		) THEN 'provider_attempt_unresolved'::decodex.routing_blocker
		ELSE 'provider_attempt_completed'::decodex.routing_blocker END
	FROM decodex.routing_snapshot_members AS member
	WHERE snapshot_row.runtime_session_id IS NOT NULL
		AND member.snapshot_id=snapshot_row.snapshot_id
		AND member.disposition='included'
		AND EXISTS (
			SELECT 1 FROM decodex.provider_attempts AS attempt
			WHERE attempt.consumer_kind='managed_run_execution'
				AND attempt.managed_run_id=p_managed_run_id
				AND attempt.managed_execution_id=p_managed_execution_id
		);

	INSERT INTO decodex.routing_decision_blocker_refs(
		decision_id,snapshot_id,account_id,position,blocker
	)
	SELECT decision_uuid,snapshot_row.snapshot_id,member.account_id,
		COALESCE((
			SELECT pg_catalog.max(existing.position)
			FROM decodex.routing_decision_blocker_refs AS existing
			WHERE existing.decision_id=decision_uuid
				AND existing.account_id=member.account_id
		),0)+1,
		CASE WHEN EXISTS (
			SELECT 1 FROM decodex.process_generations AS generation
			WHERE generation.account_id=member.account_id
				AND generation.state<>'dead'
		) THEN 'process_generation_unresolved'::decodex.routing_blocker
		ELSE 'process_generation_unavailable'::decodex.routing_blocker END
	FROM decodex.routing_snapshot_members AS member
	WHERE snapshot_row.runtime_session_id IS NOT NULL
		AND member.snapshot_id=snapshot_row.snapshot_id
		AND member.disposition='included'
		AND NOT EXISTS (
			SELECT 1
			FROM decodex.routing_decision_blocker_refs AS existing
			WHERE existing.decision_id=decision_uuid
				AND existing.account_id=member.account_id
				AND existing.blocker::text NOT IN (
					'quota_five_hour_depleted',
					'quota_seven_day_depleted'
				)
		)
		AND NOT EXISTS (
			SELECT 1
			FROM decodex.provider_attempts AS attempt
			WHERE attempt.consumer_kind='managed_run_execution'
				AND attempt.managed_run_id=p_managed_run_id
				AND attempt.managed_execution_id=p_managed_execution_id
		)
		AND NOT EXISTS (
			SELECT 1
			FROM decodex.process_generations AS generation
			JOIN decodex.process_generation_execution_epochs AS epoch
				ON epoch.execution_epoch_id=generation.execution_epoch_id
			WHERE generation.account_id=member.account_id
				AND generation.state='ready'
				AND generation.process_id IS NOT NULL
				AND epoch.retired_at IS NULL
		);

	SELECT member.position,member.account_id
	INTO selected_position,selected_account
	FROM decodex.routing_snapshot_members AS member
	WHERE member.snapshot_id=snapshot_row.snapshot_id
		AND member.disposition='included'
		AND NOT EXISTS (
			SELECT 1
			FROM decodex.routing_decision_blocker_refs AS blocker
			WHERE blocker.decision_id=decision_uuid
				AND blocker.account_id=member.account_id
		)
		AND NOT EXISTS (
			SELECT 1
			FROM decodex.routing_decision_quota_refs AS fact
			WHERE fact.decision_id=decision_uuid
				AND fact.account_id=member.account_id
				AND (
					fact.observation_revision IS NULL
					OR fact.remaining_percent IS NULL
					OR fact.remaining_percent=0
					OR fact.confidence<>'high'
					OR fact.observed_at_micros>decided_micros
					OR decided_micros-fact.observed_at_micros>300000000
					OR fact.resets_at_micros IS NULL
					OR fact.resets_at_micros<=decided_micros
					OR fact.source_id IS NULL
					OR fact.timestamp_precision<>'unix_microsecond'
				)
		)
		AND (
			SELECT pg_catalog.count(*)
			FROM decodex.routing_decision_blocker_refs AS blocker
			JOIN decodex.routing_snapshot_members AS predecessor
				ON predecessor.snapshot_id=blocker.snapshot_id
				AND predecessor.account_id=blocker.account_id
			WHERE blocker.decision_id=decision_uuid
				AND predecessor.disposition='included'
				AND predecessor.position<member.position
				AND blocker.blocker::text IN (
					'quota_five_hour_depleted',
					'quota_seven_day_depleted'
				)
		)=(
			SELECT pg_catalog.count(*)
			FROM decodex.routing_decision_blocker_refs AS blocker
			JOIN decodex.routing_snapshot_members AS predecessor
				ON predecessor.snapshot_id=blocker.snapshot_id
				AND predecessor.account_id=blocker.account_id
			JOIN decodex.routing_decision_quota_refs AS fact
				ON fact.decision_id=blocker.decision_id
				AND fact.account_id=blocker.account_id
				AND fact.window_class=CASE blocker.blocker::text
					WHEN 'quota_five_hour_depleted'
						THEN 'five_hour'::decodex.quota_window_class
					ELSE 'seven_day'::decodex.quota_window_class
				END
			WHERE blocker.decision_id=decision_uuid
				AND predecessor.disposition='included'
				AND predecessor.position<member.position
				AND blocker.blocker::text IN (
					'quota_five_hour_depleted',
					'quota_seven_day_depleted'
				)
				AND fact.remaining_percent=0
				AND fact.confidence='high'
				AND fact.observed_at_micros<=decided_micros
				AND decided_micros-fact.observed_at_micros<=300000000
				AND fact.resets_at_micros>decided_micros
				AND fact.source_id IS NOT NULL
				AND fact.timestamp_precision='unix_microsecond'
				AND fact.raw_observed_at=fact.observed_at_micros::text
				AND fact.raw_resets_at=fact.resets_at_micros::text
		)
	ORDER BY (
		snapshot_row.runtime_session_id IS NOT NULL AND member.sticky
	) DESC,member.position,member.account_id
	LIMIT 1;
	IF FOUND THEN
		decision_kind:='selected';
	ELSIF EXISTS (
		SELECT 1 FROM decodex.routing_snapshot_members
		WHERE snapshot_id=snapshot_row.snapshot_id
			AND disposition='included'
	) AND NOT EXISTS (
		SELECT 1
		FROM decodex.routing_snapshot_members AS member
		LEFT JOIN decodex.routing_decision_blocker_refs AS blocker
			ON blocker.decision_id=decision_uuid
			AND blocker.account_id=member.account_id
		WHERE member.snapshot_id=snapshot_row.snapshot_id
			AND member.disposition='included'
		GROUP BY member.account_id
		HAVING pg_catalog.count(blocker.blocker)=0
			OR pg_catalog.bool_or(
				blocker.blocker::text NOT IN (
					'quota_five_hour_depleted','quota_seven_day_depleted'
				)
			)
	) AND NOT EXISTS (
		SELECT 1
		FROM decodex.routing_snapshot_members AS member
		JOIN decodex.routing_decision_quota_refs AS fact
			ON fact.decision_id=decision_uuid
			AND fact.account_id=member.account_id
		WHERE member.snapshot_id=snapshot_row.snapshot_id
			AND member.disposition='included'
			AND (
				fact.observation_revision IS NULL
				OR fact.remaining_percent IS NULL
				OR fact.confidence<>'high'
				OR fact.observed_at_micros>decided_micros
				OR decided_micros-fact.observed_at_micros>300000000
				OR fact.resets_at_micros IS NULL
				OR fact.resets_at_micros<=decided_micros
				OR fact.source_id IS NULL
				OR fact.timestamp_precision<>'unix_microsecond'
				OR fact.raw_observed_at<>fact.observed_at_micros::text
				OR fact.raw_resets_at<>fact.resets_at_micros::text
			)
	) THEN
		decision_kind:='waiting_usage';
		SELECT pg_catalog.min(account_ready) INTO ready_micros
		FROM (
			SELECT pg_catalog.max(fact.resets_at_micros) AS account_ready
			FROM decodex.routing_snapshot_members AS member
			JOIN decodex.routing_decision_quota_refs AS fact
				ON fact.decision_id=decision_uuid
				AND fact.account_id=member.account_id
			WHERE member.snapshot_id=snapshot_row.snapshot_id
				AND member.disposition='included'
				AND fact.remaining_percent=0
			GROUP BY member.account_id
		) AS readiness;
	ELSIF EXISTS (
		SELECT 1 FROM decodex.routing_snapshot_members
		WHERE snapshot_id=snapshot_row.snapshot_id
			AND disposition='included'
	) AND NOT EXISTS (
		SELECT 1
		FROM decodex.routing_snapshot_members AS member
		LEFT JOIN decodex.routing_decision_blocker_refs AS blocker
			ON blocker.decision_id=decision_uuid
			AND blocker.account_id=member.account_id
		WHERE member.snapshot_id=snapshot_row.snapshot_id
			AND member.disposition='included'
		GROUP BY member.account_id
		HAVING pg_catalog.count(blocker.blocker)=0
			OR pg_catalog.bool_or(
				blocker.blocker::text NOT IN (
					'process_generation_unresolved',
					'provider_attempt_unresolved'
				)
			)
	) THEN
		decision_kind:='waiting_reconciliation';
	ELSE
		decision_kind:='no_route';
		no_route_value:='blocked_evidence';
	END IF;

	IF decision_kind='selected' THEN
		INSERT INTO decodex.routing_decision_exclusions(
			decision_id,authority_shape,account_id,member_position,window_class,
			duration_minutes,observation_revision,remaining_percent,
			observed_at_micros,resets_at_micros,confidence,source_id,
			timestamp_precision,raw_observed_at,raw_resets_at,reason
		)
		SELECT decision_uuid,'managed_run_project_policy',member.account_id,
			member.position,quota.window_class,
			quota.duration_minutes,quota.observation_revision,0,quota.observed_at_micros,
			quota.resets_at_micros,quota.confidence,quota.source_id,
			quota.timestamp_precision,quota.raw_observed_at,quota.raw_resets_at,
			'usage_depleted'
		FROM decodex.routing_snapshot_members AS member
		JOIN decodex.routing_decision_quota_refs AS quota
			ON quota.decision_id=decision_uuid
			AND quota.account_id=member.account_id
		WHERE member.snapshot_id=snapshot_row.snapshot_id
			AND member.disposition='included'
			AND member.position<selected_position
			AND quota.remaining_percent=0
			AND quota.confidence='high'
			AND quota.observed_at_micros<=decided_micros
			AND decided_micros-quota.observed_at_micros<=300000000
			AND quota.resets_at_micros>decided_micros
			AND quota.source_id IS NOT NULL
			AND quota.raw_observed_at IS NOT NULL
			AND quota.raw_resets_at IS NOT NULL
			AND EXISTS (
				SELECT 1
				FROM decodex.routing_decision_blocker_refs AS blocker
				WHERE blocker.decision_id=decision_uuid
					AND blocker.account_id=member.account_id
					AND blocker.blocker=CASE quota.window_class
						WHEN 'five_hour' THEN
							'quota_five_hour_depleted'::decodex.routing_blocker
						ELSE 'quota_seven_day_depleted'::decodex.routing_blocker
					END
			)
		ORDER BY member.position,quota.position;
	ELSIF decision_kind='waiting_usage' THEN
		INSERT INTO decodex.routing_decision_exclusions(
			decision_id,authority_shape,account_id,member_position,window_class,
			duration_minutes,observation_revision,remaining_percent,
			observed_at_micros,resets_at_micros,confidence,source_id,
			timestamp_precision,raw_observed_at,raw_resets_at,reason
		)
		SELECT decision_uuid,'managed_run_project_policy',member.account_id,
			member.position,quota.window_class,
			quota.duration_minutes,quota.observation_revision,0,quota.observed_at_micros,
			quota.resets_at_micros,quota.confidence,quota.source_id,
			quota.timestamp_precision,quota.raw_observed_at,quota.raw_resets_at,
			'usage_depleted'
		FROM decodex.routing_snapshot_members AS member
		JOIN decodex.routing_decision_quota_refs AS quota
			ON quota.decision_id=decision_uuid
			AND quota.account_id=member.account_id
		WHERE member.snapshot_id=snapshot_row.snapshot_id
			AND member.disposition='included'
			AND quota.remaining_percent=0
		ORDER BY member.position,quota.position;
	END IF;

	INSERT INTO decodex.routing_decisions(
		decision_id,operation_id,authority_shape,snapshot_id,routing_policy_id,
		routing_policy_revision,consumer_kind,conversation_id,
		conversation_revision,turn_id,managed_run_id,managed_run_revision,
		managed_execution_id,kind,selected_account_id,
		waiting_ready_at_micros,no_route_reason,decided_at
	) VALUES (
		decision_uuid,p_operation_id,'managed_run_project_policy',snapshot_row.snapshot_id,
		p_routing_policy_id,p_expected_routing_policy_revision,p_consumer_kind,
		p_conversation_id,p_expected_conversation_revision,p_turn_id,
		p_managed_run_id,p_expected_managed_run_revision,p_managed_execution_id,
		decision_kind::decodex.routing_decision_kind,selected_account,
		ready_micros,no_route_value::decodex.routing_no_route_reason,decided
	);

	core:=pg_catalog.jsonb_build_object(
		'operation','route_account',
		'authority_shape','managed_run_project_policy',
		'decision_id',decision_uuid,
		'operation_id',p_operation_id,
		'snapshot_id',snapshot_row.snapshot_id,
		'consumer_kind',p_consumer_kind,
		'conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'source_runtime_session_id',p_source_runtime_session_id,
		'source_runtime_session_revision',
			p_expected_source_runtime_session_revision,
		'turn_id',p_turn_id,
		'managed_run_id',p_managed_run_id,
		'managed_run_revision',p_expected_managed_run_revision,
		'managed_execution_id',p_managed_execution_id,
		'kind',decision_kind,
		'selected_account_id',selected_account,
		'waiting_ready_at_micros',ready_micros,
		'no_route_reason',CASE
			WHEN decision_kind='no_route' THEN 'blocked_evidence'
		END,
		'decided_at_micros',decided_micros,
		'members',(
			SELECT pg_catalog.jsonb_agg(
				pg_catalog.jsonb_build_object(
					'position',member.position,
					'account_id',member.account_id,
					'disposition',member.disposition,
					'sticky',member.sticky,
					'blockers',COALESCE((
						SELECT pg_catalog.jsonb_agg(
							blocker.blocker ORDER BY blocker.position
						)
						FROM decodex.routing_decision_blocker_refs AS blocker
						WHERE blocker.decision_id=decision_uuid
							AND blocker.account_id=member.account_id
					),'[]'::jsonb)
				)
				ORDER BY member.position
			)
			FROM decodex.routing_snapshot_members AS member
			WHERE member.snapshot_id=snapshot_row.snapshot_id
		),
		'quota_facts',(
			SELECT pg_catalog.jsonb_agg(
				pg_catalog.to_jsonb(quota.*)-'decision_id'-'snapshot_id'-
					'authority_shape'-'observation_state'-'used_percent'-'error_code'
				ORDER BY member.position,quota.position
			)
			FROM decodex.routing_decision_quota_refs AS quota
			JOIN decodex.routing_decision_member_refs AS member
				USING(decision_id,account_id)
			WHERE quota.decision_id=decision_uuid
		),
		'capability_facts',(
			SELECT pg_catalog.jsonb_agg(
				pg_catalog.to_jsonb(capability.*)-'decision_id'-'snapshot_id'
				ORDER BY member.position,capability.position
			)
			FROM decodex.routing_decision_capability_refs AS capability
			JOIN decodex.routing_decision_member_refs AS member
				USING(decision_id,account_id)
			WHERE capability.decision_id=decision_uuid
		),
		'exclusions',(
			SELECT COALESCE(
				pg_catalog.jsonb_agg(
					pg_catalog.to_jsonb(exclusion.*)-'decision_id'-
						'authority_shape'-'used_percent'
					ORDER BY member_position,window_class
				),
				'[]'::jsonb
			)
			FROM decodex.routing_decision_exclusions AS exclusion
			WHERE decision_id=decision_uuid
		),
		'causes',CASE WHEN decision_kind='selected' THEN '[]'::jsonb ELSE (
			SELECT COALESCE(
				pg_catalog.jsonb_agg(
					pg_catalog.jsonb_build_object(
						'account_id',blocker.account_id,
						'blocker',blocker.blocker
					)
					ORDER BY member.position,blocker.position
				),
				'[]'::jsonb
			)
			FROM decodex.routing_decision_blocker_refs AS blocker
			JOIN decodex.routing_snapshot_members AS member
				ON member.snapshot_id=blocker.snapshot_id
				AND member.account_id=blocker.account_id
			WHERE blocker.decision_id=decision_uuid
				AND (
					decision_kind='no_route'
					OR member.disposition='included'
				)
		) END
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(
			public.digest(pg_catalog.convert_to(core::text,'UTF8'),'sha256'),
			'hex'
		)
	);
	response:=pg_catalog.convert_to(
		pg_catalog.jsonb_build_object(
			'classification','success',
			'effect',effect
		)::text,
		'UTF8'
	);
	UPDATE decodex.exact_command_receipts
	SET receipt_state='completed_success',outcome_class='success',
		effect_envelope=effect,response_bytes=response,
		completed_at=pg_catalog.clock_timestamp()
	WHERE protocol_version=p_protocol
		AND idempotency_key=p_idempotency_key;
	RETURN response;
END
$$;


--
-- Name: set_account_enabled_exact(uuid, bigint, boolean); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.set_account_enabled_exact(p_account_id uuid, p_expected_revision bigint, p_enabled boolean) RETURNS TABLE(result_code text, revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE current_revision bigint;
BEGIN
	IF p_enabled IS NULL THEN
		RETURN QUERY SELECT 'invalid_request',0::bigint;
		RETURN;
	END IF;
	SELECT account.revision INTO current_revision FROM decodex.accounts AS account
	WHERE account.account_id=p_account_id AND account.tombstoned_at IS NULL FOR UPDATE;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'account_missing',0::bigint; RETURN;
	END IF;
	IF current_revision<>p_expected_revision THEN
		RETURN QUERY SELECT 'stale_account',current_revision; RETURN;
	END IF;
	IF EXISTS (SELECT 1 FROM decodex.accounts AS account WHERE account.account_id=p_account_id
		AND account.enabled IS NOT DISTINCT FROM p_enabled) THEN
		RETURN QUERY SELECT 'updated',current_revision; RETURN;
	END IF;
	UPDATE decodex.accounts AS account SET
		enabled=p_enabled,revision=account.revision+1,
		updated_at=pg_catalog.clock_timestamp()
	WHERE account.account_id=p_account_id RETURNING account.revision INTO current_revision;
	RETURN QUERY SELECT 'updated',current_revision;
END
$$;


--
-- Name: set_account_operation_target_exact(uuid, integer, bigint, text, uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.set_account_operation_target_exact(p_operation_id uuid, p_target_store_schema_version integer, p_target_credential_version bigint, p_target_credential_fingerprint text, p_target_credential_writer_operation_id uuid) RETURNS TABLE(result_code text, account_revision bigint, phase decodex.account_operation_phase)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE operation decodex.account_operations%ROWTYPE;
DECLARE current_revision bigint;
BEGIN
	SELECT * INTO operation FROM decodex.account_operations
	WHERE operation_id=p_operation_id FOR UPDATE;
	IF NOT FOUND THEN
		RETURN QUERY SELECT 'operation_missing',0::bigint,'prepared'::decodex.account_operation_phase;
		RETURN;
	END IF;
	SELECT revision INTO current_revision FROM decodex.accounts
	WHERE account_id=operation.account_id;
	IF operation.target_credential_version IS NOT NULL THEN
		IF (operation.target_store_schema_version,operation.target_credential_version,
			operation.target_credential_fingerprint,
			operation.target_credential_writer_operation_id) IS NOT DISTINCT FROM
			(p_target_store_schema_version,p_target_credential_version,
			p_target_credential_fingerprint,p_target_credential_writer_operation_id)
		THEN RETURN QUERY SELECT 'replayed',current_revision,operation.phase;
		ELSE RETURN QUERY SELECT 'identity_conflict',current_revision,operation.phase;
		END IF;
		RETURN;
	END IF;
	IF operation.kind<>'refresh' OR operation.phase<>'provider_effect_pending'
		OR p_target_store_schema_version<>1
		OR p_target_credential_version<>operation.expected_credential_version+1
		OR p_target_credential_fingerprint !~ '^[0-9a-f]{64}$'
		OR p_target_credential_writer_operation_id IS DISTINCT FROM p_operation_id
	THEN
		RETURN QUERY SELECT 'stale_operation',current_revision,operation.phase;
		RETURN;
	END IF;
	UPDATE decodex.account_operations SET
		target_store_schema_version=p_target_store_schema_version,
		target_credential_version=p_target_credential_version,
		target_credential_fingerprint=p_target_credential_fingerprint,
		target_credential_writer_operation_id=p_target_credential_writer_operation_id,
		updated_at=pg_catalog.clock_timestamp()
	WHERE operation_id=p_operation_id;
	RETURN QUERY SELECT 'advanced',current_revision,operation.phase;
END
$_$;


--
-- Name: set_account_order_exact(bigint, uuid[]); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.set_account_order_exact(p_expected_routing_revision bigint, p_order uuid[]) RETURNS TABLE(result_code text, routing_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE current_routing_revision bigint;
DECLARE current_order uuid[];
BEGIN
	PERFORM decodex.lock_account_routing_universe_exact();
	SELECT control.revision INTO current_routing_revision
	FROM decodex.account_routing_control AS control
	WHERE control.singleton;
	IF p_expected_routing_revision IS NULL OR p_expected_routing_revision < 1 THEN
		RETURN QUERY SELECT 'invalid_request',current_routing_revision; RETURN;
	END IF;
	IF current_routing_revision<>p_expected_routing_revision THEN
		RETURN QUERY SELECT 'stale_routing_control',current_routing_revision; RETURN;
	END IF;
	IF p_order IS NULL OR pg_catalog.cardinality(p_order)>512
		OR pg_catalog.cardinality(p_order)<>(SELECT pg_catalog.count(*)
			FROM decodex.accounts WHERE tombstoned_at IS NULL)
		OR pg_catalog.cardinality(p_order)<>(SELECT pg_catalog.count(DISTINCT value)
			FROM pg_catalog.unnest(p_order) AS value)
		OR EXISTS (SELECT 1 FROM pg_catalog.unnest(p_order) AS value
			LEFT JOIN decodex.accounts AS account ON account.account_id=value
			WHERE account.account_id IS NULL OR account.tombstoned_at IS NOT NULL)
	THEN
		RETURN QUERY SELECT 'invalid_order',current_routing_revision; RETURN;
	END IF;
	SELECT COALESCE(
		pg_catalog.array_agg(ordering.account_id ORDER BY ordering.position),
		'{}'::uuid[]
	) INTO current_order FROM decodex.account_routing_order AS ordering;
	IF current_order IS NOT DISTINCT FROM p_order THEN
		RETURN QUERY SELECT 'updated',current_routing_revision; RETURN;
	END IF;
	DELETE FROM decodex.account_routing_order;
	INSERT INTO decodex.account_routing_order(account_id,position)
	SELECT value,ordinality-1
	FROM pg_catalog.unnest(p_order) WITH ORDINALITY AS entry(value,ordinality);
	UPDATE decodex.account_routing_control AS control
	SET revision=control.revision+1,updated_at=pg_catalog.clock_timestamp()
	WHERE control.singleton RETURNING control.revision INTO current_routing_revision;
	PERFORM decodex.lock_account_routing_universe_exact();
	RETURN QUERY SELECT 'updated',current_routing_revision;
END
$$;


--
-- Name: set_balanced_account_selection_exact(bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.set_balanced_account_selection_exact(p_expected_routing_revision bigint) RETURNS TABLE(result_code text, routing_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE current_routing_revision bigint;
BEGIN
	PERFORM decodex.lock_account_routing_universe_exact();
	SELECT control.revision INTO current_routing_revision
	FROM decodex.account_routing_control AS control
	WHERE control.singleton;
	IF p_expected_routing_revision IS NULL OR p_expected_routing_revision < 1 THEN
		RETURN QUERY SELECT 'invalid_request',current_routing_revision; RETURN;
	END IF;
	IF current_routing_revision<>p_expected_routing_revision THEN
		RETURN QUERY SELECT 'stale_routing_control',current_routing_revision; RETURN;
	END IF;
	IF EXISTS (
		SELECT 1 FROM decodex.account_routing_control AS control
		WHERE control.singleton AND control.mode='balanced'
			AND control.fixed_account_id IS NULL
	) THEN
		RETURN QUERY SELECT 'updated',current_routing_revision; RETURN;
	END IF;
	UPDATE decodex.account_routing_control AS control
	SET mode='balanced',fixed_account_id=NULL,revision=control.revision+1,
		updated_at=pg_catalog.clock_timestamp()
	WHERE control.singleton RETURNING control.revision INTO current_routing_revision;
	PERFORM decodex.lock_account_routing_universe_exact();
	RETURN QUERY SELECT 'updated',current_routing_revision;
END
$$;


--
-- Name: set_fixed_account_selection_exact(bigint, uuid, bigint); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.set_fixed_account_selection_exact(p_expected_routing_revision bigint, p_account_id uuid, p_expected_account_revision bigint) RETURNS TABLE(result_code text, routing_revision bigint, account_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE current_routing_revision bigint;
DECLARE current_account_revision bigint;
DECLARE account_tombstoned_at timestamptz;
BEGIN
	PERFORM decodex.lock_account_routing_universe_exact();
	SELECT control.revision INTO current_routing_revision
	FROM decodex.account_routing_control AS control
	WHERE control.singleton;
	IF p_expected_routing_revision IS NULL OR p_expected_routing_revision < 1
		OR p_account_id IS NULL OR p_expected_account_revision IS NULL
		OR p_expected_account_revision < 1
	THEN
		RETURN QUERY SELECT 'invalid_request',current_routing_revision,0::bigint; RETURN;
	END IF;
	IF current_routing_revision<>p_expected_routing_revision THEN
		RETURN QUERY SELECT 'stale_routing_control',current_routing_revision,0::bigint; RETURN;
	END IF;
	SELECT account.revision,account.tombstoned_at
	INTO current_account_revision,account_tombstoned_at
	FROM decodex.accounts AS account
	WHERE account.account_id=p_account_id;
	IF NOT FOUND OR account_tombstoned_at IS NOT NULL OR NOT EXISTS (
		SELECT 1 FROM decodex.account_routing_order AS ordering
		WHERE ordering.account_id=p_account_id
	) THEN
		RETURN QUERY SELECT 'account_missing',current_routing_revision,0::bigint; RETURN;
	END IF;
	IF current_account_revision<>p_expected_account_revision THEN
		RETURN QUERY SELECT
			'stale_account',current_routing_revision,current_account_revision; RETURN;
	END IF;
	IF EXISTS (
		SELECT 1 FROM decodex.account_routing_control AS control
		WHERE control.singleton AND control.mode='fixed'
			AND control.fixed_account_id=p_account_id
	) THEN
		RETURN QUERY SELECT 'updated',current_routing_revision,current_account_revision; RETURN;
	END IF;
	UPDATE decodex.account_routing_control AS control
	SET mode='fixed',fixed_account_id=p_account_id,revision=control.revision+1,
		updated_at=pg_catalog.clock_timestamp()
	WHERE control.singleton RETURNING control.revision INTO current_routing_revision;
	PERFORM decodex.lock_account_routing_universe_exact();
	RETURN QUERY SELECT 'updated',current_routing_revision,current_account_revision;
END
$$;


--
-- Name: terminalize_quick_task_turn_exact(text, text, uuid, bigint, uuid, bigint, uuid, bigint, uuid, bigint, uuid, bigint, uuid, decodex.provider_attempt_terminal_outcome, uuid, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.terminalize_quick_task_turn_exact(p_protocol text, p_idempotency_key text, p_conversation_id uuid, p_expected_conversation_revision bigint, p_runtime_session_id uuid, p_expected_runtime_session_revision bigint, p_user_turn_id uuid, p_expected_user_turn_revision bigint, p_assistant_turn_id uuid, p_expected_assistant_turn_revision bigint, p_provider_attempt_id uuid, p_expected_provider_attempt_revision bigint, p_provider_evidence_id uuid, p_provider_outcome decodex.provider_attempt_terminal_outcome, p_provider_thread_id uuid, p_provider_turn_id text) RETURNS TABLE(result_code text, conversation_id uuid, conversation_revision bigint, runtime_session_id uuid, prior_runtime_session_revision bigint, runtime_session_revision bigint, user_turn_id uuid, user_turn_revision bigint, assistant_turn_id uuid, assistant_turn_revision bigint, provider_attempt_id uuid, provider_attempt_revision bigint, provider_evidence_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request jsonb; claimed record; document jsonb;
DECLARE conversation_row decodex.conversations%ROWTYPE;
DECLARE session_row decodex.runtime_sessions%ROWTYPE;
DECLARE source_session_row decodex.runtime_sessions%ROWTYPE;
DECLARE user_turn_row decodex.turns%ROWTYPE;
DECLARE assistant_turn_row decodex.turns%ROWTYPE;
DECLARE attempt_row decodex.provider_attempts%ROWTYPE;
DECLARE evidence_row decodex.provider_attempt_positive_evidence%ROWTYPE;
DECLARE plan_row decodex.continuation_plans%ROWTYPE;
DECLARE terminal_status decodex.turn_status;
DECLARE new_session_revision bigint; new_user_revision bigint;
DECLARE new_assistant_revision bigint; payload jsonb; links jsonb;
DECLARE core jsonb; effect jsonb;
BEGIN
	request:=pg_catalog.jsonb_build_object(
		'operation','terminalize_quick_task_turn','protocol_version',p_protocol,
		'conversation_id',p_conversation_id,
		'expected_conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'expected_runtime_session_revision',p_expected_runtime_session_revision,
		'user_turn_id',p_user_turn_id,
		'expected_user_turn_revision',p_expected_user_turn_revision,
		'assistant_turn_id',p_assistant_turn_id,
		'expected_assistant_turn_revision',p_expected_assistant_turn_revision,
		'provider_attempt_id',p_provider_attempt_id,
		'expected_provider_attempt_revision',p_expected_provider_attempt_revision,
		'provider_evidence_id',p_provider_evidence_id,
		'provider_outcome',p_provider_outcome,
		'provider_thread_id',p_provider_thread_id,
		'provider_turn_id',p_provider_turn_id
	);
	SELECT * INTO claimed FROM decodex.claim_runtime_session_thread_command(
		p_protocol,p_idempotency_key,request
	);
	IF claimed.replayed THEN
		document:=pg_catalog.convert_from(claimed.response_bytes,'UTF8')::jsonb;
		IF document->>'classification'<>'success' THEN
			RETURN QUERY SELECT 'rejected',p_conversation_id,
				p_expected_conversation_revision,p_runtime_session_id,
				p_expected_runtime_session_revision,NULL::bigint,p_user_turn_id,NULL::bigint,
				p_assistant_turn_id,NULL::bigint,p_provider_attempt_id,
				p_expected_provider_attempt_revision,p_provider_evidence_id;
			RETURN;
		END IF;
		effect:=document->'effect';
		RETURN QUERY SELECT 'replayed',(effect->>'conversation_id')::uuid,
			(effect->>'conversation_revision')::bigint,
			(effect->>'runtime_session_id')::uuid,
			(effect->>'prior_runtime_session_revision')::bigint,
			(effect->>'runtime_session_revision')::bigint,
			(effect->>'user_turn_id')::uuid,(effect->>'user_turn_revision')::bigint,
			NULLIF(effect->>'assistant_turn_id','')::uuid,
			NULLIF(effect->>'assistant_turn_revision','')::bigint,
			(effect->>'provider_attempt_id')::uuid,
			(effect->>'provider_attempt_revision')::bigint,
			(effect->>'provider_evidence_id')::uuid;
		RETURN;
	END IF;

	IF p_conversation_id IS NULL OR p_runtime_session_id IS NULL
		OR p_user_turn_id IS NULL OR p_provider_attempt_id IS NULL
		OR p_provider_evidence_id IS NULL OR p_provider_thread_id IS NULL
		OR p_expected_conversation_revision IS NULL
		OR p_expected_conversation_revision<=0
		OR p_expected_runtime_session_revision IS NULL
		OR p_expected_runtime_session_revision<=0
		OR p_expected_user_turn_revision IS DISTINCT FROM 1
		OR (p_assistant_turn_id IS NULL)<>
			(p_expected_assistant_turn_revision IS NULL)
		OR p_expected_assistant_turn_revision IS NOT NULL
			AND p_expected_assistant_turn_revision<>1
		OR p_expected_provider_attempt_revision IS NULL
		OR p_expected_provider_attempt_revision<=1
		OR p_provider_outcome NOT IN ('succeeded','failed_definitive')
		OR p_provider_turn_id IS NULL
		OR p_provider_turn_id COLLATE pg_catalog."C" !~
			'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
	THEN
		PERFORM decodex.complete_runtime_session_thread_rejection(
			p_protocol,p_idempotency_key,'terminalize_quick_task_turn',request,'invalid_input'
		);
		RETURN QUERY SELECT 'rejected',p_conversation_id,p_expected_conversation_revision,
			p_runtime_session_id,p_expected_runtime_session_revision,NULL::bigint,
			p_user_turn_id,NULL::bigint,p_assistant_turn_id,NULL::bigint,
			p_provider_attempt_id,p_expected_provider_attempt_revision,p_provider_evidence_id;
		RETURN;
	END IF;

	PERFORM pg_catalog.pg_advisory_xact_lock_shared(1400);
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);
	PERFORM pg_catalog.pg_advisory_xact_lock(
		1276,pg_catalog.hashtext(p_runtime_session_id::text)
	);
	SELECT * INTO conversation_row FROM decodex.conversations
	WHERE conversation_id=p_conversation_id FOR UPDATE;
	SELECT * INTO session_row FROM decodex.runtime_sessions
	WHERE runtime_session_id=p_runtime_session_id FOR UPDATE;
	SELECT * INTO user_turn_row FROM decodex.turns
	WHERE turn_id=p_user_turn_id FOR UPDATE;
	IF p_assistant_turn_id IS NOT NULL THEN
		SELECT * INTO assistant_turn_row FROM decodex.turns
		WHERE turn_id=p_assistant_turn_id FOR UPDATE;
	END IF;
	SELECT * INTO attempt_row FROM decodex.provider_attempts
	WHERE attempt_id=p_provider_attempt_id FOR SHARE;
	SELECT * INTO evidence_row FROM decodex.provider_attempt_positive_evidence
	WHERE evidence_id=p_provider_evidence_id FOR SHARE;
	SELECT * INTO plan_row FROM decodex.continuation_plans
	WHERE plan_id=attempt_row.continuation_plan_id FOR SHARE;
	SELECT * INTO source_session_row FROM decodex.runtime_sessions
	WHERE runtime_session_id=plan_row.source_runtime_session_id FOR UPDATE;
	terminal_status:=CASE p_provider_outcome
		WHEN 'succeeded' THEN 'completed'::decodex.turn_status
		ELSE 'failed'::decodex.turn_status
	END;
	IF conversation_row.conversation_id IS NULL
		OR conversation_row.status<>'open'
		OR conversation_row.revision<>p_expected_conversation_revision
		OR session_row.runtime_session_id IS NULL
		OR session_row.conversation_id<>p_conversation_id
		OR session_row.state<>'active'
		OR session_row.revision<>p_expected_runtime_session_revision
		OR session_row.codex_thread_id IS DISTINCT FROM p_provider_thread_id
		OR session_row.last_known_turn_id IS NOT DISTINCT FROM p_provider_turn_id
		OR user_turn_row.turn_id IS NULL
		OR user_turn_row.conversation_id<>p_conversation_id
		OR user_turn_row.runtime_session_id<>plan_row.source_runtime_session_id
		OR user_turn_row.role<>'user'
		OR user_turn_row.possible_side_effects<>'unknown'
		OR user_turn_row.status<>'active'
		OR user_turn_row.revision<>p_expected_user_turn_revision
		OR attempt_row.attempt_id IS NULL
		OR attempt_row.consumer_kind<>'conversation_turn'
		OR attempt_row.conversation_id<>p_conversation_id
		OR attempt_row.turn_id<>p_user_turn_id
		OR attempt_row.accepted_runtime_session_id<>p_runtime_session_id
		OR attempt_row.accepted_runtime_session_revision<>
			p_expected_runtime_session_revision
		OR attempt_row.revision<>p_expected_provider_attempt_revision
		OR attempt_row.state::text<>p_provider_outcome::text
		OR attempt_row.terminal_evidence_id<>p_provider_evidence_id
		OR plan_row.plan_id IS NULL
		OR plan_row.conversation_revision<>p_expected_conversation_revision
		OR plan_row.turn_id<>p_user_turn_id
		OR evidence_row.evidence_id IS NULL
		OR evidence_row.attempt_id<>p_provider_attempt_id
		OR evidence_row.attempt_revision<>p_expected_provider_attempt_revision-1
		OR evidence_row.request_id<>attempt_row.request_id
		OR evidence_row.selected_account_id<>attempt_row.selected_account_id
		OR evidence_row.outcome<>p_provider_outcome
		OR evidence_row.provider_thread_id IS DISTINCT FROM p_provider_thread_id::text
		OR evidence_row.provider_turn_id IS DISTINCT FROM p_provider_turn_id
		OR p_assistant_turn_id IS NULL AND EXISTS (
			SELECT 1 FROM decodex.turns AS assistant
			WHERE assistant.conversation_id=p_conversation_id
				AND assistant.sequence=user_turn_row.sequence+1
				AND assistant.role='assistant'
		)
		OR p_assistant_turn_id IS NOT NULL AND (
			assistant_turn_row.turn_id IS NULL
			OR assistant_turn_row.conversation_id<>p_conversation_id
			OR assistant_turn_row.runtime_session_id<>p_runtime_session_id
			OR assistant_turn_row.sequence<>user_turn_row.sequence+1
			OR assistant_turn_row.role<>'assistant'
			OR assistant_turn_row.possible_side_effects<>'unknown'
			OR assistant_turn_row.status<>'active'
			OR assistant_turn_row.revision<>p_expected_assistant_turn_revision
		)
	THEN
		PERFORM decodex.complete_runtime_session_thread_rejection(
			p_protocol,p_idempotency_key,'terminalize_quick_task_turn',request,
			'authority_unavailable'
		);
		RETURN QUERY SELECT 'rejected',p_conversation_id,p_expected_conversation_revision,
			p_runtime_session_id,p_expected_runtime_session_revision,NULL::bigint,
			p_user_turn_id,NULL::bigint,p_assistant_turn_id,NULL::bigint,
			p_provider_attempt_id,p_expected_provider_attempt_revision,p_provider_evidence_id;
		RETURN;
	END IF;

	UPDATE decodex.turns SET status=terminal_status,revision=revision+1
	WHERE turn_id=p_user_turn_id RETURNING revision INTO new_user_revision;
	IF p_assistant_turn_id IS NOT NULL THEN
		UPDATE decodex.turns SET status=terminal_status,revision=revision+1
		WHERE turn_id=p_assistant_turn_id RETURNING revision INTO new_assistant_revision;
	END IF;
	UPDATE decodex.runtime_sessions SET
		last_known_turn_id=p_provider_turn_id,revision=revision+1
	WHERE runtime_session_id=p_runtime_session_id
	RETURNING revision INTO new_session_revision;
	IF plan_row.kind='context_pack_fallback'
		AND source_session_row.runtime_session_id<>p_runtime_session_id
		AND source_session_row.state='active'
	THEN
		UPDATE decodex.runtime_sessions SET state='ended',revision=revision+1
		WHERE runtime_session_id=source_session_row.runtime_session_id;
	END IF;
	payload:=pg_catalog.jsonb_build_object(
		'kind','quick_task_turn_terminalized','conversation_id',p_conversation_id,
		'conversation_revision',p_expected_conversation_revision,
		'runtime_session_id',p_runtime_session_id,
		'prior_runtime_session_revision',p_expected_runtime_session_revision,
		'runtime_session_revision',new_session_revision,
		'user_turn_id',p_user_turn_id,'user_turn_revision',new_user_revision,
		'assistant_turn_id',p_assistant_turn_id,
		'assistant_turn_revision',new_assistant_revision,
		'turn_status',terminal_status,'provider_attempt_id',p_provider_attempt_id,
		'provider_attempt_revision',p_expected_provider_attempt_revision,
		'provider_evidence_id',p_provider_evidence_id,
		'provider_outcome',p_provider_outcome,
		'provider_thread_id',p_provider_thread_id,
		'provider_turn_id',p_provider_turn_id
	);
	links:=decodex.append_runtime_session_thread_effect(
		p_runtime_session_id,new_session_revision,'quick_task_turn_terminalized',
		p_idempotency_key,payload
	);
	core:=payload||pg_catalog.jsonb_build_object(
		'operation','terminalize_quick_task_turn',
		'activity_sequence',links->'activity_sequence','outbox_id',links->'outbox_id'
	);
	effect:=core||pg_catalog.jsonb_build_object(
		'effect_digest_source',core::text,
		'effect_digest',pg_catalog.encode(public.digest(
			pg_catalog.convert_to(core::text,'UTF8'),'sha256'),'hex')
	);
	PERFORM decodex.complete_runtime_session_thread_command(
		p_protocol,p_idempotency_key,effect
	);
	RETURN QUERY SELECT 'applied',p_conversation_id,p_expected_conversation_revision,
		p_runtime_session_id,p_expected_runtime_session_revision,new_session_revision,
		p_user_turn_id,new_user_revision,p_assistant_turn_id,new_assistant_revision,
		p_provider_attempt_id,p_expected_provider_attempt_revision,p_provider_evidence_id;
END
$_$;


--
-- Name: transition_objective(decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, bigint, decodex.objective_state, decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.transition_objective(p_objective_id decodex.canonical_uuid_v4_text, p_project_id decodex.canonical_uuid_v4_text, p_expected_revision bigint, p_state decodex.objective_state, p_actor_id decodex.canonical_uuid_v4_text, p_correlation_id decodex.canonical_uuid_v4_text, p_provenance text) RETURNS TABLE(result_code text, actual_revision bigint, changed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE canonical_objective_id uuid;
DECLARE canonical_project_id uuid;
DECLARE canonical_actor_id uuid;
DECLARE canonical_correlation_id uuid;
DECLARE stored decodex.objectives%ROWTYPE;
BEGIN
	IF p_objective_id IS NULL OR p_project_id IS NULL OR p_actor_id IS NULL
		OR p_correlation_id IS NULL THEN
		RAISE EXCEPTION 'identity ingress requires canonical UUID-v4 text'
			USING ERRCODE = '23514', CONSTRAINT = 'canonical_uuid_v4_text_ingress';
	END IF;
	canonical_objective_id := p_objective_id::text::uuid;
	canonical_project_id := p_project_id::text::uuid;
	canonical_actor_id := p_actor_id::text::uuid;
	canonical_correlation_id := p_correlation_id::text::uuid;
	SELECT current.* INTO stored FROM decodex.objectives AS current
	WHERE current.objective_id=canonical_objective_id FOR UPDATE;
	IF NOT FOUND THEN RETURN QUERY SELECT 'not_found', NULL::bigint, false; RETURN; END IF;
	IF stored.project_id<>canonical_project_id THEN
		RETURN QUERY SELECT 'invalid_project', NULL::bigint, false; RETURN;
	END IF;
	IF stored.revision IS DISTINCT FROM p_expected_revision THEN
		RETURN QUERY SELECT 'revision_conflict', stored.revision, false; RETURN;
	END IF;
	PERFORM 1 FROM decodex.projects AS project JOIN decodex.agents AS lead
		ON lead.project_id=project.project_id AND lead.role='lead'
	WHERE project.project_id=canonical_project_id AND project.status='active'
		AND lead.agent_id=canonical_actor_id AND lead.status='active' FOR KEY SHARE OF project, lead;
	IF NOT FOUND THEN RETURN QUERY SELECT 'invalid_authority', stored.revision, false; RETURN; END IF;
	IF NOT (
		(stored.state='proposed' AND p_state IN ('active','abandoned'))
		OR (stored.state='active' AND p_state IN ('blocked','abandoned'))
		OR (stored.state='blocked' AND p_state IN ('active','abandoned'))
	) THEN RETURN QUERY SELECT 'invalid_transition', stored.revision, false; RETURN; END IF;
	UPDATE decodex.objectives SET state=p_state,revision=revision+1,
		last_changed_by=canonical_actor_id,last_correlation_id=canonical_correlation_id,
		last_provenance=p_provenance,updated_at=pg_catalog.clock_timestamp()
	WHERE objective_id=canonical_objective_id;
	RETURN QUERY SELECT 'ok', stored.revision+1, true;
END
$$;


--
-- Name: transition_program(decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, bigint, decodex.program_state, decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.transition_program(p_program_id decodex.canonical_uuid_v4_text, p_project_id decodex.canonical_uuid_v4_text, p_expected_revision bigint, p_state decodex.program_state, p_actor_id decodex.canonical_uuid_v4_text, p_correlation_id decodex.canonical_uuid_v4_text, p_provenance text) RETURNS TABLE(result_code text, actual_revision bigint, changed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE canonical_program_id uuid;
DECLARE canonical_project_id uuid;
DECLARE canonical_actor_id uuid;
DECLARE canonical_correlation_id uuid;
DECLARE stored decodex.programs%ROWTYPE;
BEGIN
	IF p_program_id IS NULL OR p_project_id IS NULL OR p_actor_id IS NULL
		OR p_correlation_id IS NULL THEN
		RAISE EXCEPTION 'identity ingress requires canonical UUID-v4 text'
			USING ERRCODE = '23514', CONSTRAINT = 'canonical_uuid_v4_text_ingress';
	END IF;
	canonical_program_id := p_program_id::text::uuid;
	canonical_project_id := p_project_id::text::uuid;
	canonical_actor_id := p_actor_id::text::uuid;
	canonical_correlation_id := p_correlation_id::text::uuid;
	SELECT current.* INTO stored FROM decodex.programs AS current
	WHERE current.program_id=canonical_program_id FOR UPDATE;
	IF NOT FOUND THEN RETURN QUERY SELECT 'not_found', NULL::bigint, false; RETURN; END IF;
	IF stored.project_id<>canonical_project_id THEN
		RETURN QUERY SELECT 'invalid_project', NULL::bigint, false; RETURN;
	END IF;
	IF stored.revision IS DISTINCT FROM p_expected_revision THEN
		RETURN QUERY SELECT 'revision_conflict', stored.revision, false; RETURN;
	END IF;
	PERFORM 1 FROM decodex.projects AS project JOIN decodex.agents AS lead
		ON lead.project_id=project.project_id AND lead.role='lead'
	WHERE project.project_id=canonical_project_id AND project.status='active'
		AND lead.agent_id=canonical_actor_id AND lead.agent_id=stored.owner_agent_id
		AND lead.status='active' FOR KEY SHARE OF project, lead;
	IF NOT FOUND THEN RETURN QUERY SELECT 'invalid_authority', stored.revision, false; RETURN; END IF;
	IF NOT (
		(stored.state='active' AND p_state IN ('needs_attention','blocked','paused','retired'))
		OR (stored.state='needs_attention' AND p_state IN ('active','blocked','paused','retired'))
		OR (stored.state='blocked' AND p_state IN ('active','needs_attention','paused','retired'))
		OR (stored.state='paused' AND p_state IN ('active','retired'))
	) THEN RETURN QUERY SELECT 'invalid_transition', stored.revision, false; RETURN; END IF;
	UPDATE decodex.programs SET state=p_state,revision=revision+1,
		last_changed_by=canonical_actor_id,last_correlation_id=canonical_correlation_id,
		last_provenance=p_provenance,updated_at=pg_catalog.clock_timestamp()
	WHERE program_id=canonical_program_id;
	RETURN QUERY SELECT 'ok', stored.revision+1, true;
END
$$;


--
-- Name: transition_project(decodex.canonical_uuid_v4_text, bigint, decodex.project_status); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.transition_project(p_project_id decodex.canonical_uuid_v4_text, p_expected_revision bigint, p_status decodex.project_status) RETURNS TABLE(project_id uuid, repository_identity text, repository_root text, default_cwd text, project_status decodex.project_status, metadata jsonb, project_revision bigint, agent_id uuid, agent_role decodex.agent_role, agent_status decodex.agent_status, agent_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE canonical_project_id pg_catalog.uuid;
DECLARE changed bigint;
BEGIN
	IF p_project_id IS NULL THEN
		RAISE EXCEPTION 'identity ingress requires canonical UUID-v4 text'
			USING ERRCODE = '23514', CONSTRAINT = 'canonical_uuid_v4_text_ingress';
	END IF;
	canonical_project_id := p_project_id::pg_catalog.text::pg_catalog.uuid;
	UPDATE decodex.projects AS project
	SET status = p_status, revision = project.revision + 1, updated_at = clock_timestamp()
	WHERE project.project_id = canonical_project_id
		AND project.revision = p_expected_revision
		AND (
			(project.status = 'active' AND p_status IN ('paused', 'archived'))
			OR (project.status = 'paused' AND p_status IN ('active', 'archived'))
		);
	GET DIAGNOSTICS changed = ROW_COUNT;
	IF changed <> 1 THEN RETURN; END IF;

	UPDATE decodex.agents AS lead
	SET status = CASE p_status
		WHEN 'active' THEN 'active'::decodex.agent_status
		WHEN 'paused' THEN 'paused'::decodex.agent_status
		WHEN 'archived' THEN 'retired'::decodex.agent_status
	END,
		revision = lead.revision + 1,
		updated_at = clock_timestamp()
	WHERE lead.project_id = canonical_project_id AND lead.role = 'lead' AND lead.revision = p_expected_revision;
	GET DIAGNOSTICS changed = ROW_COUNT;
	IF changed <> 1 THEN
		RAISE EXCEPTION 'Project canonical Lead revision differs'
			USING ERRCODE = '40001';
	END IF;

	RETURN QUERY
	SELECT project.project_id, project.repository_identity, project.repository_root,
		project.default_cwd, project.status, project.metadata, project.revision,
		lead.agent_id, lead.role, lead.status, lead.revision
	FROM decodex.projects AS project
	JOIN decodex.agents AS lead ON lead.project_id = project.project_id AND lead.role = 'lead'
	WHERE project.project_id = canonical_project_id;
END
$$;


--
-- Name: transition_runtime_session_exact(text, text, uuid, bigint, decodex.runtime_session_state); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.transition_runtime_session_exact(p_protocol text, p_idempotency_key text, p_session_id uuid, p_expected_revision bigint, p_target_state decodex.runtime_session_state) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request_value jsonb;
DECLARE existing_request jsonb;
DECLARE existing_response bytea;
DECLARE inserted_count integer;
DECLARE prior_state decodex.runtime_session_state;
DECLARE actual_revision bigint;
DECLARE profile_value jsonb;
DECLARE account_value jsonb;
DECLARE session_value jsonb;
DECLARE activity_sequence bigint;
DECLARE activity_aggregate_kind text;
DECLARE activity_aggregate_id text;
DECLARE activity_revision bigint;
DECLARE activity_event_kind text;
DECLARE activity_payload jsonb;
DECLARE outbox_id bigint;
DECLARE outbox_effect_key text;
DECLARE outbox_aggregate_kind text;
DECLARE outbox_aggregate_id text;
DECLARE outbox_aggregate_revision bigint;
DECLARE outbox_payload jsonb;
DECLARE effect_value jsonb;
DECLARE response_value bytea;
BEGIN
	IF p_protocol IS NULL OR p_idempotency_key IS NULL OR p_session_id IS NULL
		OR p_expected_revision IS NULL OR p_target_state IS NULL
	THEN
		RAISE EXCEPTION 'exact RuntimeSession transition is incomplete' USING ERRCODE = '22004';
	END IF;
	IF pg_catalog.octet_length(p_protocol) NOT BETWEEN 1 AND 64
		OR p_protocol COLLATE pg_catalog."C" !~ '^[a-z0-9][a-z0-9._/-]{0,63}$'
		OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 256
		OR decodex.has_credential_material(p_idempotency_key)
	THEN
		RAISE EXCEPTION 'exact RuntimeSession command identity is invalid' USING ERRCODE = '22023';
	END IF;

	request_value := decodex.build_runtime_session_transition_request(
		p_protocol, p_session_id, p_expected_revision, p_target_state
	);
	INSERT INTO decodex.exact_command_receipts(
		protocol_version, idempotency_key, request_envelope, request_digest, receipt_state
	) VALUES (
		p_protocol, p_idempotency_key, request_value,
		public.digest(pg_catalog.convert_to(request_value::text, 'UTF8'), 'sha256'), 'executing'
	) ON CONFLICT (protocol_version, idempotency_key) DO NOTHING;
	GET DIAGNOSTICS inserted_count = ROW_COUNT;

	IF inserted_count = 0 THEN
		SELECT request_envelope, response_bytes INTO existing_request, existing_response
		FROM decodex.exact_command_receipts
		WHERE protocol_version = p_protocol AND idempotency_key = p_idempotency_key
		FOR UPDATE;
		IF existing_request <> request_value THEN
			RAISE EXCEPTION 'exact idempotency conflict' USING ERRCODE = 'DX001';
		END IF;
		IF existing_response IS NULL THEN
			RAISE EXCEPTION 'incomplete exact receipt is not replayable' USING ERRCODE = 'DX002';
		END IF;
		RETURN existing_response;
	END IF;

	-- The following UPDATE has the same outer coordinator as every hierarchy mutation.
	-- Acquire it before the executor can select and lock the RuntimeSession tuple below.
	PERFORM pg_catalog.pg_advisory_xact_lock(1271);

	SELECT session.state, session.revision,
		pg_catalog.jsonb_build_object(
			'profile_snapshot_id', profile.profile_snapshot_id,
			'source_profile_id', profile.source_profile_id, 'role', profile.role,
			'model', profile.model, 'reasoning_effort', profile.reasoning_effort,
			'service_tier', profile.service_tier,
			'instructions_digest', profile.instructions_digest,
			'instructions', profile.instructions, 'provenance', profile.provenance,
			'source_revision', profile.source_revision, 'created_at', profile.created_at
		),
		pg_catalog.jsonb_build_object(
			'account_snapshot_id', account.account_snapshot_id,
			'source_account_id', account.source_account_id,
			'display_label', account.display_label, 'observed_state', account.observed_state,
			'source_revision', account.source_revision, 'created_at', account.created_at
		)
	INTO prior_state, actual_revision, profile_value, account_value
	FROM decodex.runtime_sessions AS session
	JOIN decodex.profile_snapshots AS profile USING (profile_snapshot_id)
	JOIN decodex.account_snapshots AS account USING (account_snapshot_id)
	WHERE session.runtime_session_id = p_session_id
	FOR UPDATE OF session;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_runtime_session_rejection(
			p_protocol, p_idempotency_key, 'missing_target'
		);
	END IF;
	IF actual_revision <> p_expected_revision THEN
		RETURN decodex.complete_exact_runtime_session_rejection(
			p_protocol, p_idempotency_key, 'stale_revision'
		);
	END IF;
	IF NOT (
		(prior_state = 'starting' AND p_target_state IN ('active', 'ended', 'diverged'))
		OR (prior_state = 'active' AND p_target_state IN ('ended', 'diverged'))
	) OR (p_target_state IN ('ended', 'diverged') AND EXISTS (
		SELECT 1 FROM decodex.turns
		WHERE runtime_session_id = p_session_id AND status = 'active'
	)) THEN
		RETURN decodex.complete_exact_runtime_session_rejection(
			p_protocol, p_idempotency_key, 'illegal_transition'
		);
	END IF;

	UPDATE decodex.runtime_sessions
	SET state = p_target_state, revision = revision + 1
	WHERE runtime_session_id = p_session_id AND revision = p_expected_revision
	RETURNING pg_catalog.jsonb_build_object(
		'runtime_session_id', runtime_session_id, 'conversation_id', conversation_id,
		'profile_snapshot_id', profile_snapshot_id,
		'account_snapshot_id', account_snapshot_id,
		'codex_thread_id', codex_thread_id, 'last_known_turn_id', last_known_turn_id,
		'state', state, 'revision', revision, 'created_at', created_at,
		'updated_at', updated_at, 'ended_at', ended_at
	) INTO session_value;
	IF session_value IS NULL THEN
		RAISE EXCEPTION 'RuntimeSession compare-and-swap lost after row lock' USING ERRCODE = '40001';
	END IF;

	activity_payload := pg_catalog.jsonb_build_object(
		'kind', 'runtime_session', 'runtime_session_snapshot', session_value,
		'profile_snapshot', profile_value, 'account_snapshot', account_value,
		'prior_state', prior_state, 'new_state', p_target_state,
		'prior_revision', p_expected_revision,
		'new_revision', (session_value->>'revision')::bigint
	);
	INSERT INTO decodex.activity(
		aggregate_kind, aggregate_id, revision, event_kind, correlation_key, payload
	) VALUES (
		'runtime_session', p_session_id::text, (session_value->>'revision')::bigint,
		'runtime_session_transitioned', p_idempotency_key, activity_payload
	) RETURNING sequence, aggregate_kind, aggregate_id, revision, event_kind, payload
	INTO activity_sequence, activity_aggregate_kind, activity_aggregate_id,
		activity_revision, activity_event_kind, activity_payload;
	outbox_payload := pg_catalog.jsonb_build_object(
		'activity_sequence', activity_sequence, 'event_kind', 'runtime_session_transitioned',
		'aggregate_kind', 'runtime_session', 'aggregate_id', p_session_id,
		'revision', (session_value->>'revision')::bigint, 'payload', activity_payload
	);
	INSERT INTO decodex.outbox(
		effect_key, aggregate_kind, aggregate_id, aggregate_revision, payload
	) VALUES (
		'activity/' || activity_sequence::text, 'runtime_session', p_session_id::text,
		(session_value->>'revision')::bigint, outbox_payload
	) RETURNING id, effect_key, aggregate_kind, aggregate_id, aggregate_revision, payload
	INTO outbox_id, outbox_effect_key, outbox_aggregate_kind,
		outbox_aggregate_id, outbox_aggregate_revision, outbox_payload;

	effect_value := pg_catalog.jsonb_build_object(
		'request', request_value,
		'runtime_session_snapshot', session_value, 'profile_snapshot', profile_value,
		'account_snapshot', account_value, 'prior_state', prior_state,
		'new_state', p_target_state, 'prior_revision', p_expected_revision,
		'new_revision', (session_value->>'revision')::bigint,
		'activity_sequence', activity_sequence,
		'activity_aggregate_kind', activity_aggregate_kind,
		'activity_aggregate_id', activity_aggregate_id,
		'activity_revision', activity_revision,
		'activity_event_kind', activity_event_kind,
		'activity_payload', activity_payload,
		'outbox_id', outbox_id, 'outbox_effect_key', outbox_effect_key,
		'outbox_aggregate_kind', outbox_aggregate_kind,
		'outbox_aggregate_id', outbox_aggregate_id,
		'outbox_aggregate_revision', outbox_aggregate_revision,
		'outbox_payload', outbox_payload
	);
	response_value := pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification', 'success', 'effect', effect_value
	)::text, 'UTF8');
	UPDATE decodex.exact_command_receipts
	SET receipt_state = 'completed_success', outcome_class = 'success',
		effect_envelope = effect_value, response_bytes = response_value,
		completed_at = pg_catalog.clock_timestamp()
	WHERE protocol_version = p_protocol AND idempotency_key = p_idempotency_key;

	RETURN response_value;
END
$_$;


--
-- Name: try_acquire_lease(text, uuid, interval); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.try_acquire_lease(p_resource_key text, p_holder_id uuid, p_ttl interval) RETURNS TABLE(acquired boolean, lease_token uuid, revision bigint)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE
	ttl_milliseconds bigint := decodex.lease_ttl_milliseconds(p_ttl);
	write_at timestamptz := clock_timestamp();
BEGIN
	RETURN QUERY
	WITH acquired AS (
		INSERT INTO decodex.leases (resource_key, holder_id, expires_at, updated_at)
		VALUES (
			p_resource_key,
			p_holder_id,
			write_at + ttl_milliseconds * interval '1 millisecond',
			write_at
		)
		ON CONFLICT (resource_key) DO UPDATE
		SET holder_id = EXCLUDED.holder_id,
			lease_token = gen_random_uuid(),
			expires_at = EXCLUDED.expires_at,
			revision = decodex.leases.revision + 1,
			updated_at = EXCLUDED.updated_at
		WHERE decodex.leases.expires_at <= write_at
			OR decodex.leases.holder_id = EXCLUDED.holder_id
		RETURNING decodex.leases.lease_token, decodex.leases.revision
	)
	SELECT true, acquired.lease_token, acquired.revision FROM acquired
	UNION ALL
	SELECT false, NULL::uuid, NULL::bigint WHERE NOT EXISTS (SELECT 1 FROM acquired);
END
$$;


--
-- Name: update_program_context(decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, bigint, integer, bigint, jsonb, jsonb, decodex.canonical_uuid_v4_text, decodex.canonical_uuid_v4_text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.update_program_context(p_program_id decodex.canonical_uuid_v4_text, p_project_id decodex.canonical_uuid_v4_text, p_expected_revision bigint, p_review_interval_days integer, p_next_review_at bigint, p_metrics jsonb, p_signals jsonb, p_actor_id decodex.canonical_uuid_v4_text, p_correlation_id decodex.canonical_uuid_v4_text, p_provenance text) RETURNS TABLE(result_code text, actual_revision bigint, changed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE canonical_program_id uuid;
DECLARE canonical_project_id uuid;
DECLARE canonical_actor_id uuid;
DECLARE canonical_correlation_id uuid;
DECLARE stored decodex.programs%ROWTYPE;
BEGIN
	IF p_program_id IS NULL OR p_project_id IS NULL OR p_actor_id IS NULL
		OR p_correlation_id IS NULL THEN
		RAISE EXCEPTION 'identity ingress requires canonical UUID-v4 text'
			USING ERRCODE = '23514', CONSTRAINT = 'canonical_uuid_v4_text_ingress';
	END IF;
	canonical_program_id := p_program_id::text::uuid;
	canonical_project_id := p_project_id::text::uuid;
	canonical_actor_id := p_actor_id::text::uuid;
	canonical_correlation_id := p_correlation_id::text::uuid;
	SELECT current.* INTO stored FROM decodex.programs AS current
	WHERE current.program_id=canonical_program_id FOR UPDATE;
	IF NOT FOUND THEN RETURN QUERY SELECT 'not_found', NULL::bigint, false; RETURN; END IF;
	IF stored.project_id<>canonical_project_id THEN
		RETURN QUERY SELECT 'invalid_project', NULL::bigint, false; RETURN;
	END IF;
	IF stored.revision IS DISTINCT FROM p_expected_revision THEN
		RETURN QUERY SELECT 'revision_conflict', stored.revision, false; RETURN;
	END IF;
	PERFORM 1 FROM decodex.projects AS project JOIN decodex.agents AS lead
		ON lead.project_id=project.project_id AND lead.role='lead'
	WHERE project.project_id=canonical_project_id AND project.status='active'
		AND lead.agent_id=canonical_actor_id AND lead.agent_id=stored.owner_agent_id
		AND lead.status='active' FOR KEY SHARE OF project, lead;
	IF NOT FOUND THEN RETURN QUERY SELECT 'invalid_authority', stored.revision, false; RETURN; END IF;
	IF stored.state='retired' THEN RETURN QUERY SELECT 'invalid_transition', stored.revision, false; RETURN; END IF;
	IF stored.review_interval_days=p_review_interval_days
		AND stored.next_review_at=decodex.program_timestamp(p_next_review_at)
		AND stored.metrics=p_metrics AND stored.signals=p_signals
	THEN RETURN QUERY SELECT 'invalid_transition', stored.revision, false; RETURN; END IF;
	UPDATE decodex.programs SET review_interval_days=p_review_interval_days,
		next_review_at=decodex.program_timestamp(p_next_review_at),metrics=p_metrics,
		signals=p_signals,revision=revision+1,
		last_changed_by=canonical_actor_id,last_correlation_id=canonical_correlation_id,
		last_provenance=p_provenance,updated_at=pg_catalog.clock_timestamp()
	WHERE program_id=canonical_program_id;
	RETURN QUERY SELECT 'ok', stored.revision+1, true;
END
$$;


--
-- Name: update_role_profile_exact(text, text, decodex.role_profile_role, bigint, text, text, text, text, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.update_role_profile_exact(p_protocol text, p_idempotency_key text, p_role decodex.role_profile_role, p_expected_revision bigint, p_model text, p_reasoning_effort text, p_service_tier text, p_instructions text, p_provenance text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request_value jsonb;
DECLARE existing_request jsonb;
DECLARE existing_response bytea;
DECLARE inserted_count integer;
DECLARE actual_revision bigint;
DECLARE profile_value jsonb;
DECLARE activity_sequence bigint;
DECLARE activity_payload jsonb;
DECLARE outbox_id bigint;
DECLARE outbox_payload jsonb;
DECLARE effect_value jsonb;
DECLARE response_value bytea;
BEGIN
	IF p_protocol IS NULL OR p_idempotency_key IS NULL OR p_role IS NULL
		OR p_expected_revision IS NULL OR p_model IS NULL OR p_reasoning_effort IS NULL
		OR p_service_tier IS NULL OR p_instructions IS NULL
	THEN
		RAISE EXCEPTION 'exact RoleProfile update is incomplete' USING ERRCODE = '22004';
	END IF;
	IF pg_catalog.octet_length(p_protocol) NOT BETWEEN 1 AND 64
		OR p_protocol COLLATE pg_catalog."C" !~ '^[a-z0-9][a-z0-9._/-]{0,63}$'
		OR pg_catalog.octet_length(p_idempotency_key) NOT BETWEEN 1 AND 256
		OR decodex.has_credential_material(p_idempotency_key)
	THEN
		RAISE EXCEPTION 'exact RoleProfile command identity is invalid' USING ERRCODE = '22023';
	END IF;

	request_value := decodex.build_role_profile_update_request(
		p_protocol, p_role, p_expected_revision, p_model, p_reasoning_effort,
		p_service_tier, p_instructions, p_provenance
	);
	INSERT INTO decodex.exact_command_receipts(
		protocol_version, idempotency_key, request_envelope, request_digest, receipt_state
	) VALUES (
		p_protocol, p_idempotency_key, request_value,
		public.digest(pg_catalog.convert_to(request_value::text, 'UTF8'), 'sha256'), 'executing'
	) ON CONFLICT (protocol_version, idempotency_key) DO NOTHING;
	GET DIAGNOSTICS inserted_count = ROW_COUNT;

	IF inserted_count = 0 THEN
		SELECT request_envelope, response_bytes INTO existing_request, existing_response
		FROM decodex.exact_command_receipts
		WHERE protocol_version = p_protocol AND idempotency_key = p_idempotency_key
		FOR UPDATE;
		IF existing_request <> request_value THEN
			RAISE EXCEPTION 'exact idempotency conflict' USING ERRCODE = 'DX001';
		END IF;
		IF existing_response IS NULL THEN
			RAISE EXCEPTION 'incomplete exact receipt is not replayable' USING ERRCODE = 'DX002';
		END IF;
		RETURN existing_response;
	END IF;

	IF p_expected_revision < 1 THEN
		RETURN decodex.complete_exact_role_profile_rejection(
			p_protocol, p_idempotency_key, 'invalid_expected_revision'
		);
	END IF;
	IF NOT decodex.is_role_profile_configuration(
		p_model, p_reasoning_effort, p_service_tier, p_instructions, p_provenance
	) THEN
		RETURN decodex.complete_exact_role_profile_rejection(
			p_protocol, p_idempotency_key, 'invalid_profile'
		);
	END IF;

	SELECT current_revision INTO actual_revision
	FROM decodex.role_profiles WHERE role = p_role FOR UPDATE;
	IF NOT FOUND THEN
		RETURN decodex.complete_exact_role_profile_rejection(
			p_protocol, p_idempotency_key, 'not_bootstrapped'
		);
	END IF;
	IF actual_revision <> p_expected_revision THEN
		RETURN decodex.complete_exact_role_profile_rejection(
			p_protocol, p_idempotency_key, 'stale_revision'
		);
	END IF;

	WITH inserted_revision AS (
		INSERT INTO decodex.role_profile_revisions(
			role, revision, model, reasoning_effort, service_tier, instructions, provenance
		) VALUES (
			p_role, actual_revision + 1, p_model, p_reasoning_effort,
			p_service_tier, p_instructions, p_provenance
		) RETURNING role, revision, model, reasoning_effort, service_tier,
			instructions, provenance, created_at
	), advanced_profile AS (
		UPDATE decodex.role_profiles
		SET current_revision = actual_revision + 1, updated_at = pg_catalog.clock_timestamp()
		WHERE role = p_role AND current_revision = actual_revision
		RETURNING role, current_revision, created_at, updated_at
	)
	SELECT pg_catalog.jsonb_build_object(
		'role', revision.role, 'revision', revision.revision,
		'model', revision.model, 'reasoning_effort', revision.reasoning_effort,
		'service_tier', revision.service_tier, 'instructions', revision.instructions,
		'provenance', revision.provenance, 'created_at', revision.created_at,
		'updated_at', profile.updated_at
	) INTO profile_value
	FROM inserted_revision AS revision JOIN advanced_profile AS profile USING (role);

	IF profile_value IS NULL THEN
		RAISE EXCEPTION 'RoleProfile compare-and-swap lost after row lock' USING ERRCODE = '40001';
	END IF;

	activity_payload := profile_value || pg_catalog.jsonb_build_object('kind', 'role_profile');
	INSERT INTO decodex.activity(
		aggregate_kind, aggregate_id, revision, event_kind, correlation_key, payload
	) VALUES (
		'role_profile', p_role::text, (profile_value->>'revision')::bigint,
		'role_profile_updated', p_idempotency_key, activity_payload
	) RETURNING sequence, payload INTO activity_sequence, activity_payload;
	outbox_payload := pg_catalog.jsonb_build_object(
		'activity_sequence', activity_sequence, 'event_kind', 'role_profile_updated',
		'aggregate_kind', 'role_profile', 'aggregate_id', p_role,
		'revision', (profile_value->>'revision')::bigint, 'payload', activity_payload
	);
	INSERT INTO decodex.outbox(
		effect_key, aggregate_kind, aggregate_id, aggregate_revision, payload
	) VALUES (
		'activity/' || activity_sequence::text, 'role_profile', p_role::text,
		(profile_value->>'revision')::bigint, outbox_payload
	) RETURNING id, payload INTO outbox_id, outbox_payload;

	effect_value := pg_catalog.jsonb_build_object(
		'profile', profile_value, 'activity_sequence', activity_sequence,
		'activity_payload', activity_payload, 'outbox_id', outbox_id,
		'outbox_payload', outbox_payload
	);
	response_value := pg_catalog.convert_to(pg_catalog.jsonb_build_object(
		'classification', 'success', 'effect', effect_value
	)::text, 'UTF8');
	UPDATE decodex.exact_command_receipts
	SET receipt_state = 'completed_success', outcome_class = 'success',
		effect_envelope = effect_value, response_bytes = response_value,
		completed_at = pg_catalog.clock_timestamp()
	WHERE protocol_version = p_protocol AND idempotency_key = p_idempotency_key;

	RETURN response_value;
END
$_$;


--
-- Name: update_work_item_exact(text, text, uuid, uuid, bigint, uuid, uuid[], uuid[], uuid[], text, text, decodex.work_item_priority, text[], text[], decodex.work_item_state, uuid, uuid, text); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.update_work_item_exact(p_protocol text, p_idempotency_key text, p_work_item_id uuid, p_project_id uuid, p_expected_revision bigint, p_program_id uuid, p_objective_ids uuid[], p_depends_on_ids uuid[], p_blocked_by_ids uuid[], p_title text, p_description text, p_priority decodex.work_item_priority, p_acceptance_criteria text[], p_validation_criteria text[], p_target_state decodex.work_item_state, p_actor_id uuid, p_correlation_id uuid, p_provenance text) RETURNS bytea
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'decodex'
    AS $_$
DECLARE request_value jsonb;
DECLARE replay bytea;
DECLARE item record;
DECLARE project_state text;
DECLARE lead_state text;
DECLARE lead_role text;
BEGIN
	request_value := pg_catalog.jsonb_build_object(
		'protocol_version',p_protocol,'operation','update_work_item','work_item_id',p_work_item_id,
		'project_id',p_project_id,'expected_revision',p_expected_revision,'program_id',p_program_id,
		'objective_ids',p_objective_ids,'depends_on_ids',p_depends_on_ids,'blocked_by_ids',p_blocked_by_ids,
		'title',p_title,'description',p_description,'priority',p_priority,
		'acceptance_criteria',p_acceptance_criteria,'validation_criteria',p_validation_criteria,
		'target_state',p_target_state,'actor_id',p_actor_id,'correlation_id',p_correlation_id,
		'provenance',p_provenance);
	replay := decodex.reserve_exact_work_item_command(p_protocol,p_idempotency_key,request_value);
	IF replay IS NOT NULL THEN RETURN replay; END IF;
	IF p_work_item_id IS NULL OR p_project_id IS NULL OR p_expected_revision IS NULL
		OR p_objective_ids IS NULL OR p_depends_on_ids IS NULL OR p_blocked_by_ids IS NULL
		OR p_title IS NULL OR p_description IS NULL OR p_priority IS NULL
		OR p_acceptance_criteria IS NULL OR p_validation_criteria IS NULL
		OR p_target_state IS NULL OR p_actor_id IS NULL OR p_correlation_id IS NULL
		OR p_provenance IS NULL OR p_expected_revision <= 0
		OR p_work_item_id::text COLLATE pg_catalog."C" !~
			'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_input'); END IF;
	PERFORM pg_catalog.pg_advisory_xact_lock(1343,pg_catalog.hashtext(p_project_id::text));
	SELECT work.* INTO item FROM decodex.work_items work
	WHERE work.work_item_id=p_work_item_id AND work.project_id=p_project_id FOR UPDATE OF work;
	IF NOT FOUND THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'missing_target'); END IF;
	IF item.revision <> p_expected_revision THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'stale_revision'); END IF;
	IF p_target_state IN ('ready','running','done') OR NOT (
		(item.state='inbox' AND p_target_state IN ('inbox','planned','canceled')) OR
		(item.state='planned' AND p_target_state IN ('inbox','planned','blocked','canceled')) OR
		(item.state='ready' AND p_target_state IN ('planned','blocked','canceled')) OR
		(item.state='running' AND p_target_state IN ('review','blocked','canceled')) OR
		(item.state='review' AND p_target_state IN ('blocked','canceled')) OR
		(item.state='blocked' AND p_target_state IN ('planned','canceled'))
	) THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'illegal_transition'); END IF;
	IF NOT decodex.is_work_item_text(p_title,256) OR NOT decodex.is_work_item_text(p_description,4096)
		OR NOT decodex.is_work_item_text(p_provenance,4096)
		OR NOT decodex.is_work_item_criteria(p_acceptance_criteria)
		OR NOT decodex.is_work_item_criteria(p_validation_criteria)
		OR pg_catalog.cardinality(p_objective_ids)>32
		OR pg_catalog.cardinality(p_depends_on_ids)+pg_catalog.cardinality(p_blocked_by_ids)>256
		OR COALESCE(pg_catalog.array_ndims(p_objective_ids),1) <> 1
		OR COALESCE(pg_catalog.array_ndims(p_depends_on_ids),1) <> 1
		OR COALESCE(pg_catalog.array_ndims(p_blocked_by_ids),1) <> 1
		OR pg_catalog.array_position(p_objective_ids,NULL) IS NOT NULL
		OR pg_catalog.array_position(p_depends_on_ids,NULL) IS NOT NULL
		OR pg_catalog.array_position(p_blocked_by_ids,NULL) IS NOT NULL
		OR p_work_item_id=ANY(p_depends_on_ids) OR p_work_item_id=ANY(p_blocked_by_ids)
		OR p_correlation_id::text COLLATE pg_catalog."C" !~
			'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_input'); END IF;
	IF EXISTS (SELECT 1 FROM pg_catalog.unnest(p_objective_ids) id LEFT JOIN decodex.objectives objective
		ON objective.objective_id=id AND objective.project_id=p_project_id WHERE objective.objective_id IS NULL)
		OR (p_program_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM decodex.programs
			WHERE program_id=p_program_id AND project_id=p_project_id))
		OR EXISTS (SELECT 1 FROM pg_catalog.unnest(p_depends_on_ids||p_blocked_by_ids) id
			LEFT JOIN decodex.work_items related ON related.work_item_id=id AND related.project_id=p_project_id
			WHERE related.work_item_id IS NULL)
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_relation'); END IF;
	PERFORM 1 FROM decodex.programs WHERE program_id=p_program_id FOR SHARE;
	PERFORM 1 FROM decodex.objectives WHERE objective_id=ANY(p_objective_ids)
		ORDER BY objective_id FOR SHARE;
	PERFORM 1 FROM decodex.work_items WHERE work_item_id=ANY(p_depends_on_ids||p_blocked_by_ids)
		ORDER BY work_item_id FOR SHARE;
	SELECT project.status,lead.status,lead.role INTO project_state,lead_state,lead_role
	FROM decodex.projects project JOIN decodex.agents lead
		ON lead.agent_id=item.lead_agent_id AND lead.project_id=project.project_id
	WHERE project.project_id=p_project_id FOR SHARE OF project,lead;
	IF project_state <> 'active' OR lead_state <> 'active' OR lead_role <> 'lead'
		OR p_actor_id <> item.lead_agent_id THEN
		RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_authority'); END IF;
	IF (SELECT pg_catalog.count(*) FROM pg_catalog.unnest(p_objective_ids) value)
		<> (SELECT pg_catalog.count(DISTINCT value) FROM pg_catalog.unnest(p_objective_ids) value)
		OR (SELECT pg_catalog.count(*) FROM pg_catalog.unnest(p_depends_on_ids||p_blocked_by_ids) value)
		<> (SELECT pg_catalog.count(DISTINCT value) FROM pg_catalog.unnest(p_depends_on_ids||p_blocked_by_ids) value)
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'duplicate_relation'); END IF;
	IF EXISTS (SELECT 1 FROM pg_catalog.unnest(p_objective_ids) id LEFT JOIN decodex.objectives objective
		ON objective.objective_id=id AND objective.project_id=p_project_id WHERE objective.objective_id IS NULL)
		OR (p_program_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM decodex.programs
			WHERE program_id=p_program_id AND project_id=p_project_id))
		OR EXISTS (SELECT 1 FROM pg_catalog.unnest(p_depends_on_ids||p_blocked_by_ids) id
			LEFT JOIN decodex.work_items related ON related.work_item_id=id AND related.project_id=p_project_id
			WHERE related.work_item_id IS NULL)
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_relation'); END IF;
	IF (SELECT pg_catalog.count(*) FROM decodex.work_items WHERE project_id=p_project_id) > 4096
		OR (SELECT pg_catalog.count(*) FROM decodex.work_item_edges
			WHERE project_id=p_project_id AND work_item_id<>p_work_item_id)
			+ pg_catalog.cardinality(p_depends_on_ids) + pg_catalog.cardinality(p_blocked_by_ids) > 16384
	THEN RETURN decodex.complete_exact_work_item_rejection(p_protocol,p_idempotency_key,'invalid_input'); END IF;
	BEGIN
		DELETE FROM decodex.work_item_readiness_blockers WHERE work_item_id=p_work_item_id;
		DELETE FROM decodex.work_item_objectives WHERE work_item_id=p_work_item_id;
		DELETE FROM decodex.work_item_edges WHERE work_item_id=p_work_item_id;
		INSERT INTO decodex.work_item_objectives(project_id,work_item_id,objective_id)
		SELECT p_project_id,p_work_item_id,id FROM pg_catalog.unnest(p_objective_ids) id ORDER BY id;
		INSERT INTO decodex.work_item_edges(project_id,work_item_id,related_work_item_id,kind)
		SELECT p_project_id,p_work_item_id,id,'depends_on'::decodex.work_item_edge_kind
		FROM pg_catalog.unnest(p_depends_on_ids) id
		UNION ALL SELECT p_project_id,p_work_item_id,id,'blocked_by'::decodex.work_item_edge_kind
		FROM pg_catalog.unnest(p_blocked_by_ids) id ORDER BY 3;
		IF decodex.work_item_graph_cycle(p_project_id) THEN
			RAISE EXCEPTION 'candidate WorkItem graph contains a cycle' USING ERRCODE='P1343';
		END IF;
	EXCEPTION WHEN SQLSTATE 'P1343' THEN
		RETURN decodex.complete_exact_work_item_rejection(
			p_protocol,p_idempotency_key,'dependency_cycle');
	END;
	UPDATE decodex.work_items SET program_id=p_program_id,title=p_title,description=p_description,
		priority=p_priority,acceptance_criteria=p_acceptance_criteria,
		validation_criteria=p_validation_criteria,state=p_target_state,revision=revision+1,
		last_changed_by=p_actor_id,last_correlation_id=p_correlation_id,last_provenance=p_provenance,
		updated_at=pg_catalog.clock_timestamp() WHERE work_item_id=p_work_item_id;
	RETURN decodex.complete_exact_work_item_success(p_protocol,p_idempotency_key,
		'work_item_updated',p_work_item_id,pg_catalog.jsonb_build_object('request',request_value));
END
$_$;


--
-- Name: work_item_document(uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.work_item_document(p_work_item_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
SELECT pg_catalog.jsonb_build_object(
	'work_item_id', item.work_item_id, 'project_id', item.project_id,
	'lead_agent_id', item.lead_agent_id, 'program_id', item.program_id,
	'objective_ids', COALESCE((SELECT pg_catalog.jsonb_agg(link.objective_id ORDER BY link.objective_id)
		FROM decodex.work_item_objectives AS link WHERE link.work_item_id = item.work_item_id), '[]'::jsonb),
	'edges', COALESCE((SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
		'kind', edge.kind, 'related_work_item_id', edge.related_work_item_id
	) ORDER BY edge.related_work_item_id) FROM decodex.work_item_edges AS edge
		WHERE edge.work_item_id = item.work_item_id), '[]'::jsonb),
	'title', item.title, 'description', item.description, 'priority', item.priority,
	'acceptance_criteria', item.acceptance_criteria,
	'validation_criteria', item.validation_criteria, 'state', item.state,
	'revision', item.revision, 'last_changed_by', item.last_changed_by,
	'last_correlation_id', item.last_correlation_id,
	'last_provenance', item.last_provenance,
	'created_at_microseconds', (EXTRACT(EPOCH FROM item.created_at)*1000000)::bigint,
	'updated_at_microseconds', (EXTRACT(EPOCH FROM item.updated_at)*1000000)::bigint,
	'accepted_revision', (SELECT pg_catalog.max(acceptance.work_item_revision)
		FROM decodex.work_item_acceptances AS acceptance
		WHERE acceptance.work_item_id = item.work_item_id)
) FROM decodex.work_items AS item WHERE item.work_item_id = p_work_item_id
$$;


--
-- Name: work_item_graph_cycle(uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.work_item_graph_cycle(p_project_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
WITH RECURSIVE reach(origin, node) AS (
	SELECT edge.work_item_id, edge.related_work_item_id
	FROM decodex.work_item_edges AS edge WHERE edge.project_id = p_project_id
	UNION
	SELECT reach.origin, edge.related_work_item_id
	FROM reach JOIN decodex.work_item_edges AS edge
		ON edge.project_id = p_project_id AND edge.work_item_id = reach.node
)
SELECT EXISTS (SELECT 1 FROM reach WHERE origin = node)
$$;


--
-- Name: work_item_readiness(uuid); Type: FUNCTION; Schema: decodex; Owner: -
--

CREATE FUNCTION decodex.work_item_readiness(p_work_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'pg_catalog', 'decodex'
    AS $$
DECLARE item record;
DECLARE blockers jsonb := '[]'::jsonb;
BEGIN
	SELECT work.project_id, work.lead_agent_id, work.program_id,
		project.status AS project_state, lead.status AS lead_state, lead.role AS lead_role
	INTO STRICT item
	FROM decodex.work_items AS work
	JOIN decodex.projects AS project USING (project_id)
	JOIN decodex.agents AS lead ON lead.agent_id = work.lead_agent_id
	WHERE work.work_item_id = p_work_item_id;
	IF item.project_state <> 'active' THEN blockers := blockers || pg_catalog.jsonb_build_array(
		pg_catalog.jsonb_build_object('kind','project_inactive','subject_id',NULL,
			'observed_state',item.project_state)); END IF;
	IF item.lead_state <> 'active' OR item.lead_role <> 'lead' THEN
		blockers := blockers || pg_catalog.jsonb_build_array(
		pg_catalog.jsonb_build_object('kind','lead_inactive','subject_id',NULL,
			'observed_state',CASE WHEN item.lead_state <> 'active' THEN item.lead_state
				ELSE 'not_lead' END)); END IF;
	IF item.program_id IS NOT NULL THEN blockers := blockers || COALESCE((
		SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
			'kind','program_inactive','subject_id',program.program_id,
			'observed_state',program.state) ORDER BY program.program_id)
		FROM decodex.programs AS program WHERE program.program_id = item.program_id
			AND program.state <> 'active'), '[]'::jsonb); END IF;
	blockers := blockers || COALESCE((
		SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
			'kind','objective_inactive','subject_id',objective.objective_id,
			'observed_state',objective.state) ORDER BY objective.objective_id)
		FROM decodex.work_item_objectives AS link
		JOIN decodex.objectives AS objective USING (objective_id)
		WHERE link.work_item_id = p_work_item_id AND objective.state <> 'active'
	), '[]'::jsonb);
	blockers := blockers || COALESCE((
		SELECT pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
			'kind', CASE edge.kind WHEN 'depends_on' THEN 'dependency_incomplete'
				ELSE 'blocker_active' END,
			'subject_id', related.work_item_id, 'observed_state', related.state
		) ORDER BY edge.related_work_item_id)
		FROM decodex.work_item_edges AS edge
		JOIN decodex.work_items AS related ON related.work_item_id = edge.related_work_item_id
		WHERE edge.work_item_id = p_work_item_id AND (
			(edge.kind = 'depends_on' AND related.state <> 'done') OR
			(edge.kind = 'blocked_by' AND related.state NOT IN ('done','canceled'))
		)
	), '[]'::jsonb);
	IF decodex.work_item_graph_cycle(item.project_id) THEN
		blockers := blockers || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
			'kind','dependency_cycle','subject_id',NULL,'observed_state','cycle'));
	END IF;
	RETURN blockers;
END
$$;


