-- Name: accounts; Type: TABLE; Schema: decodex; Owner: -
--

CREATE TABLE decodex.accounts (
    account_id uuid NOT NULL,
    display_label text NOT NULL,
    state decodex.account_state DEFAULT 'unknown'::decodex.account_state NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    observed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    provider_kind decodex.account_provider_kind,
    provider_account_id text,
    credential_store_schema_version integer,
    credential_version bigint,
    credential_fingerprint text,
    credential_writer_operation_id uuid,
    credential_store_observation decodex.account_store_observation DEFAULT 'unknown'::decodex.account_store_observation NOT NULL,
    credential_store_observed_at timestamp with time zone,
    tombstoned_at timestamp with time zone,
    CONSTRAINT accounts_credential_binding_shape CHECK ((((credential_store_schema_version IS NULL) AND (credential_version IS NULL) AND (credential_fingerprint IS NULL) AND (credential_writer_operation_id IS NULL)) OR ((credential_store_schema_version = 1) AND (credential_version > 0) AND (credential_fingerprint ~ '^[0-9a-f]{64}$'::text) AND (credential_writer_operation_id IS NOT NULL) AND (provider_kind IS NOT NULL)))),
    CONSTRAINT accounts_display_label_check CHECK (((length(display_label) >= 1) AND (length(display_label) <= 128))),
    CONSTRAINT accounts_finite_timestamps CHECK ((isfinite(observed_at) AND isfinite(updated_at))),
    CONSTRAINT accounts_lifecycle_no_credentials CHECK ((((provider_account_id IS NULL) OR (NOT decodex.has_credential_material(provider_account_id))) AND ((credential_fingerprint IS NULL) OR (NOT decodex.has_credential_material(credential_fingerprint))))),
    CONSTRAINT accounts_no_credentials CHECK (((NOT decodex.has_credential_material(display_label)) AND (NOT decodex.has_credential_material(metadata)))),
    CONSTRAINT accounts_observed_state_not_administrative CHECK ((state <> 'disabled'::decodex.account_state)),
    CONSTRAINT accounts_provider_identity_shape CHECK ((((provider_kind IS NULL) AND (provider_account_id IS NULL)) OR ((provider_kind IS NOT NULL) AND (octet_length(provider_account_id) >= 1) AND (octet_length(provider_account_id) <= 512) AND (provider_account_id !~ '[[:cntrl:]]'::text)))),
    CONSTRAINT accounts_revision_check CHECK ((revision > 0)),
    CONSTRAINT accounts_store_observation_shape CHECK ((((credential_store_observation = 'unknown'::decodex.account_store_observation) = (credential_store_observed_at IS NULL)) AND ((credential_store_observed_at IS NULL) OR isfinite(credential_store_observed_at)))),
    CONSTRAINT accounts_tombstone_shape CHECK (((tombstoned_at IS NULL) OR ((NOT enabled) AND (credential_store_schema_version IS NULL) AND (credential_version IS NULL) AND (credential_fingerprint IS NULL)))),
    CONSTRAINT accounts_v27_display_label_shape CHECK (((octet_length(display_label) >= 1) AND (octet_length(display_label) <= 128) AND (display_label !~ '[[:cntrl:]]'::text)))
);


