    CONSTRAINT codex_experiment_retained_title_attestations_returned_cwd_check CHECK (((returned_cwd <> ''::text) AND (octet_length(returned_cwd) <= 4096) AND (returned_cwd !~ '[[:cntrl:]]'::text)))
