--
-- Name: command_receipts; Type: TABLE; Schema: decodex; Owner: -
--

CREATE TABLE decodex.command_receipts (
    idempotency_key text NOT NULL,
    request_hash text NOT NULL,
    response jsonb,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    protocol_version text DEFAULT 'decodex/store-command/1'::text NOT NULL,
    operation text DEFAULT 'legacy'::text NOT NULL,
    project_scope text DEFAULT 'global'::text NOT NULL,
    scope_id text DEFAULT 'global'::text NOT NULL,
    entity_id text DEFAULT 'legacy'::text NOT NULL,
    expected_revision bigint,
    payload_hash text,
    payload_length bigint,
    receipt_state decodex.command_receipt_state DEFAULT 'pending'::decodex.command_receipt_state NOT NULL,
    claim_token uuid,
    completion_claim_token uuid,
    claim_expires_at timestamp with time zone,
    response_bytes bytea,
    CONSTRAINT command_receipts_check CHECK (((response IS NOT NULL) = (completed_at IS NOT NULL))),
    CONSTRAINT command_receipts_claim CHECK ((((receipt_state = 'pending'::decodex.command_receipt_state) AND (response IS NULL) AND (response_bytes IS NULL) AND (completed_at IS NULL) AND (claim_token IS NOT NULL) AND (completion_claim_token IS NULL) AND (claim_expires_at IS NOT NULL) AND isfinite(claim_expires_at) AND (claim_expires_at > created_at)) OR ((receipt_state = 'completed'::decodex.command_receipt_state) AND (response IS NOT NULL) AND (response_bytes IS NOT NULL) AND (completed_at IS NOT NULL) AND (claim_token IS NULL) AND (completion_claim_token IS NOT NULL) AND (claim_expires_at IS NULL)))),
    CONSTRAINT command_receipts_finite_timestamps CHECK ((isfinite(created_at) AND ((completed_at IS NULL) OR isfinite(completed_at)))),
    CONSTRAINT command_receipts_idempotency_key_check CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 256))),
    CONSTRAINT command_receipts_no_credentials CHECK (((NOT decodex.has_credential_material(idempotency_key)) AND ((response IS NULL) OR (NOT decodex.has_credential_material(response))))),
    CONSTRAINT command_receipts_payload CHECK ((((payload_hash IS NULL) AND (payload_length IS NULL)) OR ((payload_hash ~ '^[0-9a-f]{64}$'::text) AND ((payload_length >= 1) AND (payload_length <= 67108864))))),
    CONSTRAINT command_receipts_protocol CHECK (((protocol_version = ANY (ARRAY['decodex/store-command/1'::text, 'decodex/account-command/1'::text])) AND (operation ~ '^[a-z][a-z0-9_]{0,63}$'::text) AND (project_scope ~ '^[a-z][a-z0-9_]{0,31}$'::text) AND ((octet_length(scope_id) >= 1) AND (octet_length(scope_id) <= 256)) AND ((octet_length(entity_id) >= 1) AND (octet_length(entity_id) <= 256)))),
    CONSTRAINT command_receipts_request_hash_check CHECK ((request_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT command_receipts_saga_no_credentials CHECK (((NOT decodex.has_credential_material(operation)) AND (NOT decodex.has_credential_material(project_scope)) AND (NOT decodex.has_credential_material(scope_id)) AND (NOT decodex.has_credential_material(entity_id)))),
    CONSTRAINT command_receipts_timestamp_order CHECK (((completed_at IS NULL) OR (completed_at >= created_at)))
);


--
-- Name: context_pack_sources; Type: TABLE; Schema: decodex; Owner: -
--

CREATE TABLE decodex.context_pack_sources (
    context_pack_id uuid NOT NULL,
    conversation_id uuid NOT NULL,
    "position" integer NOT NULL,
    kind decodex.context_source_kind NOT NULL,
    source_id text NOT NULL,
    source_revision bigint NOT NULL,
    content_digest text NOT NULL,
    original_byte_length bigint NOT NULL,
    included_byte_length bigint NOT NULL,
    included_digest text NOT NULL,
    disposition decodex.context_source_disposition NOT NULL,
    artifact_id uuid,
    artifact_revision bigint,
    CONSTRAINT context_pack_sources_artifact_shape CHECK ((((kind = 'artifact'::decodex.context_source_kind) = ((artifact_id IS NOT NULL) AND (artifact_revision IS NOT NULL))) AND ((kind <> 'artifact'::decodex.context_source_kind) OR ((source_id = (artifact_id)::text) AND (source_revision = artifact_revision))))),
    CONSTRAINT context_pack_sources_check CHECK (((included_byte_length >= 0) AND (included_byte_length <= original_byte_length))),
    CONSTRAINT context_pack_sources_content_digest_check CHECK ((content_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT context_pack_sources_disposition_shape CHECK ((((disposition = 'omitted'::decodex.context_source_disposition) AND (included_byte_length = 0) AND (included_digest = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855'::text)) OR ((disposition = 'complete'::decodex.context_source_disposition) AND (original_byte_length > 0) AND (included_byte_length = original_byte_length) AND (included_digest = content_digest)) OR ((disposition = 'truncated'::decodex.context_source_disposition) AND (included_byte_length > 0) AND (included_byte_length < original_byte_length)))),
    CONSTRAINT context_pack_sources_included_digest_check CHECK ((included_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT context_pack_sources_no_credentials CHECK ((NOT decodex.has_credential_material(source_id))),
    CONSTRAINT context_pack_sources_original_byte_length_check CHECK (((original_byte_length >= 0) AND (original_byte_length <= 2097152))),
    CONSTRAINT context_pack_sources_pinned_shape CHECK (((("position" = 0) = (kind = 'pinned_revision'::decodex.context_source_kind)) AND (("position" <> 0) OR ((disposition = 'complete'::decodex.context_source_disposition) AND (included_byte_length > 0))))),
    CONSTRAINT context_pack_sources_position_check CHECK ((("position" >= 0) AND ("position" < 512))),
    CONSTRAINT context_pack_sources_source_id_check CHECK (((octet_length(source_id) >= 1) AND (octet_length(source_id) <= 256))),
    CONSTRAINT context_pack_sources_source_revision_check CHECK ((source_revision > 0))
);


