    CONSTRAINT context_packs_manifest_digest_check CHECK ((manifest_digest ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT context_packs_max_bytes_check CHECK (((max_bytes >= 1024) AND (max_bytes <= 262144))),
    CONSTRAINT context_packs_omitted_source_count_check CHECK ((omitted_source_count >= 0)),
    CONSTRAINT context_packs_pack_revision_check CHECK ((pack_revision > 0)),
    CONSTRAINT context_packs_payload_shape CHECK ((((inline_bytes IS NOT NULL) AND (blob_hash IS NULL)) OR ((inline_bytes IS NULL) AND (blob_hash IS NOT NULL)))),
    CONSTRAINT context_packs_recent_item_limit_check CHECK (((recent_item_limit >= 1) AND (recent_item_limit <= 256))),
    CONSTRAINT context_packs_source_count_check CHECK (((source_count >= 1) AND (source_count <= 512)))
);


--
-- Name: continuation_plans; Type: TABLE; Schema: decodex; Owner: -
--

CREATE TABLE decodex.continuation_plans (
    plan_id uuid NOT NULL,
