    codex_experiment_revision bigint,
    codex_observation_id uuid,
    replay_permitted boolean DEFAULT false NOT NULL,
    dispatch_enabled boolean DEFAULT false NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    request_envelope jsonb NOT NULL,
    effect_envelope jsonb NOT NULL,
    response_bytes bytea NOT NULL,
    planned_at timestamp with time zone NOT NULL,
    consumer_kind decodex.provider_attempt_consumer_kind NOT NULL,
    consumer_conversation_id uuid,
    conversation_revision bigint,
    turn_id uuid,
    managed_execution_id uuid,
    same_thread_provider_attempt_id uuid,
    same_thread_provider_attempt_revision bigint,
    same_thread_provider_evidence_id uuid,
    CONSTRAINT continuation_plans_consumer_shape CHECK (((((consumer_kind)::text = 'conversation_turn'::text) AND (consumer_conversation_id IS NOT NULL) AND (conversation_revision > 0) AND (turn_id IS NOT NULL) AND (managed_run_id IS NULL) AND (managed_run_revision IS NULL) AND (managed_execution_id IS NULL)) OR (((consumer_kind)::text = 'managed_run_execution'::text) AND (consumer_conversation_id IS NULL) AND (conversation_revision IS NULL) AND (turn_id IS NULL) AND (managed_run_id IS NOT NULL) AND (managed_run_revision > 0) AND (managed_execution_id IS NOT NULL)))),
    CONSTRAINT continuation_plans_dispatch_enabled_check CHECK ((NOT dispatch_enabled)),
    CONSTRAINT continuation_plans_evidence_revision CHECK ((((routing_evidence_id IS NULL) = (routing_evidence_revision IS NULL)) AND ((routing_evidence_id IS NULL) = (schema_fingerprint IS NULL)))),
    CONSTRAINT continuation_plans_experiment_revision CHECK ((((codex_experiment_id IS NULL) = (codex_experiment_revision IS NULL)) AND ((codex_experiment_id IS NULL) = (codex_observation_id IS NULL)))),
    CONSTRAINT continuation_plans_finite_time CHECK (isfinite(planned_at)),
    CONSTRAINT continuation_plans_managed_run_revision_check CHECK ((managed_run_revision > 0)),
    CONSTRAINT continuation_plans_replay_permitted_check CHECK ((NOT replay_permitted)),
    CONSTRAINT continuation_plans_revision_check CHECK ((revision = 1)),
    CONSTRAINT continuation_plans_shape CHECK ((((kind = 'initial_thread'::decodex.continuation_plan_kind) AND (consumer_kind = 'conversation_turn'::decodex.provider_attempt_consumer_kind) AND (codex_thread_id IS NULL) AND (fallback_context_pack_id IS NULL) AND (fallback_runtime_session_id IS NULL) AND (routing_evidence_id IS NULL) AND (routing_evidence_revision IS NULL) AND (schema_fingerprint IS NULL) AND (codex_experiment_id IS NULL) AND (codex_experiment_revision IS NULL) AND (codex_observation_id IS NULL) AND (same_thread_provider_attempt_id IS NULL) AND (same_thread_provider_attempt_revision IS NULL) AND (same_thread_provider_evidence_id IS NULL)) OR ((kind = 'same_thread'::decodex.continuation_plan_kind) AND (codex_thread_id IS NOT NULL) AND (fallback_context_pack_id IS NULL) AND (fallback_runtime_session_id IS NULL) AND (((consumer_kind = 'managed_run_execution'::decodex.provider_attempt_consumer_kind) AND (routing_evidence_id IS NOT NULL) AND (routing_evidence_revision > 0) AND ((schema_fingerprint COLLATE "C") ~ '^[0-9a-f]{64}$'::text) AND (codex_experiment_id IS NOT NULL) AND (codex_experiment_revision = 3) AND (codex_observation_id IS NOT NULL) AND (same_thread_provider_attempt_id IS NULL) AND (same_thread_provider_attempt_revision IS NULL) AND (same_thread_provider_evidence_id IS NULL)) OR ((consumer_kind = 'conversation_turn'::decodex.provider_attempt_consumer_kind) AND (routing_evidence_id IS NULL) AND (routing_evidence_revision IS NULL) AND (schema_fingerprint IS NULL) AND (codex_experiment_id IS NULL) AND (codex_experiment_revision IS NULL) AND (codex_observation_id IS NULL) AND (same_thread_provider_attempt_id IS NOT NULL) AND (same_thread_provider_attempt_revision > 0) AND (same_thread_provider_evidence_id IS NOT NULL)))) OR ((kind = 'context_pack_fallback'::decodex.continuation_plan_kind) AND (codex_thread_id IS NULL) AND (fallback_context_pack_id IS NOT NULL) AND (fallback_runtime_session_id IS NOT NULL) AND (routing_evidence_id IS NULL) AND (routing_evidence_revision IS NULL) AND (schema_fingerprint IS NULL) AND (codex_experiment_id IS NULL) AND (codex_experiment_revision IS NULL) AND (codex_observation_id IS NULL) AND (same_thread_provider_attempt_id IS NULL) AND (same_thread_provider_attempt_revision IS NULL) AND (same_thread_provider_evidence_id IS NULL)))),
    CONSTRAINT continuation_plans_source_runtime_session_revision_check CHECK ((source_runtime_session_revision > 0))
);


--
-- Name: conversations; Type: TABLE; Schema: decodex; Owner: -
--

CREATE TABLE decodex.conversations (
    conversation_id uuid NOT NULL,
    title text NOT NULL,
    initial_quick_task_message text,
    initial_quick_task_working_directory text,
