);


--
-- Name: exact_command_receipts; Type: TABLE; Schema: decodex; Owner: -
--

CREATE TABLE decodex.exact_command_receipts (
    protocol_version text NOT NULL,
    idempotency_key text NOT NULL,
    request_envelope jsonb NOT NULL,
    request_digest bytea NOT NULL,
    receipt_state decodex.exact_receipt_state NOT NULL,
    outcome_class text,
    effect_envelope jsonb,
    response_bytes bytea,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    completed_at timestamp with time zone,
    CONSTRAINT exact_command_receipts_finite_times CHECK ((isfinite(created_at) AND ((completed_at IS NULL) OR isfinite(completed_at)) AND ((completed_at IS NULL) OR (completed_at >= created_at)))),
    CONSTRAINT exact_command_receipts_identity_bounded CHECK (((octet_length(protocol_version) >= 1) AND (octet_length(protocol_version) <= 64) AND ((protocol_version COLLATE "C") ~ '^[a-z0-9][a-z0-9._/-]{0,63}$'::text) AND (octet_length(idempotency_key) >= 1) AND (octet_length(idempotency_key) <= 256) AND (NOT decodex.has_credential_material(idempotency_key)))),
    CONSTRAINT exact_command_receipts_no_credentials CHECK (((NOT decodex.has_credential_material(request_envelope)) AND ((effect_envelope IS NULL) OR (NOT decodex.has_credential_material(effect_envelope))))),
    CONSTRAINT exact_command_receipts_request_digest CHECK ((request_digest = public.digest(convert_to((request_envelope)::text, 'UTF8'::name), 'sha256'::text))),
    CONSTRAINT exact_command_receipts_response_authority CHECK (((response_bytes IS NULL) OR ((NOT (((convert_from(response_bytes, 'UTF8'::name))::jsonb ->> 'classification'::text) IS DISTINCT FROM outcome_class)) AND (NOT (((convert_from(response_bytes, 'UTF8'::name))::jsonb -> 'effect'::text) IS DISTINCT FROM effect_envelope))))),
    CONSTRAINT exact_command_receipts_shape CHECK ((((receipt_state = 'executing'::decodex.exact_receipt_state) AND (outcome_class IS NULL) AND (effect_envelope IS NULL) AND (response_bytes IS NULL) AND (completed_at IS NULL)) OR ((receipt_state = 'completed_success'::decodex.exact_receipt_state) AND (outcome_class = 'success'::text) AND (effect_envelope IS NOT NULL) AND (response_bytes IS NOT NULL) AND (completed_at IS NOT NULL)) OR ((receipt_state = 'completed_rejected'::decodex.exact_receipt_state) AND (outcome_class = 'stable_domain_rejection'::text) AND (effect_envelope IS NOT NULL) AND (response_bytes IS NOT NULL) AND (completed_at IS NOT NULL))))
);


