--
-- Name: outbox; Type: TABLE; Schema: decodex; Owner: -
--

CREATE TABLE decodex.outbox (
    id bigint NOT NULL,
    effect_key text NOT NULL,
    aggregate_kind text NOT NULL,
    aggregate_id text NOT NULL,
    aggregate_revision bigint NOT NULL,
    payload jsonb NOT NULL,
    state decodex.outbox_state DEFAULT 'pending'::decodex.outbox_state NOT NULL,
    effect_state decodex.effect_state DEFAULT 'not_started'::decodex.effect_state NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 16 NOT NULL,
    available_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    lease_holder uuid,
    claim_token uuid,
    lease_acquired_at timestamp with time zone,
    lease_expires_at timestamp with time zone,
    receipt jsonb,
    reconciliation jsonb,
    last_failure_code text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    delivered_at timestamp with time zone,
    dead_lettered_at timestamp with time zone,
    retain_until timestamp with time zone,
    CONSTRAINT outbox_aggregate_id_check CHECK (((length(aggregate_id) >= 1) AND (length(aggregate_id) <= 256))),
    CONSTRAINT outbox_aggregate_kind_check CHECK ((aggregate_kind ~ '^[a-z][a-z0-9_]{0,63}$'::text)),
    CONSTRAINT outbox_aggregate_revision_check CHECK ((aggregate_revision > 0)),
    CONSTRAINT outbox_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT outbox_check CHECK (((state = 'dead_letter'::decodex.outbox_state) = (dead_lettered_at IS NOT NULL))),
    CONSTRAINT outbox_claim_shape CHECK ((((state = 'in_flight'::decodex.outbox_state) AND (lease_holder IS NOT NULL) AND (claim_token IS NOT NULL) AND (lease_acquired_at IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR ((state <> 'in_flight'::decodex.outbox_state) AND (lease_holder IS NULL) AND (claim_token IS NULL) AND (lease_acquired_at IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT outbox_delivered_evidence CHECK (((state <> 'delivered'::decodex.outbox_state) OR ((effect_state = 'receipt_recorded'::decodex.effect_state) AND COALESCE(decodex.is_meaningful_evidence(receipt), false) AND COALESCE(decodex.is_meaningful_evidence(reconciliation), false) AND (NOT decodex.has_credential_material(receipt)) AND (NOT decodex.has_credential_material(reconciliation))))),
    CONSTRAINT outbox_delivered_retention CHECK (((state <> 'delivered'::decodex.outbox_state) OR decodex.is_valid_operation_duration((retain_until - delivered_at)))),
    CONSTRAINT outbox_delivered_timestamps CHECK ((((state = 'delivered'::decodex.outbox_state) = (delivered_at IS NOT NULL)) AND ((state = 'delivered'::decodex.outbox_state) = (retain_until IS NOT NULL)))),
    CONSTRAINT outbox_effect_key_check CHECK (((length(effect_key) >= 1) AND (length(effect_key) <= 256))),
    CONSTRAINT outbox_finite_timestamps CHECK ((isfinite(available_at) AND ((lease_acquired_at IS NULL) OR isfinite(lease_acquired_at)) AND ((lease_expires_at IS NULL) OR isfinite(lease_expires_at)) AND isfinite(created_at) AND ((delivered_at IS NULL) OR isfinite(delivered_at)) AND ((dead_lettered_at IS NULL) OR isfinite(dead_lettered_at)) AND ((retain_until IS NULL) OR isfinite(retain_until)))),
    CONSTRAINT outbox_in_flight_lease_duration CHECK (((state <> 'in_flight'::decodex.outbox_state) OR ((lease_acquired_at >= created_at) AND decodex.is_valid_operation_duration((lease_expires_at - lease_acquired_at))))),
    CONSTRAINT outbox_last_failure_code_check CHECK (((last_failure_code IS NULL) OR (last_failure_code ~ '^[a-z][a-z0-9_]{0,127}$'::text))),
    CONSTRAINT outbox_max_attempts_check CHECK ((max_attempts > 0)),
    CONSTRAINT outbox_meaningful_receipt_state CHECK (((effect_state = 'receipt_recorded'::decodex.effect_state) = COALESCE(decodex.is_meaningful_evidence(receipt), false))),
    CONSTRAINT outbox_no_credentials CHECK (((NOT decodex.has_credential_material(effect_key)) AND (NOT decodex.has_credential_material(aggregate_kind)) AND (NOT decodex.has_credential_material(aggregate_id)) AND (NOT decodex.has_credential_material(payload)) AND ((receipt IS NULL) OR (NOT decodex.has_credential_material(receipt))) AND ((reconciliation IS NULL) OR (NOT decodex.has_credential_material(reconciliation))) AND ((last_failure_code IS NULL) OR (NOT decodex.has_credential_material(last_failure_code))))),
    CONSTRAINT outbox_terminal_chronology CHECK ((((delivered_at IS NULL) OR (delivered_at >= created_at)) AND ((dead_lettered_at IS NULL) OR (dead_lettered_at >= created_at))))
);


