    CONSTRAINT waiting_usage_wake_transitions_state_shape CHECK ((((transition_kind = 'registered'::decodex.waiting_usage_wake_transition_kind) AND (state = 'pending'::decodex.waiting_usage_wake_state) AND (claim_id IS NULL) AND (lease_holder IS NULL) AND (lease_fence_id IS NULL) AND (lease_acquired_at IS NULL) AND (lease_expires_at IS NULL) AND (terminal_reason IS NULL) AND (routing_resolution_request_id IS NULL)) OR ((transition_kind = ANY (ARRAY['claimed'::decodex.waiting_usage_wake_transition_kind, 'reclaimed'::decodex.waiting_usage_wake_transition_kind])) AND (state = 'leased'::decodex.waiting_usage_wake_state) AND (claim_id IS NOT NULL) AND (lease_holder IS NOT NULL) AND (lease_fence_id IS NOT NULL) AND (lease_acquired_at IS NOT NULL) AND (lease_expires_at IS NOT NULL) AND (terminal_reason IS NULL) AND (routing_resolution_request_id IS NULL)) OR ((transition_kind = 'fired'::decodex.waiting_usage_wake_transition_kind) AND (state = 'fired'::decodex.waiting_usage_wake_state) AND (claim_id IS NULL) AND (lease_holder IS NULL) AND (lease_fence_id IS NULL) AND (lease_acquired_at IS NULL) AND (lease_expires_at IS NULL) AND (terminal_reason IS NULL) AND (routing_resolution_request_id IS NOT NULL)) OR ((transition_kind = 'cancelled'::decodex.waiting_usage_wake_transition_kind) AND (state = 'cancelled'::decodex.waiting_usage_wake_state) AND (claim_id IS NULL) AND (lease_holder IS NULL) AND (lease_fence_id IS NULL) AND (lease_acquired_at IS NULL) AND (lease_expires_at IS NULL) AND (terminal_reason = 'explicit_cancellation'::decodex.waiting_usage_wake_terminal_reason) AND (routing_resolution_request_id IS NULL)) OR ((transition_kind = 'superseded'::decodex.waiting_usage_wake_transition_kind) AND (state = 'superseded'::decodex.waiting_usage_wake_state) AND (claim_id IS NULL) AND (lease_holder IS NULL) AND (lease_fence_id IS NULL) AND (lease_acquired_at IS NULL) AND (lease_expires_at IS NULL) AND (terminal_reason = ANY (ARRAY['managed_run_stale'::decodex.waiting_usage_wake_terminal_reason, 'policy_revision_stale'::decodex.waiting_usage_wake_terminal_reason, 'ambiguous_decision_lineage'::decodex.waiting_usage_wake_terminal_reason])) AND (routing_resolution_request_id IS NULL))))
);


--
-- Name: work_item_acceptances; Type: TABLE; Schema: decodex; Owner: -
--

CREATE TABLE decodex.work_item_acceptances (
    acceptance_id uuid NOT NULL,
    project_id uuid NOT NULL,
    work_item_id uuid NOT NULL,
    work_item_revision bigint NOT NULL,
    work_item_updated_at timestamp with time zone NOT NULL,
    accepted_by uuid NOT NULL,
    acceptance_criteria text[] NOT NULL,
    validation_criteria text[] NOT NULL,
    criteria_provenance text NOT NULL,
    evidence_summary text NOT NULL,
    evidence_provenance text NOT NULL,
    correlation_id uuid NOT NULL,
    accepted_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT work_item_acceptances_chronology CHECK ((isfinite(work_item_updated_at) AND isfinite(accepted_at) AND ((work_item_updated_at >= '1969-12-31 19:00:00-05'::timestamp with time zone) AND (work_item_updated_at <= '9999-12-31 18:59:59.999999-05'::timestamp with time zone)) AND ((accepted_at >= '1969-12-31 19:00:00-05'::timestamp with time zone) AND (accepted_at <= '9999-12-31 18:59:59.999999-05'::timestamp with time zone)) AND (accepted_at >= work_item_updated_at))),
    CONSTRAINT work_item_acceptances_criteria_bounded CHECK ((decodex.is_work_item_criteria(acceptance_criteria) AND decodex.is_work_item_criteria(validation_criteria))),
    CONSTRAINT work_item_acceptances_ids_canonical CHECK (((((acceptance_id)::text COLLATE "C") ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text) AND (((correlation_id)::text COLLATE "C") ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text))),
    CONSTRAINT work_item_acceptances_provenance_bounded CHECK ((decodex.is_work_item_text(criteria_provenance, 4096) AND decodex.is_work_item_text(evidence_summary, 4096) AND decodex.is_work_item_text(evidence_provenance, 4096))),
    CONSTRAINT work_item_acceptances_work_item_revision_check CHECK ((work_item_revision > 0))
);


