CREATE TABLE decodex.work_item_readiness_blockers (
    project_id uuid NOT NULL,
    work_item_id uuid NOT NULL,
    work_item_revision bigint NOT NULL,
    ordinal integer NOT NULL,
    kind decodex.work_item_blocker_kind NOT NULL,
    subject_id uuid,
    observed_state text,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT work_item_readiness_blockers_finite_time CHECK ((isfinite(recorded_at) AND ((recorded_at >= '1969-12-31 19:00:00-05'::timestamp with time zone) AND (recorded_at <= '9999-12-31 18:59:59.999999-05'::timestamp with time zone)))),
    CONSTRAINT work_item_readiness_blockers_ordinal_check CHECK (((ordinal >= 1) AND (ordinal <= 16384))),
    CONSTRAINT work_item_readiness_blockers_shape CHECK ((((kind = ANY (ARRAY['project_inactive'::decodex.work_item_blocker_kind, 'lead_inactive'::decodex.work_item_blocker_kind, 'dependency_cycle'::decodex.work_item_blocker_kind])) AND (subject_id IS NULL) AND (observed_state IS NOT NULL)) OR ((kind = ANY (ARRAY['program_inactive'::decodex.work_item_blocker_kind, 'objective_inactive'::decodex.work_item_blocker_kind, 'dependency_incomplete'::decodex.work_item_blocker_kind, 'blocker_active'::decodex.work_item_blocker_kind])) AND (subject_id IS NOT NULL) AND (observed_state IS NOT NULL)))),
    CONSTRAINT work_item_readiness_blockers_state_bounded CHECK (((octet_length(observed_state) >= 1) AND (octet_length(observed_state) <= 64) AND ((observed_state COLLATE "C") ~ '^[a-z][a-z0-9_]{0,63}$'::text))),
    CONSTRAINT work_item_readiness_blockers_work_item_revision_check CHECK ((work_item_revision > 0))
);


--
-- Name: work_items; Type: TABLE; Schema: decodex; Owner: -
--

CREATE TABLE decodex.work_items (
    work_item_id uuid NOT NULL,
    project_id uuid NOT NULL,
    lead_agent_id uuid NOT NULL,
    program_id uuid,
    title text NOT NULL,
    description text NOT NULL,
    priority decodex.work_item_priority NOT NULL,
    acceptance_criteria text[] NOT NULL,
    validation_criteria text[] NOT NULL,
    state decodex.work_item_state DEFAULT 'inbox'::decodex.work_item_state NOT NULL,
    revision bigint DEFAULT 1 NOT NULL,
    last_changed_by uuid NOT NULL,
    last_correlation_id uuid NOT NULL,
    last_provenance text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT work_items_criteria_bounded CHECK ((decodex.is_work_item_criteria(acceptance_criteria) AND decodex.is_work_item_criteria(validation_criteria))),
    CONSTRAINT work_items_finite_times CHECK ((isfinite(created_at) AND isfinite(updated_at) AND (created_at >= '1969-12-31 19:00:00-05'::timestamp with time zone) AND (updated_at <= '9999-12-31 18:59:59.999999-05'::timestamp with time zone) AND (updated_at >= created_at))),
    CONSTRAINT work_items_ids_canonical CHECK (((((work_item_id)::text COLLATE "C") ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text) AND (((last_correlation_id)::text COLLATE "C") ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text))),
    CONSTRAINT work_items_revision_check CHECK ((revision > 0)),
    CONSTRAINT work_items_text_bounded CHECK ((decodex.is_work_item_text(title, 256) AND decodex.is_work_item_text(description, 4096) AND decodex.is_work_item_text(last_provenance, 4096)))
);


