-- Exact initial product-state singleton owned by the latest schema.
INSERT INTO decodex.account_routing_control(singleton) VALUES (true);

-- Exact schema-owner defaults are identity-independent because bootstrap runs as that owner.
ALTER DEFAULT PRIVILEGES REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
ALTER DEFAULT PRIVILEGES REVOKE USAGE ON TYPES FROM PUBLIC;

DO $decodex_schema_owner_acl$
BEGIN
	EXECUTE pg_catalog.format(
		'GRANT CONNECT, CREATE ON DATABASE %I TO %I',
		pg_catalog.current_database(),current_user
	);
	EXECUTE pg_catalog.format(
		'GRANT USAGE, CREATE ON SCHEMA public TO %I',current_user
	);
END
$decodex_schema_owner_acl$;

DO $decodex_runtime_acl$
DECLARE runtime_role pg_catalog.text;
BEGIN
	runtime_role:=pg_catalog.current_setting('decodex.bootstrap_runtime_role',false);
	IF runtime_role IS NULL OR runtime_role='' OR
		pg_catalog.octet_length(runtime_role)>
			pg_catalog.current_setting('max_identifier_length')::pg_catalog.int4 OR
		runtime_role=current_user::pg_catalog.text OR NOT EXISTS (
		SELECT 1 FROM pg_catalog.pg_roles AS role
		WHERE role.rolname::pg_catalog.text=runtime_role
			AND role.rolcanlogin AND NOT role.rolinherit AND NOT role.rolsuper
			AND NOT role.rolcreatedb AND NOT role.rolcreaterole
			AND NOT role.rolreplication AND NOT role.rolbypassrls
			AND role.rolconnlimit=-1
			AND role.rolvaliduntil='infinity'::pg_catalog.timestamptz
	) THEN
		RAISE EXCEPTION 'configured runtime role is absent or unsafe' USING ERRCODE='42501';
	END IF;
	EXECUTE pg_catalog.format(
		'REVOKE ALL PRIVILEGES ON DATABASE %I FROM %I',
		pg_catalog.current_database(),runtime_role
	);
	EXECUTE pg_catalog.format(
		'REVOKE ALL PRIVILEGES ON SCHEMA public,decodex FROM %I',runtime_role
	);
	EXECUTE pg_catalog.format(
		'REVOKE ALL PRIVILEGES ON ALL TABLES IN SCHEMA decodex FROM %I',runtime_role
	);
	EXECUTE pg_catalog.format(
		'REVOKE ALL PRIVILEGES ON ALL SEQUENCES IN SCHEMA decodex FROM %I',runtime_role
	);
	EXECUTE pg_catalog.format(
		'REVOKE ALL PRIVILEGES ON ALL FUNCTIONS IN SCHEMA decodex FROM %I',runtime_role
	);
	EXECUTE pg_catalog.format(
		'REVOKE CREATE ON DATABASE %I FROM PUBLIC',pg_catalog.current_database()
	);
	EXECUTE pg_catalog.format('GRANT CONNECT ON DATABASE %1$I TO %2$I',pg_catalog.current_database(),runtime_role);
	EXECUTE pg_catalog.format('GRANT EXECUTE ON FUNCTION decodex.accept_policy_revision(p_policy_id decodex.canonical_uuid_v4_text, p_project_id decodex.canonical_uuid_v4_text, p_revision bigint, p_provenance text, p_snapshot jsonb, p_accepted_by decodex.canonical_uuid_v4_text, p_supersedes_revision bigint) TO %I',runtime_role);
